#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADS1115 I2C address when ADDR pin is tied to GND */
#define ADS1115_ADDR 0x48

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/*
 * Config word (16-bit, big-endian on the bus):
 *   Bit 15    OS        = 1  (begin single conversion)
 *   Bits 14:12 MUX[2:0] = 100 (AIN0 single-ended)
 *   Bits 11:9  PGA[2:0]  = 001 (±4.096 V)
 *   Bit  8     MODE      = 1  (single-shot)
 *   Bits 7:5   DR[2:0]   = 100 (128 SPS)
 *   Bit  2     COMP_MODE = 0
 *   Bit  1     COMP_POL  = 0
 *   Bit  0     COMP_LAT  = 0
 * => 0x8483
 */
#define ADS1115_CONFIG_BASE 0x8483

/* MLX91219 parameters */
#define MLX91219_SENSITIVITY_V_PER_A 0.040f   /* 40 mV/A */
#define MLX91219_ZERO_CURRENT_V 0.0f        /* mid-supply zero */
#define MLX91219_SUPPLY_V 3.3f

#define I2C_BUS 1
#define SAMPLE_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a 16-bit value to an ADS1115 register (big-endian on the bus).
 * Returns 0 on success, -1 on failure.
 */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteI2CBlockData(handle, reg, buf + 1, 2) < 0) {
        fprintf(stderr, "Error writing register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from an ADS1115 register (big-endian on the bus).
 * Returns 0 on success and stores the value in *out, -1 on failure.
 */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading register 0x%02X\n", reg);
        return -1;
    }
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Trigger a single-shot conversion on AIN0 and return the raw ADC count.
 * Returns 0 on success and stores the count in *raw_out, -1 on failure.
 */
static int ads1115_read_ain0(int handle, int16_t *raw_out)
{
    uint16_t config = ADS1115_CONFIG_BASE | 0x8000;  /* assert OS bit */
    uint16_t conv;

    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, config) != 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    gpioDelay(10000);

    if (ads1115_read_reg(handle, ADS1115_REG_CONVERSION, &conv) != 0)
        return -1;

    *raw_out = (int16_t)conv;
    return 0;
}

static float calculate_current(int16_t raw)
{
    float voltage = (raw * MLX91219_SENSITIVITY_V_PER_A) - MLX91219_ZERO_CURRENT_V;
    return voltage / MLX91219_SENSITIVITY_V_PER_A;
}

int main(void)
{
    int16_t raw;
    float current;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX91219 current sensor via ADS1115 (I2C addr 0x%02X)\n", ADS1115_ADDR);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        if (ads1115_read_ain0(g_i2c_handle, &raw) != 0) {
            fprintf(stderr, "ADS1115 read error — sensor absent or bus fault\n");
            break;
        }

        current = calculate_current(raw);
        printf("Current: %.3f A\n", current);
        fflush(stdout);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

