    if (fprintf(log_file, "%s,%d,%.2f\n", timestamp, flame_detected, temperature) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_D0, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", FLAME_SENSOR_D0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MCP3008_CS, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MCP3008_CS);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(MCP3008_CS, 1);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "SPI read error; skipping log entry\n");
        } else {
            int flame_detected = (adc_value > 500) ? 1 : 0;
            float temperature = approximate_temperature(adc_value);

            if (log_data(flame_detected, temperature) < 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

