#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define BUZZER_GPIO 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_CONV_REG 0x00
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_MUX_AIN0_GND 0x4000
#define ADS1115_PGA_4_096V 0x0200
#define ADS1115_MODE_SINGLE 0x0100
#define ADS1115_DR_128SPS 0x0080
#define ADS1115_CONFIG_BASE (ADS1115_OS_SINGLE | ADS1115_MUX_AIN0_GND | ADS1115_PGA_4_096V | ADS1115_MODE_SINGLE | ADS1115_DR_128SPS)
#define DEBOUNCE_MS 50
#define POLL_MS 100
#define BUZZER_ON_MS 2000
#define LOG_FILE "fire_log.txt"

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t flame_event_pending = 0;
static volatile uint32_t last_flame_tick = 0;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void flame_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)user;
    if (tick - last_flame_tick >= DEBOUNCE_MS * 1000) {
        flame_event_pending = 1;
        last_flame_tick = tick;
    }
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", FLAME_SENSOR_GPIO);
        return -1;
    }
    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d\n", FLAME_SENSOR_GPIO);
        return -1;
    }
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", BUZZER_GPIO);
        return -1;
    }
    if (gpioWrite(BUZZER_GPIO, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise buzzer state on GPIO%d\n", BUZZER_GPIO);
        return -1;
    }
    return 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X (pigpio error %d)\n",
                I2C_BUS, ADS1115_ADDR, i2c_handle);
        return -1;
    }
    char cfg[3];
    cfg[0] = ADS1115_CONFIG_REG;
    cfg[1] = (ADS1115_CONFIG_BASE >> 8) & 0xFF;
    cfg[2] = ADS1115_CONFIG_BASE & 0xFF;
    if (i2cWriteDevice(i2c_handle, cfg, 3) < 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature) {
    char reg = ADS1115_CONV_REG;
    if (i2cWriteDevice(i2c_handle, &reg, 1) < 0) {
        fprintf(stderr, "Error: failed to select ADS1115 conversion register\n");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error: failed to read ADS1115 conversion result\n");
        return -1;
    }
    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    float voltage = (raw * 4.096) / 32768.0;
    *temperature = (voltage * 100.0) - 20.0;
    return 0;
}

static void log_event(const char *msg) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, NULL, NULL);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    if (gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, flame_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR for flame sensor on GPIO%d\n", FLAME_SENSOR_GPIO);
        cleanup();
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");
    log_event("System started");

    while (running) {
        int flame = gpioRead(FLAME_SENSOR_GPIO);
        if (flame < 0) {
            fprintf(stderr, "Warning: failed to read flame sensor on GPIO%d\n", FLAME_SENSOR_GPIO);
            gpioDelay(POLL_MS * 1000);
            continue;
        }

        if (flame == 0) {
            if (flame_event_pending) {
                flame_event_pending = 0;
                log_event("Flame detected!");
            }
        } else {
            float temp;
            if (read_temperature(&temp) < 0) {
                fprintf(stderr, "Warning: failed to read temperature\n");
            } else {
                if (temp > 60.0) {
                    log_event("Temperature above 60C");
                    gpioWrite(BUZZER_GPIO, 1);
                    gpioDelay(BUZZER_ON_MS * 1000);
                    gpioWrite(BUZZER_GPIO, 0);
                } else {
                    log_event("Temperature normal");
                }
            }
        }

        gpioDelay(POLL_MS * 1000);
    }

    printf("\nShutting down...\n");
    log_event("System stopped");
    cleanup();
    return 0;
}

