#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define DEFAULT_THRESHOLD 5.0
#define DEFAULT_SENSITIVITY 0.100
#define DEFAULT_LOG_FILE "current_log.txt"
#define DEFAULT_GPIO_CHIP "gpiochip4"
#define DEFAULT_GPIO_LINE 18
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_BITS_PER_WORD 8
#define SPI_MODE 0
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_fan_line = NULL;
static char *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    if (value < 0 || value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", value);
        return -1;
    }
    return value;
}

static float voltage_to_current(int adc_value, float sensitivity) {
    return (float)adc_value * sensitivity;
}

static int log_data(float current, float voltage, float threshold, float sensitivity) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    FILE *fp = fopen(g_log_file, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", g_log_file, strerror(errno));
        return -1;
    }

    fprintf(fp, "%s, Current: %.3f A, Voltage: %.3f V, Threshold: %.3f A, Sensitivity: %.3f V/A\n",
            timestamp, current, voltage, threshold, sensitivity);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int control_fan(int state) {
    if (g_fan_line == NULL) {
        fprintf(stderr, "GPIO line not initialized\n");
        return -1;
    }

    if (gpiod_line_set_value(g_fan_line, state) < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (g_fan_line != NULL) {
        gpiod_line_set_value(g_fan_line, 0);
        gpiod_line_release(g_fan_line);
        g_fan_line = NULL;
    }
    if (g_chip != NULL) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_log_file != NULL) {
        free(g_log_file);
        g_log_file = NULL;
    }
}

int main(int argc, char *argv[]) {
    float threshold = DEFAULT_THRESHOLD;
    float sensitivity = DEFAULT_SENSITIVITY;
    char *log_file = strdup(DEFAULT_LOG_FILE);
    if (log_file == NULL) {
        fprintf(stderr, "Error allocating memory for log file\n");
        return EXIT_FAILURE;
    }

    int opt;
    while ((opt = getopt(argc, argv, "t:s:l:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 's':
                sensitivity = atof(optarg);
                break;
            case 'l':
                strncpy(log_file, optarg, sizeof(log_file) - 1);
                log_file[sizeof(log_file) - 1] = '\0';
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s sensitivity] [-l log_file]\n", argv[0]);
                free(log_file);
                return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        free(log_file);
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        free(log_file);
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        free(log_file);
        return EXIT_FAILURE;
    }

    g_chip = gpiod_chip_open_by_name(DEFAULT_GPIO_CHIP);
    if (g_chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", DEFAULT_GPIO_CHIP, strerror(errno));
        cleanup();
        free(log_file);
        return EXIT_FAILURE;
    }

