#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x28
#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define CO_OFFSET 1000.0
#define CO_SCALE 0.001
#define CO_MIN_PPM 10.0
#define CO_MAX_PPM 1000.0

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_co_raw(int16_t *raw_value);
float calculate_co_ppm(int16_t raw_value);
int log_co_ppm(float co_ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d). Sensor may be absent or bus error.\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw 16-bit resistance value from the CO element (simulated via external ADC or internal conversion)
int read_co_raw(int16_t *raw_value) {
    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error: I2C read failed (read %d bytes). Sensor may be disconnected.\n", bytes_read);
        return -1;
    }
    *raw_value = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Convert raw resistance value to CO concentration in PPM using a logarithmic calibration curve
float calculate_co_ppm(int16_t raw_value) {
    float resistance = (float)raw_value;
    float log_resistance = log10f(resistance + 1.0f); // Avoid log(0)
    float ppm = CO_OFFSET + (CO_SCALE * (log_resistance - log10f(CO_MIN_PPM + 1.0f)));
    if (ppm < CO_MIN_PPM) ppm = CO_MIN_PPM;
    if (ppm > CO_MAX_PPM) ppm = CO_MAX_PPM;
    return ppm;
}

// Log CO concentration to file with timestamp
int log_co_ppm(float co_ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f PPM\n", timestamp, co_ppm);
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handlers
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return EXIT_FAILURE;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("CO sensor logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int16_t raw_value;
        if (read_co_raw(&raw_value) == 0) {
            float co_ppm = calculate_co_ppm(raw_value);
            if (log_co_ppm(co_ppm) != 0) {
                fprintf(stderr, "Warning: Failed to log CO concentration.\n");
            }
        } else {
            fprintf(stderr, "Warning: Failed to read CO sensor data.\n");
        }

        // Sleep for the sample interval, checking terminate flag every second
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && !terminate; i++) {
            sleep(1);
        }
    }

    // Cleanup
    cleanup();
    printf("CO sensor logging stopped.\n");
    return EXIT_SUCCESS;
}

