void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read sensor data from the MICS-4514
int read_sensor_data(unsigned short *ox, unsigned short *red) {
    char buffer[4];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int bytes_read = i2cReadDevice(i2c_handle, buffer, 4);
        if (bytes_read == 4) {
            *ox = (buffer[0] << 8) | buffer[1];
            *red = (buffer[2] << 8) | buffer[3];
            return 0;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d/%d): %s\n", retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            gpioDelay(100000); // 100ms delay before retry
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    return -1;
}

