    if (co_ppm > CO_THRESHOLD) {
        FILE *fp = fopen(ALERT_LOG_FILE, "a");
        if (fp == NULL) {
            fprintf(stderr, "Error opening %s: %s\n", ALERT_LOG_FILE, strerror(errno));
            return;
        }

        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char s[64];
        strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

        fprintf(fp, "%s, ALERT: CO level exceeded threshold (%.2f PPM > %.2f PPM)\n", s, co_ppm, CO_THRESHOLD);
        fclose(fp);
    }
}

