void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    unsigned short ox_value, red_value;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&ox_value, &red_value) == 0) {
            float co_ppm = calculate_co_ppm(ox_value);
            log_co_data(co_ppm);
            check_co_threshold(co_ppm);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds.\n", READ_INTERVAL);
        }

        gpioDelay(READ_INTERVAL * 1000000); // Delay for 5 seconds
    }

    // Cleanup
    cleanup();
    return 0;
}

