#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define MIC1_ADDR 0x48
#define MIC2_ADDR 0x49
#define LOG_FILE "audio_log.txt"
#define SAMPLE_INTERVAL_US 100000
#define SENSITIVITY_DBV_PA -38.0
#define REF_PRESSURE_PA 20e-6
#define ERROR_VALUE -999.0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mic_raw(int handle, int16_t *out) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, 0x00, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read error on handle %d: %s\n", handle, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    return 0;
}

static double raw_to_db(int16_t raw) {
    double pressure_pa = (double)raw * (REF_PRESSURE_PA / 32768.0);
    return SENSITIVITY_DBV_PA + 20.0 * log10(pressure_pa);
}

static int log_data(double avg_db) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, avg_db);
    } else {
        fprintf(fp, "timestamp_error, %.2f\n", avg_db);
    }
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int h1 = i2cOpen(I2C_BUS, MIC1_ADDR, 0);
    if (h1 < 0) {
        fprintf(stderr, "Failed to open I2C for mic1 (0x%02X): %s\n", MIC1_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    int h2 = i2cOpen(I2C_BUS, MIC2_ADDR, 0);
    if (h2 < 0) {
        fprintf(stderr, "Failed to open I2C for mic2 (0x%02X): %s\n", MIC2_ADDR, strerror(errno));
        i2cClose(h1);
        gpioTerminate();
        return 1;
    }

    printf("Acoustic Leak Detection System started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t raw1 = 0, raw2 = 0;
        int ok1 = read_mic_raw(h1, &raw1);
        int ok2 = read_mic_raw(h2, &raw2);

        double db1 = ok1 ? raw_to_db(raw1) : ERROR_VALUE;
        double db2 = ok2 ? raw_to_db(raw2) : ERROR_VALUE;
        double avg_db = (db1 + db2) / 2.0;

        if (log_data(avg_db) != 0) {
            fprintf(stderr, "Logging failed\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    i2cClose(h1);
    i2cClose(h2);
    gpioTerminate();
    printf("Shutdown complete.\n");
    return 0;
}

