#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define LED_GPIO 17
#define OVERCURRENT_THRESHOLD 50.0
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 10
#define SAMPLE_INTERVAL_US (1000000 / SAMPLE_RATE_HZ)

// ADS1115 Config: Single-shot, AIN0, PGA=4.096V, 128 SPS, Continuous mode
#define ADS1115_CONFIG_BASE 0x8000 // Single-shot bit
#define ADS1115_CONFIG_MUX_A0 0x4000 // AIN0 vs GND
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_CONT 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADS1115_CONFIG_OS_BEGIN 0x8000
#define ADS1115_CONFIG_VALUE (ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_A0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_CONT | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_CQUE_NONE)

// MLX91204 Transfer Function (Ratiometric, 5V supply, 0-100A)
#define V_SUPPLY 5.0
#define V_MIN 0.5
#define V_MAX 4.5
#define I_MIN 0.0
#define I_MAX 100.0

// Circular Buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Global Variables
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static CircularBuffer current_buffer;

// Function Prototypes
int init_pigpio(void);
int init_i2c(void);
int16_t read_ads1115(void);
float voltage_to_current(float voltage);
void add_to_buffer(CircularBuffer *cb, float value);
float get_average(CircularBuffer *cb);
void control_led(int state);
void signal_handler(int signal);
void cleanup(void);

// Initialize Circular Buffer
void init_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Initialize pigpio library
int init_pigpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication with ADS1115
int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw 16-bit ADC value from ADS1115
int16_t read_ads1115(void) {
    char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_VALUE >> 8) & 0xFF;
    config[2] = ADS1115_CONFIG_VALUE & 0xFF;

    if (i2cWriteDevice(i2c_handle, config, 3) < 0) {
        fprintf(stderr, "Error: Failed to write ADS1115 config\n");
        return -1;
    }

    // Wait for conversion (128 SPS -> ~7.8ms, use 10ms for safety)
    gpioDelay(10000);

    char reg[1] = {ADS1115_REG_CONVERSION};
    if (i2cWriteDevice(i2c_handle, reg, 1) < 0) {
        fprintf(stderr, "Error: Failed to set conversion register pointer\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read ADS1115 conversion\n");
        return -1;
    }

    return (int16_t)((data[0] << 8) | data[1]);
}

// Convert voltage to current using MLX91204 transfer function
float voltage_to_current(float voltage) {
    if (voltage < V_MIN) voltage = V_MIN;
    if (voltage > V_MAX) voltage = V_MAX;
    return (voltage - V_MIN) / (V_MAX - V_MIN) * (I_MAX - I_MIN) + I_MIN;
}

// Add a value to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

// Calculate the average of the values in the circular buffer
float get_average(CircularBuffer *cb) {
    if (cb->count == 0) return 0.0;
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Control the LED (1 = ON, 0 = OFF)
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Cleanup resources
void cleanup(void) {
    control_led(0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    // Initialize pigpio
    if (init_pigpio() != 0) {
        return EXIT_FAILURE;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Initialize circular buffer
    init_buffer(&current_buffer);

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Overcurrent Protection System running. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int16_t raw = read_ads1115();
        if (raw == -1) {
            fprintf(stderr, "Error: Failed to read ADC value. Retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float voltage = (raw * V_SUPPLY) / 32768.0;
        float current = voltage_to_current(voltage);

        add_to_buffer(&current_buffer, current);
        float avg_current = get_average(&current_buffer);

        printf("Current: %.2f A, Average Current: %.2f A\n", current, avg_current);

        if (avg_current > OVERCURRENT_THRESHOLD) {
            control_led(1);
            printf("WARNING: Overcurrent detected! Average current: %.2f A\n", avg_current);
        } else {
            control_led(0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    cleanup();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

