            printf("WARNING: Overcurrent detected! Average current: %.2f A\n", avg_current);
        } else {
            control_led(0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    cleanup();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

