#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TCS34725_ADDR        0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE      0x00
#define TCS34725_ATIME       0x01
#define TCS34725_CONTROL     0x0F
#define TCS34725_ID          0x12
#define TCS34725_CDATA       0x14
#define TCS34725_RDATA       0x16
#define TCS34725_GDATA       0x18
#define TCS34725_BDATA       0x1A
#define TCS34725_ID_VALUE    0x44
#define TCS34725_POWER_ON    0x01
#define TCS34725_AEN         0x02
#define TCS34725_TIMEOUT_MS  3000
#define LOG_FILE             "color_log.csv"
#define MAX_CONSECUTIVE_ERRORS 3

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, TCS34725_COMMAND_BIT | reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
        return -1;
    }
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, TCS34725_COMMAND_BIT | reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *out = (uint16_t)rc;
    return 0;
}

static int tcs34725_init(int handle)
{
    uint16_t id = 0;
    if (i2c_read_word(handle, TCS34725_ID, &id) != 0)
        return -1;

    if ((id & 0x0F) != TCS34725_ID_VALUE) {
        fprintf(stderr, "TCS34725 ID mismatch: got 0x%04X, expected 0x%04X\n", id, TCS34725_ID_VALUE);
        return -1;
    }

    if (i2c_write_byte(handle, TCS34725_ATIME, 0xFF) != 0)
        return -1;

    if (i2c_write_byte(handle, TCS34725_CONTROL, 0x01) != 0)
        return -1;

    if (i2c_write_byte(handle, TCS34725_ENABLE, TCS34725_POWER_ON | TCS34725_AEN) != 0)
        return -1;

    return 0;
}

static int tcs34725_read_color(int handle, uint16_t *clear, uint16_t *red,
                               uint16_t *green, uint16_t *blue)
{
    if (i2c_read_word(handle, TCS34725_CDATA, clear) != 0) return -1;
    if (i2c_read_word(handle, TCS34725_RDATA, red)   != 0) return -1;
    if (i2c_read_word(handle, TCS34725_GDATA, green) != 0) return -1;
    if (i2c_read_word(handle, TCS34725_BDATA, blue)  != 0) return -1;
    return 0;
}

static int log_color_data(FILE *fp, uint16_t clear, uint16_t red,
                          uint16_t green, uint16_t blue)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u,%u,%u,%u\n", ts, clear, red, green, blue) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(1, TCS34725_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (tcs34725_init(g_i2c_handle) != 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Write header if file is empty */
    if (fseek(g_log_file, 0, SEEK_END) == 0) {
        long sz = ftell(g_log_file);
        if (sz == 0) {
            fprintf(g_log_file, "Timestamp,Clear,Red,Green,Blue\n");
            fflush(g_log_file);
        }
    } else {
        perror("fseek");
        fclose(g_log_file);
        g_log_file = NULL;
    }

    int consecutive_errors = 0;

    while (g_running) {
        uint16_t clear, red, green, blue;

        if (tcs34725_read_color(g_i2c_handle, &clear, &red, &green, &blue) == 0) {
            consecutive_errors = 0;
            if (log_color_data(g_log_file, clear, red, green, blue) != 0) {
                fprintf(stderr, "Failed to log color data\n");
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Failed to read color data (consecutive errors: %d)\n",
                    consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Max consecutive errors reached, exiting.\n");
                break;
            }
        }

        /* Sleep 1 second; use gpioDelay so signals are handled promptly */
        gpioDelay(1000000);
    }

    /* Clean shutdown */
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    return 0;
}

