#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define GPIO_CHIP "gpiochip0"
#define MOTOR_PIN 17
#define CURRENT_THRESHOLD 10.0
#define SENSITIVITY 0.1
#define OFFSET 0.05
#define LOG_FILE "current_log.csv"
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return -1;
    }
    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("set SPI mode");
        close(spi_fd); spi_fd = -1; return -1;
    }
    int bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("set bits per word");
        close(spi_fd); spi_fd = -1; return -1;
    }
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("set SPI speed");
        close(spi_fd); spi_fd = -1; return -1;
    }
    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return -1;
    }
    motor_line = gpiod_chip_get_line(chip, MOTOR_PIN);
    if (!motor_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip); chip = NULL; return -1;
    }
    if (gpiod_line_request_output(motor_line, "motor_ctrl", 1) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip); chip = NULL; motor_line = NULL; return -1;
    }
    return 0;
}

static int read_mcp3008(int channel) {
    if (spi_fd < 0 || !motor_line) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d): %s\n", attempt + 1, strerror(errno));
        usleep(10000);
    }
    return -1;
}

static float adc_to_current(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * 3.3;
    return (voltage - OFFSET) / SENSITIVITY;
}

static void log_current(float current) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, current);
    fflush(log_file);
}

static void cleanup(void) {
    if (motor_line) {
        gpiod_line_set_value(motor_line, 0);
        gpiod_line_release(motor_line);
        motor_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_spi() < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return 1;
    }
    if (init_gpio() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        close(spi_fd); spi_fd = -1;
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log file");
        cleanup();
        return 1;
    }
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,current_in_Amperes\n");
        fflush(log_file);
    }

    printf("Monitoring current... Press Ctrl+C to exit.\n");

    while (running) {
        int adc = read_mcp3008(MCP3008_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "Failed to read ADC after %d retries\n", MAX_RETRIES);
            sleep(1);
            continue;
        }
        float current = adc_to_current(adc);
        log_current(current);
        printf("Current: %.2f A\n", current);

        if (current > CURRENT_THRESHOLD) {
            printf("Overcurrent detected! Shutting down motor.\n");
            gpiod_line_set_value(motor_line, 0);
            sleep(1);
            gpiod_line_set_value(motor_line, 1);
            printf("Motor re-enabled.\n");
        }
        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

