#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>

/* Configuration */
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define WARNING_LED_GPIO 17
#define PRESSURE_THRESHOLD 105.0f
#define SAMPLE_INTERVAL_US 1000000
#define MAX_RETRIES 3

/* ADS1115 Registers */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

/* ADS1115 Config: AIN0 single-ended, AIN1 single-ended, gain 2/3, 128 SPS, continuous */
#define ADS1115_CONFIG_BASE 0x8000  /* OS bit: start conversion */
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_MUX_AIN1 0x5000
#define ADS1115_CONFIG_PGA_2_3V 0x0200
#define ADS1115_CONFIG_MODE_CONT 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADS1115_CONFIG_DEFAULT (ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 | ADS1115_CONFIG_MUX_AIN1 | ADS1115_CONFIG_PGA_2_3V | ADS1115_CONFIG_MODE_CONT | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE)

/* MLX90834 Transfer Function (Linear approximation) */
#define V_MIN 0.0f
#define V_MAX 5.0f
#define P_MIN 0.0f
#define P_MAX 400.0f

/* Temperature NTC Approximation (simplified linear model) */
#define T_MIN 0.0f
#define T_MAX 100.0f
#define V_T_MIN 1.0f
#define V_T_MAX 2.0f

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

/* Function prototypes */
static int ads1115_init(void);
static int ads1115_read_adc(uint16_t *pressure_raw, uint16_t *temperature_raw);
static float adc_to_voltage(uint16_t raw);
static float voltage_to_pressure(float voltage);
static float voltage_to_temperature(float voltage);
static void control_led(float pressure);
static void signal_handler(int signal);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Initialize ADS1115 ADC */
static int ads1115_init(void) {
    uint16_t config = ADS1115_CONFIG_DEFAULT;
    char buf[3];

    if (i2cWriteWordData(i2c_handle, ADS1115_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Error: Failed to write ADS1115 config register.\n");
        return -1;
    }

    /* Wait for first conversion to complete (~8ms at 128 SPS) */
    gpioDelay(10000);

    /* Verify config was accepted */
    if (i2cWriteWordData(i2c_handle, ADS1115_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Error: Failed to verify ADS1115 config.\n");
        return -1;
    }

    return 0;
}

/* Read ADC values from ADS1115 with retry logic */
static int ads1115_read_adc(uint16_t *pressure_raw, uint16_t *temperature_raw) {
    char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        /* Read conversion register (2 bytes) */
        if (i2cReadI2CBlockData(i2c_handle, ADS1115_REG_CONVERSION, buf, 2) == 2) {
            *pressure_raw = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint8_t)buf[1];
            *temperature_raw = ((uint16_t)(buf[1] & 0xFF) << 8) | (uint8_t)buf[0];
            return 0;
        }

        fprintf(stderr, "Warning: I2C read failed (attempt %d/%d).\n", retries + 1, MAX_RETRIES);
        retries++;
        gpioDelay(10000); /* 10ms delay before retry */
    }

    fprintf(stderr, "Error: Failed to read ADC values after %d retries.\n", MAX_RETRIES);
    return -1;
}

/* Convert raw ADC value to voltage */
static float adc_to_voltage(uint16_t raw) {
    /* ADS1115 16-bit signed, gain 2/3 (4.096V full scale) */
    return (raw * 4.096f) / 32768.0f;
}

/* Convert voltage to pressure (MLX90834 linear transfer function) */
static float voltage_to_pressure(float voltage) {
    return P_MIN + (voltage - V_MIN) * (P_MAX - P_MIN) / (V_MAX - V_MIN);
}

/* Convert voltage to temperature (simplified NTC linear model) */
static float voltage_to_temperature(float voltage) {
    return T_MIN + (voltage - V_T_MIN) * (T_MAX - T_MIN) / (V_T_MAX - V_T_MIN);
}

/* Control warning LED based on pressure threshold */
static void control_led(float pressure) {
    if (pressure > PRESSURE_THRESHOLD) {
        gpioWrite(WARNING_LED_GPIO, 1);
    } else {
        gpioWrite(WARNING_LED_GPIO, 0);
    }
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to ADS1115 */
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus to ADS1115 (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADS1115 */
    if (ads1115_init() < 0) {
        fprintf(stderr, "Error: ADS1115 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(WARNING_LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", WARNING_LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(WARNING_LED_GPIO, 0);

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90834 Pressure Sensor Interface (via ADS1115 ADC)\n");
    printf("Sampling every 1 second. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        uint16_t pressure_raw = 0, temperature_raw = 0;

        if (ads1115_read_adc(&pressure_raw, &temperature_raw) == 0) {
            float voltage = adc_to_voltage(pressure_raw);
            float pressure = voltage_to_pressure(voltage);
            float temperature = voltage_to_temperature(voltage);

            printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);
            control_led(pressure);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
            gpioWrite(WARNING_LED_GPIO, 0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioWrite(WARNING_LED_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

