#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define MCP3008_CHANNEL 0
#define OVERCURRENT_THRESHOLD 10.0
#define SHUTDOWN_GPIO 27
#define LOG_FILE "current_log.txt"
#define SAMPLE_INTERVAL_US 100000
#define VREF 3.3
#define ADC_MAX 1024.0
#define SENSOR_SENSITIVITY 0.066
#define SENSOR_ZERO_CURRENT_V 1.65

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_current(int adc_value) {
    float voltage = (adc_value / ADC_MAX) * VREF;
    float current = (voltage - SENSOR_ZERO_CURRENT_V) / SENSOR_SENSITIVITY;
    return current;
}

static int log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime failed\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Current: %.2f A\n", timestamp, current) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Failed to flush log file\n");
        return -1;
    }
    return 0;
}

static void shutdown_motor(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (gpioInitialise() >= 0) {
        gpioWrite(SHUTDOWN_GPIO, 0);
        gpioTerminate();
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d)\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SHUTDOWN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", SHUTDOWN_GPIO);
        shutdown_motor();
        return EXIT_FAILURE;
    }
    gpioWrite(SHUTDOWN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers\n");
        shutdown_motor();
        return EXIT_FAILURE;
    }

    printf("Motor current monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float current = adc_to_current(adc_value);

        if (log_current(current) != 0) {
            fprintf(stderr, "Failed to log current\n");
        }

        if (current > OVERCURRENT_THRESHOLD) {
            printf("OVERCURRENT: %.2f A\n", current);
            if (fprintf(log_file, "OVERCURRENT: %.2f A\n", current) < 0) {
                fprintf(stderr, "Failed to log OVERCURRENT event\n");
            }
            if (fflush(log_file) != 0) {
                fprintf(stderr, "Failed to flush log file\n");
            }

            if (gpioWrite(SHUTDOWN_GPIO, 1) != 0) {
                fprintf(stderr, "Failed to assert shutdown GPIO\n");
            }
            break;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    shutdown_motor();
    return EXIT_SUCCESS;
}

