#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_BEGIN 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128_SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define PRESSURE_OFFSET 0.5
#define PRESSURE_SENSITIVITY 0.1
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 1000000

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int configure_ads1115();
int read_pressure(float *pressure);
void log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", ADS1115_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure ADS1115 for single-shot conversion on AIN0
int configure_ads1115() {
    // Write configuration: OS=begin, MUX=AIN0/GND, PGA=4.096V, MODE=single, DR=128 SPS, CQUE=none
    uint16_t config = ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0_GND |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128_SPS | ADS1115_CONFIG_CQUE_NONE;

    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, config_buf, 3) < 0) {
        fprintf(stderr, "Failed to write ADS1115 configuration\n");
        return -1;
    }

    return 0;
}

// Read pressure from ADS1115 and convert to kPa
int read_pressure(float *pressure) {
    char reg_buf[1] = {ADS1115_REG_CONVERSION};
    char data_buf[2];

    // Trigger a single-shot conversion
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) < 0) {
        fprintf(stderr, "Failed to trigger conversion\n");
        return -1;
    }

    // Wait for conversion to complete (approx 8ms for 128 SPS)
    gpioDelay(10000);

    // Read conversion result
    if (i2cReadI2CBlockData(i2c_handle, ADS1115_REG_CONVERSION, data_buf, 2) < 0) {
        fprintf(stderr, "Failed to read conversion data\n");
        return -1;
    }

    // Combine bytes (MSB first)
    int16_t raw_value = (data_buf[0] << 8) | data_buf[1];

    // Convert to voltage (PGA = 4.096V, 16-bit signed)
    float voltage = (raw_value * 4.096) / 32768.0;

    // Convert to pressure (kPa)
    *pressure = (voltage - PRESSURE_OFFSET) / PRESSURE_SENSITIVITY;

    return 0;
}

// Log pressure data to file
void log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

    fprintf(fp, "%s,%.2f\n", timestamp, pressure);
    fclose(fp);
}

int main() {
    // Register signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        cleanup();
        return 1;
    }

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float pressure;
        if (read_pressure(&pressure) == 0) {
            // Validate pressure range (0-100 kPa)
            if (pressure >= 0.0 && pressure <= 100.0) {
                log_pressure(pressure);
                printf("Pressure: %.2f kPa\n", pressure);
            } else {
                fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
            }
        } else {
            fprintf(stderr, "Failed to read pressure\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    cleanup();
    printf("Pressure monitoring stopped.\n");

    return 0;
}

