#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3208_CS 8
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define SAMPLE_INTERVAL 5

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) return -1;

    char tx[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx[3] = {0};

    gpioWrite(MCP3208_CS, 0);
    int status = spiXfer(spi_handle, tx, rx, 3);
    gpioWrite(MCP3208_CS, 1);

    if (status < 0) return -1;

    return ((rx[1] & 0x0F) << 8) | rx[2];
}

static float calculate_humidity(int adc_value) {
    float vout = (adc_value / 4095.0) * 5.0;
    return (vout - 0.824) / 0.0315;
}

static float calculate_temperature(int adc_value) {
    float vout = (adc_value / 4095.0) * 5.0;
    float thermistor_resistance = (5.0 - vout) / vout * 10000.0;
    return (log(thermistor_resistance / 10000.0) / 0.00335) - 273.15;
}

static void send_email_alert(float humidity) {
    char command[256];
    snprintf(command, sizeof(command),
             "echo \"Subject: Humidity Alert\n\nHumidity: %.2f%%\" | ssmtp recipient@example.com", humidity);
    int result = system(command);
    if (result != 0) {
        fprintf(stderr, "Failed to send email alert (exit code: %d)\n", result);
    }
}

static void log_data(float humidity, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed.\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(MCP3208_CS, PI_OUTPUT);
    gpioWrite(MCP3208_CS, 1);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int humidity_adc = read_mcp3208(0);
        int temp_adc = read_mcp3208(1);

        if (humidity_adc < 0 || temp_adc < 0) {
            fprintf(stderr, "SPI transfer error.\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float humidity = calculate_humidity(humidity_adc);
        float temperature = calculate_temperature(temp_adc);

        if (humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(humidity);
        }

        log_data(humidity, temperature);
        printf("Humidity: %.2f%%, Temperature: %.2f°C\n", humidity, temperature);

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nCleaning up...\n");
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

