    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CS_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "mcp3208_cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature_celsius\n");
        fflush(log_file);
    }

    printf("Starting temperature logging. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t adc_value = 0;
        if (read_adc(spi_fd, cs_line, &adc_value) < 0) {
            fprintf(stderr, "ADC read failed, retrying...\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float temperature = convert_to_celsius(adc_value);

        if (temperature < TMP36_MIN_C || temperature > TMP36_MAX_C) {
            fprintf(stderr, "Warning: Temperature %.2fC out of TMP36 range [%.0f, %.0f]. Sensor absent or fault.\n",
                    temperature, TMP36_MIN_C, TMP36_MAX_C);
        } else {
            if (log_temperature(log_file, temperature) < 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");
    ret = 0;

cleanup:
    if (log_file) fclose(log_file);
    if (spi_fd >= 0) close(spi_fd);
    if (cs_line) gpiod_line_release(cs_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

