#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

/* Configuration */
#define SPI_CHANNEL 0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED   1000000    /* 1 MHz */
#define SPI_FLAGS   0          /* Mode 0, active-low CE */
#define ADC_CHANNELS 3
#define SAMPLE_RATE 100        /* Hz */
#define LOG_FILE "impact_log.txt"
#define VREF 3.3f
#define ZERO_G_VOLTAGE 1.65f   /* ADXL335 0g output at 3.3V supply */
#define SENSITIVITY 0.3f       /* 300 mV/g */
#define IMPACT_THRESHOLD 2.0f  /* g */
#define ADC_MAX 1023           /* 10-bit ADC */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read a single-ended channel from MCP3008 via SPI */
static int read_mcp3008(int channel, int *adc_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    if (adc_value == NULL) {
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     * tx[0] = 0x01 (start bit)
     * tx[1] = (0x08 | channel) << 4 (single-ended + channel, upper nibble)
     * tx[2] = 0x00 (don't care)
     * Result: bits 9..0 in rx[1] (lower 2 bits) and rx[2] (8 bits)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return 0;
}

/* Convert raw ADC value to voltage */
static float adc_to_voltage(int adc_value) {
    return ((float)adc_value / (float)ADC_MAX) * VREF;
}

/* Convert voltage to acceleration in g */
static float voltage_to_g(float voltage) {
    return (voltage - ZERO_G_VOLTAGE) / SENSITIVITY;
}

/* Log data to file */
static int log_data(float x, float y, float z, float magnitude, int impact) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime failed\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%s\n",
                timestamp, x, y, z, magnitude, impact ? "IMPACT DETECTED" : "N/A") < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel: CE0, 1 MHz, Mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,x_g,y_g,z_g,magnitude_g,impact\n");
        fflush(log_file);
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ADXL335 impact logger started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        int x_adc = 0, y_adc = 0, z_adc = 0;
        int err = 0;

        /* Read all three channels */
        if (read_mcp3008(0, &x_adc) != 0) err = 1;
        if (read_mcp3008(1, &y_adc) != 0) err = 1;
        if (read_mcp3008(2, &z_adc) != 0) err = 1;

        if (err) {
            fprintf(stderr, "SPI read error; skipping sample\n");
            gpioDelay(1000000 / SAMPLE_RATE);
            continue;
        }

        /* Validate ADC values are within 0..1023 */
        if (x_adc < 0 || x_adc > ADC_MAX ||
            y_adc < 0 || y_adc > ADC_MAX ||
            z_adc < 0 || z_adc > ADC_MAX) {
            fprintf(stderr, "ADC value out of range: X=%d Y=%d Z=%d\n", x_adc, y_adc, z_adc);
            gpioDelay(1000000 / SAMPLE_RATE);
            continue;
        }

        /* Convert to voltages */
        float v_x = adc_to_voltage(x_adc);
        float v_y = adc_to_voltage(y_adc);
        float v_z = adc_to_voltage(z_adc);

        /* Convert to acceleration in g */
        float x_g = voltage_to_g(v_x);
        float y_g = voltage_to_g(v_y);
        float z_g = voltage_to_g(v_z);

        /* Compute magnitude */
        float magnitude = sqrtf(x_g * x_g + y_g * y_g + z_g * z_g);

        /* Impact detection */
        int impact = (magnitude > IMPACT_THRESHOLD) ? 1 : 0;

        /* Log the data */
        if (log_data(x_g, y_g, z_g, magnitude, impact) != 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        /* Delay for the desired sample rate */
        gpioDelay(1000000 / SAMPLE_RATE);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

