        return ERR_READ_FAILED;
    }

    /*
     * Raw ADC values are stored in little-endian format.
     * buffer[0] = IR sample, buffer[1] = RED sample
     * Note: These raw values must be processed by the Si1172 algorithm
     *       (e.g., Si1172 SDK's HR/SpO2 calculation) to obtain accurate HR
     *       and SpO2.  For this example, we log the raw ADC values as proxy
     *       values.
     */
    *hr = (int16_t)((buffer[1] << 8) | buffer[0]);
    *spo2 = (int16_t)((buffer[3] << 8) | buffer[2]);

    return ERR_OK;
}

/* Function to log data to a CSV file */
static void log_data(time_t timestamp, int hr, int spo2, int error_code) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return;
    }

    fprintf(log_file, "%ld,%d,%d,%d\n", (long)timestamp, hr, spo2, error_code);
    fflush(log_file);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 at the Si1172 address */
    i2c_handle = i2cOpen(1, SI1172_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    /* Open the log file in append mode */
    log_file = fopen("biometric_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Write the header row if the file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,hr,spo2,error_code\n");
        fflush(log_file);
    }

    /* Initialize the Si1172 sensor */
    int init_result = si1172_init();
    if (init_result != ERR_OK) {
        fprintf(stderr, "Si1172 initialization failed (code %d).\n", init_result);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Set up signal handling for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to set SIGINT handler: %s\n", strerror(errno));
    }

    /* Main loop */
    while (!terminate) {
        int hr = 0, spo2 = 0;
        int error_code = si1172_read_data(&hr, &spo2);

        time_t current_time = time(NULL);

        if (error_code == ERR_OK) {
            log_data(current_time, hr, spo2, ERR_OK);
        } else {
            log_data(current_time, hr, spo2, error_code);
        }

        gpioDelay(1000000); /* 1 second */
    }

    /* Graceful shutdown */
    printf("\nShutting down gracefully...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

