#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <string.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define SAMPLE_RATE 16000
#define GAIN_DEFAULT 1.0f
#define NUM_SAMPLES 100

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float process_audio(int mic1_value, int mic2_value, float gain) {
    float diff = (float)mic1_value - (float)mic2_value;
    return diff * gain;
}

int main(int argc, char *argv[]) {
    float gain = GAIN_DEFAULT;

    if (argc > 1) {
        char *endptr;
        gain = strtof(argv[1], &endptr);
        if (*endptr != '\0' || gain <= 0.0f) {
            fprintf(stderr, "Invalid gain value: %s\n", argv[1]);
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Noise-cancellation audio processing started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int mic1_value = read_mcp3008(0);
        int mic2_value = read_mcp3008(1);

        if (mic1_value < 0 || mic2_value < 0) {
            fprintf(stderr, "Error reading audio data. Retrying...\n");
            gpioDelay(100000);
            continue;
        }

        float processed_audio = process_audio(mic1_value, mic2_value, gain);

        printf("%.2f\n", processed_audio);
        fflush(stdout);

        gpioDelay(1000000 / SAMPLE_RATE);
    }

    printf("\nExiting gracefully...\n");
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

