#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define BUZZER_PIN 18
#define FLAME_THRESHOLD_VOLTAGE 1.0
#define TEMP_OFFSET 25.0
#define TEMP_SCALE 0.001
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL_MS 500

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *buzzer_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    unsigned int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    unsigned char bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        return -1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", BUZZER_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(buzzer_line, "flame_buzzer", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", BUZZER_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        buzzer_line = NULL;
        return -1;
    }

    return 0;
}

static int read_ambient_temperature(void) {
    FILE *fp = fopen(AMBIENT_TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Cannot open ambient_temp.txt: %s. Using default 25.0 C\n", strerror(errno));
        return 25.0;
    }

    char temp_str[32];
    if (!fgets(temp_str, sizeof(temp_str), fp)) {
        fprintf(stderr, "Warning: Cannot read ambient temperature from file. Using default 25.0 C\n");
        fclose(fp);
        return 25.0;
    }
    fclose(fp);

    char *endptr;
    float temp = strtof(temp_str, &endptr);
    if (*endptr != '\0' || temp < -50.0 || temp > 100.0) {
        fprintf(stderr, "Warning: Invalid temperature '%s'. Using default 25.0 C\n", temp_str);
        return 25.0;
    }
    return temp;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float compensate_voltage(int adc_value, float temperature) {
    float voltage = (float)adc_value / 1023.0 * 3.3;
    return voltage + (temperature - TEMP_OFFSET) * TEMP_SCALE;
}

static void log_data(int raw_adc, float voltage, float temperature, int flame_detected) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%.3f,%.3f,%.2f,%d\n", timestamp, raw_adc, voltage, temperature, flame_detected, flame_detected);
    fflush(log_file);
}

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_spi() < 0) {
        return 1;
    }

    if (init_gpio() < 0) {
        close(spi_fd);
        spi_fd = -1;
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_adc = -1;
        for (int retry = 0; retry < MAX_RETRIES; retry++) {
            raw_adc = read_mcp3008(0);
            if (raw_adc >= 0 && raw_adc <= 1023) {
                break;
            }
            if (retry < MAX_RETRIES - 1) {
                fprintf(stderr, "Retrying MCP3008 read (attempt %d/%d)...\n", retry + 2, MAX_RETRIES);
                usleep(100000);
            }
        }

        if (raw_adc < 0 || raw_adc > 1023) {
            fprintf(stderr, "Error: Failed to read valid ADC value after %d retries. Skipping iteration.\n", MAX_RETRIES);
            if (buzzer_line) {
                gpiod_line_set_value(buzzer_line, 0);
            }
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        float temperature = read_ambient_temperature();
        float voltage = (float)raw_adc / 1023.0 * 3.3;
        float compensated_voltage = compensate_voltage(raw_adc, temperature);
        int flame_detected = (compensated_voltage > FLAME_THRESHOLD_VOLTAGE);

        if (flame_detected) {
            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                fprintf(stderr, "Error: Failed to set buzzer ON: %s\n", strerror(errno));
            }
        } else {
            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                fprintf(stderr, "Error: Failed to set buzzer OFF: %s\n", strerror(errno));
            }
        }

        log_data(raw_adc, voltage, temperature, flame_detected);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

