        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_spi() < 0) {
        return 1;
    }

    if (init_gpio() < 0) {
        close(spi_fd);
        spi_fd = -1;
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_adc = -1;
        for (int retry = 0; retry < MAX_RETRIES; retry++) {
            raw_adc = read_mcp3008(0);
            if (raw_adc >= 0 && raw_adc <= 1023) {
                break;
            }
            if (retry < MAX_RETRIES - 1) {
                fprintf(stderr, "Retrying MCP3008 read (attempt %d/%d)...\n", retry + 2, MAX_RETRIES);
                usleep(100000);
            }
        }

        if (raw_adc < 0 || raw_adc > 1023) {
            fprintf(stderr, "Error: Failed to read valid ADC value after %d retries. Skipping iteration.\n", MAX_RETRIES);
            if (buzzer_line) {
                gpiod_line_set_value(buzzer_line, 0);
            }
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        float temperature = read_ambient_temperature();
        float voltage = (float)raw_adc / 1023.0 * 3.3;
        float compensated_voltage = compensate_voltage(raw_adc, temperature);
        int flame_detected = (compensated_voltage > FLAME_THRESHOLD_VOLTAGE);

        if (flame_detected) {
            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                fprintf(stderr, "Error: Failed to set buzzer ON: %s\n", strerror(errno));
            }
        } else {
            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                fprintf(stderr, "Error: Failed to set buzzer OFF: %s\n", strerror(errno));
            }
        }

        log_data(raw_adc, voltage, temperature, flame_detected);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

