#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0
#define WATER_LEVEL_THRESHOLD_HIGH 75.0
#define WATER_LEVEL_THRESHOLD_LOW  70.0
#define LED_GPIO 17
#define JSON_FILE "water_levels.json"
#define SAMPLE_INTERVAL_US 5000000
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *json_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (json_file != NULL) {
        fflush(json_file);
        fclose(json_file);
        json_file = NULL;
    }
    if (gpioInitialise() >= 0) {
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
    }
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)(0x80 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static void log_data(double water_level) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    size_t len = strlen(timestamp);
    snprintf(timestamp + len, sizeof(timestamp) - len, ".%03ld", ts.tv_nsec / 1000000);

    if (json_file == NULL) {
        json_file = fopen(JSON_FILE, "w");
        if (json_file == NULL) {
            perror("fopen water_levels.json");
            return;
        }
        fprintf(json_file, "[\n");
    }

    fprintf(json_file, "  {\"timestamp\": \"%s\", \"water_level\": %.2f},\n", timestamp, water_level);
    fflush(json_file);
}

