    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", pigpio_error(spi_handle));
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", LED_GPIO);
        cleanup();
        return 1;
    }
    gpioWrite(LED_GPIO, 0);

    int led_state = 0;
    double water_level = 0.0;

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        water_level = (double)adc_value / 1023.0 * 100.0;

        log_data(water_level);

        if (water_level > WATER_LEVEL_THRESHOLD_HIGH && led_state == 0) {
            if (gpioWrite(LED_GPIO, 1) == 0) {
                led_state = 1;
            }
        } else if (water_level < WATER_LEVEL_THRESHOLD_LOW && led_state == 1) {
            if (gpioWrite(LED_GPIO, 0) == 0) {
                led_state = 0;
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return 0;
}

