#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0       // SPI0 CE0
#define SPI_SPEED 1000000   // 1 MHz
#define MCP3008_CHANNEL 0   // MCP3008 channel connected to AWM7300V
#define LOG_FILE "airflow_log.csv"
#define SAMPLE_INTERVAL_US 100000 // 100 milliseconds

// Global variables for signal handling
static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_lpm(int adc_value);
int log_data(float lpm);
void signal_handler(int signal);
int setup();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format for single-ended mode:
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel << 4
    // Byte 2: Don't care (0x00)
    char tx_buffer[3] = {0x01, (char)(0x80 | (channel << 4)), 0x00};
    char rx_buffer[3] = {0};

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from the last two bytes
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + (rx_buffer[2] & 0xFF);
    return adc_value;
}

// Function to convert ADC value to LPM
float convert_to_lpm(int adc_value) {
    // AWM7300V: 0-3.3V output maps to 0-1000 LPM
    // 10-bit ADC: 0-1023
    // LPM = (ADC / 1023.0) * 1000
    return ((float)adc_value / 1023.0f) * 1000.0f;
}

// Function to log data to a CSV file
int log_data(float lpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, lpm) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: Failed to flush log file\n");
        return -1;
    }

    return 0;
}

// Setup function
int setup() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,LPM\n");
        fflush(log_file);
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: Failed to register SIGTERM handler");
        return 1;
    }

    // Initialize pigpio and SPI
    if (setup() != 0) {
        return 1;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        // Convert to LPM
        float lpm = convert_to_lpm(adc_value);

        // Log data
        if (log_data(lpm) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        // Print to console
        printf("ADC: %d, LPM: %.2f\n", adc_value, lpm);

        // Delay
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    cleanup();
    printf("Airflow monitoring stopped.\n");

    return 0;
}

