#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Configuration
#define SPI_CHANNEL 0       // SPI0 CE0 (GPIO8)
#define SPI_SPEED 1000000   // 1 MHz
#define SPI_FLAGS 0          // Mode 0, active low CS
#define ADC_CHANNEL 0        // MCP3008 channel 0
#define VREF 3.3             // Reference voltage
#define ADC_MAX 1023         // 10-bit ADC
#define SAMPLE_INTERVAL 1   // Seconds

// MLX90823 pressure mapping (0.1 bar to 1.5 bar -> 10 kPa to 150 kPa)
#define PRESSURE_MIN 10.0   // kPa
#define PRESSURE_MAX 150.0  // kPa
#define VOLTAGE_MIN 0.5     // V
#define VOLTAGE_MAX 4.5     // V

// Global variables
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
float voltage_to_pressure(float voltage);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

// Read ADC value from MCP3008 via SPI
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format (3 bytes):
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel << 4
    // Byte 2: Don't care (0x00)
    unsigned char tx_buf[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char rx_buf[3] = {0};

    int bytes_transferred = spiXfer(spi_handle, (char *)tx_buf, (char *)rx_buf, 3);
    if (bytes_transferred != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", bytes_transferred);
        return -1;
    }

    // Extract 10-bit ADC value from response
    // rx_buf[1] contains the two most significant bits in its lower 2 bits
    // rx_buf[2] contains the 8 least significant bits
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Convert voltage to pressure (kPa)
float voltage_to_pressure(float voltage) {
    if (voltage < VOLTAGE_MIN) voltage = VOLTAGE_MIN;
    if (voltage > VOLTAGE_MAX) voltage = VOLTAGE_MAX;

    float pressure = PRESSURE_MIN + (voltage - VOLTAGE_MIN) * (PRESSURE_MAX - PRESSURE_MIN) / (VOLTAGE_MAX - VOLTAGE_MIN);
    return pressure;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MLX90823 Pressure Sensor Reader\n");
    printf("SPI channel %d, ADC channel %d, sampling every %d seconds\n", SPI_CHANNEL, ADC_CHANNEL, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to exit\n\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Convert ADC value to voltage
        float voltage = (float)adc_value * VREF / (float)(ADC_MAX + 1);

        // Convert voltage to pressure
        float pressure = voltage_to_pressure(voltage);

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        // Log data
        printf("%s - ADC: %d, Voltage: %.3f V, Pressure: %.2f kPa\n", timestamp, adc_value, voltage, pressure);

        // Check for sensor-absent conditions (0V or 3.3V)
        if (voltage == 0.0f) {
            printf("%s - WARNING: Sensor voltage at 0V - sensor absent or disconnected\n", timestamp);
        } else if (voltage == VREF) {
            printf("%s - WARNING: Sensor voltage at %fV - sensor saturated or fault\n", timestamp, voltage);
        }

        // Wait for next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    cleanup();
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

