#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define MCP3008_CHANNEL 0
#define MIN_ADC_VALUE 300
#define MAX_ADC_VALUE 700
#define READ_INTERVAL 5
#define MAX_CONSECUTIVE_ERRORS 10

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int mcp3008_read(uint8_t channel, uint16_t *adc_value) {
    if (channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Error setting CS low: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Error setting CS high: %s\n", strerror(errno));
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static float adc_to_moisture(uint16_t adc_value) {
    if (adc_value < MIN_ADC_VALUE) adc_value = MIN_ADC_VALUE;
    if (adc_value > MAX_ADC_VALUE) adc_value = MAX_ADC_VALUE;
    return 100.0f - ((float)(adc_value - MIN_ADC_VALUE) / (float)(MAX_ADC_VALUE - MIN_ADC_VALUE) * 100.0f);
}

static void log_data(float moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Soil Moisture: %.2f%%\n", timestamp, moisture_level);
    fflush(stdout);
}

static void cleanup(void) {
    if (cs_line) {
        gpiod_line_set_value(cs_line, 1);
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, 8);
    if (!cs_line) {
