#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define VREF 3.3f
#define NUM_CHANNELS 4
#define SAMPLE_INTERVAL_SEC 1
#define CSV_FILE "environmental_data.csv"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int spi_fd, struct gpiod_line *cs_line, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Failed to assert CS");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Failed to deassert CS");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_voltage(int adc_value, float vref) {
    return (float)adc_value * vref / 1024.0f;
}

static int log_data(FILE *fp, const char *timestamp, const float voltages[NUM_CHANNELS]) {
    if (fprintf(fp, "%s,%.4f,%.4f,%.4f,%.4f\n", timestamp, voltages[0], voltages[1], voltages[2], voltages[3]) < 0) {
        perror("Failed to write to CSV");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("Failed to open gpiochip4");
        return 1;
    }

    struct gpiod_line *cs_line = gpiod_chip_get_line(chip, 8);
    if (!cs_line) {
        perror("Failed to get GPIO8 line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008_cs", 1) < 0) {
        perror("Failed to request CS line as output");
        gpiod_chip_close(chip);
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        goto cleanup;
    }

    FILE *fp = fopen(CSV_FILE, "a");
    if (!fp) {
        perror("Failed to open CSV file");
        goto cleanup;
    }

    while (running) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        float voltages[NUM_CHANNELS];
        int error = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int adc_value = read_mcp3008(spi_fd, cs_line, i);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading channel %d\n", i);
                error = 1;
                break;
            }
            voltages[i] = adc_to_voltage(adc_value, VREF);
        }

        if (error) {
            continue;
        }

        if (log_data(fp, timestamp, voltages) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

cleanup:
    if (fp) {
        fclose(fp);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);

    return 0;
}

