#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define PUMP_GPIO 17
#define MOISTURE_LOW_THRESHOLD 300
#define MOISTURE_HIGH_THRESHOLD 600
#define SAMPLE_INTERVAL_SEC 5
#define BUFFER_SIZE 20

#define MCP3008_CHANNEL 0

typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int spi_handle = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, dummy byte */
    char tx_buf[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx_buf[3] = { 0 };

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx_buf[1] + 8 bits of rx_buf[2] */
    int adc_value = ((rx_buf[1] & 0x03) << 8) | (rx_buf[2] & 0xFF);
    return adc_value;
}

static int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Failed to write pump GPIO %d\n", PUMP_GPIO);
        return -1;
    }
    return 0;
}

static void log_data(int moisture_level, int pump_state) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Failed to get current time\n");
        return;
    }

    log_buffer[buffer_index].timestamp = now;
    log_buffer[buffer_index].moisture_level = moisture_level;
    log_buffer[buffer_index].pump_state = pump_state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }

    printf("Logged: %ld, Moisture: %d, Pump: %s\n",
           (long)now, moisture_level, pump_state ? "ON" : "OFF");
}

static void print_log_buffer(void) {
    printf("\n--- Log Buffer ---\n");
    int start = (buffer_count < BUFFER_SIZE) ? 0 : buffer_index;
    for (int i = 0; i < buffer_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S",
                 localtime(&log_buffer[idx].timestamp));
        printf("[%s] Moisture: %d, Pump: %s\n",
               ts, log_buffer[idx].moisture_level,
               log_buffer[idx].pump_state ? "ON" : "OFF");
    }
    printf("--- End Log Buffer ---\n\n");
    fflush(stdout);
}

static void timer_callback(void *user_data) {
    (void)user_data;

    int moisture_level = read_mcp3008(MCP3008_CHANNEL);
    if (moisture_level < 0) {
        fprintf(stderr, "Error reading moisture level\n");
        return;
    }

    int current_pump_state = gpioRead(PUMP_GPIO);
    if (current_pump_state < 0) {
        fprintf(stderr, "Error reading pump GPIO state\n");
        return;
    }

    log_data(moisture_level, current_pump_state);

    if (moisture_level < MOISTURE_LOW_THRESHOLD && current_pump_state == 0) {
        if (control_pump(1) == 0) {
            printf("Moisture low (%d). Pump ON.\n", moisture_level);
        }
    } else if (moisture_level > MOISTURE_HIGH_THRESHOLD && current_pump_state == 1) {
        if (control_pump(0) == 0) {
            printf("Moisture high (%d). Pump OFF.\n", moisture_level);
        }
    }

    print_log_buffer();
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    control_pump(0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set pump GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(PUMP_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize pump GPIO %d to LOW\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetTimerFunc(0, SAMPLE_INTERVAL_SEC, timer_callback) != 0) {
        fprintf(stderr, "Failed to set timer function\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Sampling every %d seconds.\n",
           SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to exit.\n");

    while (program_running) {
        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

