#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define MAX30102_ADDR 0x57
#define I2C_BUS 1

#define REG_INTR_STATUS_1 0x00
#define REG_INTR_ENABLE_1 0x01
#define REG_FIFO_WR_PTR 0x02
#define REG_OVF_COUNTER 0x03
#define REG_FIFO_RD_PTR 0x04
#define REG_FIFO_DATA 0x07
#define REG_FIFO_CONFIG 0x05
#define REG_MODE_CONFIG 0x06
#define REG_SPO2_CONFIG 0x08
#define REG_LED1_PA 0x09
#define REG_LED2_PA 0x0A
#define REG_PART_ID 0xFF

#define EXPECTED_PART_ID 0x15

#define SAMPLE_INTERVAL_US 1000000
#define FIFO_SAMPLES 6

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_fifo_data(int handle, uint8_t *data) {
    int result = i2cReadI2CBlockData(handle, REG_FIFO_DATA, (char *)data, FIFO_SAMPLES);
    if (result != FIFO_SAMPLES) {
        fprintf(stderr, "Error reading FIFO data: expected %d bytes, got %d\n", FIFO_SAMPLES, result);
        return -1;
    }
    return 0;
}

static int initialize_max30102(int handle) {
    uint8_t part_id;
    if (read_register(handle, REG_PART_ID, &part_id) != 0) {
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }

    if (write_register(handle, REG_MODE_CONFIG, 0x40) != 0) return -1;
    gpioDelay(10000);

    if (write_register(handle, REG_INTR_ENABLE_1, 0x00) != 0) return -1;
    if (write_register(handle, REG_INTR_STATUS_1, 0x00) != 0) return -1;
    if (write_register(handle, REG_FIFO_WR_PTR, 0x00) != 0) return -1;
    if (write_register(handle, REG_OVF_COUNTER, 0x00) != 0) return -1;
    if (write_register(handle, REG_FIFO_RD_PTR, 0x00) != 0) return -1;
    if (write_register(handle, REG_FIFO_CONFIG, 0x00) != 0) return -1;
    if (write_register(handle, REG_MODE_CONFIG, 0x03) != 0) return -1;
    if (write_register(handle, REG_SPO2_CONFIG, 0x27) != 0) return -1;
    if (write_register(handle, REG_LED1_PA, 0x24) != 0) return -1;
    if (write_register(handle, REG_LED2_PA, 0x24) != 0) return -1;

    return 0;
}

static int read_spo2(int handle, float *spo2) {
    uint8_t data[FIFO_SAMPLES];
    if (read_fifo_data(handle, data) != 0) {
        return -1;
    }

    uint32_t red_count = 0;
    uint32_t ir_count = 0;
    for (int i = 0; i < FIFO_SAMPLES; i++) {
        if (i % 2 == 0) {
            red_count += data[i];
        } else {
            ir_count += data[i];
        }
    }

    if (red_count == 0 || ir_count == 0) {
        return -1;
    }

    float ratio = (float)ir_count / (float)red_count;
    *spo2 = 110.0f - 25.0f * ratio;
    if (*spo2 < 0) *spo2 = 0;
    if (*spo2 > 100) *spo2 = 100;
    return 0;
}

static int read_heart_rate(int handle, float *heart_rate) {
    uint8_t data[FIFO_SAMPLES];
    if (read_fifo_data(handle, data) != 0) {
        return -1;
    }

    uint32_t ir_count = 0;
    for (int i = 0; i < FIFO_SAMPLES; i++) {
        if (i % 2 == 1) {
            ir_count += data[i];
        }
    }

    if (ir_count == 0) {
        return -1;
    }

    int peaks = 0;
    for (int i = 1; i < FIFO_SAMPLES - 1; i++) {
        if (data[i] > 100 && data[i - 1] < 100 && data[i + 1] < 100) {
            peaks++;
        }
    }

    if (peaks == 0) {
        return -1;
    }

    *heart_rate = 60.0f + (peaks * 3.0f);
    return 0;
}

static void log_data(float spo2, float heart_rate) {
    FILE *fp = fopen("health_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening health_log.txt\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, SpO2: %.2f%%, Heart Rate: %.2f BPM\n", timestamp, spo2, heart_rate);
    fclose(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_max30102(i2c_handle) != 0) {
        fprintf(stderr, "MAX30102 initialization failed\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float spo2, heart_rate;
    while (!terminate) {
        if (read_spo2(i2c_handle, &spo2) == 0 && read_heart_rate(i2c_handle, &heart_rate) == 0) {
            if (spo2 < 95.0f || heart_rate > 100.0f) {
                log_data(spo2, heart_rate);
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

