#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define NUM_SENSORS 3
#define LOG_FILE "soil_moisture_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t program_running = 1;

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_lines[NUM_SENSORS] = {NULL};
static int spi_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int init_gpio_cs(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    const char *cs_pins[] = {"8", "7", "25"};
    for (int i = 0; i < NUM_SENSORS; i++) {
        cs_lines[i] = gpiod_chip_get_line(chip, atoi(cs_pins[i]));
        if (!cs_lines[i]) {
            fprintf(stderr, "Error getting GPIO line %s: %s\n", cs_pins[i], strerror(errno));
            return -1;
        }

        if (gpiod_line_request_output(cs_lines[i], "mcp3008_cs", 1) < 0) {
            fprintf(stderr, "Error requesting GPIO line %s as output: %s\n", cs_pins[i], strerror(errno));
            return -1;
        }
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_lines[channel], 0) < 0) {
        fprintf(stderr, "Error setting CS low: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error sending SPI message: %s\n", strerror(errno));
        gpiod_line_set_value(cs_lines[channel], 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_lines[channel], 1) < 0) {
        fprintf(stderr, "Error setting CS high: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int log_data(FILE *fp, int sensor_values[NUM_SENSORS]) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor_values[0], sensor_values[1], sensor_values[2]) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (cs_lines[i]) {
            gpiod_line_release(cs_lines[i]);
            cs_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_spi() < 0) {
        return 1;
    }

    if (init_gpio_cs() < 0) {
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3\n");
        fflush(log_file);
    }

    printf("Soil moisture logging started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor_values[NUM_SENSORS];
        int read_failed = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_values[i] = read_mcp3008(i);
            if (sensor_values[i] < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i + 1);
                sensor_values[i] = -1;
                read_failed = 1;
            }
        }

        if (!read_failed) {
            if (log_data(log_file, sensor_values) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

