#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define MAX_RETRIES 3
#define DRY_RAW 200
#define WET_RAW 800

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static int threshold = DEFAULT_THRESHOLD;
static int duration = DEFAULT_DURATION;
static int sleep_interval = DEFAULT_SLEEP_INTERVAL;

static void log_message(const char *message) {
    FILE *fp = fopen("irrigation.log", "a");
    if (fp) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fclose(fp);
    } else {
        perror("Error opening log file");
    }
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) return -1;
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int map_raw_to_moisture(int raw) {
    if (raw < DRY_RAW) return 0;
    if (raw > WET_RAW) return 100;
    return (int)(((float)(raw - DRY_RAW) / (WET_RAW - DRY_RAW)) * 100.0f);
}

static void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    control_pump(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't': threshold = atoi(optarg); break;
            case 'd': duration = atoi(optarg); break;
            case 's': sleep_interval = atoi(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_pump(0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d)\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Irrigation system started");

    while (running) {
        int raw = -1;
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            raw = read_mcp3008(MCP3008_CHANNEL);
            if (raw >= 0) break;
            fprintf(stderr, "SPI read attempt %d/%d failed\n", attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1) sleep(1);
        }

        if (raw < 0) {
            log_message("Error: SPI communication failed after retries");
            sleep(sleep_interval);
            continue;
        }

        int moisture = map_raw_to_moisture(raw);
        char log_buf[128];
        snprintf(log_buf, sizeof(log_buf), "Soil moisture: %d%% (raw: %d)", moisture, raw);
        log_message(log_buf);

        if (moisture < threshold) {
            log_message("Moisture below threshold, activating pump");
            control_pump(1);
            sleep(duration);
            control_pump(0);
            log_message("Pump deactivated");
        }

        sleep(sleep_interval);
    }

    log_message("Shutting down irrigation system");
    cleanup();
    return EXIT_SUCCESS;
}

