#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL_US 10000
#define EMA_ALPHA 0.1
#define PEAK_MARGIN 0.2
#define LOG_FILE "/var/log/sound_events.log"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double update_ema(double current, double new_value) {
    return EMA_ALPHA * new_value + (1.0 - EMA_ALPHA) * current;
}

static void log_event(int value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s: Peak detected (value=%d)\n", timestamp, value) < 0) {
        perror("fprintf");
    }

    if (fclose(fp) != 0) {
        perror("fclose");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel=%d, speed=%d)\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return 1;
    }

    double ema_value = 0.0;
    int consecutive_errors = 0;

    while (running) {
        int raw = read_mcp3008(ADC_CHANNEL);
        if (raw < 0) {
            consecutive_errors++;
            if (consecutive_errors > 10) {
                fprintf(stderr, "Too many consecutive SPI errors, aborting\n");
                break;
            }
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        consecutive_errors = 0;

        double current_ema = update_ema(ema_value, (double)raw);

        if (raw > current_ema * (1.0 + PEAK_MARGIN)) {
            log_event(raw);
            ema_value = current_ema;
        } else {
            ema_value = current_ema;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return 0;
}

