#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define PCF8591_ADDR   0x48
#define AIN0_CTRL      0x00  /* single-ended, analog output disabled */
#define SAMPLE_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    int fd = -1;
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the PCF8591 slave address */
    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    /*
     * PCF8591 returns the result of the *previous* conversion on the
     * first read after a control-byte write.  A dummy read discards
     * that stale value so the next read is the current sample.
     */
    uint8_t dummy;
    if (read(fd, &dummy, 1) != 1) {
        fprintf(stderr, "Dummy read failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /*
     * Write the control byte to select AIN0 in single-ended mode.
     * The PCF8591 is read-only; writing the control byte configures
     * the next conversion.  The first read after the write returns
     * the result of that conversion.
     */
    uint8_t ctrl = AIN0_CTRL;
    if (write(fd, &ctrl, 1) != 1) {
        fprintf(stderr, "Write control byte failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Monitoring AIN0 (0x%02X) on %s every 100 ms. Press Ctrl-C to stop.\n",
           PCF8591_ADDR, I2C_BUS);

    while (g_running) {
        uint8_t sample;
        ssize_t n = read(fd, &sample, 1);
        if (n != 1) {
            fprintf(stderr, "Read failed: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("AIN0: %3u\n", (unsigned)sample);
        fflush(stdout);
        usleep(SAMPLE_DELAY_US);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

