     * PCF8591 returns the result of the *previous* conversion on the
     * first read after a control-byte write.  A dummy read discards
     * that stale value so the next read is the current sample.
     */
    uint8_t dummy;
    if (read(fd, &dummy, 1) != 1) {
        fprintf(stderr, "Dummy read failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /*
     * Write the control byte to select AIN0 in single-ended mode.
     * The PCF8591 is read-only; writing the control byte configures
     * the next conversion.  The first read after the write returns
     * the result of that conversion.
     */
    uint8_t ctrl = AIN0_CTRL;
    if (write(fd, &ctrl, 1) != 1) {
        fprintf(stderr, "Write control byte failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Monitoring AIN0 (0x%02X) on %s every 100 ms. Press Ctrl-C to stop.\n",
           PCF8591_ADDR, I2C_BUS);

    while (g_running) {
        uint8_t sample;
        ssize_t n = read(fd, &sample, 1);
        if (n != 1) {
            fprintf(stderr, "Read failed: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("AIN0: %3u\n", (unsigned)sample);
        fflush(stdout);
        usleep(SAMPLE_DELAY_US);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

