#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

/* ---------------- Configuration ---------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x48          /* ADS1115 I2C address */
#define ADC_CHANNEL          0             /* AIN0 */
#define ADC_PGA              4096          /* +/-4.096 V range */
#define ADC_OS               0             /* Single-shot */
#define ADC_MODE             0             /* +/-4.096 V */
#define ADC_DR               128           /* 128 SPS */
#define ADC_CONV_DELAY_US    10000         /* 10 ms for 128 SPS */

#define GPIO_SHUTDOWN        27
#define BUFFER_SIZE          10
#define THRESHOLD_GAUSS      500.0f
#define SAMPLE_PERIOD_US     1000000       /* 1 Hz */
#define VREF                 3.3f
#define ZERO_GAUSS_V         2.5f          /* SS49E zero-field output */
#define SENSITIVITY_MV_GAUSS 1.4f          /* ~1.4 mV/Gauss */
#define VOLTAGE_MIN          0.0f
#define VOLTAGE_MAX          3.3f

/* ---------------- Globals ---------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---------------- Circular Buffer ---------------- */
typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb) {
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float cb_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/* ---------------- Signal Handler ---------------- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---------------- ADS1115 Write ---------------- */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t val) {
    char buf[3];
    buf[0] = reg;
    buf[1] = (val >> 8) & 0xFF;
    buf[2] = val & 0xFF;
    if (i2cWriteDevice(handle, buf, 3) < 0) return -1;
    return 0;
}

/* ---------------- ADS1115 Read ---------------- */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *val) {
    char buf[2];
    if (i2cWriteDevice(handle, (char *)&reg, 1) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *val = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ---------------- ADC Conversion ---------------- */
static int ads1115_read_adc(int handle, uint16_t *raw) {
    /* Start single-shot conversion on AIN0 */
    if (ads1115_write_reg(handle, 0x01, ADC_OS) < 0) return -1;
    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    gpioDelay(10000);
    /* Read conversion result */
    if (ads1115_read_reg(handle, 0x00, raw) < 0) return -1;
    return 0;
}

/* ---------------- Sensor Reading ---------------- */
static float read_sensor(int handle) {
    uint16_t raw = 0;
    if (ads1115_read_adc(handle, &raw) < 0) {
        syslog(LOG_ERR, "I2C/ADC read failed");
        return -1.0f;
    }
    /* Convert raw 16-bit signed to voltage (PGA = +/-4.096 V) */
    int16_t signed_raw = (int16_t)raw;
    float voltage = (signed_raw * ADC_PGA) / 32768.0f;

    if (voltage < VOLTAGE_MIN || voltage > VOLTAGE_MAX) {
        syslog(LOG_ERR, "Voltage out of range: %.3f V", voltage);
        return -1.0f;
    }

    /* SS49E transfer function: B = (V - V0) / Sensitivity */
    float gauss = (voltage - ZERO_GAUSS_V) / SENSITIVITY_MV_GAUSS;
    return gauss;
}

/* ---------------- Shutdown ---------------- */
static void shutdown_motor(int gpio) {
    gpioWrite(gpio, 1);
    syslog(LOG_INFO, "Motor shutdown triggered");
}

/* ---------------- Cleanup ---------------- */
static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(GPIO_SHUTDOWN, 0);
    gpioTerminate();
    closelog();
}

/* ---------------- Main ---------------- */
int main(void) {
    openlog("hall_sensor_monitor", LOG_PID | LOG_CONS, LOG_USER);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* Configure shutdown GPIO */
    if (gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", GPIO_SHUTDOWN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_SHUTDOWN, 0);

    /* Open I2C bus to ADS1115 */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %d at addr 0x%02X", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Hall sensor monitor started (threshold %.1f G)", THRESHOLD_GAUSS);

    CircularBuffer gauss_buffer;
    cb_init(&gauss_buffer);

    while (g_running) {
        float gauss = read_sensor(g_i2c_handle);

        if (gauss >= 0.0f) {
            cb_add(&gauss_buffer, gauss);
            float avg = cb_average(&gauss_buffer);

            if (avg > THRESHOLD_GAUSS) {
                shutdown_motor(GPIO_SHUTDOWN);
            }

            syslog(LOG_INFO, "G=%.2f V=%.3f V avg=%.2f G", gauss, gauss * SENSITIVITY_MV_GAUSS / 1000.0f, avg);
        } else {
            syslog(LOG_ERR, "Sensor read failed");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

