#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MOISTURE_THRESHOLD 300
#define PUMP_DURATION 10
#define READ_INTERVAL 60
#define LOG_FILE "watering_events.txt"
#define ADC_CHANNEL 0
#define ADC_MAX 1023
#define ADC_MIN 0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    if (adc_value < ADC_MIN || adc_value > ADC_MAX) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1;
    }
    return adc_value;
}

static void log_event(int moisture_level) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "%s - Moisture Level: %d\n", timestamp, moisture_level);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

static void water_plant(void) {
    printf("Watering plant...\n");
    if (gpioWrite(PUMP_GPIO, 1) != 0) {
        fprintf(stderr, "Error: Failed to activate pump.\n");
        return;
    }
    sleep(PUMP_DURATION);
    if (gpioWrite(PUMP_GPIO, 0) != 0) {
        fprintf(stderr, "Error: Failed to deactivate pump.\n");
    }
    printf("Watering cycle complete.\n");
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioWrite(PUMP_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Automated plant watering system started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_level = read_mcp3008(ADC_CHANNEL);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level.\n");
            log_event(-1);
            sleep(1);
            continue;
        }

        printf("Moisture Level: %d\n", moisture_level);
        log_event(moisture_level);

        if (moisture_level < MOISTURE_THRESHOLD) {
            water_plant();
        }

        for (int i = 0; i < READ_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

