#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0
#define PWM_GPIO    18
#define PWM_FREQ    1000
#define PWM_RANGE   1023
#define ADC_CHANNEL 0
#define SAMPLE_US  100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0-1023 on success, -1 on SPI transfer failure.
 */
static int read_adc(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01  (start bit)
     *   tx[1] = (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   tx[2] = 0x00  (clock out remaining bits)
     * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for PWM GPIO %d\n", PWM_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed for GPIO %d\n", PWM_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "gpioSetPWMrange failed for GPIO %d\n", PWM_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with PWM off */
    gpioPWM(PWM_GPIO, 0);

    while (running) {
        int adc_value = read_adc(spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            /* SPI error: keep running, but warn */
            fprintf(stderr, "ADC read error, continuing\n");
        } else {
            int duty = adc_value;
            if (gpioPWM(PWM_GPIO, duty) != 0) {
                fprintf(stderr, "gpioPWM failed for duty %d\n", duty);
            }
            printf("ADC: %d, PWM: %d\n", adc_value, duty);
            fflush(stdout);
        }
        gpioDelay(SAMPLE_US);
    }

    /* Clean shutdown */
    gpioPWM(PWM_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

