#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

#define LED_PIN 17
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_GAIN_4_096V 0x0200
#define ADS1115_MODE_SINGLE 0x0100
#define ADS1115_DR_128_SPS 0x0080
#define ADS1115_MUX_AIN0_GND 0x4000
#define ADS1115_OS_SINGLE 0x8000

static volatile sig_atomic_t running = 1;
static double threshold = 100.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ads1115_write_reg(int handle, uint8_t reg, uint16_t val) {
    char buf[3];
    buf[0] = reg;
    buf[1] = (val >> 8) & 0xFF;
    buf[2] = val & 0xFF;
    return i2cWriteDevice(handle, buf, 3);
}

static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *val) {
    char buf[2];
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *val = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int ads1115_read_adc(int handle, int16_t *raw) {
    uint16_t cfg = ADS1115_OS_SINGLE | ADS1115_MUX_AIN0_GND | ADS1115_GAIN_4_096V | ADS1115_MODE_SINGLE | ADS1115_DR_128_SPS;
    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, cfg) != 0) return -1;
    usleep(10000);
    uint16_t val;
    if (ads1115_read_reg(handle, ADS1115_REG_CONVERSION, &val) != 0) return -1;
    *raw = (int16_t)val;
    return 0;
}

static double calculate_magnetic_field(int16_t raw) {
    double voltage = (raw * 4.096) / 32768.0;
    return voltage / 0.001;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_gauss]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring magnetic field (threshold: %.2f Gauss). Press Ctrl+C to exit.\n", threshold);

    while (running) {
        int16_t raw;
        if (ads1115_read_adc(i2c_handle, &raw) != 0) {
            fprintf(stderr, "Warning: ADC read failed, retrying...\n");
            usleep(100000);
            continue;
        }

        double field = calculate_magnetic_field(raw);
        printf("Magnetic Field: %.2f Gauss\n", field);

        if (field > threshold) {
            printf("Threshold exceeded! Blinking LED.\n");
            gpioWrite(LED_PIN, 1);
            usleep(50000);
            gpioWrite(LED_PIN, 0);
            usleep(50000);
            while (running && usleep(100000) == 100000 && field > threshold) {
                gpioWrite(LED_PIN, 1);
                usleep(50000);
                gpioWrite(LED_PIN, 0);
                usleep(50000);
            }
        }

        usleep(100000);
    }

    gpioWrite(LED_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

