#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define PWM_FREQUENCY 100
#define PWM_RANGE 1000
#define NOISE_THRESHOLD 500
#define LOG_FILE "vibration_log.txt"
#define SAMPLE_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int map_noise_to_duty(int noise_level) {
    if (noise_level <= NOISE_THRESHOLD) {
        return 0;
    }
    return (int)(((float)noise_level / NOISE_THRESHOLD) * PWM_RANGE);
}

static void log_event(int motor1_duty, int motor2_duty) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - Motor1 Duty: %d, Motor2 Duty: %d\n", timestamp, motor1_duty, motor2_duty);
    fclose(fp);
}

static void cleanup(void) {
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpioTerminate();
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 || ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to configure SPI");
        cleanup();
        return 1;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) < 0 || gpioSetMode(MOTOR2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set motor pin modes\n");
        cleanup();
        return 1;
    }

    if (gpioSetPWMfrequency(MOTOR1_PIN, PWM_FREQUENCY) < 0 || gpioSetPWMfrequency(MOTOR2_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        cleanup();
        return 1;
    }

    if (gpioSetPWMrange(MOTOR1_PIN, PWM_RANGE) < 0 || gpioSetPWMrange(MOTOR2_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        cleanup();
        return 1;
    }

    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);

    printf("Vibration motor control started. Press Ctrl+C to exit.\n");

    while (running) {
        int noise_level = read_mcp3008(0);
        if (noise_level < 0) {
            fprintf(stderr, "Error reading noise level, skipping iteration\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        int motor1_duty = map_noise_to_duty(noise_level);
        int motor2_duty = map_noise_to_duty(noise_level);

        gpioPWM(MOTOR1_PIN, motor1_duty);
        gpioPWM(MOTOR2_PIN, motor2_duty);

        log_event(motor1_duty, motor2_duty);

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

