#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES_MODE 0x11
#define BH1750_MEASUREMENT_DELAY_MS 180
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define CSV_FILE "tamper_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;
static FILE *csv_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        if (n == 0) return -1;
        total += (int)n;
    }
    return 0;
}

static int read_bh1750(int fd, float *lux) {
    if (i2c_write_cmd(fd, BH1750_CONT_HIGH_RES_MODE) < 0) {
        return -1;
    }
    usleep(BH1750_MEASUREMENT_DELAY_MS * 1000);
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) {
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) return -1;
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void log_data(FILE *fp, int sound_level, float light_level, int error_code) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(fp, "%s,%d,%.2f,%d\n", ts, sound_level, light_level, error_code);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to configure SPI: %s\n", strerror(errno));
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    csv_fp = fopen(CSV_FILE, "a");
    if (!csv_fp) {
        fprintf(stderr, "Failed to open CSV file %s: %s\n", CSV_FILE, strerror(errno));
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }
    fseek(csv_fp, 0, SEEK_END);
    if (ftell(csv_fp) == 0) {
        fprintf(csv_fp, "timestamp,sound_level_db,light_level_lux,error_code\n");
    }

    while (running) {
        int sound_level = read_mcp3008(spi_fd, 0);
        float light_level = 0.0f;
        int error_code = 0;

        if (sound_level < 0) {
            fprintf(stderr, "ADC read error: %s\n", strerror(errno));
            error_code = -1;
        } else if (read_bh1750(i2c_fd, &light_level) < 0) {
            fprintf(stderr, "BH1750 read error: %s\n", strerror(errno));
            error_code = -1;
        }

        log_data(csv_fp, sound_level, light_level, error_code);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (csv_fp) fclose(csv_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    if (spi_fd >= 0) close(spi_fd);
    return 0;
}

