#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define VALVE_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define NUM_SENSORS 3
#define LOG_FILE "irrigation.log"
#define PWM_FREQ 100
#define PWM_RANGE 100
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calculate_average(int values[], int n) {
    int sum = 0;
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (values[i] >= 0) {
            sum += values[i];
            count++;
        }
    }
    return (count > 0) ? (sum / count) : -1;
}

static int map_moisture_to_valve(int moisture_level) {
    if (moisture_level < 0) return 0;
    if (moisture_level > 1023) moisture_level = 1023;
    return 100 - (int)(((float)moisture_level / 1023.0f) * 100.0f);
}

static int set_valve_position(int position) {
    if (position < 0) position = 0;
    if (position > 100) position = 100;
    int pwm_value = (int)(((float)position / 100.0f) * PWM_RANGE);
    if (gpioPWM(VALVE_GPIO, pwm_value) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO%d\n", VALVE_GPIO);
        return -1;
    }
    return 0;
}

static void log_data(int sensor_values[], int avg, int valve_pos) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s, Sensor1: %d, Sensor2: %d, Sensor3: %d, Avg: %d, Valve: %d\n",
            timestamp, sensor_values[0], sensor_values[1], sensor_values[2], avg, valve_pos);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", VALVE_GPIO);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQ);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed on channel %d\n", SPI_CHANNEL);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int sensor_values[NUM_SENSORS];
    int valve_position = 0;

    while (running) {
        int read_failed = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_values[i] = read_mcp3008(i);
            if (sensor_values[i] < 0) {
                fprintf(stderr, "Failed to read sensor %d\n", i + 1);
                sensor_values[i] = -1;
                read_failed = 1;
            }
        }
        if (read_failed) {
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }
        int avg = calculate_average(sensor_values, NUM_SENSORS);
        if (avg < 0) {
            fprintf(stderr, "Invalid average, skipping\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }
        valve_position = map_moisture_to_valve(avg);
        if (set_valve_position(valve_position) != 0) {
            fprintf(stderr, "Failed to set valve position\n");
        }
        log_data(sensor_values, avg, valve_position);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    set_valve_position(0);
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

