#define MCP3008_CHANNEL 0
#define LOG_FILE "soil_data.txt"
#define READ_INTERVAL 5
#define MAX_RETRIES 5
#define RETRY_DELAY_BASE 1000000

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    int result = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1;
    }
    return adc_value;
}

static float calculate_moisture_percentage(int adc_value) {
    return (float)adc_value / 1023.0 * 100.0;
}

static int log_data(float moisture_percentage) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage);
    fclose(fp);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = -1;
        int retries = 0;
        int delay_ms = RETRY_DELAY_BASE;

        while (retries < MAX_RETRIES && !terminate) {
            adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value >= 0) break;
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "SPI read failed, retrying in %d ms...\n", delay_ms);
                gpioDelay(delay_ms * 1000);
                delay_ms *= 2;
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read soil moisture after %d retries.\n", MAX_RETRIES);
        } else {
            float moisture_percentage = calculate_moisture_percentage(adc_value);
            if (log_data(moisture_percentage) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
            printf("Moisture: %.2f%% (ADC: %d)\n", moisture_percentage, adc_value);
        }

        if (!terminate) {
            gpioDelay(READ_INTERVAL * 1000000);
        }
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Soil moisture monitoring stopped.\n");
    return 0;
}

