#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define MIN_FREQ 220
#define MAX_FREQ 880
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define TIMEOUT_US 30000
#define PWM_PERIOD_NS 10000000
#define PWM_DUTY_MAX 1000000

volatile sig_atomic_t program_running = 1;

struct gpiod_chip *chip = NULL;
struct gpiod_line *trig_line = NULL;
struct gpiod_line *echo_line = NULL;
int spi_fd = -1;

float min_distance = 2.0;
float max_distance = 400.0;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

void cleanup() {
    if (trig_line) gpiod_line_release(trig_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (chip) gpiod_chip_close(chip);
    if (spi_fd >= 0) close(spi_fd);
}

int init_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        perror("gpiod_chip_get_line (trig)");
        return -1;
    }
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("gpiod_chip_get_line (echo)");
        return -1;
    }
    if (gpiod_line_request_output(trig_line, "theremin", 0) < 0) {
        perror("gpiod_line_request_output (trig)");
        return -1;
    }
    if (gpiod_line_request_input(echo_line, "theremin") < 0) {
        perror("gpiod_line_request_input (echo)");
        return -1;
    }
    return 0;
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI");
        return -1;
    }
    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl SPI mode");
        return -1;
    }
    int bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl SPI bits");
        return -1;
    }
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl SPI speed");
        return -1;
    }
    return 0;
}

float read_distance() {
    gpiod_line_set_value(trig_line, 0);
    usleep(2);
    gpiod_line_set_value(trig_line, 1);
    usleep(10);
    gpiod_line_set_value(trig_line, 0);

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &start);
        if (start.tv_sec > start.tv_nsec) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1.0;
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if (end.tv_sec > end.tv_nsec) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            return -1.0;
        }
    }
    long diff_ns = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);
    float distance = (diff_ns / 1000000000.0) * 34300.0 / 2.0;
    return distance;
}

int read_photoresistor() {
    unsigned char tx[3] = {0x01, 0x80, 0x00};
    unsigned char rx[3] = {0, 0, 0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

float map_distance_to_frequency(float distance) {
    if (distance < 0) return MIN_FREQ;
    if (distance < min_distance) return MIN_FREQ + (distance - min_distance) * (MAX_FREQ - MIN_FREQ) / (min_distance - 0);
    if (distance > max_distance) return MAX_FREQ - (distance - max_distance) * (MAX_FREQ - MIN_FREQ) / (max_distance - 0);
    return MIN_FREQ + (distance - min_distance) * (MAX_FREQ - MIN_FREQ) / (max_distance - min_distance);
}

float map_photoresistor_to_duty(int adc_value) {
    if (adc_value < 0) return 0;
    float range = (float)adc_value / 1023.0;
    return PWM_DUTY_MAX * range;
}

void set_pwm_frequency(float frequency) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/period");
    FILE *fp = fopen(path, "w");
    if (!fp) {
        perror("open period");
        return;
    }
    long period_ns = (long)PWM_PERIOD_NS;
    fprintf(fp, "%ld", period_ns);
    fclose(fp);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
    fp = fopen(path, "w");
    if (!fp) {
        perror("open duty");
        return;
    }
    long duty_ns = (long)map_photoresistor_to_duty(read_photoresistor()) * period_ns / PWM_DUTY_MAX;
    fprintf(fp, "%ld", duty_ns);
    fclose(fp);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/enable");
    fp = fopen(path, "w");
    if (!fp) {
        perror("open enable");
        return;
    }
    fprintf(fp, "1");
    fclose(fp);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/frequency");
    fp = fopen(path, "w");
    if (!fp) {
        perror("open frequency");
        return;
    }
    fprintf(fp, "%.2f", frequency);
    fclose(fp);
}

void set_pwm_frequency_off() {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/enable");
    FILE *fp = fopen(path, "w");
    if (fp) {
        fprintf(fp, "0");
        fclose(fp);
    }
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
    fp = fopen(path, "w");
    if (fp) {
        fprintf(fp, "0");
        fclose(fp);
    }
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/frequency");
    fp = fopen(path, "w");
    if (fp) {
        fprintf(fp, "0");
        fclose(fp);
    }
}

void save_config() {
    FILE *fp = fopen("theremin_config.txt", "w");
    if (!fp) {
        perror("fopen config");
        return;
    }
    fprintf(fp, "%.2f,%.2f", min_distance, max_distance);
    fclose(fp);
}

void load_config() {
    FILE *fp = fopen("theremin_config.txt", "r");
    if (!fp) return;
    if (fscanf(fp, "%f,%f", &min_distance, &max_distance) != 2) {
        min_distance = 2.0;
        max_distance = 400.0;
    }
    fclose(fp);
}

int main() {
    signal(SIGINT, signal_handler);
    load_config();

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }
    if (init_spi() < 0) {
        cleanup();
        return 1;
    }

    while (program_running) {
        float distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, holding last state\n");
            usleep(100000);
            continue;
        }
        float frequency = map_distance_to_frequency(distance);
        set_pwm_frequency(frequency);
        usleep(50000);
    }

    set_pwm_frequency_off();
    cleanup();
    save_config();
    return 0;
}

