#include <signal.h>
#include <math.h>

// Motor 1
#define MOTOR1_ENABLE 18
#define MOTOR1_DIR 23

// Motor 2
#define MOTOR2_ENABLE 24
#define MOTOR2_DIR 25

// SPI
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// MCP3008 ADC channels for potentiometers
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

// PWM range
#define PWM_RANGE 255

// Speed mapping constants
#define MIN_SPEED 50
#define MAX_SPEED 255

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int map_speed(int adc_value);
void set_motor_speed(int motor_num, int speed);
void move_forward(int motor_num);
void move_backward(int motor_num);
void stop_motor(int motor_num);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3] = {0x01, (0x08 | channel) << 4, 0x00};
    unsigned char rx_buf[3] = {0};

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to map potentiometer value to speed factor using logarithmic scale
int map_speed(int adc_value) {
    if (adc_value < 0) adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;

    // Logarithmic mapping for finer control at low speeds
    float speed_factor = pow(10, (float)(adc_value / 1023.0 * 3.0));
    return (int)speed_factor;
}

// Function to set motor speed using PWM
void set_motor_speed(int motor_num, int speed) {
    if (motor_num == 1) {
        gpioPWM(MOTOR1_ENABLE, speed);
    } else if (motor_num == 2) {
        gpioPWM(MOTOR2_ENABLE, speed);
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor_num);
    }
}

// Function to move motor forward
void move_forward(int motor_num) {
    if (motor_num == 1) {
        gpioWrite(MOTOR1_DIR, 1);
    } else if (motor_num == 2) {
        gpioWrite(MOTOR2_DIR, 1);
    }
}

// Function to move motor backward
void move_backward(int motor_num) {
    if (motor_num == 1) {
        gpioWrite(MOTOR1_DIR, 0);
    } else if (motor_num == 2) {
        gpioWrite(MOTOR2_DIR, 0);
    }
}

// Function to stop motor
void stop_motor(int motor_num) {
    if (motor_num == 1) {
        gpioWrite(MOTOR1_DIR, 0);
        gpioPWM(MOTOR1_ENABLE, 0);
    } else if (motor_num == 2) {
        gpioWrite(MOTOR2_DIR, 0);
        gpioPWM(MOTOR2_ENABLE, 0);
    }
}

// Cleanup function to release resources
void cleanup() {
    stop_motor(1);
    stop_motor(2);
    gpioTerminate();
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

