    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIR, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(MOTOR1_ENABLE, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_ENABLE, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Motion control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read potentiometer values
        int pot1_value = read_mcp3008(POT1_CHANNEL);
        int pot2_value = read_mcp3008(POT2_CHANNEL);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error: Failed to read potentiometer values. Retrying...\n");
            sleep(1);
            continue;
        }

        // Map potentiometer values to speed factors
        int speed1 = map_speed(pot1_value);
        int speed2 = map_speed(pot2_value);

        // Move Motor 1 forward and Motor 2 backward
        move_forward(1);
        move_backward(2);
        set_motor_speed(1, speed1);
        set_motor_speed(2, speed2);

        // Hold for 2 seconds
        sleep(2);

        // Stop motors
        stop_motor(1);
        stop_motor(2);

        // Pause for 5 seconds
        sleep(5);

        // Reverse direction for Motor 1 and Motor 2
        move_backward(1);
        move_forward(2);

        // Repeat the process
        while (!terminate) {
            // Read potentiometer values
            int pot1_value = read_mcp3008(POT1_CHANNEL);
            int pot2_value = read_mcp3008(POT2_CHANNEL);

            if (pot1_value < 0 || pot2_value < 0) {
