#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LED_GPIO 17
#define SAMPLE_RATE_MS 10
#define CALIBRATION_DURATION_S 5
#define NOISE_THRESHOLD_PERCENT 10.0
#define DEBOUNCE_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calibrate_noise_level(int duration_s) {
    long sum = 0;
    int valid_samples = 0;

    printf("Calibrating noise level for %d seconds...\n", duration_s);

    for (int i = 0; i < duration_s * 1000 / SAMPLE_RATE_MS && running; i++) {
        int sample = read_mcp3008(0);
        if (sample < 0) {
            fprintf(stderr, "Error reading ADC during calibration\n");
            return -1;
        }
        sum += sample;
        valid_samples++;
        gpioDelay(SAMPLE_RATE_MS * 1000);
    }

    if (valid_samples == 0) {
