#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define CS_PIN          8
#define SPI_SPEED_HZ    1000000
#define SAMPLE_PERIOD_NS 1000000  /* 1 ms -> 1 kHz */
#define LOG_FILE        "audio_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int open_log_file(void)
{
    FILE *fp = fopen(LOG_FILE, "w");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }
    return 0;
}

static int open_spi_device(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(fd);
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(fd);
        return -1;
    }

    return fd;
}

static int open_gpio_chip_and_line(struct gpiod_line_request **out_req)
{
    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open(" GPIO_CHIP ")");
        return -1;
    }

    struct gpiod_line_settings *settings = gpiod_line_settings_new();
    if (!settings) {
        perror("gpiod_line_settings_new");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_settings_set_output_value(settings, GPIOD_LINE_VALUE_INACTIVE);

    struct gpiod_line_config *cfg = gpiod_line_config_new();
    if (!cfg) {
        perror("gpiod_line_config_new");
        gpiod_line_settings_free(settings);
        gpiod_chip_close(chip);
        return -1;
    }

    unsigned int offset = CS_PIN;
    if (gpiod_line_config_add_line_settings(cfg, &offset, 1, settings) < 0) {
        perror("gpiod_line_config_add_line_settings");
        gpiod_line_config_free(cfg);
        gpiod_line_settings_free(settings);
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_request_config *req_cfg = gpiod_request_config_new();
    if (!req_cfg) {
        perror("gpiod_request_config_new");
        gpiod_line_config_free(cfg);
        gpiod_line_settings_free(settings);
        gpiod_chip_close(chip);
        return -1;
    }
    gpiod_request_config_set_consumer(req_cfg, "mcp3008-cs");

    struct gpiod_line_request *req = gpiod_chip_request_lines(chip, req_cfg, cfg);
    if (!req) {
        perror("gpiod_chip_request_lines");
        gpiod_request_config_free(req_cfg);
        gpiod_line_config_free(cfg);
        gpiod_line_settings_free(settings);
        gpiod_chip_close(chip);
        return -1;
    }

    *out_req = req;
    gpiod_request_config_free(req_cfg);
    gpiod_line_config_free(cfg);
    gpiod_line_settings_free(settings);
    gpiod_chip_close(chip);
    return 0;
}

static int read_mcp3008(int spi_fd, struct gpiod_line_request *req, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /* Drive CS low to start the SPI transaction */
    if (gpiod_line_request_set_value(req, CS_PIN, GPIOD_LINE_VALUE_ACTIVE) < 0) {
        perror("gpiod_line_request_set_value(active)");
        return -1;
    }

    uint8_t tx[3] = {
        0x01,                       /* start bit */
        (uint8_t)((0x08 | channel) << 4), /* single-ended + channel */
        0x00                        /* dummy for clocking data out */
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = 8;
    tr.delay_usecs = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        gpiod_line_request_set_value(req, CS_PIN, GPIOD_LINE_VALUE_INACTIVE);
        return -1;
    }

    /* Drive CS high to end the SPI transaction */
    if (gpiod_line_request_set_value(req, CS_PIN, GPIOD_LINE_VALUE_INACTIVE) < 0) {
        perror("gpiod_line_request_set_value(inactive)");
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int log_sample(FILE *fp, int adc_value)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) < 0) {
        perror("clock_gettime");
        return -1;
    }

    if (fprintf(fp, "%ld,%d\n", (long)ts.tv_sec, adc_value) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

int main(void)
{
    if (install_signal_handlers() < 0) {
        return EXIT_FAILURE;
    }

    int spi_fd = -1;
    struct gpiod_line_request *req = NULL;
    FILE *log_fp = NULL;
    int rc = EXIT_FAILURE;

    if (open_spi_device() < 0) {
        goto cleanup;
    }
    spi_fd = open_spi_device();

    if (open_gpio_chip_and_line(&req) < 0) {
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "w");
    if (!log_fp) {
        goto cleanup;
    }

    struct timespec next_deadline;
    clock_gettime(CLOCK_MONOTONIC_RAW, &next_deadline);

    while (g_running) {
        int adc_value = read_mcp3008(spi_fd, req, 0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed; continuing\n");
            next_deadline.tv_nsec += SAMPLE_PERIOD_NS;
            if (next_deadline.tv_nsec >= 1000000000L) {
                next_deadline.tv_nsec -= 1000000000L;
                next_deadline.tv_sec++;
            }
            nanosleep(&next_deadline, NULL);
            continue;
        }

        if (log_sample(log_fp, adc_value) < 0) {
            fprintf(stderr, "Log write failed; continuing\n");
        }

        next_deadline.tv_nsec += SAMPLE_PERIOD_NS;
        if (next_deadline.tv_nsec >= 1000000000L) {
            next_deadline.tv_nsec -= 1000000000L;
            next_deadline.tv_sec++;
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC_RAW, &now);
        if (now.tv_sec < next_deadline.tv_sec ||
            (now.tv_sec == next_deadline.tv_sec && now.tv_nsec < next_deadline.tv_nsec)) {
            struct timespec sleep_ts;
            sleep_ts.tv_sec = next_deadline.tv_sec - now.tv_sec;
            sleep_ts.tv_nsec = next_deadline.tv_nsec - now.tv_nsec;
            if (sleep_ts.tv_nsec < 0) {
                sleep_ts.tv_sec--;
                sleep_ts.tv_nsec += 1000000000L;
            }
            nanosleep(&sleep_ts, NULL);
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (log_fp) {
        fclose(log_fp);
    }
    if (req) {
        gpiod_line_request_release(req);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return rc;
}

