#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>
#include <time.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_FLAGS 0 // Mode 0, active low CS

#define CS_PIN 8 // GPIO8 (CE0)
#define X_CHANNEL 0
#define Y_CHANNEL 1
#define Z_CHANNEL 2

#define SENSITIVITY 0.3 // 300 mV/g
#define ZERO_G_OFFSET 1.5 // 1.5V at rest

#define PROCESS_NOISE 0.01
#define MEASUREMENT_NOISE 0.1

#define Q_MATRIX 0.001
#define R_MATRIX 0.01

#define SAMPLE_RATE 10 // Hz
#define SAMPLE_DELAY_US (1000000 / SAMPLE_RATE)

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Kalman filter state
typedef struct {
    double state_estimate[3];
    double state_estimate_error[3][3];
    double Q[3][3];
    double R[3][3];
    double P[3][3];
    double B[3];
    double K[3];
} KalmanFilter;

KalmanFilter filter;

// Function prototypes
int read_mcp3008(int channel);
void kalman_filter(double x, double y, double z, double *x_out, double *y_out, double *z_out);
void signal_handler(int signal);
void cleanup();

// Function to read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // MCP3008 SPI command format for single-ended mode
    // Start bit (1), single-ended mode (1), channel select (3 bits)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode + channel
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect MCP3008

    if (result != 3) {
        fprintf(stderr, "SPI transfer failed for channel %d: %d\n", channel, result);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Kalman filter function
void kalman_filter(double x, double y, double z, double *x_out, double *y_out, double *z_out) {
    // Predict
    filter.state_estimate[0] += (SAMPLE_DELAY_US * Q_MATRIX[0][0] / 1000000.0);
    filter.state_estimate[1] += (SAMPLE_DELAY_US * Q_MATRIX[1][1] / 1000000.0);
    filter.state_estimate[2] += (SAMPLE_DELAY_US * Q_MATRIX[2][2] / 1000000.0);
    filter.state_estimate_error[0][0] += (SAMPLE_DELAY_US * (Q_MATRIX[0][0] + PROCESS_NOISE) / 1000000.0);
    filter.state_estimate_error[1][1] += (SAMPLE_DELAY_US * (Q_MATRIX[1][1] + PROCESS_NOISE) / 1000000.0);
    filter.state_estimate_error[2][2] += (SAMPLE_DELAY_US * (Q_MATRIX[2][2] + PROCESS_NOISE) / 1000000.0);

    // Update
    double y_x = x - filter.state_estimate[0];
    double y_y = y - filter.state_estimate[1];
    double y_z = z - filter.state_estimate[2];

    double S_x = filter.state_estimate_error[0][0] + R_MATRIX[0][0];
    double S_y = filter.state_estimate_error[1][1] + R_MATRIX[1][1];
    double S_z = filter.state_estimate_error[2][2] + R_MATRIX[2][2];

    double K_x = filter.state_estimate_error[0][0] / S_x;
    double K_y = filter.state_estimate_error[1][1] / S_y;
    double K_z = filter.state_estimate_error[2][2] / S_z;

    filter.state_estimate[0] += K_x * y_x;
    filter.state_estimate[1] += K_y * y_y;
    filter.state_estimate[2] += K_z * y_z;

    filter.state_estimate_error[0][0] -= K_x * filter.state_estimate_error[0][0];
    filter.state_estimate_error[1][1] -= K_y * filter.state_estimate_error[1][1];
    filter.state_estimate_error[2][2] -= K_z * filter.state_estimate_error[2][2];

    *x_out = filter.state_estimate[0];
    *y_out = filter.state_estimate[1];
    *z_out = filter.state_estimate[2];
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output and deselect ADC
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Kalman filter
    filter.Q[0][0] = Q_MATRIX; filter.Q[0][1] = 0; filter.Q[0][2] = 0;
    filter.Q[1][0] = 0; filter.Q[1][1] = Q_MATRIX; filter.Q[1][2] = 0;
    filter.Q[2][0] = 0; filter.Q[2][1] = 0; filter.Q[2][2] = Q_MATRIX;

    filter.R[0][0] = R_MATRIX; filter.R[0][1] = 0; filter.R[0][2] = 0;
    filter.R[1][0] = 0; filter.R[1][1] = R_MATRIX; filter.R[1][2] = 0;
    filter.R[2][0] = 0; filter.R[2][1] = 0; filter.R[2][2] = R_MATRIX;

    filter.P[0][0] = 1; filter.P[0][1] = 0; filter.P[0][2] = 0;
    filter.P[1][0] = 0; filter.P[1][1] = 1; filter.P[1][2] = 0;
    filter.P[2][0] = 0; filter.P[2][1] = 0; filter.P[2][2] = 1;

    filter.B[0] = 0; filter.B[1] = 0; filter.B[2] = 0;
    filter.K[0] = 0; filter.K[1] = 0; filter.K[2] = 0;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values
        int x_adc = read_mcp3008(X_CHANNEL);
        int y_adc = read_mcp3008(Y_CHANNEL);
        int z_adc = read_mcp3008(Z_CHANNEL);

        if (x_adc < 0 || y_adc < 0 || z_adc < 0) {
            fprintf(stderr, "Error reading ADC values. Skipping sample.\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        // Convert ADC values to voltage
        double x_voltage = (x_adc / 1023.0) * 3.3;
        double y_voltage = (y_adc / 1023.0) * 3.3;
        double z_voltage = (z_adc / 1023.0) * 3.3;

        // Convert voltage to acceleration (g)
        double x_accel = (x_voltage - ZERO_G_OFFSET) / SENSITIVITY;
        double y_accel = (y_voltage - ZERO_G_OFFSET) / SENSITIVITY;
        double z_accel = (z_voltage - ZERO_G_OFFSET) / SENSITIVITY;

        // Apply Kalman filter
        double x_filtered, y_filtered, z_filtered;
        kalman_filter(x_accel, y_accel, z_accel, &x_filtered, &y_filtered, &z_filtered);

        // Print results
