#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27
#define VCC 3.3
#define V_QUIESCENT (VCC / 2.0)
#define SENSITIVITY 0.025
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_US 100000
#define MIN_FIELD_MT -100.0
#define MAX_FIELD_MT 100.0

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_sensor(struct gpiod_line *line, const char *name) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Error reading %s: %s\n", name, strerror(errno));
        return -1;
    }
    return val;
}

static float calculate_field(int sensor_value) {
    float voltage = (float)sensor_value * (VCC / 3.0);
    float field = (voltage - V_QUIESCENT) / SENSITIVITY;
    return field;
}

static void log_data(FILE *fp, float f1, float f2, float f3) {
    if (fprintf(fp, "%.2f,%.2f,%.2f\n", f1, f2, f3) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    int gpios[3] = {SENSOR1_GPIO, SENSOR2_GPIO, SENSOR3_GPIO};
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpios[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO %d: %s\n", gpios[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "drv5055_reader") < 0) {
            fprintf(stderr, "Failed to request GPIO %d as input: %s\n", gpios[i], strerror(errno));
            goto cleanup;
        }
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Starting magnetic field monitoring. Press Ctrl+C to exit.\n");

    while (program_running) {
        int v1 = read_sensor(lines[0], "sensor1");
        int v2 = read_sensor(lines[1], "sensor2");
        int v3 = read_sensor(lines[2], "sensor3");

        if (v1 < 0 || v2 < 0 || v3 < 0) {
            fprintf(stderr, "Sensor read error, skipping iteration.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float f1 = calculate_field(v1);
        float f2 = calculate_field(v2);
        float f3 = calculate_field(v3);

        log_data(fp, f1, f2, f3);

        if (f1 < MIN_FIELD_MT || f1 > MAX_FIELD_MT ||
            f2 < MIN_FIELD_MT || f2 > MAX_FIELD_MT ||
            f3 < MIN_FIELD_MT || f3 > MAX_FIELD_MT) {
            fprintf(stderr, "Warning: Field values out of range: %.2f, %.2f, %.2f mT\n", f1, f2, f3);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    for (int i = 0; i < 3; i++) {
        if (lines[i]) gpiod_line_release(lines[i]);
    }
    if (chip) gpiod_chip_close(chip);
    return ret;
}

