#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define PUMP_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "watering.log"
#define ADC_CHANNEL 0
#define ADC_MAX 1023

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile int running = 1;

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Invalid ADC channel");
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    if (spiXfer(spi_handle, tx, rx, 3) != 0) {
        log_event("SPI transfer failed");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        log_event("Failed to write pump GPIO");
        return -1;
    }
    char msg[64];
    snprintf(msg, sizeof(msg), "Pump set to %s", state ? "ON" : "OFF");
    log_event(msg);
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    if (log_file) {
        log_event("Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }
    log_event("Program started");
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        log_event("Failed to set pump GPIO mode");
        cleanup();
        return 1;
    }
    gpioWrite(PUMP_GPIO, 0);
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        log_event("Failed to open SPI");
        cleanup();
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    while (running) {
        int moisture = read_adc(ADC_CHANNEL);
        if (moisture < 0) {
            log_event("ADC read error, skipping cycle");
        } else {
            int level = (moisture * 100) / ADC_MAX;
            char msg[64];
            snprintf(msg, sizeof(msg), "Moisture level: %d%%", level);
            log_event(msg);
            if (level < MOISTURE_THRESHOLD) {
                control_pump(1);
            } else {
                control_pump(0);
            }
        }
        gpioDelay(60000000);
    }
    cleanup();
    return 0;
}

