            char msg[64];
            snprintf(msg, sizeof(msg), "Moisture level: %d%%", level);
            log_event(msg);
            if (level < MOISTURE_THRESHOLD) {
                control_pump(1);
            } else {
                control_pump(0);
            }
        }
        gpioDelay(60000000);
    }
    cleanup();
    return 0;
}

