#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define CSV_FILE "sensor_data.csv"
#define NUM_CHANNELS 3
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *csv_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)(0x80 | (channel << 4)), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int log_data(FILE *fp, const int *values, int num_channels) {
    if (fprintf(fp, "Channel0,Channel1,Channel2\n") < 0) {
        perror("Failed to write CSV header");
        return -1;
    }
    for (int i = 0; i < num_channels; i++) {
        if (fprintf(fp, "%d,", values[i]) < 0) {
            perror("Failed to write CSV data");
            return -1;
        }
    }
    if (fflush(fp) != 0) {
        perror("Failed to flush CSV file");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(spi_fd);
        spi_fd = -1;
        return 1;
    }

    if (fprintf(csv_file, "Timestamp,Channel0,Channel1,Channel2\n") < 0) {
        perror("Failed to write CSV header");
        fclose(csv_file);
        csv_file = NULL;
        close(spi_fd);
        spi_fd = -1;
        return 1;
    }

    int values[NUM_CHANNELS];
    while (running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            values[i] = read_mcp3008(i);
            if (values[i] < 0) {
                fprintf(stderr, "Error reading channel %d\n", i);
                running = 0;
                break;
            }
        }
        if (!running) break;

        if (log_data(csv_file, values, NUM_CHANNELS) < 0) {
            fprintf(stderr, "Error logging data\n");
            running = 0;
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (csv_file != NULL) {
        fclose(csv_file);
        csv_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    return 0;
}

