#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>

#define MQTT_HOST "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define LED_GPIO 17
#define MAX_RECONNECT_DELAY 60

static volatile sig_atomic_t running = 1;
static struct mosquitto *mosq = NULL;
static int reconnect_delay = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", ts, msg);
}

void connect_callback(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker.\n");
        int rc = mosquitto_subscribe(m, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("Failed to subscribe to topic");
        }
    } else {
        log_error("Connection failed");
    }
}

void disconnect_callback(struct mosquitto *m, void *userdata, int rc) {
    (void)m; (void)userdata;
    if (rc != 0) {
        log_error("Unexpected disconnect");
    }
}

void message_callback(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m; (void)userdata;
    if (message->payloadlen > 0) {
        char payload[32];
        int len = message->payloadlen < (int)sizeof(payload) - 1 ? message->payloadlen : (int)sizeof(payload) - 1;
        memcpy(payload, message->payload, len);
        payload[len] = '\0';

        cJSON *json = cJSON_Parse(payload);
        if (!json) {
            log_error("JSON parse error");
            return;
        }

        cJSON *state_obj = cJSON_GetObjectItemCaseSensitive(json, "led_state");
        if (!cJSON_IsBoolean(state_obj)) {
            log_error("Invalid led_state type");
            cJSON_Delete(json);
            return;
        }

        int led_state = cJSON_GetBooleanValue(state_obj);
        gpioWrite(LED_GPIO, led_state ? 1 : 0);
        cJSON_Delete(json);
    }
}

void connect_lost_callback(struct mosquitto *m, void *userdata, int rc) {
    (void)m; (void)userdata;
    log_error("MQTT connection lost");
}

void connect_failed_callback(struct mosquitto *m, void *userdata, int rc) {
    (void)m; (void)userdata;
    log_error("MQTT connection failed");
}

int init_mosquitto(void) {
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create mosquitto instance");
        return -1;
    }
    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_message_callback_set(mosq, message_callback);
    mosquitto_connect_lost_callback_set(mosq, connect_lost_callback);
    mosquitto_connect_failed_callback_set(mosq, connect_failed_callback);
    return 0;
}

void cleanup_mosquitto(void) {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
        mosquitto_lib_cleanup();
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    if (init_mosquitto() != 0) {
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to connect to MQTT broker");
        cleanup_mosquitto();
        gpioTerminate();
        return 1;
    }

    while (running) {
        rc = mosquitto_loop(mosq, 100, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("MQTT loop error");
            if (reconnect_delay < MAX_RECONNECT_DELAY) {
                sleep(reconnect_delay);
                reconnect_delay *= 2;
            }
        }
    }

    cleanup_mosquitto();
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    return 0;
}

