#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18
#define CONSUMER "sound_sensor_alarm"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sound_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret;

    /* Register signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 4) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the sound sensor line (GPIO17) */
    sound_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!sound_line) {
        perror("gpiod_chip_get_line(sound)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request sound sensor line as input */
    ret = gpiod_line_request_input(sound_line, CONSUMER);
    if (ret < 0) {
        perror("gpiod_line_request_input(sound)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get the alarm LED line (GPIO18) */
    led_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line(led)");
        gpiod_line_release(sound_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request alarm LED line as output, initial value LOW */
    ret = gpiod_line_request_output(led_line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(led)");
        gpiod_line_release(sound_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Sound sensor alarm started. Press Ctrl+C to exit.\n");

    while (running) {
        int sound_level = gpiod_line_get_value(sound_line);
        if (sound_level < 0) {
            perror("gpiod_line_get_value(sound)");
            break;
        }

        printf("Sound level: %d\n", sound_level);

        if (sound_level == 0) {
            printf("Sound detected! Activating alarm.\n");
            ret = gpiod_line_set_value(led_line, 1);
            if (ret < 0) {
                perror("gpiod_line_set_value(led, ON)");
                break;
            }

            /* Blink LED ON for 1 second (100 ms intervals) */
            for (int i = 0; i < 10 && running; i++) {
                ret = gpiod_line_set_value(led_line, 0);
                if (ret < 0) {
                    perror("gpiod_line_set_value(led, OFF)");
                    running = 0;
                    break;
                }
                usleep(100000); /* 100 ms */
            }

            ret = gpiod_line_set_value(led_line, 1);
            if (ret < 0) {
                perror("gpiod_line_set_value(led, ON) after blink");
                break;
            }
        }

        usleep(100000); /* 100 ms delay between readings */
    }

    /* Clean up: turn off LED and release lines */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (sound_line) {
        gpiod_line_release(sound_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

