#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "/dev/gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE        "/var/log/vibration_shutdown.log"
#define CONSUMER_NAME   "vibration-monitor"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s: %s\n", timestamp, message) < 0) {
        perror("fprintf()");
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
    }
}

static void shutdown_system(void)
{
    log_event("Vibration detected. Shutting down system.");
    printf("Vibration detected. Shutting down system...\n");
    fflush(stdout);

    int ret = system("sudo shutdown -h now");
    if (ret == -1) {
        perror("system()");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open()");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line()");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_falling_edge_events(line, CONSUMER_NAME);
    if (ret < 0) {
        perror("gpiod_line_request_falling_edge_events()");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Vibration monitoring started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);
    fflush(stdout);

    while (program_running) {
        struct timespec ts = { 1, 0 }; /* 1-second timeout per iteration */
        ret = gpiod_line_event_wait(line, &ts);

        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("gpiod_line_event_wait()");
            break;
        }

        if (ret == 0) {
            continue; /* timeout, no event */
        }

        struct gpiod_line_event event;
        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            perror("gpiod_line_event_read()");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            log_event("Vibration detected.");
            shutdown_system();
            break;
        }
    }

    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Vibration monitoring stopped.\n");
    return EXIT_SUCCESS;
}

