static double calculate_altitude(double pressure_pa) {
    return 44330.0 * (1.0 - pow(pressure_pa / SEA_LEVEL_PRESSURE, 0.1903));
}

static int log_altitude(double altitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    if (fprintf(log_file, "%s, %.2f\n", timestamp, altitude) < 0) return -1;
    fflush(log_file);
    return 0;
