#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define VREF 3.3
#define LM35_MV_PER_C 10.0
#define BUFFER_SIZE 120
#define SAMPLE_INTERVAL_SEC 5

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static float temp_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel, int *adc_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx[3] = {0, 0, 0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return 0;
}

static float adc_to_temperature(int adc_value) {
    float voltage = (float)adc_value * VREF / 1024.0;
    return voltage * 1000.0 / LM35_MV_PER_C;
}

static void log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Temperature: %.2f °C (timestamp: %s)\n", temperature, timestamp);
}

static int write_buffer_to_file(const char *filename) {
    FILE *fp = fopen(filename, "wb+");
    if (!fp) {
        fprintf(stderr, "Error opening file %s for writing\n", filename);
        return -1;
    }

    if (fseek(fp, 0, SEEK_SET) != 0) {
        fprintf(stderr, "Error seeking to beginning of file\n");
        fclose(fp);
        return -1;
    }

    if (ftruncate(fileno(fp), BUFFER_SIZE * sizeof(float)) != 0) {
        fprintf(stderr, "Error truncating file\n");
        fclose(fp);
        return -1;
    }

    size_t written = fwrite(temp_buffer, sizeof(float), buffer_count, fp);
    if (written != buffer_count) {
        fprintf(stderr, "Error writing to file (wrote %zu of %d entries)\n", written, buffer_count);
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing file\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file\n");
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle: %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = 0;
        if (read_mcp3008(MCP3008_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "Skipping sample due to SPI error\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float temperature = adc_to_temperature(adc_value);
        log_temperature(temperature);

        temp_buffer[buffer_index] = temperature;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        if (buffer_count < BUFFER_SIZE) {
            buffer_count++;
        }

        if (buffer_count == BUFFER_SIZE) {
            if (write_buffer_to_file("temp_log.dat") != 0) {
                fprintf(stderr, "Warning: failed to write log file\n");
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nCleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

