    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    uint8_t spi_mode = SPI_MODE_0;
    uint8_t spi_bits = 8;
    uint32_t spi_speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_speed) < 0) {
        fprintf(stderr, "Error configuring SPI: %s\n", strerror(errno));
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float light = 0.0f;
        int sound = 0;
        int light_ok = read_bh1750(i2c_fd, &light);
        int sound_ok = read_mcp3008(spi_fd, MCP3008_CHANNEL, &sound);

        if (light_ok < 0) {
            fprintf(stderr, "Error reading BH1750 sensor: %s\n", strerror(errno));
        }
        if (sound_ok < 0) {
            fprintf(stderr, "Error reading MCP3008 ADC: %s\n", strerror(errno));
        }

        if (light_ok == 0 && sound_ok == 0) {
            if (log_data(LOG_FILE, light, sound) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Sensor read error; skipping log entry\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    close(i2c_fd);
    close(spi_fd);
    return 0;
}

