#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

/* Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_FLAGS 0  /* mode 0, active-low CE */
#define I2C_BUS 1
#define I2C_ADDR 0x62
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3

/* TMP36 transfer function constants */
#define TMP36_OFFSET_V 0.0f
#define TMP36_SCALE_V_PER_C 0.01f
#define VREF 3.3f
#define DAC_MAX 4095.0f
#define TEMP_MIN 0.0f
#define TEMP_MAX 50.0f

/* Globals for cleanup */
static int spi_handle = -1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    int raw_adc;
} SensorData;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read 10-bit value from MCP3008 channel 0 via SPI                    */
/* Returns 0-1023 on success, -1 on failure                           */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0 */
    unsigned char tx[3] = { 0x01, (unsigned char)(0x80 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

/* ------------------------------------------------------------------ */
/* Convert raw ADC to Celsius                                         */
/* ------------------------------------------------------------------ */
static float adc_to_celsius(int raw_adc) {
    float voltage = (float)raw_adc * (VREF / (float)(1 << 10));
    return (voltage - TMP36_OFFSET_V) * TMP36_SCALE_V_PER_C;
}

/* ------------------------------------------------------------------ */
/* Set MCP4725 DAC output to a given voltage (0-3.3V)                  */
/* ------------------------------------------------------------------ */
static int set_dac_voltage(float voltage) {
    if (voltage < 0.0f || voltage > VREF) {
        fprintf(stderr, "Error: DAC voltage %.3f V out of range [0, %.1f] V\n",
                voltage, VREF);
        return -1;
    }

    /* Convert 0-3.3V to 0-4095 counts */
    int dac_value = (int)((voltage / VREF) * DAC_MAX + 0.5f);
    if (dac_value < 0) dac_value = 0;
    if (dac_value > 4095) dac_value = 4095;

    /* MCP4725: 16-bit command, 5 MSBs = 0x7F for 16-bit mode,
     * 12 LSBs = the DAC value (left-justified) */
    unsigned char cmd[3] = { 0x7F, (unsigned char)(dac_value >> 8), (unsigned char)(dac_value & 0xFF) };

    int ret = i2cWriteDevice(i2c_handle, (char *)cmd, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: I2C write to MCP4725 failed (returned %d)\n", ret);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one reading to file and stdout                                  */
/* ------------------------------------------------------------------ */
static void log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(log_file, "%s, Raw ADC: %d, Temperature: %.2f C, DAC Voltage: %.3f V\n",
            ts, data.raw_adc, data.temperature,
            (data.temperature * (VREF / TMP36_SCALE_V_PER_C)) / 100.0f);
    fflush(log_file);

    printf("%s, Raw ADC: %d, Temperature: %.2f C, DAC Voltage: %.3f V\n",
           ts, data.raw_adc, data.temperature,
           (data.temperature * (VREF / TMP36_SCALE_V_PER_C)) / 100.0f);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open I2C */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle %d)\n", i2c_handle);
        spiClose(spi_handle);
        spi_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        spiClose(spi_handle);
        spi_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        int raw = -1;
        for (int attempt = 0; attempt < MAX_RETRIES && !terminate; attempt++) {
            raw = read_mcp3008(0);
            if (raw >= 0) break;
            if (attempt < MAX_RETRIES - 1) {
                fprintf(stderr, "Warning: ADC read attempt %d/%d failed\n",
                        attempt + 1, MAX_RETRIES);
                gpioDelay(100000); /* 100 ms backoff */
            }
        }

        if (raw < 0) {
            fprintf(stderr, "Error: ADC read failed after %d attempts\n", MAX_RETRIES);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        SensorData data;
        data.temperature = adc_to_celsius(raw);
        data.raw_adc = raw;

        if (set_dac_voltage(data.temperature * (VREF / TMP36_SCALE_V_PER_C)) != 0) {
            fprintf(stderr, "Warning: DAC set failed for reading %d\n", raw);
        }

        log_data(data);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

