#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define CONSUMER "relay-sequencer"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 22, 23, 24};
static struct gpiod_line *relay_lines[NUM_RELAYS];
static struct gpiod_chip *chip = NULL;
static volatile sig_atomic_t keep_running = 1;

static void cleanup_and_exit(int exit_code) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 0);
            gpiod_line_release(relay_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(exit_code);
}

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", relay_pins[i]);
            cleanup_and_exit(EXIT_FAILURE);
        }
        if (gpiod_line_request_output(relay_lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", relay_pins[i]);
            cleanup_and_exit(EXIT_FAILURE);
        }
    }

    while (keep_running) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (!keep_running) break;
            if (gpiod_line_set_value(relay_lines[i], 1) < 0) {
                fprintf(stderr, "Failed to set GPIO line %u HIGH\n", relay_pins[i]);
                cleanup_and_exit(EXIT_FAILURE);
            }
            sleep(1);
            if (!keep_running) break;
            if (gpiod_line_set_value(relay_lines[i], 0) < 0) {
                fprintf(stderr, "Failed to set GPIO line %u LOW\n", relay_pins[i]);
                cleanup_and_exit(EXIT_FAILURE);
            }
            sleep(1);
        }
    }

    cleanup_and_exit(EXIT_SUCCESS);
    return 0;
}

