#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0
#define SPI_SPEED        1000000          /* 1 MHz */
#define SPI_FLAGS        0                /* mode 0, active-low CS */
#define MCP3008_CHANNEL  0                /* single-ended CH0 */
#define PWM_RANGE        255
#define PWM_DUTY         150              /* 0-255 */
#define MOTOR_IN1        17
#define MOTOR_IN2        18
#define MOTOR_ENA        27
#define RAIN_THRESHOLD   5
#define POLL_INTERVAL_S  1
#define MOTOR_RUN_S      3
#define LOG_FILE         "rain_log.txt"

/* ----------------------------- Globals ----------------------------------- */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* ----------------------------- Prototypes -------------------------------- */
static int  initialize_gpio(void);
static int  initialize_spi(void);
static int  read_mcp3008(int channel, int *out_value);
static int  rain_level_from_adc(int adc_value);
static void motor_forward(void);
static void motor_reverse(void);
static void close_window(void);
static void open_window(void);
static void log_rain_data(int rain_level);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    if (initialize_spi() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    int window_open = 1;   /* 1 = open, 0 = closed */

    while (program_running) {
        int adc_value = 0;
        if (read_mcp3008(MCP3008_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "Error reading MCP3008 channel %d. Skipping cycle.\n",
                    MCP3008_CHANNEL);
            time_sleep(POLL_INTERVAL_S);
            continue;
        }

        int rain_level = rain_level_from_adc(adc_value);

        log_rain_data(rain_level);

        if (rain_level >= RAIN_THRESHOLD && window_open) {
            close_window();
            window_open = 0;
        } else if (rain_level < RAIN_THRESHOLD && !window_open) {
            open_window();
            window_open = 1;
        }

        time_sleep(POLL_INTERVAL_S);
    }

    cleanup();
    return EXIT_SUCCESS;
}

