static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d.\n", channel);
        return -1;
    }
    if (spi_handle < 0) {
        fprintf(stderr, "SPI not initialized.\n");
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1 + channel, then don't-care */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d).\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] + all 8 bits of rx[2] */
    int value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
