#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define MIC_PIN 26
#define LED_PIN 16
#define THRESHOLD_RAW 700   /* ~2.31 V on 3.3 V rail */
#define DEBOUNCE_MS 50
#define LED_ON_MS 500
#define SAMPLE_DELAY_US 1000  /* 1 ms between samples */

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read a 10-bit ADC value from the specified GPIO pin using pigpio's
 * bit-banged sampling of the pin's digital state.
 *
 * The MAX9814 output is connected to a voltage divider so that
 * 0 V -> 0 V, 1000 Hz -> ~0.7 V, 10 kHz -> ~2.2 V, 20 kHz -> ~3.3 V.
 * A simple RC low-pass filter (10 kΩ, 1 µF) on the MAX9814 output
 * converts the 20 kHz carrier to ~2.2 V at 1000 Hz.
 *
 * We sample the pin at 1 kHz for 100 ms (100 samples) and count
 * the number of 'high' samples.  This gives a 10-bit reading where
 * 0 = 0 V, 1023 = 3.3 V.
 */
static int read_adc(int pin) {
    int high_count = 0;
    for (int i = 0; i < 100 && running; i++) {
        if (gpioRead(pin) == 1) {
            high_count++;
        }
        gpioDelay(SAMPLE_DELAY_US);
    }
    return high_count;
}

static void log_detection(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime() failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s - Clap detected!\n", timestamp);
    fflush(stdout);
}

int main(void) {
    int ret;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialization failed (code %d)\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure microphone pin as input */
    ret = gpioSetMode(MIC_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set MIC_PIN %d as input\n", MIC_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output */
    ret = gpioSetMode(LED_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set LED_PIN %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED is off at start */
    ret = gpioWrite(LED_PIN, 0);
    if (ret != 0) {
        fprintf(stderr, "Failed to initialize LED_PIN %d to LOW\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Clap detector running. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        int adc_value = read_adc(MIC_PIN);

        if (adc_value < 0) {
            fprintf(stderr, "ADC read error on pin %d\n", MIC_PIN);
            gpioDelay(1000000);
            continue;
        }

        if (adc_value > THRESHOLD_RAW) {
            log_detection();
            ret = gpioWrite(LED_PIN, 1);
            if (ret != 0) {
                fprintf(stderr, "Failed to turn on LED (code %d)\n", ret);
            }
            gpioDelay(LED_ON_MS * 1000);
            ret = gpioWrite(LED_PIN, 0);
            if (ret != 0) {
                fprintf(stderr, "Failed to turn off LED (code %d)\n", ret);
            }
            gpioDelay(DEBOUNCE_MS * 1000);
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

