#define GPIO_PATH "/sys/class/gpio/gpio%d/value"
#define GPIO_EXPORT_PATH "/sys/class/gpio/export"
#define GPIO_UNEXPORT_PATH "/sys/class/gpio/unexport"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int gpio_export(int pin) {
    int fd = open(GPIO_EXPORT_PATH, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", GPIO_EXPORT_PATH, strerror(errno));
        return -1;
    }
    char buf[16];
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "Error writing to %s: %s\n", GPIO_EXPORT_PATH, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_unexport(int pin) {
    int fd = open(GPIO_UNEXPORT_PATH, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", GPIO_UNEXPORT_PATH, strerror(errno));
        return -1;
    }
    char buf[16];
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "Error writing to %s: %s\n", GPIO_UNEXPORT_PATH, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int read_gpio_value(int pin) {
    char path[64];
    snprintf(path, sizeof(path), GPIO_PATH, pin);
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    char value_str[4];
    ssize_t bytes = read(fd, value_str, sizeof(value_str) - 1);
    close(fd);
    if (bytes <= 0) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        return -1;
    }
    value_str[bytes] = '\0';
    return (value_str[0] == '1') ? 1 : 0;
}

static double calculate_distance(int gpio_value) {
    double voltage = (double)gpio_value ? 3.3 : 0.0;
    return 26.0 / voltage + (-6.0);
}

static void log_distance(double distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Distance: %.2f mm\n", timestamp, distance);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpio_export(GPIO_PIN) < 0) {
        return 1;
    }

    printf("GPIO %d initialized. Reading distance...\n", GPIO_PIN);

    while (running) {
        int gpio_value = read_gpio_value(GPIO_PIN);
        if (gpio_value < 0) {
            fprintf(stderr, "Error reading GPIO %d, retrying in 1 second...\n", GPIO_PIN);
            sleep(1);
            continue;
        }

        double distance = calculate_distance(gpio_value);
        log_distance(distance);

        if (distance < DISTANCE_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    gpio_unexport(GPIO_PIN);
    return 0;
}

