#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LED_GPIO 21
#define THRESHOLD_MT 10.0
#define VCC 3.3
#define SENSITIVITY_MV_PER_MT 1.65
#define ADC_MAX 1023.0
#define ADC_RESOLUTION 1023.0
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_DELAY_US 100000

static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double adc_to_voltage(int adc_value) {
    return (double)adc_value * VCC / ADC_RESOLUTION;
}

static double voltage_to_field_mt(double voltage) {
    double quiescent = VCC / 2.0;
    return (voltage - quiescent) * 1000.0 / SENSITIVITY_MV_PER_MT;
}

static int log_data(double field_mt) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.4f mT\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, field_mt);
    fclose(fp);
    return 0;
}

static void control_led(int state) {
    if (gpioWrite(LED_GPIO, state) != 0) {
        fprintf(stderr, "Failed to write LED GPIO %d\n", LED_GPIO);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d)\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED GPIO %d as output\n", LED_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_led(0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring magnetic field (threshold %.1f mT). Press Ctrl+C to exit.\n", THRESHOLD_MT);

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, skipping sample\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        double voltage = adc_to_voltage(adc_value);
        double field_mt = voltage_to_field_mt(voltage);

        if (log_data(field_mt) != 0) {
            fprintf(stderr, "Logging failed\n");
        }

        if (field_mt > THRESHOLD_MT) {
            control_led(1);
        } else {
            control_led(0);
        }

        printf("Field: %.4f mT\n", field_mt);
        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    control_led(0);
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

