#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * Raspberry Pi Zero W - MLX91211 Current Sensor via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> Pi 5V (Pin 2)
 *   MCP3008 VREF -> Pi 5V (Pin 2)
 *   MCP3008 AGND -> Pi GND (Pin 6)
 *   MCP3008 DGND -> Pi GND (Pin 6)
 *   MCP3008 CLK  -> Pi GPIO11 (Pin 23, SPI0 SCLK)
 *   MCP3008 DOUT -> Pi GPIO9  (Pin 21, SPI0 MISO)
 *   MCP3008 DIN  -> Pi GPIO10 (Pin 19, SPI0 MOSI)
 *   MCP3008 CS   -> Pi GPIO8  (Pin 24, SPI0 CE0)
 *   MCP3008 CH0  -> MLX91211 analog output
 *   MLX91211 VDD -> Pi 5V (Pin 2)
 *   MLX91211 GND -> Pi GND (Pin 6)
 *
 * MCP3008 SPI0, CE0, 1 MHz, mode 0.
 * MLX91211 output: 2.5V (0A) to 5.0V (+50A).
 */

#define SPI_CHANNEL    0          /* SPI0 CE0 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 CH0 */
#define LOG_FILE       "current_log.txt"
#define SAMPLE_US      100000     /* 100 ms */
#define ADC_MAX        1023       /* 10-bit */
#define VREF           5.0        /* MCP3008 VREF tied to Pi 5V */
#define VZERO          2.5        /* MLX91211 0A output */
#define I_FULL_SCALE   50.0       /* MLX91211 full-scale current */

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Read MCP3008 single-ended channel (0-7).
 * Returns 0-1023 on success, -1 on SPI error.
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1 + channel, then don't-care */
    unsigned char tx[3] = { 0x01, (unsigned char)(0x80 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_voltage(int adc)
{
    return ((float)adc / (float)ADC_MAX) * VREF;
}

static float voltage_to_current(float voltage)
{
    if (voltage < VZERO) voltage = VZERO;
    if (voltage > (VZERO + I_FULL_SCALE * (VREF - VZERO) / VREF))
        voltage = VZERO + I_FULL_SCALE * (VREF - VZERO) / VREF;
    return (voltage - VZERO) * (I_FULL_SCALE / (VREF - VZERO));
}

static void log_current(float current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s %.2f A\n", timestamp, current);
    fflush(log_file);
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX91211 current monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc = read_mcp3008(ADC_CHANNEL);
        if (adc < 0) {
            gpioDelay(SAMPLE_US);
            continue;
        }

        float voltage = adc_to_voltage(adc);
        if (voltage < VZERO || voltage > (VZERO + I_FULL_SCALE * (VREF - VZERO) / VREF)) {
            fprintf(stderr, "Warning: voltage %.3f V out of range, skipping sample\n", voltage);
            gpioDelay(SAMPLE_US);
            continue;
        }

        float current = voltage_to_current(voltage);
        log_current(current);
        gpioDelay(SAMPLE_US);
    }

    /* Cleanup */
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

