#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define CHIP_NUMBER 0
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_MS 2
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int debounce_read(struct gpiod_line *line) {
    int count[2] = {0, 0};
    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO value\n");
            return -1;
        }
        if (val == 0) count[0]++;
        else count[1]++;
        usleep(DEBOUNCE_DELAY_MS * 1000);
    }
    return (count[0] > count[1]) ? 0 : 1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_number(CHIP_NUMBER);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    if (!line1) {
        perror("gpiod_chip_get_line sensor1");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    if (!line2) {
        perror("gpiod_chip_get_line sensor2");
        goto cleanup;
    }

    if (gpiod_line_request_input(line1, "b5w-db01-s1") < 0) {
        perror("gpiod_line_request_input sensor1");
        goto cleanup;
    }

    if (gpiod_line_request_input(line2, "b5w-db01-s2") < 0) {
        perror("gpiod_line_request_input sensor2");
        goto cleanup;
    }

    printf("B5W-DB01 sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = debounce_read(line1);
        int s2 = debounce_read(line2);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error reading sensor data\n");
            break;
        }

        printf("Sensor 1: %d, Sensor 2: %d\n", s1, s2);

        if (s1 == 0 && s2 == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

