#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <sys/wait.h>
#include <pigpio.h>

#define PIR_GPIO 17
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define DEBOUNCE_DELAY_MS 200
#define POLL_INTERVAL_MS 50
#define OUTPUT_DIR "/home/pi/security_cam/"
#define CAPTURE_CMD "libcamera-still -o " OUTPUT_DIR "%s.jpg --width %d --height %d --encoding jpg --quality 85 --nopreview"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int capture_image(const char *filename) {
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        return -1;
    }
    if (pid == 0) {
        /* Child process */
        execlp("libcamera-still", "libcamera-still", filename, (char *)NULL);
        perror("execlp libcamera-still");
        _exit(127);
    }
    /* Parent: wait for child */
    int status;
    if (waitpid(pid, &status, 0) < 0) {
        perror("waitpid");
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        return 0;
    }
    return -1;
}

static int generate_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y%m%d_%H%M%S", timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int capture_and_log(void) {
    char filename[256];
    char timestamp[32];

    if (generate_timestamp(timestamp, sizeof(timestamp)) != 0) {
        syslog(LOG_ERR, "Failed to generate timestamp");
        return -1;
    }

    snprintf(filename, sizeof(filename), "%s%s.jpg", timestamp, IMAGE_WIDTH, IMAGE_HEIGHT);

    syslog(LOG_INFO, "Capturing image: %s", filename);

    if (capture_image(filename) != 0) {
        syslog(LOG_ERR, "Failed to capture image: %s", filename);
        return -1;
    }

    syslog(LOG_INFO, "Image captured: %s", filename);
    return 0;
}

int main(void) {
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        closelog();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        closelog();
        return 1;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as input", PIR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        syslog(LOG_ERR, "Failed to set pull-down on GPIO %d", PIR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Security camera started. PIR on GPIO%d, poll %dms, debounce %dms", PIR_GPIO, POLL_INTERVAL_MS, DEBOUNCE_DELAY_MS);

    int last_state = gpioRead(PIR_GPIO);
    if (last_state < 0) {
        syslog(LOG_ERR, "Initial gpioRead failed on GPIO %d", PIR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }

    while (running) {
        int current_state = gpioRead(PIR_GPIO);
        if (current_state < 0) {
            syslog(LOG_ERR, "gpioRead failed on GPIO %d", PIR_GPIO);
            break;
        }

        if (current_state != last_state) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            int confirmed_state = gpioRead(PIR_GPIO);
            if (confirmed_state < 0) {
                syslog(LOG_ERR, "gpioRead failed on GPIO %d during debounce", PIR_GPIO);
                break;
            }
            if (confirmed_state != current_state) {
                /* Transient glitch — ignore */
                continue;
            }

            if (current_state == 1) {
                syslog(LOG_INFO, "Motion detected");
                if (capture_and_log() != 0) {
                    syslog(LOG_ERR, "Capture failed");
                }
            } else {
                syslog(LOG_INFO, "Motion cleared");
            }

            last_state = current_state;
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    syslog(LOG_INFO, "Shutting down");
    gpioTerminate();
    closelog();
    return 0;
}

