    struct v4l2_buffer buf;
    unsigned char *buffers[NUM_BUFFERS];
    int buffer_fds[NUM_BUFFERS];
    int i;

    for (i = 0; i < NUM_BUFFERS; i++) {
        buffers[i] = NULL;
        buffer_fds[i] = -1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (init_camera(&fd, &cap, &fmt, &req) < 0) {
        return 1;
    }

    if (start_capture(fd, buf) < 0) {
        close(fd);
        return 1;
    }

    for (i = 0; i < req.count; i++) {
        struct v4l2_buffer buf_local;
        memset(&buf_local, 0, sizeof(buf_local));
        buf_local.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf_local.memory = V4L2_MEMORY_MMAP;
        buf_local.index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf_local) < 0) {
            perror("VIDIOC_QUERYBUF");
            goto cleanup;
        }

        buffers[i] = mmap(NULL, buf_local.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf_local.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("mmap");
            buffers[i] = NULL;
            goto cleanup;
        }
        buffer_fds[i] = fd;
    }

    while (running) {
        for (i = 0; i < req.count; i++) {
            if (read_frame(buffer_fds[i], buffers[i], BUFFER_SIZE) == 0) {
                long long timestamp = get_timestamp_us();
                if (log_frame(timestamp) < 0) {
                    fprintf(stderr, "Failed to log frame\n");
                }
            } else {
                break;
            }
        }
    }

cleanup:
    for (i = 0; i < req.count; i++) {
        if (buffers[i] != NULL) {
            munmap(buffers[i], buf_local.length);
        }
        if (buffer_fds[i] >= 0) {
            close(buffer_fds[i]);
        }
    }

    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
    }

    return 0;
}

