#include <arpa/inet.h>
#include <linux/videodev2.h>

#define MAX_PACKET_SIZE 65000
#define MAX_FRAMES 1000
#define FRAME_SIZE 640 * 480 * 2
#define NUM_BUFFERS 4

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

struct buffer {
    void   *start;
    size_t  length;
};

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(int argc, char *argv[]) {
    const char *server_ip = NULL;
    int server_port = 0;
    int fd = -1;
    struct buffer *buffers = NULL;
    int num_buffers = 0;
    int sockfd = -1;
    int ret = EXIT_FAILURE;

    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }
    server_ip = argv[1];
    server_port = atoi(argv[2]);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("open(/dev/video0)");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "/dev/video0 is not a video capture device\n");
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "/dev/video0 does not support streaming\n");
        goto cleanup;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Warning: driver did not accept YUYV, using %s\n",
                fmt.fmt.pix.pixelformat);
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }
    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto cleanup;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("calloc");
        goto cleanup;
    }

    for (num_buffers = 0; num_buffers < req.count; num_buffers++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = num_buffers;
        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            goto cleanup;
        }
        buffers[num_buffers].length = buf.length;
        buffers[num_buffers].start = mmap(NULL, buf.length,
                                          PROT_READ | PROT_WRITE,
                                          MAP_SHARED, fd, buf.m.offset);
        if (buffers[num_buffers].start == MAP_FAILED) {
            perror("mmap");
            buffers[num_buffers].start = NULL;
            goto cleanup;
        }
    }

    for (int i = 0; i < num_buffers; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            goto cleanup;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        goto cleanup;
    }

    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_ip, &servaddr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid server IP: %s\n", server_ip);
        goto cleanup;
    }

    unsigned char header[16];
    int frame_count = 0;
    int frag_count = 0;

    while (running) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) continue;
            perror("VIDIOC_DQBUF");
            goto cleanup;
        }

        if (buf.index >= num_buffers) {
            fprintf(stderr, "Buffer index out of range\n");
            goto cleanup;
        }

        if (buf.bytesused < FRAME_SIZE) {
            continue;
        }

        frame_count++;
        frag_count = 0;

        while (buf.bytesused > 0) {
            int to_send = buf.bytesused;
            if (to_send > MAX_PACKET_SIZE) {
                to_send = MAX_PACKET_SIZE;
            }

            int hdr_size = 16;
            int payload = to_send - hdr_size;
            if (payload <= 0) {
                hdr_size = buf.bytesused;
                payload = buf.bytesused;
            }

            memcpy(header, &frame_count, 4);
            memcpy(header + 4, &frag_count, 4);
            memcpy(header + 8, &frame_count, 4);
            memcpy(header + 12, &payload, 4);

            ssize_t sent = sendto(sockfd, header, hdr_size, 0,
                                  (struct sockaddr *)&servaddr,
                                  sizeof(servaddr));
            if (sent < 0) {
                perror("sendto");
                goto cleanup;
            }
            if (sent != hdr_size) {
                fprintf(stderr, "Partial header send: %zd of %d\n", sent, hdr_size);
                goto cleanup;
            }

            sent = sendto(sockfd, (void *)(buf.base + buf.bytesused - payload),
                          payload, 0,
                          (struct sockaddr *)&servaddr,
                          sizeof(servaddr));
            if (sent < 0) {
                perror("sendto payload");
                goto cleanup;
            }
            if (sent != payload) {
                fprintf(stderr, "Partial payload send: %zd of %d\n", sent, payload);
                goto cleanup;
            }

            frag_count++;
            buf.bytesused -= payload;
        }

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            goto cleanup;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (sockfd >= 0) {
        close(sockfd);
    }
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
    }
    if (buffers) {
        for (int i = 0; i < num_buffers; i++) {
            if (buffers[i].start && buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        free(buffers);
    }
    return ret;
}

