#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define PAN_PIN      4
#define TILT_PIN     5
#define TILT_UP_PIN  6
#define TILT_DOWN_PIN 7
#define PAN_LEFT_PIN  8
#define PAN_RIGHT_PIN 9

#define PWM_PERIOD_NS 20000000L  /* 20 ms = 50 Hz */
#define MIN_PULSE_NS  1000000L   /* 1 ms  */
#define MAX_PULSE_NS  2000000L   /* 2 ms  */
#define MID_PULSE_NS  1500000L   /* 1.5 ms */

#define BUTTON_POLLED_MS 50

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_ns(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    return (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
}

static void sleep_ns(long long ns) {
    struct timespec ts;
    ts.tv_sec  = (time_t)(ns / 1000000000LL);
    ts.tv_nsec = (long)(ns % 1000000000LL);
    nanosleep(&ts, NULL);
}

static int set_servo_pulse(struct gpiod_line *line, int duty) {
    if (duty < 0) duty = 0;
    if (duty > 100) duty = 100;
    long long on_ns = (PWM_PERIOD_NS * (long long)duty) / 100;
    long long off_ns = PWM_PERIOD_NS - on_ns;
    if (on_ns < MIN_PULSE_NS) on_ns = MIN_PULSE_NS;
    if (off_ns < MIN_PULSE_NS) off_ns = MIN_PULSE_NS;
    if (on_ns > MAX_PULSE_NS) on_ns = MAX_PULSE_NS;
    if (off_ns > MAX_PULSE_NS) off_ns = MAX_PULSE_NS;

    if (gpiod_line_set_value(line, 1) < 0) return -1;
    sleep_ns(on_ns);
    if (gpiod_line_set_value(line, 0) < 0) return -1;
    sleep_ns(off_ns);
    return 0;
}

static int move_servo(struct gpiod_line *line, int direction, int *position) {
    *position += direction;
    if (*position < 25) *position = 25;
    if (*position > 125) *position = 125;
    return set_servo_pulse(line, *position);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pan_line = NULL, *tilt_line = NULL;
    struct gpiod_line *up_line = NULL, *down_line = NULL;
    struct gpiod_line *left_line = NULL, *right_line = NULL;
    int pan_pos = 75, tilt_pos = 75;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    pan_line  = gpiod_chip_get_line(chip, PAN_PIN);
    tilt_line = gpiod_chip_get_line(chip, TILT_PIN);
    up_line   = gpiod_chip_get_line(chip, TILT_UP_PIN);
    down_line = gpiod_chip_get_line(chip, TILT_DOWN_PIN);
    left_line = gpiod_chip_get_line(chip, PAN_LEFT_PIN);
    right_line = gpiod_chip_get_line(chip, PAN_RIGHT_PIN);

    if (!pan_line || !tilt_line || !up_line || !down_line ||
        !left_line || !right_line) {
        fprintf(stderr, "Failed to get one or more GPIO lines\n");
        goto cleanup;
    }

    if (gpiod_line_request_output(pan_line, "pan-servo", 0) < 0 ||
        gpiod_line_request_output(tilt_line, "tilt-servo", 0) < 0 ||
        gpiod_line_request_output(up_line, "tilt-up", 1) < 0 ||
        gpiod_line_request_output(down_line, "tilt-down", 1) < 0 ||
        gpiod_line_request_output(left_line, "pan-left", 1) < 0 ||
        gpiod_line_request_output(right_line, "pan-right", 1) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("Pan-tilt servo control started. Press Ctrl+C to exit.\n");

    while (running) {
        int up_val, down_val, left_val, right_val;

        up_val = gpiod_line_get_value(up_line);
        down_val = gpiod_line_get_value(down_line);
        left_val = gpiod_line_get_value(left_line);
        right_val = gpiod_line_get_value(right_line);

        if (up_val < 0 || down_val < 0 || left_val < 0 || right_val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        if (up_val == 0) move_servo(tilt_line, 5, &tilt_pos);
        if (down_val == 0) move_servo(tilt_line, -5, &tilt_pos);
        if (left_val == 0) move_servo(pan_line, 5, &pan_pos);
        if (right_val == 0) move_servo(pan_line, -5, &pan_pos);

        sleep_ns(BUTTON_POLLED_MS * 1000000LL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (pan_line) gpiod_line_release(pan_line);
    if (tilt_line) gpiod_line_release(tilt_line);
    if (up_line)   gpiod_line_release(up_line);
    if (down_line) gpiod_line_release(down_line);
    if (left_line) gpiod_line_release(left_line);
    if (right_line) gpiod_line_release(right_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

