#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <jpeglib.h>

#define CAMERA_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define BLUR_SIZE 5
#define JPEG_QUALITY 75
#define CAPTURE_TIMEOUT_SEC 2

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, int request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd_out) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    *fd_out = open(CAMERA_DEVICE, O_RDWR);
    if (*fd_out < 0) {
        fprintf(stderr, "Error opening %s: %s\n", CAMERA_DEVICE, strerror(errno));
        return -1;
    }

    if (xioctl(*fd_out, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(*fd_out);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", CAMERA_DEVICE);
        close(*fd_out);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", CAMERA_DEVICE);
        close(*fd_out);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd_out, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        close(*fd_out);
        return -1;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Warning: device did not accept YUYV, using %s\n", fmt.fmt.pix.pixelformat);
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd_out, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        close(*fd_out);
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(*fd_out, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        close(*fd_out);
        return -1;
    }

    if (xioctl(*fd_out, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        close(*fd_out);
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(*fd_out, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        close(*fd_out);
        return -1;
    }

    return 0;
}

static int capture_frame(int fd, unsigned char **frame_out) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = CAPTURE_TIMEOUT_SEC;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return -1;
        fprintf(stderr, "select() failed: %s\n", strerror(errno));
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "Frame capture timeout (%d s)\n", CAPTURE_TIMEOUT_SEC);
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
        return -1;
    }

    *frame_out = malloc(buf.length);
    if (!*frame_out) {
        fprintf(stderr, "Memory allocation failed\n");
        xioctl(fd, VIDIOC_QBUF, &buf);
        return -1;
    }

    memcpy(*frame_out, buf.data, buf.length);
    xioctl(fd, VIDIOC_QBUF, &buf);

    return 0;
}

static void yuyv_to_rgb24(const unsigned char *yuyv, unsigned char *rgb, int w, int h) {
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j += 2) {
            int y0 = yuyv[i * w + j];
            int u = yuyv[i * w + j + 1];
            int y1 = yuyv[i * w + j + w + 1];
            int v = yuyv[i * w + j + w + 2];

            int r = y0 + (16 + (v * 110) / 1024);
            int g = y0 - (u * 84) / 1024 - (v * 110) / 1024;
            int b = y0 + (u * 128) / 1024;

            rgb[i * w * 3 + j * 3] = (unsigned char)(r < 0 ? 0 : (r > 255 ? 255 : r));
            rgb[i * w * 3 + j * 3 + 1] = (unsigned char)(g < 0 ? 0 : (g > 255 ? 255 : g));
            rgb[i * w * 3 + j * 3 + 2] = (unsigned char)(b < 0 ? 0 : (b > 255 ? 255 : b));
        }
    }
}

static void apply_blur(unsigned char *rgb, int w, int h, int blur_size) {
    int half = blur_size / 2;
    int size = blur_size * blur_size;
    unsigned char *blur = malloc(size * 3);
    if (!blur) return;

    for (int i = 0; i < size; i++) blur[i] = 0;

    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            int idx = (i * w + j) * 3;
            for (int dy = -half; dy <= half; dy++) {
                for (int dx = -half; dx <= half; dx++) {
                    int ni = i + dy;
                    int nj = j + dx;
                    if (ni >= 0 && ni < h && nj >= 0 && nj < w) {
                        int nidx = (ni * w + nj) * 3;
                        blur[i * size + dy * blur_size + dx] += rgb[nidx];
                    }
                }
            }
        }
    }

    for (int i = 0; i < size; i++) blur[i] /= (blur_size * blur_size);

    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            int idx = (i * w + j) * 3;
            for (int dy = -half; dy <= half; dy++) {
                for (int dx = -half; dx <= half; dx++) {
                    int ni = i + dy;
                    int nj = j + dx;
                    if (ni >= 0 && ni < h && nj >= 0 && nj < w) {
                        int nidx = (ni * w + nj) * 3;
                        rgb[idx] = (unsigned char)(blur[i * size + dy * blur_size + dx] + rgb[nidx]);
                    }
                }
            }
        }
    }

    free(blur);
}

static int save_jpeg(const unsigned char *rgb, int w, int h, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile = NULL;
    JSAMPROW row_pointer[1];

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);
    jpeg_mem_dest(&cinfo, &outfile);

    cinfo.image_width = w;
    cinfo.image_height = h;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);
    jpeg_start_compress(&cinfo, TRUE);

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb[cinfo.next_scanline * w * 3];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);

    if (!outfile) {
        fprintf(stderr, "Failed to create JPEG output\n");
        return -1;
    }

    if (fwrite(outfile, 1, jpeg_get_buffer_size(outfile), stdout) != jpeg_get_buffer_size(outfile)) {
        fprintf(stderr, "Failed to write JPEG data\n");
        fclose(outfile);
        return -1;
    }

    fclose(outfile);
    return 0;
}

int main(void) {
    int fd = -1;
    unsigned char *frame = NULL;
    unsigned char *rgb = NULL;
    char filename[256];
    int ret = 1;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_camera(&fd) < 0) return 1;

    if (capture_frame(fd, &frame) < 0) {
        fprintf(stderr, "Frame capture failed\n");
        goto cleanup;
    }

    if (frame) {
        int w = IMAGE_WIDTH;
        int h = IMAGE_HEIGHT;
        int n = w * h * 2;
        rgb = malloc(w * h * 3);
        if (!rgb) {
            fprintf(stderr, "Memory allocation failed\n");
            goto cleanup;
        }
        yuyv_to_rgb24(frame, rgb, w, h);
        apply_blur(rgb, w, h, BLUR_SIZE);

        time_t rawtime;
        struct tm *timeinfo;
        char ts[80];
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(ts, sizeof(ts), "%Y%m%d_%H%M%S", timeinfo);
        snprintf(filename, sizeof(filename), "capture_%s.jpg", ts);

        if (save_jpeg(rgb, w, h, filename) < 0) {
            fprintf(stderr, "JPEG save failed\n");
            goto cleanup;
        }
        printf("Saved blurred image: %s\n", filename);
        ret = 0;
    }

cleanup:
    if (frame) free(frame);
    if (rgb) free(rgb);
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        xioctl(fd, VIDIOC_QBUF, &buf);
        munmap(buf.data, buf.length);
        free(buf.data);
        close(fd);
    }
    return ret;
}

