    printf("  Bus info: %s\n", cap->bus_info);
}

static void print_frame_size(const struct v4l2_frmsizeenum *fs) {
    printf("  Frame size: %ux%u\n", fs->pixel_format, fs->size_width);
}

static void print_frame_interval(const struct v4l2_frmivalenum *fi) {
    printf("  Frame interval: %u/%u\n", fi->step_rate, fi->denominator);
}

int main(void) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_frmsizeenum frmsize;
    struct v4l2_frmivalenum frmival;
    struct v4l2_control focus_ctrl;
    unsigned int focus_step;
    int focus_supported;

    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

