#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN  6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define SERVO_CENTER_PULSE_WIDTH 1500
#define STEP_SIZE 10
#define LOOP_DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_pulse(int pin, int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: pulse width %d out of range [%d, %d]\n",
                pulse_width, SERVO_MIN_PULSE_WIDTH, SERVO_MAX_PULSE_WIDTH);
        return -1;
    }
    if (gpioServo(pin, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int move_servo(int pin, int direction, int *current_pulse) {
    *current_pulse += direction;
    if (*current_pulse > SERVO_MAX_PULSE_WIDTH) {
        *current_pulse = SERVO_MAX_PULSE_WIDTH;
    } else if (*current_pulse < SERVO_MIN_PULSE_WIDTH) {
        *current_pulse = SERVO_MIN_PULSE_WIDTH;
    }
    return set_servo_pulse(pin, *current_pulse);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pan_pulse = SERVO_CENTER_PULSE_WIDTH;
    int tilt_pulse = SERVO_CENTER_PULSE_WIDTH;

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set servo pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(UP_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set button pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set button pull-ups\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pan-Tilt Servo Control\n");
    printf("Pan servo: GPIO%d | Tilt servo: GPIO%d\n", PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("Buttons (active-low, wired to GND): UP=GPIO%d, DOWN=GPIO%d, LEFT=GPIO%d, RIGHT=GPIO%d\n",
           UP_BUTTON_PIN, DOWN_BUTTON_PIN, LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int up_pressed = (gpioRead(UP_BUTTON_PIN) == 0);
        int down_pressed = (gpioRead(DOWN_BUTTON_PIN) == 0);
        int left_pressed = (gpioRead(LEFT_BUTTON_PIN) == 0);
        int right_pressed = (gpioRead(RIGHT_BUTTON_PIN) == 0);

        if (up_pressed) {
            if (move_servo(PAN_SERVO_PIN, STEP_SIZE, &pan_pulse) == 0) {
                printf("Pan servo moving UP  -> %d us\n", pan_pulse);
            }
        } else if (down_pressed) {
            if (move_servo(PAN_SERVO_PIN, -STEP_SIZE, &pan_pulse) == 0) {
                printf("Pan servo moving DOWN -> %d us\n", pan_pulse);
            }
        }

        if (left_pressed) {
            if (move_servo(TILT_SERVO_PIN, STEP_SIZE, &tilt_pulse) == 0) {
                printf("Tilt servo moving LEFT -> %d us\n", tilt_pulse);
            }
        } else if (right_pressed) {
            if (move_servo(TILT_SERVO_PIN, -STEP_SIZE, &tilt_pulse) == 0) {
                printf("Tilt servo moving RIGHT -> %d us\n", tilt_pulse);
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

