#define PIR_GPIO 17
#define DEBOUNCE_SEC 2
#define POLL_INTERVAL_US 100000
#define CAPTURE_DIR "motion_captures"
#define JPEG_QUALITY 85
#define SERVER_ENDPOINT "/upload"
#define MAX_FILENAME_LEN 256
#define MAX_MSG_LEN 512

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ensure_capture_dir(void) {
    struct stat st;
    if (stat(CAPTURE_DIR, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", CAPTURE_DIR);
        return -1;
    }
    if (mkdir(CAPTURE_DIR, 0755) != 0 && errno != EEXIST) {
        fprintf(stderr, "Error creating directory '%s': %s\n", CAPTURE_DIR, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    char command[512];
    snprintf(command, sizeof(command),
             "libcamera-still -o %s -q %d --width 640 --height 480 2>/dev/null",
             filename, JPEG_QUALITY);

    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error executing libcamera-still: %s\n", strerror(errno));
        return -1;
    }

    char buffer[128];
    size_t total = 0;
    while (fgets(buffer, sizeof(buffer), fp) != NULL) {
        size_t len = strlen(buffer);
        if (len > 0 && buffer[len - 1] == '\n') buffer[--len] = '\0';
        if (total + len >= sizeof(buffer)) break;
        strncat(buffer, buffer + total, sizeof(buffer) - total - 1);
        total += len;
    }
    pclose(fp);

    if (total == 0) {
        fprintf(stderr, "libcamera-still produced no output\n");
        return -1;
    }

    if (access(filename, F_OK) != 0) {
        fprintf(stderr, "Error: image file not created: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int send_data(const char *filename, const char *timestamp, int motion_status, int gpio_pin) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error initializing libcurl\n");
        return -1;
    }

    char json[MAX_MSG_LEN];
    int json_len = snprintf(json, sizeof(json),
        "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion_status\":\"%d\",\"gpio_pin\":%d}",
        filename, timestamp, motion_status, gpio_pin);
    if (json_len < 0 || (size_t)json_len >= sizeof(json)) {
        fprintf(stderr, "Error formatting JSON payload\n");
        curl_easy_cleanup(curl);
        return -1;
    }

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        fprintf(stderr, "Error creating curl headers\n");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, "http://localhost:8080" SERVER_ENDPOINT);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
