#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_GPIO_LINE	17
#define GPIO_CHIP_NAME	"gpiochip0"
#define IMAGES_DIR		"/home/pi/images"
#define LOG_FILE		"/home/pi/motion_capture.log"
#define DEBOUNCE_MS	50
#define POLL_TIMEOUT_MS	1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
	(void)sig;
	program_running = 0;
}

static void log_event(const char *message)
{
	FILE *fp = fopen(LOG_FILE, "a");
	if (!fp) {
		fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
		return;
	}

	time_t t = time(NULL);
	struct tm tm;
	if (localtime_r(&t, &tm)) {
		fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
			tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
			tm.tm_hour, tm.tm_min, tm.tm_sec, message);
	} else {
		fprintf(fp, "[unknown time] %s\n", message);
	}
	fclose(fp);
}

static int capture_image(const char *filename)
{
	char command[512];
	int ret = snprintf(command, sizeof(command),
		"libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview",
		filename);
	if (ret < 0 || (size_t)ret >= sizeof(command)) {
		log_event("Error: image filename too long for command buffer");
		return -1;
	}

	int status = system(command);
	if (status == -1) {
		log_event("Error: system() failed to execute libcamera-still");
		return -1;
	}
	if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
		char msg[128];
		snprintf(msg, sizeof(msg),
			"Error: libcamera-still exited with status %d",
			WIFEXITED(status) ? WEXITSTATUS(status) : -1);
		log_event(msg);
		return -1;
	}
	return 0;
}

static int generate_filename(char *buf, size_t buflen)
{
	time_t rawtime;
	struct tm *timeinfo;

	time(&rawtime);
	timeinfo = localtime(&rawtime);
	if (!timeinfo) {
		log_event("Error: localtime() failed");
		return -1;
	}

	if (strftime(buf, buflen, "%Y%m%d_%H%M%S", timeinfo) == 0) {
		log_event("Error: strftime() failed");
		return -1;
	}

	char ms_buf[8];
	snprintf(ms_buf, sizeof(ms_buf), "%03d",
		rand() % 1000);

	if (snprintf(buf + strlen(buf), buflen - strlen(buf),
		"_%s%s.jpg", ms_buf, buf) >= (int)buflen) {
		log_event("Error: filename too long after appending millisecond");
		return -1;
	}
	return 0;
}

int main(void)
{
	struct gpiod_chip *chip = NULL;
	struct gpiod_line *pir_line = NULL;
	int ret = EXIT_FAILURE;

	struct sigaction sa;
	memset(&sa, 0, sizeof(sa));
	sa.sa_handler = signal_handler;
	sigemptyset(&sa.sa_mask);
	sa.sa_flags = 0;
	if (sigaction(SIGINT, &sa, NULL) == -1) {
		log_event("Error: failed to register SIGINT handler");
		return EXIT_FAILURE;
	}
	if (sigaction(SIGTERM, &sa, NULL) == -1) {
		log_event("Error: failed to register SIGTERM handler");
		return EXIT_FAILURE;
	}

	chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
	if (!chip) {
		log_event("Error: failed to open GPIO chip");
		return EXIT_FAILURE;
	}

	pir_line = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
	if (!pir_line) {
		log_event("Error: failed to get GPIO line 17");
		goto cleanup_chip;
	}

	if (gpiod_line_request_falling_edge_events(pir_line, "pir-motion") < 0) {
		log_event("Error: failed to request falling-edge events on GPIO17");
		goto cleanup_chip;
	}

	log_event("Motion detection system started");

	while (program_running) {
		struct timespec ts = { 0, POLL_TIMEOUT_MS * 1000000L };
		int ev = gpiod_line_event_wait(pir_line, &ts);
		if (ev < 0) {
			if (errno == EINTR) continue;
			log_event("Error: gpiod_line_event_wait failed");
			break;
		}
		if (ev == 0) {
			continue;
		}

		struct gpiod_line_event event;
		if (gpiod_line_event_read(pir_line, &event) < 0) {
			log_event("Error: gpiod_line_event_read failed");
			continue;
		}

		if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) {
			continue;
		}

		char filename[128];
		if (generate_filename(filename, sizeof(filename)) < 0) {
			continue;
		}

		char log_msg[256];
		snprintf(log_msg, sizeof(log_msg),
			"Motion detected on GPIO%d. Capturing image: %s",
			PIR_GPIO_LINE, filename);
		log_event(log_msg);

		if (capture_image(filename) < 0) {
			log_event("Error: image capture failed");
		} else {
			char copy_msg[256];
			snprintf(copy_msg, sizeof(copy_msg),
				"Image saved: %s", filename);
			log_event(copy_msg);
		}
	}

	log_event("Motion detection system stopped");
	ret = EXIT_SUCCESS;

cleanup_chip:
	if (pir_line) {
		gpiod_line_release(pir_line);
	}
	if (chip) {
		gpiod_chip_close(chip);
	}
	return ret;
}

