#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define NEUTRAL_ANGLE 90
#define DELAY_MS 100

static volatile int keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int angle_to_pulse_width(int angle) {
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    return MIN_PULSE_WIDTH + (angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH)) / MAX_ANGLE;
}

int set_servo_angle(int gpio, int angle) {
    int pulse = angle_to_pulse_width(angle);
    if (gpioServo(gpio, pulse) != 0) {
        fprintf(stderr, "Error: Failed to set servo on GPIO %d to angle %d\n", gpio, angle);
        return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, handle_signal);

    int pan_angle = NEUTRAL_ANGLE;
    int tilt_angle = NEUTRAL_ANGLE;

    while (keep_running) {
        int input = getchar();
        if (input == EOF) break;

        switch (input) {
            case 'w':
                pan_angle = (pan_angle + 5 > MAX_ANGLE) ? MAX_ANGLE : pan_angle + 5;
                break;
            case 's':
                pan_angle = (pan_angle - 5 < MIN_ANGLE) ? MIN_ANGLE : pan_angle - 5;
                break;
            case 'a':
                tilt_angle = (tilt_angle + 5 > MAX_ANGLE) ? MAX_ANGLE : tilt_angle + 5;
                break;
            case 'd':
                tilt_angle = (tilt_angle - 5 < MIN_ANGLE) ? MIN_ANGLE : tilt_angle - 5;
                break;
            case 'q':
                set_servo_angle(PAN_SERVO_PIN, NEUTRAL_ANGLE);
                set_servo_angle(TILT_SERVO_PIN, NEUTRAL_ANGLE);
                keep_running = 0;
                break;
            default:
                fprintf(stderr, "Invalid input '%c'. Use w/s/a/d/q.\n", input);
                break;
        }

        if (set_servo_angle(PAN_SERVO_PIN, pan_angle) != 0 ||
            set_servo_angle(TILT_SERVO_PIN, tilt_angle) != 0) {
            fprintf(stderr, "Error: Failed to set servo angles\n");
            keep_running = 0;
        }

        gpioDelay(DELAY_MS * 1000);
    }

    set_servo_angle(PAN_SERVO_PIN, NEUTRAL_ANGLE);
    set_servo_angle(TILT_SERVO_PIN, NEUTRAL_ANGLE);
    gpioTerminate();
    return 0;
}

