}

int read_cpu_temp() {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    return temp_milli / 1000;
}

int read_cpu_usage() {
    FILE *fp = fopen(STAT_FILE, "r");
    if (fp == NULL) {
        perror("Error opening CPU usage file");
        return -1;
    }

    char buffer[128];
    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error reading CPU usage from file\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    if (sscanf(buffer, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error parsing CPU usage data\n");
        return -1;
    }

    unsigned long long total_time = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    unsigned long long idle_time = idle + iowait;

    if (total_time == 0) {
        return 0;
    }

    unsigned long long cpu_usage = (total_time - idle_time) * 100 / total_time;
    return (int)cpu_usage;
}

void ssd1306_send_command(unsigned char command) {
    char buf[2] = {SSD1306_COMMAND, command};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error sending command 0x%02X\n", command);
        exit(1);
    }
}

void ssd1306_send_data(unsigned char data) {
    char buf[2] = {SSD1306_DATA, data};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error sending data 0x%02X\n", data);
        exit(1);
    }
}

