#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define OLED_WIDTH 128
#define OLED_HEIGHT 64
#define OLED_I2C_ADDR 0x3C
#define OLED_I2C_BUS 1

#define SSD1306_CONTROL 0x00
#define SSD1306_COMMAND 0x01
#define SSD1306_DATA 0x40

#define SSD1306_DISPLAYOFF 0xAE
#define SSD1306_DISPLAYON 0xAF
#define SSD1306_NORMALDISPLAY 0xA5
#define SSD1306_FLIPHORIZONTAL 0xD3
#define SSD1306_FLIPVERTICAL 0xDB
#define SSD1306_STARTLINE 0x40
#define SSD1306_CHARGEPUMP 0x8D
#define SSD1306_MEMORYMODE 0x00
#define SSD1306_SEGREMAP 0x01
#define SSD1306_COMSCANDEC 0x14

#define SSD1306_SETDISPLAYOFFSET 0xD3
#define SSD1306_SETSTARTLINE 0x40

#define SSD1306_INIT1 0xA1
#define SSD1306_INIT2 0xC8

#define SSD1306_CLEARDISPLAY 0x01
#define SSD1306_INVERTDISPLAY 0x02
#define SSD1306_NORMEMPHASIS 0x07
#define SSD1306_SHOWCONTRAST 0x08
#define SSD1306_PRECHARGE 0xD9
#define SSD1306_PHASE1 0x10
#define SSD1306_PHASE2 0x20
#define SSD1306_PHASE3 0x14
#define SSD1306_MODE1 0xA0
#define SSD1306_MODE2 0xA1
#define SSD1306_VCOMDETECT 0xDB
#define SSD1306_DISPLAYALLON_RESUME 0x07

#define SSD1306_COLUMN_START 0x00
#define SSD1306_COLUMN_END 0x0F
#define SSD1306_PAGE_START 0x00
#define SSD1306_PAGE_END 0x07

#define SSD1306_SET_COLUMN_RANGE 0x21
#define SSD1306_SET_DISPLAY_OFFSET 0x21
#define SSD1306_SET_START_LINE 0x40

#define SSD1306_DISPLAY_BUFFER_SIZE (OLED_WIDTH * (OLED_HEIGHT / 8))

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define STAT_FILE "/proc/stat"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int read_cpu_temp() {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    return temp_milli / 1000;
}

int read_cpu_usage() {
    FILE *fp = fopen(STAT_FILE, "r");
    if (fp == NULL) {
        perror("Error opening CPU usage file");
        return -1;
    }

    char buffer[128];
    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error reading CPU usage from file\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    if (sscanf(buffer, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error parsing CPU usage data\n");
        return -1;
    }

    unsigned long long total_time = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    unsigned long long idle_time = idle + iowait;

    if (total_time == 0) {
        return 0;
    }

    unsigned long long cpu_usage = (total_time - idle_time) * 100 / total_time;
    return (int)cpu_usage;
}

void ssd1306_send_command(unsigned char command) {
    char buf[2] = {SSD1306_COMMAND, command};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error sending command 0x%02X\n", command);
        exit(1);
    }
}

void ssd1306_send_data(unsigned char data) {
    char buf[2] = {SSD1306_DATA, data};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error sending data 0x%02X\n", data);
        exit(1);
    }
}

