#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define PULSES_PER_LITER 450.0
#define LOG_INTERVAL_SEC 1
#define UPDATE_INTERVAL_SEC 10

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int lcd_init() {
    if (i2cWriteByte(i2c_handle, 0x33) < 0) return -1;
    if (i2cWriteByte(i2c_handle, 0x32) < 0) return -1;
    if (i2cWriteByte(i2c_handle, 0x28) < 0) return -1;
    if (i2cWriteByte(i2c_handle, 0x0C) < 0) return -1;
    if (i2cWriteByte(i2c_handle, 0x06) < 0) return -1;
    if (i2cWriteByte(i2c_handle, 0x01) < 0) return -1;
    return 0;
}

void lcd_clear() {
    if (i2c_handle < 0) return;
    if (i2cWriteByte(i2c_handle, 0x01) < 0) return;
    usleep(2000);
}

void lcd_set_cursor(int col, int row) {
    if (i2c_handle < 0) return;
    int addr = (row == 0) ? 0x80 + col : 0xC0 + col;
    if (i2cWriteByte(i2c_handle, addr) < 0) return;
}

void lcd_print(const char *str) {
    if (i2c_handle < 0) return;
    for (int i = 0; str[i] != '\0'; i++) {
        if (i2cWriteByte(i2c_handle, (unsigned char)str[i]) < 0) return;
    }
}

void lcd_update() {
    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_print("Flow:");
    lcd_set_cursor(0, 1);
    char buf[17];
    snprintf(buf, sizeof(buf), "Rate: %.2f L/min | Vol: %.2f L", flow_rate, total_volume);
    lcd_print(buf);
}

void flow_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)tick;
    if (level == 1) {
        pulses++;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
