#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define LCD_ADDR             0x27
#define LCD_I2C_BUS          1
#define LCD_WIDTH            16
#define LCD_CHR              1
#define LCD_CMD              0
#define LCD_LINE_1           0x80
#define LCD_LINE_2           0xC0
#define LCD_BACKLIGHT        0x08
#define LCD_ENABLE           0x04
#define LCD_RS               0x01
#define LCD_STROBE           0x02
#define LCD_DELAY_US         5000

#define ANEMOMETER_GPIO       17
#define SPI_CHANNEL           0
#define SPI_SPEED_HZ         1000000
#define SPI_MODE             0
#define SPI_BITS             8
#define SAMPLE_PERIOD_US     500000
#define PULSES_PER_SAMPLE    10
#define WIND_SPEED_PER_PULSE 0.5f
#define WIND_VANE_MIN        0
#define WIND_VANE_MAX        359
#define ADC_MAX              1023

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (i2cWriteByte(fd, byte) < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int lcd_strobe(int fd, uint8_t data) {
    uint8_t reg = data | LCD_STROBE;
    if (i2c_write_byte(fd, reg) < 0) return -1;
    gpioDelay(1);
    reg |= LCD_ENABLE;
    if (i2c_write_byte(fd, reg) < 0) return -1;
    gpioDelay(1);
    return 0;
}

static int lcd_byte(int fd, uint8_t bits, uint8_t mode) {
    uint8_t high = (bits & 0xF0) | mode | LCD_BACKLIGHT;
    uint8_t low  = ((bits << 4) & 0xF0) | mode | LCD_BACKLIGHT;
    if (lcd_strobe(fd, high) < 0) return -1;
    if (lcd_strobe(fd, low) < 0) return -1;
    return 0;
}

static int lcd_init(int fd) {
    gpioDelay(50000);
    if (i2c_write_byte(fd, 0x33) < 0) return -1;
    if (i2c_write_byte(fd, 0x32) < 0) return -1;
    if (i2c_write_byte(fd, 0x28) < 0) return -1;
    if (i2c_write_byte(fd, 0x0C) < 0) return -1;
    if (i2c_write_byte(fd, 0x06) < 0) return -1;
    if (i2c_write_byte(fd, 0x01) < 0) return -1;
    return 0;
}

static int lcd_clear(int fd) {
    if (lcd_byte(fd, 0x01, LCD_CMD) < 0) return -1;
    gpioDelay(2000);
    return 0;
}

static int lcd_set_cursor(int fd, uint8_t col, uint8_t row) {
    uint8_t addr = (row == 0) ? (0x80 + col) : (0xC0 + col);
    if (lcd_byte(fd, addr, LCD_CMD) < 0) return -1;
    return 0;
}

static int lcd_print(int fd, const char *text) {
    while (*text) {
        if (lcd_byte(fd, (uint8_t)*text++, LCD_CHR) < 0) return -1;
    }
    return 0;
}

static int lcd_write_line(int fd, int line, const char *text) {
    if (lcd_set_cursor(fd, 0, line) < 0) return -1;
    return lcd_print(fd, text);
}

static int lcd_write_line_int(int fd, int line, int value) {
    char buf[16];
    snprintf(buf, sizeof(buf), "%d", value);
    return lcd_write_line(fd, line, buf);
}

static int lcd_write_line_float(int fd, int line, float value) {
    char buf[16];
    snprintf(buf, sizeof(buf), "%.1f", value);
    return lcd_write_line(fd, line, buf);
}

static int lcd_write_line_direction(int fd, int line, float direction) {
    char buf[16];
    snprintf(buf, sizeof(buf), "  %5.1f", direction);
    return lcd_write_line(fd, line, buf);
}

static int lcd_write_line_speed(int fd, int line, float speed) {
    char buf[16];
    snprintf(buf, sizeof(buf), "spd: %5.1f", speed);
    return lcd_write_line(fd, line, buf);
}

static int lcd_write_line_error(int fd, int line, const char *msg) {
    char buf[64];
    snprintf(buf, sizeof(buf), "ERR: %s", msg);
    return lcd_write_line(fd, line, buf);
}

static int lcd_write_line_info(int fd, int line, const char *msg) {
    char buf[64];
    snprintf(buf, sizeof(buf), "Info: %s", msg);
    return lcd_write_line(fd, line, buf);
}

static int lcd_clear_all(int fd) {
    if (lcd_byte(fd, 0x01, LCD_CMD) < 0) return -1;
    gpioDelay(2000);
    return 0;
}

static int lcd_init_failed(void) {
    fprintf(stderr, "LCD initialization failed.\n");
    return -1;
}

static int spi_init(void) {
    char spi_dev[32];
    snprintf(spi_dev, sizeof(spi_dev), "/dev/spidev%d.%d", SPI_CHANNEL, SPI_SPEED_HZ);
    g_spi_fd = open(spi_dev, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", spi_dev, strerror(errno));
        return -1;
    }
    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }
    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }
    return 0;
}

static int mcp3008_read(int fd, int channel) {
    if (channel < 0 || channel > 7) return -1;
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float map_adc_to_angle(int adc) {
    if (adc < 0) adc = 0;
    if (adc > ADC_MAX) adc = ADC_MAX;
    return (float)adc / (float)ADC_MAX * (float)(WIND_VANE_MAX - WIND_VANE_MIN) + WIND_VANE_MIN;
}

static void anemometer_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    static int pulse_count = 0;
    pulse_count++;
}

static void cleanup(void) {
    if (g_i2c_fd >= 0) {
        lcd_clear_all(g_i2c_fd);
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return 1;
    }

    g_i2c_fd = i2cOpen(LCD_I2C_BUS, LCD_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                LCD_I2C_BUS, LCD_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (lcd_init(g_i2c_fd) < 0) {
        fprintf(stderr, "LCD initialization failed.\n");
        cleanup();
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(ANEMOMETER_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input.\n", ANEMOMETER_GPIO);
        cleanup();
        return 1;
    }
    if (gpioSetPullUpDown(ANEMOMETER_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d.\n", ANEMOMETER_GPIO);
        cleanup();
        return 1;
    }
    if (gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, anemometer_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR on GPIO%d.\n", ANEMOMETER_GPIO);
        cleanup();
        return 1;
    }

    printf("Wind monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int pulses = 0;
        float wind_speed = 0.0f;
        float wind_direction = 0.0f;
        int adc_value = 0;
        int adc_stuck = 0;

        for (int i = 0; i < PULSES_PER_SAMPLE && g_running; i++) {
            gpioDelay(SAMPLE_PERIOD_US / PULSES_PER_SAMPLE);
            pulses++;
        }

        if (pulses > 0) {
            wind_speed = (float)pulses * WIND_SPEED_PER_PULSE;
        }

        adc_value = mcp3008_read(g_spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed; skipping sample.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (adc_value == 0 || adc_value == ADC_MAX) {
            fprintf(stderr, "ADC stuck at %d (sensor absent or bus error).\n", adc_value);
            adc_stuck = 1;
        }

        if (!adc_stuck) {
            wind_direction = map_adc_to_angle(adc_value);
        }

        lcd_clear_all(g_i2c_fd);
        lcd_write_line_int(g_i2c_fd, 0, (int)wind_speed);
        lcd_write_line_direction(g_i2c_fd, 1, wind_direction);

        if (adc_stuck) {
            lcd_write_line_error(g_i2c_fd, 2, "ADC error");
        } else {
            lcd_write_line_info(g_i2c_fd, 2, "OK");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

