#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define LCD_WIDTH 16
#define PULSES_PER_LITER 7.5
#define MEASUREMENT_INTERVAL_SEC 1
#define SENSOR_TIMEOUT_SEC 60

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

void lcd_write_4bits(int handle, unsigned char data) {
    if (i2cWriteByteData(handle, 0, data) < 0) {
        log_message("I2C write failed");
    }
}

void lcd_send_command(int handle, unsigned char cmd) {
    lcd_write_4bits(handle, cmd | 0x0C);
    lcd_write_4bits(handle, (cmd << 4) | 0x0C);
}

void lcd_send_data(int handle, unsigned char data) {
    lcd_write_4bits(handle, (data & 0xF0) | 0x0C);
    lcd_write_4bits(handle, ((data << 4) & 0xF0) | 0x0C);
}

void lcd_init(int handle) {
    i2c_handle = handle;
    gpioDelay(50000);
    lcd_send_command(handle, 0x33);
    lcd_send_command(handle, 0x32);
    lcd_send_command(handle, 0x28);
    lcd_send_command(handle, 0x0C);
    lcd_send_command(handle, 0x06);
    lcd_send_command(handle, 0x01);
    gpioDelay(2000);
}

void lcd_clear(int handle) {
    lcd_send_command(handle, 0x01);
    gpioDelay(2000);
}

void lcd_set_cursor(int handle, int col, int row) {
    unsigned char addr = (col == 0) ? 0x00 : 0x40;
    lcd_send_command(handle, 0x80 | (row + (col == 1) ? 0x40 : 0x00));
}

void lcd_print(int handle, const char *text) {
    for (int i = 0; text[i] != '\0'; i++) {
        lcd_send_data(handle, (unsigned char)text[i]);
    }
}

void lcd_display_flow_rate(int handle, float flow_rate) {
    char line1[17];
    char line2[17];
    snprintf(line1, sizeof(line1), "Flow Rate:");
    snprintf(line2, sizeof(line2), "%.2f L/min", flow_rate);
    lcd_set_cursor(handle, 0, 0);
    lcd_print(handle, line1);
    lcd_set_cursor(handle, 0, 1);
    lcd_print(handle, line2);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    log_file = fopen("flow_monitor.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        log_message("Failed to set GPIO mode");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(FLOW_SENSOR_GPIO, pulse_counter) != 0) {
        log_message("Failed to set alert function");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    lcd_init(I2C_BUS);
    log_message("Flow monitor started");

    int pulse_count = 0;
    time_t last_pulse_time = time(NULL);
    int sensor_active = 0;

    while (running) {
        sleep(MEASUREMENT_INTERVAL_SEC);
        if (!running) break;

        time_t current_time = time(NULL);
        int elapsed_sec = (int)(current_time - last_pulse_time);

        if (elapsed_sec > SENSOR_TIMEOUT_SEC) {
            if (sensor_active) {
                log_message("Warning: No pulses for 60 seconds, sensor may be absent");
            }
            pulse_count = 0;
            sensor_active = 0;
        }

        float flow_rate = 0.0;
        if (pulse_count > 0) {
            float liters = (float)pulse_count / PULSES_PER_LITER;
            flow_rate = liters / (MEASUREMENT_INTERVAL_SEC / 60.0);
        }

        lcd_clear(I2C_BUS);
        lcd_display_flow_rate(I2C_BUS, flow_rate);

        last_pulse_time = current_time;
        if (pulse_count > 0) {
            sensor_active = 1;
        }
    }

    log_message("Shutting down");
    if (i2c_handle >= 0) {
        lcd_clear(i2c_handle);
        gpioDelay(100000);
        i2cClose(i2c_handle);
    }
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

