#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define SCAN_DELAY_US 800

/* BCM GPIO numbers for rows (anodes) and columns (cathodes) */
static const unsigned int row_pins[NUM_ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
static const unsigned int col_pins[NUM_COLS] = {5, 6, 12, 13, 19, 16, 26, 20};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *row_lines[NUM_ROWS];
static struct gpiod_line *col_lines[NUM_COLS];
static volatile sig_atomic_t keep_running = 1;

static void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

static void release_resources(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (row_lines[i]) {
            gpiod_line_release(row_lines[i]);
            row_lines[i] = NULL;
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
            col_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int setup_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open gpiochip0\n");
        return -1;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Error: Failed to get row line %u\n", row_pins[i]);
            return -1;
        }
        if (gpiod_line_request_output(row_lines[i], "led_matrix", 0) < 0) {
            fprintf(stderr, "Error: Failed to request row line %u as output\n", row_pins[i]);
            return -1;
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Error: Failed to get column line %u\n", col_pins[i]);
            return -1;
        }
        if (gpiod_line_request_output(col_lines[i], "led_matrix", 1) < 0) {
            fprintf(stderr, "Error: Failed to request column line %u as output\n", col_pins[i]);
            return -1;
        }
    }

    return 0;
}

static void scan_display(int row_index) {
    for (int col = 0; col < NUM_COLS; col++) {
        if (gpiod_line_set_value(col_lines[col], 0) < 0) {
            fprintf(stderr, "Error: Failed to set column %d LOW\n", col);
            return;
        }
        if (gpiod_line_set_value(row_lines[row_index], 1) < 0) {
            fprintf(stderr, "Error: Failed to set row %d HIGH\n", row_index);
            return;
        }
        usleep(SCAN_DELAY_US);
        if (gpiod_line_set_value(col_lines[col], 1) < 0) {
            fprintf(stderr, "Error: Failed to set column %d HIGH\n", col);
            return;
        }
        if (gpiod_line_set_value(row_lines[row_index], 0) < 0) {
            fprintf(stderr, "Error: Failed to set row %d LOW\n", row_index);
            return;
        }
        usleep(SCAN_DELAY_US);
    }
}

static void left_wave(void) {
    for (int i = 0; i < NUM_ROWS && keep_running; i++) {
        scan_display(i);
    }
}

static void right_wave(void) {
    for (int i = NUM_ROWS - 1; i >= 0 && keep_running; i--) {
        scan_display(i);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (setup_gpio() < 0) {
        release_resources();
        return 1;
    }

    while (keep_running) {
        left_wave();
        usleep(500000);
        if (!keep_running) break;
        right_wave();
        usleep(500000);
    }

    release_resources();
    return 0;
}

