/*
 * VL53L3CX Time-of-Flight Multi-Target Sensor Reader
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio (I2C)
 * Sensor:  STMicroelectronics VL53L3CX (I2C addr 0x29, bus 1)
 *
 * NOTE: The VL53L3CX requires a proprietary ST Ultra Lite Driver (ULD)
 * firmware download for proper operation.  This stub implements the
 * I2C communication layer and application logic, but leaves the
 * complex ULD firmware download and sensor-specific initialization
 * as a placeholder.  A real deployment must replace the
 * __vl53l3cx_init() stub with the ST ULD initialization sequence.
 *
 * Build:  gcc -Wall -Wextra -O2 -o vl53l3cx_reader vl53l3cx_reader.c -lpigpio -lrt
 * Run:    sudo ./vl53l3cx_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L3CX_ADDR        0x29
#define SAMPLE_PERIOD_US     100000   /* 100 ms */
#define MAX_TARGETS          10
#define MAX_DISTANCE_MM      4000

/*
 * VL53L3CX ULD firmware download / initialization sequence (stubbed).
 * A real deployment must replace this with the ST ULD initialization
 * flow, which includes setting the sensor mode, starting ranging,
 * and configuring the output data stream.
 */
static int vl53l3cx_init(int handle)
{
    /*
     * Placeholder: write a small calibration data block to the
     * sensor to trigger firmware download and initialization.
     * In practice, this involves writing a 16-byte block to register
     * 0x00, then reading back the 16-byte calibration word at 0x00.
     */
    uint8_t init_data[16] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08,
                              0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F, 0x10};

    if (i2cWriteDevice(handle, (char *)init_data, sizeof(init_data)) < 0) {
        fprintf(stderr, "[ERROR] I2C write failed during VL53L3CX init.\n");
        return -1;
    }

    /* Allow firmware download to complete (typical ~10 ms). */
    gpioDelay(10000);

    /*
     * Read back the 16-byte calibration word from register 0x00.
     * This is a placeholder; the real ULD init includes a more
     * elaborate sequence of register writes and reads.
     */
    uint8_t cal_word[16];
    if (i2cReadDevice(handle, (char *)cal_word, sizeof(cal_word)) != (int)sizeof(cal_word)) {
        fprintf(stderr, "[ERROR] I2C read failed during VL53L3CX init.\n");
        return -1;
    }

    printf("[INFO] VL53L3CX firmware download and initialization complete.\n");
    return 0;
}

/*
 * Read distance for a single target.
 * Returns distance in mm on success, or -1 on error.
 */
static int read_distance(int handle, uint8_t target_id)
{
    /*
     * Placeholder: write the target index to register 0x00, then
     * read the 16-bit distance word from register 0x01.
     * In practice, the ULD flow includes setting the measurement
     * mode, starting a single-shot ranging cycle, and reading the
     * result from a dedicated result register.
     */
    uint8_t reg = 0x00;
    uint8_t data[2];

    if (i2cWriteDevice(handle, (char *)&reg, 1) < 0) {
        fprintf(stderr, "[ERROR] I2C write (target select) failed for target %u.\n", target_id);
        return -1;
    }

    if (i2cReadDevice(handle, (char *)data, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C read (distance) failed for target %u.\n", target_id);
        return -1;
    }

    return (data[0] << 8) | data[1];
}

/*
 * Log distance data with an ISO-8601 timestamp.
 */
static void log_data(const int distances[], int num_targets)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("%s - Targets: %d\n", timestamp, num_targets);
    for (int i = 0; i < num_targets; i++) {
        printf("  Target %d: %d mm\n", i + 1, distances[i]);
    }
    fflush(stdout);
}

/* ------------------------------- Signal Handler --------------------------- */
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------- Main ------------------------------------- */
int main(void)
{
    int handle = -1;
    int distances[MAX_TARGETS];
    int num_targets = 0;
    int rc = EXIT_FAILURE;

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to VL53L3CX */
    handle = i2cOpen(I2C_BUS, VL53L3CX_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, VL53L3CX_ADDR, handle);
        goto cleanup_gpio;
    }

    /* Initialize the sensor */
    if (vl53l3cx_init(handle) != 0) {
        fprintf(stderr, "[ERROR] VL53L3CX initialization failed. Sensor may be absent or bus error.\n");
        goto cleanup_i2c;
    }

    printf("[INFO] VL53L3CX reader started. Sampling every %d ms.\n",
           SAMPLE_PERIOD_US / 1000);
    fflush(stdout);

    /* Main sampling loop */
    while (running) {
        num_targets = 0;

        for (int i = 0; i < MAX_TARGETS; i++) {
            int dist = read_distance(handle, (uint8_t)i);
            if (dist >= 0) {
                distances[num_targets++] = dist;
            } else {
                fprintf(stderr, "[WARN] Failed to read distance for target %d.\n", i + 1);
            }
        }

        if (num_targets > 0) {
            log_data(distances, num_targets);
        } else {
            printf("[INFO] No valid targets detected this cycle.\n");
        }

        /* Sleep for the sample period (microseconds) */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\n[INFO] Shutting down gracefully...\n");
    rc = EXIT_SUCCESS;

cleanup_i2c:
    if (handle >= 0) {
        i2cClose(handle);
    }
cleanup_gpio:
    gpioTerminate();

    return rc;
}

