#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define MLX75031_ADDR 0x4C
#define DISTANCE_REG 0x0D
#define LOG_FILE "depth_log.csv"
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, MLX75031_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, MLX75031_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_distance(uint16_t *distance) {
    char buf[2];
    int rc;

    rc = i2cWriteByte(i2c_handle, DISTANCE_REG);
    if (rc < 0) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n",
                DISTANCE_REG, strerror(errno));
        return -1;
    }

    gpioDelay(1000);

    rc = i2cReadDevice(i2c_handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error reading 2 bytes from register 0x%02X: %s\n",
                DISTANCE_REG, strerror(errno));
        return -1;
    }

    *distance = ((uint16_t)(buf[0] << 8)) | (uint16_t)(buf[1] & 0xFF);
