#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1145_ADDR 0x60
#define I2C_BUS 1

#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_PS_LED21 0x0F
#define SI1145_REG_PS_LED3 0x10
#define SI1145_REG_PARAM_WR 0x17
#define SI1145_REG_COMMAND 0x30
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_PS1_DATA0 0x18
#define SI1145_REG_PS1_DATA1 0x19

#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_PS_FORCE 0x07
#define SI1145_CMD_PSALS_FORCE 0x05
#define SI1145_CMD_PARAM_QUERY 0x80
#define SI1145_CMD_PARAM_SET 0xA0
#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_PSALS_AUTO 0x0D

#define SI1145_PART_ID 0x45
#define SI1145_HW_KEY_VAL 0x17

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int si1145_write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, val, rc);
    }
    return rc;
}

static int si1145_read_reg(uint8_t reg) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
    }
    return rc;
}

static int si1145_read_word(uint8_t reg_lsb) {
    int lsb = si1145_read_reg(reg_lsb);
    if (lsb < 0) return -1;
    int msb = si1145_read_reg(reg_lsb + 1);
    if (msb < 0) return -1;
    return (lsb | (msb << 8));
}

static int si1145_init(void) {
    int part_id = si1145_read_reg(SI1145_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read PART_ID\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }

    if (si1145_write_reg(SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) return -1;
    gpioDelay(10000);

    if (si1145_write_reg(SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) return -1;

    if (si1145_write_reg(SI1145_REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (si1145_write_reg(SI1145_REG_MEAS_RATE1, 0x00) < 0) return -1;

    if (si1145_write_reg(SI1145_REG_PS_LED21, 0x0F) < 0) return -1;
    if (si1145_write_reg(SI1145_REG_PS_LED3, 0x00) < 0) return -1;

    if (si1145_write_reg(SI1145_REG_PARAM_WR, 0x00) < 0) return -1;

    if (si1145_write_reg(SI1145_REG_COMMAND, SI1145_CMD_PSALS_AUTO) < 0) return -1;

    return 0;
}

static int si1145_read_data(uint16_t *proximity, uint16_t *ambient_light) {
    if (si1145_write_reg(SI1145_REG_COMMAND, SI1145_CMD_PSALS_FORCE) < 0) return -1;
    gpioDelay(10000);

    int ps1 = si1145_read_word(SI1145_REG_PS1_DATA0);
    if (ps1 < 0) return -1;

    int als_vis = si1145_read_word(SI1145_REG_ALS_VIS_DATA0);
    if (als_vis < 0) return -1;

    *proximity = (uint16_t)ps1;
    *ambient_light = (uint16_t)als_vis;
    return 0;
}

static void log_data(uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, proximity, ambient_light);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (si1145_init() != 0) {
        fprintf(stderr, "Si1145 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    uint16_t proximity, ambient_light;

    while (running) {
        if (si1145_read_data(&proximity, &ambient_light) == 0) {
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
