#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define WATERING_THRESHOLD_CM 15.0
#define POLL_INTERVAL_SEC 60
#define ECHO_TIMEOUT_NS 30000000L
#define TRIGGER_PULSE_US 10
#define CONSUMER "plant-watering-hc-sr04"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", ts, msg);
    fflush(log_file);
}

static void log_distance(float distance) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: Distance: %.2f cm\n", ts, distance);
    fflush(log_file);
}

static void log_error(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: ERROR: %s\n", ts, msg);
    fflush(log_file);
}

static void log_watering_reminder(void) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: Time to water the plant!\n", ts);
    fflush(log_file);
}

static long long elapsed_ns(const struct timespec *start, const struct timespec *end) {
    return (long long)(end->tv_sec - start->tv_sec) * 1000000000LL +
           (end->tv_nsec - start->tv_nsec);
}

static float measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    struct timespec start, end;
    struct gpiod_line_event event;
    struct gpiod_line_request_config trig_cfg, echo_cfg;
    int ret;

    /* Ensure trigger is low */
    ret = gpiod_line_request_output(trig, CONSUMER, 0);
    if (ret < 0) {
        log_error("Failed to request trigger line as output");
        return -1.0f;
    }
    gpiod_line_set_value(trig, 0);

    /* 10 us trigger pulse */
    struct timespec trig_start, trig_end;
    clock_gettime(CLOCK_MONOTONIC, &trig_start);
    gpiod_line_set_value(trig, 1);
    clock_gettime(CLOCK_MONOTONIC, &trig_end);
    long long trig_us = elapsed_ns(&trig_start, &trig_end);
    if (trig_us < 10000) {
        log_error("Trigger pulse too short");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout 30 ms) */
    clock_gettime(CLOCK_MONOTONIC, &start);
    for (;;) {
        ret = gpiod_line_event_wait(echo, &((struct timespec){.tv_sec = 0, .tv_nsec = ECHO_TIMEOUT_NS}));
        if (ret < 0) {
            log_error("Timeout waiting for echo rising edge");
            return -1.0f;
        }
        if (ret == 0) break; /* timeout */
        if (gpiod_line_event_read(echo, &event) < 0) {
            log_error("Failed to read echo event");
            return -1.0f;
        }
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) break;
    }

    clock_gettime(CLOCK_MONOTONIC, &start);
    /* Wait for echo falling edge (timeout 30 ms) */
    for (;;) {
        ret = gpiod_line_event_wait(echo, &((struct timespec){.tv_sec = 0, .tv_nsec = ECHO_TIMEOUT_NS}));
        if (ret < 0) {
            log_error("Timeout waiting for echo falling edge");
            return -1.0f;
        }
        if (ret == 0) break; /* timeout */
        if (gpiod_line_event_read(echo, &event) < 0) {
            log_error("Failed to read echo event");
            return -1.0f;
        }
        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) break;
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    long long pulse_ns = elapsed_ns(&start, &end);
    if (pulse_ns == 0) {
        log_error("Zero pulse duration");
        return -1.0f;
    }

    float distance = (float)pulse_ns / 1000000000.0f * SPEED_OF_SOUND / 2.0f;
    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Distance out of range: %.2f cm", distance);
        log_error(msg);
        return -1.0f;
    }
    return distance;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    log_message("Program started");

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_error("Failed to open gpiochip0");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        log_error("Failed to get GPIO lines");
        goto cleanup;
    }

    trig_cfg.consumer = CONSUMER;
    trig_cfg.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    echo_cfg.consumer = CONSUMER;
    echo_cfg.request_type = GPIOD_LINE_REQUEST_EVENT_RISING_FALLING;
    echo_cfg.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN;

    ret = gpiod_line_request(trig, &trig_cfg, 0);
    if (ret < 0) {
        log_error("Failed to request trigger line");
        goto cleanup;
    }
    ret = gpiod_line_request(echo, &echo_cfg, 0);
    if (ret < 0) {
        log_error("Failed to request echo line");
        goto cleanup;
    }

    log_message("GPIO initialized");

    while (program_running) {
        float distance = measure_distance(trig, echo);

        if (distance >= 0.0f) {
            log_distance(distance);
            if (distance < WATERING_THRESHOLD_CM) {
                log_watering_reminder();
            }
        } else {
            log_error("Measurement failed");
        }

        /* Sleep in 1-second increments to allow signal handling */
        for (int i = 0; i < POLL_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    if (log_file) {
        log_message("Program exiting");
        fclose(log_file);
    }
    return EXIT_SUCCESS;
}

