#include <linux/i2c.h>

#define SI1182_ADDR        0x5A
#define SI1182_REG_PART_ID 0x00
#define SI1182_REG_MEAS_RATE0 0x08
#define SI1182_REG_COMMAND 0x47
#define SI1182_REG_PS_DATA0 0x24
#define SI1182_REG_PS_DATA1 0x25

#define SI1182_PART_ID_VAL 0x82
#define SI1182_CMD_RESET   0x01
#define SI1182_CMD_START   0x02

#define I2C_BUS "/dev/i2c-1"
#define CSV_FILE "heartrate.csv"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *csv_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    int r = i2c_smbus_read_byte_data(fd, reg);
    if (r < 0) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint8_t)r;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    int r = i2c_smbus_write_byte_data(fd, reg, val);
    if (r < 0) {
        fprintf(stderr, "I2C write reg 0x%02X val 0x%02X failed: %s\n", reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16_le(int fd, uint8_t reg, uint16_t *val) {
    int r = i2c_smbus_read_word_data(fd, reg);
    if (r < 0) {
        fprintf(stderr, "I2C read16 reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)r;
    return 0;
}

static int init_si1182(int fd) {
    uint8_t part_id = 0;
    if (i2c_read_reg8(fd, SI1182_REG_PART_ID, &part_id) < 0) {
        return -1;
    }
    if (part_id != SI1182_PART_ID_VAL) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1182_PART_ID_VAL);
        return -1;
    }
    printf("Si1182 detected (PART_ID=0x%02X)\n", part_id);

    if (i2c_write_reg8(fd, SI1182_REG_COMMAND, SI1182_CMD_RESET) < 0) {
        return -1;
    }
    usleep(10000);

    if (i2c_write_reg8(fd, SI1182_REG_MEAS_RATE0, 0x0A) < 0) {
        return -1;
    }
    if (i2c_write_reg8(fd, SI1182_REG_COMMAND, SI1182_CMD_START) < 0) {
        return -1;
    }
    usleep(10000);
    return 0;
}

static int read_proximity(int fd, uint16_t *prox) {
    return i2c_read_reg16_le(fd, SI1182_REG_PS_DATA0, prox);
}

static int log_data(FILE *fp, uint16_t prox, int bpm) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t == NULL) {
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    if (fprintf(fp, "%s,%d\n", ts, bpm) < 0) {
        return -1;
    }
    if (fflush(fp) != 0) {
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open(" I2C_BUS ")");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(i2c_fd);
        return 1;
    }

    if (init_si1182(i2c_fd) < 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    csv_fp = fopen(CSV_FILE, "a");
    if (csv_fp == NULL) {
        perror("fopen(" CSV_FILE ")");
        close(i2c_fd);
        return 1;
    }

    printf("Logging to %s. Press Ctrl+C to stop.\n", CSV_FILE);

    while (running) {
        uint16_t prox = 0;
        if (read_proximity(i2c_fd, &prox) < 0) {
            fprintf(stderr, "Proximity read failed; skipping sample\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        int bpm = (int)((prox * 10) / 100);
        if (log_data(csv_fp, prox, bpm) < 0) {
            fprintf(stderr, "CSV write failed\n");
        }

        printf("Proximity: %u, BPM: %d\n", prox, bpm);
        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (csv_fp) {
        fclose(csv_fp);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

