#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define CH101_ADDR     0x45
#define TRIGGER_CMD    0x01
#define MEASURE_CMD    0x02
#define READ_CMD       0x03
#define LOG_FILE       "distance_log.txt"
#define SAMPLE_US      200000   /* 200 ms between samples */
#define MEASURE_US     50000    /* 50 ms measurement wait */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single command byte to the CH101. Returns 0 on success, -1 on error. */
static int ch101_write_cmd(int handle, uint8_t cmd)
{
    if (i2cWriteByte(handle, cmd) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(0x%02X) failed\n", cmd);
        return -1;
    }
    return 0;
}

/* Read a 16-bit big-endian distance (mm) from the CH101. Returns 0 on success. */
static int ch101_read_distance(int handle, uint16_t *distance_mm)
{
    char buf[2];

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed\n");
        return -1;
    }

    *distance_mm = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* Trigger a measurement and read the result. Returns 0 on success, -1 on error. */
static int ch101_measure(int handle, uint16_t *distance_mm)
{
    if (ch101_write_cmd(handle, MEASURE_CMD) != 0)
        return -1;

    gpioDelay(MEASURE_US);

    return ch101_read_distance(handle, distance_mm);
}

/* Append a timestamped distance reading to the log file. Returns 0 on success. */
static int log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t t;
    struct tm tm_info;
    char timestamp[32];

    time(&t);
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, %u\n", timestamp, distance_mm) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush failed\n");
        return -1;
    }

    return 0;
}

int main(void)
{
    int i2c_handle = -1;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 at the CH101 default address --- */
    i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, CH101_ADDR, i2c_handle);
        goto cleanup_gpio;
    }

    /* --- Open log file in append mode --- */
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        goto cleanup_i2c;
    }

    printf("CH101 distance measurement started. Press Ctrl-C to stop.\n");
    printf("Bus %d, addr 0x%02X, logging to %s\n", I2C_BUS, CH101_ADDR, LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t distance_mm = 0;

        if (ch101_measure(i2c_handle, &distance_mm) == 0) {
            if (log_distance(log_fp, distance_mm) != 0) {
                fprintf(stderr, "[WARN] Logging failed for this sample\n");
            }
            printf("Distance: %u mm\n", distance_mm);
        } else {
            fprintf(stderr, "[WARN] Measurement failed; will retry next cycle\n");
        }

        /* Sleep 200 ms between samples (interruptible by signals) */
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down gracefully...\n");
    ret = EXIT_SUCCESS;

    /* --- Cleanup --- */
    if (log_fp != NULL) {
        fclose(log_fp);
    }
cleanup_i2c:
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
cleanup_gpio:
    gpioTerminate();

    return ret;
}

