#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ICU20201_ADDR 0x6A
#define LED_PIN 17
#define DISTANCE_THRESHOLD_CM 20.0
#define LOG_FILE "distance_log.txt"
#define SAMPLE_INTERVAL_US 100000

/* ICU-20201 register addresses (datasheet) */
#define REG_DISTANCE_MSB 0x00
#define REG_DISTANCE_LSB 0x01
#define REG_SYSTEM_CONFIG 0x02
#define REG_MODE_CONFIG 0x03

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, ICU20201_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int configure_sensor(void) {
    /* Set mode to continuous measurement (simplified; datasheet specific config may differ) */
    if (i2cWriteByteData(i2c_handle, REG_MODE_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error writing MODE_CONFIG register\n");
        return -1;
    }
    return 0;
}

static int read_distance_cm(void) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, REG_DISTANCE_MSB, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }
    /* Combine MSB and LSB (big-endian) and convert to centimeters */
    unsigned int raw = ((unsigned int)(unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    return (int)(raw / 10.0);
}

static void log_distance(int distance_cm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, Distance: %.1f cm\n", timestamp, distance_cm);
    } else {
        fprintf(fp, "(unknown time), Distance: %.1f cm\n", distance_cm);
    }
    fclose(fp);
}

static void control_led(int distance_cm) {
    if (distance_cm < DISTANCE_THRESHOLD_CM) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting LED pin mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting distance measurement. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int distance = read_distance_cm();
        if (distance >= 0) {
            log_distance(distance);
            control_led(distance);
        } else {
            fprintf(stderr, "Sensor read error; continuing.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    gpioWrite(LED_PIN, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

