        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n", WHO_AM_I_VAL, who);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int read_distance(int *distance) {
    int raw = i2cReadByteData(i2c_handle, DISTANCE_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading distance register: %d\n", raw);
        return -1;
    }
    *distance = raw;
    return 0;
}

static void log_data(int distance, int threshold) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Distance: %d mm, Threshold: %d mm\n", timestamp, distance, threshold);
    fclose(fp);
}

static void control_led(int distance, int threshold) {
    if (distance < threshold) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;

    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold value. Using default: %d mm\n", DEFAULT_THRESHOLD);
            threshold = DEFAULT_THRESHOLD;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting ICU-20201 ToF sensor monitoring. Threshold: %d mm\n", threshold);

    while (running) {
        int distance;
        if (read_distance(&distance) == 0) {
            log_data(distance, threshold);
            control_led(distance, threshold);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
            gpioWrite(LED_GPIO, 0);
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

