#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define B5L_ADDR       0x50
#define CMD_FRAME_LEN  4
#define RESP_FRAME_LEN 15
#define DIST_BYTES     11
#define NUM_SAMPLES    10
#define THRESHOLD_MM   1000
#define LOG_FILE       "intrusion_log.txt"
#define SAMPLE_DELAY_US 100000
#define CYCLE_DELAY_US  100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len) {
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_resp(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

static int read_distance(int fd, uint16_t *distance_mm) {
    uint8_t cmd[CMD_FRAME_LEN] = {0x50, 0x0A, 0x00, 0x01};
    uint8_t resp[RESP_FRAME_LEN];

    if (i2c_write_cmd(fd, cmd, CMD_FRAME_LEN) < 0)
        return -1;

    usleep(10000);

    if (i2c_read_resp(fd, resp, RESP_FRAME_LEN) < 0)
        return -1;

    if (resp[0] != B5L_ADDR) {
        fprintf(stderr, "Sensor not responding (addr mismatch: 0x%02X)\n", resp[0]);
        return -1;
    }

    *distance_mm = ((uint16_t)resp[DIST_BYTES] << 8) | resp[DIST_BYTES + 1];
    return 0;
}

static int log_intrusion(const char *filename, uint16_t distance_mm) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s - Intrusion detected! Distance: %u mm\n", ts, distance_mm);
    } else {
        fprintf(fp, "(unknown time) - Intrusion detected! Distance: %u mm\n", distance_mm);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, B5L_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                B5L_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("B5L-LD50-07050 intrusion detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t total_distance = 0;
        int valid_samples = 0;

        for (int i = 0; i < NUM_SAMPLES && g_running; i++) {
            uint16_t dist;
            if (read_distance(g_i2c_fd, &dist) == 0) {
                total_distance += dist;
                valid_samples++;
            } else {
                fprintf(stderr, "Warning: read_distance failed on sample %d\n", i);
            }
            usleep(SAMPLE_DELAY_US);
        }

        if (valid_samples > 0) {
            uint16_t avg_distance = total_distance / valid_samples;
            if (avg_distance < THRESHOLD_MM) {
                printf("Intrusion detected! Average distance: %u mm\n", avg_distance);
                if (log_intrusion(LOG_FILE, avg_distance) < 0) {
                    fprintf(stderr, "Failed to log intrusion event.\n");
                }
            }
        }

        usleep(CYCLE_DELAY_US);
    }

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

