#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L0X_ADDR        0x29
#define I2C_BUS             1

#define REG_SYSRANGE_START  0x00
#define REG_RESULT_INT_STAT 0x13
#define REG_RESULT_RANGE_STAT 0x14
#define REG_SYSTEM_INT_CLEAR 0x0B
#define REG_MODEL_ID        0xC0

#define EXPECTED_MODEL_ID   0xEE
#define RANGE_TIMEOUT_MS    100
#define LOOP_DELAY_US       500000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *out) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read failed (reg=0x%02X, len=%u): got %d, %s\n",
                reg, len, rc, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l0x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_byte(handle, REG_MODEL_ID, &model_id) != 0) {
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0x%02X)\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }
    printf("VL53L0X detected (model ID 0x%02X)\n", model_id);
    return 0;
}

static int vl53l0x_read_distance(int handle, uint16_t *distance_mm) {
    if (i2c_write_byte(handle, REG_SYSRANGE_START, 0x01) != 0) {
        return -1;
    }

    for (int i = 0; i < RANGE_TIMEOUT_MS; i++) {
        uint8_t status = 0;
        if (i2c_read_byte(handle, REG_RESULT_INT_STAT, &status) != 0) {
            return -1;
        }
        if (status & 0x01) {
            break;
        }
        gpioDelay(1000);
        if (i == RANGE_TIMEOUT_MS - 1) {
            fprintf(stderr, "Timeout waiting for measurement\n");
            return -1;
        }
    }

    uint8_t buf[2] = {0};
    if (i2c_read_block(handle, REG_RESULT_RANGE_STAT, buf, 2) != 0) {
        return -1;
    }

    *distance_mm = (uint16_t)((buf[1] << 8) | buf[0]);

    if (i2c_write_byte(handle, REG_SYSTEM_INT_CLEAR, 0x01) != 0) {
        return -1;
    }

    return 0;
}

static void print_timestamp(void) {
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];
    localtime_r(&now, &tm_info);
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("[%s] ", buf);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %s\n",
                I2C_BUS, VL53L0X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l0x_init(handle) != 0) {
        fprintf(stderr, "VL53L0X initialization failed\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L0X ranging started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance = 0;
        if (vl53l0x_read_distance(handle, &distance) == 0) {
            print_timestamp();
            printf("Distance: %u mm\n", distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: failed to read distance\n");
        }
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

