#include <pigpio.h>

#define SI1182_ADDR 0x39
#define SI1182_REG_IRQ_STATUS 0x25
#define SI1182_REG_PROX_DATA_LSB 0x2A
#define SI1182_REG_PROX_DATA_MSB 0x2B
#define SI1182_REG_CONFIG 0x18

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int si1182_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

static int si1182_read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, pigpio_error(rc));
    }
    return rc;
}

static int si1182_init(int handle) {
    /* Enable proximity mode by writing 0x01 to CONFIG register */
    if (si1182_write_reg(handle, SI1182_REG_CONFIG, 0x01) < 0) {
        return -1;
    }
    return 0;
}

static int si1182_read_proximity(int handle, uint16_t *proximity) {
    int irq_status;
    int lsb, msb;

    /* Poll IRQ status bit 0 (data-ready) */
    irq_status = si1182_read_reg(handle, SI1182_REG_IRQ_STATUS);
    if (irq_status < 0) {
        return -1;
    }
    if ((irq_status & 0x01) == 0) {
        return 1; /* no new data yet */
    }

    /* Read 16-bit proximity data */
    lsb = si1182_read_reg(handle, SI1182_REG_PROX_DATA_LSB);
    if (lsb < 0) {
        return -1;
    }

    msb = si1182_read_reg(handle, SI1182_REG_PROX_DATA_MSB);
    if (msb < 0) {
        return -1;
    }

    *proximity = ((uint16_t)msb << 8) | (uint16_t)lsb;

    /* Clear IRQ status by writing 0x01 to IRQ status register */
    if (si1182_write_reg(handle, SI1182_REG_IRQ_STATUS, 0x01) < 0) {
        return -1;
    }

    return 0;
}

int main(void) {
    int handle;
    uint16_t proximity;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at Si1182 address */
    handle = i2cOpen(1, SI1182_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n",
                SI1182_ADDR, pigpio_error(handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize Si1182 sensor */
    if (si1182_init(handle) < 0) {
        fprintf(stderr, "Si1182 initialization failed (sensor may be absent)\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si1182 proximity sensor initialized. Reading data every 500 ms...\n");

    /* Main loop */
    while (running) {
        int rc = si1182_read_proximity(handle, &proximity);

        if (rc == 0) {
            printf("Proximity: %u\n", proximity);
        } else if (rc < 0) {
            fprintf(stderr, "Error reading proximity data\n");
        }

        /* 500 ms delay (500,000 microseconds) */
        gpioDelay(500000);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    i2cClose(handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

