#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75030_ADDR  0x4C
#define DIST_REG       0x00
#define DIST_SCALE     0.125f   /* mm per LSB */
#define POLL_MS        500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit little-endian register from the MLX75030.
 * Returns 0 on success and stores the raw value in *out;
 * returns -1 on error.
 */
static int read_distance_raw(int fd, uint16_t *out)
{
    uint8_t reg = DIST_REG;
    uint8_t buf[2];

    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg pointer 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* Read two bytes: low byte first, then high byte */
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read failed (got %zd bytes): %s\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto done;

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        goto done;
    }

    /* Set the slave address */
    if (ioctl(fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                MLX75030_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Verify the sensor responds by reading the distance register */
    uint16_t dummy;
    if (read_distance_raw(fd, &dummy) != 0) {
        fprintf(stderr, "MLX75030 not responding at address 0x%02X on %s\n",
                MLX75030_ADDR, I2C_BUS);
        goto cleanup;
    }

    printf("MLX75030 detected at 0x%02X. Logging distance every %d ms.\n",
           MLX75030_ADDR, POLL_MS);
    printf("Press Ctrl-C to exit.\n");
    fflush(stdout);

    struct timespec ts = { .tv_sec = POLL_MS / 1000,
                          .tv_nsec = (POLL_MS % 1000) * 1000000L };

    while (g_running) {
        uint16_t raw;
        if (read_distance_raw(fd, &raw) == 0) {
            float distance = (float)raw * DIST_SCALE;
            printf("Distance: %6.2f mm\n", distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Read error; will retry next cycle.\n");
        }
        nanosleep(&ts, NULL);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
done:
    return rc;
}

