#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// OPT3101 I2C address
#define OPT3101_ADDR 0x44

// OPT3101 Register Addresses
#define OPT3101_REG_SYSTEM_CONFIG 0x00
#define OPT3101_REG_RESULT_DATA 0x04
#define OPT3101_REG_ERROR_STATUS 0x08

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t distance;
    uint16_t ambient_light;
    uint16_t error_flags;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Function to initialize the OPT3101 sensor
int initialize_sensor() {
    // Example configuration: Enable channel 0, set integration time, etc.
    // This is a simplified initialization. Refer to the OPT3101 datasheet for exact register values.
    uint8_t config_data[] = {0x01, 0x02, 0x03}; // Example values
    int result = i2cWriteI2CBlockData(i2c_handle, OPT3101_REG_SYSTEM_CONFIG, (char *)config_data, sizeof(config_data));
    if (result != 0) {
        fprintf(stderr, "Error writing to system config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the OPT3101 sensor
int read_sensor_data(sensor_data_t *data) {
    char buffer[2];
    int result = i2cReadI2CBlockData(i2c_handle, OPT3101_REG_RESULT_DATA, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading result data: %d\n", result);
        data->distance = 0;
        data->ambient_light = 0;
        data->error_flags = 0xFFFF; // Indicate error
        return -1;
    }

    // Combine the two bytes into a 16-bit value (big-endian)
    data->distance = ((uint16_t)buffer[0] << 8) | (uint16_t)buffer[1];
    data->ambient_light = ((uint16_t)buffer[2] << 8) | (uint16_t)buffer[3];

    // Check for errors (bit 0 of the ambient light data indicates an error)
    if (data->ambient_light & 0x0001) {
        data->error_flags = data->ambient_light;
    } else {
        data->error_flags = 0;
    }

    return 0;
}

// Function to log sensor data
void log_sensor_data(sensor_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    time_t now = ts.tv_sec;
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);

    printf("[%s.%03ld] Channel 0: Distance = %u mm, Ambient Light = %u, Error Flags = %u\n",
           buf, ts.tv_nsec / 1000000,
           data.distance,
           data.ambient_light,
           data.error_flags);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, OPT3101_ADDR, 0); // Bus 1, address 0x44, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed. Check wiring and sensor presence.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log the data
            log_sensor_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Delay for 500 milliseconds
        gpioDelay(500000); // 500 ms in microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

