#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define TRIGGER_PULSE_US  10
#define ECHO_TIMEOUT_US   200000   /* 200 ms */
#define MAX_DISTANCE_CM   38.0     /* HC-SR04 max range ~38 cm */
#define MIN_DISTANCE_CM   2.0      /* HC-SR04 min range ~2 cm */
#define SAMPLE_PERIOD_US  1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in cm using the HC-SR04.
 * Returns >= 0 on success, -1.0 on timeout, -2.0 on invalid pulse.
 *
 * The HC-SR04 operates at 5V. A 1 kOhm series resistor protects the Pi
 * GPIO input (3.3V tolerant). The echo line is active-high and idles
 * high; a falling edge marks the end of the echo burst.
 */
static double measure_distance(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_tick;
    int level;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0;
    }
    gpioDelay(5);  /* settle */

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 1) failed\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout 200 ms) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (1) {
        level = gpioRead(ECHO_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead(echo) failed\n");
            return -1.0;
        }
        if (level == 1) {
            start_tick = gpioTick();
            break;
        }
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo rising-edge timeout\n");
            return -1.0;
        }
    }

    /* Wait for echo falling edge (timeout 200 ms) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (1) {
        level = gpioRead(ECHO_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead(echo) failed\n");
            return -1.0;
        }
        if (level == 0) {
            end_tick = gpioTick();
            break;
        }
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo falling-edge timeout\n");
            return -1.0;
        }
    }

    uint32_t pulse_us = end_tick - start_tick;

    if (pulse_us == 0 || pulse_us > ECHO_TIMEOUT_US) {
        fprintf(stderr, "Error: invalid pulse duration %u us\n", pulse_us);
        return -2.0;
    }

    /* distance = (pulse_us * 0.0343) / 2  (speed of sound 343 m/s) */
    return (double)pulse_us * 0.0343 / 2.0;
}

