#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <sys/select.h>
#include <pigpio.h>

#define UART_PORT "/dev/serial0"
#define BAUD_RATE B98000
#define GPIO_LED 17
#define RANGE_BINS 64
#define RANGE_RESOLUTION 0.0486f
#define INTRUSION_THRESHOLD 1.0f
#define LED_ON_TIME_US 2000000
#define LOG_FILE "intrusion_log.csv"
#define READ_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(const char *port, speed_t baud) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, baud);
    cfsetospeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_exact(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        fd_set rfds;
        FD_ZERO(&rfds);
        FD_SET(fd, &rfds);

        struct timeval tv = { .tv_sec = READ_TIMEOUT_MS / 1000, .tv_usec = (READ_TIMEOUT_MS % 1000) * 1000 };

        int ret = select(fd + 1, &rfds, NULL, NULL, &tv);
        if (ret < 0) {
            if (errno == EINTR) continue;
            perror("select() error");
            return -1;
        }
        if (ret == 0) {
            fprintf(stderr, "Timeout reading %zu bytes\n", len);
            return -1;
        }

        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("read() error");
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART closed unexpectedly\n");
            return -1;
        }
        total += n;
    }
    return 0;
}

static int process_frame(const uint8_t *frame, int *distance_out) {
    if (frame[0] != 0x02 || frame[1] != 0x01 || frame[2] != 0x04 || frame[3] != 0x03 ||
        frame[4] != 0x06 || frame[5] != 0x05 || frame[6] != 0x08 || frame[7] != 0x07) {
        fprintf(stderr, "Invalid magic word\n");
        return -1;
    }

    if (frame[8] != 0x00 || frame[9] != 0x00 || frame[10] != 0x00 || frame[11] != 0x00) {
        fprintf(stderr, "Invalid frame length\n");
        return -1;
    }

    uint16_t range_profile[RANGE_BINS];
    for (int i = 0; i < RANGE_BINS; i++) {
        uint16_t val = (frame[8 + 2 * i] << 8) | frame[8 + 2 * i + 1];
        range_profile[i] = val;
    }

    float max_range = 0.0f;
    for (int i = 0; i < RANGE_BINS; i++) {
        float range = (float)i * RANGE_RESOLUTION;
        if (range_profile[i] > 0 && range < INTRUSION_THRESHOLD) {
            max_range = range;
        }
    }

    if (max_range > 0.0f) {
        *distance_out = max_range;
        return 1;
    }
    *distance_out = -1.0f;
    return 0;
}

static void log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file);
}

static void trigger_alert(int gpio_pin) {
    gpioWrite(gpio_pin, 1);
    gpioDelay(LED_ON_TIME_US);
    gpioWrite(gpio_pin, 0);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    uart_fd = init_uart(UART_PORT, BAUD_RATE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Distance (m)\n");
        fflush(log_file);
    }

    uint8_t frame_buf[144];
    int distance;

    while (running) {
        if (read_exact(uart_fd, frame_buf, sizeof(frame_buf)) == 0) {
            if (process_frame(frame_buf, &distance) == 1) {
                printf("Intrusion detected at %.2f meters\n", distance);
                log_intrusion(distance);
                trigger_alert(GPIO_LED);
            }
        } else {
            fprintf(stderr, "Failed to read frame\n");
            break;
        }
    }

    if (uart_fd >= 0) close(uart_fd);
    if (log_file) fclose(log_file);
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();

    return 0;
}

