#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x69
#define GPIO_ALERT     17
#define DISTANCE_THRESHOLD 10.0f
#define SAMPLE_PERIOD_US 100000  /* 100 ms */
#define LOG_FILE       "distance_log.txt"

/* ICU-20201 register addresses (16-bit distance in mm) */
#define REG_DISTANCE_HIGH 0x31
#define REG_DISTANCE_LOW  0x32

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read 16-bit distance from the ICU-20201.
 * Returns 0 on success and stores the distance in *out_mm.
 * Returns -1 on I2C error, -2 on sensor-absence (no ACK). */
static int read_distance_mm(int handle, int *out_mm)
{
    char reg = (char)REG_DISTANCE_HIGH;
    char buf[2];

    /* Write the register pointer */
    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "[ERROR] I2C write pointer 0x%02X failed\n", REG_DISTANCE_HIGH);
        return -1;
    }

    /* Read two bytes of distance data */
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C read distance (0x%02X) failed\n", REG_DISTANCE_HIGH);
        return -1;
    }

    *out_mm = ((int)(unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    return 0;
}

static void log_distance(float distance_cm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&t, &tm_info) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    } else {
        snprintf(ts, sizeof(ts), "1970-01-01T00:00:00");
    }

    fprintf(fp, "%s, Distance: %.2f cm\n", ts, distance_cm);
    fclose(fp);
}

static void check_threshold(float distance_cm)
{
    if (distance_cm < DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_ALERT, 1);
        gpioDelay(100000);  /* 100 ms alert pulse */
        gpioWrite(GPIO_ALERT, 0);
    }
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the ICU-20201 default address */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure alert GPIO */
    if (gpioSetMode(GPIO_ALERT, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", GPIO_ALERT);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_ALERT, 0);

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ICU-20201 distance monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int mm;
        if (read_distance_mm(g_i2c_handle, &mm) != 0) {
            /* I2C error or sensor-absence: log and continue */
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Sensor-absence heuristic: if the device never ACKs, treat as no-data */
        if (mm == 0 && mm != 0x0000) {
            fprintf(stderr, "[WARN] Sensor not responding (0 mm read)\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float distance_cm = (float)mm / 10.0f;
        log_distance(distance_cm);
        check_threshold(distance_cm);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");
    gpioWrite(GPIO_ALERT, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

