#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define LOG_FILE       "distance_log.csv"
#define POLL_INTERVAL  100000   /* microseconds (100 ms) */
#define RANGE_TIMEOUT  100000   /* microseconds (100 ms) */

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET              0x0000
#define REG_MODEL_ID                0x010F
#define REG_SYSTEM_MODE_START       0x0070
#define REG_SYSRANGE_START          0x0000
#define REG_RESULT_INTERRUPT_STATUS 0x0130
#define REG_RESULT_RANGE_STATUS     0x0780
#define REG_SYSTEM_INTERRUPT_CLEAR  0x0140

#define EXPECTED_MODEL_ID           0xEA
#define SYSRANGE_START_BIT          0x01

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write one byte to a 16-bit register address */
static int reg_write(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read one byte from a 16-bit register address */
static int reg_read(int handle, uint16_t reg, uint8_t *value)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, (char *)value, 1) != 1)
        return -1;
    return 0;
}

/* Read a 16-bit big-endian register */
static int reg_read_16(int handle, uint16_t reg, uint16_t *value)
{
    char addr[2];
    char data[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;
    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int init_sensor(int handle)
{
    uint8_t model_id = 0;
    if (reg_read(handle, REG_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Error: failed to read model ID register.\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X).\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }
    printf("VL53L1X detected (model ID 0x%02X).\n", model_id);

    if (reg_write(handle, REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write soft reset.\n");
        return -1;
    }
    gpioDelay(2000); /* 2 ms */

    if (reg_write(handle, REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error: failed to start continuous ranging.\n");
        return -1;
    }
    return 0;
}

static int read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    int waited = 0;

    /* Poll data-ready bit (bit 0 of SYSRANGE_START) */
    while (waited < RANGE_TIMEOUT) {
        if (reg_read(handle, REG_RESULT_INTERRUPT_STATUS, &status) < 0) {
            fprintf(stderr, "Error: failed to read interrupt status.\n");
            return -1;
        }
        if (status & SYSRANGE_START_BIT)
            break;
        gpioDelay(1000); /* 1 ms */
        waited += 1000;
    }
    if (waited >= RANGE_TIMEOUT) {
        fprintf(stderr, "Error: ranging timeout.\n");
        return -1;
    }

    /* Read 16-bit distance (big-endian at 0x078) */
    if (reg_read_16(handle, REG_RESULT_RANGE_STATUS, distance_mm) < 0) {
        fprintf(stderr, "Error: failed to read distance register.\n");
        return -1;
    }

