#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

#define I2C_BUS        1
#define CH201_ADDR     0x45
#define LED_GPIO       18
#define SAMPLE_US      100000   /* 100 ms */
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000    /* 10 ms */

/* CH201 register addresses (datasheet) */
#define CH201_REG_DISTANCE  0x00
#define CH201_REG_MODE      0x01
#define CH201_REG_CONFIG    0x02

/* Mode bits: 0x01 = continuous mode */
#define CH201_MODE_CONTINUOUS 0x01

/* Config bits: 0x00 = default, 0x01 = 100 ms standby */
#define CH201_CONFIG_DEFAULT  0x00
#define CH201_CONFIG_100MS   0x01

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a byte to a CH201 register; returns 0 on success, -1 on failure. */
static int ch201_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* Read a byte from a CH201 register; returns 0 on success, -1 on failure. */
static int ch201_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* Read distance from CH201; returns distance in mm on success, -1 on failure. */
static int ch201_read_distance(int handle)
{
    uint8_t dist_raw;
    int retries = MAX_RETRIES;

    while (retries > 0) {
        if (ch201_read_reg(handle, CH201_REG_DISTANCE, &dist_raw) == 0) {
            /* Distance is the lower 8 bits of the 16-bit result */
            return (int)dist_raw;
        }
        retries--;
        if (retries > 0)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* Map distance (mm) to blink frequency (Hz); clamps to [1, 10] Hz. */
static int distance_to_frequency(int distance)
{
    if (distance < 50)
        return 10;
    if (distance > 500)
        return 1;
    return 10 - (distance - 50) * 9 / 450;
}

/* Blink the LED for half_cycles at the given frequency (Hz). */
static void blink_led(int gpio, int frequency, int half_cycles)
{
    int period_us = 500000 / frequency;
    int on_us     = period_us / 2;
    int off_us    = period_us / 2;

    for (int i = 0; i < half_cycles && g_running; i++) {
        gpioWrite(gpio, 1);
        gpioDelay(on_us);
        gpioWrite(gpio, 0);
        gpioDelay(off_us);
    }
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at CH201 default address */
    g_i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X on bus %d: %d\n",
                CH201_ADDR, I2C_BUS, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure CH201: continuous mode, 100 ms standby */
    if (ch201_write_reg(g_i2c_handle, CH201_REG_MODE, CH201_MODE_CONTINUOUS) != 0) {
        fprintf(stderr, "Failed to set CH201 continuous mode\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (ch201_write_reg(g_i2c_handle, CH201_REG_CONFIG, CH201_CONFIG_100MS) != 0) {
        fprintf(stderr, "Failed to set CH201 config\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO as output and ensure it is off */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CH201 distance sensor running. Press Ctrl+C to exit.\n");

    while (g_running) {
        int distance = ch201_read_distance(g_i2c_handle);
        if (distance < 0) {
            fprintf(stderr, "Sensor read failed; continuing.\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        int frequency = distance_to_frequency(distance);
        int half_cycles = (frequency > 0) ? (frequency * 2) : 1;

        /* Blink for half_cycles at the calculated frequency */
        blink_led(LED_GPIO, frequency, half_cycles);

        /* Log timestamped data */
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("[%s] Distance: %d mm, Blink frequency: %d Hz\n",
               ts, distance, frequency);
        fflush(stdout);

        gpioDelay(SAMPLE_US);
    }

    /* Clean shutdown */
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

