#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define POLL_INTERVAL_US 10000
#define DEBOUNCE_DELAY_US 50000
#define LOG_FILE "proximity_log.txt"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error: failed to read GPIO %d\n", gpio_pin);
        return -1;
    }
    return value;
}

static const char *get_event_type(int sensor_id, int previous_state, int current_state) {
    if (sensor_id == 1) {
        if (previous_state == 1 && current_state == 0) {
            return "DETECTED";
        }
    } else if (sensor_id == 2) {
        if (previous_state == 0 && current_state == 1) {
            return "CLEARED";
        }
    }
    return "UNKNOWN";
}

static int log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: failed to get UTC time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Sensor %d - %s\n", timestamp, sensor_id, event_type) < 0) {
        fprintf(stderr, "Error: failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    int sensor1_state = 1;
    int sensor2_state = 1;
    int previous_sensor1_state = 1;
    int previous_sensor2_state = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error: sensor read failure, exiting\n");
            break;
        }

        sensor1_state = sensor1_value;
        sensor2_state = sensor2_value;

        if (sensor1_state != previous_sensor1_state) {
            const char *event_type = get_event_type(1, previous_sensor1_state, sensor1_state);
            if (log_event(1, event_type) != 0) {
                fprintf(stderr, "Error: failed to log event for sensor 1\n");
            }
            previous_sensor1_state = sensor1_state;
        }

        if (sensor2_state != previous_sensor2_state) {
            const char *event_type = get_event_type(2, previous_sensor2_state, sensor2_state);
            if (log_event(2, event_type) != 0) {
                fprintf(stderr, "Error: failed to log event for sensor 2\n");
            }
            previous_sensor2_state = sensor2_state;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Error: failed to close log file: %s\n", strerror(errno));
        }
        log_file = NULL;
    }

    gpioTerminate();

    return 0;
}

