#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_ADDR     0x49
#define MEAS_TRIGGER   0x04
#define MEAS_STATUS    0x06
#define DIST_HIGH      0x08
#define DIST_LOW       0x09
#define STATUS_DATA_RDY 0x01
#define POLL_TIMEOUT_MS 50
#define SAMPLE_PERIOD_MS 500
#define LOG_FILE       "distance_log.csv"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an 8-bit register. */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, value, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* Read a single byte from an 8-bit register. */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write(0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read(0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit little-endian register pair (high first). */
static int i2c_read_reg16(int fd, uint8_t reg_hi, uint8_t reg_lo, uint16_t *out) {
    uint8_t hi, lo;
    if (i2c_read_reg8(fd, reg_hi, &hi) < 0) return -1;
    if (i2c_read_reg8(fd, reg_lo, &lo) < 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* Trigger a single measurement and wait for data-ready. */
static int ch101_trigger_and_wait(int fd) {
    if (i2c_write_reg8(fd, MEAS_TRIGGER, 0x01) < 0) return -1;

    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        uint8_t status;
        if (i2c_read_reg8(fd, MEAS_STATUS, &status) < 0) return -1;
        if (status & STATUS_DATA_RDY) return 0;
        usleep(1000);
    }
    fprintf(stderr, "CH-101 measurement timeout after %d ms\n", POLL_TIMEOUT_MS);
    return -1;
}

static int log_data(FILE *fp, uint16_t distance_mm) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%u\n", ts, (unsigned)distance_mm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", CH101_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty. */
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,distance_mm\n");
        fflush(fp);
    }

    while (g_running) {
        if (ch101_trigger_and_wait(fd) < 0) {
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        uint16_t distance;
        if (i2c_read_reg16(fd, DIST_HIGH, DIST_LOW, &distance) < 0) {
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

