    (void)sig;
    running = 0;
}

int read_distance(int handle, uint16_t *distance) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(handle, buf, 2);
        if (result == 2) {
            *distance = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }
        fprintf(stderr, "I2C read failed (attempt %d/%d): %d\n", retries + 1, RETRY_COUNT, result);
        retries++;
        if (retries < RETRY_COUNT) {
            gpioDelay(RETRY_DELAY_US);
        }
    }
    return -1;
}

void log_distance(uint16_t distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm *tm_info = localtime(&ts.tv_sec);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    printf("%s.%03ld Distance: %u mm\n", timestamp, ts.tv_nsec / 1000000, distance);
    fflush(stdout);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

