    if (write_reg16(handle, REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(1000);

    if (write_reg16(handle, REG_I2C_SLAVE_DEVICE_ADDRESS, VL53L1X_ADDR) < 0) return -1;
    if (write_reg16(handle, REG_SYSTEM_MODE_START, 0x00) < 0) return -1;
    gpioDelay(1000);

    return 0;
}

static int read_distance(int handle, uint8_t *distance) {
    if (write_reg16(handle, REG_SYSTEM_MODE_START, 0x01) < 0) return -1;
    gpioDelay(1000);
    if (read_reg16(handle, REG_RESULT_FINAL_CROSSTALK_CORRECTED_DISTANCE_MM, distance) < 0) return -1;
    if (write_reg16(handle, REG_SYSTEM_MODE_START, 0x00) < 0) return -1;
    gpioDelay(1000);
    return 0;
