#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   17

#define SPEED_OF_SOUND 343.0
#define MIN_DISTANCE   2.0
#define MAX_DISTANCE   400.0
#define MIN_ANGLE      -90
#define MAX_ANGLE      90
#define SERVO_MIN_US   1000   /* ~ -90 degrees (SG90) */
#define SERVO_MAX_US   2000   /* ~ +90 degrees (SG90) */
#define ECHO_TIMEOUT_US 50000 /* 50 ms timeout for echo */
#define LOOP_DELAY_US  200000 /* 200 ms between readings */
#define TRIGGER_PULSE_US 10

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in cm using the HC-SR04.
 * Returns distance on success, or -1.0 on timeout / error.
 */
static float measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 1) failed\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout if sensor absent) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo stuck low (timeout)\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout if sensor absent) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo stuck high (timeout)\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    float distance = (pulse_width / 1000000.0) * SPEED_OF_SOUND / 2.0;

    if (distance < 0.0 || distance > 400.0) {
        fprintf(stderr, "Warning: Distance %.2f cm out of range\n", distance);
        return -1.0;
    }
    return distance;
}

/*
 * Map distance to servo pulse width in microseconds.
 * Returns -1.0 if distance is invalid.
 */
static int map_distance_to_angle(float distance) {
    if (distance < 0.0 || distance < MIN_DISTANCE) {
        return -1;
    }
    if (distance > MAX_DISTANCE) {
        return -1;
    }
    float angle = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) *
                   (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE;
    return (int)(angle + 0.5);
}

/*
 * Set servo angle in degrees (-90 to +90).
 * Returns 0 on success, -1 on error.
 */
static int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle %d out of range [%d, %d]\n",
                angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }
    int pulse_width = SERVO_MIN_US +
                      (int)((float)angle / (MAX_ANGLE - MIN_ANGLE) *
                            (SERVO_MAX_US - SERVO_MIN_US));
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

/*
 * Log distance and angle to sensor_data.log.
 * Returns 0 on success, -1 on error.
 */
static int log_data(float distance, int angle) {
    FILE *fp = fopen("sensor_data.log", "a");
    if (!fp) {
        fprintf(stderr, "Error: Cannot open sensor_data.log: %s\n",
                strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %.2f cm, Angle: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            distance, angle);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: fclose failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger) failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo) failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(servo) failed\n");
        gpioTerminate();
        return 1;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000); /* 100 ms settle */

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Warning: Invalid distance reading, skipping.\n");
        } else {
            int angle = map_distance_to_angle(distance);
            if (angle < 0) {
                fprintf(stderr, "Warning: Invalid distance %.2f cm, skipping.\n",
                        distance);
            } else {
                if (set_servo_angle(angle) < 0) {
                    fprintf(stderr, "Warning: Failed to set servo angle.\n");
                }
                if (log_data(distance, angle) < 0) {
                    fprintf(stderr, "Warning: Failed to log data.\n");
                }
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Graceful shutdown: stop servo, release resources */
    gpioServo(SERVO_PIN, 0); /* Stop servo PWM */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nParking Assist System stopped.\n");
    return 0;
}

