#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100
#define POLL_INTERVAL_US 50000
#define RANGE_TIMEOUT_MS 1000

#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_SYSTEM_START 0x0080
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0089
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

#define VL53L1X_MODEL_ID 0xEA
#define VL53L1X_EXPECTED_ID 0xEA

static int i2c_handle = -1;
static int message_queue_id = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_byte(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, buf, 1) != 1) return -1;
    *value = (uint8_t)buf[0];
    return 0;
}

static int i2c_read_word(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_byte(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        return -1;
    }
    if (model_id != VL53L1X_EXPECTED_ID) {
        fprintf(stderr, "Invalid model ID: 0x%02X (expected 0x%02X)\n", model_id, VL53L1X_EXPECTED_ID);
        return -1;
    }

    if (i2c_write_byte(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error writing soft reset 0x00: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1000);

    if (i2c_write_byte(handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0) {
        fprintf(stderr, "Error writing soft reset 0x01: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1000);

    if (i2c_write_byte(handle, 0x00, 0x01) < 0) {
        fprintf(stderr, "Error setting timing budget: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1000);

    if (i2c_write_byte(handle, VL53L1X_REG_SYSTEM_START, 0x01) < 0) {
        fprintf(stderr, "Error starting ranging: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1000);

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint8_t status = 0;
    int timeout = 0;
    while (timeout < RANGE_TIMEOUT_MS) {
        if (i2c_read_byte(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, &status) < 0) {
            fprintf(stderr, "Error reading interrupt status: %s\n", strerror(errno));
            return -1;
        }
        if ((status & 0x01) == 0) break;
        gpioDelay(1000);
        timeout++;
    }
    if (timeout >= RANGE_TIMEOUT_MS) {
        fprintf(stderr, "Range measurement timeout\n");
        return -1;
    }

