#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define BUZZER_PIN  22

#define SPEED_OF_SOUND_CM_PER_S 34300.0
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define THRESHOLD_CM    30.0
#define ECHO_TIMEOUT_US 30000   /* 30 ms max echo wait */
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US    100000 /* 100 ms between readings */

static volatile sig_atomic_t running = 1;

/* Echo measurement state (updated by alert callback) */
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick   = 0;
static volatile int      echo_seen  = 0;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * pigpio alert callback for echo pin.
 * tick is a 32-bit microsecond counter that wraps every ~71.6 min.
 * gpioTick() returns the current tick; we compute the difference.
 */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        start_tick = tick;
        echo_seen  = 0;
    } else if (level == 0) {
        end_tick = tick;
        echo_seen = 1;
    }
}

/*
 * Send a 10 us trigger pulse and wait for the echo.
 * Returns distance in cm, or -1.0 on timeout/error.
 */
static float get_distance(void)
{
    echo_seen  = 0;
    start_tick = 0;
    end_tick   = 0;

    /* Ensure trigger is low before starting */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to reset trigger pin\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0;
    }

    /* Wait for echo with timeout */
    uint32_t waited = 0;
    while (!echo_seen && waited < ECHO_TIMEOUT_US) {
        gpioDelay(100);
        waited += 100;
    }

    if (!echo_seen) {
        fprintf(stderr, "Warning: echo timeout (no echo received)\n");
        return -1.0;
    }

    /* Compute elapsed microseconds, handling 32-bit wraparound */
    uint32_t elapsed = end_tick - start_tick;

    /* distance = (elapsed_us * speed_cm_per_s) / 2 / 1000000 */
    float distance = (float)elapsed * SPEED_OF_SOUND_CM_PER_S / 2000000.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of valid range [%.0f-%.0f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0;
    }

    return distance;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    /* Register alert callback for echo pin */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to register echo alert\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    int buzzer_on = 0;

    while (running) {
        float distance = get_distance();

        if (distance < 0.0f) {
            /* Error or timeout already reported in get_distance */
            if (buzzer_on) {
                gpioWrite(BUZZER_PIN, 0);
                buzzer_on = 0;
            }
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        printf("Distance: %.2f cm\n", distance);

        if (distance < THRESHOLD_CM) {
            if (!buzzer_on) {
                if (gpioWrite(BUZZER_PIN, 1) == 0) {
                    buzzer_on = 1;
                } else {
                    fprintf(stderr, "Error: failed to turn on buzzer\n");
                }
            }
        } else {
            if (buzzer_on) {
                if (gpioWrite(BUZZER_PIN, 0) == 0) {
                    buzzer_on = 0;
                } else {
                    fprintf(stderr, "Error: failed to turn off buzzer\n");
                }
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Cleanup */
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioTerminate();

    printf("\nParking sensor stopped.\n");
    return EXIT_SUCCESS;
}

