    return i2cWriteDevice(handle, buf, 3);
}

static int vl53l1x_read_reg16(int handle, uint16_t reg, uint8_t *value) {
    char buf[2] = {(char)(reg >> 8), (char)(reg & 0xFF)};
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, (char *)value, 1) != 1) return -1;
    return 0;
}

static int vl53l1x_init(int handle) {
    uint8_t id = 0;
    if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, &id) < 0) {
        fprintf(stderr, "VL53L1X not responding (sensor absent or bus error)\n");
        return -1;
    }
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(VL53L1X_BOOT_DELAY_MS * 1000);
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(VL53L1X_BOOT_DELAY_MS * 1000);
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE, 0x01) < 0) return -1;
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint8_t status = 0;
    for (int i = 0; i < VL53L1X_MAX_RETRIES; i++) {
        if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) < 0) {
            gpioDelay(1000);
            continue;
        }
        if ((status & 0x01) == 0) {
            uint8_t dist_low = 0, dist_high = 0;
            if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, &dist_low) < 0 ||
                vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE + 1, &dist_high) < 0) {
                return -1;
            }
            *distance = (dist_high << 8) | dist_low;
            return 0;
        }
        gpioDelay(VL53L1X_RANGE_DELAY_MS * 1000);
    }
    return -1;
}

static void control_gate(int open) {
    gpioServo(SERVO_PIN, open ? 1500 : 500);
    log_event(open ? "Gate Opened" : "Gate Closed");
}

static void mqtt_connect_callback(void *context, char *reason) {
    (void)context;
    fprintf(stderr, "MQTT Connect Reason: %s\n", reason ? reason : "Unspecified");
}

static void mqtt_message_callback(void *context, char *topic, int topicLen, MQTTClient_message *message) {
    (void)context;
    if (!topic || topicLen < 1) return;
    if (strcmp(topic, MQTT_TOPIC) == 0) {
        if (message->payloadlen > 0) {
            char payload[256];
