/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — captures rising and falling edge ticks     */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        /* Rising edge — echo pulse starts */
        g_rise_tick = tick;
    } else if (level == 0) {
        /* Falling edge — echo pulse ends */
        if (g_rise_tick != 0) {
            uint32_t pulse_us = tick - g_rise_tick;  /* handles 32-bit wrap */
            float distance_cm = (pulse_us * SPEED_OF_SOUND) / 2.0f;

            if (pulse_us >= MIN_PULSE_US && pulse_us <= MAX_PULSE_US) {
                time_t rawtime;
    time(&rawtime);
    struct tm *timeinfo = localtime(&rawtime);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    printf("[%s] Distance: %.2f cm\n", timestamp, distance_cm);

    if (g_log_file) {
        fprintf(g_log_file, "%s, %.2f\n", timestamp, distance_cm);
        fflush(g_log_file);
    }
    } else {
        fprintf(stderr, "Warning: rejected reading (%u us) — out of range\n",
                pulse_us);
        if (g_log_file) {
            fprintf(g_log_file, "Warning: rejected reading (%u us) - out of range\n",
                    pulse_us);
            fflush(g_log_file);
        }
    }
    }
    g_rise_tick = 0;
}

/* ------------------------------------------------------------------ */
/* Generate a 10 us trigger pulse                                    */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --------------------------------------- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n",
                TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n",
                ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-down on ECHO so it reads LOW when idle */
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Warning: failed to set pull-down on ECHO_PIN %d.\n",
                ECHO_PIN);
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000);  /* 50 ms settle time */

    /* --- Register alert callback for ECHO rising/falling edges ---- */
    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Error: failed to register alert callback on ECHO_PIN %d.\n",
                ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --------------------------------------------- */
    g_log_file = fopen("distance_log.txt", "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: cannot open distance_log.txt: %s\n",
                strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers ----------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("  TRIGGER: GPIO %d | ECHO: GPIO %d | log: distance_log.txt\n",
           TRIGGER_PIN, ECHO_PIN);
    printf("  Press Ctrl+C to exit.\n");

    /* --- Main measurement loop ------------------------------------- */
    while (g_running) {
        /* Reset echo state before triggering */
        g_rise_tick = 0;

        trigger_sensor();

        /*
         * Wait for the falling edge (echo pulse end) or until timeout.
         * pigpio's gpioTick() returns uint32_t microseconds; handle 32-bit wrap.
         */
        uint32_t wait_start = gpioTick();
        while (g_running) {
            uint32_t now = gpioTick();
            if (now - wait_start > TIMEOUT_US) {
                break;  /* timeout — no echo received */
            }
            gpioDelay(1000);  /* 1 ms poll interval */
        }

        /*
         * If we broke out of the wait loop because TIMEOUT_US elapsed,
         * log a warning and continue.
         */
        if (!g_running) {
            break;
        }

        if (g_rise_tick == 0) {
            fprintf(stderr, "Warning: no echo received within %d us.\n",
                    TIMEOUT_US);
            if (g_log_file) {
                fprintf(g_log_file, "Warning: no echo received within %d us.\n",
                        TIMEOUT_US);
                fflush(g_log_file);
            }
        }

        /* --- 200 ms sample period ----------------------------------- */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Cleanup ---------------------------------------------------- */
    printf("\nShutting down...\n");

    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

