#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_MOTOR_FORWARD 17
#define GPIO_MOTOR_BACKWARD 18
#define GPIO_SENSOR_TRIGGER 24
#define DISTANCE_THRESHOLD_LOW 100
#define DISTANCE_THRESHOLD_HIGH 300
#define POLL_TIMEOUT_MS 100
#define MAX_RETRIES 3

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    int rc = i2cWriteDevice(handle, buf, 3);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%04X, val 0x%02X): %d\n", reg, value, rc);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    int rc = i2cWriteDevice(handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C write (read reg addr) failed: %d\n", rc);
        return -1;
    }
    rc = i2cReadDevice(handle, (char *)value, 1);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%04X): %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    int rc = i2cWriteDevice(handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C write (read reg addr) failed: %d\n", rc);
        return -1;
    }
    rc = i2cReadDevice(handle, (char *)value, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%04X): %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int handle) {
    if (i2c_write_reg8(handle, 0x0000, 0x00) < 0) return -1;
    gpioDelay(1000);
    if (i2c_write_reg8(handle, 0x0000, 0x01) < 0) return -1;
    gpioDelay(1000);
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint8_t status = 0;
    int elapsed = 0;
    while (elapsed < POLL_TIMEOUT_MS) {
        if (i2c_read_reg8(handle, 0x0089, &status) < 0) return -1;
        if (status & 0x01) break;
        gpioDelay(1000);
        elapsed++;
    }
    if (elapsed >= POLL_TIMEOUT_MS) {
        fprintf(stderr, "VL53L1X data-ready timeout\n");
        return -1;
    }
    if (i2c_read_reg16(handle, 0x0096, distance) < 0) return -1;
    return 0;
}

static void motor_control(int distance) {
    if (distance < DISTANCE_THRESHOLD_LOW) {
        gpioWrite(GPIO_MOTOR_FORWARD, 1);
        gpioWrite(GPIO_MOTOR_BACKWARD, 0);
        printf("Moving forward (distance: %d mm)\n", distance);
    } else if (distance > DISTANCE_THRESHOLD_HIGH) {
        gpioWrite(GPIO_MOTOR_FORWARD, 0);
        gpioWrite(GPIO_MOTOR_BACKWARD, 1);
        printf("Moving backward (distance: %d mm)\n", distance);
    } else {
        gpioWrite(GPIO_MOTOR_FORWARD, 0);
        gpioWrite(GPIO_MOTOR_BACKWARD, 0);
        printf("Stopping (distance: %d mm)\n", distance);
    }
}

static void sensor_interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    if (i2c_handle >= 0) {
        uint16_t distance = 0;
        if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
            motor_control((int)distance);
        } else {
            fprintf(stderr, "Sensor read failed, stopping motor\n");
            gpioWrite(GPIO_MOTOR_FORWARD, 0);
            gpioWrite(GPIO_MOTOR_BACKWARD, 0);
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_MOTOR_FORWARD, PI_OUTPUT);
    gpioSetMode(GPIO_MOTOR_BACKWARD, PI_OUTPUT);
    gpioSetMode(GPIO_SENSOR_TRIGGER, PI_INPUT);
    gpioSetPullUpDown(GPIO_SENSOR_TRIGGER, PI_PUD_DOWN);

    if (gpioSetISRFuncEx(GPIO_SENSOR_TRIGGER, RISING_EDGE, 0, sensor_interrupt_handler, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR for GPIO%d\n", GPIO_SENSOR_TRIGGER);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance sensor running. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioWrite(GPIO_MOTOR_FORWARD, 0);
    gpioWrite(GPIO_MOTOR_BACKWARD, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

