#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define NUM_ELECTRODES 12
#define POLL_DELAY_MS 50

#define LED1_PIN 17
#define LED2_PIN 18
#define LED3_PIN 27
#define LED4_PIN 22

#define MHDR 0x2B
#define NHDR 0x2C
#define NCLR 0x2D
#define FDLR 0x2E
#define ELECONFIG0 0x5E
#define ELECONFIG1 0x5F
#define ELECONFIG2 0x5A
#define ELECONFIG3 0x5B
#define ELECONFIG4 0x5C
#define ELECONFIG5 0x5D
#define TOUCHSTATUS_L 0x00
#define TOUCHSTATUS_H 0x01
#define SOFTRESET 0x80
#define RESET_CMD 0x63

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_lines[4] = {NULL, NULL, NULL, NULL};
static int led_pins[4] = {LED1_PIN, LED2_PIN, LED3_PIN, LED4_PIN};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    uint8_t id;
    if (i2c_read_reg(0x5C, &id) < 0) return -1;
    if (id != 0x03) {
        fprintf(stderr, "Unexpected MPR121 ID: 0x%02X (expected 0x03)\n", id);
        return -1;
    }
    if (i2c_write_reg(SOFTRESET, RESET_CMD) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg(ELECONFIG0, 0x00) < 0) return -1;
    if (i2c_write_reg(MHDR, 0x01) < 0) return -1;
    if (i2c_write_reg(NHDR, 0x01) < 0) return -1;
    if (i2c_write_reg(NCLR, 0x0E) < 0) return -1;
    if (i2c_write_reg(FDLR, 0x00) < 0) return -1;
    if (i2c_write_reg(ELECONFIG2, 0x0B) < 0) return -1;
    if (i2c_write_reg(ELECONFIG3, 0xC8) < 0) return -1;
    if (i2c_write_reg(ELECONFIG4, 0x82) < 0) return -1;
    if (i2c_write_reg(ELECONFIG5, 0xB4) < 0) return -1;
    if (i2c_write_reg(ELECONFIG0, 0x0C) < 0) return -1;
    return 0;
}

static int read_touch_status(uint16_t *status) {
    uint8_t lo, hi;
    if (i2c_read_reg(TOUCHSTATUS_L, &lo) < 0) return -1;
    if (i2c_read_reg(TOUCHSTATUS_H, &hi) < 0) return -1;
    *status = ((uint16_t)hi << 8) | lo;
    return 0;
}

static void set_led_pattern(uint8_t pattern) {
    for (int i = 0; i < 4; i++) {
        if (gpiod_line_set_value(led_lines[i], (pattern >> i) & 1) < 0) {
            fprintf(stderr, "Failed to set LED %d: %s\n", i, strerror(errno));
        }
    }
}

static void log_event(int electrode, uint8_t pattern) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s - Electrode %d touched, LED pattern: 0x%02X\n", timestamp, electrode, pattern);
    fflush(log_file);
}

static void log_no_touch(void) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s - No electrodes touched\n", timestamp);
    fflush(log_file);
}

static void cleanup(void) {
    for (int i = 0; i < 4; i++) {
        if (led_lines[i]) {
            gpiod_line_set_value(led_lines[i], 0);
            gpiod_line_release(led_lines[i]);
        }
    }
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_file) fclose(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen("proximity_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        cleanup();
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return 1;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        cleanup();
        return 1;
    }
    for (int i = 0; i < 4; i++) {
        led_lines[i] = gpiod_chip_get_line(chip, led_pins[i]);
        if (!led_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", led_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(led_lines[i], "proximity_art", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", led_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
    }

    uint8_t patterns[NUM_ELECTRODES] = {0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x01, 0x02, 0x04, 0x08};

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }

        int electrode_touched = -1;
        for (int i = 0; i < NUM_ELECTRODES; i++) {
            if (touch_status & (1 << i)) {
                electrode_touched = i;
                break;
            }
        }

        if (electrode_touched != -1) {
            uint8_t pattern = patterns[electrode_touched];
            set_led_pattern(pattern);
            log_event(electrode_touched, pattern);
        } else {
            log_no_touch();
        }

        usleep(POLL_DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

