#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define MPR121_ADDR 0x5A
#define I2C_BUS 1
#define LED_GPIO 27
#define LOG_FILE "proximity.log"

#define MPR121_TOUCH_STATUS_L 0x00
#define MPR121_TOUCH_STATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_DEVICE_ID 0x0D
#define MPR121_TOUCH_THRESH_0 0x41
#define MPR121_RELEASE_THRESH_0 0x42
#define MPR121_FILTER_CONFIG 0x2B
#define MPR121_AFE_CONFIG 0x2C
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ELECTRODE_CONFIG_0 0x40

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int mpr121_read_reg(uint8_t reg) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return rc;
}

static int mpr121_init(void) {
    int id = mpr121_read_reg(MPR121_DEVICE_ID);
    if (id < 0) return -1;
    if (id != 0x0D) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0x0D)\n", id);
        return -1;
    }

    if (mpr121_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;
    if (mpr121_write_reg(MPR121_AFE_CONFIG, 0x10) < 0) return -1;
    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FILTER_CONFIG, 0x01) < 0) return -1;

    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(0x41 + (i * 2), 0x0A) < 0) return -1;
        if (mpr121_write_reg(0x42 + (i * 2), 0x05) < 0) return -1;
    }

    if (mpr121_write_reg(MPR121_ELECTRODE_CONFIG, 0x0C) < 0) return -1;

    return 0;
}

static int read_touch_status(uint16_t *status) {
    int low = mpr121_read_reg(MPR121_TOUCH_STATUS_L);
    if (low < 0) return -1;
    int high = mpr121_read_reg(MPR121_TOUCH_STATUS_H);
    if (high < 0) return -1;
    *status = (uint16_t)((high << 8) | low);
    return 0;
}

static void log_event(int electrode) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Proximity detected on electrode %d\n", timestamp, electrode);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity detector running. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        if (touch_status & (1 << 0)) {
            printf("Proximity detected on electrode 0\n");
            log_event(0);
            gpioWrite(LED_GPIO, 1);
            gpioDelay(1000000);
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(10000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

