#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define LOG_FILE "distance_log.txt"
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 30000
#define LOOP_DELAY_US 1000000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_distance(FILE *fp, double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "gmtime failed: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(fp, "%s, %.2f\n", timestamp, distance) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int measure_distance(struct gpiod_line *trigger, struct gpiod_line *echo, double *distance) {
    struct timespec start, end;
    long long pulse_us;

    /* Ensure trigger is low */
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    usleep(5);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trigger, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
        return -1;
    }
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for echo rising edge (timeout 30 ms) */
    int timeout = 0;
    while (gpiod_line_get_value(echo) == 0) {
        if (gpiod_line_get_value(echo) < 0) {
            fprintf(stderr, "Failed to read echo low: %s\n", strerror(errno));
            return -1;
        }
        clock_gettime(CLOCK_MONOTONIC, &start);
        timeout = 0;
        while (gpiod_line_get_value(echo) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            long long elapsed_us = (end.tv_sec - start.tv_sec) * 1000000LL +
                                   (end.tv_nsec - start.tv_nsec) / 1000LL;
            if (elapsed_us > ECHO_TIMEOUT_US) {
                timeout = 1;
                break;
            }
        }
        if (timeout) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            return -1;
        }
    }

    /* Measure echo pulse width (timeout 30 ms) */
    timeout = 0;
    while (gpiod_line_get_value(echo) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        long long elapsed_us = (end.tv_sec - start.tv_sec) * 1000000LL +
                               (end.tv_nsec - start.tv_nsec) / 1000LL;
        if (elapsed_us > ECHO_TIMEOUT_US) {
            timeout = 1;
            break;
        }
    }
    if (timeout) {
        fprintf(stderr, "Timeout waiting for echo falling edge\n");
        return -1;
    }

    pulse_us = (end.tv_sec - start.tv_sec) * 1000000LL +
               (end.tv_nsec - start.tv_nsec) / 1000LL;

    /* distance = (pulse_us * 0.0343) / 2  cm */
    *distance = (double)pulse_us * 0.0343 / 2.0;

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    /* Open GPIO chip 0 (gpiochip0 on Pi Zero W) */
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        goto cleanup;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        fprintf(stderr, "Failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request trigger as output, initial value low */
    if (gpiod_line_request_output(trigger, "hc-sr04-trigger", 0) < 0) {
        fprintf(stderr, "Failed to request trigger as output: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request echo as input */
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo as input: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Open log file in append mode */
    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        double distance;
        int rc = measure_distance(trigger, echo, &distance);

        if (rc == 0) {
            if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
                fprintf(stderr, "Distance %.2f cm out of range [%.0f, %.0f]. Rejecting.\n",
                        distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
                if (log_distance(fp, -1.0) < 0) {
                    fprintf(stderr, "Failed to log rejected reading.\n");
                }
            } else {
                if (log_distance(fp, distance) < 0) {
                    fprintf(stderr, "Failed to log distance.\n");
                } else {
                    printf("Distance: %.2f cm\n", distance);
                }
            }
        } else {
            fprintf(stderr, "Failed to measure distance.\n");
            if (log_distance(fp, -1.0) < 0) {
                fprintf(stderr, "Failed to log error.\n");
            }
        }

        usleep(LOOP_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fp) {
        fclose(fp);
    }
    if (trigger) {
        gpiod_line_release(trigger);
    }
    if (echo) {
        gpiod_line_release(echo);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

