#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIG_PIN      17
#define ECHO_PIN      18
#define LOG_FILE      "distance_log.txt"
#define TRIG_PULSE_US 10
#define SAMPLE_PERIOD_S 1
#define MIN_PULSE_US  58
#define MAX_PULSE_US  25000
#define SPEED_OF_SOUND_MPS 343.0
#define SAMPLE_PERIOD_US  (SAMPLE_PERIOD_S * 1000000)

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/*
 * pigpio ISR callback: fires on EITHER_EDGE of ECHO_PIN.
 * pigpio guarantees callbacks run in a dedicated thread, so we
 * keep the pulse-width calculation simple and use a 32-bit tick
 * difference that handles wraparound.
 */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        static uint32_t start_tick = 0;
        start_tick = tick;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        uint32_t end_tick;
        uint32_t pulse_us;

        /* Handle 32-bit tick wraparound */
        if (start_tick == 0) {
            /* Should not happen; level==0 only called after level==1 */
            return;
        }
        end_tick = tick;
        pulse_us = end_tick - start_tick; /* pigpio ticks are microseconds */
        start_tick = 0;

        if (pulse_us > 0 && pulse_us < MAX_PULSE_US) {
            double distance_m = (double)pulse_us * SPEED_OF_SOUND_MPS / 2.0e6;
            time_t rawtime;
            struct tm timeinfo;
            char timestamp[32];

            time(&rawtime);
            localtime_r(&rawtime, &timeinfo);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

            if (g_log_fp) {
                fprintf(g_log_fp, "%s, Distance: %.2f m\n", timestamp, distance_m);
                fflush(g_log_fp);
            } else {
                fprintf(stderr, "Error: log file not open.\n");
            }
        } else {
            fprintf(stderr, "Warning: echo pulse %u us out of range (too short or too long).\n", pulse_us);
        }
    }
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIG_PIN %d as output.\n", TRIG_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /*
     * HC-SR04 echo signal is 5V TTL; the Pi's input is 3.3V.
     * Use a voltage divider (1 kOhm / 2 kOhm) to step the signal down.
     * This keeps the Pi safe and the logic levels clean.
     */
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    /* Ensure trigger starts LOW */
    gpioWrite(TRIG_PIN, 0);
    gpioDelay(50000); /* 50 ms settle */

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Register ISR on EITHER_EDGE --- */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR on ECHO_PIN %d.\n", ECHO_PIN);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error installing signal handler");
        gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG=GPIO%d, ECHO=GPIO%d, logging to '%s'.\n", TRIG_PIN, ECHO_PIN, LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        /* Fire a 10 us trigger pulse */
        gpioWrite(TRIG_PIN, 1);
        gpioDelay(TRIG_PULSE_US);
        gpioWrite(TRIG_PIN, 0);

        /* Wait for the echo callback to capture the pulse */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

