#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define TRIGGER_PIN 27
#define DISTANCE_REG 0x0014
#define STATUS_REG 0x0016
#define MODE_REG 0x0018
#define TIMEOUT_REG 0x0019
#define START_REG 0x0020

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int read_reg16(int handle, uint16_t reg, uint8_t *buf, int len) {
    char cmd[2];
    cmd[0] = (reg >> 8) & 0xFF;
    cmd[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, cmd, 2) < 0) return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != len) return -1;
    return 0;
}

static int init_vl53l1x(int handle) {
    if (write_reg16(handle, MODE_REG, 0x00) < 0) return -1;
    if (write_reg16(handle, TIMEOUT_REG, 0x00) < 0) return -1;
    if (write_reg16(handle, START_REG, 0x01) < 0) return -1;
    return 0;
}

static int read_distance(int handle, int *distance) {
    uint8_t buf[2];
    if (read_reg16(handle, DISTANCE_REG, buf, 2) < 0) return -1;
    *distance = (buf[1] << 8) | buf[0];
    return 0;
}

static int read_status(int handle, uint8_t *status) {
    return read_reg16(handle, STATUS_REG, status, 1);
}

static void log_data(int distance, uint8_t status) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    syslog(LOG_INFO, "Timestamp: %s, Distance: %d mm, Status: 0x%02X",
           timestamp, distance, status);
}

int main(void) {
    openlog("vl53l1x_reader", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioWrite(TRIGGER_PIN, 1);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device at 0x%02X: %d", VL53L1X_ADDR, i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (init_vl53l1x(i2c_handle) < 0) {
        syslog(LOG_ERR, "Failed to initialise VL53L1X sensor");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        int distance;
        uint8_t status;

        if (read_distance(i2c_handle, &distance) == 0 &&
            read_status(i2c_handle, &status) == 0) {
            log_data(distance, status);
        } else {
            syslog(LOG_ERR, "Failed to read sensor data");
        }

        gpioDelay(100000);
    }

    syslog(LOG_INFO, "Shutting down cleanly");
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

