#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD_CM 20.0f
#define LOG_FILE "gate_log.txt"

#define REG_MODEL_ID 0x010F
#define REG_SYSRANGE_START 0x0015
#define REG_RANGE_MODE 0x0021
#define REG_DISTANCE_HIGH 0x0089
#define REG_DISTANCE_LOW 0x008A

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg8(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        return -1;
    }
    char read_buf[2];
    if (i2cReadDevice(handle, read_buf, 2) != 2) {
        return -1;
    }
    *value = ((uint8_t)read_buf[0] << 8) | (uint8_t)read_buf[1];
    return 0;
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg8(handle, REG_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error: Failed to read model ID from sensor.\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Unexpected model ID 0x%02X (expected 0xEA).\n", model_id);
        return -1;
    }
    if (i2c_write_reg8(handle, REG_RANGE_MODE, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to set ranging mode.\n");
        return -1;
    }
    if (i2c_write_reg8(handle, REG_SYSRANGE_START, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }
    return 0;
}

static int read_distance_cm(int handle, float *distance_cm) {
    uint16_t distance_mm = 0;
    if (i2c_read_reg16(handle, REG_DISTANCE_HIGH, &distance_mm) != 0) {
        return -1;
    }
    *distance_cm = (float)distance_mm / 10.0f;
    return 0;
}

static void control_gate(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Error: Failed to write GPIO %d.\n", gpio);
    }
}

static void log_event(const char *message) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not open.\n");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, VL53L1X_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GATE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", GATE_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_gate(GATE_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("System started: gate closed, monitoring distance.");

    while (!terminate) {
        float distance_cm = 0.0f;
        if (read_distance_cm(i2c_handle, &distance_cm) != 0) {
            log_event("Error: Failed to read distance from sensor.");
            control_gate(GATE_GPIO, 0);
            gpioDelay(100000);
            continue;
        }

        int gate_state = (distance_cm < DISTANCE_THRESHOLD_CM) ? 1 : 0;
        if (gate_state != (int)gpioRead(GATE_GPIO)) {
            control_gate(GATE_GPIO, gate_state);
            char msg[128];
            snprintf(msg, sizeof(msg), "Gate state changed to %s (distance: %.2f cm)",
                     gate_state ? "OPEN" : "CLOSED", distance_cm);
            log_event(msg);
        }

        gpioDelay(100000);
    }

    log_event("System shutting down: closing gate and releasing resources.");
    control_gate(GATE_GPIO, 0);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

