#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE   2.0
#define MAX_DISTANCE   400.0
#define ECHO_TIMEOUT   30000   /* microseconds */
#define TRIGGER_PULSE  10
#define SAMPLE_SIZE    5
#define LOG_FILE       "distance_log.csv"
#define POLL_DELAY_US  100000  /* 100 ms */

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_width = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * pigpio alert callback for echo pin.
 * tick is a 32-bit microsecond counter that wraps every ~71.6 min.
 */
static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        /* Rising edge: start of echo pulse */
        echo_received = 0;
        pulse_width = 0;
    } else if (level == 0) {
        /* Falling edge: end of echo pulse */
        pulse_width = tick;
        echo_received = 1;
    }
}

static double measure_distance(void) {
    echo_received = 0;
    pulse_width = 0;

    /* Ensure trigger is low before starting */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0;
    }

    /* Wait for echo with timeout (poll every 100 us) */
    uint32_t start_tick = gpioTick();
    while (!echo_received && (gpioTick() - start_tick) < ECHO_TIMEOUT) {
        gpioDelay(100);
    }

    if (!echo_received) {
        return -1.0;
    }

    /* Handle 32-bit tick wrap-around */
    uint32_t pw = pulse_width;
    double distance = (pw / 1000000.0) * SPEED_OF_SOUND / 2.0;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0;
    }

    return distance;
}

static double moving_average(double new_value, double *history, int size, int *index) {
    history[*index] = new_value;
    *index = (*index + 1) % size;
    double sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += history[i];
    }
    return sum / size;
}

static double distance_to_angle(double distance) {
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;
    double angle = (log10(distance - MIN_DISTANCE) /
                    log10(MAX_DISTANCE - MIN_DISTANCE)) * 180.0;
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    return angle;
}

static int angle_to_pulse_width(double angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    return (int)(500 + (angle / 180.0) * 2000);
}

static int set_servo_angle(double angle) {
    int pulse = angle_to_pulse_width(angle);
    if (gpioServo(SERVO_PIN, pulse) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse %d\n", pulse);
        return -1;
    }
    return 0;
}

static void log_data(double distance, double angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, distance, angle);
        fflush(log_file);
    }
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Configure pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(SERVO) failed\n");
        gpioTerminate();
        return 1;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50);

    /* Register alert callback for echo pin */
    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFunc failed\n");
        gpioTerminate();
        return 1;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "timestamp,distance_cm,angle_deg\n");
    fflush(log_file);

    /* Install signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    double distance_history[SAMPLE_SIZE] = {0};
    int history_index = 0;
    int servo_angle = 90;

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance();

        if (distance < 0) {
            fprintf(stderr, "Warning: invalid distance reading, using default angle\n");
            distance = -1.0;
        }

        double avg_distance = moving_average(distance, distance_history, SAMPLE_SIZE, &history_index);

        if (avg_distance >= 0) {
            double angle = distance_to_angle(avg_distance);
            if (set_servo_angle(angle) == 0) {
                servo_angle = angle;
            }
        } else {
            servo_angle = 90;
        }

        log_data(avg_distance, servo_angle);

        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);  /* Stop servo PWM */
    gpioSetAlertFunc(ECHO_PIN, NULL);
    if (log_file) {
        fclose(log_file);
    }
