#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define PROXIMITY_HIGH_REG 0x08
#define PROXIMITY_LOW_REG 0x09
#define GPIO_INTERRUPT_PIN 27
#define LOG_FILE "proximity.log"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static int threshold = DEFAULT_THRESHOLD;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_proximity(int handle, int *proximity) {
    int high = i2cReadByteData(handle, PROXIMITY_HIGH_REG);
    if (high < 0) {
        fprintf(stderr, "Error reading proximity high byte: %d\n", high);
        return -1;
    }
    int low = i2cReadByteData(handle, PROXIMITY_LOW_REG);
    if (low < 0) {
        fprintf(stderr, "Error reading proximity low byte: %d\n", low);
        return -1;
    }
    *proximity = (high << 8) | low;
    return 0;
}

static void log_proximity(int proximity, const char *status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file) {
        fprintf(log_file, "%s, %d, %s\n", timestamp, proximity, status);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio;
    (void)tick;
    (void)user_data;

    if (level != 1) return;

    int proximity;
    if (read_proximity(i2c_handle, &proximity) != 0) {
        return;
    }

    if (proximity > threshold) {
        log_proximity(proximity, "ALERT");
    } else {
        log_proximity(proximity, "SAFE");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            char *endptr;
            long val = strtol(argv[i + 1], &endptr, 0);
            if (*endptr != '\0' || val < 0 || val > 0x7F) {
                fprintf(stderr, "Invalid I2C address: %s\n", argv[i + 1]);
                return 1;
            }
            i2c_address = (int)val;
            i++;
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            char *endptr;
            long val = strtol(argv[i + 1], &endptr, 0);
            if (*endptr != '\0' || val < 0) {
                fprintf(stderr, "Invalid threshold: %s\n", argv[i + 1]);
                return 1;
            }
            threshold = (int)val;
            i++;
        } else {
            fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_INTERRUPT_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_INTERRUPT_PIN, PI_PUD_UP);

    if (gpioSetISRFuncEx(GPIO_INTERRUPT_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("Proximity monitoring started. Threshold: %d\n", threshold);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

