#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define PWM_PIN     18

#define MIN_FREQUENCY 200.0
#define MAX_FREQUENCY 2000.0
#define MIN_DISTANCE  2.0
#define MAX_DISTANCE  200.0
#define PWM_DUTY_CYCLE 128  /* 50% of 255 */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Trigger the HC-SR04 and wait for the echo pulse.
 * Returns distance in cm, or -1.0 on timeout / error.
 */
static double get_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger is low before starting */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0;
    }
    gpioDelay(2);

    /* 10 us trigger pulse */
    if (gpioTrigger(TRIGGER_PIN, 10, 1) < 0) {
        fprintf(stderr, "Error: gpioTrigger failed\n");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout 200 ms) */
    timeout_tick = gpioTick() + 200000;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo start timeout\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout 200 ms) */
    timeout_tick = gpioTick() + 200000;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo end timeout\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    double pulse_us = (double)(end_tick - start_tick);
    double distance = (pulse_us * 0.0343) / 2.0;  /* speed of sound 343 m/s */

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f-%.0f]\n",
                distance, MIN_DISTANCE, MAX_DISTANCE);
        return -1.0;
    }
    return distance;
}

/*
 * Map distance to frequency using a logarithmic curve.
 * Returns the mapped frequency, or the previous frequency if out of range.
 */
static double map_distance_to_frequency(double distance) {
    if (distance < 0.0) {
        return -1.0;
    }
    if (distance <= MIN_DISTANCE) {
        return MIN_FREQUENCY;
    }
    if (distance >= MAX_DISTANCE) {
        return MAX_FREQUENCY;
    }
    double log_distance = log10(distance / MIN_DISTANCE + 1.0);
    double scaled = log_distance / log10(MAX_DISTANCE / MIN_DISTANCE + 1.0);
    return MIN_FREQUENCY + scaled * (MAX_FREQUENCY - MIN_FREQUENCY);
}

/*
 * Set PWM frequency and duty cycle.
 * Returns 0 on success, -1 on error.
 */
static int set_tone(double frequency) {
    if (frequency < MIN_FREQUENCY || frequency > MAX_FREQUENCY) {
        fprintf(stderr, "Error: frequency %.2f Hz out of range [%.0f-%.0f]\n",
                frequency, MIN_FREQUENCY, MAX_FREQUENCY);
        return -1;
    }

    int freq = (int)frequency;
    if (gpioSetPWMfrequency(PWM_PIN, freq) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", freq);
        return -1;
    }
    if (gpioPWM(PWM_PIN, PWM_DUTY_CYCLE) < 0) {
        fprintf(stderr, "Error: gpioPWM(%d, %d) failed\n", PWM_PIN, PWM_DUTY_CYCLE);
        return -1;
    }
    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(PWM_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    double previous_frequency = MIN_FREQUENCY;
    int pwm_initialized = 0;

    printf("Theremin ready. Move your hand between %.0f and %.0f cm from the sensor.\n",
           MIN_DISTANCE, MAX_DISTANCE);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        double distance = get_distance();

        if (distance < 0.0) {
            /* Error or out-of-range: keep previous frequency */
            fprintf(stderr, "Warning: using previous frequency %.2f Hz\n",
                    previous_frequency);
        } else {
            double frequency = map_distance_to_frequency(distance);
            if (set_tone(frequency) < 0) {
                fprintf(stderr, "Warning: failed to set tone\n");
            } else {
                previous_frequency = frequency;
            }
