        gpioDelay(10000);  /* 10 ms loop delay */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (pwm_initialized) {
        gpioPWM(PWM_PIN, 0);
    }
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

