#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_FREQ    200
#define MAX_FREQ    2000
#define MIN_DIST    5.0f
#define MAX_DIST    50.0f
#define MAX_RANGE   400.0f
#define LOOP_DELAY  10000  /* 10 ms */
#define TIMEOUT_US  100000 /* 100 ms */

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read distance from HC-SR04.
 * Returns distance in cm, or -1.0 on timeout/error.
 */
static float read_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0f;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to write trigger high\n");
        return -1.0f;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout if no object detected) */
    timeout_tick = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Warning: timeout waiting for echo start\n");
            return -1.0f;
        }
        gpioDelay(1);
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    timeout_tick = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Warning: timeout waiting for echo end\n");
            return -1.0f;
        }
        gpioDelay(1);
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float distance = (diff / 1000000.0f) * 34300.0f / 2.0f;

    /* Sanity check: HC-SR04 range is 2 cm to 400 cm */
    if (distance < 2.0f || distance > MAX_RANGE) {
        fprintf(stderr, "Warning: distance %.2f cm out of valid range\n", distance);
        return -1.0f;
    }
    return distance;
}

/*
 * Map distance to frequency using linear interpolation.
 * Returns frequency in Hz, clamped to [MIN_FREQ, MAX_FREQ].
 */
static int map_distance_to_frequency(float distance) {
    if (distance <= MIN_DIST) {
        return MIN_FREQ;
    }
    if (distance >= MAX_DIST) {
        return MAX_FREQ;
    }
    float frac = (distance - MIN_DIST) / (MAX_DIST - MIN_DIST);
    return (int)(MIN_FREQ + frac * (MAX_FREQ - MIN_FREQ));
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50);

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }

    printf("Theremin running. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = read_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Error: sensor read failed, using last valid distance\n");
            distance = -1.0f;
        }

        int frequency = map_distance_to_frequency(distance);

        /* Drive buzzer via hardware PWM (50% duty cycle) */
        if (gpioHardwarePWM(BUZZER_PIN, frequency, 500000) < 0) {
            fprintf(stderr, "Error: gpioHardwarePWM failed\n");
        }

        printf("Distance: %.2f cm, Frequency: %d Hz\n", distance, frequency);

        gpioDelay(LOOP_DELAY);
    }

    /* Clean shutdown */
    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    gpioTerminate();
    printf("\nTheremin stopped.\n");
    return EXIT_SUCCESS;
}

