#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0
#define CS_PIN      8
#define LOG_FILE    "distance_log.csv"
#define MAX_RANGE   5000
#define MIN_RANGE   200
#define READ_DELAY  100000

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_write_reg(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x3F), (char)value };
    char rx[2] = { 0 };
    if (gpioWrite(CS_PIN, 0) < 0) return -1;
    int ret = spiXfer(spi_handle, tx, rx, 2);
    gpioWrite(CS_PIN, 1);
    if (ret != 2) return -1;
    return 0;
}

static int spi_read_reg(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0 };
    if (gpioWrite(CS_PIN, 0) < 0) return -1;
    int ret = spiXfer(spi_handle, tx, rx, 2);
    gpioWrite(CS_PIN, 1);
    if (ret != 2) return -1;
    *value = (uint8_t)rx[1];
    return 0;
}

static int init_sensor(void) {
    if (spi_write_reg(0x01, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write mode register 0x01\n");
        return -1;
    }
    if (spi_write_reg(0x02, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write range register 0x02\n");
        return -1;
    }
    return 0;
}

static int read_distance(uint16_t *distance) {
    if (spi_write_reg(0x00, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to trigger measurement\n");
        return -1;
    }
    gpioDelay(1000);
    uint8_t lo, hi;
    if (spi_read_reg(0x0C, &lo) < 0) return -1;
    if (spi_read_reg(0x0D, &hi) < 0) return -1;
    *distance = ((uint16_t)hi << 8) | lo;
    return 0;
}

static void log_distance(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%u\n", timestamp, (unsigned)distance);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1);
    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Distance_mm\n");
        fflush(log_file);
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("Starting obstacle avoidance. Press Ctrl+C to stop.\n");
    while (!terminate) {
        uint16_t distance;
        if (read_distance(&distance) == 0) {
            if (distance >= MIN_RANGE && distance <= MAX_RANGE) {
                log_distance(distance);
            } else {
                fprintf(stderr, "Warning: Out-of-range reading (%u mm)\n", distance);
            }
        } else {
            fprintf(stderr, "Error: SPI read failed\n");
        }
        gpioDelay(READ_DELAY);
    }
    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

