#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1175_I2C_ADDR 0x60
#define SI1175_REG_ALS_VIS_DATA0 0x22
#define SI1175_REG_ALS_VIS_DATA1 0x23
#define LOG_FILE_NAME "proximity_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t *value) {
    if (read(fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint16_t *value) {
    uint8_t low, high;
    if (i2c_read_byte(fd, &low) < 0) {
        return -1;
    }
    if (i2c_read_byte(fd, &high) < 0) {
        return -1;
    }
    *value = ((uint16_t)high << 8) | low;
    return 0;
}

static int init_i2c(void) {
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1175_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                SI1175_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int read_als_visible(uint16_t *als_value) {
    if (i2c_read_word(g_i2c_fd, als_value) < 0) {
        fprintf(stderr, "Error reading ALS visible data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int log_data(uint16_t als_value) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%u\n", timestamp, (unsigned)als_value) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (fprintf(g_log_file, "timestamp,als_visible\n") < 0) {
        fprintf(stderr, "Error writing CSV header: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error flushing CSV header: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting Si1175 proximity logging. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t als_value = 0;

        if (read_als_visible(&als_value) < 0) {
            fprintf(stderr, "Error reading ALS visible value. Retrying in %d seconds.\n",
                    SAMPLE_INTERVAL_SEC);
        } else {
            if (log_data(als_value) < 0) {
                fprintf(stderr, "Error logging data. Retrying in %d seconds.\n",
                        SAMPLE_INTERVAL_SEC);
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully.\n");
    cleanup();
    return EXIT_SUCCESS;
}

