#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

#define SI1145_ADDR 0x60
#define I2C_BUS 1
#define MAX_RETRIES 3
#define LOG_FILE "proximity_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %d\n", value, reg, result);
        return -1;
    }
    return 0;
}

static int init_si1145(int handle) {
    int result;

    result = write_register(handle, 0x07, 0x03);
    if (result < 0) return -1;
    result = write_register(handle, 0x06, 0x02);
    if (result < 0) return -1;
    result = write_register(handle, 0x1A, 0x00);
    if (result < 0) return -1;
    result = write_register(handle, 0x21, 0x0B);
    if (result < 0) return -1;
    result = write_register(handle, 0x24, 0x00);
    if (result < 0) return -1;
    result = write_register(handle, 0x22, 0x49);
    if (result < 0) return -1;
    result = write_register(handle, 0x0C, 0x03);
    if (result < 0) return -1;
    result = write_register(handle, 0x0F, 0x0F);
    if (result < 0) return -1;
    result = write_register(handle, 0x11, 0x03);
    if (result < 0) return -1;
    result = write_register(handle, 0x0D, 0x07);
    if (result < 0) return -1;
    result = write_register(handle, 0x80, 0x03);
    if (result < 0) return -1;

    return 0;
}

static int read_proximity(int handle, uint16_t *proximity) {
    int low, high;

    low = i2cReadByteData(handle, 0x16);
    if (low < 0) {
        fprintf(stderr, "Error reading PS1_DATA0: %d\n", low);
        return -1;
    }

    high = i2cReadByteData(handle, 0x17);
    if (high < 0) {
        fprintf(stderr, "Error reading PS1_DATA1: %d\n", high);
        return -1;
    }

    *proximity = (uint16_t)((high << 8) | low);
    return 0;
}

static void log_data(uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %u\n", timestamp, proximity);
    fflush(log_file);
}

static void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

int main(void) {
    int retries;
    uint16_t proximity;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_si1145(i2c_handle) < 0) {
        fprintf(stderr, "Error initializing Si1145 sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && running) {
            if (read_proximity(i2c_handle, &proximity) == 0) {
                success = 1;
                break;
            }
            retries++;
            fprintf(stderr, "Retry %d/%d...\n", retries, MAX_RETRIES);
            gpioDelay(100000);
        }

        if (success) {
            log_data(proximity);
        } else {
            log_error("Failed to read proximity data after multiple retries");
        }

        gpioDelay(1000000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

