#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define SPEED_OF_SOUND 34300.0
#define MAX_DISTANCE 200.0
#define MIN_DISTANCE 20.0

#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500

#define ECHO_TIMEOUT_US 30000

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

double measure_distance() {
    uint32_t start_tick, end_tick;
    int timeout = 0;

    trigger_sensor();

    while (gpioRead(ECHO_PIN) == 0) {
        gpioDelay(1);
        timeout++;
        if (timeout > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin did not go high (timeout).\n");
            return -1.0;
        }
    }

    start_tick = gpioTick();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin did not go low (timeout).\n");
            return -1.0;
        }
    }

    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    double distance = (diff / 1000000.0) * SPEED_OF_SOUND / 2.0;

    return distance;
}

void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    int pulse_width = SERVO_MIN_PULSE + (angle * (SERVO_MAX_PULSE - SERVO_MIN_PULSE) / 180);
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(500000);

    signal(SIGINT, signal_handler);

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (program_running) {
        double distance = measure_distance();

        if (distance < 0) {
            fprintf(stderr, "Error: Failed to measure distance.\n");
            gpioDelay(100000);
            continue;
        }

        printf("Distance: %.2f cm\n", distance);

        int angle;
        if (distance >= MAX_DISTANCE) {
            angle = 0;
        } else if (distance <= MIN_DISTANCE) {
            angle = 180;
        } else {
            angle = (int)((MAX_DISTANCE - distance) / (MAX_DISTANCE - MIN_DISTANCE) * 90);
        }

        set_servo_angle(angle);

        gpioDelay(100000);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Parking Assist System stopped.\n");

    return 0;
}

