#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define MIN_ANGLE_DEG   0
#define MAX_ANGLE_DEG   180
#define SERVO_MIN_US    500
#define SERVO_MAX_US    2500
#define ECHO_TIMEOUT_US 50000
#define LOOP_DELAY_US   100000
#define TRIGGER_PULSE_US 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set SERVO_PIN %d as output\n", SERVO_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static double measure_distance(void) {
    uint32_t start_tick, end_tick;
    int timeout;

    trigger_sensor();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 0) {
        if (++timeout > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo start timeout\n");
            return -1.0;
        }
        gpioDelay(1);
    }
    start_tick = gpioTick();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        if (++timeout > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo end timeout\n");
            return -1.0;
        }
        gpioDelay(1);
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    if (pulse_us == 0) {
        fprintf(stderr, "Error: zero pulse duration\n");
        return -1.0;
    }
    return (double)pulse_us * 0.0343 / 2.0;
}

static int distance_to_angle(double distance) {
    if (distance < MIN_DISTANCE_CM) return MIN_ANGLE_DEG;
    if (distance > MAX_DISTANCE_CM) return MAX_ANGLE_DEG;
    return (int)(((distance - MIN_DISTANCE_CM) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM)) * (MAX_ANGLE_DEG - MIN_ANGLE_DEG) + MIN_ANGLE_DEG);
}

static void set_servo_angle(int angle) {
    if (angle < MIN_ANGLE_DEG) angle = MIN_ANGLE_DEG;
    if (angle > MAX_ANGLE_DEG) angle = MAX_ANGLE_DEG;
    int pulse_us = SERVO_MIN_US + (int)((double)angle / MAX_ANGLE_DEG * (SERVO_MAX_US - SERVO_MIN_US));
    gpioServo(SERVO_PIN, pulse_us);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() < 0) {
        return 1;
    }

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Error: distance measurement failed\n");
        } else {
            int angle = distance_to_angle(distance);
            set_servo_angle(angle);
            printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
        }
        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nParking Assist System stopped.\n");
    return 0;
}

