#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define TEMP_REG 0x01
#define HUMID_REG 0x02
#define CONFIG_REG 0x03
#define CONFIG_VALUE 0x00
#define CONVERSION_DELAY_US 10000
#define POLL_INTERVAL_US 2000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, SI7005_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int configure_sensor(void) {
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, CONFIG_VALUE) < 0) {
        fprintf(stderr, "Error writing CONFIG register 0x%02X\n", CONFIG_REG);
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);
    return 0;
}

static int read_temperature(float *temperature) {
    int raw = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading temperature register 0x%02X: %d\n", TEMP_REG, raw);
        return -1;
    }
    *temperature = (175.72f * (float)raw) / 65536.0f - 46.85f;
    return 0;
}

static int read_humidity(float *humidity) {
    int raw = i2cReadWordData(i2c_handle, HUMID_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading humidity register 0x%02X: %d\n", HUMID_REG, raw);
        return -1;
    }
    *humidity = (125.0f * (float)raw) / 65536.0f - 6.0f;
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (configure_sensor() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        float temperature, humidity;
        if (read_temperature(&temperature) == 0 && read_humidity(&humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Sensor read error, attempting I2C recovery...\n");
            if (init_i2c() != 0) {
                fprintf(stderr, "I2C re-init failed, exiting\n");
                break;
            }
            if (configure_sensor() != 0) {
                fprintf(stderr, "Sensor re-config failed, exiting\n");
                break;
            }
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

