#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP31_ADDR     0x28
#define TRIGGER_CMD    0x2196
#define SAMPLE_PERIOD_US 100000  /* 100 ms */
#define MAX_RETRIES    3
#define RETRY_DELAY_US 100000    /* 100 ms initial backoff */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; no async-unsafe operations         */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 2-byte command to the SDP31                                */
/* ------------------------------------------------------------------ */
static int sdp31_write_cmd(int handle, uint8_t msb, uint8_t lsb)
{
    char buf[2] = { (char)msb, (char)lsb };
    int rc = i2cWriteDevice(handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(0x%02X%02X) failed: %d\n",
                msb, lsb, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes from the SDP31 (pressure MSB, pressure LSB, CRC,        */
/* temperature MSB, temperature LSB, CRC)                            */
/* ------------------------------------------------------------------ */
static int sdp31_read_data(int handle, uint8_t *data)
{
    int rc = i2cReadDevice(handle, (char *)data, 6);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed: %d\n", rc);
        return -1;
    }
    if (rc != 6) {
        fprintf(stderr, "[ERROR] Short read: got %d bytes, expected 6\n", rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger continuous measurement and read one sample                 */
/* ------------------------------------------------------------------ */
static int sdp31_read_sample(int handle, float *pressure_pa, float *temp_c)
{
    uint8_t data[6];

    if (sdp31_write_cmd(handle, TRIGGER_CMD[0], TRIGGER_CMD[1]) != 0)
        return -1;

    gpioDelay(1000);  /* 1 ms conversion wait */

    if (sdp31_read_data(handle, data) != 0)
        return -1;

    /* CRC checks (optional but good practice) */
    if (data[2] != ((data[0] + data[1]) & 0xFF)) {
        fprintf(stderr, "[WARN] Pressure CRC mismatch\n");
        return -1;
    }
    if (data[5] != ((data[3] + data[4]) & 0xFF)) {
        fprintf(stderr, "[WARN] Temperature CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temp     = (int16_t)((data[3] << 8) | data[4]);

    *pressure_pa    = (float)raw_pressure / 60.0f;
    *temp_c         = (float)raw_temp / 200.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append one CSV line to the log file                                */
/* ------------------------------------------------------------------ */
static int log_sample(FILE *fp, float pressure, float temp)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temp) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush log failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --- */
    g_i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SDP31_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file --- */
    g_log_file = fopen("airflow.log", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open airflow.log for append\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction failed; Ctrl+C still works\n");
    }

    printf("SDP31 airflow logger started. Press Ctrl+C to stop.\n");

    /* --- main loop --- */
    while (g_running) {
        float pressure = 0.0f, temp = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (sdp31_read_sample(g_i2c_handle, &pressure, &temp) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "[WARN] Read attempt %d/%d failed\n",
                    attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1) {
                gpioDelay(RETRY_DELAY_US);
                RETRY_DELAY_US *= 2;  /* exponential backoff */
            }
        }

        if (ok) {
            if (log_sample(g_log_file, pressure, temp) != 0) {
                fprintf(stderr, "[ERROR] Logging failed; continuing\n");
            }
        } else {
            fprintf(stderr, "[ERROR] All %d attempts failed; skipping sample\n",
                    MAX_RETRIES);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

