#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7015_ADDR 0x40
#define CMD_TEMP_NOHOLD 0xF3
#define CMD_HUMID_NOHOLD 0xF5
#define LOG_FILE "sensor_data.txt"
#define SAMPLE_INTERVAL_SEC 5
#define MEAS_TIMEOUT_MS 20

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_measurement(int handle, uint8_t cmd, uint16_t *raw) {
    char buf[2];
    int rc;

    rc = i2cWriteByte(handle, cmd);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteByte(0x%02X) failed: %s\n", cmd, pigpio_error(rc));
        return -1;
    }

    for (int i = 0; i < MEAS_TIMEOUT_MS; i++) {
        rc = i2cReadDevice(handle, buf, 2);
        if (rc == 2) {
            *raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }
        if (rc < 0) {
            fprintf(stderr, "i2cReadDevice failed: %s\n", pigpio_error(rc));
            return -1;
        }
        gpioDelay(1000); /* 1 ms */
    }
    fprintf(stderr, "Measurement timeout (cmd 0x%02X)\n", cmd);
    return -1;
}

static float convert_temperature(uint16_t raw) {
    return (175.72f * (float)raw / 65536.0f) - 46.85f;
}

static float convert_humidity(uint16_t raw) {
    float rh = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (rh < 0.0f) rh = 0.0f;
