#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR     0x25
#define MEASURE_CMD     0x362F
#define LOG_FILE        "airflow_data.txt"
#define SAMPLE_PERIOD_US 100000
#define MEASURE_DELAY_US 45000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else           crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += (int)n;
    }
    return 0;
}

static int read_sdp800(int fd, float *pressure, float *temperature) {
    if (i2c_write_cmd(fd, MEASURE_CMD) < 0) return -1;
    usleep(MEASURE_DELAY_US);

    uint8_t buf[9];
    if (i2c_read_data(fd, buf, 9) < 0) return -1;

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Scale-factor CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_factor    = (int16_t)((buf[6] << 8) | buf[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor (0)\n");
        return -1;
    }

    *pressure    = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temperature / 200.0f - 45.0f;
    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            pressure, temperature);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", SDP800_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,Pressure(Pa),Temperature(C)\n");
        fflush(g_log_fp);
    }

    printf("SDP800 monitoring started. Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        float pressure, temperature;
        if (read_sdp800(g_i2c_fd, &pressure, &temperature) == 0) {
            log_data(g_log_fp, pressure, temperature);
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Read failed; continuing.\n");
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

