static int read_sensor(uint8_t cmd, uint16_t *raw_out) {
    char buf[2];
    int result, retries = I2C_RETRIES;

    while (retries > 0) {
        result = i2cWriteByte(i2c_handle, cmd);
        if (result < 0) {
            fprintf(stderr, "I2C write failed (cmd 0x%02X), retry %d/%d\n", cmd, I2C_RETRIES - retries + 1, I2C_RETRIES);
