#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1

#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_GET_DATA_READY_STATUS 0xE4B8

#define MEASUREMENT_INTERVAL_SEC 5
#define STARTUP_DELAY_SEC 1

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int send_command(uint16_t cmd) {
    uint8_t buf[2];
    buf[0] = (cmd >> 8) & 0xFF;
    buf[1] = cmd & 0xFF;
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to write command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int read_measurement(uint16_t *co2, float *temperature, float *humidity) {
    uint8_t buf[9];
    if (i2cReadDevice(i2c_handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "Error: Failed to read 9 bytes from SCD40\n");
        return -1;
    }
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: CO2 CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: Humidity CRC mismatch\n");
        return -1;
    }
    uint16_t raw_co2 = (buf[0] << 8) | buf[1];
    uint16_t raw_temp = (buf[3] << 8) | buf[4];
    uint16_t raw_hum = (buf[6] << 8) | buf[7];
    *co2 = raw_co2;
    *temperature = -45.0f + 175.0f * (float)raw_temp / 65535.0f;
    *humidity = 100.0f * (float)raw_hum / 65535.0f;
    return 0;
}

static int check_data_ready(int *ready) {
    if (send_command(CMD_GET_DATA_READY_STATUS) != 0)
        return -1;
    gpioDelay(2000);
    uint8_t buf[3];
    if (i2cReadDevice(i2c_handle, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: Failed to read data-ready status\n");
        return -1;
    }
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: Data-ready CRC mismatch\n");
        return -1;
    }
    uint16_t status = (buf[0] << 8) | buf[1];
    *ready = (status & 0x07FF) != 0;
    return 0;
}

static int log_data(uint16_t co2, float temp, float hum) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    if (fprintf(log_file, "%s,%u,%.2f,%.2f\n", ts, co2, temp, hum) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        send_command(CMD_STOP_PERIODIC_MEASUREMENT);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at addr 0x%02X\n", I2C_BUS, SCD40_I2C_ADDR);
        gpioTerminate();
        return 1;
    }
    log_file = fopen("air_quality.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open air_quality.log\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (send_command(CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement\n");
        cleanup();
        return 1;
    }
    gpioDelay(STARTUP_DELAY_SEC * 1000000);
    signal(SIGINT, signal_handler);
    while (!terminate) {
        int ready = 0;
        if (check_data_ready(&ready) != 0) {
            fprintf(stderr, "Warning: Data-ready check failed, retrying...\n");
            gpioDelay(1000000);
            continue;
        }
        if (ready) {
            uint16_t co2;
            float temp, hum;
            if (read_measurement(&co2, &temp, &hum) == 0) {
                if (log_data(co2, temp, hum) != 0)
                    fprintf(stderr, "Warning: Failed to log data\n");
            } else {
                fprintf(stderr, "Warning: Failed to read measurement\n");
            }
        }
        for (int i = 0; i < MEASUREMENT_INTERVAL_SEC && !terminate; i++)
            gpioDelay(1000000);
    }
    cleanup();
    return 0;
}

