#define CMD_STOP_PERIODIC      0x3F86
#define CMD_GET_DATA_READY     0xE4B8
#define CMD_READ_MEASUREMENT   0xEC05
#define CMD_READ_SENSOR_ID     0xE087
#define SENSOR_ID_EXPECTED     0x0401
#define LED_GPIO               17
#define CO2_THRESHOLD          1000
#define BUFFER_SIZE            20
#define MEASUREMENT_INTERVAL   5

#define CRC8_POLYNOMIAL        0x31
#define CRC8_INIT              0xFF

typedef struct {
    uint16_t co2;
    float    temperature;
    float    humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static circular_buffer_t g_buffer;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int handle, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
