#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 5000000  /* 5 seconds */
#define TIMEOUT_US 50000            /* 50 ms timeout for edge waits */
#define MAX_CONSECUTIVE_ERRORS 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read temperature from TMP05 on GPIO_PIN.
 * Returns 0 on success and stores Celsius in *temp_c.
 * Returns -1 on timeout, -2 on division-by-zero, -3 on out-of-range.
 */
static int read_temperature(int gpio_pin, float *temp_c) {
    uint32_t t0, t1;
    int level;
    uint32_t elapsed;

    /* Wait for falling edge (start of high pulse) */
    t0 = gpioTick();
    level = gpioRead(gpio_pin);
    while (level == 1) {
        if ((gpioTick() - t0) > TIMEOUT_US) {
            return -1;  /* timeout waiting for falling edge */
        }
        level = gpioRead(gpio_pin);
    }

    /* Wait for rising edge (end of high pulse) */
    t1 = gpioTick();
    level = gpioRead(gpio_pin);
    while (level == 0) {
        if ((gpioTick() - t1) > TIMEOUT_US) {
            return -1;  /* timeout waiting for rising edge */
        }
        level = gpioRead(gpio_pin);
    }

    /* Calculate pulse widths */
    uint32_t tl = gpioTick();
    uint32_t th = 0;
    while (gpioTick() - tl < TIMEOUT_US) {
        level = gpioRead(gpio_pin);
        if (level == 1) {
            th = gpioTick();
            break;
        }
    }
    if (th == 0) {
        return -1;  /* sensor may be stuck low */
    }

    /* Calculate temperature using TMP05 formula */
    float temp = 4215.0f - (2143.0f * (float)th / (float)tl);
    *temp_c = temp;
    return 0;
}

/* Log a temperature reading with ISO-8601 timestamp */
static void log_temperature(float temp_c) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, temp_c);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

/* Log a sensor-malfunction entry */
static void log_malfunction(void) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    if (log_file != NULL) {
        fprintf(log_file, "%s, SENSOR MALFUNCTION\n", timestamp);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

int main(void) {
    float temperature;
    int consecutive_errors = 0;

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    /* Configure GPIO pin as input */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Temperature monitoring started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (running) {
        int ret = read_temperature(GPIO_PIN, &temperature);

        if (ret == 0) {
            consecutive_errors = 0;
            if (temperature < -40.0f || temperature > 150.0f) {
                fprintf(stderr, "Warning: Temperature out of range: %.2f C\n", temperature);
            }
            log_temperature(temperature);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error reading temperature (ret=%d, consecutive=%d)\n", ret, consecutive_errors);

            if (ret == -1) {
                /* Timeout: sensor may be absent or line stuck */
                fprintf(stderr, "Sensor timeout: check wiring and sensor presence.\n");
            } else if (ret == -2) {
                fprintf(stderr, "Division by zero in temperature calculation.\n");
            }

            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                log_malfunction();
                fprintf(stderr, "Sensor malfunction detected. Logging malfunction entry.\n");
                consecutive_errors = 0;  /* reset to avoid spamming log */
            }
        }

        /* Wait for next sample interval */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

