            consecutive_errors = 0;
            if (temperature < -40.0f || temperature > 150.0f) {
                fprintf(stderr, "Warning: Temperature out of range: %.2f C\n", temperature);
            }
            log_temperature(temperature);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error reading temperature (ret=%d, consecutive=%d)\n", ret, consecutive_errors);

            if (ret == -1) {
                /* Timeout: sensor may be absent or line stuck */
                fprintf(stderr, "Sensor timeout: check wiring and sensor presence.\n");
            } else if (ret == -2) {
                fprintf(stderr, "Division by zero in temperature calculation.\n");
            }

            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                log_malfunction();
                fprintf(stderr, "Sensor malfunction detected. Logging malfunction entry.\n");
                consecutive_errors = 0;  /* reset to avoid spamming log */
            }
        }

        /* Wait for next sample interval */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

