#define SHT35_ADDR 0x44
#define I2C_BUS 1
#define MEASURE_CMD_HIGH_REP 0x24
#define MEASURE_CMD_ARG 0x00
#define MEASUREMENT_DELAY_US 15000
#define LOG_INTERVAL_S 5
#define MAX_RETRIES 3
#define RETRY_DELAY_S 1

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sht35(int handle, float *temp, float *hum) {
    uint8_t cmd[2] = {MEASURE_CMD_HIGH_REP, MEASURE_CMD_ARG};
    uint8_t buf[6];
    int rc;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cWriteDevice(handle, (char *)cmd, 2);
        if (rc < 0) {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", attempt + 1, rc);
            if (attempt < MAX_RETRIES - 1)
                sleep(RETRY_DELAY_S);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        rc = i2cReadDevice(handle, (char *)buf, 6);
        if (rc < 0) {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", attempt + 1, rc);
            if (attempt < MAX_RETRIES - 1)
                sleep(RETRY_DELAY_S);
            continue;
        }

        if (crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "Temperature CRC mismatch (attempt %d)\n", attempt + 1);
            if (attempt < MAX_RETRIES - 1)
                sleep(RETRY_DELAY_S);
            continue;
        }

        if (crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "Humidity CRC mismatch (attempt %d)\n", attempt + 1);
            if (attempt < MAX_RETRIES - 1)
                sleep(RETRY_DELAY_S);
            continue;
        }

        uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
        uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

        *temp = -45.0f + 175.0f * (float)t_raw / 65535.0f;
        *hum = 100.0f * (float)h_raw / 65535.0f;
        return 0;
    }

    fprintf(stderr, "SHT35 read failed after %d attempts\n", MAX_RETRIES);
    return -1;
}

static void apply_offset(float *t, float *h) {
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    double t_utc = (double)tm_utc.tm_gmtoff / 60.0;

    double phase = t_utc / 3600.0;
    double offset_t = 2.0 * sin(2.0 * M_PI * phase);
    double offset_h = 5.0 * sin(2.0 * M_PI * phase);

    *t += offset_t;
    *h += offset_h;
}

