        if (read_sht35(i2c_handle, &temp, &hum) == 0) {
            apply_offset(&temp, &hum);
            log_data(log_file, temp, hum);
        } else {
            log_data(log_file, NAN, NAN);
        }
        sleep(LOG_INTERVAL_S);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

