#define I2C_BUS "/dev/i2c-1"
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F
#define CONVERSION_TIME_MS 45
#define LOG_FILE "airflow.csv"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
