static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

static int read_sdp810(int fd, float *pressure, float *temperature) {
    if (i2c_write_cmd(fd, MEASURE_CMD) < 0)
        return -1;

    usleep(CONVERSION_TIME_MS * 1000);

    uint8_t data[9];
    if (i2c_read_bytes(fd, data, 9) < 0)
        return -1;

    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[6], 2) != data[8]) {
        fprintf(stderr, "Scale factor CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temperature = (int16_t)((data[3] << 8) | data[4]);
    uint16_t scale_factor = (uint16_t)((data[6] << 8) | data[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor\n");
        return -1;
    }

    *pressure = (float)raw_pressure / scale_factor;
    *temperature = (float)raw_temperature / 200.0f;
    return 0;
}

