#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT35_ADDR     0x44
#define MEASURE_CMD    0x2400  /* single-shot, high repeatability, clock-stretching disabled */
#define MEASURE_DELAY_US 15000  /* 15 ms */
#define SAMPLE_INTERVAL_S 5
#define CSV_FILE       "environment.csv"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF, no final XOR */
static uint8_t sht35_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static int sht35_read(int handle, float *temperature, float *humidity)
{
    uint8_t cmd[2] = {
        (uint8_t)((MEASURE_CMD >> 8) & 0xFF),
        (uint8_t)(MEASURE_CMD & 0xFF)
    };
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed\n");
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed\n");
        return -1;
    }

    if (sht35_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }
    if (sht35_crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity   = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

static int log_to_csv(const char *filename, float temperature, float humidity)
{
    FILE *fp = fopen(filename, "r");
    long pos = ftell(fp);
    if (pos < 0) {
        fp = fopen(filename, "w");
        if (!fp) {
            fprintf(stderr, "[ERROR] Cannot create %s\n", filename);
            return -1;
        }
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
    } else {
        if (pos == 0)
            fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
        fseek(fp, 0, SEEK_END);
    }
    fclose(fp);

    fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] Cannot open %s for append\n", filename);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);

    if (fclose(fp) != 0) {
        fprintf(stderr, "[ERROR] fclose failed on %s\n", filename);
        return -1;
    }
    return 0;
}

