    if (handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus %d, addr 0x%02X)\n", I2C_BUS, SHT35_ADDR);
        gpioTerminate();
        return 1;
    }

    printf("SHT35 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float temperature, humidity;

