static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int read_measurement(int fd, uint8_t cmd, uint16_t *raw) {
    uint8_t buf[3];
    int elapsed = 0;
    while (elapsed < POLL_TIMEOUT_MS) {
        if (i2c_write_cmd(fd, cmd) < 0)
            return -1;
        usleep(2000);
        if (i2c_read_bytes(fd, buf, 3) < 0)
            return -1;
        if (crc8(buf, 2) == buf[2]) {
            *raw = (uint16_t)((buf[0] << 8) | buf[1]);
            return 0;
        }
        fprintf(stderr, "CRC mismatch on cmd 0x%02X (got 0x%02X, expected 0x%02X)\n",
                cmd, crc8(buf, 2), buf[2]);
        return -1;
    }
    fprintf(stderr, "Timeout waiting for measurement cmd 0x%02X\n", cmd);
    return -1;
}

static int read_sensor(int fd, float *temp, float *hum) {
    uint16_t raw_h, raw_t;

    if (read_measurement(fd, CMD_MEASURE_HUM, &raw_h) < 0)
        return -1;
    if (read_measurement(fd, CMD_MEASURE_TEMP, &raw_t) < 0)
        return -1;

    *hum = 125.0f * raw_h / 65536.0f - 6.0f;
    *temp = 175.72f * raw_t / 65536.0f - 46.85f;
