        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", SI7021_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (i2c_write_cmd(g_i2c_fd, CMD_RESET) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X; check wiring.\n", SI7021_ADDR);
        close(g_i2c_fd);
        return 1;
    }
    usleep(15000);

    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        fp = fopen(LOG_FILE, "w");
        if (fp) {
            fprintf(fp, "timestamp,temperature_C,humidity_percent\n");
            fclose(fp);
        } else {
            fprintf(stderr, "Failed to create %s: %s\n", LOG_FILE, strerror(errno));
            close(g_i2c_fd);
            return 1;
        }
    } else {
        fclose(fp);
    }

    printf("Greenhouse monitor started. Logging to %s every %d s. Press Ctrl+C to exit.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);

    while (g_running) {
        float temp, hum;
        if (read_sensor(g_i2c_fd, &temp, &hum) == 0) {
            printf("T=%.2f C  H=%.2f %%\n", temp, hum);
            log_data(temp, hum);
        } else {
            fprintf(stderr, "Sensor read failed; resetting.\n");
            reset_sensor(g_i2c_fd);
            if (read_sensor(g_i2c_fd, &temp, &hum) != 0) {
                fprintf(stderr, "Sensor still unresponsive after reset.\n");
            } else {
                printf("T=%.2f C  H=%.2f %%\n", temp, hum);
                log_data(temp, hum);
            }
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down cleanly.\n");
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    return 0;
}

