#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define PWM_RANGE 1000000
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL_US 100000

/* Honeywell Zephyr HAFBLF0100A2AX5 transfer function (approximate) */
#define MIN_FLOW_RATE 0.0f
#define MAX_FLOW_RATE 10.0f
#define MIN_COUNTS 1638.0f
#define MAX_COUNTS 14745.0f

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_sensor_data(int handle, uint16_t *raw_data) {
    char buffer[2];
    int bytes_read = i2cReadDevice(handle, buffer, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }
    *raw_data = ((uint16_t)(buffer[0] & 0x3F) << 8) | (uint16_t)buffer[1];
    return 0;
}

static float calculate_flow_rate(uint16_t raw_data) {
    float counts = (float)raw_data;
    float flow_rate = MIN_FLOW_RATE + (MAX_FLOW_RATE - MIN_FLOW_RATE) *
                      (counts - MIN_COUNTS) / (MAX_COUNTS - MIN_COUNTS);
    return flow_rate;
}

static void set_fan_speed(float flow_rate) {
    if (flow_rate < MIN_FLOW_RATE) flow_rate = MIN_FLOW_RATE;
    if (flow_rate > MAX_FLOW_RATE) flow_rate = MAX_FLOW_RATE;
    int duty_cycle = (int)((flow_rate / MAX_FLOW_RATE) * PWM_RANGE);
    if (gpioPWM(FAN_GPIO, duty_cycle) < 0) {
        fprintf(stderr, "Error setting PWM duty cycle: %s\n", strerror(errno));
    }
}

static void log_data(FILE *fp, float flow_rate) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO mode: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting flow monitoring. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t raw_data;
        if (read_sensor_data(i2c_handle, &raw_data) == 0) {
            float flow_rate = calculate_flow_rate(raw_data);
            set_fan_speed(flow_rate);
            log_data(log_file, flow_rate);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

