#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define TEMP_REG       0x00
#define LED_GPIO       17
#define BUFFER_SIZE    10
#define THRESHOLD_C    28.0f
#define SAMPLE_PERIOD  1.0f

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

typedef struct {
    float buf[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value)
{
    cb->buf[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float cb_average(const CircularBuffer *cb)
{
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++)
        sum += cb->buf[i];
    return sum / (float)cb->count;
}

static int read_temperature(int handle, float *out_temp)
{
    int raw = i2cReadWordData(handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "I2C read error (pigpio code %d)\n", raw);
        return -1;
    }
    /* pigpio returns the word in little-endian byte order: [low_byte, high_byte] */
    uint16_t word = ((uint16_t)raw & 0xFF) | (((uint16_t)raw >> 8) & 0xFF) << 8;
    /* STLM75: 9-bit two's-complement, low 7 bits are 0 */
    int16_t value = (int16_t)(word >> 7);
    *out_temp = (float)value / 2.0f;
    return 0;
}

int main(void)
{
    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed (pigpio code %d)\n", handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    CircularBuffer cb;
    cb_init(&cb);

    while (g_running) {
        float temp;
        if (read_temperature(handle, &temp) == 0) {
            cb_add(&cb, temp);
            float avg = cb_average(&cb);
            int led_state = (avg > THRESHOLD_C) ? 1 : 0;
            gpioWrite(LED_GPIO, led_state);
            printf("Temperature: %.2f C, Average: %.2f C, LED: %s\n",
                   temp, avg, led_state ? "ON" : "OFF");
        } else {
            /* On I2C error, turn off the LED for safety and retry next cycle */
            gpioWrite(LED_GPIO, 0);
        }
        time_sleep(SAMPLE_PERIOD);
    }

    /* Clean shutdown */
    gpioWrite(LED_GPIO, 0);
    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

