#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD30_I2C_ADDR 0x61
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define CO2_THRESHOLD_LOW 800
#define CO2_THRESHOLD_HIGH 1200
#define MEASUREMENT_INTERVAL_SEC 2

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t scd30_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int scd30_write_command(uint16_t cmd) {
    uint8_t buf[2];
    buf[0] = (cmd >> 8) & 0xFF;
    buf[1] = cmd & 0xFF;
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int scd30_read_data(uint8_t *data, int len) {
    if (i2cReadDevice(i2c_handle, (char *)data, len) != len) {
        fprintf(stderr, "Error: I2C read failed (expected %d bytes, got %d)\n", len, len);
        return -1;
    }
    return 0;
}

static int scd30_init(void) {
    if (scd30_write_command(0x0001) != 0) return -1;
    gpioDelay(10000);
    if (scd30_write_command(0x0002) != 0) return -1;
