#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define SDP32_ADDR 0x21
#define I2C_BUS 1
#define SDP32_CMD_CONT_MEAS 0x362F
#define SDP32_READ_LEN 9
#define SDP32_CRC_POLY 0x31
#define SDP32_CRC_INIT 0xFF

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = SDP32_CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ SDP32_CRC_POLY;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sdp32(int handle, float *pressure_pa) {
    uint8_t cmd[2] = { (SDP32_CMD_CONT_MEAS >> 8) & 0xFF, SDP32_CMD_CONT_MEAS & 0xFF };
    uint8_t buf[SDP32_READ_LEN];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to send continuous-measurement command.\n");
        return -1;
    }

    gpioDelay(20000);

    if (i2cReadDevice(handle, (char *)buf, SDP32_READ_LEN) != SDP32_READ_LEN) {
        fprintf(stderr, "Error: Failed to read 9 bytes from SDP32.\n");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: Pressure CRC mismatch.\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }
    if (crc8(buf + 6, 2) != buf[8]) {
        fprintf(stderr, "Error: Scale-factor CRC mismatch.\n");
        return -1;
    }

    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    int16_t scale_factor = (buf[6] << 8) | buf[7];

    if (scale_factor == 0) {
        fprintf(stderr, "Error: Invalid scale factor (0).\n");
        return -1;
    }

    *pressure_pa = (float)raw_pressure / (float)scale_factor;
    return 0;
}

static void log_data(float pressure_pa) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, Pressure: %.2f Pa\n", timestamp, pressure_pa);
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    int interval = 1000;

    if (argc > 1) {
        interval = atoi(argv[1]);
        if (interval <= 0) {
            fprintf(stderr, "Invalid interval. Using default 1000 ms.\n");
            interval = 1000;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at address 0x%02X on bus %d.\n", SDP32_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP32 Differential Pressure Sensor Reader\n");
    printf("I2C Bus: %d, Address: 0x%02X, Interval: %d ms\n", I2C_BUS, SDP32_ADDR, interval);
    printf("Press Ctrl+C to exit.\n\n");

    while (!terminate) {
        float pressure_pa;
        if (read_sdp32(i2c_handle, &pressure_pa) == 0) {
            log_data(pressure_pa);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, retrying in %d ms...\n", interval);
        }
        gpioDelay(interval * 1000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

