#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25
#define MEASURE_CMD    0x3615
#define CONV_DELAY_US  45000   /* 45 ms worst-case conversion time */
#define SAMPLE_PERIOD  1       /* seconds between samples */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/*
 * Read one differential-pressure / temperature sample from the SDP810.
 * Returns 0 on success, -1 on I/O or CRC error.
 */
static int read_sdp810(int handle, float *pressure, float *temperature)
{
    uint8_t cmd[2] = {
        (uint8_t)((MEASURE_CMD >> 8) & 0xFF),
        (uint8_t)(MEASURE_CMD & 0xFF)
    };
    uint8_t buf[9];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (measure command) failed\n");
        return -1;
    }

    gpioDelay(CONV_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed (sensor absent or bus error)\n");
        return -1;
    }

    /* Validate CRC on each 3-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "[ERROR] CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    uint16_t scale_p        = (uint16_t)((buf[6] << 8) | buf[7]);
    uint16_t scale_t        = (uint16_t)((buf[8] << 8) | buf[9]);

    if (scale_p == 0 || scale_t == 0) {
        fprintf(stderr, "[ERROR] Scale factor invalid (p=%u t=%u)\n", scale_p, scale_t);
        return -1;
    }

    *pressure    = (float)raw_pressure    / (float)scale_p;
    *temperature = (float)raw_temperature / 200.0f;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SDP810-125Pa reader started on I2C bus %d, addr 0x%02X\n",
           I2C_BUS, I2C_ADDR);
    printf("Press Ctrl+C to stop.\n\n");

    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;

        if (read_sdp810(handle, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n",
                   pressure, temperature);
        } else {
            fprintf(stderr, "[WARN] Read failed; will retry next cycle\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            gpioDelay(100000);
    }

    i2cClose(handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

