#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HDC1000_ADDR        0x40
#define HDC1000_CONFIG_REG  0x02
#define HDC1000_TEMP_REG    0x00
#define I2C_BUS             "/dev/i2c-1"
#define READ_INTERVAL_SEC   5
#define CONVERSION_DELAY_MS 20

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    ssize_t n = write(fd, &reg_buf, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg16: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    uint8_t data[2];
    n = read(fd, data, 2);
    if (n != 2) {
        fprintf(stderr, "i2c_read_reg16: read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

static int hdc1000_init(int fd)
{
    /*
     * Configuration Register (0x02):
     *   Bit 12 (MEAS) = 1  -> enable combined temp/humidity measurement
     *   Bits 10-9 (MODE) = 00 -> 14-bit resolution
     *   Bits 8-6 (HEAT) = 000 -> heater off
     *   Bits 5-4 (INT) = 00  -> no interrupt
     *   Bits 3-0 (FDR) = 0000 -> 1 Hz trigger rate (not used here)
     * Value: 0x4000
     */
    if (i2c_write_reg8(fd, HDC1000_CONFIG_REG, 0x40) != 0) {
        fprintf(stderr, "Failed to configure HDC1000\n");
        return -1;
    }
    return 0;
}

static int hdc1000_read(int fd, float *temperature, float *humidity)
{
    uint16_t raw_temp, raw_hum;

    /* Trigger a measurement by writing the temperature register pointer */
    if (i2c_write_reg8(fd, HDC1000_TEMP_REG, 0x00) != 0) {
        return -1;
    }

    usleep(CONVERSION_DELAY_MS * 1000);

    if (i2c_read_reg16(fd, HDC1000_TEMP_REG, &raw_temp) != 0) {
        return -1;
    }
    if (i2c_read_reg16(fd, HDC1000_TEMP_REG, &raw_hum) != 0) {
        return -1;
    }

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity    = ((float)raw_hum  / 65536.0f) * 100.0f;

    return 0;
}

int main(void)
{
    int fd = -1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                HDC1000_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (hdc1000_init(fd) != 0) {
        fprintf(stderr, "HDC1000 sensor not detected or init failed.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("HDC1000 initialized. Reading every %d seconds. Press Ctrl+C to exit.\n",
           READ_INTERVAL_SEC);

    while (g_running) {
        float temperature, humidity;

        if (hdc1000_read(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "Error reading HDC1000 sensor.\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully.\n");
    close(fd);
    return EXIT_SUCCESS;
}

