#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define TEMP_REG 0x00
#define MEAS_TEMP_CMD 0xE3
#define CONV_TIME_US 10000
#define POLL_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *temperature) {
    char buf[2];
    int result;

    result = i2cWriteByte(i2c_handle, MEAS_TEMP_CMD);
    if (result < 0) {
        fprintf(stderr, "Error writing measurement command to I2C: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(CONV_TIME_US);

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data from I2C: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw_temp = ((uint16_t)buf[0] << 8) | (uint16_t)buf[1];
    *temperature = (175.72f * raw_temp / 65536.0f) - 46.85f;
    return 0;
}

int main(void) {
    float temperature;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set up signal handlers");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7051 temperature logger started. Press Ctrl+C to exit.\n");

    while (running) {
        current_time = time(NULL);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        if (read_temperature(&temperature) == 0) {
            printf("%s - Temperature: %.2f C\n", timestamp, temperature);
        } else {
            fprintf(stderr, "%s - Error reading temperature\n", timestamp);
        }

        sleep(POLL_INTERVAL_S);
    }

    printf("\nExiting gracefully...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

