        return -1;
    }

    uint16_t raw_temp = ((uint16_t)buf[0] << 8) | (uint16_t)buf[1];
    *temperature = (175.72f * raw_temp / 65536.0f) - 46.85f;
    return 0;
}

int main(void) {
