#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x63
#define MEAS_CMD       0x40
#define OTP_READ_CMD   0x50
#define OTP_DATA_LEN   8
#define MEAS_DELAY_US  7000
#define SAMPLE_PERIOD  5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_otp_data(uint16_t *cal) {
    char cmd = OTP_READ_CMD;
    char buf[OTP_DATA_LEN];

    if (i2cWriteDevice(g_i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write OTP read command\n");
        return -1;
    }
    gpioDelay(1000);

    if (i2cReadDevice(g_i2c_handle, buf, OTP_DATA_LEN) != OTP_DATA_LEN) {
        fprintf(stderr, "Error: failed to read OTP data\n");
        return -1;
    }

    for (int i = 0; i < OTP_DATA_LEN; i++) {
        if (buf[i] == 0x00) {
            buf[i] = 0xFF;
        }
    }

    cal[0] = (uint16_t)((buf[0] << 8) | buf[1]);
    cal[1] = (uint16_t)((buf[2] << 8) | buf[3]);
    cal[2] = (uint16_t)((buf[4] << 8) | buf[5]);
    cal[3] = (uint16_t)((buf[6] << 8) | buf[7]);
    return 0;
}

static int read_sensor(float *temperature, float *pressure) {
    char cmd = MEAS_CMD;
    char buf[6];

    if (i2cWriteDevice(g_i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write measurement command\n");
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);

    if (i2cReadDevice(g_i2c_handle, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read measurement data\n");
        return -1;
    }

    uint16_t raw_t = (uint16_t)((buf[0] << 8) | buf[1]);
    uint32_t raw_p = (uint32_t)((buf[2] << 16) | (buf[3] << 8) | buf[4]);

    float t_comp = (float)raw_t / 65536.0f;
    float p_comp = (float)raw_p / 65536.0f;

    *temperature = -45.0f + 175.0f * t_comp;
    *pressure = 45000.0f + 22500.0f * p_comp;
    return 0;
}

static void log_data(float temperature, float pressure) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", ts, temperature, pressure);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d). Sensor may be absent at 0x%02X.\n",
                g_i2c_handle, I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    uint16_t cal[4];
    if (read_otp_data(cal) != 0) {
        fprintf(stderr, "Error: failed to read calibration coefficients\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    float scale_factor_lut = (float)cal[0] / 256.0f;
    float scale_factor_h  = (float)cal[1] / 256.0f;
    float scale_factor_p  = (float)cal[2] / 256.0f;

    float temperature, pressure;

    while (g_running) {
        if (read_sensor(&temperature, &pressure) == 0) {
            log_data(temperature, pressure);
        } else {
            fprintf(stderr, "Warning: sensor read failed, skipping sample\n");
        }
        gpioDelay(SAMPLE_PERIOD * 1000000);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return 0;
}

