#define SDP800_ADDR 0x25
#define MEASURE_CMD_0 0x36
#define MEASURE_CMD_1 0x2F
#define LOG_FILE "airflow_log.csv"
#define SAMPLE_INTERVAL_US 1000000
#define MEASURE_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sdp800(int handle, float *pressure) {
    uint8_t cmd[2] = {MEASURE_CMD_0, MEASURE_CMD_1};
    uint8_t buf[3];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error writing measurement command: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error reading measurement data: %s\n", strerror(errno));
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch: computed 0x%02X, received 0x%02X\n", crc8(buf, 2), buf[2]);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *pressure = (float)raw / 60.0f;
    return 0;
}

static int log_data(const char *filename, float pressure) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Pressure (Pa)\n");
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

