#define LOG_FILE "environmental_data.log"
#define MAX_LOG_SIZE (1024 * 1024)
#define SAMPLE_INTERVAL_SEC 5
#define MEASUREMENT_DELAY_US 40000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hih6130(int handle, float *temperature, float *humidity) {
    uint8_t buf[4];
    int result;

    /* Trigger measurement: write 0x00 to the sensor */
    result = i2cWriteByte(handle, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    /* Read 4 bytes: [status, MSB, LSB, CRC] */
    result = i2cReadDevice(handle, (char *)buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: expected 4 bytes, got %d\n", result);
        return -1;
    }

    /* Validate status bit (bit 0 of status byte should be 0 for normal operation) */
    if (buf[0] & 0x01) {
        fprintf(stderr, "Sensor error: status bit set (0x%02X)\n", buf[0]);
        return -1;
    }

    /* Convert raw values to physical units */
    uint16_t raw_t = ((uint16_t)buf[1] << 8) | buf[2];
    uint16_t raw_h = ((uint16_t)buf[3] << 8) | buf[2]; /* LSB and CRC overlap; use LSB for humidity */

    *temperature = ((float)raw_t * 165.0f) / 16383.0f - 40.0f;
    *humidity = ((float)raw_h * 100.0f) / 16383.0f;

    return 0;
}

static int log_data(const char *filename, float temperature, float humidity) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    /* Check if file size exceeds max size */
    long pos = ftell(fp);
    if (pos < 0) {
        perror("Error getting file size");
        fclose(fp);
        return -1;
    }

    if (pos >= MAX_LOG_SIZE) {
        /* Truncate the file */
        if (ftruncate(fileno(fp), 0) != 0) {
            perror("Error truncating log file");
            fclose(fp);
            return -1;
        }
    }

    /* Get current timestamp */
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("Error getting time");
        fclose(fp);
        return -1;
    }

    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    /* Write data to the log file */
    if (fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

