#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define SENT_PIN 4
#define SENT_TICK_US 3
#define SENT_SYNC_TICKS 56
#define SENT_NIBBLE_MIN_TICKS 12
#define SENT_NIBBLE_MAX_TICKS 271
#define SENT_TIMEOUT_US 100000
#define LOG_FILE "pressure_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(int pin, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(pin) != level) {
        if ((gpioTick() - start) > timeout_us) return -1;
    }
    return 0;
}

static int read_sent_nibble(void) {
    if (wait_for_level(SENT_PIN, 0, SENT_TIMEOUT_US) < 0) return -1;
    if (wait_for_level(SENT_PIN, 1, SENT_TIMEOUT_US) < 0) return -1;
    uint32_t start = gpioTick();
    while (gpioRead(SENT_PIN) == 1) {
        if ((gpioTick() - start) > SENT_TIMEOUT_US) return -1;
    }
    uint32_t width = gpioTick() - start;
    int ticks = (int)((width + SENT_TICK_US / 2) / SENT_TICK_US);
    if (ticks < SENT_NIBBLE_MIN_TICKS || ticks > SENT_NIBBLE_MAX_TICKS) return -1;
    return ticks - SENT_NIBBLE_MIN_TICKS;
}

static int read_sent_word(void) {
    if (read_sent_nibble() < 0) return -1;
    if (read_sent_nibble() < 0) return -1;
    if (read_sent_nibble() < 0) return -1;
    if (read_sent_nibble() < 0) return -1;
    if (read_sent_nibble() < 0) return -1;
    return 0;
}

static int read_sent_data(int *raw_value) {
    if (read_sent_word() < 0) return -1;
    int status = read_sent_nibble();
    if (status < 0) return -1;
    int data[3];
    for (int i = 0; i < 3; i++) {
        data[i] = read_sent_nibble();
        if (data[i] < 0) return -1;
    }
    int checksum = read_sent_nibble();
    if (checksum < 0) return -1;

    int sum = (status + data[0] + data[1] + data[2]) & 0xF;
    if (sum != checksum) return -1;

    *raw_value = (data[0] << 8) | (data[1] << 4) | data[2];
    return 0;
}

static float convert_to_pressure(int raw_value) {
    return (float)raw_value * 0.1f;
}

static int log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENT_PIN, PI_INPUT);
    gpioSetPullUpDown(SENT_PIN, PI_PUD_UP);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting SENT pressure monitoring on GPIO %d...\n", SENT_PIN);

    while (running) {
        int raw_value = 0;
        if (read_sent_data(&raw_value) == 0) {
            float pressure = convert_to_pressure(raw_value);
            if (log_pressure(pressure) != 0) {
                fprintf(stderr, "Logging failed\n");
            } else {
                printf("Pressure: %.2f Pa\n", pressure);
            }
        } else {
            fprintf(stderr, "SENT read error or timeout\n");
        }
        gpioDelay(100000);
    }

    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

