#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define DEVICE_ID_REG 0x01
#define DEVICE_ID_EXPECTED 0x0117
#define LOG_FILE "greenhouse_temps.dat"
#define SAMPLE_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_device_id(int handle, uint16_t *id) {
    char buf[2];
    if (i2cReadI2CBlockData(handle, DEVICE_ID_REG, buf, 2) != 2) {
        fprintf(stderr, "Error reading device ID: %s\n", strerror(errno));
        return -1;
    }
    *id = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int read_temperature(int handle, float *temperature) {
    char buf[2];
    if (i2cReadI2CBlockData(handle, TEMP_REG, buf, 2) != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1;
    }
    int16_t raw = ((int16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *temperature = (float)raw * 0.0078125f;
    return 0;
}

static int log_temperature(FILE *fp, float temperature) {
    if (fwrite(&temperature, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Error writing temperature to file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
