#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SHT40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define I2C_BUS 1
#define LOG_FILE "environmental_data.txt"
#define READ_INTERVAL_SEC 5
#define CONVERSION_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sht40(int handle, float *temperature, float *humidity) {
    uint8_t cmd = MEASURE_HIGH_PRECISION;
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to write measurement command to SHT40.\n");
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read 6 bytes from SHT40.\n");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch.\n");
        return -1;
    }

    uint16_t raw_temp = (buf[0] << 8) | buf[1];
    uint16_t raw_hum  = (buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * ((float)raw_temp / 65535.0f);
    *humidity    = -6.0f  + 125.0f * ((float)raw_hum  / 65535.0f);

    return 0;
}

static int log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n",
                I2C_BUS, SHT40_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler.\n");
    }

    printf("Smart Greenhouse Monitor started. Logging to %s every %d seconds.\n",
           LOG_FILE, READ_INTERVAL_SEC);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        float temperature, humidity;

        if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
            if (log_data(log_file, temperature, humidity) != 0) {
                fprintf(stderr, "Warning: Logging failed for this sample.\n");
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed; will retry next cycle.\n");
        }

        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    printf("\nShutting down gracefully...\n");

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

