#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS        1
#define TMP117_ADDR    0x48
#define TEMP_REG       0x00
#define SAMPLE_PERIOD  5.0   /* seconds */
#define LOG_FILE       "temperature_log.dat"
#define BUFFER_SIZE    100
#define TEMP_ERROR     -999.0

typedef struct {
    time_t timestamp;
    float  temperature;
} TemperatureReading;

static TemperatureReading circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, TMP117_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static float read_temperature(void)
{
    char buf[2];
    int  bytes;

    bytes = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "Error reading temperature register: %s\n",
                bytes < 0 ? strerror(errno) : "short read");
        return TEMP_ERROR;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return (float)raw * 0.0078125f;
}

static void add_reading(float temperature)
{
    circular_buffer[buffer_index].timestamp   = time(NULL);
    circular_buffer[buffer_index].temperature = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static int log_buffer_to_file(void)
{
    FILE *fp = fopen(LOG_FILE, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    int start = (buffer_count < BUFFER_SIZE) ? 0 : buffer_index;
    int count = buffer_count;

    for (int i = 0; i < count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        if (fwrite(&circular_buffer[idx], sizeof(TemperatureReading), 1, fp) != 1) {
            fprintf(stderr, "Error writing to %s: %s\n", LOG_FILE, strerror(errno));
            fclose(fp);
            return -1;
        }
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install signal handlers: %s\n", strerror(errno));
    }

    printf("TMP117 temperature logger started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float temperature = read_temperature();

        if (temperature != TEMP_ERROR) {
            printf("Temperature: %.4f °C\n", temperature);
            add_reading(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        /* Persist every sample so no data is lost on abrupt exit. */
        if (log_buffer_to_file() != 0) {
            fprintf(stderr, "Warning: failed to log buffer to file.\n");
        }

        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

