#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SHTC3_ADDR 0x70
#define MEASURE_CMD 0x7866
#define LOG_FILE "shtc3_environment.log"
#define SAMPLE_INTERVAL_US 5000000
#define CONVERSION_DELAY_US 15000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_shtc3(int handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = { (MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF };
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t temp_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t hum_raw  = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = 175.0f * (float)temp_raw / 65535.0f - 45.0f;
    *humidity   = 100.0f * (float)hum_raw  / 65535.0f;

    if (*temperature < -40.0f || *temperature > 125.0f) {
        fprintf(stderr, "Error: Temperature out of range: %.2f C\n", *temperature);
        return -1;
    }
    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "Error: Humidity out of range: %.2f %%\n", *humidity);
        return -1;
    }

    return 0;
}

static int log_data(const char *filename, float temperature, float humidity) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error: Cannot open log file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, SHTC3_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (addr 0x%02X): %s\n", SHTC3_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    float temperature, humidity;

    while (!terminate) {
        if (read_shtc3(i2c_handle, &temperature, &humidity) == 0) {
            if (log_data(LOG_FILE, temperature, humidity) == 0) {
                printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

