#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7202_ADDR 0x40
#define LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int read_sensor_data(int handle, float *field_gauss, float *temp_celsius) {
    char buf[2];
    int result;

    buf[0] = 0x00;
    buf[1] = 0x00;

    result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    int raw_field = (buf[0] << 8) | buf[1];
    int raw_temp = (buf[1] << 8) | buf[0];

    *field_gauss = (float)raw_field * 0.1f;
    *temp_celsius = (float)raw_temp * 0.01f - 25.0f;

    return 0;
}

int log_data(FILE *fp, float field_gauss, float temp_celsius) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (isnan(field_gauss) && isnan(temp_celsius)) {
        fprintf(fp, "%s,NaN,NaN\n", timestamp);
    } else {
        fprintf(fp, "%s,%.2f,%.2f\n", timestamp, field_gauss, temp_celsius);
    }

    fflush(fp);
    return 0;
}

int main() {
    float field_gauss, temp_celsius;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Magnetic Field (Gauss),Temperature (Celsius)\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        if (read_sensor_data(i2c_handle, &field_gauss, &temp_celsius) == 0) {
            log_data(log_file, field_gauss, temp_celsius);
        } else {
            log_data(log_file, NAN, NAN);
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

