    if (bytes_read != 4) {
        fprintf(stderr, "Error reading I2C device: expected 4 bytes, got %d\n", bytes_read);
        return -1;
    }
    *raw_flow = ((uint16_t)(buffer[0] & 0x0F) << 8) | (uint8_t)buffer[1];
    *raw_temp = ((uint16_t)(buffer[2] & 0x0F) << 8) | (uint8_t)buffer[3];
    return 0;
}

