    float slpm = ((float)raw_flow / 16384.0f) - 0.1f;
    slpm = slpm / 0.8f * 25.0f;
    return slpm;
}

static float convert_temperature(uint16_t raw_temp) {
    float celsius = ((float)raw_temp / 4096.0f) - 0.1f;
    celsius = celsius / 0.8f * 80.0f - 40.0f;
    return celsius;
}

