    while (running) {
        if (read_sensor_data(&raw_flow, &raw_temp) == 0) {
            retry_count = 0;
            float flow_rate = convert_flow_rate(raw_flow);
            float temperature = convert_temperature(raw_temp);
            if (log_data(flow_rate, temperature) != 0) {
                fprintf(stderr, "Error logging data\n");
