#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define LOG_FILE "dht11_readings.txt"
#define SAMPLE_INTERVAL_SEC 2
#define START_LOW_US 18000
#define START_HIGH_US 30
#define RESP_LOW_US 80
#define RESP_HIGH_US 80
#define BIT_LOW_US 50
#define BIT_TIMEOUT_US 200
#define READ_TIMEOUT_US 200
#define MAX_READ_RETRIES 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,ERROR,%s\n", ts, msg);
    fclose(fp);
}

static void log_reading(float temp, float hum) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,OK,%.1f,%.1f\n", ts, temp, hum);
    fclose(fp);
}

static int wait_for_level(int target, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(DHT11_GPIO) != target) {
        if ((gpioTick() - start) > timeout_us) return -1;
    }
    return 0;
}

static int read_dht11(float *temp, float *hum) {
    uint8_t data[5] = {0};
    int retries = 0;

    while (retries < MAX_READ_RETRIES && running) {
        memset(data, 0, sizeof(data));
        uint32_t start = gpioTick();

        if (gpioSetMode(DHT11_GPIO, PI_OUTPUT) < 0) {
            log_error("gpioSetMode failed");
            retries++;
            sleep(1);
            continue;
        }
        if (gpioWrite(DHT11_GPIO, 0) < 0) {
            log_error("gpioWrite low failed");
            retries++;
            sleep(1);
            continue;
        }
        gpioDelay(START_LOW_US);

        if (gpioWrite(DHT11_GPIO, 1) < 0) {
            log_error("gpioWrite high failed");
            retries++;
            sleep(1);
            continue;
        }
        gpioDelay(START_HIGH_US);

        if (gpioSetMode(DHT11_GPIO, PI_INPUT) < 0) {
            log_error("gpioSetMode input failed");
            retries++;
            sleep(1);
            continue;
        }

        if (wait_for_level(0, READ_TIMEOUT_US) < 0) {
            log_error("Timeout waiting for sensor response low");
            retries++;
            sleep(1);
            continue;
        }
        if (wait_for_level(1, READ_TIMEOUT_US) < 0) {
            log_error("Timeout waiting for sensor response high");
            retries++;
            sleep(1);
            continue;
        }
        if (wait_for_level(0, READ_TIMEOUT_US) < 0) {
            log_error("Timeout waiting for data bit 0");
            retries++;
            sleep(1);
            continue;
        }

        for (int i = 0; i < 40; i++) {
            if (wait_for_level(1, BIT_TIMEOUT_US) < 0) {
                log_error("Timeout waiting for data bit high");
                retries++;
                goto retry;
            }
            if (wait_for_level(0, BIT_TIMEOUT_US) < 0) {
                log_error("Timeout waiting for data bit low");
                retries++;
                goto retry;
            }
            uint32_t high_us = gpioTick() - gpioTick();
            data[i / 8] <<= 1;
            if (high_us > 40) data[i / 8] |= 1;
        }

        if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
            log_error("Checksum mismatch");
            retries++;
            sleep(1);
            continue;
        }

        *hum = (float)data[0];
        *temp = (float)data[2];
        return 0;

retry:
        retries++;
        sleep(1);
    }

    log_error("Max retries reached");
    return -1;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        float temp, hum;
        if (read_dht11(&temp, &hum) == 0) {
            log_reading(temp, hum);
            printf("Temp: %.1f C, Hum: %.1f %%\n", temp, hum);
        } else {
            log_error("DHT11 read failed after retries");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    gpioTerminate();
    return 0;
}

