#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SHT31_ADDR        0x44
#define SHT31_CMD_MSB     0x2C
#define SHT31_CMD_LSB     0x06
#define SHT31_MEAS_DELAY_US 15000
#define SHT31_MAX_RETRIES 3
#define LOG_FILE          "sht31d_data.log"
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int read_sht31d(int handle, float *temperature, float *humidity)
{
    uint8_t cmd[2] = { SHT31_CMD_MSB, SHT31_CMD_LSB };
    uint8_t buf[6];
    int rc;

    for (int attempt = 0; attempt < SHT31_MAX_RETRIES; attempt++) {
        rc = i2cWriteDevice(handle, (char *)cmd, 2);
        if (rc != 0) {
            fprintf(stderr, "[attempt %d] i2cWriteDevice failed: %s\n",
                    attempt + 1, strerror(errno));
            gpioDelay(SHT31_MEAS_DELAY_US);
            continue;
        }

        gpioDelay(SHT31_MEAS_DELAY_US);

        rc = i2cReadDevice(handle, (char *)buf, 6);
        if (rc != 6) {
            fprintf(stderr, "[attempt %d] i2cReadDevice failed: %s\n",
                    attempt + 1, rc < 0 ? strerror(errno) : "short read");
            continue;
        }

        if (crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "[attempt %d] temperature CRC mismatch\n", attempt + 1);
            continue;
        }
        if (crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "[attempt %d] humidity CRC mismatch\n", attempt + 1);
            continue;
        }

        uint16_t t_raw = (uint16_t)((buf[0] << 8) | buf[1]);
        uint16_t h_raw = (uint16_t)((buf[3] << 8) | buf[4]);

        *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
        *humidity    = 100.0f * (float)h_raw / 65535.0f;

        return 0;
    }

    return -1;
}

static void log_data(float temperature, float humidity)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
