#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADPD105_ADDR_1 0x64
#define ADPD105_ADDR_2 0x65
#define ADPD105_REG_DEVICE_ID 0x00
#define ADPD105_REG_RED_DATA 0x64
#define ADPD105_REG_GREEN_DATA 0x66
#define ADPD105_REG_BLUE_DATA 0x68
#define ADPD105_EXPECTED_DEVICE_ID 0x2A
#define LOG_FILE "cct_log.csv"
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;
static int i2c_handle_1 = -1;
static int i2c_handle_2 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adpd105_data(int handle, int *red, int *green, int *blue) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(handle, ADPD105_REG_RED_DATA, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading red data from handle %d: %d\n", handle, result);
        return -1;
    }
    *red = (buf[1] << 8) | buf[0];

    result = i2cReadI2CBlockData(handle, ADPD105_REG_GREEN_DATA, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading green data from handle %d: %d\n", handle, result);
        return -1;
    }
    *green = (buf[1] << 8) | buf[0];

    result = i2cReadI2CBlockData(handle, ADPD105_REG_BLUE_DATA, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading blue data from handle %d: %d\n", handle, result);
        return -1;
    }
    *blue = (buf[1] << 8) | buf[0];

    return 0;
}

static double calculate_cct(int red, int green, int blue) {
    double r = (double)red;
    double g = (double)green;
    double b = (double)blue;
    double x = (g / r) - 1.0;
    double y = (b / r) - 1.0;
    double cct = 449.0 * pow(x, 3) + 3525.0 * pow(x, 2) + 6823.3 * x + 5520.33;
    return cct;
}

static int log_cct_data(double average_cct) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, average_cct) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle_1 >= 0) {
        i2cClose(i2c_handle_1);
        i2c_handle_1 = -1;
    }
    if (i2c_handle_2 >= 0) {
        i2cClose(i2c_handle_2);
        i2c_handle_2 = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int red1, green1, blue1, red2, green2, blue2;
    double cct1, cct2, average_cct;
    int ret;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle_1 = i2cOpen(I2C_BUS, ADPD105_ADDR_1, 0);
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Error opening I2C device 1 at 0x%02X: %d\n", ADPD105_ADDR_1, i2c_handle_1);
        gpioTerminate();
        return 1;
    }

    i2c_handle_2 = i2cOpen(I2C_BUS, ADPD105_ADDR_2, 0);
    if (i2c_handle_2 < 0) {
        fprintf(stderr, "Error opening I2C device 2 at 0x%02X: %d\n", ADPD105_ADDR_2, i2c_handle_2);
        i2cClose(i2c_handle_1);
        i2c_handle_1 = -1;
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle_1);
        i2c_handle_1 = -1;
        i2cClose(i2c_handle_2);
        i2c_handle_2 = -1;
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
        fflush(log_file);
    }

    while (running) {
        int device_id;
        char buf[1];

        ret = i2cReadI2CBlockData(i2c_handle_1, ADPD105_REG_DEVICE_ID, buf, 1);
        if (ret != 1) {
            fprintf(stderr, "Error reading device ID from handle 1: %d\n", ret);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }
        device_id = buf[0];
        if (device_id != ADPD105_EXPECTED_DEVICE_ID) {
            fprintf(stderr, "Unexpected device ID from handle 1: 0x%02X (expected 0x%02X)\n", device_id, ADPD105_EXPECTED_DEVICE_ID);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        ret = i2cReadI2CBlockData(i2c_handle_2, ADPD105_REG_DEVICE_ID, buf, 1);
        if (ret != 1) {
            fprintf(stderr, "Error reading device ID from handle 2: %d\n", ret);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }
        device_id = buf[0];
        if (device_id != ADPD105_EXPECTED_DEVICE_ID) {
            fprintf(stderr, "Unexpected device ID from handle 2: 0x%02X (expected 0x%02X)\n", device_id, ADPD105_EXPECTED_DEVICE_ID);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        if (read_adpd105_data(i2c_handle_1, &red1, &green1, &blue1) != 0) {
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }
        if (read_adpd105_data(i2c_handle_2, &red2, &green2, &blue2) != 0) {
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        cct1 = calculate_cct(red1, green1, blue1);
        cct2 = calculate_cct(red2, green2, blue2);
        average_cct = (cct1 + cct2) / 2.0;

        if (log_cct_data(average_cct) != 0) {
            fprintf(stderr, "Error logging CCT data\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

