#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define TEMP_REG       0x00
#define FAN_GPIO       18
#define TEMP_THRESHOLD_HIGH 28.0f
#define TEMP_THRESHOLD_LOW  26.0f
#define BUFFER_SIZE    60
#define SAMPLE_PERIOD  1.0

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb) {
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float cb_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / (float)cb->count;
}

static int read_temperature(int handle, float *out) {
    char reg = (char)TEMP_REG;
    char buf[2];

    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X)\n", TEMP_REG);
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C read failed (temp reg 0x%02X)\n", TEMP_REG);
        return -1;
    }

    int16_t raw = (int16_t)(((uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    /* LM75B: 9-bit signed, bits D9-D1 carry into bit 8; D0 is always 0 */
    raw >>= 1;
    if (raw & 0x0080) raw |= 0xF800;
    *out = (float)raw * 0.5f;
    return 0;
}

static int control_fan(int gpio, float avg_temp) {
    int level = (avg_temp > TEMP_THRESHOLD_HIGH) ? 1 : 0;
    if (gpioWrite(gpio, level) != 0) {
        fprintf(stderr, "GPIO write failed (pin %d, level %d)\n", gpio, level);
        return -1;
    }
    printf("Fan %s (avg %.2f C)\n", level ? "ON" : "OFF", avg_temp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "I2C open failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "GPIO setMode failed (pin %d)\n", FAN_GPIO);
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    CircularBuffer cb;
    cb_init(&cb);

    while (g_running) {
        float temp;
        if (read_temperature(handle, &temp) == 0) {
            cb_add(&cb, temp);
            float avg = cb_average(&cb);
            printf("Temperature: %.2f C, Average: %.2f C\n", temp, avg);
            if (control_fan(FAN_GPIO, avg) != 0) {
                fprintf(stderr, "Fan control failed\n");
            }
        } else {
            fprintf(stderr, "Temperature read failed; will retry next cycle\n");
        }
        time_sleep(SAMPLE_PERIOD);
    }

    /* Graceful shutdown */
    gpioWrite(FAN_GPIO, 0);
    i2cClose(handle);
    gpioTerminate();
    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

