#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define STTS2004_ADDR  0x4A
#define TEMP_REG       0x00
#define GPIO_CHIP      "gpiochip0"
#define LED_LINE       17
#define TEMP_THRESHOLD_HIGH  28.0f
#define TEMP_THRESHOLD_LOW   27.0f
#define MAX_CONSECUTIVE_ERRORS 5

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

int main(void) {
    int i2c_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", STTS2004_ADDR, strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_LINE);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "stts2004-led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_LINE, strerror(errno));
        goto cleanup;
    }

    int consecutive_errors = 0;

    while (running) {
        int16_t raw;
        if (i2c_read_reg16(i2c_fd, TEMP_REG, &raw) == 0) {
            consecutive_errors = 0;
            float temperature = (float)raw >> 4;
            temperature /= 100.0f;
            printf("Temperature: %.2f °C\n", temperature);

            if (temperature > TEMP_THRESHOLD_HIGH) {
                if (gpiod_line_set_value(led_line, 1) < 0) {
                    fprintf(stderr, "Failed to set LED high: %s\n", strerror(errno));
                }
            } else if (temperature < TEMP_THRESHOLD_LOW) {
                if (gpiod_line_set_value(led_line, 0) < 0) {
                    fprintf(stderr, "Failed to set LED low: %s\n", strerror(errno));
                }
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error reading temperature (consecutive: %d)\n", consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Too many consecutive I2C errors. Exiting.\n");
                goto cleanup;
            }
        }
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return ret;
}

