#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x40
#define CMD_MEASURE_RH_NO_HOLD  0xF5
#define CMD_MEASURE_TEMP_NO_HOLD 0xF3
#define CMD_READ_TEMP_PREV_RH   0xE0
#define CMD_READ_ID             0xFA
#define CMD_READ_FW_REV         0xFC
#define CMD_RESET               0xFE
#define CMD_READ_PREV_TEMP      0xE0
#define CMD_READ_PREV_RH        0xE1
#define MAX_RETRIES             3
#define SAMPLE_INTERVAL_S       60
#define LOG_FILE                "environment.log"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_message(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        time_t t = time(NULL);
        struct tm tm;
        localtime_r(&t, &tm);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,%s\n", ts, msg);
        fclose(fp);
    }
    fprintf(stderr, "%s\n", msg);
}

static int i2c_write_cmd(int handle, uint8_t cmd) {
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (i2cWriteDevice(handle, (char *)&cmd, 1) == 0)
            return 0;
        gpioDelay(10000);
    }
    return -1;
}

static int i2c_read_bytes(int handle, uint8_t *buf, int len) {
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (i2cReadDevice(handle, (char *)buf, len) == len)
            return 0;
        gpioDelay(10000);
    }
    return -1;
}

static int read_sensor(int handle, uint16_t *raw_t, uint16_t *raw_h) {
    if (i2c_write_cmd(handle, CMD_MEASURE_RH_NO_HOLD) != 0) {
        log_message("Error: failed to send RH measurement command");
        return -1;
    }
    gpioDelay(20000);
    uint8_t buf[3];
    if (i2c_read_bytes(handle, buf, 3) != 0) {
        log_message("Error: failed to read RH measurement result");
        return -1;
    }
    *raw_h = ((uint16_t)buf[0] << 8) | buf[1];
    if (i2c_write_cmd(handle, CMD_READ_PREV_RH) != 0) {
        log_message("Error: failed to send read-previous-RH command");
        return -1;
    }
    gpioDelay(20000);
    if (i2c_read_bytes(handle, buf, 2) != 0) {
        log_message("Error: failed to read previous RH value");
        return -1;
    }
    *raw_t = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static float convert_temperature(uint16_t raw) {
    return (175.72f * (float)raw / 65536.0f) - 46.85f;
}

static float convert_humidity(uint16_t raw) {
    float h = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (h < 0.0f) h = 0.0f;
    if (h > 100.0f) h = 100.0f;
    return h;
}

static int sensor_present(int handle) {
    if (i2c_write_cmd(handle, CMD_READ_ID) != 0) return 0;
    gpioDelay(10000);
    uint8_t id[2];
    if (i2c_read_bytes(handle, id, 2) != 0) return 0;
    if (id[0] != 0x05 || id[1] != 0x42) return 0;
    if (i2c_write_cmd(handle, CMD_READ_FW_REV) != 0) return 0;
    gpioDelay(10000);
    uint8_t fw[2];
    if (i2c_read_bytes(handle, fw, 2) != 0) return 0;
    if (fw[0] != 0x01 || fw[1] != 0x00) return 0;
    return 1;
}

static int init_sensor(int handle) {
    if (i2c_write_cmd(handle, CMD_RESET) != 0) {
        log_message("Error: failed to reset sensor");
        return -1;
    }
    gpioDelay(20000);
    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, SI7021_ADDR, g_i2c_handle);
