        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, SI7021_ADDR, g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (!sensor_present(g_i2c_handle)) {
        fprintf(stderr, "Si7021 sensor not detected (ID=0x0542, FW=0x0100)\n");
        log_message("Error: Si7021 sensor not detected");
        cleanup();
        return 1;
    }

    if (init_sensor(g_i2c_handle) != 0) {
        log_message("Error: sensor initialization failed");
