#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define STS40_ADDR      0x44
#define LOG_FILE        "temperature_log.txt"
#define SAMPLE_PERIOD_S 5
#define MEAS_DELAY_MS   10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Sensirion CRC-8: polynomial 0x31, init 0xFF, no final XOR */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_open(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, STS40_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                STS40_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int sts40_read_temp(int fd, float *temp_c)
{
    uint8_t cmd[2] = { 0x2C, 0xE0 };
    ssize_t w = write(fd, cmd, sizeof(cmd));
    if (w != (ssize_t)sizeof(cmd)) {
        fprintf(stderr, "write(cmd): %s\n", w < 0 ? strerror(errno) : "short write");
        return -1;
    }

    usleep(MEAS_DELAY_MS * 1000);

    uint8_t buf[3];
    ssize_t r = read(fd, buf, sizeof(buf));
    if (r != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "read: %s\n", r < 0 ? strerror(errno) : "short read");
        return -1;
    }

    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch: calc=0x%02X recv=0x%02X\n",
                sensirion_crc8(buf, 2), buf[2]);
        return -1;
    }

    uint16_t raw = (uint16_t)((buf[0] << 8) | buf[1]);
    *temp_c = -45.0f + 175.0f * (float)raw / 65535.0f;
    return 0;
}

static void log_temperature(float temp_c)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    if (fprintf(g_log_fp, "%s, Temperature: %.2f C\n", ts, temp_c) < 0)
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
    fflush(g_log_fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = i2c_open();
    if (g_i2c_fd < 0)
        return 1;

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    while (g_running) {
        float temp;
        if (sts40_read_temp(g_i2c_fd, &temp) == 0) {
            log_temperature(temp);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }
        sleep(SAMPLE_PERIOD_S);
    }

    fprintf(stderr, "\nShutting down cleanly.\n");
    if (g_log_fp)  fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

