    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler\n");
    }

    float pressure, temperature;

    while (running) {
        if (read_sdp810(i2c_handle, &pressure, &temperature) == 0) {
            log_data(log_file, pressure, temperature);
        } else {
