#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define LOG_DIR "/var/log/scd40_data"
#define ERROR_LOG "/var/log/scd40_error.log"
#define BUFFER_SIZE 100
#define LOGGING_INTERVAL 60
#define MEASUREMENT_DELAY_US 1000000

#define CMD_START_PERIODIC 0x21B1
#define CMD_STOP_PERIODIC 0x3F86
#define CMD_READ_MEASUREMENT 0xE000

#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF

typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t running = 1;
static pthread_t logging_thread;

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG, "a");
    if (!fp) {
        perror("fopen error log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static void init_circular_buffer(circular_buffer_t *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    pthread_mutex_init(&cb->mutex, NULL);
}

static void add_to_buffer(circular_buffer_t *cb, sensor_data_t data) {
    pthread_mutex_lock(&cb->mutex);
    cb->data[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
    pthread_mutex_unlock(&cb->mutex);
}

static int write_buffer_to_csv(const char *filename) {
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        log_error("Failed to open CSV file for writing");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "# SCD40 Data Log started at %d-%02d-%02d %02d:%02d:%02d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec);
    pthread_mutex_lock(&buffer.mutex);
    int start = (buffer.count == BUFFER_SIZE) ? buffer.tail : 0;
    for (int i = 0; i < buffer.count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        sensor_data_t d = buffer.data[idx];
        fprintf(fp, "%ld,%.0f,%.2f,%.2f\n",
                (long)d.timestamp, d.co2, d.temperature, d.humidity);
    }
    pthread_mutex_unlock(&buffer.mutex);
    fclose(fp);
    return 0;
}

static void *logging_thread_func(void *arg) {
    (void)arg;
    while (running) {
        sleep(LOGGING_INTERVAL);
        if (!running) break;
        char filename[256];
        snprintf(filename, sizeof(filename), "%s/scd40_data_%d.csv", LOG_DIR, time(NULL));
        if (write_buffer_to_csv(filename) != 0) {
            log_error("Logging thread failed to write CSV");
        }
    }
    return NULL;
}

static int send_command(uint16_t cmd) {
    char buf[2] = { (char)(cmd >> 8), (char)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        log_error("Failed to write command to I2C");
        return -1;
    }
    return 0;
}

static int read_measurement(uint8_t *data) {
    char cmd[2] = { (char)(CMD_READ_MEASUREMENT >> 8), (char)(CMD_READ_MEASUREMENT & 0xFF) };
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) {
        log_error("Failed to write read command");
        return -1;
    }
    usleep(2000);
    if (i2cReadDevice(i2c_handle, (char *)data, 9) != 9) {
        log_error("Failed to read 9 bytes from I2C");
        return -1;
    }
    return 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int parse_measurement(const uint8_t *data, sensor_data_t *out) {
    if (crc8(&data[0], 2) != data[2]) {
        log_error("CO2 CRC mismatch");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        log_error("Temperature CRC mismatch");
        return -1;
    }
    if (crc8(&data[6], 2) != data[8]) {
        log_error("Humidity CRC mismatch");
        return -1;
    }
    uint16_t co2_raw = (data[0] << 8) | data[1];
    uint16_t temp_raw = (data[3] << 8) | data[4];
    uint16_t hum_raw = (data[6] << 8) | data[7];
    out->co2 = (float)co2_raw;
    out->temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    out->humidity = 100.0f * (float)hum_raw / 65535.0f;
    out->timestamp = time(NULL);
    return 0;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        send_command(CMD_STOP_PERIODIC);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    write_buffer_to_csv(LOG_DIR);
    pthread_join(logging_thread, NULL);
    pthread_mutex_destroy(&buffer.mutex);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (send_command(CMD_START_PERIODIC) != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        cleanup();
        return 1;
    }
    usleep(MEASUREMENT_DELAY_US);

    init_circular_buffer(&buffer);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (pthread_create(&logging_thread, NULL, logging_thread_func, NULL) != 0) {
        perror("pthread_create");
        cleanup();
        return 1;
    }

    uint8_t data[9];
    sensor_data_t sensor_data;

    while (running) {
        if (read_measurement(data) == 0) {
            if (parse_measurement(data, &sensor_data) == 0) {
                add_to_buffer(&buffer, sensor_data);
            }
        }
        sleep(5);
    }

    running = 0;
    cleanup();
    return 0;
}

