        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int parse_measurement(const uint8_t *data, sensor_data_t *out) {
    if (crc8(&data[0], 2) != data[2]) {
        log_error("CO2 CRC mismatch");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        log_error("Temperature CRC mismatch");
        return -1;
    }
    if (crc8(&data[6], 2) != data[8]) {
        log_error("Humidity CRC mismatch");
        return -1;
    }
    uint16_t co2_raw = (data[0] << 8) | data[1];
    uint16_t temp_raw = (data[3] << 8) | data[4];
    uint16_t hum_raw = (data[6] << 8) | data[7];
    out->co2 = (float)co2_raw;
    out->temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    out->humidity = 100.0f * (float)hum_raw / 65535.0f;
    out->timestamp = time(NULL);
    return 0;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        send_command(CMD_STOP_PERIODIC);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    write_buffer_to_csv(LOG_DIR);
    pthread_join(logging_thread, NULL);
    pthread_mutex_destroy(&buffer.mutex);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (send_command(CMD_START_PERIODIC) != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        cleanup();
        return 1;
    }
    usleep(MEASUREMENT_DELAY_US);

    init_circular_buffer(&buffer);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (pthread_create(&logging_thread, NULL, logging_thread_func, NULL) != 0) {
        perror("pthread_create");
        cleanup();
        return 1;
    }

    uint8_t data[9];
    sensor_data_t sensor_data;

    while (running) {
        if (read_measurement(data) == 0) {
            if (parse_measurement(data, &sensor_data) == 0) {
                add_to_buffer(&buffer, sensor_data);
            }
        }
        sleep(5);
    }

    running = 0;
    cleanup();
    return 0;
}

