#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x63
#define WHO_AM_I 0x08
#define WHO_AM_I_VAL 0x08
#define MEASURE_CMD 0x00
#define MEASURE_DELAY_US 10000
#define DATA_LEN 6
#define LOG_FILE "environmental_data.txt"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(int handle, uint16_t *c0, uint16_t *c1, uint16_t *c00, uint16_t *c10, uint16_t *c01, uint16_t *c11, uint16_t *c20) {
    char buf[8];
    if (i2cReadI2CBlockData(handle, 0x05, buf, 8) != 8) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    *c0 = (uint16_t)((buf[0] << 8) | buf[1]);
    *c1 = (uint16_t)((buf[2] << 8) | buf[3]);
    *c00 = (uint16_t)((buf[4] << 8) | buf[5]);
    *c10 = (uint16_t)((buf[6] << 8) | buf[7]);
    return 0;
}

static int read_sensor(int handle, float *pressure, float *temperature) {
    char buf[DATA_LEN];
    if (i2cWriteByte(handle, MEASURE_CMD) < 0) {
        fprintf(stderr, "Error: Failed to trigger measurement\n");
        return -1;
    }
    gpioDelay(MEASURE_DELAY_US);
    if (i2cReadDevice(handle, buf, DATA_LEN) != DATA_LEN) {
        fprintf(stderr, "Error: Failed to read sensor data\n");
        return -1;
    }
    uint32_t raw_p = ((uint32_t)(buf[0] & 0x0F) << 16) | ((uint32_t)buf[1] << 8) | (uint32_t)buf[2];
    uint32_t raw_t = ((uint32_t)(buf[3] & 0x0F) << 16) | ((uint32_t)buf[4] << 8) | (uint32_t)buf[5];
    float p_comp = (float)raw_p / 1048576.0f;
    float t_comp = (float)raw_t / 1048576.0f;
    float p = 0.0f, t = 0.0f;
    float c00_inv = 1.0f / (float)c00;
    float c10_inv = 1.0f / (float)c10;
    float c01_inv = 1.0f / (float)c01;
    float c11_inv = 1.0f / (float)c11;
    float c20_inv = 1.0f / (float)c20;
    p = c00_inv * c00 + c10_inv * c10 * p_comp + c01_inv * c01 * p_comp * p_comp + c11_inv * c11 * p_comp * p_comp * p_comp + c20_inv * c20 * p_comp * p_comp * p_comp * p_comp;
    t = c00_inv * c00 + c10_inv * c10 * t_comp + c01_inv * c01 * t_comp * t_comp + c11_inv * c11 * t_comp * t_comp * t_comp + c20_inv * c20 * t_comp * t_comp * t_comp * t_comp;
    *pressure = p * 100.0f;
    *temperature = t * 200.0f;
    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, Pressure: %.2f hPa, Temperature: %.2f C\n", ts, pressure, temperature);
    fflush(fp);
    printf("%s, Pressure: %.2f hPa, Temperature: %.2f C\n", ts, pressure, temperature);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", I2C_ADDR);
        gpioTerminate();
        return 1;
    }
    int id = i2cReadByteData(handle, WHO_AM_I);
    if (id != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n", id, WHO_AM_I_VAL);
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }
    uint16_t c0, c1, c00, c10, c01, c11, c20;
    if (read_calibration(handle, &c0, &c1, &c00, &c10, &c01, &c11, &c20) != 0) {
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }
    while (running) {
        float p, t;
        if (read_sensor(handle, &p, &t) == 0) {
            log_data(fp, p, t);
        }
        for (int i = 0; i < 50 && running; i++) {
            gpioDelay(100000);
        }
    }
    fclose(fp);
    i2cClose(handle);
    gpioTerminate();
    return 0;
}

