    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select) failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_calibration(int fd, uint16_t *c0, uint16_t *c1, uint16_t *c2, uint16_t *c3) {
    uint8_t buf[8];
    if (i2c_read_block(fd, OTP_REG, buf, 8) < 0) return -1;
    if (crc8(&buf[0], 2) != buf[2]) { fprintf(stderr, "Pressure CRC mismatch\n"); return -1; }
    if (crc8(&buf[3], 2) != buf[5]) { fprintf(stderr, "Temp CRC mismatch\n"); return -1; }
    *c0 = (buf[0] << 8) | buf[1];
    *c1 = (buf[3] << 8) | buf[4];
    *c2 = (buf[6] << 8) | buf[7];
    *c3 = (buf[7] << 8) | buf[7]; /* dummy for 4th byte */
    return 0;
