    uint8_t buf[6];
    if (i2c_read_block(fd, 0x00, buf, 6) < 0) return -1;
    if (crc8(&buf[0], 2) != buf[2]) { fprintf(stderr, "Pressure CRC mismatch\n"); return -1; }
    if (crc8(&buf[3], 2) != buf[5]) { fprintf(stderr, "Temp CRC mismatch\n"); return -1; }
    uint32_t p_raw = (buf[0] << 16) | (buf[1] << 8) | buf[3];
    uint32_t t_raw = (buf[4] << 8) | buf[5];
    float p = (float)p_raw / 1048576.0f;
    float t = (float)t_raw / 1048576.0f;
    float p_comp = c[0] + c[1] * p + c[2] * t + c[3] * p * t;
