    if (!chip) { perror("gpiod_chip_open"); close(fd); return 1; }
    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_LINE);
    if (!led) { perror("gpiod_chip_get_line"); gpiod_chip_close(chip); close(fd); return 1; }
