#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW 28.0
#define LOG_FILE "temperature_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_US 10000
#define SAMPLE_INTERVAL_US 2000000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_temperature(int handle, uint8_t reg, float *temp) {
    char buf[2];
    int rc;

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        rc = i2cWriteByte(handle, reg);
        if (rc < 0) {
            fprintf(stderr, "I2C write failed (reg 0x%02X, attempt %d): %d\n", reg, attempt + 1, rc);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(10000);

        rc = i2cReadDevice(handle, buf, 2);
        if (rc == 2) {
            uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            *temp = (float)raw * 0.02f - 273.15f;
            return 0;
        }

        fprintf(stderr, "I2C read failed (reg 0x%02X, attempt %d): %d\n", reg, attempt + 1, rc);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static void log_temperature(float ambient, float object) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Ambient: %.2f C, Object: %.2f C\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, ambient, object);
    } else {
        fprintf(fp, "(timestamp error), Ambient: %.2f C, Object: %.2f C\n", ambient, object);
    }
    fclose(fp);
}

static void control_fan(float object_temp) {
    static int fan_on = 0;

    if (object_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1);
        fan_on = 1;
        printf("Fan ON (Object: %.2f C)\n", object_temp);
    } else if (object_temp < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0);
        fan_on = 0;
        printf("Fan OFF (Object: %.2f C)\n", object_temp);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90614 temperature monitor started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float ambient, object;

        if (read_temperature(i2c_handle, AMBIENT_TEMP_REG, &ambient) == 0 &&
            read_temperature(i2c_handle, OBJECT_TEMP_REG, &object) == 0) {
            log_temperature(ambient, object);
            control_fan(object);
        } else {
            fprintf(stderr, "Sensor read failed; skipping log entry.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

