#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define PORT 8080
#define MAX_RETRIES 3
#define MEASURE_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_sht40(int handle, float *temperature, float *humidity) {
    unsigned char cmd = MEASURE_CMD;
    unsigned char data[6];
    int result;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cWriteDevice(handle, (char *)&cmd, 1);
        if (result != 0) {
            fprintf(stderr, "I2C write error (attempt %d): %d\n", attempt + 1, result);
            gpioDelay(MEASURE_DELAY_US);
            continue;
        }

        gpioDelay(MEASURE_DELAY_US);

        result = i2cReadDevice(handle, (char *)data, 6);
        if (result != 6) {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", attempt + 1, result);
            continue;
        }

        unsigned int raw_temperature = (data[0] << 8) | data[1];
        unsigned int raw_humidity = (data[3] << 8) | data[4];

        *temperature = -45.0f + 175.0f * (float)raw_temperature / 65535.0f;
        *humidity = -6.0f + 125.0f * (float)raw_humidity / 65535.0f;

        if (*humidity < 0.0f) *humidity = 0.0f;
        if (*humidity > 100.0f) *humidity = 100.0f;

        return 0;
    }

    fprintf(stderr, "Failed to read SHT40 after %d attempts.\n", MAX_RETRIES);
    return -1;
}

void handle_client(int client_socket) {
    float temperature, humidity;
    char buffer[256];

    if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
        snprintf(buffer, sizeof(buffer),
            "HTTP/1.1 200 OK\r\n"
            "Content-Type: text/html\r\n"
            "Connection: close\r\n"
            "\r\n"
            "<!DOCTYPE html><html><head><title>SHT40 Data</title></head><body>"
            "<h1>SHT40 Temperature: %.2f &deg;C</h1><h2>Humidity: %.2f %%</h2>"
            "</body></html>\r\n", temperature, humidity);
    } else {
        snprintf(buffer, sizeof(buffer),
            "HTTP/1.1 500 Internal Server Error\r\n"
            "Content-Type: text/html\r\n"
            "Connection: close\r\n"
            "\r\n"
            "<!DOCTYPE html><html><head><title>Error</title></head><body>"
            "<h1>Sensor Read Error</h1></body></html>\r\n");
    }

    send(client_socket, buffer, strlen(buffer), 0);
    close(client_socket);
}

int main() {
    struct sockaddr_in address;
    int opt = 1;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket failed");
        i2cClose(i2c_handle);
        gpioTerminate();
