#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP102_ADDR 0x48
#define TEMP_REG 0x00
#define LOG_FILE "temperature_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, float *temp_c) {
    int raw = i2cReadWordData(handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading temperature register: %s\n", pigpio_error(raw));
        return -1;
    }
    /* TMP102: 12-bit two's-complement, left-justified in 16 bits.
     * Bits [15:4] = temperature data, bits [3:0] = unused. */
    int16_t shifted = (int16_t)((raw >> 4) & 0x0FFF);
    if (shifted & 0x0800) {
        shifted |= 0xF000; /* sign-extend */
    }
    *temp_c = (float)shifted * 0.0625f;
    return 0;
}

static int log_temperature(float temp_c) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", timestamp, temp_c);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %s\n",
                TMP102_ADDR, pigpio_error(handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        float temp_c;
        if (read_temperature(handle, &temp_c) == 0) {
            if (log_temperature(temp_c) != 0) {
                fprintf(stderr, "Error logging temperature\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature, skipping log entry\n");
        }
        /* Sleep in 1-second increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

