#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HDC2010_ADDR        0x40
#define HDC2010_REG_TEMP_LOW 0x00
#define HDC2010_REG_TEMP_HIGH 0x01
#define HDC2010_REG_HUM_LOW   0x02
#define HDC2010_REG_HUM_HIGH  0x03
#define HDC2010_REG_MEAS_CFG  0x0E
#define HDC2010_REG_CONFIG   0x0F

#define HDC2010_MEAS_TEMP_HUM 0x01
#define HDC2010_CONFIG_HEATER_DIS 0x00
#define HDC2010_CONFIG_14BIT 0x00

#define I2C_BUS 1
#define MAX_RETRIES 3
#define POLL_TIMEOUT_MS 500

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C block read failed (reg=0x%02X, len=%u): %s\n",
                reg, len, pigpio_error(rc));
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "I2C block read short: got %d, expected %u\n",
                rc, len);
        return -1;
    }
    return 0;
}

static int hdc2010_trigger_measurement(int handle) {
    return i2c_write_reg(handle, HDC2010_REG_MEAS_CFG, HDC2010_MEAS_TEMP_HUM);
}

static int hdc2010_wait_measurement(int handle) {
    uint8_t cfg;
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        if (i2c_read_reg(handle, HDC2010_REG_MEAS_CFG, &cfg) < 0)
            return -1;
        if ((cfg & 0x01) == 0)
            return 0;
        gpioDelay(1000);
    }
    fprintf(stderr, "HDC2010 measurement timeout\n");
    return -1;
}

static int hdc2010_read_temperature(int handle, float *temperature) {
    uint8_t buf[2];
    if (i2c_read_block(handle, HDC2010_REG_TEMP_LOW, buf, 2) < 0)
        return -1;
    uint16_t raw = ((uint16_t)buf[1] << 8) | buf[0];
    *temperature = ((float)raw / 65536.0f) * 165.0f - 40.0f;
    return 0;
}

static int hdc2010_read_humidity(int handle, float *humidity) {
    uint8_t buf[2];
    if (i2c_read_block(handle, HDC2010_REG_HUM_LOW, buf, 2) < 0)
        return -1;
    uint16_t raw = ((uint16_t)buf[1] << 8) | buf[0];
    *humidity = ((float)raw / 65536.0f) * 100.0f;
    return 0;
}

static int hdc2010_init(int handle) {
    if (i2c_write_reg(handle, HDC2010_REG_CONFIG,
                      HDC2010_CONFIG_HEATER_DIS | HDC2010_CONFIG_14BIT) < 0)
        return -1;
    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, HDC2010_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, HDC2010_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (hdc2010_init(g_i2c_handle) < 0) {
        fprintf(stderr, "HDC2010 init failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HDC2010 initialised on I2C bus %d, address 0x%02X.\n",
           I2C_BUS, HDC2010_ADDR);
    printf("Temperature: %6.2f C  Humidity: %5.2f %%\n", 0.0f, 0.0f);
    fflush(stdout);

    while (g_running) {
        if (hdc2010_trigger_measurement(g_i2c_handle) < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            break;
        }
        if (hdc2010_wait_measurement(g_i2c_handle) < 0) {
            fprintf(stderr, "Measurement wait failed\n");
            break;
        }

        float temperature, humidity;
        if (hdc2010_read_temperature(g_i2c_handle, &temperature) < 0 ||
            hdc2010_read_humidity(g_i2c_handle, &humidity) < 0) {
            fprintf(stderr, "Sensor read failed; retrying next cycle\n");
            break;
        }

        printf("Temperature: %6.2f C  Humidity: %5.2f %%\n",
               temperature, humidity);
        fflush(stdout);

        for (int i = 0; i < 5 && g_running; i++)
            sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

