#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define RELAY_PIN 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define SAMPLE_INTERVAL_US 1000000
#define SPI_SPEED_HZ 1000000
#define SPI_BITS 8
#define SPI_MODE 0

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_profile(float profile[], int max_points) {
    FILE *fp = fopen(PROFILE_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening profile file: %s\n", strerror(errno));
        return -1;
    }
    char line[256];
    int count = 0;
    while (fgets(line, sizeof(line), fp) && count < max_points) {
        float time, temp;
        if (sscanf(line, "%f,%f", &time, &temp) == 2) {
            profile[count++] = temp;
        }
    }
    fclose(fp);
    return count;
}

static int init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    int bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    int speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", RELAY_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(relay_line, "reflow_oven", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", RELAY_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        relay_line = NULL;
        return -1;
    }
    return 0;
}

static int read_max6675(float *temp) {
    unsigned char tx[3] = {0x00, 0x00, 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    int raw = ((rx[1] & 0x0F) << 8) | rx[2];
    if (raw & 0x0004) {
        fprintf(stderr, "MAX6675 open circuit detected\n");
        return -1;
    }
    *temp = (float)raw / 16.0f;
    return 0;
}

static float pid_control(float current_temp, float target_temp, float *integral, float *prev_error) {
    float error = target_temp - current_temp;
    *integral += error;
    float derivative = error - *prev_error;
    float output = 0.0f;
    if (fabsf(*integral) > 100.0f) {
        output = 0.5f;
    } else {
        output = 0.1f * (*integral) + 0.01f * derivative;
    }
    *prev_error = error;
    if (output < 0.0f) output = 0.0f;
    if (output > 1.0f) output = 1.0f;
    return output;
}

static void set_relay(float duty_cycle) {
    if (duty_cycle < 0.0f) duty_cycle = 0.0f;
    if (duty_cycle > 1.0f) duty_cycle = 1.0f;
    int val = (duty_cycle > 0.5f) ? 1 : 0;
    if (gpiod_line_set_value(relay_line, val) < 0) {
        fprintf(stderr, "Error setting relay GPIO: %s\n", strerror(errno));
    }
}

static void log_data(float temp, float target_temp, float duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, temp, target_temp, duty_cycle);
    fflush(log_file);
}

static void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_spi() < 0) {
        return 1;
    }
    if (init_gpio() < 0) {
        close(spi_fd);
        spi_fd = -1;
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    fprintf(log_file, "timestamp,temperature_c,target_temp_c,duty_cycle\n");

    float profile[100];
    int profile_len = read_profile(profile, 100);
    if (profile_len <= 0) {
        fprintf(stderr, "Failed to read profile\n");
        cleanup();
        return 1;
    }

    float integral = 0.0f, prev_error = 0.0f;
    time_t start_time = 0;
    int point_idx = 0;

    while (running) {
        float temp;
        if (read_max6675(&temp) < 0) {
            fprintf(stderr, "Sensor read error, skipping cycle\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        if (point_idx < profile_len) {
            float target_temp = profile[point_idx];
            float duty_cycle = pid_control(temp, target_temp, &integral, &prev_error);
            set_relay(duty_cycle);
            log_data(temp, target_temp, duty_cycle);
            point_idx++;
        } else {
            point_idx = 0;
        }

        if (start_time == 0) {
            start_time = time(NULL);
        } else if (difftime(time(NULL), start_time) >= 1.0) {
            start_time = time(NULL);
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

