#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <gpiod.h>

#define DS18B20_GPIO_DIR 4
#define HEATER_RELAY_GPIO 17
#define PWM_GPIO 18
#define LOG_FILE "greenhouse.log"
#define SAMPLE_INTERVAL_SEC 5
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *pwm_line = NULL;

static float Kp = 1.0, Ki = 0.1, Kd = 0.01;
static float setpoint = 25.0;
static float integral = 0.0;
static float previous_error = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_ds18b20(float *temperature) {
    char path[256];
    char line[256];
    FILE *fp;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        snprintf(path, sizeof(path), "/sys/bus/w1/devices/28-0x557004444bff/w1_slave");
        fp = fopen(path, "r");
        if (!fp) {
            fprintf(stderr, "Error opening %s: %s. Retry %d/%d\n", path, strerror(errno), retries + 1, MAX_RETRIES);
            retries++;
            sleep(1);
            continue;
        }

        int crc = 0;
        int valid = 1;
        while (fgets(line, sizeof(line), fp) != NULL) {
            if (strstr(line, "YES")) crc = 0;
            else if (strstr(line, "NO")) crc = 1;
            else { valid = 0; break; }
        }
        fclose(fp);

        if (!valid) {
            fprintf(stderr, "CRC error on %s. Retry %d/%d\n", path, retries + 1, MAX_RETRIES);
            retries++;
            sleep(1);
            continue;
        }

        fp = fopen(path, "r");
        if (!fp) {
            fprintf(stderr, "Error opening %s: %s. Retry %d/%d\n", path, strerror(errno), retries + 1, MAX_RETRIES);
            retries++;
            sleep(1);
            continue;
        }

        char *t = strstr(line, "t=");
        if (!t) { fclose(fp); return -1; }
        long temp_raw = strtol(t + 2, NULL, 10);
        *temperature = (float)temp_raw / 1000.0;
        fclose(fp);
        return 0;
    }
    return -1;
}

static float pid_control(float current_temp) {
    float error = setpoint - current_temp;
    integral += error * SAMPLE_INTERVAL_SEC;
    if (integral > 100.0) integral = 100.0;
    if (integral < 0.0) integral = 0.0;
    float derivative = (error - previous_error) / SAMPLE_INTERVAL_SEC;
    float output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;
    return output;
}

static void set_pwm(float duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 100.0) duty_cycle = 100.0;
    int pwm_value = (int)(duty_cycle * 1000000 / 100.0);
    if (pwm_line) gpiod_line_set_value(pwm_line, 1);
    if (pwm_value > 0) {
        gpiod_line_set_value(pwm_line, 1);
        usleep(pwm_value * 1000);
        gpiod_line_set_value(pwm_line, 0);
    }
}

static void log_data(float avg_temp, float pid_out, float pwm_duty) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, %.2f, %.2f, %.2f, %.2f\n", ts, avg_temp, setpoint, pid_out, pwm_duty);
    fflush(log_file);
}

static void cleanup(void) {
    if (relay_line) gpiod_line_set_value(relay_line, 0);
    if (pwm_line) gpiod_line_set_value(pwm_line, 0);
    if (relay_line) gpiod_line_release(relay_line);
    if (pwm_line) gpiod_line_release(pwm_line);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <setpoint_temp> <Kp> <Ki>\n", argv[0]);
        return 1;
    }
    setpoint = atof(argv[1]);
    Kp = atof(argv[2]);
    Ki = atof(argv[3]);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) { perror("fopen log"); return 1; }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) { perror("gpiod_chip_open"); fclose(log_file); return 1; }

    relay_line = gpiod_chip_get_line(chip, HEATER_RELAY_GPIO);
    pwm_line = gpiod_chip_get_line(chip, PWM_GPIO);
    if (!relay_line || !pwm_line) { perror("gpiod_chip_get_line"); cleanup(); return 1; }

    if (gpiod_line_request_output(relay_line, "greenhouse", 0) < 0 ||
        gpiod_line_request_output(pwm_line, "greenhouse", 0) < 0) {
        perror("gpiod_line_request_output"); cleanup(); return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Greenhouse heater started. Setpoint: %.2f C\n", setpoint);

    while (running) {
        float temp = 0.0;
        int ok = 0;
        for (int i = 0; i < MAX_RETRIES && running; i++) {
            if (read_ds18b20(&temp) == 0) { ok = 1; break; }
            sleep(1);
        }
        if (!ok) {
            fprintf(stderr, "Sensor read failed after retries. Skipping cycle.\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float pid_out = pid_control(temp);
        float duty = pid_out;
        if (duty < 0.0) duty = 0.0;
        if (duty > 100.0) duty = 100.0;

        set_pwm(duty);
        log_data((temp + temp) / 2.0, pid_out, duty);
        printf("Temp: %.2f C, PID: %.2f, PWM: %.2f%%\n", temp, pid_out, duty);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

