#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define AHT20_ADDR     0x38
#define GPIO_CHIP      "gpiochip4"
#define GPIO_LINE      17
#define HUMIDITY_HIGH  60.0f
#define HUMIDITY_LOW   55.0f
#define POLL_INTERVAL  5
#define MEAS_DELAY_MS  80
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t msb, uint8_t lsb, uint8_t data) {
    uint8_t buf[3] = { msb, lsb, data };
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, 3) == 3) return 0;
        if (attempt < MAX_RETRIES - 1) usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_data(int fd, uint8_t *buf, int len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (read(fd, buf, len) == len) return 0;
        if (attempt < MAX_RETRIES - 1) usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int aht20_init(int fd) {
    if (i2c_write_cmd(fd, 0xBE, 0x08, 0x00) < 0) return -1;
    usleep(20000);
    if (i2c_write_cmd(fd, 0xBE, 0x08, 0x00) < 0) return -1;
    usleep(20000);
    return 0;
}

static int aht20_read_humidity(int fd, float *humidity) {
    if (i2c_write_cmd(fd, 0xAC, 0x33, 0x00) < 0) return -1;
    usleep(MEAS_DELAY_MS * 1000);

    uint8_t data[6];
    if (i2c_read_data(fd, data, 6) < 0) return -1;

    if (data[0] & 0x01) {
        fprintf(stderr, "AHT20 not calibrated (status=0x%02X)\n", data[0]);
        return -1;
    }
    if (data[0] & 0x02) {
        fprintf(stderr, "AHT20 busy (status=0x%02X)\n", data[0]);
        return -1;
    }

    uint32_t raw = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
    *humidity = (float)raw / 1048576.0f * 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", AHT20_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (aht20_init(i2c_fd) < 0) {
        fprintf(stderr, "AHT20 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line *relay = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!relay) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(relay, "aht20-dehumidifier", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    printf("AHT20 dehumidifier controller started. Press Ctrl+C to exit.\n");

    while (running) {
        float humidity;
        if (aht20_read_humidity(i2c_fd, &humidity) == 0) {
            printf("[%ld] Humidity: %.2f%%\n", (long)time(NULL), humidity);

            if (humidity > HUMIDITY_HIGH) {
                gpiod_line_set_value(relay, 1);
                printf("Dehumidifier ON\n");
            } else if (humidity < HUMIDITY_LOW) {
                gpiod_line_set_value(relay, 0);
                printf("Dehumidifier OFF\n");
            }
        } else {
            fprintf(stderr, "[%ld] Error reading humidity (sensor may be absent or bus error)\n", (long)time(NULL));
        }

        for (int i = 0; i < POLL_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    gpiod_line_set_value(relay, 0);
    gpiod_line_release(relay);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

