        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(relay, "aht20-dehumidifier", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    printf("AHT20 dehumidifier controller started. Press Ctrl+C to exit.\n");

    while (running) {
        float humidity;
        if (aht20_read_humidity(i2c_fd, &humidity) == 0) {
            printf("[%ld] Humidity: %.2f%%\n", (long)time(NULL), humidity);

            if (humidity > HUMIDITY_HIGH) {
                gpiod_line_set_value(relay, 1);
                printf("Dehumidifier ON\n");
            } else if (humidity < HUMIDITY_LOW) {
                gpiod_line_set_value(relay, 0);
                printf("Dehumidifier OFF\n");
            }
        } else {
            fprintf(stderr, "[%ld] Error reading humidity (sensor may be absent or bus error)\n", (long)time(NULL));
        }

        for (int i = 0; i < POLL_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    gpiod_line_set_value(relay, 0);
    gpiod_line_release(relay);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

