#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <syslog.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define HTU21D_ADDR 0x40
#define I2C_BUS "/dev/i2c-1"
#define API_ENDPOINT "http://api.example.com/humidity"
#define READ_INTERVAL 60
#define MAX_RETRIES 3
#define MEASUREMENT_DELAY_MS 20

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int sock_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_write_bytes(int fd, uint8_t *buf, int len) {
    if (write(fd, buf, len) != len) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int read_humidity(int fd, float *humidity) {
    uint8_t cmd[2] = {0x25, 0x00};
    uint8_t buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_bytes(fd, cmd, 2) == 0) {
            usleep(MEASUREMENT_DELAY_MS * 1000);
            if (i2c_read_bytes(fd, buf, 3) == 0) {
                uint16_t raw_h = (buf[0] << 8) | buf[1];
                *humidity = -6.0f + 125.0f * (float)raw_h / 65535.0f;
                return 0;
            }
        }
        retries++;
        usleep(10000);
    }
    syslog(LOG_ERR, "Failed to read humidity after %d retries", MAX_RETRIES);
    return -1;
}

int send_http_post(float humidity) {
    struct sockaddr_in addr;
    char json_string[128];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        memset(&addr, 0, sizeof(addr));
        addr.sin_family = AF_INET;
        addr.sin_port = htons(80);
        if (inet_pton(AF_INET, "api.example.com", &addr.sin_addr) <= 0) {
            syslog(LOG_ERR, "Invalid address: api.example.com");
            retries++;
            sleep(1);
            continue;
        }

        sock_fd = socket(AF_INET, SOCK_STREAM, 0);
        if (sock_fd < 0) {
            syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
            retries++;
            sleep(1);
            continue;
        }

        if (connect(sock_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
            syslog(LOG_ERR, "Connection failed: %s", strerror(errno));
            close(sock_fd);
            sock_fd = -1;
            retries++;
            sleep(1);
            continue;
        }

        snprintf(json_string, sizeof(json_string), "{\"humidity\": %.2f}", humidity);

        if (send(sock_fd, json_string, strlen(json_string), 0) < 0) {
            syslog(LOG_ERR, "Send failed: %s", strerror(errno));
            close(sock_fd);
            sock_fd = -1;
            retries++;
            sleep(1);
            continue;
        }

        close(sock_fd);
        sock_fd = -1;
        return 0;
    }
    syslog(LOG_ERR, "Failed to send HTTP POST after %d retries", MAX_RETRIES);
    return -1;
}

int main() {
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %s: %s", I2C_BUS, strerror(errno));
        closelog();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(i2c_fd);
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Humidity monitor started");

    while (running) {
        float humidity;
        if (read_humidity(i2c_fd, &humidity) == 0) {
            syslog(LOG_INFO, "Humidity: %.2f%%", humidity);
            if (send_http_post(humidity) != 0) {
                syslog(LOG_ERR, "Failed to send HTTP POST");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }
        sleep(READ_INTERVAL);
    }

    if (i2c_fd >= 0) close(i2c_fd);
    if (sock_fd >= 0) close(sock_fd);
    syslog(LOG_INFO, "Humidity monitor stopped");
    closelog();
    return 0;
}

