/* logger.c — Raspberry Pi 4B environmental logger
 *
 * TMP117 temperature + AHT20 humidity + PIR motion logger.
 *
 * Build:  gcc -O2 -Wall -Wextra -o logger logger.c -lgpiod -lrt
 * Run:    ./logger   (requires read/write access to /dev/i2c-1)
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMP117_ADDR    0x48
#define AHT20_ADDR     0x38
#define PIR_GPIO       17
#define SAMPLE_PERIOD  1          /* seconds */
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 10

/* TMP117: temperature register 0x00, 16-bit signed big-endian, LSB = 0.0078125 °C */
#define TMP117_TEMP_REG 0x00

/* AHT20: init cmd 0xBE 0x08 0x00, measure cmd 0xAC 0x33 0x00, 7-byte response */
#define AHT20_INIT_CMD_LEN 3
#define AHT20_MEASURE_CMD_LEN 3
#define AHT20_MEASURE_DELAY_MS 20

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------
 * I2C helpers
 * ------------------------------------------------------------------ */

static int i2c_write_cmd(int fd, uint8_t *cmd, size_t len)
{
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: got %zd of %zu (%s)\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------
 * TMP117 temperature
 * ------------------------------------------------------------------ */

static int read_tmp117(int fd, float *temp_c)
{
    uint8_t buf[2];
    int16_t raw;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_cmd(fd, (uint8_t[]){TMP117_TEMP_REG}, 1) != 0) {
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (i2c_read_block(fd, buf, 2) != 0) {
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        raw = (int16_t)((buf[0] << 8) | buf[1]);
        *temp_c = (float)raw * 0.0078125f;
        return 0;
    }
    return -1;
}

/* ------------------------------------------------------------------
 * AHT20 humidity + temperature
 * ------------------------------------------------------------------ */

static int init_aht20(int fd)
{
    uint8_t init_cmd[AHT20_INIT_CMD_LEN] = {0xBE, 0x08, 0x00};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_cmd(fd, init_cmd, sizeof(init_cmd)) != 0) {
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        usleep(2000);
        uint8_t resp[1];
        if (read(fd, resp, 1) != 1) {
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (resp[0] & 0x80) {
            fprintf(stderr, "AHT20 init busy bit set (attempt %d)\n", attempt + 1);
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        return 0;
    }
    return -1;
}

static int read_aht20(int fd, float *humidity, float *temp_c)
{
    uint8_t measure_cmd[AHT20_MEASURE_CMD_LEN] = {0xAC, 0x33, 0x00};
    uint8_t resp[7];
    int16_t raw_h, raw_t;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_cmd(fd, measure_cmd, sizeof(measure_cmd)) != 0) {
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        usleep(AHT20_MEASURE_DELAY_MS * 1000);

        if (i2c_read_block(fd, resp, sizeof(resp)) != 0) {
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (resp[0] & 0x80) {
            fprintf(stderr, "AHT20 busy after measure (attempt %d)\n", attempt + 1);
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        /* 20-bit humidity: bits [6:4] of byte 1 (upper 4 bits) + bytes 2-6 */
        raw_h = ((int16_t)(resp[1] & 0x3F) << 8) | resp[2];
        /* 20-bit temperature: bytes 3-5 */
        raw_t = ((int16_t)resp[3] << 12) | ((int16_t)resp[4] << 4) | (resp[5] >> 4);

        *humidity = ((float)raw_h / 1048576.0f) * 100.0f;
        *temp_c   = ((float)raw_t / 1048576.0f) * 200.0f - 50.0f;
        return 0;
    }
    return -1;
}

/* ------------------------------------------------------------------
 * Daily log file
 * ------------------------------------------------------------------ */

static void create_daily_file(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char filename[64];

    localtime_r(&now, &tm_info);
    strftime(filename, sizeof(filename), "data_%Y-%m-%d.csv", &tm_info);

    FILE *fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "Cannot create %s: %s\n", filename, strerror(errno));
        return;
    }
    fprintf(fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
    fclose(fp);
}

/* ------------------------------------------------------------------
 * Main
 * ------------------------------------------------------------------ */

int main(void)
{
    int i2c_fd = -1;
    FILE *log_fp = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    int ret = EXIT_FAILURE;

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                TMP117_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Probe TMP117 */
    uint8_t probe = 0xFE;
    if (write(i2c_fd, &probe, 1) != 1) {
        fprintf(stderr, "TMP117 not responding at 0x%02X: %s\n",
                TMP117_ADDR, strerror(errno));
        /* Continue anyway — sensor may be absent */
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                AHT20_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Probe AHT20 */
    probe = 0x00;
    if (write(i2c_fd, &probe, 1) != 1) {
        fprintf(stderr, "AHT20 not responding at 0x%02X: %s\n",
                AHT20_ADDR, strerror(errno));
        /* Continue anyway */
    }

    /* Initialize AHT20 */
    if (init_aht20(i2c_fd) != 0) {
        fprintf(stderr, "AHT20 init failed — continuing without humidity\n");
    }

    /* Open GPIO chip and line for PIR */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open failed: %s\n", strerror(errno));
        goto cleanup;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!pir_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                PIR_GPIO, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(pir_line, "pir_logger") != 0) {
        fprintf(stderr, "gpiod_line_request_input failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Create daily log file */
    create_daily_file();

    printf("Logger started. Sampling every %d s. Press Ctrl+C to stop.\n",
           SAMPLE_PERIOD);

    while (g_running) {
        float temp_c = 0.0f, humidity = 0.0f;
        int motion = 0;
        int pir_val;
        time_t now = time(NULL);
        struct tm tm_info;
        char timestamp[32];

        localtime_r(&now, &tm_info);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

        /* TMP117 */
        if (read_tmp117(i2c_fd, &temp_c) != 0) {
            fprintf(stderr, "%s: TMP117 read failed\n", timestamp);
            temp_c = -999.0f;
        }

        /* AHT20 */
        if (init_aht20(i2c_fd) != 0 || read_aht20(i2c_fd, &humidity, &temp_c) != 0) {
            fprintf(stderr, "%s: AHT20 read failed\n", timestamp);
            humidity = -1.0f;
        }

        /* PIR */
        pir_val = gpiod_line_get_value(pir_line);
        if (pir_val < 0) {
            fprintf(stderr, "%s: PIR read failed: %s\n",
                    timestamp, strerror(errno));
            motion = -1;
        } else {
            motion = (pir_val == 1);
        }

        /* Write CSV */
        log_fp = fopen("data_current.csv", "a");
        if (!log_fp) {
            fprintf(stderr, "%s: Cannot open data_current.csv: %s\n",
                    timestamp, strerror(errno));
        } else {
            fprintf(log_fp, "%s,%.2f,%.2f,%d\n",
                    timestamp, temp_c, humidity, motion);
            fclose(log_fp);
            log_fp = NULL;
        }

        /* Midnight file rotation */
        if (now % 86400 != 0) {
            create_daily_file();
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp) fclose(log_fp);
    if (pir_line) gpiod_line_release(pir_line);
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
    return ret;
}

