static int set_motor_direction(struct gpiod_line *in1, struct gpiod_line *in2, int direction) {
    if (direction == 0) {
        if (gpiod_line_set_value(in1, 0) < 0 || gpiod_line_set_value(in2, 0) < 0) {
            log_event("Error setting motor direction to stop.");
            return -1;
        }
        return 0;
    }
    if (gpiod_line_set_value(in1, 1) < 0 || gpiod_line_set_value(in2, 0) < 0) {
        log_event("Error setting motor direction to forward.");
        return -1;
    }
    return 0;
}

static int run_motor(struct gpiod_line *enable, struct gpiod_line *in1, struct gpiod_line *in2, int duration_sec) {
