    enable_line = gpiod_chip_get_line(chip, MOTOR_ENABLE_PIN);
    in1_line = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);
    if (!rain_line || !enable_line || !in1_line || !in2_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_input(rain_line, "rain_sensor") < 0) {
        perror("gpiod_line_request_input(rain_line)");
        goto cleanup;
    }
    if (gpiod_line_request_output(enable_line, "motor_enable", 0) < 0) {
        perror("gpiod_line_request_output(enable_line)");
        goto cleanup;
    }
    if (gpiod_line_request_output(in1_line, "motor_in1", 0) < 0) {
        perror("gpiod_line_request_output(in1_line)");
        goto cleanup;
    }
    if (gpiod_line_request_output(in2_line, "motor_in2", 0) < 0) {
        perror("gpiod_line_request_output(in2_line)");
        goto cleanup;
    }

    log_event("Program started. Monitoring rain sensor...");

    while (program_running) {
        int rain_value = gpiod_line_get_value(rain_line);
        if (rain_value < 0) {
            perror("gpiod_line_get_value(rain_line)");
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (rain_value == 0) {
            log_event("Rain detected!");
            if (run_motor(enable_line, in1_line, in2_line, MOTOR_RUN_SEC) < 0) {
                log_event("Motor control failed.");
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

