    long prev_system_raw = strtol(token, NULL, 10);
    token = strtok(NULL, " \t");
    if (!token) { free(prev_ptr); return 0.0; }
    long prev_idle_raw = strtol(token, NULL, 10);

    prev_user = (double)prev_user_raw;
    prev_nice = (double)prev_nice_raw;
    prev_system = (double)prev_system_raw;
    prev_idle = (double)prev_idle_raw;

    /* Parse the current line */
    char *curr_ptr = strdup(curr_line);
    if (!curr_ptr) {
        perror("strdup");
        return 0.0;
    }

    token = strtok(curr_ptr, " \t");
    if (!token) { free(curr_ptr); return 0.0; }
    long curr_user_raw = strtol(token, NULL, 10);
    token = strtok(NULL, " \t");
    if (!token) { free(curr_ptr); return 0.0; }
    long curr_nice_raw = strtol(token, NULL, 10);
    token = strtok(NULL, " \t");
    if (!token) { free(curr_ptr); return 0.0; }
    long curr_system_raw = strtol(token, NULL, 10);
    token = strtok(NULL, " \t");
    if (!token) { free(curr_ptr); return 0.0; }
    long curr_idle_raw = strtol(token, NULL, 10);

    long curr_user = (long)curr_user_raw;
    long curr_nice = (long)curr_nice_raw;
    long curr_system = (long)curr_system_raw;
    long curr_idle = (long)curr_idle_raw;

    /* Compute the delta */
    long prev_total = prev_user + prev_nice + prev_system + prev_idle;
    long curr_total = curr_user + curr_nice + curr_system + curr_idle;

    if (prev_total == 0) {
        free(prev_ptr);
        return 0.0;
    }

    long delta_user = curr_user - prev_user;
    long delta_nice = curr_nice - prev_nice;
    long delta_system = curr_system - prev_system;
    long delta_idle = curr_idle - prev_idle;

    long delta_total = delta_user + delta_nice + delta_system + delta_idle;

    double delta = (double)delta_total / (double)prev_total;

    free(prev_ptr);
    free(curr_ptr);

    return delta;
}

/*
 * Map CPU load (0.0-1.0) to RGB values (0-255).
 * 0% -> Green, 50% -> Yellow, 100% -> Red.
 */
static void map_cpu_load_to_rgb(double cpu_load, int *r, int *g, int *b)
{
    if (cpu_load < 0.0) cpu_load = 0.0;
    if (cpu_load > 1.0) cpu_load = 1.0;

    if (cpu_load < 0.5) {
        *r = 0;
        *g = (int)(cpu_load * 255.0);
        *b = 0;
    } else {
        *r = (int)((cpu_load - 0.5) * 255.0);
        *g = 255;
        *b = 0;
    }
}

/*
 * Set the RGB LED color using hardware PWM.
 * For a common-anode LED, a value of 255 means OFF (cathode high).
 */
static void set_led_color(int r, int g, int b)
{
    if (r < 0) r = 0; if (r > 255) r = 255;
    if (g < 0) g = 0; if (g > 255) g = 255;
    if (b < 0) b = 0; if (b > 255) b = 255;

    gpioPWM(RED_PIN,   PWM_RANGE - r);
    gpioPWM(GREEN_PIN, PWM_RANGE - g);
    gpioPWM(BLUE_PIN,  PWM_RANGE - b);
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    /* Configure PWM on the three pins */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0)
    {
        fprintf(stderr, "Error: failed to set GPIO modes.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0)
    {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        gpioTerminate();
        return 1;
    }

    /* Read initial /proc/stat */
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("fopen(/proc/stat)");
        gpioTerminate();
        return 1;
    }

    char line1[256];
    char line2[256];
    if (!fgets(line1, sizeof(line1), fp) || !fgets(line2, sizeof(line2), fp)) {
        perror("fgets(/proc/stat)");
        fclose(fp);
        gpioTerminate();
        return 1;
    }
    fclose(fp);

    double prev_cpu_load = 0.0;
    int prev_r = 0, prev_g = 0, prev_b = 0;

    /* Main loop */
    while (g_running) {
        /* Read current /proc/stat */
        fp = fopen("/proc/stat", "r");
        if (!fp) {
            perror("fopen(/proc/stat)");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        char line3[256];
        char line4[256];
        if (!fgets(line3, sizeof(line3), fp) || !fgets(line4, sizeof(line4), fp)) {
            perror("fgets(/proc/stat)");
            fclose(fp);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        fclose(fp);

        double cpu_load = calculate_cpu_load(line1, line3);

        int r, g, b;
        map_cpu_load_to_rgb(cpu_load, &r, &g, &b);

        set_led_color(r, g, b);

        prev_cpu_load = cpu_load;
        prev_r = r;
        prev_g = g;
        prev_b = b;

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown: turn LED off (common-anode: all channels high) */
    set_led_color(255, 255, 255);

    gpioTerminate();
    return 0;
}

