#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_REG_CHIP_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_DATA 0xF7
#define BMP280_REG_CALIB 0x88
#define BMP280_CHIP_ID 0x58
#define UDP_SERVER_IP "192.168.1.100"
#define UDP_SERVER_PORT 5000
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int udp_socket = -1;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

static bmp280_calib_data calib;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(int handle, bmp280_calib_data *c) {
    uint8_t buf[24];
    if (i2cReadI2CBlockData(handle, BMP280_REG_CALIB, (char *)buf, 24) != 24) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    c->dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    c->dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    c->dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    c->dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    c->dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    c->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    c->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    c->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    c->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    c->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    c->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    c->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int read_raw_data(int handle, int32_t *temp, int32_t *press) {
    uint8_t buf[6];
    if (i2cWriteByteData(handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_MEAS\n");
        return -1;
    }
    gpioDelay(10000);
    if (i2cReadI2CBlockData(handle, BMP280_REG_DATA, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read data\n");
        return -1;
    }
    *press = (int32_t)(((uint32_t)buf[0] << 12) | ((uint32_t)buf[1] << 4) | ((uint32_t)buf[2] >> 4));
    *temp = (int32_t)(((uint32_t)buf[3] << 12) | ((uint32_t)buf[4] << 4) | ((uint32_t)buf[5] >> 4));
    return 0;
}

static double compensate_temperature(int32_t raw_temp, int32_t *t_fine) {
    double var1 = ((double)raw_temp / 16384.0 - (double)calib.dig_T1 / 1024.0) * (double)calib.dig_T2;
    double var2 = ((double)raw_temp / 131072.0 - (double)calib.dig_T1 / 8192.0) * ((double)raw_temp / 131072.0 - (double)calib.dig_T1 / 8192.0) * (double)calib.dig_T3;
    *t_fine = (int32_t)(var1 + var2);
    return (var1 + var2) / 5120.0;
}

static double compensate_pressure(int32_t raw_press, int32_t t_fine) {
    double var1 = (double)t_fine / 2.0 - 64000.0;
    double var2 = var1 * var1 * (double)calib.dig_P6 / 32768.0;
    var2 = var2 + var1 * (double)calib.dig_P5 * 2.0;
    var2 = var2 / 4.0 + (double)calib.dig_P4 * 65536.0;
    var1 = ((double)calib.dig_P3 * var1 * var1 / 524288.0 + (double)calib.dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * (double)calib.dig_P1;
    if (var1 == 0.0) return 0.0;
    double p = 1048576.0 - (double)raw_press;
    p = (p - var2 / 4096.0) * 6250.0 / var1;
    var1 = (double)calib.dig_P9 * p * p / 2147483648.0;
    var2 = p * (double)calib.dig_P8 / 32768.0;
    p = p + (var1 + var2 + (double)calib.dig_P7) / 16.0;
    return p;
}

static int send_udp_data(double temp, double press) {
    struct sockaddr_in addr;
    char buffer[128];
    int len = snprintf(buffer, sizeof(buffer), "{\"temperature\":%.2f,\"pressure\":%.2f}", temp, press);
    if (len < 0 || len >= (int)sizeof(buffer)) return -1;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(UDP_SERVER_PORT);
    if (inet_pton(AF_INET, UDP_SERVER_IP, &addr.sin_addr) <= 0) return -1;
    if (sendto(udp_socket, buffer, len, 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto failed");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    int chip_id = i2cReadByteData(i2c_handle, BMP280_REG_CHIP_ID);
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (read_calibration_data(i2c_handle, &calib) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("socket creation failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        int32_t raw_temp, raw_press;
        if (read_raw_data(i2c_handle, &raw_temp, &raw_press) == 0) {
            int32_t t_fine;
            double temp = compensate_temperature(raw_temp, &t_fine);
            double press = compensate_pressure(raw_press, t_fine);
            if (send_udp_data(temp, press) != 0) {
                fprintf(stderr, "Warning: UDP send failed\n");
            } else {
                printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temp, press);
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (udp_socket >= 0) close(udp_socket);
    gpioTerminate();
    return 0;
}

