#define FAN_GPIO          18
#define SPI_CHANNEL       0
#define SPI_SPEED         500000
#define SPI_FLAGS         0
#define PWM_FREQUENCY     1000
#define PWM_RANGE         255
#define BUFFER_SIZE       20
#define SAMPLE_INTERVAL   1

#define TEMP_THRESHOLD_1  25.0f
#define TEMP_THRESHOLD_2  40.0f
#define TEMP_THRESHOLD_3  60.0f

#define TEMP_MIN          0.0f
#define TEMP_MAX          1000.0f

#define PWM_DUTY_OFF      0
#define PWM_DUTY_LOW      50
#define PWM_DUTY_MED      150
#define PWM_DUTY_HIGH     200

typedef struct {
    time_t timestamp;
    float  temperature;
    int    pwm_duty;
} TemperatureReading;

static TemperatureReading temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

