                printf("Logged: %.2f C, %.2f Pa\n", temperature, pressure);
            } else {
                fprintf(stderr, "Error reading BMP180 data\n");
            }
        }
        gpioDelay(1000000);
    }
    printf("\nExiting gracefully...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

