#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "rtd_log.csv"
#define CS_PIN 8
#define SPI_SPEED_HZ 1000000
#define SAMPLE_INTERVAL_SEC 5

#define MAX31865_REG_RTD_MSB 0x00
#define MAX31865_REG_RTD_LSB 0x01
#define MAX31865_REG_FAULT 0x02
#define MAX31865_REG_CONFIG 0x03

#define MAX31865_CONFIG_3WIRE_RTD_BIAS_ON 0x03

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED_HZ;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int cs_init(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", CS_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "max31865_cs", 1) < 0) {
        fprintf(stderr, "Error requesting CS line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        cs_line = NULL;
        return -1;
    }

    return 0;
}

static int max31865_write_reg(uint8_t reg, uint8_t value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), value };
    uint8_t rx[2] = {0};

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Error asserting CS low: %s\n", strerror(errno));
        return -1;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI write: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Error deasserting CS high: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int max31865_read_reg(uint8_t reg, uint8_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), 0x00 };
    uint8_t rx[2] = {0};

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Error asserting CS low: %s\n", strerror(errno));
        return -1;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI read: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    *value = rx[1];

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Error deasserting CS high: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int max31865_init(void) {
    if (max31865_write_reg(MAX31865_REG_CONFIG, MAX31865_CONFIG_3WIRE_RTD_BIAS_ON) < 0) {
        fprintf(stderr, "Error initializing MAX31865\n");
        return -1;
    }
    return 0;
}

static int read_rtd_raw(int16_t *raw_temp) {
    uint8_t msb, lsb;
    if (max31865_read_reg(MAX31865_REG_RTD_MSB, &msb) < 0) return -1;
    if (max31865_read_reg(MAX31865_REG_RTD_LSB, &lsb) < 0) return -1;

    *raw_temp = (int16_t)((msb << 8) | lsb);
    return 0;
}

static int read_fault(uint8_t *fault) {
    return max31865_read_reg(MAX31865_REG_FAULT, fault);
}

static float calculate_temperature(int16_t raw_temp) {
    const float r0 = 3.9083e-3;
    const float r_ext = 3.4625e-3;
    const float a = 0.0000003125;
    const float b = 0.0000000001225;
    const float c = -0.000000000000542;

    float r_load = r0 * (1.0 + (raw_temp / 32768.0));
    float temp = (a + (b * r_load) + (c * r_load * r_load)) * r_ext;
    return temp;
}

static int log_data(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (cs_init() < 0) {
        cleanup();
        return 1;
    }

    if (max31865_init() < 0) {
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature\n");
        fflush(log_file);
    }

    printf("Starting temperature monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t raw_temp;
        uint8_t fault;
        float temperature;

        if (read_rtd_raw(&raw_temp) < 0) {
            fprintf(stderr, "Error reading RTD raw value\n");
        } else if (read_fault(&fault) < 0) {
            fprintf(stderr, "Error reading fault register\n");
        } else {
            if (fault & 0x01) {
                fprintf(stderr, "MAX31865 fault detected: 0x%02X\n", fault);
            } else {
                temperature = calculate_temperature(raw_temp);
                if (log_data(temperature) < 0) {
                    fprintf(stderr, "Error logging data\n");
                } else {
                    printf("Temperature: %.2f C\n", temperature);
                }
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully.\n");
    cleanup();
    return 0;
}

