#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_OSS 0
#define ALERT_GPIO 24
#define BUFFER_SIZE (60 * 10)
#define SAMPLE_INTERVAL_US 50000
#define PRESSURE_THRESHOLD 5.0

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

typedef struct {
    time_t timestamp;
    float pressure;
} PressureReading;

static PressureReading pressure_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(void) {
    int result;
    result = i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1);
    if (result < 0) return -1;
    ac1 = (int16_t)result;
    result = i2cReadByteData(i2c_handle, 0xAC);
    if (result < 0) return -1;
    ac2 = (int16_t)result;
    result = i2cReadByteData(i2c_handle, 0xAE);
    if (result < 0) return -1;
    ac3 = (int16_t)result;
    result = i2cReadByteData(i2c_handle, 0xB0);
    if (result < 0) return -1;
    ac4 = (uint16_t)result;
    result = i2cReadByteData(i2c_handle, 0xB2);
    if (result < 0) return -1;
    ac5 = (uint16_t)result;
    result = i2cReadByteData(i2c_handle, 0xB4);
    if (result < 0) return -1;
    ac6 = (uint16_t)result;
    result = i2cReadByteData(i2c_handle, 0xB6);
    if (result < 0) return -1;
    b1 = (int16_t)result;
    result = i2cReadByteData(i2c_handle, 0xB8);
    if (result < 0) return -1;
    b2 = (int16_t)result;
    result = i2cReadByteData(i2c_handle, 0xBA);
    if (result < 0) return -1;
    mb = (int16_t)result;
    result = i2cReadByteData(i2c_handle, 0xBC);
    if (result < 0) return -1;
    mc = (int16_t)result;
    result = i2cReadByteData(i2c_handle, 0xBE);
    if (result < 0) return -1;
    md = (int16_t)result;
    return 0;
}

static int read_raw_temperature(void) {
    int msb, lsb;
    msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    if (msb < 0) return -1;
    lsb = i2cReadByteData(i2c_handle, BMP180_REG_MSB + 1);
    if (lsb < 0) return -1;
    return (msb << 8) | lsb;
}

static int read_raw_pressure(void) {
    int msb, lsb, xlsb;
    msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    if (msb < 0) return -1;
    lsb = i2cReadByteData(i2c_handle, BMP180_REG_MSB + 1);
    if (lsb < 0) return -1;
    xlsb = i2cReadByteData(i2c_handle, BMP180_REG_MSB + 2);
    if (xlsb < 0) return -1;
    return ((msb << 16) | (lsb << 8) | xlsb) >> (8 - BMP180_OSS);
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    return x1 + x2;
}

static float calculate_pressure(int32_t up, int32_t b5) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (float)p;
}

static void add_reading(float pressure) {
    time(&pressure_buffer[buffer_index].timestamp);
    pressure_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static float calculate_average_pressure(void) {
    if (buffer_count == 0) return 0.0;
    float sum = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        sum += pressure_buffer[i].pressure;
    }
    return sum / buffer_count;
}

static void alert_callback(void *user_data) {
    (void)user_data;
    if (buffer_count >= 60) {
        float avg = calculate_average_pressure();
        float diff = pressure_buffer[buffer_index].pressure - avg;
        if (diff > PRESSURE_THRESHOLD) {
            gpioWrite(ALERT_GPIO, 1);
            time_t now = time(NULL);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(stderr, "%s - ALERT: Pressure deviation %.2f hPa\n", ts, diff);
            gpioWrite(ALERT_GPIO, 0);
        }
    }
}

static void timer_callback(void *user_data) {
    (void)user_data;
    int32_t ut, up;
    int32_t b5;
    if (read_raw_temperature() < 0) {
        fprintf(stderr, "Error reading temperature\n");
        return;
    }
    ut = read_raw_temperature();
    b5 = compute_b5(ut);
    if (read_raw_pressure() < 0) {
        fprintf(stderr, "Error reading pressure\n");
        return;
    }
    up = read_raw_pressure();
    float pressure = calculate_pressure(up, b5);
    add_reading(pressure);
    gpioWrite(ALERT_GPIO, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data() < 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, timer_callback, NULL) < 0) {
        fprintf(stderr, "Error setting timer\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    while (running) {
        gpioDelay(100000);
    }
    gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, NULL, NULL);
    gpioWrite(ALERT_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

