#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34
#define BMP180_OSS 0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(void) {
    uint8_t buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, (char *)buf, 22) != 22) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1 = (int16_t)((buf[12] << 8) | buf[13]);
    b2 = (int16_t)((buf[14] << 8) | buf[15]);
    mb = (int16_t)((buf[16] << 8) | buf[17]);
    mc = (int16_t)((buf[18] << 8) | buf[19]);
    md = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temperature(int32_t *raw_temp) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) {
        fprintf(stderr, "Error: Failed to write temperature command\n");
        return -1;
    }
    gpioDelay(5000);
    uint8_t buf[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read raw temperature\n");
        return -1;
    }
    *raw_temp = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int32_t *raw_pressure) {
    uint8_t cmd = BMP180_CMD_PRESSURE0 | (BMP180_OSS << 6);
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, cmd) < 0) {
        fprintf(stderr, "Error: Failed to write pressure command\n");
        return -1;
    }
    gpioDelay(26000);
    uint8_t buf[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: Failed to read raw pressure\n");
        return -1;
    }
    *raw_pressure = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | (int32_t)buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

static int calculate_b5(int32_t ut, int32_t *b5_out) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;
    *b5_out = b5;
    return 0;
}

static int calculate_temperature(int32_t ut, int32_t b5, float *temp_out) {
    int32_t t = (b5 + 8) >> 4;
    int32_t x1 = ((t >> 3) * (t >> 3)) >> 13;
    x1 = (x1 * (int32_t)b2) >> 16;
    int32_t x2 = (t * (int32_t)ac2) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;
    x1 = ((int32_t)ac3 * t) >> 13;
    x2 = ((t * (int32_t)ac2) >> 11) + 16;
    x3 = (x1 + x2) + 32768;
    uint32_t b6 = (uint32_t)(x3 * (uint32_t)ac4) >> 15;
    int32_t b4 = (b6 - b3) * 50000;
    int32_t b7 = ((int32_t)md * 100000) >> 16;
    int32_t t_final = (b4 + b7) >> 16;
    *temp_out = (float)t_final / 100.0f;
    return 0;
}

static int calculate_pressure(int32_t up, int32_t b5, float *pressure_out) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * (b6 * b6 >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;
    uint32_t x1_u = ((uint32_t)ac3 * b6) >> 13;
    uint32_t x2_u = ((uint32_t)b1 * (b6 * b6 >> 12)) >> 16;
    uint32_t x3_u = (x1_u + x2_u + 32768) >> 15;
    uint32_t b4 = (uint32_t)(x3 + x3_u) * 50000;
    uint32_t b7 = ((uint32_t)up - b3) * 50000;
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    *pressure_out = (float)p;
    return 0;
}

static void log_data(float temperature, float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
    fflush(log_file);
}

