        gpioTerminate();
        return 1;
    }
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error: Invalid calibration data (sensor absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen("bmp180_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    while (running) {
        int32_t ut, up, b5;
        if (read_raw_temperature(&ut) != 0 || read_raw_pressure(&up) != 0) {
            fprintf(stderr, "Error: Sensor read failed, retrying...\n");
            gpioDelay(1000000);
