#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define BMP280_ADDR_1 0x76
#define BMP280_ADDR_2 0x77
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_REG 0xE0
#define BMP280_RESET_CMD 0xB6
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_CTRL_MEAS_VAL 0x27
#define BMP280_STATUS_REG 0xF3
#define BMP280_DATA_REG 0xF7
#define BMP280_CALIB_REG 0x88
#define BMP280_CALIB_LEN 24
#define LOG_FILE "weather_data.txt"
#define SAMPLE_INTERVAL_SEC 5
#define MEAS_TIMEOUT_MS 100

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_t;

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg(0x%02X, 0x%02X) failed: %s\n", reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_regs write(0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_regs read(0x%02X, %zu) failed: got %zd (%s)\n", reg, len, n, strerror(errno));
        return -1;
    }
    return 0;
}

static int bmp280_read_calibration(int fd, bmp280_calib_t *cal) {
    uint8_t buf[BMP280_CALIB_LEN];
    if (i2c_read_regs(fd, BMP280_CALIB_REG, buf, BMP280_CALIB_LEN) != 0)
        return -1;
    cal->dig_T1 = (uint16_t)(buf[0]  | (buf[1]  << 8));
    cal->dig_T2 = (int16_t)(buf[2]  | (buf[3]  << 8));
    cal->dig_T3 = (int16_t)(buf[4]  | (buf[5]  << 8));
    cal->dig_P1 = (uint16_t)(buf[6]  | (buf[7]  << 8));
    cal->dig_P2 = (int16_t)(buf[8]  | (buf[9]  << 8));
    cal->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    cal->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    cal->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    cal->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    cal->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    cal->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    cal->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int bmp280_read_raw(int fd, int32_t *raw_t, int32_t *raw_p) {
    uint8_t buf[6];
    if (i2c_read_regs(fd, BMP280_DATA_REG, buf, 6) != 0)
        return -1;
    *raw_p = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | (buf[2] >> 4);
    *raw_t = ((int32_t)buf[3] << 12) | ((int32_t)buf[4] << 4) | (buf[5] >> 4);
    return 0;
}

static double bmp280_compensate_temp(int32_t raw_t, const bmp280_calib_t *cal, int32_t *t_fine) {
    int32_t var1 = ((((raw_t >> 3) - ((int32_t)cal->dig_T1 << 1))) * ((int32_t)cal->dig_T2)) >> 11;
    int32_t var2 = (((((raw_t >> 4) - ((int32_t)cal->dig_T1)) * ((raw_t >> 4) - ((int32_t)cal->dig_T1))) >> 12) * ((int32_t)cal->dig_T3)) >> 14;
    *t_fine = var1 + var2;
    int32_t T = (*t_fine * 5 + 128) >> 8;
    return (double)T / 100.0;
}

static double bmp280_compensate_press(int32_t raw_p, const bmp280_calib_t *cal, int32_t t_fine) {
    int64_t var1 = ((int64_t)t_fine) - 128000;
    int64_t var2 = var1 * var1 * (int64_t)cal->dig_P6;
    var2 = var2 + ((var1 * (int64_t)cal->dig_P5) << 17);
    var2 = var2 + (((int64_t)cal->dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)cal->dig_P3) >> 8) + ((var1 * (int64_t)cal->dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)cal->dig_P1) >> 33;
    if (var1 == 0) return 0.0;
    int64_t p = 1048576 - raw_p;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)cal->dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)cal->dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)cal->dig_P7) << 4);
    return (double)p / 256.0;
}

static int bmp280_init(int fd, bmp280_calib_t *cal) {
    uint8_t chip_id;
    if (i2c_read_regs(fd, BMP280_CHIP_ID_REG, &chip_id, 1) != 0)
        return -1;
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "BMP280 chip_id mismatch: got 0x%02X, expected 0x%02X\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2c_write_reg(fd, BMP280_RESET_REG, BMP280_RESET_CMD) != 0)
        return -1;
    usleep(2000);
    if (bmp280_read_calibration(fd, cal) != 0)
        return -1;
    if (i2c_write_reg(fd, BMP280_CTRL_MEAS_REG, BMP280_CTRL_MEAS_VAL) != 0)
        return -1;
    return 0;
}

static int bmp280_read(int fd, const bmp280_calib_t *cal, double *temp, double *press) {
    if (i2c_write_reg(fd, BMP280_CTRL_MEAS_REG, BMP280_CTRL_MEAS_VAL) != 0)
        return -1;
    uint8_t status;
    int timeout = 0;
    do {
        if (i2c_read_regs(fd, BMP280_STATUS_REG, &status, 1) != 0)
            return -1;
        if (status & 0x08) {
            timeout = 0;
        } else {
            usleep(2000);
            timeout += 2;
            if (timeout > MEAS_TIMEOUT_MS) {
                fprintf(stderr, "BMP280 measurement timeout\n");
                return -1;
            }
        }
    } while (status & 0x08);
    int32_t raw_t, raw_p;
    if (bmp280_read_raw(fd, &raw_t, &raw_p) != 0)
        return -1;
    int32_t t_fine;
    *temp = bmp280_compensate_temp(raw_t, cal, &t_fine);
    *press = bmp280_compensate_press(raw_p, cal, t_fine);
    return 0;
}

static int log_data(const char *filename, double temp, double press) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", filename, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", ts, temp, press) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    int addrs[2] = {BMP280_ADDR_1, BMP280_ADDR_2};
    int found = 0;
    for (int i = 0; i < 2; i++) {
        if (ioctl(fd, I2C_SLAVE, addrs[i]) < 0) {
            fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", addrs[i], strerror(errno));
            continue;
        }
        uint8_t chip_id;
        if (i2c_read_regs(fd, BMP280_CHIP_ID_REG, &chip_id, 1) != 0) {
            fprintf(stderr, "No BMP280 at 0x%02X\n", addrs[i]);
            continue;
        }
        if (chip_id == BMP280_CHIP_ID) {
            printf("BMP280 found at 0x%02X\n", addrs[i]);
            found = 1;
            break;
        }
    }
    if (!found) {
        fprintf(stderr, "BMP280 not found on %s\n", I2C_BUS);
        close(fd);
        return 1;
    }
    bmp280_calib_t cal;
    if (bmp280_init(fd, &cal) != 0) {
        fprintf(stderr, "BMP280 init failed\n");
        close(fd);
        return 1;
    }
    printf("BMP280 initialized. Logging to %s every %d seconds.\n", LOG_FILE, SAMPLE_INTERVAL_SEC);
    while (g_running) {
        double temp, press;
        if (bmp280_read(fd, &cal, &temp, &press) != 0) {
            fprintf(stderr, "Read failed; continuing\n");
        } else {
            if (log_data(LOG_FILE, temp, press) != 0)
                fprintf(stderr, "Log failed\n");
            else
                printf("Logged: %.2f °C, %.2f hPa\n", temp, press);
        }
        for (int s = 0; s < SAMPLE_INTERVAL_SEC && g_running; s++)
            sleep(1);
    }
    printf("\nExiting cleanly.\n");
    close(fd);
    return 0;
}

