    int32_t raw_t, raw_p;
    if (bmp280_read_raw(fd, &raw_t, &raw_p) != 0)
        return -1;
    int32_t t_fine;
    *temp = bmp280_compensate_temp(raw_t, cal, &t_fine);
    *press = bmp280_compensate_press(raw_p, cal, t_fine);
    return 0;
}

static int log_data(const char *filename, double temp, double press) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", filename, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", ts, temp, press) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    int addrs[2] = {BMP280_ADDR_1, BMP280_ADDR_2};
    int found = 0;
    for (int i = 0; i < 2; i++) {
        if (ioctl(fd, I2C_SLAVE, addrs[i]) < 0) {
            fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", addrs[i], strerror(errno));
            continue;
        }
        uint8_t chip_id;
        if (i2c_read_regs(fd, BMP280_CHIP_ID_REG, &chip_id, 1) != 0) {
            fprintf(stderr, "No BMP280 at 0x%02X\n", addrs[i]);
            continue;
        }
        if (chip_id == BMP280_CHIP_ID) {
            printf("BMP280 found at 0x%02X\n", addrs[i]);
            found = 1;
            break;
        }
    }
    if (!found) {
        fprintf(stderr, "BMP280 not found on %s\n", I2C_BUS);
        close(fd);
        return 1;
    }
    bmp280_calib_t cal;
    if (bmp280_init(fd, &cal) != 0) {
        fprintf(stderr, "BMP280 init failed\n");
        close(fd);
        return 1;
    }
    printf("BMP280 initialized. Logging to %s every %d seconds.\n", LOG_FILE, SAMPLE_INTERVAL_SEC);
    while (g_running) {
        double temp, press;
        if (bmp280_read(fd, &cal, &temp, &press) != 0) {
            fprintf(stderr, "Read failed; continuing\n");
        } else {
            if (log_data(LOG_FILE, temp, press) != 0)
                fprintf(stderr, "Log failed\n");
            else
                printf("Logged: %.2f °C, %.2f hPa\n", temp, press);
        }
        for (int s = 0; s < SAMPLE_INTERVAL_SEC && g_running; s++)
            sleep(1);
    }
    printf("\nExiting cleanly.\n");
    close(fd);
    return 0;
}

