#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <pthread.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define LM75_ADDR      0x48
#define TEMP_REG       0x00
#define GPIO_CHIP      "gpiochip4"
#define GPIO_LINE      18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD 28.0f
#define POLL_INTERVAL  1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static float temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LM75_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", LM75_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }
    led_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!led_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(led_line, "lm75_monitor", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        led_line = NULL;
        return -1;
    }
    return 0;
}

static int read_temperature(float *temp) {
    uint8_t reg = TEMP_REG;
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing temperature register address: %s\n", strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    raw >>= 5;
    *temp = (float)raw / 256.0f;
    return 0;
}

static void update_buffer(float temp) {
    pthread_mutex_lock(&buffer_mutex);
    temperature_buffer[buffer_index] = temp;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++) sum += temperature_buffer[i];
    float avg = buffer_count > 0 ? sum / (float)buffer_count : 0.0f;
    printf("Temperature: %.2f C, Buffer: %.2f C (avg %d/%d)\n", temp, avg, buffer_count, BUFFER_SIZE);
    pthread_mutex_unlock(&buffer_mutex);
}

static void control_led(float temp) {
    int val = (temp > TEMP_THRESHOLD) ? 1 : 0;
    if (gpiod_line_set_value(led_line, val) < 0) {
        fprintf(stderr, "Error setting LED value: %s\n", strerror(errno));
    }
}

static void *data_acquisition_thread(void *arg) {
    (void)arg;
    while (running) {
        float temp;
        if (read_temperature(&temp) == 0) {
            update_buffer(temp);
            control_led(temp);
        } else {
            fprintf(stderr, "Temperature read failed, attempting re-init...\n");
            if (i2c_fd >= 0) close(i2c_fd);
            i2c_fd = -1;
            sleep(1);
            if (init_i2c() != 0) {
                fprintf(stderr, "I2C re-init failed, retrying in %d s...\n", POLL_INTERVAL);
                sleep(POLL_INTERVAL);
            }
        }
        sleep(POLL_INTERVAL);
    }
    return NULL;
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    pthread_mutex_destroy(&buffer_mutex);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (init_i2c() != 0) return 1;
    if (init_gpio() != 0) {
        close(i2c_fd);
        return 1;
    }
    pthread_t tid;
    if (pthread_create(&tid, NULL, data_acquisition_thread, NULL) != 0) {
        fprintf(stderr, "Error creating data acquisition thread: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    while (running) sleep(1);
    pthread_join(tid, NULL);
    cleanup();
    return 0;
}

