#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_FLAGS 0x0000  /* mode 1, active-low CE */

#define MAX31865_CONFIG_REG 0x80
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_STATUS_REG 0x07

#define R_REF 430.0
#define PT100_NOMINAL_R 100.0
#define MAX_TEMP 80.0
#define PWM_FREQ 1000
#define PWM_RANGE 1000
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

typedef struct {
    double target_temperature;
    double Kp;
    double Ki;
    double Kd;
} PID_Config;

static PID_Config pid_config;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename, PID_Config *cfg) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: could not open config '%s', using defaults\n", filename);
        cfg->target_temperature = 25.0;
        cfg->Kp = 1.0;
        cfg->Ki = 0.1;
        cfg->Kd = 0.01;
        return -1;
    }
    char line[256];
    int got_target = 0, got_kp = 0, got_ki = 0, got_kd = 0;
    while (fgets(line, sizeof(line), fp)) {
        char *p = line;
        while (*p == ' ' || *p == '\t') p++;
        if (*p == '\0' || *p == '#') continue;
        if (strncmp(p, "target_temperature", 17) == 0) {
            if (sscanf(p, " = %.2f", &cfg->target_temperature) != 1) {
                fprintf(stderr, "Warning: malformed target_temperature, using default\n");
                cfg->target_temperature = 25.0;
            }
            got_target = 1;
        } else if (strncmp(p, "Kp", 2) == 0) {
            if (sscanf(p, " = %.2f", &cfg->Kp) != 1) {
                fprintf(stderr, "Warning: malformed Kp, using default\n");
                cfg->Kp = 1.0;
            }
            got_kp = 1;
        } else if (strncmp(p, "Ki", 2) == 0) {
            if (sscanf(p, " = %.2f", &cfg->Ki) != 1) {
                fprintf(stderr, "Warning: malformed Ki, using default\n");
                cfg->Ki = 0.1;
            }
            got_ki = 1;
        } else if (strncmp(p, "Kd", 2) == 0) {
            if (sscanf(p, " = %.2f", &cfg->Kd) != 1) {
                fprintf(stderr, "Warning: malformed Kd, using default\n");
                cfg->Kd = 0.01;
            }
            got_kd = 1;
        }
    }
    fclose(fp);
    if (!got_target || !got_kp || !got_ki || !got_kd) {
        fprintf(stderr, "Warning: config missing some fields, using defaults\n");
    }
    return 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel=%d, speed=%d): %s\n",
                SPI_CHANNEL, SPI_SPEED, pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

static int init_max31865(void) {
    /* Write config: VBIAS=1, auto-conversion=1, fault-clear=1 */
    unsigned char cfg[3] = { MAX31865_CONFIG_REG, 0xC1, 0x00 };
    if (spiWrite(spi_handle, (char *)cfg, 3) != 3) {
        fprintf(stderr, "Error: failed to write MAX31865 config register\n");
        return -1;
    }
    /* Allow VBIAS to settle */
    gpioDelay(10000);
    return 0;
}

static int read_rtd_code(unsigned short *rtd_code) {
    unsigned char msb = 0, lsb = 0;
    if (spiReadByteData(spi_handle, MAX31865_RTD_MSB_REG) < 0) {
        fprintf(stderr, "Error: SPI read failed for RTD MSB\n");
        return -1;
    }
    msb = (unsigned char)spiReadByteData(spi_handle, MAX31865_RTD_MSB_REG);
    if (spiReadByteData(spi_handle, MAX31865_RTD_LSB_REG) < 0) {
        fprintf(stderr, "Error: SPI read failed for RTD LSB\n");
        return -1;
    }
    lsb = (unsigned char)spiReadByteData(spi_handle, MAX31865_RTD_LSB_REG);
    *rtd_code = ((unsigned short)(msb & 0x7F) << 7) | (lsb >> 1);
    return 0;
}

static int read_fault_status(unsigned char *fault) {
    unsigned char status = 0;
    if (spiReadByteData(spi_handle, MAX31865_FAULT_STATUS_REG) < 0) {
        fprintf(stderr, "Error: SPI read failed for fault status\n");
        return -1;
    }
    status = (unsigned char)spiReadByteData(spi_handle, MAX31865_FAULT_STATUS_REG);
    *fault = (unsigned char)(status & 0x07);
    return 0;
}

static double rtd_to_resistance(unsigned short rtd_code) {
    return ((double)rtd_code / 32768.0) * R_REF;
}

static double resistance_to_temperature(double resistance) {
    /* Callendar-Van Dusen for PT100: R = R0(1 + A*t + B*t^2) */
    double A = 0.0039083, B = -0.0000005775;
    double t = (resistance - PT100_NOMINAL_R) / (A * PT100_NOMINAL_R);
    if (t < 0) t = 0;
    return PT100_NOMINAL_R * (1.0 + A * t + B * t * t);
}

static double pid_compute(double setpoint, double actual, double *integral, double *prev_error) {
    double error = setpoint - actual;
    *integral += error;
    if (*integral > 100.0) *integral = 100.0;
    if (*integral < -100.0) *integral = -100.0;
    double derivative = error - *prev_error;
    double output = pid_config.Kp * error + pid_config.Ki * (*integral) + pid_config.Kd * derivative;
    *prev_error = error;
    if (output < 0) output = 0;
    if (output > 100) output = 100;
    return output;
}

static void set_pwm(double duty) {
    if (duty < 0) duty = 0;
    if (duty > 100) duty = 100;
    int pwm_val = (int)(duty * PWM_RANGE / 100.0);
    if (gpioPWM(HEATER_GPIO, pwm_val) < 0) {
        fprintf(stderr, "Error: gpioPWM failed\n");
    }
}

static void cleanup(void) {
    set_pwm(0.0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO%d\n", HEATER_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for GPIO%d\n", HEATER_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for GPIO%d\n", HEATER_GPIO);
        gpioTerminate();
        return 1;
    }
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }
    if (init_max31865() != 0) {
        cleanup();
        return 1;
    }
    read_config("pid_config.json", &pid_config);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("PID heater control started. Target=%.2f°C, Kp=%.2f, Ki=%.2f, Kd=%.2f\n",
           pid_config.target_temperature, pid_config.Kp, pid_config.Ki, pid_config.Kd);
    double integral = 0.0, prev_error = 0.0;
    while (running) {
        unsigned short rtd_code = 0;
        unsigned char fault = 0;
        if (read_rtd_code(&rtd_code) != 0) {
            fprintf(stderr, "Error: RTD read failed, shutting down\n");
            break;
        }
        if (rtd_code == 0xFFFF) {
            fprintf(stderr, "Error: RTD code 0xFFFF indicates no conversion ready\n");
            break;
        }
        if (fault & 0x01) {
            fprintf(stderr, "Error: MAX31865 fault bit set (open circuit)\n");
            break;
        }
        if (fault & 0x02) {
            fprintf(stderr, "Error: MAX31865 fault bit set (short to GND)\n");
            break;
        }
        if (fault & 0x04) {
            fprintf(stderr, "Error: MAX31865 fault bit set (short to VBIAS)\n");
            break;
        }
        double resistance = rtd_to_resistance(rtd_code);
        double temperature = resistance_to_temperature(resistance);
        printf("RTD code=%u, R=%.2f, T=%.2f\n", rtd_code, resistance, temperature);
        double output = pid_compute(pid_config.target_temperature, temperature, &integral, &prev_error);
        set_pwm(output);
        gpioDelay(LOOP_DELAY_US);
    }
    cleanup();
    return 0;
}

