#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP180_ADDR 0x77
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "breach_log.txt"

#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34
#define BMP180_CMD_PRESSURE1 0x3E

#define TEMP_THRESHOLD 30.0
#define PRESSURE_THRESHOLD 950.0

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_read_reg16u(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int read_calibration_data(void) {
    if (i2c_read_reg16(i2c_fd, 0xAA, &ac1) < 0) return -1;
    if (i2c_read_reg16(i2c_fd, 0xAC, &ac2) < 0) return -1;
    if (i2c_read_reg16(i2c_fd, 0xAE, &ac3) < 0) return -1;
    if (i2c_read_reg16u(i2c_fd, 0xB0, &ac4) < 0) return -1;
    if (i2c_read_reg16u(i2c_fd, 0xB2, &ac5) < 0) return -1;
    if (i2c_read_reg16u(i2c_fd, 0xB4, &ac6) < 0) return -1;
    if (i2c_read_reg16(i2c_fd, 0xB6, (int16_t*)&b1) < 0) return -1;
    if (i2c_read_reg16(i2c_fd, 0xB8, (int16_t*)&b2) < 0) return -1;
    if (i2c_read_reg16(i2c_fd, 0xBA, (int16_t*)&mb) < 0) return -1;
    if (i2c_read_reg16(i2c_fd, 0xBC, (int16_t*)&mc) < 0) return -1;
    if (i2c_read_reg16(i2c_fd, 0xBE, (int16_t*)&md) < 0) return -1;
    return 0;
}

static int read_raw_temperature(int32_t *raw_temp) {
    if (i2c_write_reg8(i2c_fd, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    usleep(5000);
    uint8_t msb, lsb;
    if (i2c_read_reg8(i2c_fd, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(i2c_fd, BMP180_REG_LSB, &lsb) < 0) return -1;
    *raw_temp = (int32_t)((msb << 8) | lsb);
    return 0;
}

static int read_raw_pressure(int32_t *raw_pressure) {
    if (i2c_write_reg8(i2c_fd, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE0) < 0) return -1;
    usleep(5000);
    uint8_t msb, lsb;
    if (i2c_read_reg8(i2c_fd, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(i2c_fd, BMP180_REG_LSB, &lsb) < 0) return -1;
    *raw_pressure = (int32_t)((msb << 8) | lsb);
    return 0;
}

static int read_raw_pressure_alt(int32_t *raw_pressure) {
    if (i2c_write_reg8(i2c_fd, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE1) < 0) return -1;
    usleep(5000);
    uint8_t msb, lsb;
    if (i2c_read_reg8(i2c_fd, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(i2c_fd, BMP180_REG_LSB, &lsb) < 0) return -1;
    *raw_pressure = (int32_t)((msb << 8) | lsb);
    return 0;
}

static int calculate_b5(int32_t raw_temp, int32_t *b5_out) {
    int32_t x1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    *b5_out = b5;
    return 0;
}

static int calculate_temperature(int32_t raw_temp, float *temp_out) {
    int32_t b5;
    if (calculate_b5(raw_temp, &b5) < 0) return -1;
    int32_t t = (b5 + 8) >> 4;
    *temp_out = ((t * 5 + 128) >> 8) / 10.0;
    return 0;
}

static int calculate_pressure(int32_t raw_pressure, int32_t raw_pressure_alt, float *pressure_out) {
    int32_t b5;
    if (calculate_b5(raw_temp, &b5) < 0) return -1;
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((int32_t)ac1 * 4 + x3) << 2) / 4;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)(raw_pressure - b3) * (uint32_t)(50000 >> 2));
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    *pressure_out = (float)p;
    return 0;
}

static void log_breach(float temp, float press) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s - Temperature: %.2f C, Pressure: %.2f hPa\n", ts, temp, press);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", BMP180_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (read_calibration_data() < 0) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("BMP180 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int32_t raw_temp = 0, raw_pressure = 0, raw_pressure_alt = 0;
        int ok = 0;

        for (int retry = 0; retry < 3 && running; retry++) {
            if (read_raw_temperature(&raw_temp) == 0 &&
                read_raw_pressure(&raw_pressure) == 0 &&
                read_raw_pressure_alt(&raw_pressure_alt) == 0) {
                ok = 1;
                break;
            }
            usleep(100000);
        }

        if (!ok) {
            fprintf(stderr, "Error reading sensor data after retries.\n");
            sleep(1);
            continue;
        }

        float temp = 0.0, press = 0.0;
        if (calculate_temperature(raw_temp, &temp) < 0 ||
            calculate_pressure(raw_pressure, raw_pressure_alt, &press) < 0) {
            fprintf(stderr, "Error calculating temperature or pressure.\n");
            sleep(1);
            continue;
        }

        if (temp > TEMP_THRESHOLD || press < PRESSURE_THRESHOLD) {
            log_breach(temp, press);
        }

        sleep(1);
    }

    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    printf("Exiting.\n");
    return 0;
}

