#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34
#define BMP180_CMD_PRESSURE1 0x36
#define BMP180_CMD_PRESSURE2 0x38
#define BMP180_CMD_PRESSURE3 0x3A
#define BMP180_OSS 0
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_MS 500

typedef struct {
    time_t timestamp;
    int valid;
    float temperature;
    float pressure;
} sensor_data_t;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static bmp180_cal_t cal;
static int i2c_handle = -1;
static sensor_data_t buffer[BUFFER_SIZE];
static int buffer_index = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(void) {
    uint8_t data[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, (char *)data, 22) != 22) {
        fprintf(stderr, "Error: failed to read 22-byte calibration block\n");
        return -1;
    }
    cal.ac1 = (int16_t)((data[0] << 8) | data[1]);
    cal.ac2 = (int16_t)((data[2] << 8) | data[3]);
    cal.ac3 = (int16_t)((data[4] << 8) | data[5]);
    cal.ac4 = (uint16_t)((data[6] << 8) | data[7]);
    cal.ac5 = (uint16_t)((data[8] << 8) | data[9]);
    cal.ac6 = (uint16_t)((data[10] << 8) | data[11]);
    cal.b1 = (int16_t)((data[12] << 8) | data[13]);
    cal.b2 = (int16_t)((data[14] << 8) | data[15]);
    cal.mb = (int16_t)((data[16] << 8) | data[17]);
    cal.mc = (int16_t)((data[18] << 8) | data[19]);
    cal.md = (int16_t)((data[20] << 8) | data[21]);
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) != 0) {
        fprintf(stderr, "Error: failed to write temperature command\n");
        return -1;
    }
    gpioDelay(5000);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_MSB + 1);
    if (msb < 0 || lsb < 0) {
        fprintf(stderr, "Error: failed to read raw temperature\n");
        return -1;
    }
    *ut = (int32_t)((msb << 8) | lsb);
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    for (int i = 0; i < 4; i++) {
        if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE0 + i) != 0) {
            fprintf(stderr, "Error: failed to write pressure command %d\n", i);
            return -1;
        }
        gpioDelay(26000);
        int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
        int lsb = i2cReadByteData(i2c_handle, BMP180_REG_MSB + 1);
        int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_MSB + 2);
        if (msb < 0 || lsb < 0 || xlsb < 0) {
            fprintf(stderr, "Error: failed to read pressure word %d\n", i);
            return -1;
        }
        up[i] = ((int32_t)(msb << 16) | (lsb << 8) | xlsb) >> (8 - BMP180_OSS);
    }
    return 0;
}

static float calculate_temperature(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)cal.ac6) * (int32_t)cal.ac5) >> 15;
    int32_t x2 = ((int32_t)cal.mc << 11) / (x1 + (int32_t)cal.md);
    int32_t b5 = x1 + x2;
    return ((b5 + 8) >> 4) / 10.0f;
}

static float calculate_pressure(int32_t up[4]) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)cal.b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)cal.ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)cal.ac1 * 4 + x3) << BMP180_OSS) + 2) >> 2);
    x1 = ((int32_t)cal.ac3 * b6) >> 13;
    x2 = ((int32_t)cal.b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)cal.ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up[0] * (uint32_t)(x3 + 32768)) >> 15;
    int32_t p;
    if (b4 == 0) {
        return 0.0f;
    }
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    return (float)(p + ((x1 + x2 + 3791) >> 4));
}

static void timer_callback(void *user_data) {
    (void)user_data;
    int32_t ut, up[4];
    if (read_raw_temperature(&ut) != 0) return;
    if (read_raw_pressure(up) != 0) return;
    float temp = calculate_temperature(ut);
    float pres = calculate_pressure(up);
    time_t now = time(NULL);
    sensor_data_t *sd = &buffer[buffer_index];
    sd->timestamp = now;
    sd->valid = 1;
    sd->temperature = temp;
    sd->pressure = pres;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    printf("Timestamp: %ld, Temp: %.2f C, Pressure: %.2f Pa\n", (long)now, temp, pres);
}

static void cleanup(void) {
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus 1 at 0x%02X\n", BMP180_ADDR);
        gpioTerminate();
        return 1;
    }
    if (read_calibration() != 0) {
        cleanup();
        return 1;
    }
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to set timer\n");
        cleanup();
        return 1;
    }
    printf("BMP180 monitoring started. Press Ctrl+C to exit.\n");
    while (running) {
        gpioDelay(100000);
    }
    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

