#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define SPI_FLAGS 0
#define MAX_DUTY_CYCLE 80.0
#define DEFAULT_TARGET_TEMP 25.0
#define LOG_FILE "heater_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(float temperature, float duty_cycle) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file);
}

static int read_max31855(int handle, float *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(handle, tx, rx, 4) != 4) {
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        return -2;
    }

    if (raw & 0x00000004) {
        return -3;
    }

    if (raw & 0x00000002) {
        return -4;
    }

    int16_t thermocouple_raw = (int16_t)(raw >> 18);
    *temperature = thermocouple_raw * 0.25f;
    return 0;
}

static float calculate_duty_cycle(float target_temp, float current_temp, float kp, float ki, float *integral, float *prev_error) {
    float error = target_temp - current_temp;
    float dt = 1.0f;

    float proportional = kp * error;
    *integral += error * dt;
    if (*integral > 100.0f) *integral = 100.0f;
    if (*integral < 0.0f) *integral = 0.0f;

    float derivative = (error - *prev_error) / dt;
    float output = proportional + ki * (*integral);
    *prev_error = error;

    if (output < 0.0f) output = 0.0f;
    if (output > MAX_DUTY_CYCLE) output = MAX_DUTY_CYCLE;

    return output;
}

static void set_heater_pwm(float duty_cycle) {
    if (duty_cycle < 0.0f) duty_cycle = 0.0f;
    if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;

    int pwm_value = (int)(duty_cycle / MAX_DUTY_CYCLE * 255.0f);
    gpioPWM(HEATER_GPIO, pwm_value);
}

int main(void) {
    float target_temp = DEFAULT_TARGET_TEMP;
    float integral = 0.0f;
    float prev_error = 0.0f;
    float duty_cycle = 0.0f;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, 1000);
    gpioSetPWMrange(HEATER_GPIO, 255);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),DutyCycle(%%)\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting heater control. Target: %.2f°C\n", target_temp);

    while (running) {
        float temperature = 0.0f;
        int ret = read_max31855(spi_handle, &temperature);

        if (ret == 0) {
            duty_cycle = calculate_duty_cycle(target_temp, temperature, 1.0f, 0.1f, &integral, &prev_error);
            set_heater_pwm(duty_cycle);
            log_data(temperature, duty_cycle);
            printf("Temp: %.2f°C, Duty: %.2f%%\n", temperature, duty_cycle);
        } else {
            fprintf(stderr, "MAX31855 error: %d\n", ret);
            set_heater_pwm(0.0f);
            log_data(0.0f, 0.0f);
            fprintf(log_file, "ERROR,MAX31855_FAULT,0.0\n");
            fflush(log_file);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    set_heater_pwm(0.0f);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

