        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),DutyCycle(%%)\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting heater control. Target: %.2f°C\n", target_temp);

    while (running) {
        float temperature = 0.0f;
        int ret = read_max31855(spi_handle, &temperature);

        if (ret == 0) {
            duty_cycle = calculate_duty_cycle(target_temp, temperature, 1.0f, 0.1f, &integral, &prev_error);
            set_heater_pwm(duty_cycle);
            log_data(temperature, duty_cycle);
            printf("Temp: %.2f°C, Duty: %.2f%%\n", temperature, duty_cycle);
        } else {
            fprintf(stderr, "MAX31855 error: %d\n", ret);
            set_heater_pwm(0.0f);
            log_data(0.0f, 0.0f);
            fprintf(log_file, "ERROR,MAX31855_FAULT,0.0\n");
            fflush(log_file);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    set_heater_pwm(0.0f);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

