#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define PWM_RANGE 255

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_cpu_temp(void)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    int temp = -1;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: error closing %s: %s\n", TEMP_FILE, strerror(errno));
    }

    return temp;
}

static void set_led_color(int red, int green, int blue)
{
    /* Common-anode: channel off (duty 255) = fully on; channel on (duty 0) = fully off */
    gpioPWM(RED_PIN, PWM_RANGE - red);
    gpioPWM(GREEN_PIN, PWM_RANGE - green);
    gpioPWM(BLUE_PIN, PWM_RANGE - blue);
}

static void set_color_by_temp(int temp)
{
    if (temp < 40000) {
        set_led_color(0, 0, 255);
    } else if (temp < 60000) {
        set_led_color(0, 255, 0);
    } else {
        set_led_color(255, 0, 0);
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with LED off (common-anode: duty 255 = off) */
    gpioPWM(RED_PIN, PWM_RANGE);
    gpioPWM(GREEN_PIN, PWM_RANGE);
    gpioPWM(BLUE_PIN, PWM_RANGE);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        gpioPWM(RED_PIN, PWM_RANGE);
        gpioPWM(GREEN_PIN, PWM_RANGE);
        gpioPWM(BLUE_PIN, PWM_RANGE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int temp = read_cpu_temp();
        if (temp < 0) {
            /* Read error: turn off LED and continue */
            gpioPWM(RED_PIN, PWM_RANGE);
            gpioPWM(GREEN_PIN, PWM_RANGE);
            gpioPWM(BLUE_PIN, PWM_RANGE);
            sleep(0.5);
            continue;
        }

        set_color_by_temp(temp);

        printf("CPU Temperature: %d m°C, RGB: (%d, %d, %d)\n",
               temp,
               (PWM_RANGE - gpioGetPWMdutycycle(RED_PIN)),
               (PWM_RANGE - gpioGetPWMdutycycle(GREEN_PIN)),
               (PWM_RANGE - gpioGetPWMdutycycle(BLUE_PIN)));
        fflush(stdout);

        sleep(0.5);
    }

    /* Clean shutdown: turn off LED (common-anode: duty 255 = off) */
    gpioPWM(RED_PIN, PWM_RANGE);
    gpioPWM(GREEN_PIN, PWM_RANGE);
    gpioPWM(BLUE_PIN, PWM_RANGE);

    gpioTerminate();
    return EXIT_SUCCESS;
}

