#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define MAX_WAIT_US 100000
#define MAX_WAIT_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(float *humidity, float *temperature) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_idx = 0;
    int last_state = 1;
    int timeout = 0;

    if (gpioSetMode(DHT22_GPIO, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(DHT22_GPIO, 1) < 0) return -1;
    gpioDelay(2000);
    if (gpioWrite(DHT22_GPIO, 0) < 0) return -1;
    gpioDelay(30);
    if (gpioSetMode(DHT22_GPIO, PI_INPUT) < 0) return -1;

    while (gpioRead(DHT22_GPIO) == last_state) {
        if (++timeout > MAX_WAIT_MS) return -1;
        gpioDelay(1);
    }
    timeout = 0;
    while (gpioRead(DHT22_GPIO) != last_state) {
        if (++timeout > MAX_WAIT_MS) return -1;
        gpioDelay(1);
    }
    timeout = 0;
    while (gpioRead(DHT22_GPIO) == last_state) {
        if (++timeout > MAX_WAIT_MS) return -1;
        gpioDelay(1);
    }

    for (int i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == last_state) {
            if (++timeout > MAX_WAIT_MS) return -1;
            gpioDelay(1);
        }
        timeout = 0;
        while (gpioRead(DHT22_GPIO) != last_state) {
            if (++timeout > MAX_WAIT_MS) return -1;
            gpioDelay(1);
        }
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == last_state) {
            if (++timeout > MAX_WAIT_MS) return -1;
            gpioDelay(1);
        }

        if (timeout > 0) {
            data[bit_idx / 8] |= (1 << (7 - (bit_idx % 8)));
        }
        bit_idx++;
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        return -2;
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }
    return 0;
}

static int post_data(float humidity, float temperature) {
    CURL *curl = curl_easy_init();
    if (!curl) return -1;

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        curl_easy_cleanup(curl);
        return -1;
    }

    char json[256];
    snprintf(json, sizeof(json),
             "{\"humidity\": %.2f, \"temperature\": %.2f}",
             humidity, temperature);

    curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = curl_easy_perform(curl);
    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);

    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    float humidity, temperature;
    int retries = 0;

    while (running) {
        int result = read_dht22(&humidity, &temperature);
        if (result == 0) {
            retries = 0;
            if (post_data(humidity, temperature) == 0) {
                printf("Data posted successfully.\n");
            } else {
                fprintf(stderr, "Failed to post data.\n");
            }
        } else if (result == -2) {
            fprintf(stderr, "Checksum error.\n");
        } else {
            fprintf(stderr, "Sensor read error (code %d).\n", result);
        }

        if (retries < MAX_RETRIES) {
            retries++;
            sleep(2);
        }
    }

    gpioTerminate();
    return 0;
}

