#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE_OSS3 0x34
#define BUTTON_GPIO 4
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 2000000
#define DEBOUNCE_US 200000

static volatile sig_atomic_t logging_enabled = 0;
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void button_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)user;
    static uint32_t last_tick = 0;
    if (tick - last_tick > DEBOUNCE_US) {
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
        fflush(stdout);
        last_tick = tick;
    }
}

static int read_s16(int handle, uint8_t reg, int16_t *out) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_u16(int handle, uint8_t reg, uint16_t *out) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_calibration(int handle) {
    if (read_s16(handle, BMP180_REG_CAL_AC1, &ac1) < 0) return -1;
    if (read_s16(handle, BMP180_REG_CAL_AC2, &ac2) < 0) return -1;
    if (read_s16(handle, BMP180_REG_CAL_AC3, &ac3) < 0) return -1;
    if (read_u16(handle, BMP180_REG_CAL_AC4, &ac4) < 0) return -1;
    if (read_u16(handle, BMP180_REG_CAL_AC5, &ac5) < 0) return -1;
    if (read_u16(handle, BMP180_REG_CAL_AC6, &ac6) < 0) return -1;
    if (read_s16(handle, BMP180_REG_CAL_B1, &b1) < 0) return -1;
    if (read_s16(handle, BMP180_REG_CAL_B2, &b2) < 0) return -1;
    if (read_s16(handle, BMP180_REG_CAL_MB, &mb) < 0) return -1;
    if (read_s16(handle, BMP180_REG_CAL_MC, &mc) < 0) return -1;
    if (read_s16(handle, BMP180_REG_CAL_MD, &md) < 0) return -1;
    if (ac1 == 0 && ac2 == 0 && ac3 == 0 && ac4 == 0 && ac5 == 0 && ac6 == 0) {
        fprintf(stderr, "Calibration data invalid (sensor absent or not responding)\n");
        return -1;
    }
    return 0;
}

static int read_raw_temperature(int handle, int32_t *raw_temp) {
    char cmd = BMP180_CMD_TEMP;
    if (i2cWriteDevice(handle, &cmd, 1) != 0) return -1;
    gpioDelay(5000);
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *raw_temp = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int handle, int32_t *raw_pressure) {
    char cmd = BMP180_CMD_PRESSURE_OSS3;
    if (i2cWriteDevice(handle, &cmd, 1) != 0) return -1;
    gpioDelay(26000);
    char buf[3];
    if (i2cReadDevice(handle, buf, 3) != 3) return -1;
    *raw_pressure = ((int32_t)(buf[0] << 16) | (buf[1] << 8) | buf[2]) >> 8;
    return 0;
}

static double calculate_pressure(int32_t ut, int32_t up, int oss) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << oss) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> oss);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (double)p / 100.0;
}

static void log_pressure(double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s, %.2f hPa\n", timestamp, pressure);
        fclose(fp);
    } else {
        fprintf(stderr, "Error opening log file\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
