    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    printf("BMP180 pressure logger started. Press button on GPIO4 to toggle logging.\n");
    while (running) {
        if (logging_enabled) {
