    formdata[0].contents_type = CURLFORM_COPYCONTENTS;
    formdata[0].offset = 0;

    CURLformappendl(formdata, formdata[0].offset, json_string);

    CURLcode res;
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");

    curl_easy_setopt(curl, CURLOPT_URL, server_url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, formdata);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

    res = curl_easy_perform(curl);
    curl_slist_free_all(headers);

    if (res != CURLE_OK) {
        syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
        return -1;
    }

    long response_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
    if (response_code < 200 || response_code >= 300) {
        syslog(LOG_ERR, "HTTP POST returned status code: %ld", response_code);
        return -1;
    }
    return 0;
}

static DHT22Data read_dht22(int pin) {
    DHT22Data data = {0.0f, 0};
    int retries = 0;
    int last_state = PI_HIGH;
    int bits[40] = {0};
    int i;

    while (retries < MAX_RETRIES && running) {
        memset(bits, 0, sizeof(bits));

        /* Start signal: pull low for >= 1 ms, then high for 20-40 us */
        gpioSetMode(pin, PI_OUTPUT);
        gpioWrite(pin, PI_LOW);
        gpioDelay(2000); /* 2 ms low */
        gpioWrite(pin, PI_HIGH);
        gpioDelay(30);  /* 30 us high */
        gpioSetMode(pin, PI_INPUT);

        /* Wait for sensor response: low for ~80 us, high for ~80 us */
        uint32_t start_tick = gpioTick();
        while (gpioRead(pin) == PI_HIGH) {
            if (gpioTick() - start_tick > DHT_TIMEOUT_US) {
                syslog(LOG_ERR, "DHT22: timeout waiting for response low");
                retries++;
                goto next_retry;
            }
        }
        start_tick = gpioTick();
        while (gpioRead(pin) == PI_LOW) {
            if (gpioTick() - start_tick > DHT_TIMEOUT_US) {
                syslog(LOG_ERR, "DHT22: timeout waiting for response high");
                retries++;
                goto next_retry;
            }
        }
        start_tick = gpioTick();
        while (gpioRead(pin) == PI_HIGH) {
            if (gpioTick() - start_tick > DHT_TIMEOUT_US) {
                syslog(LOG_ERR, "DHT22: timeout waiting for data start");
                retries++;
                goto next_retry;
            }
        }

        /* Read 40 data bits */
        for (i = 0; i < 40; i++) {
            /* Wait for low-to-high transition (start of bit) */
            start_tick = gpioTick();
            while (gpioRead(pin) == PI_LOW) {
                if (gpioTick() - start_tick > DHT_TIMEOUT_US) {
                    syslog(LOG_ERR, "DHT22: timeout at bit %d low", i);
                    retries++;
                    goto next_retry;
                }
            }
            /* Measure high duration: ~26 us = '0', ~70 us = '1' */
            uint32_t high_start = gpioTick();
            while (gpioRead(pin) == PI_HIGH) {
                if (gpioTick() - high_start > DHT_TIMEOUT_US) {
                    syslog(LOG_ERR, "DHT22: timeout at bit %d high", i);
                    retries++;
                    goto next_retry;
                }
            }
            uint32_t high_duration = gpioTick() - high_start;
            bits[i] = (high_duration > 50) ? 1 : 0;
        }

        /* Verify checksum */
        int checksum = bits[0] + bits[1] + bits[2] + bits[3] +
                      bits[4] + bits[5] + bits[6] + bits[7] +
                      bits[8] + bits[9] + bits[10] + bits[11] +
                      bits[12] + bits[13] + bits[14] + bits[15] +
                      bits[16] + bits[17] + bits[18] + bits[19] +
                      bits[20] + bits[21] + bits[22] + bits[23] +
                      bits[24] + bits[25] + bits[26] + bits[27] +
                      bits[28] + bits[29] + bits[30] + bits[31] +
                      bits[32] + bits[33] + bits[34] + bits[35] +
                      bits[36] + bits[37] + bits[38] + bits[39];
        if (checksum != bits[40]) {
            syslog(LOG_ERR, "DHT22: checksum mismatch (calc=%d, recv=%d)", checksum, bits[40]);
            retries++;
            goto next_retry;
        }

        data.humidity = (float)((bits[0] << 8) | bits[1]) / 10.0f;
        data.error = 0;
        return data;

    next_retry:
        retries++;
        if (retries < MAX_RETRIES) {
            syslog(LOG_WARNING, "DHT22 read failed, retrying (%d/%d)...", retries, MAX_RETRIES);
            sleep(2);
        }
    }

    syslog(LOG_ERR, "DHT22: max retries reached");
    return data;
}

static void log_error(const char *msg) {
    syslog(LOG_ERR, "%s", msg);
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:h")) != -1) {
        switch (opt) {
            case 's':
                server_url = optarg;
                break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-s server_url]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("dht22_uploader", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        log_error("pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    CURL *curl = NULL;
    if (init_curl(&curl) != 0) {
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    while (running) {
        DHT22Data dht22_data = read_dht22(DHT22_PIN);

        if (dht22_data.error == 0) {
            char json_string[64];
            snprintf(json_string, sizeof(json_string), "{\"humidity\": %.1f}", dht22_data.humidity);

            if (post_data(curl, json_string) != 0) {
                log_error("Failed to POST data to server");
            } else {
                syslog(LOG_INFO, "Data posted successfully: %s", json_string);
            }
        } else {
            log_error("Failed to read DHT22 sensor data");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    cleanup_curl(&curl);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

