#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define MAX_TEMP_FILE "/sys/class/thermal/cooling_device0/max_state"
#define POLL_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }
    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp;
}

static int read_max_state(void) {
    FILE *fp = fopen(MAX_TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", MAX_TEMP_FILE, strerror(errno));
        return -1;
    }
    int max_state;
    if (fscanf(fp, "%d", &max_state) != 1) {
        fprintf(stderr, "Error reading max_state from %s\n", MAX_TEMP_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return max_state;
}

static int set_fan_speed(int speed) {
    if (speed < 0 || speed > (read_max_state() - 1)) {
        fprintf(stderr, "Invalid fan speed %d (max_state=%d)\n", speed, read_max_state());
        return -1;
    }
    FILE *fp = fopen(FAN_STATE_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_STATE_FILE, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", speed) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", FAN_STATE_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[unknown time] %s\n", message);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    int current_speed = -1;
    int max_state = read_max_state();
    if (max_state < 0) {
        fprintf(stderr, "Failed to read max_state; using default 3.\n");
        max_state = 3;
    }

    while (running) {
        int temp = read_temperature();
        if (temp < 0) {
            sleep(POLL_INTERVAL);
            continue;
        }

        int new_speed;
        if (temp < 4500) {
            new_speed = 0;
        } else if (temp < 5500) {
            new_speed = 1;
        } else if (temp < 6500) {
            new_speed = 2;
        } else {
            new_speed = 3;
        }

        if (new_speed != current_speed) {
            if (set_fan_speed(new_speed) == 0) {
                char msg[128];
                snprintf(msg, sizeof(msg), "Fan speed set to %d", new_speed);
                log_event(msg);
                current_speed = new_speed;
            } else {
                log_event("Failed to set fan speed");
            }
        }

        sleep(POLL_INTERVAL);
    }

    log_event("Fan stopped on shutdown");
    set_fan_speed(0);
    return 0;
}

