    int ret = spiRead(spi_handle, tx, rx, 4);
    if (ret != 4) {
        log_message("SPI read error: expected 4 bytes");
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        uint8_t fault = (raw >> 16) & 0x07;
        if (fault == 1) {
            log_message("MAX31855 fault: open circuit");
        } else if (fault == 2) {
            log_message("MAX31855 fault: short to GND");
        } else if (fault == 3) {
            log_message("MAX31855 fault: short to VCC");
        } else {
            log_message("MAX31855 unknown fault");
        }
        return -1;
    }

    int16_t thermocouple_raw = (int16_t)(raw >> 18);
    *temp_out = thermocouple_raw * 0.25;
    return 0;
}

static double calculate_pid(double setpoint, double actual, double dt) {
    double error = setpoint - actual;
    integral += error * dt;
    double derivative = (error - previous_error) / dt;
    double output = KP * error + KI * integral + KD * derivative;
    previous_error = error;
    return output;
}

static void set_heater(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(HEATER_GPIO, duty);
}

static void cleanup(void) {
    set_heater(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    set_heater(0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("PID heater controller started");

    while (running) {
        double temp = 0.0;
        int ret = read_max31855(&temp);

        if (ret == 0) {
            if (temp > MAX_TEMP || temp < MIN_TEMP) {
                log_message("Failsafe: temperature out of range");
                set_heater(0);
                integral = 0.0;
                previous_error = 0.0;
                continue;
            }

            double pid_output = calculate_pid(TARGET_TEMP, temp, 1.0);
            int pwm_duty = (int)(pid_output + 0.5);
            if (pwm_duty < 0) pwm_duty = 0;
            if (pwm_duty > PWM_RANGE) pwm_duty = PWM_RANGE;

            set_heater(pwm_duty);
            log_data(temp, pwm_duty, pid_output);
        } else {
            set_heater(0);
            integral = 0.0;
            previous_error = 0.0;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    log_message("Shutting down");
    cleanup();
    return 0;
}

