#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define MIN_TEMP 40.0
#define MAX_TEMP 70.0
#define MIN_DUTY 0.0
#define MAX_DUTY 100.0
#define PWM_FREQUENCY 25000
#define POLL_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen temperature file");
        return -1;
    }
    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Failed to parse temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp_milli / 1000;
}

static double map_temp_to_duty(double temp_c) {
    if (temp_c <= MIN_TEMP) return MIN_DUTY;
    if (temp_c >= MAX_TEMP) return MAX_DUTY;
    return MIN_DUTY + (temp_c - MIN_TEMP) * (MAX_DUTY - MIN_DUTY) / (MAX_TEMP - MIN_TEMP);
}

static int set_fan_speed(double duty_percent) {
    if (duty_percent < 0.0) duty_percent = 0.0;
    if (duty_percent > 100.0) duty_percent = 100.0;
    int duty_cycle = (int)(duty_percent / 100.0 * 255.0);
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "gpioPWM failed for GPIO%d\n", FAN_GPIO);
        return -1;
    }
    return 0;
}

static int log_data(double temp_c, double duty_percent) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temp_c, duty_percent);
    if (fclose(fp) != 0) {
        perror("fclose log file");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO%d\n", FAN_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Warning: could not set exact PWM frequency\n");
    }

    if (set_fan_speed(0.0) != 0) {
        gpioTerminate();
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    int file_exists = (fp != NULL);
    if (fclose(fp) != 0) {
        perror("fclose log file (check)");
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file (write)");
        gpioPWM(FAN_GPIO, 0);
        gpioTerminate();
        return 1;
    }
    if (file_exists) {
        fprintf(fp, "Timestamp,Temperature(C),DutyCycle(percent)\n");
    }
    if (fclose(fp) != 0) {
        perror("fclose log file (header)");
        gpioPWM(FAN_GPIO, 0);
        gpioTerminate();
        return 1;
    }

    printf("Fan control started. Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    while (running) {
        double temp = read_cpu_temp();
        if (temp < 0.0) {
            fprintf(stderr, "Temperature read failed, skipping cycle\n");
        } else {
            double duty = map_temp_to_duty(temp);
            if (set_fan_speed(duty) != 0) {
                fprintf(stderr, "Failed to set fan speed\n");
            }
            if (log_data(temp, duty) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
            printf("Temp: %.2f C, Duty: %.2f%%\n", temp, duty);
        }
        sleep(POLL_INTERVAL);
    }

    printf("\nShutting down...\n");
    set_fan_speed(0.0);
    gpioTerminate();
    return 0;
}

