#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define FLOW_LOG_FILE "flow_log.txt"
#define MEASUREMENT_CMD 0x3608
#define READ_BYTES 3
#define MAX_RETRIES 3
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int init_sensor(int handle) {
    if (i2cWriteByte(handle, (MEASUREMENT_CMD >> 8) & 0xFF) < 0) {
        fprintf(stderr, "Error writing high byte to sensor: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByte(handle, MEASUREMENT_CMD & 0xFF) < 0) {
        fprintf(stderr, "Error writing low byte to sensor: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_flow_rate(int handle, float *flow_rate) {
    uint8_t buffer[READ_BYTES];
    int retries = 0;
    int bytes_read;

    while (retries < MAX_RETRIES) {
        bytes_read = i2cReadDevice(handle, (char *)buffer, READ_BYTES);
        if (bytes_read == READ_BYTES) {
            uint8_t calculated_crc = crc8(buffer, 2);
            if (calculated_crc == buffer[2]) {
                int16_t raw_value = (buffer[0] << 8) | buffer[1];
                *flow_rate = (float)raw_value * 0.01f;
                return 0;
            } else {
                fprintf(stderr, "CRC mismatch: calculated 0x%02X, received 0x%02X\n", calculated_crc, buffer[2]);
                return -1;
            }
        } else {
            fprintf(stderr, "I2C read error: %s (attempt %d/%d)\n", strerror(errno), retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(10000);
        }
    }
    return -1;
}

static int log_flow_rate(float flow1, float flow2) {
    FILE *fp = fopen(FLOW_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    if (init_sensor(i2c_handle1) < 0 || init_sensor(i2c_handle2) < 0) {
        fprintf(stderr, "Error initializing sensors\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting flow monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ret1 = read_flow_rate(i2c_handle1, &flow1);
        int ret2 = read_flow_rate(i2c_handle2, &flow2);

        if (ret1 == 0 && ret2 == 0) {
            if (log_flow_rate(flow1, flow2) != 0) {
                fprintf(stderr, "Error logging flow rates\n");
            }
        } else {
            fprintf(stderr, "Error reading flow rates (sensor1=%d, sensor2=%d)\n", ret1, ret2);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();
    return 0;
}

