#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADPD144RI_ADDR  0x39
#define REG_FIFO_DATA   0x60
#define GPIO_CHIP       "gpiochip0"
#define LED_PIN         17
#define IR_THRESHOLD    2000
#define LOG_FILE        "adpd144ri_log.txt"
#define SAMPLE_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int log_data(FILE *fp, uint16_t red, uint16_t ir) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%u,%u\n", ts, red, ir) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", ADPD144RI_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n", GPIO_CHIP, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led, "adpd144ri-led", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(led);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("ADPD144RI monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t red = 0, ir = 0;
        if (i2c_read_reg16(i2c_fd, REG_FIFO_DATA, &red) != 0) {
            fprintf(stderr, "Sensor read error — continuing.\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        int led_val = (ir > IR_THRESHOLD) ? 1 : 0;
        if (gpiod_line_set_value(led, led_val) < 0) {
            fprintf(stderr, "gpiod_line_set_value failed: %s\n", strerror(errno));
        }

        if (log_data(log_fp, red, ir) != 0) {
            fprintf(stderr, "Logging failed — continuing.\n");
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    fclose(log_fp);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

