#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_US 1000000  /* 1 second */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t pulse_mutex;

/* ISR callback: called on every rising edge of the MLX90254 output */
static void pulse_isr(int gpio, int level, uint32_t tick, void *user)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)user;
    pthread_mutex_lock(&pulse_mutex);
    static int pulse_count = 0;
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

/* Signal handler for graceful shutdown (SIGINT, SIGTERM) */
static void signal_handler(int signum)
{
    (void)signum;
    running = 0;
}

int main(void)
{
    int ret;

    /* Initialize pigpio */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure GPIO 18 as input with pull-down */
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    /* Initialize mutex */
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Error: mutex initialization failed.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register ISR on rising edge */
    ret = gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_isr, NULL);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO %d (code %d).\n",
                GPIO_PIN, ret);
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n",
                strerror(errno));
    }

    printf("RPM monitoring started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    /* Main sampling loop */
    while (running) {
        gpioDelay(SAMPLE_INTERVAL_US);

        if (!running) {
            break;
        }

        /* Read and reset pulse count */
        pthread_mutex_lock(&pulse_mutex);
        int pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        /* Calculate RPM: pulses per second * 60 = RPM */
        double rpm = (double)pulses / (double)SAMPLE_INTERVAL_US * 60.0;

        /* Get current timestamp */
        time_t now = time(NULL);
        if (now == (time_t)-1) {
            fprintf(stderr, "Warning: time() failed: %s\n", strerror(errno));
            now = 0;
        }

        /* Log RPM with timestamp */
        fprintf(log_file, "%ld.%06ld, %.2f RPM\n",
                (long)now, (long)(now % 1000) * 1000, rpm);
        fflush(log_file);

        printf("RPM: %.2f (pulses: %d)\n", rpm, pulses);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);  /* unregister ISR */
    pthread_mutex_destroy(&pulse_mutex);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

