        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n",
                strerror(errno));
    }

    printf("RPM monitoring started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    /* Main sampling loop */
    while (running) {
        gpioDelay(SAMPLE_INTERVAL_US);

        if (!running) {
            break;
        }

        /* Read and reset pulse count */
        pthread_mutex_lock(&pulse_mutex);
        int pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        /* Calculate RPM: pulses per second * 60 = RPM */
        double rpm = (double)pulses / (double)SAMPLE_INTERVAL_US * 60.0;

        /* Get current timestamp */
        time_t now = time(NULL);
        if (now == (time_t)-1) {
            fprintf(stderr, "Warning: time() failed: %s\n", strerror(errno));
            now = 0;
        }

        /* Log RPM with timestamp */
        fprintf(log_file, "%ld.%06ld, %.2f RPM\n",
                (long)now, (long)(now % 1000) * 1000, rpm);
        fflush(log_file);

        printf("RPM: %.2f (pulses: %d)\n", rpm, pulses);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);  /* unregister ISR */
    pthread_mutex_destroy(&pulse_mutex);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

