#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_OUT 17
#define GPIO_GAIN 18
#define LOG_FILE "audio_log.txt"
#define POLL_INTERVAL_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *filename, int level) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s LEVEL=%d\n", timestamp, level) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *out_line = NULL;
    struct gpiod_line *gain_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    out_line = gpiod_chip_get_line(chip, GPIO_OUT);
    if (!out_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_OUT, strerror(errno));
        goto cleanup;
    }

    gain_line = gpiod_chip_get_line(chip, GPIO_GAIN);
    if (!gain_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_GAIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(out_line, "max9814_out") < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input: %s\n", GPIO_OUT, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(gain_line, "max9814_gain", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", GPIO_GAIN, strerror(errno));
        goto cleanup;
    }

    printf("Audio peak detection started. Press Ctrl+C to exit.\n");

    int last_state = 0;
    int first_poll = 1;

    while (running) {
        int current_state = gpiod_line_get_value(out_line);
        if (current_state < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n", GPIO_OUT, strerror(errno));
            break;
        }

        if (first_poll) {
            last_state = current_state;
            first_poll = 0;
        }

        if (current_state == 1 && last_state == 0) {
            if (log_event(LOG_FILE, 1) != 0) {
                fprintf(stderr, "Failed to log event\n");
            }
        }

        last_state = current_state;
        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (gain_line) {
        gpiod_line_release(gain_line);
    }
    if (out_line) {
        gpiod_line_release(out_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Audio peak detection stopped.\n");
    return ret;
}

