#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define LOG_FILE "flow_log.csv"
#define SAMPLE_INTERVAL_US 1000000
#define FLOW_SCALE 1000.0f

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t sensirion_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int init_sensor(void) {
    uint8_t cmd[2] = {0x36, 0x08};
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to send init command to sensor.\n");
        return -1;
    }
    return 0;
}

static int read_flow_rate(float *flow_rate) {
    uint8_t buf[3];
    int bytes_read = i2cReadDevice(i2c_handle, (char *)buf, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Error: I2C read failed (got %d bytes).\n", bytes_read);
        return -1;
    }
    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on flow data.\n");
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw / FLOW_SCALE;
    return 0;
}

static int log_flow_rate(float flow_rate) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed.\n");
        return -1;
    }
