#define I2C_ADDR 0x70
#define LOG_FILE "air_quality_log.csv"
#define READ_INTERVAL_SEC 5
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int handle, uint8_t *data) {
    char reg = 0x00;
    char buf[7];

    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: Failed to write register address.\n");
        return -1;
    }
    if (i2cReadDevice(handle, buf, 7) != 7) {
        fprintf(stderr, "Error: Failed to read 7 bytes from sensor.\n");
        return -1;
    }
    memcpy(data, buf, 7);
    return 0;
}

static int calculate_iaq(uint16_t tvoc, uint16_t eco2) {
    int iaq = 100 - (int)(tvoc / 10.0) - ((int)(eco2 - 400) / 50);
    if (iaq < 0) iaq = 0;
    if (iaq > 100) iaq = 100;
    return iaq;
}

static int log_data(FILE *fp, int iaq, uint16_t tvoc, uint16_t eco2) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%d,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            iaq, tvoc, eco2);
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

