    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at bus %d, addr 0x%02X (code %d).\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        uint8_t data[7];
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && running) {
            if (read_sensor_data(i2c_handle, data) == 0) {
                success = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Retrying I2C read (%d/%d)...\n", retries, MAX_RETRIES);
                gpioDelay(100000);
            }
        }

        if (!success) {
            fprintf(stderr, "Error: Failed to read sensor data after %d retries.\n", MAX_RETRIES);
            sleep(READ_INTERVAL_SEC);
            continue;
        }

        uint16_t tvoc = ((uint16_t)data[1] << 8) | data[2];
        uint16_t eco2 = ((uint16_t)data[5] << 8) | data[6];
        int iaq = calculate_iaq(tvoc, eco2);

        if (log_data(log_file, iaq, tvoc, eco2) != 0) {
            fprintf(stderr, "Error: Failed to log data.\n");
        }

        sleep(READ_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

