#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_MS 100
#define INTRUSION_THRESHOLD_S 5
#define CONSUMER_LABEL "ttp223_tamper"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_intrusion_alert(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char time_str[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s] Intrusion detected!\n", time_str);
    } else {
        printf("[unknown time] Intrusion detected!\n");
    }
    fflush(stdout);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct timespec start_time, current_time;
    int ret;

    /* Install signal handlers for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO line for the touch sensor */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as input with the consumer label */
    ret = gpiod_line_request_input(line, CONSUMER_LABEL);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Initialize start_time to the current time */
    if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
        fprintf(stderr, "Failed to get initial time: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Monitoring GPIO %d for tamper intrusion (threshold %d s)...\n",
           GPIO_LINE_OFFSET, INTRUSION_THRESHOLD_S);
    fflush(stdout);

    /* Main polling loop */
    while (program_running) {
        int sensor_value;

        /* Read the sensor value */
        sensor_value = gpiod_line_get_value(line);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read sensor value: %s\n", strerror(errno));
            break;
        }

        /* Check if the sensor is touched (HIGH) */
        if (sensor_value == 1) {
            /* Get the current time */
            if (clock_gettime(CLOCK_MONOTONIC, &current_time) == -1) {
                fprintf(stderr, "Failed to get current time: %s\n", strerror(errno));
                break;
            }

            /* Calculate the elapsed time since the start of the touch event */
            double elapsed_seconds =
                (current_time.tv_sec - start_time.tv_sec) +
                (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

            /* Check if the touch duration exceeds the threshold */
            if (elapsed_seconds > INTRUSION_THRESHOLD_S) {
                print_intrusion_alert();
                /* Reset the start time to the current time */
                start_time = current_time;
            }
        } else {
            /* Sensor released: reset the start time */
            start_time = current_time;
        }

        /* Sleep for the poll interval */
        struct timespec sleep_time = {0, POLL_INTERVAL_MS * 1000000L};
        nanosleep(&sleep_time, NULL);
    }

    /* Clean up resources */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

