#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PWM_PIN 18
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_MS 50
#define FLAME_TIMEOUT_MS 5000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    localtime_r(&now, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file);
}

static int read_flame_sensor(int pin) {
    int v1 = gpioRead(pin);
    if (v1 < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", pin);
        return -1;
    }
    gpioDelay(DEBOUNCE_MS * 1000);
    int v2 = gpioRead(pin);
    if (v2 < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", pin);
        return -1;
    }
    return (v1 == v2) ? v1 : -1;
}

static int set_fan_speed(int pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > PWM_RANGE) {
        fprintf(stderr, "Invalid duty cycle %d\n", duty_cycle);
        return -1;
    }
    if (gpioPWM(pin, duty_cycle) < 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static int calculate_duty_cycle(int flame_duration_ms) {
    if (flame_duration_ms <= 0) return 0;
    double decay = pow(2.0, -flame_duration_ms / 1000.0);
    return (int)(PWM_RANGE * (1.0 - decay));
}

static void cleanup(void) {
    if (log_file) {
        log_event("System shutdown");
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(FAN_PWM_PIN, 0);
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PWM_PIN, PI_INPUT);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    log_file = fopen("flame_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    log_event("System started");

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting flame sensor pin mode\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(FAN_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting fan PWM pin mode\n");
        cleanup();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency\n");
        cleanup();
        return 1;
    }
    if (gpioSetPWMrange(FAN_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int flame_active = 0;
    int flame_start_ms = 0;
    int no_flame_count = 0;

    log_event("Monitoring started");

    while (running) {
        int flame_val = read_flame_sensor(FLAME_SENSOR_PIN);
        if (flame_val < 0) {
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (flame_val == 0) {
            if (!flame_active) {
                flame_active = 1;
                flame_start_ms = gpioTick();
                log_event("Flame detected");
                set_fan_speed(FAN_PWM_PIN, calculate_duty_cycle(0));
            } else {
                int duration_ms = (int)(gpioTick() - flame_start_ms) / 1000;
                if (duration_ms > FLAME_TIMEOUT_MS) {
                    log_event("Flame timeout - sensor absent or wiring fault");
                    flame_active = 0;
                    set_fan_speed(FAN_PWM_PIN, 0);
                } else {
                    int duty = calculate_duty_cycle(duration_ms);
                    set_fan_speed(FAN_PWM_PIN, duty);
                    char msg[128];
                    snprintf(msg, sizeof(msg), "Flame duration: %d ms, Duty: %d%%", duration_ms, duty);
                    log_event(msg);
                }
            }
        } else {
            if (flame_active) {
                flame_active = 0;
                set_fan_speed(FAN_PWM_PIN, 0);
                log_event("Flame ended");
            }
            no_flame_count++;
            if (no_flame_count > FLAME_TIMEOUT_MS) {
                log_event("No flame for too long - sensor absent or wiring fault");
                no_flame_count = 0;
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    log_event("System shutting down");
    cleanup();
    return 0;
}

