static int read_lux(int handle, float *lux) {
    uint16_t raw = 0;
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_read_reg16(handle, REG_RESULT, &raw) == 0) {
            uint16_t exponent = (raw >> 12) & 0x0F;
            uint16_t mantissa = raw & 0x0FFF;
            *lux = 0.01f * (float)(1UL << exponent) * (float)mantissa;
            return 0;
        }
        retries++;
        if (retries < MAX_RETRIES) {
            gpioDelay(10000); /* 10 ms backoff */
        }
    }
    return -1;
}

static int log_data(float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    fprintf(fp, "%s, %.2f\n", timestamp, lux);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (handle=%d).\n", I2C_BUS, OPT3001_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (opt3001_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: OPT3001 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to install signal handlers: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("OPT3001 light sensor logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        float lux = 0.0f;
        if (read_lux(i2c_handle, &lux) == 0) {
            if (log_data(lux) != 0) {
                fprintf(stderr, "Warning: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Warning: Failed to read lux value after %d retries.\n", MAX_RETRIES);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

