/*
 * Flame Detection Sensor Monitor (Raspberry Pi 3 Model B+)
 * Sensor: SainSmart IR Flame Detection Module (digital output, active-low)
 * Wiring:
 *   Sensor DOUT  -> GPIO17 (physical pin 11)
 *   Sensor VCC  -> 3.3 V (physical pin 1)
 *   Sensor GND  -> GND   (physical pin 9)
 *
 * Behavior:
 *   GPIO17 reads 0 when a flame is detected, 1 otherwise.
 *   Every 1 second, prints a timestamped message to stdout.
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    printf("[%s] ", buf);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *request = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    int ret = EXIT_FAILURE;

    /* --- Install signal handler for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open the GPIO chip --- */
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Configure the line as input with pull-up bias --- */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "gpiod_line_settings_new() failed\n");
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_PULL_UP);

    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "gpiod_line_config_new() failed\n");
        goto cleanup;
    }

    unsigned int offset = GPIO_LINE_OFFSET;
    if (gpiod_line_config_add_line_settings(line_cfg, &offset, 1, settings) != 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings() failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Request the line --- */
    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "gpiod_request_config_new() failed\n");
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "flame-detect");

    request = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (request == NULL) {
        fprintf(stderr, "gpiod_chip_request_lines() failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Flame detection monitoring started on GPIO%d (active-low).\n", GPIO_LINE_OFFSET);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        int value = gpiod_line_request_get_value(request, GPIO_LINE_OFFSET);
        if (value < 0) {
            fprintf(stderr, "gpiod_line_request_get_value() failed: %s\n", strerror(errno));
            goto cleanup;
        }

        print_timestamp();

        if (value == 0) {
            printf("Flame Detected: YES\n");
        } else {
            printf("Flame Detected: NO\n");
        }
        fflush(stdout);

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (request != NULL) {
        gpiod_line_request_release(request);
    }
    if (req_cfg != NULL) {
        gpiod_request_config_free(req_cfg);
    }
    if (line_cfg != NULL) {
        gpiod_line_config_free(line_cfg);
    }
    if (settings != NULL) {
        gpiod_line_settings_free(settings);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

