#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 100

static const unsigned int sensor_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int i;
    int ret;

    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = NULL;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi Zero W) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    /* Acquire each line as input */
    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for BCM GPIO %u\n", sensor_pins[i]);
            goto cleanup;
        }
        ret = gpiod_line_request_input(lines[i], "ttp226-sensor");
        if (ret < 0) {
            fprintf(stderr, "Failed to request input for BCM GPIO %u: %s\n",
                    sensor_pins[i], strerror(-ret));
            goto cleanup;
        }
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to install SIGINT handler");
        goto cleanup;
    }

    printf("TTP226 8-channel touch sensor reader started.\n");
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        printf("Channel: ");
        for (i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading BCM GPIO %u: %s\n",
                        sensor_pins[i], strerror(-val));
                goto cleanup;
            }
            printf("%d ", val);
        }
        printf("\n");
        fflush(stdout);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully...\n");

cleanup:
    /* Release all acquired lines */
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return EXIT_SUCCESS;
}

