#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define SAMPLE_DELAY_US 100000  /* 100 ms */

static const int gpio_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_gpio(void) {
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(gpio_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", gpio_pins[i]);
            return -1;
        }
        if (gpioSetPullUpDown(gpio_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d\n", gpio_pins[i]);
            return -1;
        }
    }
    return 0;
}

static void log_sensor_data(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    long long timestamp_ms = (long long)ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL;

    printf("[+%lld ms] ", timestamp_ms);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int state = gpioRead(gpio_pins[i]);
        printf("CH%d=%d ", i + 1, state);
    }
    printf("\n");
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        log_sensor_data();
        gpioDelay(SAMPLE_DELAY_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

