/*
 * TMAG5110 Hall-Effect Latch Sensor Reader (pigpio, BCM GPIO)
 * Board:  Raspberry Pi 3 Model B+
 * Sensors: Two TMAG5110 latched Hall-effect switches
 *   - Sensor 1 OUT -> BCM GPIO 4
 *   - Sensor 2 OUT -> BCM GPIO 5
 *   (External pull-up resistors: unasserted = HIGH, asserted = LOW)
 *
 * Build:  gcc -Wall -o hall_effect hall_effect.c -lpigpio -lrt
 * Run:    sudo ./hall_effect
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 5
#define POLL_DELAY_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins as inputs --- */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set BCM GPIO %d as input.\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set BCM GPIO %d as input.\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main polling loop --- */
    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        /*
         * TMAG5110 latched output:
         *   LOW  -> magnet detected (output driven low)
         *   HIGH -> no magnet (output floating high due to pull-up)
         */
        printf("Sensor 1 (BCM %d): %s\n", SENSOR_1_PIN,
               (s1 == 0) ? "LOW (magnet detected)" : "HIGH (no magnet)");
        printf("Sensor 2 (BCM %d): %s\n", SENSOR_2_PIN,
               (s2 == 0) ? "LOW (magnet detected)" : "HIGH (no magnet)");
        printf("---\n");
        fflush(stdout);

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

