code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50
#define CONSUMER "ttp226-reader"

static const unsigned int gpio_pins[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int format_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *request = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    int ret;
    int exit_code = EXIT_FAILURE;

    memset(gpio_pins, 0, sizeof(gpio_pins));

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: cannot install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        chip = gpiod_chip_open_by_label("pinctrl-bcm2711");
    }
    if (chip == NULL) {
        chip = gpiod_chip_open_by_number(0);
    }
    if (chip == NULL) {
        fprintf(stderr, "Error: cannot open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "Error: cannot allocate line settings: %s\n", strerror(errno));
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_DISABLED);

    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "Error: cannot allocate line config: %s\n", strerror(errno));
        goto cleanup;
    }

    unsigned int offsets[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++) {
        offsets[i] = gpio_pins[i];
    }

    ret = gpiod_line_config_add_line_settings(line_cfg, offsets, NUM_CHANNELS, settings);
    if (ret) {
        fprintf(stderr, "Error: cannot add line settings: %s\n", strerror(errno));
        goto cleanup;
    }

    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "Error: cannot allocate request config: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, CONSUMER);

    request = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (request == NULL) {
        fprintf(stderr, "Error: cannot request GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Timestamp,Channel1,Channel2,Channel3,Channel4,Channel5,Channel6,Channel7,Channel8\n");
    fflush(stdout);

    while (program_running) {
        char timestamp[32];
        int values[NUM_CHANNELS];

        ret = gpiod_line_request_get_values(request, values);
        if (ret) {
            fprintf(stderr, "Error: cannot read line values: %s\n", strerror(errno));
            break;
        }

        if (format_timestamp(timestamp, sizeof(timestamp)) == 0) {
            printf("%s,%d,%d,%d,%d,%d,%d,%d,%d\n",
                   timestamp,
                   values[0], values[1], values[2], values[3],
                   values[4], values[5], values[6], values[7]);
        } else {
            fprintf(stderr, "Error: cannot format timestamp\n");
        }
        fflush(stdout);

        struct timespec delay = {0, POLL_INTERVAL_MS * 1000000L};
        nanosleep(&delay, NULL);
    }

    exit_code = EXIT_SUCCESS;

cleanup:
    if (request) {
        gpiod_line_request_release(request);
    }
    if (req_cfg) {
        gpiod_request_config_free(req_cfg);
    }
    if (line_cfg) {
        gpiod_line_config_free(line_cfg);
    }
    if (settings) {
        gpiod_line_settings_free(settings);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return exit_code;
}

