#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TILT_GPIO 4
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void log_tilt_state(int level)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    const char *state = (level == 0) ? "Tilted" : "Not Tilted";
    printf("[%s] %s\n", timestamp, state);
    fflush(stdout);
}

int main(void)
{
    int last_level = -1;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TILT_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TILT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TILT_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", TILT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n", TILT_GPIO);
    fflush(stdout);

    while (g_running) {
        int level = gpioRead(TILT_GPIO);
        if (level < 0) {
            fprintf(stderr, "gpioRead failed on GPIO %d\n", TILT_GPIO);
            break;
        }

        if (level != last_level) {
            log_tilt_state(level);
            last_level = level;
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

