#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR1_ADDR   0x36
#define SENSOR2_ADDR   0x37
#define START_MEAS_CMD 0x3608
#define MEAS_REG       0x00
#define CMD_REG        0x08
#define FLOW_SCALE     0.036f
#define ALARM_GPIO     17
#define ALARM_THRESHOLD 0.5f
#define LOG_FILE       "flow_log.txt"
#define POLL_INTERVAL  1

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t reg, uint16_t cmd) {
    uint8_t buf[3] = { reg, (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_sensor(int fd) {
    if (i2c_write_cmd(fd, CMD_REG, START_MEAS_CMD) < 0)
        return -1;
    usleep(100000);
    return 0;
}

static int read_flow_rate(int fd, float *flow_out) {
    uint8_t buf[9];
    if (i2c_read_bytes(fd, MEAS_REG, buf, sizeof(buf)) < 0)
        return -1;

    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Flow CRC mismatch\n");
        return -1;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (sensirion_crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Flow CRC mismatch\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw * FLOW_SCALE;
    return 0;
}

int main(void) {
    struct sigaction sa = { .sa_handler = sig_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return 1;
    }
    struct gpiod_line *alarm_line = gpiod_chip_get_line(chip, ALARM_GPIO);
    if (!alarm_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", ALARM_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(alarm_line, "flow_alarm", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", ALARM_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    int fd1 = open(I2C_BUS, O_RDWR);
    if (fd1 < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (ioctl(fd1, I2C_SLAVE, SENSOR1_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", SENSOR1_ADDR, strerror(errno));
        close(fd1);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (init_sensor(fd1) < 0) {
        fprintf(stderr, "Sensor 1 init failed\n");
        close(fd1);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        return 1;
    }

    int fd2 = open(I2C_BUS, O_RDWR);
    if (fd2 < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        close(fd1);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (ioctl(fd2, I2C_SLAVE, SENSOR2_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", SENSOR2_ADDR, strerror(errno));
        close(fd1);
        close(fd2);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (init_sensor(fd2) < 0) {
        fprintf(stderr, "Sensor 2 init failed\n");
        close(fd1);
        close(fd2);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        return 1;
    }

    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(fd1);
        close(fd2);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = (read_flow_rate(fd1, &f1) == 0);
        int ok2 = (read_flow_rate(fd2, &f2) == 0);

        if (ok1 && ok2) {
            float avg = (f1 + f2) / 2.0f;
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
            fprintf(log_fp, "%s, %.2f\n", ts, avg);
            fflush(log_fp);

            int alarm = (avg < ALARM_THRESHOLD) ? 1 : 0;
            if (gpiod_line_set_value(alarm_line, alarm) < 0)
                fprintf(stderr, "Failed to set alarm GPIO: %s\n", strerror(errno));
        } else {
            fprintf(stderr, "Sensor read error; skipping cycle\n");
        }

        sleep(POLL_INTERVAL);
    }

    fprintf(stderr, "\nShutting down...\n");
    fclose(log_fp);
    close(fd1);
    close(fd2);
    gpiod_line_set_value(alarm_line, 0);
    gpiod_line_release(alarm_line);
    gpiod_chip_close(chip);
    return 0;
}

