#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_PIN 4
#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000

typedef struct {
    time_t timestamp;
    int reading;
} ObstacleEvent;

static ObstacleEvent event_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void print_timestamp(time_t ts) {
    struct tm tm_info;
    char time_str[32];
    localtime_r(&ts, &tm_info);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("%s", time_str);
}

static void add_event(time_t ts, int reading) {
    event_buffer[buffer_index].timestamp = ts;
    event_buffer[buffer_index].reading = reading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_buffer(void) {
    printf("\n--- Obstacle Detection Log ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        print_timestamp(event_buffer[idx].timestamp);
        printf(" - Obstacle: %s\n", event_buffer[idx].reading == 0 ? "DETECTED" : "cleared");
    }
    printf("--- End of Log ---\n\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
