#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x55
#define D7S_REG_MODE   0x1D
#define D7S_REG_STATUS 0x1B
#define D7S_REG_X_LSB  0x2A
#define D7S_REG_X_MSB  0x2B
#define D7S_REG_Y_LSB  0x2C
#define D7S_REG_Y_MSB  0x2D
#define D7S_REG_Z_LSB  0x2E
#define D7S_REG_Z_MSB  0x2F
#define D7S_MODE_ACTIVE 0x10
#define D7S_STATUS_ACTIVE 0x01
#define SAMPLE_PERIOD_MS 500
#define ACTIVATION_TIMEOUT_MS 1000
#define SCALE_FACTOR 0.0009765625f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16_le(int fd, uint8_t reg_lsb, int16_t *out) {
    uint8_t lsb, msb;
    if (i2c_read_reg8(fd, reg_lsb, &lsb) < 0) return -1;
    if (i2c_read_reg8(fd, reg_lsb + 1, &msb) < 0) return -1;
    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

static int d7s_init(int fd) {
    if (i2c_write_reg8(fd, D7S_REG_MODE, D7S_MODE_ACTIVE) < 0) return -1;
    for (int i = 0; i < ACTIVATION_TIMEOUT_MS; i += 10) {
        uint8_t status;
        if (i2c_read_reg8(fd, D7S_REG_STATUS, &status) < 0) return -1;
        if (status & D7S_STATUS_ACTIVE) return 0;
        usleep(10000);
    }
    fprintf(stderr, "D7S sensor did not activate within %d ms\n", ACTIVATION_TIMEOUT_MS);
    return -1;
}

static int read_d7s(int fd, float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;
    if (i2c_read_reg16_le(fd, D7S_REG_X_LSB, &raw_x) < 0) return -1;
    if (i2c_read_reg16_le(fd, D7S_REG_Y_LSB, &raw_y) < 0) return -1;
    if (i2c_read_reg16_le(fd, D7S_REG_Z_LSB, &raw_z) < 0) return -1;
    *x = (float)raw_x * SCALE_FACTOR;
    *y = (float)raw_y * SCALE_FACTOR;
    *z = (float)raw_z * SCALE_FACTOR;
    return 0;
}

static int log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", D7S_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (d7s_init(g_i2c_fd) < 0) {
        fprintf(stderr, "D7S initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    g_csv = fopen("fan_health.csv", "a");
    if (!g_csv) {
        fprintf(stderr, "Cannot open fan_health.csv: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }
    fseek(g_csv, 0, SEEK_END);
    if (ftell(g_csv) == 0) {
        fprintf(g_csv, "timestamp,x_g,y_g,z_g\n");
        fflush(g_csv);
    }

    printf("Monitoring fan vibration (Ctrl+C to stop)...\n");

    while (g_running) {
        float x, y, z;
        if (read_d7s(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, retrying next cycle\n");
        } else {
            if (log_data(g_csv, x, y, z) < 0) {
                fprintf(stderr, "Log write error\n");
            }
        }
        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (g_csv) fclose(g_csv);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

