#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN      25
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int setup_gpio(void)
{
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_2_PIN);
        return -1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LED_PIN);
        return -1;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize LED state on GPIO %d\n", LED_PIN);
        return -1;
    }
    return 0;
}

static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d (rc=%d)\n", pin, v);
        return -1;
    }
    return v;
}

static int control_led(int state)
{
    int rc = gpioWrite(LED_PIN, state);
    if (rc != 0) {
        fprintf(stderr, "Error: gpioWrite failed on LED GPIO %d (rc=%d)\n", LED_PIN, rc);
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Warning: sensor read error, continuing...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        int obstacle = (s1 == 0 || s2 == 0) ? 1 : 0;

        if (control_led(obstacle) != 0) {
            fprintf(stderr, "Warning: LED control failed\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

