#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* TMAG5170-Q1 I2C address (A0=A1=0) */
#define TMAG5170_ADDR 0x0E

/* TMAG5170-Q1 register addresses */
#define TMAG5170_REG_DEVICE_ID      0x00
#define TMAG5170_REG_X_CH_RESULT    0x04
#define TMAG5170_REG_Y_CH_RESULT    0x06
#define TMAG5170_REG_Z_CH_RESULT    0x08
#define TMAG5170_REG_CONFIG         0x0A

/* Expected device ID for TMAG5170 */
#define TMAG5170_DEVICE_ID_EXPECTED 0x8D

/* Config register bits for continuous conversion, 50 mT range, all axes enabled */
#define TMAG5170_CONFIG_CONT_CONV   0x01
#define TMAG5170_CONFIG_RANGE_50MT  0x00
#define TMAG5170_CONFIG_X_EN       0x01
#define TMAG5170_CONFIG_Y_EN       0x02
#define TMAG5170_CONFIG_Z_EN       0x04
#define TMAG5170_CONFIG_MODE_CONT  0x00
#define TMAG5170_CONFIG_MASK       (TMAG5170_CONFIG_CONT_CONV | TMAG5170_CONFIG_RANGE_50MT | TMAG5170_CONFIG_X_EN | TMAG5170_CONFIG_Y_EN | TMAG5170_CONFIG_Z_EN | TMAG5170_CONFIG_MODE_CONT)

/* LSB scale factor for 50 mT range (from datasheet) */
#define TMAG5170_LSB_50MT 0.0000625f

#define I2C_BUS 1
#define LOG_FILE "magnetic_log.csv"
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int write_config(int handle, uint8_t config) {
    int rc = i2cWriteByteData(handle, TMAG5170_REG_CONFIG, config);
    if (rc < 0) {
        fprintf(stderr, "Error writing config register 0x%02X: pigpio error %d\n", TMAG5170_REG_CONFIG, rc);
        return -1;
    }
    return 0;
}

static int verify_device_id(int handle) {
    int id = i2cReadByteData(handle, TMAG5170_REG_DEVICE_ID);
    if (id < 0) {
        fprintf(stderr, "Error reading device ID register: pigpio error %d\n", id);
        return -1;
    }
    if (id != TMAG5170_DEVICE_ID_EXPECTED) {
        fprintf(stderr, "Device ID mismatch: expected 0x%02X, got 0x%02X\n", TMAG5170_DEVICE_ID_EXPECTED, id);
        return -1;
    }
    printf("TMAG5170 detected (device ID 0x%02X)\n", id);
    return 0;
}

static int initialize_sensor(int handle) {
    if (write_config(handle, TMAG5170_CONFIG_MASK) < 0) {
        return -1;
    }
    /* Allow time for the first conversion to complete after config write */
    gpioDelay(10000);
    return 0;
}

static int read_axis(int handle, uint8_t reg, float *value_mt) {
    int raw = i2cReadWordData(handle, reg);
    if (raw < 0) {
        fprintf(stderr, "Error reading register 0x%02X: pigpio error %d\n", reg, raw);
        return -1;
    }
    /* pigpio returns data in little-endian format (low byte, high byte) */
    int16_t signed_raw = (int16_t)((raw & 0xFF) | ((raw >> 8) & 0xFF) << 8);
    *value_mt = (float)signed_raw * TMAG5170_LSB_50MT;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.4f,%.4f,%.4f\n", timestamp, x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, TMAG5170_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: pigpio error %d\n", I2C_BUS, TMAG5170_ADDR, g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (verify_device_id(g_i2c_handle) < 0) {
        fprintf(stderr, "TMAG5170 not detected on bus %d, addr 0x%02X\n", I2C_BUS, TMAG5170_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(g_i2c_handle) < 0) {
        fprintf(stderr, "Failed to initialize TMAG5170\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,x_mt,y_mt,z_mt\n");
        fflush(g_log_file);
    }

    printf("Logging magnetic field data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        float x, y, z;
        int rc = read_axis(g_i2c_handle, TMAG5170_REG_X_CH_RESULT, &x);
        if (rc < 0) {
            fprintf(stderr, "Error reading X axis, continuing...\n");
        } else {
            rc = read_axis(g_i2c_handle, TMAG5170_REG_Y_CH_RESULT, &y);
            if (rc < 0) {
                fprintf(stderr, "Error reading Y axis, continuing...\n");
            } else {
                rc = read_axis(g_i2c_handle, TMAG5170_REG_Z_CH_RESULT, &z);
                if (rc < 0) {
                    fprintf(stderr, "Error reading Z axis, continuing...\n");
                } else {
                    log_data(g_log_file, x, y, z);
                }
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (g_log_file != NULL) {
        fclose(g_log_file);
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return 0;
}

