#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_PIN 4          /* BCM GPIO 4, physical pin 7 */
#define SAMPLE_INTERVAL_US 1000000  /* 1 second in microseconds */
#define LOG_FILE "rpm_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/*
 * pigpio timer callback.
 * Runs in a pigpio worker thread — keep it short and non-blocking.
 */
static void rpm_timer_cb(void *user_data)
{
    (void)user_data;

    static volatile int pulse_count = 0;
    static volatile uint32_t last_tick = 0;
    static volatile int first_sample = 1;

    uint32_t now = gpioTick();  /* microseconds since boot */

    /* Only count rising edges (level == 1) */
    if (gpioRead(SENSOR_PIN) == 1) {
        if (first_sample) {
            first_sample = 0;
            last_tick = now;
            return;
        }
        pulse_count++;
    }

    /* pigpio timer fires once per second; handle 32-bit tick wraparound */
    if (now >= last_tick) {
        double seconds = (double)(now - last_tick) / 1000000.0;
        if (seconds >= 1.0) {
            double rpm = (double)pulse_count * 60.0 / seconds;
            time_t rawtime;
            struct tm timeinfo;
            char timestamp[32];

            time(&rawtime);
            localtime_r(&rawtime, &timeinfo);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

            if (g_log_fp) {
                if (fprintf(g_log_fp, "%s %.2f\n", timestamp, rpm) < 0) {
                    fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
                }
                if (fflush(g_log_fp) != 0) {
                    fprintf(stderr, "fflush log failed: %s\n", strerror(errno));
                }
            }
            printf("%s RPM: %.2f\n", timestamp, rpm);
            fflush(stdout);

            pulse_count = 0;
            last_tick = now;
        }
    }
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pin --- */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for pin %d\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Start 1-second timer --- */
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, rpm_timer_cb, NULL) != 0) {
        fprintf(stderr, "gpioSetTimerFuncEx failed\n");
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on BCM GPIO %d. Press Ctrl+C to exit.\n", SENSOR_PIN);
    fflush(stdout);

    /* --- Main loop: wait for signal --- */
    while (g_running) {
        gpioDelay(100000);  /* 100 ms sleep to reduce CPU usage */
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, NULL, NULL);  /* disable timer */
    gpioSetAlertFuncEx(SENSOR_PIN, NULL, NULL);             /* disable alert */
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

