    STATE_A_HIGH_B_HIGH
} quadrature_state_t;

static quadrature_state_t current_state = STATE_A_LOW_B_LOW;
static quadrature_state_t previous_state = STATE_A_LOW_B_LOW;
static pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * pigpio alert callback.
 * level: 0 = falling, 1 = rising, 2 = watchdog timeout
 * gpio: 0-based pin number
 * tick: microseconds since boot (32-bit wrap-around period ~71.6 min)
 */
static void sensor_alert_cb(int gpio, int level, uint32_t tick) {
    (void)tick;
    if (level != 0) {
        return; /* Only act on rising edges */
    }

    int sensor_a_pin = (gpio == SENSOR_A_GPIO) ? SENSOR_A_GPIO : SENSOR_B_GPIO;
    int sensor_b_pin = (gpio == SENSOR_A_GPIO) ? SENSOR_B_GPIO : SENSOR_A_GPIO;

    int a_val = gpioRead(sensor_a_pin);
    int b_val = gpioRead(sensor_b_pin);

    if (a_val < 0 || b_val < 0) {
        return; /* Read error */
    }

    quadrature_state_t new_state;
    if (a_val == 0 && b_val == 0) {
        new_state = STATE_A_LOW_B_LOW;
    } else if (a_val == 1 && b_val == 0) {
        new_state = STATE_A_HIGH_B_LOW;
    } else if (a_val == 0 && b_val == 1) {
        new_state = STATE_A_LOW_B_HIGH;
    } else {
        new_state = STATE_A_HIGH_B_HIGH;
    }

    pthread_mutex_lock(&state_mutex);
    previous_state = current_state;
    current_state = new_state;
    pthread_mutex_unlock(&state_mutex);
}

static void log_rotation(const char *direction) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t len = strlen(timestamp);
    snprintf(timestamp + len, sizeof(timestamp) - len, ".%03ld", ts.tv_nsec / 1000000);

    fprintf(fp, "%s - Rotation: %s\n", timestamp, direction);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO modes and enable pull-up resistors */
    if (gpioSetMode(SENSOR_A_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_A_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_B_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_B_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_A_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_B_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register alert callbacks for both sensors */
    if (gpioSetAlertFunc(SENSOR_A_GPIO, sensor_alert_cb) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d\n", SENSOR_A_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetAlertFunc(SENSOR_B_GPIO, sensor_alert_cb) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d\n", SENSOR_B_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Rotation detection started. Press Ctrl+C to exit.\n");

    while (running) {
        pthread_mutex_lock(&state_mutex);
        quadrature_state_t current = current_state;
        quadrature_state_t previous = previous_state;
        pthread_mutex_unlock(&state_mutex);

        if (current != previous) {
            /* Detect direction based on the quadrature sequence */
            if (current == STATE_A_HIGH_B_HIGH && previous == STATE_A_LOW_B_LOW) {
                log_rotation("CW");
            } else if (current == STATE_A_LOW_B_LOW && previous == STATE_A_HIGH_B_HIGH) {
                log_rotation("CCW");
            } else {
                /* Fall-through: handle other transitions if needed */
            }
        }

        gpioDelay(10000); /* 10 ms sleep to reduce CPU usage */
    }

    /* Cleanup */
    gpioSetAlertFunc(SENSOR_A_GPIO, NULL);
    gpioSetAlertFunc(SENSOR_B_GPIO, NULL);
    gpioTerminate();
    pthread_mutex_destroy(&state_mutex);

    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

