#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <gpiod.h>

#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18
#define POLL_INTERVAL_US 50000
#define CONSUMER "touch_led"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    openlog(CONSUMER, LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to register SIGINT handler: %s", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler: %s", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        goto cleanup;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        syslog(LOG_ERR, "Failed to get touch sensor line (GPIO %d): %s", TOUCH_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        syslog(LOG_ERR, "Failed to get LED line (GPIO %d): %s", LED_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(touch_line, CONSUMER) < 0) {
        syslog(LOG_ERR, "Failed to request touch sensor line as input: %s", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, CONSUMER, 0) < 0) {
        syslog(LOG_ERR, "Failed to request LED line as output: %s", strerror(errno));
        goto cleanup;
    }

    syslog(LOG_INFO, "Touch sensor and LED control started. Touch sensor on GPIO %d, LED on GPIO %d.", TOUCH_SENSOR_PIN, LED_PIN);

    while (program_running) {
        int touch_value = gpiod_line_get_value(touch_line);
        if (touch_value < 0) {
            syslog(LOG_ERR, "Failed to read touch sensor: %s", strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        int led_value = (touch_value == 1) ? 1 : 0;

        if (gpiod_line_set_value(led_line, led_value) < 0) {
            syslog(LOG_ERR, "Failed to set LED value: %s", strerror(errno));
        }

        if (touch_value == 1) {
            syslog(LOG_INFO, "Touch detected, LED ON");
        } else {
            syslog(LOG_INFO, "Touch released, LED OFF");
        }

        usleep(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down gracefully...");
    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
    return ret;
}

