#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define TOUCH_PIN 17
#define LED_PIN 18
#define DEBOUNCE_MS 50

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    /* Open the gpiochip that exposes GPIO 17/18 on the Pi 3 B+ */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        fprintf(stderr, "Failed to get touch line %d: %s\n", TOUCH_PIN, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line %d: %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request LED line as output, initial value LOW */
    if (gpiod_line_request_output(led_line, "ttp223b-led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request touch line for rising-edge events */
    if (gpiod_line_request_rising_edge_events(touch_line, "ttp223b-touch") < 0) {
        fprintf(stderr, "Failed to request rising-edge events on touch line: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    struct timespec last_event = {0, 0};
    int led_state = 0;

    while (running) {
        struct timespec ts = {1, 0}; /* 1-second timeout per iteration */
        int ev = gpiod_line_event_wait(touch_line, &ts);
        if (ev < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Event wait error: %s\n", strerror(errno));
            goto cleanup;
        }
        if (ev == 0) continue; /* timeout, loop back */

        struct gpiod_line_event event;
        if (gpiod_line_event_read(touch_line, &event) < 0) {
            fprintf(stderr, "Event read error: %s\n", strerror(errno));
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) continue;

        /* Software debounce: ignore events within DEBOUNCE_MS */
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        long delta_ms = (now.tv_sec - last_event.tv_sec) * 1000L +
                        (now.tv_nsec - last_event.tv_nsec) / 1000000L;
        if (delta_ms < DEBOUNCE_MS) continue;
        last_event = now;

        led_state = !led_state;
        if (gpiod_line_set_value(led_line, led_state) < 0) {
            fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("Touch detected, LED toggled to %d\n", led_state);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) gpiod_line_release(led_line);
    if (touch_line) gpiod_line_release(touch_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

