#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN   27
#define LED_2_PIN   22
#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000  /* 50 ms */

typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} TouchEvent;

static TouchEvent touch_buffer[BUFFER_SIZE];
static int buffer_head = 0;
static int buffer_count = 0;
static int overflow_count = 0;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_2_PIN);
        return -1;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LED_1_PIN);
        return -1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LED_2_PIN);
        return -1;
    }

    /* Ensure LEDs start off */
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);

    return 0;
}

static void log_touch_event(int sensor_pin, int state) {
    TouchEvent *entry = &touch_buffer[buffer_head];
    entry->sensor_pin = sensor_pin;
    entry->timestamp  = time(NULL);
    entry->state      = state;

    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    } else {
        overflow_count++;
    }
}

static void cleanup(void) {
    /* Turn off LEDs */
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);

    /* Release GPIO resources */
    gpioTerminate();

    /* Print log buffer contents */
    printf("\n--- Touch Log ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_head - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        TouchEvent *entry = &touch_buffer[idx];
        printf("Sensor: %d, Timestamp: %ld, State: %d\n",
               entry->sensor_pin, (long)entry->timestamp, entry->state);
    }

    if (overflow_count > 0) {
        printf("Warning: %d event(s) overwrote oldest entry(s)\n", overflow_count);
    }

    printf("--- End of Log ---\n");
}

int main(void) {
    struct sigaction sa;
