#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define DEBOUNCE_US 5000
#define PULSES_PER_REV 2
#define LOG_FILE "shaft_log.txt"

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_sensor(int gpio) {
    int level = gpioRead(gpio);
    gpioDelay(DEBOUNCE_US);
    return gpioRead(gpio);
}

void log_data(FILE *fp, int s1, int s2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%d,%d\n", timestamp, s1, s2);
    fflush(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    int prev_s1 = -1, prev_s2 = -1;
    printf("Monitoring shaft RPM... Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = read_sensor(SENSOR_1_GPIO);
        int s2 = read_sensor(SENSOR_2_GPIO);

        if (s1 != prev_s1) {
            log_data(fp, s1, prev_s2);
            prev_s1 = s1;
        }
        if (s2 != prev_s2) {
            log_data(fp, prev_s1, s2);
            prev_s2 = s2;
        }

        if (s1 == 1 && s2 == 1) {
            static int last_count = 0;
            int count = 0;
            if (prev_s1 == 1 && prev_s2 == 1) {
                count = last_count;
            } else {
                count = 1;
            }
            last_count = count;
            double rpm = (double)count * 60.0 / PULSES_PER_REV;
            printf("RPM: %.2f\n", rpm);
        }

        gpioDelay(10000);
    }

    printf("\nExiting gracefully...\n");
    fclose(fp);
    gpioTerminate();
    return 0;
}

