#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x28
#define HEART_RATE_REG 0x02
#define SPO2_REG 0x04
#define CONFIG_REG 0x30
#define PART_ID_REG 0x00
#define EXPECTED_PART_ID 0x82
#define LOG_FILE "biometric_log.txt"
#define SAMPLE_INTERVAL_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int initialize_sensor(int handle) {
    uint8_t part_id = 0;
    if (read_register(handle, PART_ID_REG, &part_id) != 0) {
        fprintf(stderr, "Failed to read PART_ID. Sensor may be absent.\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X). Wrong sensor?\n", part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("Si1182 detected (PART_ID=0x%02X).\n", part_id);

    if (write_register(handle, CONFIG_REG, 0x01) != 0) {
        fprintf(stderr, "Failed to configure sensor.\n");
        return -1;
    }
    return 0;
}

static int read_heart_rate(int handle, int *heart_rate) {
    uint8_t hr_raw = 0;
    if (read_register(handle, HEART_RATE_REG, &hr_raw) != 0) {
        return -1;
    }
    *heart_rate = (int)hr_raw;
    return 0;
}

static int read_spo2(int handle, int *spo2) {
    uint8_t spo2_raw = 0;
    if (read_register(handle, SPO2_REG, &spo2_raw) != 0) {
        return -1;
    }
    *spo2 = (int)spo2_raw;
    return 0;
}

static int log_data(FILE *fp, int heart_rate, int spo2) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n", I2C_BUS, SI1182_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

