#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define ALARM_GPIO    27
#define TILT_THRESHOLD_MS 2000
#define POLL_INTERVAL_US  100000  /* 100 ms */
#define LOG_FILE_NAME     "bridge_integrity.log"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *event_type) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event_type);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open; event: %s\n", event_type);
    }
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        return -1;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        return -1;
    }
    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ALARM_GPIO);
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_1_GPIO);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_2_GPIO);
        return -1;
    }

    if (gpioWrite(ALARM_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize alarm GPIO %d LOW\n", ALARM_GPIO);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE_NAME, strerror(errno));
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    log_event("Bridge integrity monitoring started");

    int sensor1_active = 0;
    int sensor2_active = 0;
    uint32_t tilt_start_time = 0;
    uint32_t alarm_active_time = 0;

    while (program_running) {
        int s1 = gpioRead(SENSOR_1_GPIO);
        int s2 = gpioRead(SENSOR_2_GPIO);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "gpioRead error (s1=%d, s2=%d)\n", s1, s2);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (s1 == 1) {
            if (!sensor1_active) {
                sensor1_active = 1;
                tilt_start_time = gpioTick();
                log_event("Tilt detected on sensor 1");
            }
        } else {
            if (sensor1_active) {
                sensor1_active = 0;
                uint32_t elapsed = gpioTick() - tilt_start_time;
                if (elapsed > TILT_THRESHOLD_MS * 1000) {
                    if (gpioWrite(ALARM_GPIO, 1) == 0) {
                        alarm_active_time = gpioTick();
                        log_event("Threshold exceeded on sensor 1");
                    }
                } else {
                    log_event("Tilt ended on sensor 1");
                }
            }
        }

        if (s2 == 1) {
            if (!sensor2_active) {
                sensor2_active = 1;
                tilt_start_time = gpioTick();
                log_event("Tilt detected on sensor 2");
            }
        } else {
            if (sensor2_active) {
                sensor2_active = 0;
                uint32_t s2_elapsed = gpioTick() - tilt_start_time;
                if (s2_elapsed > TILT_THRESHOLD_MS * 1000) {
                    if (gpioWrite(ALARM_GPIO, 1) == 0) {
                        alarm_active_time = gpioTick();
                        log_event("Threshold exceeded on sensor 2");
                    }
                } else {
                    log_event("Tilt ended on sensor 2");
                }
            }
        }

        if (gpioWrite(ALARM_GPIO, 0) != 0) {
            fprintf(stderr, "Failed to deactivate alarm GPIO %d\n", ALARM_GPIO);
        }

        if (sensor1_active && sensor2_active) {
            uint32_t combined_elapsed = gpioTick() - alarm_active_time;
            if (combined_elapsed > TILT_THRESHOLD_MS * 1000) {
                if (gpioWrite(ALARM_GPIO, 0) == 0) {
                    log_event("Alarm deactivated (both sensors returned to LOW)");
                }
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("Bridge integrity monitoring stopped");
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    return EXIT_SUCCESS;
}

