/*
 * Raspberry Pi 3 Model B+ - Omron D7S-A0011 Seismic Sensor Monitor
 *
 * Wiring:
 *   D7S-A0011 SDA -> GPIO2 (pin 3)
 *   D7S-A0011 SCL -> GPIO3 (pin 5)
 *   D7S-A0011 VDD -> 3.3 V
 *   D7S-A0011 GND -> GND
 *   LED anode -> GPIO17 (pin 11) via 330 ohm resistor -> GND
 *
 * Build: gcc -O2 -Wall -o seismic seismic.c -lpigpio -lm -lrt
 * Run:   sudo ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- D7S-A0011 constants (from datasheet) ---- */
#define D7S_I2C_ADDR        0x1D          /* default 7-bit address */
#define D7S_REG_CTRL1       0x1F          /* control register 1 */
#define D7S_REG_OUT_X_L     0x28          /* X-axis LSB, little-endian 6-byte block */
#define D7S_REG_OUT_X_H     0x29
#define D7S_REG_OUT_Y_L     0x2A
#define D7S_REG_OUT_Y_H     0x2B
#define D7S_REG_OUT_Z_L     0x2C
#define D7S_REG_OUT_Z_H     0x2D

#define D7S_CTRL1_PWR_DOWN  0x01          /* bit 0: power-down */
#define D7S_CTRL1_STANDBY   0x02          /* bit 1: standby mode */

#define LED_GPIO             17
#define VIBRATION_THRESHOLD  500.0f
#define POLL_DELAY_US        100000        /* 100 ms */
#define LED_ON_DELAY_US      1000000       /* 1 s */
#define MAX_RETRIES          3
#define LOG_FILE             "seismic_events.log"

/* ---- Globals for cleanup ---- */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    int16_t x, y, z;
} AccelData;

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* ---- I2C helpers ---- */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    return i2cWriteDevice(handle, buf, 2);
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

/* ---- Sensor init ---- */
static int init_sensor(int handle) {
    uint8_t ctrl1;

    /* Read CTRL1 to verify sensor presence */
    if (i2c_read_block(handle, D7S_REG_CTRL1, &ctrl1, 1) != 1) {
        fprintf(stderr, "Error: cannot read CTRL1 - sensor may be absent.\n");
        return -1;
    }

    /* Clear power-down bit (bit 0) to wake the sensor */
    if (i2c_write_byte(handle, D7S_REG_CTRL1, ctrl1 & ~D7S_CTRL1_PWR_DOWN) != 0) {
        fprintf(stderr, "Error: failed to clear power-down bit.\n");
        return -1;
    }

    /* Set standby mode (bit 1) for continuous operation */
    if (i2c_write_byte(handle, D7S_REG_CTRL1, ctrl1 | D7S_CTRL1_STANDBY) != 0) {
        fprintf(stderr, "Error: failed to set standby mode.\n");
        return -1;
    }

    return 0;
}

/* ---- Read acceleration with retries ---- */
static int read_acceleration(int handle, AccelData *data) {
    uint8_t buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_read_block(handle, D7S_REG_OUT_X_L, buf, 6) == 6) {
            data->x = (int16_t)((buf[1] << 8) | buf[0]);
            data->y = (int16_t)((buf[3] << 8) | buf[2]);
            data->z = (int16_t)((buf[5] << 8) | buf[4]);
            return 0;
        }
        retries++;
        if (retries < MAX_RETRIES)
            gpioDelay(10000); /* 10 ms backoff */
    }
    return -1;
}

/* ---- Vibration magnitude ---- */
static float calculate_vibration_magnitude(const AccelData *data) {
    float x = (float)data->x;
    float y = (float)data->y;
