/*
 * flame_monitor.c — Raspberry Pi 3 Model B+
 * Monitors 5 Keyes KY-026 flame sensors on BCM GPIO 2, 3, 4, 17, 27.
 * Logs rising-edge flame events to /var/log/flame_events.log.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <gpiod.h>

#define NUM_SENSORS      5
#define LOG_FILE         "/var/log/flame_events.log"
#define POLL_INTERVAL_S  1
#define DEBOUNCE_MS      50
#define TIMESTAMP_LEN    32
#define LINE_LEN         64
#define MSG_LEN          256

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};
static const char *sensor_names[NUM_SENSORS] = {"Sensor1", "Sensor2", "Sensor3", "Sensor4", "Sensor5"};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        syslog(LOG_WARNING, "sigaction(SIGINT) failed: %s", strerror(errno));
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        syslog(LOG_WARNING, "sigaction(SIGTERM) failed: %s", strerror(errno));
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int sensor_id, unsigned int gpio_pin)
{
    FILE *fp;
    int fd;
    struct flock fl;
    time_t now;
    struct tm tm_info;
    char timestamp[TIMESTAMP_LEN];
    char message[MSG_LEN];

    now = time(NULL);
    if (now == (time_t)-1) {
        syslog(LOG_ERR, "time() failed: %s", strerror(errno));
        return;
    }

    if (localtime_r(&now, &tm_info) == NULL) {
        syslog(LOG_ERR, "localtime_r() failed");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_info) == 0) {
        syslog(LOG_ERR, "strftime() failed");
        return;
    }

    snprintf(message, sizeof(message),
             "%s - Sensor ID: %d (GPIO %u) - Flame Detected",
             timestamp, sensor_id, gpio_pin);

    /*
     * Acquire exclusive lock on the log file so that two instances
     * cannot interleave writes.  If the file is unlinked while we
     * hold the lock, flockfile() returns -1 and errno is set to
     * EWOULDBLOCK; treat this as a non-fatal condition.
     */
    fd = fileno(fopen(LOG_FILE, "a"));
    if (fd < 0) {
        syslog(LOG_ERR, "fopen(%s) failed: %s", LOG_FILE, strerror(errno));
        return;
    }

    fp = fdopen(fd, "w");
    if (fp == NULL) {
        syslog(LOG_ERR, "fdopen(%s) failed: %s", LOG_FILE, strerror(errno));
        return;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        if (errno == EWOULDBLOCK) {
            syslog(LOG_WARNING, "Log file unavailable; event not logged: %s", message);
        } else {
            syslog(LOG_ERR, "flock(LOCK_EX) failed: %s", strerror(errno));
        }
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s\n", message) < 0) {
        syslog(LOG_ERR, "fprintf() failed: %s", strerror(errno));
    }

    if (fflush(fp) == EOF) {
        syslog(LOG_ERR, "fflush() failed: %s", strerror(errno));
    }

    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_WARNING, "flock(LOCK_UN) failed: %s", strerror(errno));
    }

    if (fclose(fp) == EOF) {
        syslog(LOG_ERR, "fclose() failed: %s", strerror(errno));
    }

    syslog(LOG_INFO, "%s", message);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int read_sensor(struct gpiod_line *line, int sensor_id, unsigned int gpio_pin)
{
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        syslog(LOG_ERR, "gpiod_line_get_value(GPIO %u) failed: %s",
               gpio_pin, strerror(errno));
        return -1;
    }
    return val;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts;
    ts.tv_sec  = ms / 1000;
    ts.tv_nsec = (long)(ms % 1000) * 1000000L;
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    int prev_state[NUM_SENSORS];
    int i;
    int ret = EXIT_FAILURE;

    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    install_signal_handlers();

    for (i = 0; i < NUM_SENSORS; i++) {
        lines[i] = NULL;
        prev_state[i] = 0;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name(gpiochip0) failed: %s", strerror(errno));
        goto cleanup;
    }

    for (i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (lines[i] == NULL) {
            syslog(LOG_ERR, "gpiod_chip_get_line(%u) failed: %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(GPIO %u) failed: %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    syslog(LOG_INFO, "Flame monitoring started on GPIO %u, %u, %u, %u, %u",
           sensor_pins[0], sensor_pins[1], sensor_pins[2],
           sensor_pins[3], sensor_pins[4]);

    while (g_running) {
        for (i = 0; i < NUM_SENSORS; i++) {
            int val = read_sensor(lines[i], i + 1, sensor_pins[i]);
            if (val < 0) {
                /* Read failure — log and continue rather than abort. */
                continue;
            }

            if (val == 0 && prev_state[i] != 0) {
                /* Rising edge: debounce re-read. */
                sleep_ms(DEBOUNCE_MS);
                val = read_sensor(lines[i], i + 1, sensor_pins[i]);
                if (val < 0) {
                    syslog(LOG_ERR, "Debounce read failed for GPIO %u: %s",
                           sensor_pins[i], strerror(errno));
                    continue;
                }
                if (val == 0) {
                    log_event(i + 1, sensor_pins[i]);
                }
            }
            prev_state[i] = val;
        }
        sleep(POLL_INTERVAL_S);
    }

    syslog(LOG_INFO, "Shutting down flame monitoring");
    ret = EXIT_SUCCESS;

cleanup:
    for (i = 0; i < NUM_SENSORS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    closelog();
    return ret;
}

