#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_SENSORS 8
#define POLL_INTERVAL_MS 50
#define CONSUMER "ttp226-touch"

static const unsigned int sensor_pins[NUM_SENSORS] = {5, 6, 13, 19, 26, 12, 16, 20};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void) {
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];
    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", &tm_info) > 0) {
        printf("[%s] ", buf);
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk bulk;
    struct gpiod_line *lines[NUM_SENSORS];
    int prev_state[NUM_SENSORS];
    int ret;

    memset(lines, 0, sizeof(lines));

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default GPIO chip (gpiochip0 on Raspberry Pi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Resolve each BCM pin into a gpiod_line pointer */
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get line for BCM pin %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Request all lines as inputs in bulk */
    ret = gpiod_line_request_bulk_input(&bulk, lines, NUM_SENSORS);
    if (ret < 0) {
        fprintf(stderr, "Failed to request bulk input lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Read initial states */
    for (int i = 0; i < NUM_SENSORS; i++) {
        int val = gpiod_line_get_value(lines[i]);
        if (val < 0) {
            fprintf(stderr, "Failed to read initial state for BCM pin %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        prev_state[i] = val;
    }

    printf("TTP226 touch sensor monitoring started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading BCM pin %u: %s\n",
                        sensor_pins[i], strerror(errno));
                goto cleanup;
            }

            if (val != prev_state[i]) {
                print_timestamp();
                printf("Sensor %d (BCM %u): %s\n",
                       i, sensor_pins[i], val ? "TOUCHED" : "released");
                prev_state[i] = val;
            }
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    /* Release lines and close chip on all exit paths */
    if (chip != NULL) {
        gpiod_line_release_bulk(&bulk, lines);
        gpiod_chip_close(chip);
    }
    return (program_running == 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}

