#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VEML7700_ADDR  0x10
#define CONFIG_REG     0x00
#define ALS_REG        0x04
#define GPIO_LED       18
#define PWM_FREQ       1000
#define PWM_RANGE      100
#define LOG_FILE       "grow_log.txt"
#define SAMPLE_US      1000000  /* 1 second */

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int veml7700_write_config(int handle, uint16_t config) {
    /* VEML7700 config register: 16-bit, low byte first, high byte second */
    char buf[2];
    buf[0] = (char)(config & 0xFF);
    buf[1] = (char)((config >> 8) & 0xFF);
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        return -1;
    }
    return 0;
}

static int veml7700_read_als(int handle, uint16_t *lux_raw) {
    char buf[2];
    if (i2cReadI2CBlockData(handle, ALS_REG, buf, 2) != 2) {
        return -1;
    }
    *lux_raw = (uint16_t)((buf[1] << 8) | (buf[0] & 0xFF));
    return 0;
}

static int set_led_brightness(int gpio, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    if (gpioPWM(gpio, brightness) != 0) {
        return -1;
    }
    return 0;
}

static void log_data(FILE *fp, float lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(fp, "Timestamp: (error), Lux: %.2f, Brightness: %d, Error: %d\n",
                lux, brightness, error_code);
    } else {
        fprintf(fp, "Timestamp: %04d-%02d-%02d %02d:%02d:%02d, Lux: %.2f, Brightness: %d, Error: %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                lux, brightness, error_code);
    }
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", VEML7700_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure VEML7700: gain 1/8 (0x00), integration time 100 ms (0x00) */
    if (veml7700_write_config(i2c_handle, 0x0000) != 0) {
        fprintf(stderr, "Failed to configure VEML7700\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LED);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(GPIO_LED, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "Warning: could not set exact PWM frequency\n");
    }
    if (gpioSetPWMrange(GPIO_LED, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Warning: could not set exact PWM range\n");
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Grow light system started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t lux_raw = 0;
        int error_code = 0;

        if (veml7700_read_als(i2c_handle, &lux_raw) != 0) {
            error_code = -1;
            fprintf(stderr, "Error reading ALS data\n");
        } else {
            float lux = (float)lux_raw * 0.0576f;
            int brightness;
            if (lux < 100.0f) { brightness = 100; }
            else if (lux < 500.0f) { brightness = 75; }
            else if (lux < 1000.0f) { brightness = 50; }
            else { brightness = 25; }

            if (set_led_brightness(GPIO_LED, brightness) != 0) {
                error_code = -2;
                fprintf(stderr, "Error setting LED brightness\n");
            }

            log_data(log_file, lux, brightness, error_code);
        }

        gpioDelay(SAMPLE_US);
    }

    /* Cleanup */
    set_led_brightness(GPIO_LED, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Grow light system stopped.\n");
    return EXIT_SUCCESS;
}

