    /* Configure VEML7700: gain 1/8 (0x00), integration time 100 ms (0x00) */
    if (veml7700_write_config(i2c_handle, 0x0000) != 0) {
        fprintf(stderr, "Failed to configure VEML7700\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LED);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(GPIO_LED, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "Warning: could not set exact PWM frequency\n");
    }
    if (gpioSetPWMrange(GPIO_LED, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Warning: could not set exact PWM range\n");
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Grow light system started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t lux_raw = 0;
        int error_code = 0;

        if (veml7700_read_als(i2c_handle, &lux_raw) != 0) {
            error_code = -1;
            fprintf(stderr, "Error reading ALS data\n");
        } else {
            float lux = (float)lux_raw * 0.0576f;
            int brightness;
            if (lux < 100.0f) { brightness = 100; }
            else if (lux < 500.0f) { brightness = 75; }
            else if (lux < 1000.0f) { brightness = 50; }
            else { brightness = 25; }

            if (set_led_brightness(GPIO_LED, brightness) != 0) {
                error_code = -2;
                fprintf(stderr, "Error setting LED brightness\n");
            }

            log_data(log_file, lux, brightness, error_code);
        }

        gpioDelay(SAMPLE_US);
    }

    /* Cleanup */
    set_led_brightness(GPIO_LED, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Grow light system stopped.\n");
    return EXIT_SUCCESS;
}

