    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Security keypad simulation started. Press Ctrl+C to exit.\n");

    int last_state[NUM_CHANNELS];
    int any_touched = 0;

    while (running) {
        int any_new = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpioRead(touch_pins[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading GPIO %d\n", touch_pins[i]);
                continue;
            }

            /* Debounce: only accept if stable for DEBOUNCE_US microseconds */
            if (val != last_state[i]) {
                gpioDelay(DEBOUNCE_US);
                val = gpioRead(touch_pins[i]);
                if (val < 0) {
                    fprintf(stderr, "Error reading GPIO %d during debounce\n", touch_pins[i]);
                    continue;
                }
                if (val == last_state[i]) {
                    continue;  /* transient glitch, ignore */
                }
            }
            last_state[i] = val;

            if (val == 1) {
                if (!any_touched) {
                    any_touched = 1;
                    any_new = 1;
                }
                if (log_touch_event(i + 1) != 0) {
                    fprintf(stderr, "Warning: failed to log touch event for channel %d\n", i + 1);
                }
            } else {
                if (any_touched) {
                    any_touched = 0;
                    any_new = 1;
                }
            }
        }

        /* Update LED to reflect whether any channel is currently touched */
        if (gpioWrite(LED_PIN, any_touched ? 1 : 0) != 0) {
            fprintf(stderr, "Error writing to LED GPIO %d\n", LED_PIN);
        }

        if (any_new) {
            gpioDelay(POLL_DELAY_US);
        }
    }

    /* Graceful cleanup */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

