#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_WORD 0xC810  /* Continuous conversion, auto-range, 100 ms CT */
#define LOG_FILE "light_data.txt"
#define SAMPLE_INTERVAL_US 1000000  /* 1 second */
#define CONVERSION_WAIT_US 100000   /* 100 ms for first conversion */

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(1, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %s\n",
                OPT3001_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int configure_opt3001(void) {
    /* pigpio i2cWriteWordData sends the data in little-endian format,
     * but the OPT3001 expects big-endian (MSB first). Swap bytes. */
    uint16_t swapped = ((CONFIG_WORD >> 8) & 0xFF) | ((CONFIG_WORD & 0xFF) << 8);
    int rc = i2cWriteWordData(i2c_handle, CONFIG_REG, swapped);
    if (rc < 0) {
        fprintf(stderr, "Error writing configuration register 0x%02X: %s\n",
                CONFIG_REG, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_lux(float *lux_out) {
    int raw = i2cReadWordData(i2c_handle, RESULT_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading result register 0x%02X: %s\n",
                RESULT_REG, strerror(errno));
        return -1;
    }
    /* Swap bytes to restore big-endian order expected by OPT3001 */
    uint16_t swapped = ((raw >> 8) & 0xFF) | ((raw & 0xFF) << 8);
    uint16_t exponent = (swapped >> 12) & 0x0F;
    uint16_t mantissa = swapped & 0x0FFF;
    *lux_out = (float)mantissa * 0.01f * (float)(1u << exponent);
    return 0;
}

static int log_data(float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s, %.2f\n", timestamp, lux);
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (configure_opt3001() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Wait for the first conversion to complete (100 ms conversion time) */
    gpioDelay(CONVERSION_WAIT_US);

    while (!terminate) {
        float lux;
        if (read_lux(&lux) == 0) {
            if (log_data(lux) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Warning: failed to read lux value\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

