#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SLF3S_ADDR 0x08
#define LOG_FILE "cooling_log.csv"
#define SAMPLE_INTERVAL_US 1000000
#define FLOW_CONVERSION_FACTOR 90.0f
#define MIN_FLOW_RATE 0.0f
#define MAX_FLOW_RATE 100.0f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int initialize_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, SLF3S_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_flow_rate(float *flow_rate) {
    uint8_t cmd[2] = {0x36, 0x08};
    uint8_t buf[3];
    int result;

    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing measurement command to I2C: %d\n", result);
        return -1;
    }

    gpioDelay(2000);

    result = i2cReadDevice(i2c_handle, (char *)buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C: expected 3 bytes, got %d\n", result);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }

    int16_t raw_flow = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw_flow / FLOW_CONVERSION_FACTOR;
    return 0;
}

static void log_data(float flow_rate, int status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return;
    }

    if (status == 0) {
        fprintf(log_file, "%s,%.2f,%s\n", timestamp, flow_rate, "OK");
    } else {
        fprintf(log_file, "%s,%.2f,%s\n", timestamp, flow_rate, "ERROR");
    }
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float flow_rate;
    int status;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
        fflush(log_file);
    }

    while (running) {
        status = read_flow_rate(&flow_rate);
        if (status == 0) {
            if (flow_rate < MIN_FLOW_RATE || flow_rate > MAX_FLOW_RATE) {
                fprintf(stderr, "Flow rate out of range: %.2f ml/min\n", flow_rate);
                log_data(flow_rate, 1);
            } else {
                log_data(flow_rate, 0);
            }
        } else {
            fprintf(stderr, "Error reading flow rate. Attempting recovery...\n");
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Recovery failed. Exiting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

