            fprintf(stderr, "Failed to get timestamp\n");
            break;
        }

        if (log_data(fp, timestamp, left_val, middle_val, right_val) != 0) {
            perror("log_data");
            break;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fclose(fp);
    }
    if (left_line != NULL) {
        gpiod_line_release(left_line);
    }
    if (middle_line != NULL) {
        gpiod_line_release(middle_line);
    }
    if (right_line != NULL) {
        gpiod_line_release(right_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

