#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TOUCH_GPIO 23
#define LED_GPIO 24
#define GPIO_CHIP "/dev/gpiochip4"
#define LOG_FILE "touch_log.txt"
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(FILE *log_file, int led_state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Touch detected, LED state: %d\n", timestamp, led_state) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    FILE *log_file = NULL;
    int led_state = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_GPIO);
    if (touch_line == NULL) {
        fprintf(stderr, "Error getting touch GPIO line %d: %s\n", TOUCH_GPIO, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (led_line == NULL) {
        fprintf(stderr, "Error getting LED GPIO line %d: %s\n", LED_GPIO, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_rising_edge_events(touch_line, "ttp223_touch") < 0) {
        fprintf(stderr, "Error requesting rising edge events on touch GPIO %d: %s\n", TOUCH_GPIO, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "ttp223_led", 0) < 0) {
        fprintf(stderr, "Error requesting LED GPIO %d as output: %s\n", LED_GPIO, strerror(errno));
        goto cleanup;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        struct gpiod_line_event event;
        int event_ret = gpiod_line_event_wait(touch_line, &(struct timespec){0, POLL_TIMEOUT_MS * 1000000L});

        if (event_ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error waiting for touch event: %s\n", strerror(errno));
            goto cleanup;
        }

        if (event_ret == 0) {
            continue;
        }

        if (gpiod_line_event_read(touch_line, &event) < 0) {
            fprintf(stderr, "Error reading touch event: %s\n", strerror(errno));
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
            continue;
        }

        led_state = !led_state;
        if (gpiod_line_set_value(led_line, led_state) < 0) {
            fprintf(stderr, "Error setting LED value: %s\n", strerror(errno));
            continue;
        }

        if (log_event(log_file, led_state) < 0) {
            fprintf(stderr, "Error logging event\n");
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line != NULL) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (touch_line != NULL) {
        gpiod_line_release(touch_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return ret;
}

