/*
 * Flame detection safety system — Raspberry Pi 3 Model B+
 * Sensor : Keyes KY-026 flame sensor (digital output, active-low)
 * Buzzer : Active buzzer on GPIO18 (physical pin 12)
 * API    : libgpiod (character-device interface)
 *
 * Build  : gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 * Run    : sudo ./flame_alert   (root needed for /dev/gpiochip0 access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define FLAME_PIN      17          /* GPIO17, physical pin 11 */
#define BUZZER_PIN     18          /* GPIO18, physical pin 12 */
#define CHIP_NAME      "gpiochip0"
#define LOG_FILE       "alert_log.txt"
#define POLL_MS        500
#define BUZZER_MS      2000
#define SLICE_MS       100

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (g_log) {
        fprintf(g_log, "%s: %s\n", ts, msg);
        fflush(g_log);
    }
    printf("%s: %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
static void activate_buzzer(struct gpiod_line *buzzer, int duration_ms)
{
    if (gpiod_line_set_value(buzzer, 1) < 0) {
        fprintf(stderr, "Failed to set buzzer HIGH: %s\n", strerror(errno));
        return;
    }
    log_event("Flame detected! Buzzer activated.");

    for (int elapsed = 0; elapsed < duration_ms && g_running; elapsed += SLICE_MS) {
        usleep(SLICE_MS * 1000);
    }

    if (gpiod_line_set_value(buzzer, 0) < 0) {
        fprintf(stderr, "Failed to set buzzer LOW: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame = NULL;
    struct gpiod_line *buzzer = NULL;
    int prev_flame = 1;   /* assume no flame at startup */
    int ret = EXIT_FAILURE;

    /* ---- signal handling ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- open log file --------------------------------------------- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }
    log_event("System started");

    /* ---- open GPIO chip ------------------------------------------- */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s): %s\n",
                CHIP_NAME, strerror(errno));
        log_event("Error: cannot open GPIO chip");
        goto cleanup;
    }

    /* ---- get lines ------------------------------------------------- */
    flame = gpiod_chip_get_line(chip, FLAME_PIN);
    if (!flame) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                FLAME_PIN, strerror(errno));
        log_event("Error: cannot get flame line");
        goto cleanup;
    }

    buzzer = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                BUZZER_PIN, strerror(errno));
        log_event("Error: cannot get buzzer line");
        goto cleanup;
    }

    /* ---- request lines --------------------------------------------- */
    if (gpiod_line_request_input(flame, "flame_alert") < 0) {
        fprintf(stderr, "gpiod_line_request_input(flame): %s\n",
                strerror(errno));
        log_event("Error: cannot request flame line as input");
        goto cleanup;
    }

    if (gpiod_line_request_output(buzzer, "flame_alert", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output(buzzer): %s\n",
                strerror(errno));
        log_event("Error: cannot request buzzer line as output");
        goto cleanup;
    }

    log_event("System started");

    /* ---- main loop ------------------------------------------------- */
    while (g_running) {
        int val = gpiod_line_get_value(flame);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_get_value(flame): %s\n",
                    strerror(errno));
            log_event("Error: failed to read flame sensor");
            break;
        }

        /* Active-low: LOW (0) means flame detected */
        if (val == 0 && prev_flame == 1) {
            activate_buzzer(buzzer, BUZZER_MS);
        }
        prev_flame = val;

        for (int elapsed = 0; elapsed < POLL_MS && g_running;
             elapsed += SLICE_MS) {
            usleep(SLICE_MS * 1000);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* ---- graceful shutdown ----------------------------------------- */
    if (buzzer) {
        gpiod_line_set_value(buzzer, 0);   /* ensure buzzer off */
        gpiod_line_release(buzzer);
    }
    if (flame) {
        gpiod_line_release(flame);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (g_log) {
        log_event("System stopped");
        fclose(g_log);
        g_log = NULL;
    }
    return ret;
}

