#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TOUCH_SENSOR_PIN 4
#define LED_PIN 17
#define LOG_FILE "touch_log.txt"
#define DEBOUNCE_MS 200
#define POLL_MS 10

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_touch_event(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    gmtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo);

    if (log_fp) {
        if (fprintf(log_fp, "%s: Touch detected\n", timestamp) < 0) {
            fprintf(stderr, "Warning: failed to write to log file: %s\n", strerror(errno));
        }
        fflush(log_fp);
    } else {
        fprintf(stderr, "Warning: log file not open; event lost: %s\n", timestamp);
    }
}

int main(void) {
    int last_state = 0;
    uint32_t last_event_tick = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install signal handlers: %s\n", strerror(errno));
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = gpioRead(TOUCH_SENSOR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d\n", TOUCH_SENSOR_PIN);
            break;
        }

        uint32_t now = gpioTick();
        if (current_state == 1 && last_state == 0) {
            if (now - last_event_tick > DEBOUNCE_MS * 1000) {
                int led_state = gpioRead(LED_PIN);
                if (led_state < 0) {
                    fprintf(stderr, "Error: failed to read LED state on GPIO%d\n", LED_PIN);
                    break;
                }
                if (gpioWrite(LED_PIN, !led_state) != 0) {
                    fprintf(stderr, "Error: failed to toggle LED on GPIO%d\n", LED_PIN);
                    break;
                }
                log_touch_event();
                last_event_tick = now;
            }
        }
        last_state = current_state;
        gpioDelay(POLL_MS * 1000);
    }

    gpioWrite(LED_PIN, 0);
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioTerminate();
    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

