        fprintf(stderr, "Warning: failed to install signal handlers: %s\n", strerror(errno));
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = gpioRead(TOUCH_SENSOR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d\n", TOUCH_SENSOR_PIN);
            break;
        }

        uint32_t now = gpioTick();
        if (current_state == 1 && last_state == 0) {
            if (now - last_event_tick > DEBOUNCE_MS * 1000) {
                int led_state = gpioRead(LED_PIN);
                if (led_state < 0) {
                    fprintf(stderr, "Error: failed to read LED state on GPIO%d\n", LED_PIN);
                    break;
                }
                if (gpioWrite(LED_PIN, !led_state) != 0) {
                    fprintf(stderr, "Error: failed to toggle LED on GPIO%d\n", LED_PIN);
                    break;
                }
                log_touch_event();
                last_event_tick = now;
            }
        }
        last_state = current_state;
        gpioDelay(POLL_MS * 1000);
    }

    gpioWrite(LED_PIN, 0);
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioTerminate();
    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

