#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17
#define SENSOR_3_GPIO 27
#define LOG_FILE "magnet_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

/* TMAG5110A1 open-drain OUT pin:
 *   Low  -> south magnetic pole detected (magnet present)
 *   High -> no magnet detected
 * Internal pull-up keeps the line high when the sensor is idle;
 * the OUT pin pulls low when a south pole is near.
 */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", SENSOR_1_GPIO);
        return -1;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", SENSOR_2_GPIO);
        return -1;
    }
    if (gpioSetMode(SENSOR_3_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", SENSOR_3_GPIO);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d\n", SENSOR_1_GPIO);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d\n", SENSOR_2_GPIO);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR_3_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d\n", SENSOR_3_GPIO);
        return -1;
    }
    return 0;
}

static int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error: failed to read GPIO%d\n", gpio_pin);
        return -1;
    }
    return value;
}

static void log_state(int sensor_id, int state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s - Sensor %d: %s\n", timestamp, sensor_id,
                state ? "Magnet Removed" : "Magnet Present") < 0) {
        fprintf(stderr, "Error: failed to write to log file\n");
    } else {
        fflush(log_file);
    }
}

int main(void) {
    int prev_state[3] = {0, 0, 0};
    int curr_state[3] = {0, 0, 0};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n",
                strerror(errno));
    }

    printf("Magnetic sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < 3; i++) {
            curr_state[i] = read_sensor(i == 0 ? SENSOR_1_GPIO :
                                      i == 1 ? SENSOR_2_GPIO : SENSOR_3_GPIO);
            if (curr_state[i] < 0) {
                /* Read error already reported; skip this sensor this cycle. */
                continue;
            }
            if (curr_state[i] != prev_state[i]) {
                log_state(i + 1, curr_state[i]);
                prev_state[i] = curr_state[i];
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

