#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x4A

#define REG_PART_ID 0x00
#define REG_HW_REV 0x01
#define REG_LED_CURRENT 0x3F
#define REG_AVG_CONFIG 0x04
#define REG_ENABLE 0x01
#define REG_HR_DATA 0x2A

#define MOVING_AVG_WINDOW 5
#define MIN_BPM 30
#define MAX_BPM 220
#define RETRY_DELAY_US 100000
#define SAMPLE_INTERVAL_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X = 0x%02X: %d\n", reg, value, rc);
        return -1;
    }
    return 0;
}

static int read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int verify_sensor(void) {
    uint8_t part_id = 0, hw_rev = 0;
    if (read_reg(REG_PART_ID, &part_id) < 0) return -1;
    if (read_reg(REG_HW_REV, &hw_rev) < 0) return -1;
    if (part_id != 0x02 || hw_rev != 0x01) {
        fprintf(stderr, "Sensor verification failed: PART_ID=0x%02X HW_REV=0x%02X (expected 0x02 0x01)\n", part_id, hw_rev);
        return -1;
    }
    return 0;
}

static int configure_sensor(void) {
    if (write_reg(REG_LED_CURRENT, 0x0A) < 0) return -1;
    if (write_reg(REG_AVG_CONFIG, 0x04) < 0) return -1;
    if (write_reg(REG_ENABLE, 0x01) < 0) return -1;
    return 0;
}

static int read_heart_rate(float *bpm) {
    int raw = i2cReadWordData(i2c_handle, REG_HR_DATA);
    if (raw < 0) {
        fprintf(stderr, "Error reading HR data: %d\n", raw);
        return -1;
    }
    *bpm = (float)raw * 0.5f;
    return 0;
}

static float moving_average(float new_value, float *history, int window, int *index) {
    history[*index] = new_value;
    *index = (*index + 1) % window;
    float sum = 0.0f;
    for (int i = 0; i < window; i++) sum += history[i];
    return sum / (float)window;
}

static int log_heart_rate(float bpm) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (fprintf(log_file, "%s,%.2f\n", timestamp, bpm) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, SI1182_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (verify_sensor() < 0) {
        fprintf(stderr, "Si1182 sensor not detected or wrong part\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (configure_sensor() < 0) {
        fprintf(stderr, "Failed to configure Si1182\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("heart_rate.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening heart_rate.csv\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    float history[MOVING_AVG_WINDOW] = {0};
    int history_index = 0;

    while (!terminate) {
        float bpm = 0.0f;
        if (read_heart_rate(&bpm) == 0) {
            bpm = moving_average(bpm, history, MOVING_AVG_WINDOW, &history_index);
            if (bpm >= MIN_BPM && bpm <= MAX_BPM) {
                if (log_heart_rate(bpm) == 0) {
                    printf("BPM: %.2f\n", bpm);
                } else {
                    fprintf(stderr, "Failed to log heart rate\n");
                }
            } else {
                fprintf(stderr, "Invalid heart rate: %.2f BPM\n", bpm);
            }
        } else {
            fprintf(stderr, "Failed to read heart rate, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

