/*
 * touch_counter.c — Raspberry Pi Zero W
 *
 * Reads an 8-channel TTP226 capacitive touch sensor module (active-high)
 * on GPIO 5-12 and displays an 8-bit binary counter on GPIO 17-24.
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 *
 * libgpiod v2+ bulk/config API (no sysfs, no deprecated v1 simple API).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 10000   /* 10 ms */
#define STABILIZE_DELAY_MS 200   /* 200 ms after chip/line request */

/* ---- Pin assignments (BCM numbering) ---- */
static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
static const unsigned int display_pins[NUM_CHANNELS] = {17, 24, 23, 22, 21, 20, 19, 18};

/* ---- Globals for cleanup ---- */
static struct gpiod_chip *chip = NULL;
static struct gpiod_line_request *sensor_req = NULL;
static struct gpiod_line_request *display_req = NULL;
static volatile sig_atomic_t running = 1;

/* ---- Signal handler ---- */
static void handle_signal(int sig)
{
    (void)sig;
    running = 0;
}

/* ---- Timestamp helper ---- */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
}

/* ---- Log to file ---- */
static void log_touch_event(int channel, int counter)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    FILE *fp = fopen("touch_log.txt", "a");
    if (fp) {
        fprintf(fp, "%s, Channel: %d, Counter: %d\n", ts, channel, counter);
        fclose(fp);
    } else {
        fprintf(stderr, "Warning: cannot open touch_log.txt: %s\n",
                strerror(errno));
    }
}

/* ---- Cleanup all resources ---- */
static void cleanup(void)
{
    if (display_req) {
        /* Reset all display outputs to 0 (safe state) */
        for (int i = 0; i < NUM_CHANNELS; i++)
            gpiod_line_request_set_value(display_req, display_pins[i], 0);
        gpiod_line_request_release(display_req);
        display_req = NULL;
    }
    if (sensor_req) {
        gpiod_line_request_release(sensor_req);
        sensor_req = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

/* ---- Main ---- */
int main(void)
{
    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: cannot open /dev/gpiochip0: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Request sensor lines (input) ---- */
    struct gpiod_line_settings *in_settings = gpiod_line_settings_new();
    if (!in_settings) {
        fprintf(stderr, "Error: gpiod_line_settings_new failed: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    gpiod_line_settings_set_direction(in_settings, GPIOD_LINE_DIRECTION_INPUT);

    struct gpiod_line_config *in_cfg = gpiod_line_config_new();
    if (!in_cfg) {
        fprintf(stderr, "Error: gpiod_line_config_new failed: %s\n",
                strerror(errno));
        gpiod_line_settings_free(in_settings);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_config_add_line_settings(in_cfg, sensor_pins,
                                             NUM_CHANNELS, in_settings) < 0) {
        fprintf(stderr, "Error: gpiod_line_config_add_line_settings failed: %s\n",
                strerror(errno));
        gpiod_line_config_free(in_cfg);
        gpiod_line_settings_free(in_settings);
        cleanup();
        return EXIT_FAILURE;
    }

    sensor_req = gpiod_chip_request_lines(chip, NULL, in_cfg);
    if (!sensor_req) {
        fprintf(stderr, "Error: gpiod_chip_request_lines (sensor) failed: %s\n",
                strerror(errno));
        gpiod_line_config_free(in_cfg);
        gpiod_line_settings_free(in_settings);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Request display lines (output, initially 0) ---- */
    struct gpiod_line_settings *out_settings = gpiod_line_settings_new();
    if (!out_settings) {
        fprintf(stderr, "Error: gpiod_line_settings_new (output) failed: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    gpiod_line_settings_set_direction(out_settings, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_settings_set_output_value(out_settings, GPIOD_LINE_VALUE_INACTIVE);

    struct gpiod_line_config *out_cfg = gpiod_line_config_new();
    if (!out_cfg) {
        fprintf(stderr, "Error: gpiod_line_config_new (output) failed: %s\n",
                strerror(errno));
        gpiod_line_settings_free(out_settings);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_config_add_line_settings(out_cfg, display_pins,
                                             NUM_CHANNELS, out_settings) < 0) {
        fprintf(stderr, "Error: gpiod_line_config_add_line_settings (output) failed: %s\n",
                strerror(errno));
        gpiod_line_config_free(out_cfg);
        gpiod_line_settings_free(out_settings);
        cleanup();
        return EXIT_FAILURE;
    }

    display_req = gpiod_chip_request_lines(chip, NULL, out_cfg);
    if (!display_req) {
        fprintf(stderr, "Error: gpiod_chip_request_lines (display) failed: %s\n",
                strerror(errno));
        gpiod_line_config_free(out_cfg);
        gpiod_line_settings_free(out_settings);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Stabilization delay ---- */
    usleep(STABILIZE_DELAY_MS * 1000);

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction failed: %s\n", strerror(errno));
    }

    printf("Touch counter running. Press Ctrl+C to exit.\n");

    int prev_state[NUM_CHANNELS];
    int counter = 0;

    /* ---- Main loop ---- */
    while (running) {
        int new_state[NUM_CHANNELS];
        int read_failed = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_request_get_value(sensor_req, sensor_pins[i]);
            if (val < 0) {
                fprintf(stderr, "Error: gpiod_line_request_get_value failed on GPIO %u: %s\n",
                        sensor_pins[i], strerror(errno));
                read_failed = 1;
                break;
            }
            new_state[i] = val;
        }

        if (read_failed)
            break;

        /* Detect rising edges (inactive -> active) without double-counting */
        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (new_state[i] == 1 && prev_state[i] == 0) {
                counter = (counter + 1) % 256;

                if (gpiod_line_request_set_value(display_req, display_pins[i],
                                                counter & (1 << (NUM_CHANNELS - 1 - i))) < 0) {
                    fprintf(stderr, "Error: gpiod_line_request_set_value failed on GPIO %u: %s\n",
                            display_pins[i], strerror(errno));
                }

                log_touch_event(i + 1, counter);
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
            }
            prev_state[i] = new_state[i];
        }

        usleep(POLL_INTERVAL_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

