#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_17 17
#define GPIO_18 18
#define LOG_FILE "/var/log/tilt_events.log"
#define POLL_INTERVAL_MS 100
#define DEBOUNCE_MS 50

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(FILE *log_file, int sensor_id) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_id);
    fflush(log_file);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line18 = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line(GPIO 17)");
        goto cleanup;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("gpiod_chip_get_line(GPIO 18)");
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(line17, "tilt-monitor",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input_flags(GPIO 17)");
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(line18, "tilt-monitor",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input_flags(GPIO 18)");
        goto cleanup;
    }

    printf("Monitoring tilt sensors on GPIO %d and %d. Press Ctrl+C to exit.\n",
           GPIO_17, GPIO_18);

    int last_state17 = 1;  /* assume untouched (high) */
    int last_state18 = 1;
    struct timespec last_event17 = {0, 0};
    struct timespec last_event18 = {0, 0};

    while (program_running) {
        int val17 = gpiod_line_get_value(line17);
        int val18 = gpiod_line_get_value(line18);

        if (val17 < 0) {
            perror("gpiod_line_get_value(GPIO 17)");
            break;
        }
        if (val18 < 0) {
            perror("gpiod_line_get_value(GPIO 18)");
            break;
        }

        if (val17 != last_state17) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            long elapsed_ms = (now.tv_sec - last_event17.tv_sec) * 1000L +
                              (now.tv_nsec - last_event17.tv_nsec) / 1000000L;
            if (elapsed_ms > DEBOUNCE_MS) {
                log_event(log_file, 1);
                last_event17 = now;
            }
            last_state17 = val17;
        }

        if (val18 != last_state18) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            long elapsed_ms = (now.tv_sec - last_event18.tv_sec) * 1000L +
                              (now.tv_nsec - last_event18.tv_nsec) / 1000000L;
            if (elapsed_ms > DEBOUNCE_MS) {
                log_event(log_file, 2);
                last_event18 = now;
            }
            last_state18 = val18;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);

    printf("\nExiting gracefully.\n");
    return ret;
}

