#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MIC_GPIO 4
#define LED_GPIO 17
#define SAMPLE_PERIOD_US 125
#define LED_ON_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void print_timestamp_ms(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char buf[32];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("%s.%03ld", buf, ts.tv_nsec / 1000000);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MIC_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set MIC_GPIO %d as input.\n", MIC_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LED_GPIO %d as output.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize LED_GPIO %d to LOW.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int mic_val = gpioRead(MIC_GPIO);
        if (mic_val < 0) {
            fprintf(stderr, "Error: gpioRead failed on MIC_GPIO %d.\n", MIC_GPIO);
            break;
        }

        if (mic_val == 1) {
            print_timestamp_ms();
            printf(" - Sound detected!\n");
            fflush(stdout);

            if (gpioWrite(LED_GPIO, 1) != 0) {
                fprintf(stderr, "Error: gpioWrite failed to turn LED ON.\n");
                break;
            }
            gpioDelay(LED_ON_MS * 1000);
            if (gpioWrite(LED_GPIO, 0) != 0) {
                fprintf(stderr, "Error: gpioWrite failed to turn LED OFF.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

