/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 3 Model B+
 * Uses libgpiod (v1.x API: gpiod_line, gpiod_chip, gpiod_line_get_value).
 *
 * Compile:
 *   gcc -O2 -Wall -Wextra -o ttp226_reader ttp226_reader.c -lgpiod
 *
 * Wiring (TTP226 OUT1..OUT8 -> BCM GPIO):
 *   OUT1 -> GPIO5   OUT2 -> GPIO6   OUT3 -> GPIO13  OUT4 -> GPIO19
 *   OUT5 -> GPIO26  OUT6 -> GPIO12  OUT7 -> GPIO16  OUT8 -> GPIO20
 *
 * Each line is polled every 200 ms and its state (0 or 1) is printed
 * in a timestamped line: [timestamp] CH1=0 CH2=1 CH3=0 CH4=0 CH5=0 CH6=0 CH7=0 CH8=0
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200

static const unsigned int channel_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        fprintf(stderr, "[?s] ");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char buf[32];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("[%s.%03ld] ", buf, ts.tv_nsec / 1000000L);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int i;
    int ret = EXIT_FAILURE;

    for (i = 0; i < NUM_CHANNELS; i++)
        lines[i] = NULL;

    /* --- Signal handling for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open gpiochip0 --- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Request each channel line as input --- */
    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, channel_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get line for BCM GPIO %u: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "ttp226-reader") != 0) {
            fprintf(stderr, "Failed to request BCM GPIO %u as input: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main polling loop --- */
    while (g_running) {
        print_timestamp();

        for (i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read BCM GPIO %u: %s\n",
                        channel_pins[i], strerror(errno));
                goto cleanup;
            }
            printf("%d=%d ", i + 1, val);
        }
        printf("\n");
        fflush(stdout);

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int ms = 0; ms < POLL_INTERVAL_MS && g_running; ms += 100)
            usleep(100 * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* --- Release all libgpiod resources --- */
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL)
            gpiod_line_release(lines[i]);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nResources released. Exiting.\n");

    return ret;
}

