#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <syslog.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define PWM_FREQ  1000
#define PWM_RANGE 255
#define FADE_STEPS 50
#define FADE_DELAY_US 5000000  /* 5 seconds */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_led_color(uint8_t r, uint8_t g, uint8_t b) {
    if (gpioPWM(RED_PIN,  PWM_RANGE - r) < 0) {
        syslog(LOG_ERR, "gpioPWM failed on RED_PIN %d", RED_PIN);
        return -1;
    }
    if (gpioPWM(GREEN_PIN, PWM_RANGE - g) < 0) {
        syslog(LOG_ERR, "gpioPWM failed on GREEN_PIN %d", GREEN_PIN);
        return -1;
    }
    if (gpioPWM(BLUE_PIN,  PWM_RANGE - b) < 0) {
        syslog(LOG_ERR, "gpioPWM failed on BLUE_PIN %d", BLUE_PIN);
        return -1;
    }
    return 0;
}

static int fade_to_color(uint8_t r, uint8_t g, uint8_t b) {
    for (int i = 0; i <= FADE_STEPS && g_running; i++) {
        if (i < FADE_STEPS / 2) {
            uint8_t sr = (uint8_t)(r * i / FADE_STEPS);
            uint8_t sg = (uint8_t)(g * i / FADE_STEPS);
            uint8_t sb = (uint8_t)(b * i / FADE_STEPS);
        } else {
            uint8_t sr = (uint8_t)(r * (FADE_STEPS - i) / FADE_STEPS);
            uint8_t sg = (uint8_t)(g * (FADE_STEPS - i) / FADE_STEPS);
            uint8_t sb = (uint8_t)(b * (FADE_STEPS - i) / FADE_STEPS);
        }
        if (set_led_color(sr, sg, sb) < 0) {
            return -1;
        }
        gpioDelay(FADE_DELAY_US / FADE_STEPS);
    }
    return 0;
}

static uint8_t hsv_to_rgb(float h, float s, float v) {
    float c = v * s;
    float x = c * (1.0f - fabsf(fmodf(h * 6.0f, 2.0f) - 1.0f));
    float m = v - c;
    float r, g, b;
    if (h < 1.0f) {
        r = c; g = x; b = 0.0f;
    } else if (h < 2.0f) {
        r = x; g = c; b = 0.0f;
    } else if (h < 3.0f) {
        r = 0.0f; g = c; b = x;
    } else if (h < 4.0f) {
        r = 0.0f; g = x; b = c;
    } else if (h < 5.0f) {
        r = x; g = 0.0f; b = c;
    } else {
        r = c; g = 0.0f; b = x;
    }
    r += m; g += m; b += m;
    return (uint8_t)(r * 255.0f);
}

int main(void) {
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "mood_lamp starting");

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %m");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    while (g_running) {
        float h = (float)rand() / (float)RAND_MAX;
        float s = 1.0f;
        float v = 1.0f;
        uint8_t r = hsv_to_rgb(h, s, v);
        uint8_t g = hsv_to_rgb(h, s, v);
        uint8_t b = hsv_to_rgb(h, s, v);

        if (fade_to_color(r, g, b) < 0) {
            break;
        }
    }

    syslog(LOG_INFO, "Shutting down mood lamp");
    set_led_color(0, 0, 0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

