#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TCS34725_ADDR  0x29

#define TCS34725_CMD   0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME  0x01
#define TCS34725_ID     0x12
#define TCS34725_CDATAL 0x14
#define TCS34725_CDATAH 0x15
#define TCS34725_RDATAL 0x16
#define TCS34725_RDATAH 0x17
#define TCS34725_GDATAL 0x18
#define TCS34725_GDATAH 0x19
#define TCS34725_BDATAL 0x1A
#define TCS34725_BDATAH 0x1B
#define TCS34725_CONTROL 0x0F

#define RED_THRESHOLD 200
#define GPIO_CHIP     "gpiochip4"
#define LED_LINE      17

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { (uint8_t)(TCS34725_CMD | reg), val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    uint8_t cmd = (uint8_t)(TCS34725_CMD | reg);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (read reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg_l, uint16_t *out) {
    uint8_t lo, hi;
    if (i2c_read_reg(fd, reg_l, &lo) < 0) return -1;
    if (i2c_read_reg(fd, reg_l + 1, &hi) < 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id;
    if (i2c_read_reg(fd, TCS34725_ID, &id) < 0) return -1;
    if (id != 0x44) {
        fprintf(stderr, "Unexpected sensor ID 0x%02X (expected 0x44)\n", id);
        return -1;
    }
    if (i2c_write_reg(fd, TCS34725_ENABLE, 0x03) < 0) return -1;
    if (i2c_write_reg(fd, TCS34725_ATIME, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, TCS34725_CONTROL, 0x00) < 0) return -1;
    return 0;
}

static int tcs34725_read(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c) {
    if (i2c_read_reg16(fd, TCS34725_CDATAL, c) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_RDATAL, r) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_GDATAL, g) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_BDATAL, b) < 0) return -1;
