        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", TCS34725_ADDR, strerror(errno));
        goto cleanup;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "TCS34725 init failed\n");
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open %s failed: %s\n", GPIO_CHIP, strerror(errno));
        goto cleanup;
    }
    led = gpiod_chip_get_line(chip, LED_LINE);
    if (!led) {
        fprintf(stderr, "gpiod get line %d failed: %s\n", LED_LINE, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(led, "tcs34725-led", 0) < 0) {
        fprintf(stderr, "gpiod request output failed: %s\n", strerror(errno));
        goto cleanup;
    }

