        printf("R:%5d  G:%5d  B:%5d  C:%5d\n", red, green, blue, clear);

        if (red > RED_THRESHOLD) {
            if (gpiod_line_set_value(led, 1) < 0) {
                fprintf(stderr, "LED set HIGH failed: %s\n", strerror(errno));
            }
        } else {
            if (gpiod_line_set_value(led, 0) < 0) {
                fprintf(stderr, "LED set LOW failed: %s\n", strerror(errno));
            }
        }

        usleep(200000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led) gpiod_line_release(led);
    if (chip) gpiod_chip_close(chip);
    if (fd >= 0) {
        i2c_write_reg(fd, TCS34725_ENABLE, 0x00);
        close(fd);
    }
    return ret;
}

