#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>

#define LED_COUNT 10
#define I2C_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES 0x10
#define BH1750_MEASUREMENT_DELAY_US 180000
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int i2c_handle) {
    char cmd = BH1750_CONTINUOUS_HIGH_RES;
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to write BH1750 command.\n");
        return -1;
    }
    gpioDelay(BH1750_MEASUREMENT_DELAY_US);

    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read BH1750 data.\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return (int)(raw / 1.2f);
}

static void set_led_brightness(int led_index, int brightness) {
    if (led_index < 0 || led_index >= LED_COUNT) return;
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;

    uint32_t color = ((uint32_t)brightness << 16) | ((uint32_t)brightness << 8) | brightness;

    gpioPulse_t pulse[4];
    pulse[0].gpioOn = (1 << 18);
    pulse[0].gpioOff = 0;
    pulse[0].usDelay = 8;

    pulse[1].gpioOn = 0;
    pulse[1].gpioOff = (1 << 18);
    pulse[1].usDelay = 4;

    pulse[2].gpioOn = (1 << 18);
    pulse[2].gpioOff = 0;
    pulse[2].usDelay = 8;

    pulse[3].gpioOn = 0;
    pulse[3].gpioOff = (1 << 18);
    pulse[3].usDelay = 4;

    uint32_t mask = 1u << led_index;
    uint32_t inverted_mask = ~mask;

    pulse[0].usDelay = (uint32_t)(8 + (color & mask) * 100);
    pulse[1].usDelay = (uint32_t)(4 + (color & mask) * 100);
    pulse[2].usDelay = (uint32_t)(8 + (color & mask) * 100);
    pulse[3].usDelay = (uint32_t)(4 + (color & mask) * 100);

    gpioWaveClear();
    gpioWaveAddGeneric(4, pulse);

    int wave_id = gpioWaveCreate();
    if (wave_id >= 0) {
        gpioWaveTxSend(wave_id, PI_WAVE_MODE_ONE_SHOT);
        while (gpioWaveTxBusy()) {
            gpioDelay(100);
        }
        gpioWaveDelete(wave_id);
    } else {
        fprintf(stderr, "Error: Failed to create wave for LED %d.\n", led_index);
    }
}

static int map_light_to_brightness(int light_level) {
    if (light_level <= 0) return 0;
    if (light_level >= 1000) return 255;

    float log_light = log10f((float)light_level);
    float log_max = log10f(1000.0f);
    float normalized = (log_light / log_max) * 255.0f;
    if (normalized > 255.0f) normalized = 255.0f;
    if (normalized < 0.0f) normalized = 0.0f;

    return (int)normalized;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_handle = i2cOpen(1, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X.\n", I2C_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int light_level = -1;
        int retries = 3;
        while (retries > 0 && light_level < 0) {
            light_level = read_bh1750(i2c_handle);
            if (light_level < 0) {
                fprintf(stderr, "Warning: BH1750 read failed, retrying...\n");
                gpioDelay(100000);
                retries--;
            }
        }

        if (light_level < 0) {
            fprintf(stderr, "Error: BH1750 read failed after multiple retries. Continuing with last valid value.\n");
        } else {
            int brightness = map_light_to_brightness(light_level);
            for (int i = 0; i < LED_COUNT; i++) {
                set_led_brightness(i, brightness);
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

