#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define BH1750_ADDR 0x23
#define I2C_DEV "/dev/i2c-1"
#define SPI_DEV "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define NUM_LEDS 10
#define LUX_MIN 10.0f
#define LUX_MAX 300.0f
#define BRIGHTNESS_MAX 31
#define BH1750_CMD_OT_HRES 0x20
#define BH1750_CONV_MS 120

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    if (i2c_write_cmd(fd, BH1750_CMD_OT_HRES) < 0) return -1;
    usleep(BH1750_CONV_MS * 1000);

    uint8_t buf[2];
    if (i2c_read_data(fd, buf, 2) < 0) return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int apa102_send(int spi_fd, uint8_t brightness) {
    if (brightness > BRIGHTNESS_MAX) brightness = BRIGHTNESS_MAX;

    size_t frame_len = 4 + (NUM_LEDS * 4) + 4;
    uint8_t *frame = malloc(frame_len);
    if (!frame) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    memset(frame, 0x00, 4);
    for (int i = 0; i < NUM_LEDS; i++) {
        frame[4 + i * 4] = 0xE0 | (brightness & 0x1F);
        frame[4 + i * 4 + 1] = 0x00;
        frame[4 + i * 4 + 2] = 0x00;
        frame[4 + i * 4 + 3] = 0xFF;
    }
    memset(frame + 4 + NUM_LEDS * 4, 0xFF, 4);

    if (spi_transfer(spi_fd, frame, frame, frame_len) < 0) {
        free(frame);
        return -1;
    }
    free(frame);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    int spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEV, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    uint8_t spi_mode = SPI_MODE_0;
    uint8_t spi_bits = 8;
    uint32_t spi_speed = SPI_SPEED_HZ;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("BH1750 + APA102 control started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            usleep(100000);
            continue;
        }

        if (lux < LUX_MIN) lux = LUX_MIN;
        if (lux > LUX_MAX) lux = LUX_MAX;

        int brightness = (int)((lux - LUX_MIN) * BRIGHTNESS_MAX / (LUX_MAX - LUX_MIN));

        if (apa102_send(spi_fd, brightness) < 0) {
            fprintf(stderr, "Failed to send APA102 frame\n");
        }

        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        usleep(50000);
    }

cleanup:
    printf("\nShutting down...\n");
    apa102_send(spi_fd, 0);
    close(spi_fd);
    close(i2c_fd);
    return 0;
}

