#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_SENSORS 3
#define I2C_BUS 1
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define BH1750_ONE_TIME_HIGH_RES_MODE2 0x21
#define APA102_SPI_CHANNEL 0
#define APA102_SPI_SPEED 1000000
#define APA102_LED_COUNT 10
#define FADE_DURATION_MS 500
#define LOOP_DELAY_MS 100
#define CONVERSION_DELAY_MS 180

static volatile sig_atomic_t running = 1;
static int i2c_handles[NUM_SENSORS];
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_bh1750(int handle) {
    if (i2cWriteByte(handle, BH1750_ONE_TIME_HIGH_RES_MODE2) < 0) {
        fprintf(stderr, "Error: Failed to write to BH1750 (handle %d)\n", handle);
        return -1;
    }
    return 0;
}

static int read_bh1750(int handle, float *lux_out) {
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read from BH1750 (handle %d)\n", handle);
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int init_apa102(void) {
    spi_handle = spiOpen(APA102_SPI_CHANNEL, APA102_SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Failed to open SPI channel %d\n", APA102_SPI_CHANNEL);
        return -1;
    }
    return 0;
}

static void apa102_set_brightness(uint8_t brightness) {
    uint8_t frame[4 + APA102_LED_COUNT * 4];
    frame[0] = 0xE0 | ((APA102_LED_COUNT & 0x07) << 4);
    for (int i = 0; i < APA102_LED_COUNT; i++) {
        frame[1 + i * 4] = 0xFF;
        frame[2 + i * 4] = 0x00;
        frame[3 + i * 4] = 0x00;
        frame[4 + i * 4] = brightness;
    }
    if (spiWrite(spi_handle, (char *)frame, sizeof(frame)) < 0) {
        fprintf(stderr, "Error: Failed to write to APA102 strip\n");
    }
}

static void fade_apa102(uint8_t target_brightness) {
    uint8_t current_brightness = 0;
    uint32_t fade_step_us = FADE_DURATION_MS * 1000 / 32;
    uint32_t elapsed = 0;
    while (running && elapsed < FADE_DURATION_MS) {
        if (current_brightness < target_brightness) {
            current_brightness += 1;
        } else {
            current_brightness -= 1;
        }
        apa102_set_brightness(current_brightness);
        gpioDelay(fade_step_us);
        elapsed += fade_step_us / 1000;
    }
}

static float calculate_average_lux(void) {
    float total_lux = 0.0f;
    int valid_count = 0;
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
            float lux;
            if (read_bh1750(i2c_handles[i], &lux) == 0) {
                total_lux += lux;
                valid_count++;
            } else {
                fprintf(stderr, "Warning: Sensor %d not reading correctly, skipping\n", i);
            }
        } else {
            fprintf(stderr, "Warning: Sensor %d not initialized, skipping\n", i);
        }
    }
    return (valid_count > 0) ? (total_lux / valid_count) : 0.0f;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        apa102_set_brightness(0x00);
        spiClose(spi_handle);
        spi_handle = -1;
    }
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
            i2c_handles[i] = -1;
        }
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = i2cOpen(I2C_BUS, BH1750_ADDR_LOW, 0);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Warning: Could not open I2C device at 0x%02X, trying 0x%02X\n",
                    BH1750_ADDR_LOW, BH1750_ADDR_HIGH);
            i2c_handles[i] = i2cOpen(I2C_BUS, BH1750_ADDR_HIGH, 0);
            if (i2c_handles[i] < 0) {
                fprintf(stderr, "Error: Could not open any BH1750 sensor at address 0x%02X or 0x%02X\n",
                        BH1750_ADDR_LOW, BH1750_ADDR_HIGH);
                cleanup();
                return 1;
            }
        }
        if (init_bh1750(i2c_handles[i]) < 0) {
            fprintf(stderr, "Error: BH1750 initialization failed at address 0x%02X\n",
                    i2c_handles[i] < 0 ? BH1750_ADDR_LOW : BH1750_ADDR_HIGH);
            cleanup();
            return 1;
        }
        gpioDelay(CONVERSION_DELAY_MS * 1000);
    }

    if (init_apa102() < 0) {
        cleanup();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        float avg_lux = calculate_average_lux();
        uint8_t brightness = (uint8_t)(avg_lux * 31.0f / 65535.0f);
        if (brightness > 31) brightness = 31;
        if (brightness < 0) brightness = 0;
        fade_apa102(brightness);
        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

