                fprintf(stderr, "Error: Could not open any BH1750 sensor at address 0x%02X or 0x%02X\n",
                        BH1750_ADDR_LOW, BH1750_ADDR_HIGH);
                cleanup();
                return 1;
            }
        }
        if (init_bh1750(i2c_handles[i]) < 0) {
            fprintf(stderr, "Error: BH1750 initialization failed at address 0x%02X\n",
                    i2c_handles[i] < 0 ? BH1750_ADDR_LOW : BH1750_ADDR_HIGH);
            cleanup();
            return 1;
        }
        gpioDelay(CONVERSION_DELAY_MS * 1000);
    }

    if (init_apa102() < 0) {
        cleanup();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        float avg_lux = calculate_average_lux();
        uint8_t brightness = (uint8_t)(avg_lux * 31.0f / 65535.0f);
        if (brightness > 31) brightness = 31;
        if (brightness < 0) brightness = 0;
        fade_apa102(brightness);
        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

