#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <math.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x10
#define VEML7700_CONFIG_REG 0x00
#define VEML7700_ALS_DATA_REG 0x04
#define WS2812B_GPIO_LINE 18
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3] = {reg, (uint8_t)(value >> 8), (uint8_t)(value & 0xFF)};
    if (write(fd, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int init_veml7700(int fd) {
    uint16_t config = 0x0000;
    if (i2c_write_reg16(fd, VEML7700_CONFIG_REG, config) < 0) {
        return -1;
    }
    return 0;
}

int read_veml7700_lux(int fd, float *lux) {
    uint16_t raw;
    if (i2c_read_reg16(fd, VEML7700_ALS_DATA_REG, &raw) < 0) {
        return -1;
    }
    *lux = (float)raw * 0.0288f;
    return 0;
}

void set_led_brightness(int brightness) {
    if (led_line) {
        gpiod_line_set_value(led_line, brightness > 0 ? 1 : 0);
    }
}

void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_veml7700(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize VEML7700: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, WS2812B_GPIO_LINE);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", WS2812B_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "ws2812b", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float lux = 0.0f;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !success) {
            if (read_veml7700_lux(i2c_fd, &lux) == 0) {
                success = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "I2C read error (attempt %d/%d): %s\n", retries, MAX_RETRIES, strerror(errno));
                    usleep(RETRY_DELAY_MS * 1000);
                }
            }
        }

        if (!success) {
            fprintf(stderr, "Failed to read lux after %d retries, using last valid value or 0\n", MAX_RETRIES);
            lux = 0.0f;
        }

        float gamma = 1.0f / 2.2f;
        float brightness = powf(lux / 120000.0f, gamma);
        if (brightness > 255.0f) brightness = 255.0f;
        if (brightness < 0.0f) brightness = 0.0f;

        int b = (int)brightness;
        set_led_brightness(b);

        printf("Lux: %.2f, Brightness: %d\n", lux, b);
        usleep(LOOP_DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

