#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18
#define CONSUMER "flame_sensor"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

static void error_handler(const char *message) {
    fprintf(stderr, "Error: %s (errno: %d - %s)\n", message, errno, strerror(errno));
    log_event(message);
}

static void self_test(struct gpiod_line *led_line, struct gpiod_line *buzzer_line) {
    log_event("Starting self-test...");
    if (gpiod_line_set_value(led_line, 1) < 0) {
        error_handler("Failed to set LED high during self-test");
        return;
    }
    usleep(500000);
    if (gpiod_line_set_value(led_line, 0) < 0) {
        error_handler("Failed to set LED low during self-test");
        return;
    }
    usleep(500000);

    int fault_count = 0;
    for (int i = 0; i < 5; i++) {
        int val = gpiod_line_get_value(led_line);
        if (val < 0) {
            error_handler("Failed to read LED during self-test");
            return;
        }
        if (val == 0) {
            fault_count++;
        }
        usleep(100000);
    }

    if (fault_count == 5) {
        log_event("Self-test failed: sensor fault detected");
        gpiod_line_set_value(buzzer_line, 1);
        usleep(200000);
        gpiod_line_set_value(buzzer_line, 0);
        usleep(200000);
        gpiod_line_set_value(buzzer_line, 1);
        usleep(600000);
        gpiod_line_set_value(buzzer_line, 0);
        usleep(200000);
        exit(1);
    } else {
        log_event("Self-test passed");
    }
}

static void error_exit(const char *message) {
    log_event(message);
    gpiod_line_set_value(LED_PIN, 1);
    usleep(200000);
    gpiod_line_set_value(LED_PIN, 0);
    usleep(200000);
    gpiod_line_set_value(BUZZER_PIN, 1);
    usleep(200000);
    gpiod_line_set_value(BUZZER_PIN, 0);
    usleep(200000);
    gpiod_line_set_value(BUZZER_PIN, 1);
    usleep(600000);
    gpiod_line_set_value(BUZZER_PIN, 0);
    usleep(200000);
    exit(1);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = 1;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        error_handler("Failed to open gpiochip4");
        return 1;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!flame_line || !buzzer_line || !led_line) {
        error_handler("Failed to get GPIO lines");
        goto cleanup;
    }

    if (gpiod_line_request_input(flame_line, CONSUMER) < 0) {
        error_handler("Failed to request flame sensor line as input");
        goto cleanup;
    }
    if (gpiod_line_request_output(buzzer_line, CONSUMER, 0) < 0) {
        error_handler("Failed to request buzzer line as output");
        goto cleanup;
    }
    if (gpiod_line_request_output(led_line, CONSUMER, 0) < 0) {
        error_handler("Failed to request LED line as output");
        goto cleanup;
    }

    self_test(led_line, buzzer_line);

    log_event("Flame sensor monitoring started");

    while (running) {
        int val = gpiod_line_get_value(flame_line);
        if (val < 0) {
            error_handler("Failed to read flame sensor");
            break;
        }

        if (val == 0) {
            log_event("Flame detected!");
            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                error_handler("Failed to activate buzzer");
                break;
            }
            if (gpiod_line_set_value(led_line, 1) < 0) {
                error_handler("Failed to activate LED");
                break;
            }
            while (running) {
                val = gpiod_line_get_value(flame_line);
                if (val < 0) {
                    error_handler("Failed to read flame sensor during alert");
                    break;
                }
                if (val == 1) {
                    break;
                }
                usleep(50000);
            }
            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                error_handler("Failed to deactivate buzzer");
                break;
            }
            if (gpiod_line_set_value(led_line, 0) < 0) {
                error_handler("Failed to deactivate LED");
                break;
            }
        } else {
            usleep(50000);
        }
    }

    log_event("Shutting down");
    ret = 0;

cleanup:
    if (flame_line) gpiod_line_release(flame_line);
    if (buzzer_line) gpiod_line_release(buzzer_line);
    if (led_line) gpiod_line_release(led_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

