#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BH1750_ADDR             0x23
#define BH1750_CONT_HIGH_RES    0x10
#define I2C_BUS                 "/dev/i2c-1"
#define GPIO_CHIP               "/sys/class/gpio/gpiochip4"
#define LED_PIN                 17
#define BUFFER_SIZE             60
#define SAMPLE_INTERVAL_SEC     1
#define MIN_LUX                 0.5
#define MAX_LUX                 5.0
#define MAX_AVG_LUX             1000.0
#define BLINK_PERIOD_MIN_SEC    0.5
#define BLINK_PERIOD_MAX_SEC    2.5

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int write_sysfs(const char *path, const char *value) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }
    ssize_t n = write(fd, value, strlen(value));
    close(fd);
    if (n < 0) {
        fprintf(stderr, "write(%s, %s): %s\n", path, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sysfs(const char *path, char *buf, size_t len) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len - 1);
    close(fd);
    if (n < 0) {
        fprintf(stderr, "read(%s): %s\n", path, strerror(errno));
        return -1;
    }
    buf[n] = '\0';
    return 0;
}

static int init_gpio(void) {
    char path[128];
    char val[16];
    snprintf(path, sizeof(path), GPIO_CHIP "/export");
    if (write_sysfs(path, "gpiochip4") < 0) return -1;
    usleep(100000);
    snprintf(path, sizeof(path), GPIO_CHIP "/gpio%d/direction", LED_PIN);
    if (write_sysfs(path, "out") < 0) return -1;
    snprintf(path, sizeof(path), GPIO_CHIP "/gpio%d/value", LED_PIN);
    if (write_sysfs(path, "0") < 0) return -1;
    return 0;
}

static void set_led(int on) {
    char path[128];
    char val[16];
    snprintf(path, sizeof(path), GPIO_CHIP "/gpio%d/value", LED_PIN);
    snprintf(val, sizeof(val), "%d", on ? 1 : 0);
    write_sysfs(path, val);
}

static int init_i2c(int *fd_out) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", BH1750_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    uint8_t cmd = BH1750_CONT_HIGH_RES;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "BH1750 init write: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    usleep(180000);
    *fd_out = fd;
    return 0;
}

static int read_bh1750(int fd, float *lux_out) {
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "BH1750 read: %s\n", n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void update_buffer(float lux, float buf[BUFFER_SIZE], int *idx) {
    buf[*idx] = lux;
    *idx = (*idx + 1) % BUFFER_SIZE;
}

static float calc_average(const float buf[BUFFER_SIZE]) {
    float sum = 0.0f;
    for (int i = 0; i < BUFFER_SIZE; i++) sum += buf[i];
    return sum / BUFFER_SIZE;
}

static float calc_blink_rate(float avg_lux) {
    float rate = MIN_LUX + (avg_lux / MAX_AVG_LUX) * (MAX_LUX - MIN_LUX);
    if (rate < MIN_LUX) rate = MIN_LUX;
    if (rate > MAX_LUX) rate = MAX_LUX;
    return rate;
}

static void sleep_sec(float sec) {
    struct timespec ts = { .tv_sec = (time_t)sec, .tv_nsec = 0 };
    nanosleep(&ts, NULL);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO init failed\n");
        return 1;
    }

    int i2c_fd = -1;
    if (init_i2c(&i2c_fd) < 0) {
        fprintf(stderr, "I2C init failed\n");
        set_led(0);
        unlink(GPIO_CHIP "/gpio17");
        return 1;
    }

    float lux_buf[BUFFER_SIZE];
    int buf_idx = 0;
    int led_on = 0;
    float avg_lux;
    float blink_rate;
    struct timespec blink_ts;
    blink_ts.tv_sec = 0;
    blink_ts.tv_nsec = 0;

    while (g_running) {
        float lux;
        if (read_bh1750(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error, retrying next cycle\n");
            sleep_sec(SAMPLE_INTERVAL_SEC);
            continue;
        }
        update_buffer(lux, lux_buf, &buf_idx);
        avg_lux = calc_average(lux_buf);
        blink_rate = calc_blink_rate(avg_lux);
        if (avg_lux > 0) {
            float period = 1.0f / blink_rate;
            if (period > BLINK_PERIOD_MAX_SEC) period = BLINK_PERIOD_MAX_SEC;
            if (period < BLINK_PERIOD_MIN_SEC) period = BLINK_PERIOD_MIN_SEC;
            blink_ts.tv_sec = period;
            blink_ts.tv_nsec = 0;
        } else {
            blink_ts.tv_sec = 0;
            blink_ts.tv_nsec = 0;
        }

        if (led_on) {
            if (blink_ts.tv_sec <= 0) {
                set_led(0);
                led_on = 0;
            } else {
                blink_ts.tv_sec -= 1.0f;
                if (blink_ts.tv_sec <= 0) {
                    set_led(0);
                    led_on = 0;
                }
            }
        } else {
            if (blink_ts.tv_sec <= 0) {
                set_led(1);
                led_on = 1;
            } else {
                blink_ts.tv_sec -= 1.0f;
                if (blink_ts.tv_sec <= 0) {
                    set_led(1);
                    led_on = 1;
                }
            }
        }

        printf("Lux: %.2f, Avg: %.2f, Rate: %.2f Hz\n", lux, avg_lux, blink_rate);
        sleep_sec(SAMPLE_INTERVAL_SEC);
    }

    set_led(0);
    if (i2c_fd >= 0) close(i2c_fd);
    unlink(GPIO_CHIP "/gpio17");
    printf("\nExiting cleanly.\n");
    return 0;
}

