#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27
#define CHIP_NAME "gpiochip0"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *data_line = NULL;
static struct gpiod_line *clock_line = NULL;
static struct gpiod_line *latch_line = NULL;

static volatile int keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

void cleanup(void) {
    if (data_line) gpiod_line_release(data_line);
    if (clock_line) gpiod_line_release(clock_line);
    if (latch_line) gpiod_line_release(latch_line);
    if (chip) gpiod_chip_close(chip);
}

void shift_out(unsigned char data) {
    for (int i = 0; i < 8; i++) {
        int bit = (data >> (7 - i)) & 1;
        if (gpiod_line_set_value(data_line, bit) < 0) {
            perror("Failed to set data line");
            return;
        }
        if (gpiod_line_set_value(clock_line, 1) < 0) {
            perror("Failed to set clock high");
            return;
        }
        usleep(1);
        if (gpiod_line_set_value(clock_line, 0) < 0) {
            perror("Failed to set clock low");
            return;
        }
        usleep(1);
    }
}

void display_digit_5(void) {
    unsigned char pattern[] = {
        0b00111111, 0b00000110, 0b01011011, 0b01001111,
        0b01100110, 0b01101101, 0b01111101, 0b00000111
    };
    for (int i = 0; i < 8 && keep_running; i++) {
        shift_out(pattern[i]);
        gpiod_line_set_value(latch_line, 1);
        usleep(1);
        gpiod_line_set_value(latch_line, 0);
        usleep(1);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        return 1;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);
    if (!data_line || !clock_line || !latch_line) {
        perror("Failed to get GPIO lines");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(data_line, "seven_seg", 0) < 0 ||
        gpiod_line_request_output(clock_line, "seven_seg", 0) < 0 ||
        gpiod_line_request_output(latch_line, "seven_seg", 0) < 0) {
        perror("Failed to request GPIO lines as output");
        cleanup();
        return 1;
    }

    while (keep_running) {
        display_digit_5();
        usleep(500000);
        if (!keep_running) break;
        usleep(500000);
    }

    cleanup();
    return 0;
}

