#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_PIN 5
#define DELAY_MS 750

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);

    while (running) {
        gpioWrite(LED_PIN, 1);
        printf("LED ON\n");
        fflush(stdout);
        time_sleep(DELAY_MS / 1000.0);

        gpioWrite(LED_PIN, 0);
        printf("LED OFF\n");
        fflush(stdout);
        time_sleep(DELAY_MS / 1000.0);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

