#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18
#define PWM_PERIOD_MS 10
#define PWM_STEPS 100
#define STEP_DELAY_NS (PWM_PERIOD_MS * 1000000L)

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *red_line = NULL;
static struct gpiod_line *green_line = NULL;
static struct gpiod_line *blue_line = NULL;
static volatile sig_atomic_t keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

void release_resources(void) {
    if (red_line) {
        gpiod_line_release(red_line);
        red_line = NULL;
    }
    if (green_line) {
        gpiod_line_release(green_line);
        green_line = NULL;
    }
    if (blue_line) {
        gpiod_line_release(blue_line);
        blue_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    srand((unsigned int)time(NULL));

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return 1;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    if (!red_line) {
        perror("gpiod_chip_get_line red");
        release_resources();
        return 1;
    }
    if (gpiod_line_request_output(red_line, "rgb-led", 0) < 0) {
        perror("gpiod_line_request_output red");
        release_resources();
        return 1;
    }

    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    if (!green_line) {
        perror("gpiod_chip_get_line green");
        release_resources();
        return 1;
    }
    if (gpiod_line_request_output(green_line, "rgb-led", 0) < 0) {
        perror("gpiod_line_request_output green");
        release_resources();
        return 1;
    }

    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!blue_line) {
        perror("gpiod_chip_get_line blue");
        release_resources();
        return 1;
    }
    if (gpiod_line_request_output(blue_line, "rgb-led", 0) < 0) {
        perror("gpiod_line_request_output blue");
        release_resources();
        return 1;
    }

    struct timespec delay = {0, STEP_DELAY_NS};

    while (keep_running) {
        int red_val = rand() % (PWM_STEPS + 1);
        int green_val = rand() % (PWM_STEPS + 1);
        int blue_val = rand() % (PWM_STEPS + 1);

        for (int i = 0; i < PWM_STEPS; i++) {
            if (!keep_running) break;
            int red_on = (i < red_val) ? 1 : 0;
            int green_on = (i < green_val) ? 1 : 0;
            int blue_on = (i < blue_val) ? 1 : 0;

            if (gpiod_line_set_value(red_line, red_on) < 0) {
                perror("gpiod_line_set_value red");
                release_resources();
                return 1;
            }
            if (gpiod_line_set_value(green_line, green_on) < 0) {
                perror("gpiod_line_set_value green");
                release_resources();
                return 1;
            }
            if (gpiod_line_set_value(blue_line, blue_on) < 0) {
                perror("gpiod_line_set_value blue");
                release_resources();
                return 1;
            }
            nanosleep(&delay, NULL);
        }
    }

    release_resources();
    return 0;
}

