#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define MODE_REG 0x0D
#define MODE_NORMAL 0x01
#define ALS_LSB_REG 0x64
#define ALS_MSB_REG 0x65
#define RED_REG 0x66
#define GREEN_REG 0x68
#define BLUE_REG 0x6A
#define LED_GPIO 18
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define SAMPLE_INTERVAL_US 500000
#define RETRY_DELAY_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_reg16(uint8_t reg, uint16_t *out) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error setting reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)(uint8_t)data[1] << 8) | (uint8_t)data[0];
    return 0;
}

static int init_adpd188bi(void) {
    if (write_reg(MODE_REG, MODE_NORMAL) != 0) {
        fprintf(stderr, "Failed to set ADPD188BI to normal mode\n");
        return -1;
    }
    return 0;
}

static int read_als(uint16_t *als) {
    return read_reg16(ALS_LSB_REG, als);
}

static int read_rgb(uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (read_reg16(RED_REG, red) != 0) return -1;
    if (read_reg16(GREEN_REG, green) != 0) return -1;
    if (read_reg16(BLUE_REG, blue) != 0) return -1;
    return 0;
}

static int map_als_to_brightness(uint16_t als) {
    int brightness = (int)((uint32_t)als * PWM_RANGE / 65535);
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    return brightness;
}

static void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %s\n", ADPD188BI_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (init_adpd188bi() != 0) {
        fprintf(stderr, "ADPD188BI initialization failed\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_GPIO);
        cleanup();
        return 1;
    }
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);
    gpioPWM(LED_GPIO, 0);

    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Smart Lighting System started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t als = 0, red = 0, green = 0, blue = 0;
        int als_ok = read_als(&als);
        int rgb_ok = read_rgb(&red, &green, &blue);

        if (als_ok == 0 && rgb_ok == 0) {
            int brightness = map_als_to_brightness(als);
            gpioPWM(LED_GPIO, brightness);
            log_data(als, red, green, blue);
        } else {
            fprintf(stderr, "Sensor read error, retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

