#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* FXOS8700CQ I2C address (SA0 tied to VDD -> 0x1F) */
#define FXOS8700_ADDR 0x1F

/* FXOS8700CQ register addresses */
#define FXOS8700_REG_STATUS 0x00
#define FXOS8700_REG_OUT_X_MSB 0x01
#define FXOS8700_REG_WHO_AM_I 0x0D
#define FXOS8700_REG_XYZ_DATA_CFG 0x0E
#define FXOS8700_REG_CTRL_REG1 0x2A

/* Expected WHO_AM_I value for FXOS8700CQ */
#define FXOS8700_WHO_AM_I_EXPECTED 0xC7

/* Impact threshold: 2g acceleration in m/s^2 (19.62 m/s^2) */
#define IMPACT_THRESHOLD 19.62

/* Sampling interval in microseconds (50 ms) */
#define SAMPLE_INTERVAL_US 50000

/* Global I2C handle for signal handler */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl+C)                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an FXOS8700CQ register                       */
/* ------------------------------------------------------------------ */
static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an FXOS8700CQ register                        */
/* ------------------------------------------------------------------ */
static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration data (6 bytes from OUT_X_MSB)                      */
/* Data is 14-bit left-justified; shift right by 2, then scale by 4096 */
/* counts/g for ±2g range.  9.81 m/s^2 per g.                       */
/* ------------------------------------------------------------------ */
static int read_acceleration(int handle, float *x, float *y, float *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(handle, FXOS8700_REG_OUT_X_MSB, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading acceleration data: expected 6 bytes, got %d\n", result);
        return -1;
    }

    int16_t raw_x = (int16_t)(((uint16_t)buffer[0] << 8) | (uint8_t)buffer[1]) >> 2;
    int16_t raw_y = (int16_t)(((uint16_t)buffer[2] << 8) | (uint8_t)buffer[3]) >> 2;
    int16_t raw_z = (int16_t)(((uint16_t)buffer[4] << 8) | (uint8_t)buffer[5]) >> 2;

    /* ±2g range: 4096 counts/g */
    *x = (float)raw_x / 4096.0f * 9.81f;
    *y = (float)raw_y / 4096.0f * 9.81f;
    *z = (float)raw_z / 4096.0f * 9.81f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log an impact event to file                                         */
/* ------------------------------------------------------------------ */
static void log_impact(float x, float y, float z, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening impact_log.txt for writing\n");
        return;
    }

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Initialize the FXOS8700CQ sensor                                    */
/* ------------------------------------------------------------------ */
static int initialize_sensor(int handle) {
    uint8_t who_am_i = 0;

    /* Verify sensor identity */
    if (read_register(handle, FXOS8700_REG_WHO_AM_I, &who_am_i) < 0) {
        return -1;
    }
    if (who_am_i != FXOS8700_WHO_AM_I_EXPECTED) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n",
