    if (write_register(handle, FXOS8700_REG_CTRL_REG1, 0x01) < 0) {
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void) {
