    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at FXOS8700CQ address */
    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
