#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define GYRO_ADDR      0x69
#define WHO_AM_I       0x0F
#define WHO_AM_I_VAL   0xD3
#define CTRL_REG1      0x20
#define CTRL_REG4      0x23
#define OUT_X_L        0x28
#define SENSITIVITY    0.00875f
#define ALERT_THRESHOLD 50.0f
#define LOG_FILE       "gyro_log.txt"
#define SAMPLE_PERIOD_US 50000
#define CALIB_SAMPLES  100

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int gyro_init(int fd) {
    uint8_t who;
    if (i2c_read_block(fd, WHO_AM_I, &who, 1) < 0) return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg(fd, CTRL_REG1, 0x0F) < 0) return -1;
    if (i2c_write_reg(fd, CTRL_REG4, 0x00) < 0) return -1;
    return 0;
}

static int gyro_read(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_L, buf, 6) < 0) return -1;
    int16_t rx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t ry = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t rz = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)rx * SENSITIVITY;
    *y = (float)ry * SENSITIVITY;
    *z = (float)rz * SENSITIVITY;
    return 0;
}

static int gyro_calibrate(int fd, float *x_off, float *y_off, float *z_off) {
    float x_sum = 0, y_sum = 0, z_sum = 0;
    for (int i = 0; i < CALIB_SAMPLES; i++) {
        float x, y, z;
        if (gyro_read(fd, &x, &y, &z) < 0) return -1;
        x_sum += x; y_sum += y; z_sum += z;
        usleep(1000);
    }
    *x_off = x_sum / CALIB_SAMPLES;
    *y_off = y_sum / CALIB_SAMPLES;
    *z_off = z_sum / CALIB_SAMPLES;
    printf("Calibration offsets: X=%.3f, Y=%.3f, Z=%.3f\n", *x_off, *y_off, *z_off);
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", GYRO_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }
    if (gyro_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Gyroscope initialization failed.\n");
        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }
    fprintf(g_log_fp, "# timestamp,x_dps,y_dps,z_dps\n");

    float x_off = 0, y_off = 0, z_off = 0;
    if (gyro_calibrate(g_i2c_fd, &x_off, &y_off, &z_off) < 0) {
        fprintf(stderr, "Calibration failed.\n");
        fclose(g_log_fp);
        close(g_i2c_fd);
        return 1;
    }

    printf("Logging gyro data to %s (Ctrl+C to stop)\n", LOG_FILE);
    while (g_running) {
        float x, y, z;
        if (gyro_read(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        x -= x_off; y -= y_off; z -= z_off;
        log_data(g_log_fp, x, y, z);
        if (x > ALERT_THRESHOLD || y > ALERT_THRESHOLD || z > ALERT_THRESHOLD) {
            fprintf(stderr, "ALERT: X=%.2f, Y=%.2f, Z=%.2f\n", x, y, z);
            fprintf(g_log_fp, "ALERT: X=%.2f, Y=%.2f, Z=%.2f\n", x, y, z);
            fflush(g_log_fp);
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

