                reg, value, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an ADXL345 register                              */
/* ------------------------------------------------------------------ */
static int adxl345_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the ADXL345: verify device ID, configure range & rate    */
/* ------------------------------------------------------------------ */
static int adxl345_init(int handle)
{
    uint8_t devid = 0;

    /* Read DEVID to confirm sensor is present and responding */
    if (adxl345_read_reg(handle, ADXL345_DEVID, &devid) < 0) {
        return -1;
    }
    if (devid != ADXL345_DEVID_VAL) {
        fprintf(stderr, "ADXL345 not detected (DEVID=0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID_VAL);
        return -1;
    }

    /* Standby mode so configuration changes take effect */
    if (adxl345_write_reg(handle, ADXL345_POWER_CTL, 0x00) < 0)
        return -1;

    /* Full-resolution mode (0x08) | ±2g range (0x08) -> 0x08 */
    if (adxl345_write_reg(handle, ADXL345_RANGE, 0x08) < 0)
        return -1;

    /* Bandwidth rate: 100 Hz (0x0A) */
    if (adxl345_write_reg(handle, ADXL345_BW_RATE, 0x0A) < 0)
        return -1;

    /* Measure mode (0x08) */
    if (adxl345_write_reg(handle, ADXL345_POWER_CTL, 0x08) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration (g units) from the ADXL345                       */
/* ------------------------------------------------------------------ */
static int adxl345_read_acceleration(int handle, float *x, float *y, float *z)
{
    char raw[6];
    int16_t x_raw, y_raw, z_raw;

    /* Burst read 6 bytes starting at DATAX0 (0x32) */
    int rc = i2cReadI2CBlockData(handle, ADXL345_DATAX0, raw, 6);
    if (rc != 6) {
        fprintf(stderr, "I2C block read failed: %s\n",
                rc < 0 ? pigpio_error(rc) : "short read");
        return -1;
    }

    x_raw = (int16_t)(((uint8_t)raw[1] << 8) | (uint8_t)raw[0]);
    y_raw = (int16_t)(((uint8_t)raw[3] << 8) | (uint8_t)raw[2]);
    z_raw = (int16_t)(((uint8_t)raw[5] << 8) | (uint8_t)raw[4]);

    /* Full-resolution mode: 4 mg/LSB → 0.004 g/LSB */
    *x = (float)x_raw * 0.004f;
    *y = (float)y_raw * 0.004f;
    *z = (float)z_raw * 0.004f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample to the CSV file                                      */
/* ------------------------------------------------------------------ */
static void log_sample(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure LED is off */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

