#define ACCEL_CTRL_REG1_A 0x20
#define ACCEL_OUT_X_L_A   0x28
#define ACCEL_OUT_X_H_A   0x29
#define ACCEL_OUT_Y_L_A   0x2A
#define ACCEL_OUT_Y_H_A   0x2B
#define ACCEL_OUT_Z_L_A   0x2C
#define ACCEL_OUT_Z_H_A   0x2D

#define MAG_MR_REG_M 0x02
#define MAG_OUT_X_H_M 0x03
#define MAG_OUT_X_L_M 0x04
#define MAG_OUT_Y_H_M 0x05
#define MAG_OUT_Y_L_M 0x06
#define MAG_OUT_Z_H_M 0x07
#define MAG_OUT_Z_L_M 0x08

#define ACCEL_SENSITIVITY 0.000061f
#define MAG_SENSITIVITY  0.00014f

static volatile sig_atomic_t running = 1;
static int accel_handle = -1;
static int mag_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_accelerometer(void) {
    accel_handle = i2cOpen(1, ACCEL_ADDR, 0);
    if (accel_handle < 0) {
        fprintf(stderr, "Error opening accelerometer I2C: %d\n", accel_handle);
        return -1;
    }
    if (i2cWriteByteData(accel_handle, ACCEL_CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to accelerometer CTRL_REG1_A\n");
        i2cClose(accel_handle);
        accel_handle = -1;
        return -1;
    }
    return 0;
}

static int init_magnetometer(void) {
    mag_handle = i2cOpen(1, MAG_ADDR, 0);
    if (mag_handle < 0) {
        fprintf(stderr, "Error opening magnetometer I2C: %d\n", mag_handle);
        return -1;
    }
    if (i2cWriteByteData(mag_handle, MAG_MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to magnetometer MR_REG_M\n");
        i2cClose(mag_handle);
        mag_handle = -1;
        return -1;
    }
    return 0;
}

static int read_accelerometer(float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(accel_handle, ACCEL_OUT_X_L_A | 0x80, buf, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | (uint8_t)buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | (uint8_t)buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | (uint8_t)buf[4]);
    *x = (float)raw_x * ACCEL_SENSITIVITY;
    *y = (float)raw_y * ACCEL_SENSITIVITY;
    *z = (float)raw_z * ACCEL_SENSITIVITY;
    return 0;
}

static int read_magnetometer(float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(mag_handle, MAG_OUT_X_H_M, buf, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    int16_t raw_z = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    int16_t raw_y = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);
    *x = (float)raw_x * MAG_SENSITIVITY;
    *y = (float)raw_y * MAG_SENSITIVITY;
    *z = (float)raw_z * MAG_SENSITIVITY;
    return 0;
}

static float calculate_heading(float ax, float ay, float az, float mx, float my, float mz) {
    float roll = atan2f(ay, az);
    float pitch = atan2f(-ax, sqrtf(ay * ay + az * az));
    float cos_roll = cosf(roll);
    float cos_pitch = cosf(pitch);
    float sin_roll = sinf(roll);
    float sin_pitch = sinf(pitch);
    float x_comp = mx * cos_pitch + mz * sin_pitch;
    float y_comp = mx * sin_roll * sin_pitch + my * cos_roll - mz * sin_roll * cos_pitch;
    float heading = atan2f(y_comp, x_comp) * 180.0f / M_PI;
    if (heading < 0) heading += 360.0f;
    return heading;
}

static int log_data(float heading, float ax, float ay, float az, float mx, float my, float mz) {
    FILE *fp = fopen("compass_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n", ts, heading, ax, ay, az, mx, my, mz);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (init_accelerometer() < 0 || init_magnetometer() < 0) {
        gpioTerminate();
        return 1;
    }
    FILE *fp = fopen("compass_log.txt", "r");
    int need_header = (fp == NULL);
    if (fp) fclose(fp);
    if (need_header) {
        fp = fopen("compass_log.txt", "w");
        if (fp) {
            fprintf(fp, "timestamp,heading_deg,ax_g,ay_g,az_g,mx_G,my_G,mz_G\n");
            fclose(fp);
        }
    }
    float ax, ay, az, mx, my, mz, heading;
    while (running) {
        if (read_accelerometer(&ax, &ay, &az) < 0 || read_magnetometer(&mx, &my, &mz) < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            gpioDelay(100000);
            continue;
        }
        heading = calculate_heading(ax, ay, az, mx, my, mz);
        if (log_data(heading, ax, ay, az, mx, my, mz) < 0) {
            fprintf(stderr, "Logging error\n");
        }
        gpioDelay(100000);
    }
    if (accel_handle >= 0) i2cClose(accel_handle);
    if (mag_handle >= 0) i2cClose(mag_handle);
    gpioTerminate();
    return 0;
}

