#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16488A Register Addresses */
#define X_GYRO_REG      0x04
#define Y_GYRO_REG      0x06
#define Z_GYRO_REG      0x08
#define X_ACCEL_REG     0x0A
#define Y_ACCEL_REG     0x0C
#define Z_ACCEL_REG     0x0E

/* Sensitivities */
#define GYRO_SENSITIVITY 0.005f   /* deg/sec/LSB */
#define ACCEL_SENSITIVITY 0.00025f /* g/LSB */

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000       /* 1 MHz */
#define SPI_FLAGS   0b11000000000 /* CPHA=1, CPOL=1, AUX_SPI_OFF */

#define SAMPLE_INTERVAL_US 100000  /* 100 ms */
#define STALL_US           40      /* >32 us stall between request and data */

static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup — close SPI, file, terminate pigpio                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a single register from the ADIS16488A                        */
/* Returns 0 on success, -1 on SPI error.                             */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *value)
{
    char tx[2], rx[2];
    int  ret;

    /*
     * ADIS16488A read protocol: send a 16-bit word whose MSB is 0
     * and the lower 7 bits are the register address.
     * The requested register's data is returned on the *next* 16-bit
     * transfer, so we stall for >32 us between the request and data
     * transfers.
     */
    tx[0] = (char)(reg & 0x7F);
    tx[1] = 0x00;

    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X (ret=%d)\n",
                reg, ret);
        return -1;
    }

    gpioDelay(STALL_US);

    /* Data transfer: send 0x0000, receive 16-bit result */
    tx[0] = 0x00;
    tx[1] = 0x00;
    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X (ret=%d)\n",
                reg, ret);
        return -1;
    }

    *value = (int16_t)(((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all six sensor axes in one transaction                       */
/* Returns 0 on success, -1 on SPI error.                             */
/* ------------------------------------------------------------------ */
static int read_all_sensors(float *gx, float *gy, float *gz,
                            float *ax, float *ay, float *az)
{
    int16_t raw_gx, raw_gy, raw_gz, raw_ax, raw_ay, raw_az;

    if (read_register(X_GYRO_REG, &raw_gx) != 0) return -1;
    if (read_register(Y_GYRO_REG, &raw_gy) != 0) return -1;
    if (read_register(Z_GYRO_REG, &raw_gz) != 0) return -1;
    if (read_register(X_ACCEL_REG, &raw_ax) != 0) return -1;
    if (read_register(Y_ACCEL_REG, &raw_ay) != 0) return -1;
    if (read_register(Z_ACCEL_REG, &raw_az) != 0) return -1;

    *gx = (float)raw_gx * GYRO_SENSITIVITY;
    *gy = (float)raw_gy * GYRO_SENSITIVITY;
    *gz = (float)raw_gz * GYRO_SENSITIVITY;
    *ax = (float)raw_ax * ACCEL_SENSITIVITY;
    *ay = (float)raw_ay * ACCEL_SENSITIVITY;
    *az = (float)raw_az * ACCEL_SENSITIVITY;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample to the CSV file                                      */
/* ------------------------------------------------------------------ */
static void log_data(float gx, float gy, float gz,
                     float ax, float ay, float az)
{
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, ts.tv_nsec / 1000000,
            gx, gy, gz, ax, ay, az);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0 at 1 MHz, mode 3 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open CSV file for appending */
    fp = fopen("imu_data.csv", "a");
    if (fp == NULL) {
        perror("Error opening imu_data.csv");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
        fflush(fp);
    }

    /* Register cleanup and signal handlers */
    if (atexit(cleanup) != 0) {
        fprintf(stderr, "Warning: atexit registration failed\n");
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADIS16488A IMU logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (running) {
        float gx, gy, gz, ax, ay, az;

        if (read_all_sensors(&gx, &gy, &gz, &ax, &ay, &az) == 0) {
            log_data(gx, gy, gz, ax, ay, az);
        } else {
            fprintf(stderr, "Sensor read error — skipping sample\n");
        }

        /*
         * Non-blocking 100 ms delay: poll running flag every 10 ms.
         * This keeps the loop responsive to signals.
         */
        for (int i = 0; i < 10 && running; i++) {
            gpioDelay(10000); /* 10 ms */
        }
    }

    printf("\nShutting down cleanly...\n");
    return EXIT_SUCCESS;
}

