/*
 * ADIS16448 IMU reader for Raspberry Pi 4 Model B
 * SPI0, CS0 (GPIO8), SPI mode 3, up to 1 MHz.
 * libgpiod manages CS0; spidev handles the 16-bit SPI transfers.
 *
 * Build: gcc -O2 -Wall -o adis16448 adis16448.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#include <gpiod.h>

/* ---- ADIS16448 register map (single-register read protocol) ---- */
#define ADIS16448_REG_XGYRO_OUT  0x04
#define ADIS16448_REG_YGYRO_OUT  0x06
#define ADIS16448_REG_ZGYRO_OUT  0x08
#define ADIS16448_REG_XACCL_OUT  0x0A
#define ADIS16448_REG_YACCL_OUT  0x0C
#define ADIS16448_REG_ZACCL_OUT  0x0E

#define ADIS16448_REG_STATUS     0x00
#define ADIS16448_REG_SMPL_PRD   0x02

/* ---- SPI / libgpiod configuration ---- */
#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8
#define CS_CHIP_LINE    8          /* GPIO8 = SPI0 CE0 */

#define SAMPLE_PERIOD_MS 100

/* ---- Scale factors ---- */
