    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
    exit(0);
}

/*
 * Read a 16-bit register from the ADIS16448.
 * The ADIS16448 requires a two-cycle SPI read:
 *   1. Send the register address (16-bit, bit 15 = 1)
 *   2. Stall for >= 40 us, then send dummy 0x0000 to clock out data
 * Returns 0 on success, -1 on failure.
 */
static int read_register(uint8_t reg, int16_t *value) {
    char tx_cmd[2];
    char rx_cmd[2];
    char tx_dummy[2];
    char rx_dummy[2];
    int ret;

    /* Build command: 16-bit address, bit 15 = 1 */
    tx_cmd[0] = (char)(reg | 0x80);
    tx_cmd[1] = 0x00;

    /* First transfer: send read command */
    ret = spiXfer(spi_handle, tx_cmd, rx_cmd, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI command transfer failed for reg 0x%02X (ret=%d)\n", reg, ret);
        return -1;
    }

    /* Stall for >= 40 us (datasheet: min 40 us) */
    gpioDelay(50); /* 50 us is safe */

    /* Second transfer: dummy to clock out data */
    tx_dummy[0] = 0x00;
    tx_dummy[1] = 0x00;

    ret = spiXfer(spi_handle, tx_dummy, rx_dummy, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI data transfer failed for reg 0x%02X (ret=%d)\n", reg, ret);
        return -1;
    }

    /* Data is MSB first */
    *value = (int16_t)(((uint16_t)(uint8_t)rx_dummy[0] << 8) | (uint8_t)rx_dummy[1]);
    return 0;
}

int main(void) {
    int16_t gyro_x, gyro_y, gyro_z;
    int16_t accl_x, accl_y, accl_z;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (1 << 8) | SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    /* Set up signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("ADIS16448 IMU Reader (pigpio)\n");
    printf("Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s\n", 0.0f, 0.0f, 0.0f);
    printf("Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n", 0.0f, 0.0f, 0.0f);
    printf("Press Ctrl+C to exit.\n\n");

    while (1) {
        if (read_register(ADIS16448_XGYRO_OUT, &gyro_x) != 0) {
            fprintf(stderr, "Failed to read gyro X\n");
            break;
        }
        if (read_register(ADIS16448_YGYRO_OUT, &gyro_y) != 0) {
            fprintf(stderr, "Failed to read gyro Y\n");
            break;
        }
        if (read_register(ADIS16448_ZGYRO_OUT, &gyro_z) != 0) {
            fprintf(stderr, "Failed to read gyro Z\n");
            break;
        }
        if (read_register(ADIS16448_XACCL_OUT, &accl_x) != 0) {
            fprintf(stderr, "Failed to read accel X\n");
            break;
        }
        if (read_register(ADIS16448_YACCL_OUT, &accl_y) != 0) {
            fprintf(stderr, "Failed to read accel Y\n");
            break;
        }
        if (read_register(ADIS16448_ZACCL_OUT, &accl_z) != 0) {
            fprintf(stderr, "Failed to read accel Z\n");
            break;
        }

        /* Convert raw to physical units */
        float gyro_x_dps = (float)gyro_x * GYRO_SCALE;
        float gyro_y_dps = (float)gyro_y * GYRO_SCALE;
        float gyro_z_dps = (float)gyro_z * GYRO_SCALE;
        float accl_x_g = (float)accl_x * ACCL_SCALE;
        float accl_y_g = (float)accl_y * ACCL_SCALE;
        float accl_z_g = (float)accl_z * ACCL_SCALE;

        printf("Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s | "
               "Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n",
               gyro_x_dps, gyro_y_dps, gyro_z_dps,
               accl_x_g, accl_y_g, accl_z_g);

        gpioDelay(100000); /* 100 ms */
    }

    /* Clean up on error */
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return 1;
}

