#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6886_ADDR 0x68

#define MPU6886_WHO_AM_I 0x75
#define MPU6886_WHO_AM_I_VAL 0x86
#define MPU6886_PWR_MGMT_1 0x6B
#define MPU6886_ACCEL_CONFIG 0x1C
#define MPU6886_GYRO_CONFIG 0x1B
#define MPU6886_ACCEL_XOUT_H 0x3B
#define MPU6886_GYRO_XOUT_H 0x43

#define ACCEL_RANGE 2.0f
#define GYRO_RANGE 250.0f

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int mpu6886_init(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, MPU6886_WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Error reading WHO_AM_I: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != MPU6886_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: 0x%02X (expected 0x%02X)\n", who_am_i, MPU6886_WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_reg8(fd, MPU6886_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    usleep(100000);

    if (i2c_write_reg8(fd, MPU6886_ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing ACCEL_CONFIG: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, MPU6886_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing GYRO_CONFIG: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_raw_accel(int fd, int16_t *ax, int16_t *ay, int16_t *az) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, MPU6886_ACCEL_XOUT_H, buf, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer: %s\n", strerror(errno));
        return -1;
    }
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static int read_raw_gyro(int fd, int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, MPU6886_GYRO_XOUT_H, buf, 6) < 0) {
        fprintf(stderr, "Error reading gyroscope: %s\n", strerror(errno));
        return -1;
    }
    *gx = (int16_t)((buf[0] << 8) | buf[1]);
    *gy = (int16_t)((buf[2] << 8) | buf[3]);
    *gz = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6886_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (mpu6886_init(fd) < 0) {
        fprintf(stderr, "MPU-6886 initialization failed.\n");
        close(fd);
        return 1;
    }

    printf("MPU-6886 initialized. Reading accel/gyro data every 50ms (Ctrl+C to exit).\n");

    while (running) {
        int16_t ax, ay, az, gx, gy, gz;
        int retries = 3;
        int success = 0;

        while (retries > 0 && running) {
            if (read_raw_accel(fd, &ax, &ay, &az) == 0 &&
                read_raw_gyro(fd, &gx, &gy, &gz) == 0) {
                success = 1;
                break;
            }
            retries--;
            if (retries > 0) usleep(10000);
        }

        if (success) {
            printf("Accel: X=%6d, Y=%6d, Z=%6d  |  Gyro: X=%6d, Y=%6d, Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Failed to read sensor data after retries.\n");
        }

        usleep(50000);
    }

    printf("\nExiting gracefully...\n");
    close(fd);
    return 0;
}

