#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADXL345_ADDRESS 0x53
#define LED_PIN 17
#define IMPACT_THRESHOLD 2.5
#define POLL_DELAY_US 10000
#define LED_ON_DELAY_US 500000
#define SCALE_FACTOR 256.0

#define REG_DEVID 0x00
#define REG_POWER_CTL 0x2D
#define REG_DATA_FORMAT 0x31
#define REG_DATAX0 0x32
#define REG_BW_RATE 0x2C

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int init_adxl345(int handle) {
    uint8_t devid = 0;
    if (read_register(handle, REG_DEVID, &devid) != 0) return -1;
    if (devid != 0xE5) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0xE5)\n", devid);
        return -1;
    }

    if (write_register(handle, REG_BW_RATE, 0x0A) != 0) return -1;
    if (write_register(handle, REG_POWER_CTL, 0x08) != 0) return -1;
    if (write_register(handle, REG_DATA_FORMAT, 0x0B) != 0) return -1;

    return 0;
}

static int read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, REG_DATAX0, buf, 6) != 6) {
        fprintf(stderr, "I2C block read error\n");
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void log_impact(FILE *fp, float mag, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Magnitude: %.2f g, X: %d, Y: %d, Z: %d\n", ts, mag, x, y, z);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_adxl345(i2c_handle) != 0) {
        fprintf(stderr, "ADXL345 init failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    log_file = fopen("impact_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) != 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        float mag = sqrtf((float)x * x + (float)y * y + (float)z * z) / SCALE_FACTOR;
        if (mag > IMPACT_THRESHOLD) {
            gpioWrite(LED_PIN, 1);
            log_impact(log_file, mag, x, y, z);
            gpioDelay(LED_ON_DELAY_US);
            gpioWrite(LED_PIN, 0);
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

