#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG  0x1B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

/* Expected device ID */
#define ICM20602_WHO_AM_I 0x12

/* Sampling interval in microseconds (100 ms = 10 Hz) */
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read failed (reg=0x%02X, expected=%u, got=%d)\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

static int init_imu(int handle)
{
    uint8_t who_am_i = 0;

    if (read_block(handle, WHO_AM_I, &who_am_i, 1) != 0)
        return -1;

    if (who_am_i != ICM20602_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, ICM20602_WHO_AM_I);
        return -1;
    }

    /* Wake up the device (clear SLEEP bit) */
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Failed to wake ICM-20602\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms settling time */

    /* Configure accelerometer range (+/- 2g) */
    if (i2cWriteByteData(handle, ACCEL_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Failed to configure accelerometer\n");
        return -1;
    }

    /* Configure gyroscope range (+/- 250 dps) */
    if (i2cWriteByteData(handle, GYRO_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Failed to configure gyroscope\n");
        return -1;
    }

    return 0;
}

static int read_imu_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                         int16_t *gx, int16_t *gy, int16_t *gz)
{
    uint8_t buf[14];

    if (read_block(handle, ACCEL_XOUT_H, buf, sizeof(buf)) != 0)
        return -1;

    *ax = (int16_t)((buf[0]  << 8) | buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | buf[3]);
    *az = (int16_t)((buf[4]  << 8) | buf[5]);
    *gx = (int16_t)((buf[8]  << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
    *gz = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

