                     int16_t gx, int16_t gy, int16_t gz)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld,%d,%d,%d,%d,%d,%d\n",
            timestamp, ts.tv_nsec / 1000000,
            ax, ay, az, gx, gy, gz);
    fflush(fp);
}

int main(void)
{
    int16_t ax, ay, az, gx, gy, gz;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %d\n",
                ICM20602_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_imu(i2c_handle) != 0) {
        fprintf(stderr, "IMU initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        perror("Failed to open imu_log.csv");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,accel_x,accel_y,accel_z,gyro_x,gyro_y,gyro_z\n");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("IMU logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        if (read_imu_data(i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            log_data(log_file, ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Failed to read IMU data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

