#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define LSM6DSR_ADDR 0x6A
#define WHO_AM_I 0x0F
#define WHO_AM_I_VAL 0x6A
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_A 0x28
#define OUTX_H_A 0x29
#define OUTY_L_A 0x2A
#define OUTY_H_A 0x2B
#define OUTZ_L_A 0x2C
#define OUTZ_H_A 0x2D

#define ACCEL_SENSITIVITY 0.061f
#define GYRO_SENSITIVITY 8.75f

#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 2.5f
#define FALL_WINDOW_MS 1000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, val, rc);
        return -1;
    }
    return 0;
}

static int read_regs(uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, expected %u, got %d)\n", reg, len, rc);
        return -1;
    }
    return 0;
}

static int init_lsm6dsr(void) {
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %d\n", LSM6DSR_ADDR, i2c_handle);
        return -1;
    }

    int who = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "I2C read error on WHO_AM_I: %d\n", who);
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }

    if (write_reg(CTRL1_XL, 0x60) < 0) return -1;
    if (write_reg(CTRL2_G, 0x60) < 0) return -1;

    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    uint8_t buf[12];
    if (read_regs(OUTX_L_G, buf, 12) < 0) return -1;

    int16_t gx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t gy = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t gz = (int16_t)((buf[5] << 8) | buf[4]);
    int16_t ax = (int16_t)((buf[7] << 8) | buf[6]);
    int16_t ay = (int16_t)((buf[9] << 8) | buf[8]);
    int16_t az = (int16_t)((buf[11] << 8) | buf[10]);

    data->gyro_x = gx * GYRO_SENSITIVITY / 1000.0f;
    data->gyro_y = gy * GYRO_SENSITIVITY / 1000.0f;
    data->gyro_z = gz * GYRO_SENSITIVITY / 1000.0f;
    data->accel_x = ax * ACCEL_SENSITIVITY / 1000.0f;
    data->accel_y = ay * ACCEL_SENSITIVITY / 1000.0f;
    data->accel_z = az * ACCEL_SENSITIVITY / 1000.0f;

    return 0;
}

static void log_data(const sensor_data_t *data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s.%03ld,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            timestamp, ts.tv_nsec / 1000000,
            data->accel_x, data->accel_y, data->accel_z,
            data->gyro_x, data->gyro_y, data->gyro_z);
    fflush(log_file);
}

static void fall_detection(const sensor_data_t *data) {
    static uint32_t freefall_start_ms = 0;
    static int in_freefall = 0;
    static uint32_t impact_start_ms = 0;
    static int impact_active = 0;

    uint32_t now_ms = (uint32_t)(clock() / 1000);

    if (in_freefall) {
        if (now_ms - freefall_start_ms > FALL_WINDOW_MS) {
            in_freefall = 0;
        }
    } else {
        if (fabsf(data->accel_x) > FREEFALL_THRESHOLD &&
            fabsf(data->accel_y) > FREEFALL_THRESHOLD &&
            fabsf(data->accel_z) > FREEFALL_THRESHOLD) {
            in_freefall = 1;
            freefall_start_ms = now_ms;
        }
    }

    if (impact_active) {
        if (now_ms - impact_start_ms > FALL_WINDOW_MS) {
            impact_active = 0;
        }
    } else {
        if (fabsf(data->accel_x) > IMPACT_THRESHOLD &&
            fabsf(data->accel_y) > IMPACT_THRESHOLD &&
            fabsf(data->accel_z) > IMPACT_THRESHOLD) {
            impact_active = 1;
            impact_start_ms = now_ms;
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialization failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("motion_log.txt", "a");
    if (!log_file) {
        perror("Failed to open motion_log.txt");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "# LSM6DSR motion log started\n");
    fflush(log_file);

    sensor_data_t sensor_data;
    uint32_t last_log_ms = 0;

    while (running) {
        if (read_sensor_data(&sensor_data) < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        uint32_t now_ms = (uint32_t)(clock() / 1000);
        if (now_ms - last_log_ms >= 100) {
            log_data(&sensor_data);
            last_log_ms = now_ms;
        }

        fall_detection(&sensor_data);

        gpioDelay(10000);
    }

    fprintf(stderr, "\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

