#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16266 Register Addresses */
#define ADIS16266_REG_XGYRO_OUT 0x14
#define ADIS16266_REG_WHO_AM_I  0x7D
#define ADIS16266_WHO_AM_I_VAL  0x3F5A

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    3        /* CPOL=1, CPHA=1 */

/* Gyroscope Scale Factor (degrees/sec per LSB) */
#define GYRO_SCALE 0.0305f

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 10000

/* Global resources for signal handler */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16266                          */
/* Returns 0 on success, -1 on SPI error.                              */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *value)
{
    char tx[2];
    char rx[2];

    /* ADIS16266: bit 7 = 1 for read, bits 6-0 = register address */
    tx[0] = (char)(0x80 | (reg & 0x7F));
    tx[1] = 0x00;

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read error for register 0x%02X\n", reg);
        return -1;
    }

    *value = (int16_t)(((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register on the ADIS16266                            */
/* Returns 0 on success, -1 on SPI error.                              */
/* ------------------------------------------------------------------ */
static int write_register(uint8_t reg, uint16_t value)
{
    char tx[2];
    char rx[2];

    /* ADIS16266: bit 7 = 0 for write, bits 6-0 = register address */
    tx[0] = (char)(reg & 0x7F);
    tx[1] = (char)((value >> 8) & 0xFF);

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write error for register 0x%02X\n", reg);
        return -1;
    }

    /* Second byte is the low byte of the written value */
    (void)rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the ADIS16266 and verify its identity                    */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int initialize_gyro(void)
{
    int16_t who_am_i;

    if (read_register(ADIS16266_REG_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }

    uint16_t id = (uint16_t)who_am_i;
    if (id != ADIS16266_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%04X, expected 0x%04X\n",
                id, ADIS16266_WHO_AM_I_VAL);
        return -1;
    }

    printf("ADIS16266 detected (WHO_AM_I = 0x%04X)\n", id);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a timestamped angular-rate reading to the CSV file               */
/* ------------------------------------------------------------------ */
static void log_data(float angular_rate)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s,%.3f\n", timestamp, angular_rate);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel: mode 3 = CPOL=1, CPHA=1 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz, mode %d)\n",
                SPI_CHANNEL, SPI_SPEED, SPI_MODE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the gyroscope */
    if (initialize_gyro() != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file once with CSV header */
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        perror("Error opening gyro_log.csv");
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(log_file, "Timestamp,AngularRate_dps\n");
    fflush(log_file);

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging angular rate to gyro_log.csv. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        int16_t raw;
        if (read_register(ADIS16266_REG_XGYRO_OUT, &raw) != 0) {
            fprintf(stderr, "Read error; continuing\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float angular_rate = (float)raw * GYRO_SCALE;
        log_data(angular_rate);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

