    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* Normal mode, all axes enabled */
    if (i2c_write_byte_retry(handle, CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Failed to configure CTRL_REG1\n");
        return -1;
    }

    /* +-250 dps full-scale range */
    if (i2c_write_byte_retry(handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Failed to configure CTRL_REG4\n");
        return -1;
    }

    return 0;
}

/* Read 6 bytes of gyroscope data (X, Y, Z) in one block */
static int read_gyro_data(int handle, float *x, float *y, float *z) {
    char buffer[6];

    /* Set register pointer to OUT_X_L (0x28) */
    if (i2cWriteByte(handle, OUT_X_L) < 0) {
        fprintf(stderr, "Failed to set register pointer to 0x%02X\n", OUT_X_L);
        return -1;
    }

    /* Read 6 bytes: X_L, X_H, Y_L, Y_H, Z_L, Z_H */
    int bytes_read = i2cReadDevice(handle, buffer, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Failed to read gyroscope data: read %d bytes (expected 6)\n",
                bytes_read);
        return -1;
    }

    /* Combine low and high bytes, convert to mdps, then to dps */
    int16_t raw_x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);

    *x = (float)raw_x / SENSITIVITY;
    *y = (float)raw_y / SENSITIVITY;
    *z = (float)raw_z / SENSITIVITY;

    return 0;
}

/* Log a sample to the CSV file */
static int log_data(FILE *fp, float x, float y, float z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(fp, "%s.%09ld,%.3f,%.3f,%.3f\n",
                timestamp, ts.tv_nsec, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x69 */
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, GYRO_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the gyroscope */
    if (init_gyro(i2c_handle) < 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open gyro_log.csv: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if the file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
        fflush(log_file);
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
    }

    printf("Gyroscope logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (running) {
        float x, y, z;

        if (read_gyro_data(i2c_handle, &x, &y, &z) < 0) {
            fprintf(stderr, "Gyroscope read error, continuing...\n");
        } else {
            if (log_data(log_file, x, y, z) < 0) {
                fprintf(stderr, "Logging error, continuing...\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

