#include <errno.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME "flame_events.log"
#define POLL_DELAY_US 500000  /* 500 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/*
 * Read the KY-026 digital output.
 * Returns 0 (flame detected, DO is LOW), 1 (no flame, DO is HIGH),
 * or -1 on error.
 */
static int read_flame_sensor(int gpio)
{
    int value = gpioRead(gpio);
    if (value == PI_BAD_GPIO) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d\n", gpio);
        return -1;
    }
    return value;
}

/*
 * Log a flame event with a timestamp.
 * Returns 0 on success, -1 on failure.
 */
static int log_flame_event(FILE *log_file, int flame_detected)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Flame detected: %s\n",
                timestamp, flame_detected ? "YES" : "NO") < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file: %s\n",
                strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    FILE *log_file = NULL;
    int ret = EXIT_SUCCESS;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO17 as input with pull-up --- */
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n",
                FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d\n",
                FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file in append mode --- */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }

    printf("Flame sensor monitoring started on GPIO%d.\n", FLAME_SENSOR_GPIO);
    printf("Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE_NAME);

    /* --- Main polling loop --- */
    while (program_running) {
        int sensor_value = read_flame_sensor(FLAME_SENSOR_GPIO);

        if (sensor_value == -1) {
            /* Sensor read error — log the error line and continue */
            if (log_flame_event(log_file, 0) != 0) {
                fprintf(stderr, "Warning: failed to log sensor error\n");
            }
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* KY-026 DO is active-LOW: LOW (0) means flame detected */
        int flame_detected = (sensor_value == 0) ? 1 : 0;

        if (log_flame_event(log_file, flame_detected) != 0) {
            fprintf(stderr, "Warning: failed to log flame event\n");
        }

        if (flame_detected) {
            printf("FLAME DETECTED!\n");
            fflush(stdout);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Warning: fclose failed: %s\n",
                    strerror(errno));
            ret = EXIT_FAILURE;
        }
    }
    gpioTerminate();
    return ret;
}

