#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x53
#define REG_X_LSB      0x28
#define REG_Y_LSB      0x2A
#define REG_Z_LSB      0x2C
#define NUM_AXES       3
#define SAMPLE_MS     100
#define LOG_FILE      "vibration_log.csv"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log   = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read reg 0x%02X failed: got %zd bytes (%s)\n",
                reg, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    *out = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    if (i2c_read_reg16(fd, REG_X_LSB, x) != 0) return -1;
    if (i2c_read_reg16(fd, REG_Y_LSB, y) != 0) return -1;
    if (i2c_read_reg16(fd, REG_Z_LSB, z) != 0) return -1;
    return 0;
}

static void log_data(FILE *f, int16_t x, int16_t y, int16_t z)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(f, "%s,%d,%d,%d\n", ts, x, y, z);
    fflush(f);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                D7S_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(g_log, "Timestamp,X,Y,Z\n");
    fflush(g_log);

    printf("Monitoring vibration (D7S-0001 @ 0x%02X on %s)...\n", D7S_ADDR, I2C_BUS);

    while (g_running) {
        int16_t x, y, z;
        if (read_acceleration(g_i2c_fd, &x, &y, &z) == 0) {
            log_data(g_log, x, y, z);
        } else {
            fprintf(stderr, "Sensor read error; skipping sample.\n");
        }
        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down cleanly...\n");
    if (g_log)  fclose(g_log);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return EXIT_SUCCESS;
}

