#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MMA8452Q_ADDR        0x1D
#define MMA8452Q_WHO_AM_I    0x0D
#define MMA8452Q_WHO_AM_I_VAL 0x2A
#define MMA8452Q_CTRL_REG1   0x2A
#define MMA8452Q_OUT_X_MSB   0x01
#define MMA8452Q_OUT_X_LSB   0x02
#define MMA8452Q_OUT_Y_MSB   0x03
#define MMA8452Q_OUT_Y_LSB   0x04
#define MMA8452Q_OUT_Z_MSB   0x05
#define MMA8452Q_OUT_Z_LSB   0x06

#define TILT_THRESHOLD_DEG   45.0
#define I2C_BUS              "/dev/i2c-1"
#define LOG_FILE             "fall_log.txt"
#define SAMPLE_PERIOD_US     10000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C block write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C block read (reg 0x%02X, len %zu) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int mma8452q_init(int fd)
{
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, MMA8452Q_WHO_AM_I, &who_am_i) != 0)
        return -1;
    if (who_am_i != MMA8452Q_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, MMA8452Q_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode: clear ACTIVE bit (bit 0) */
    if (i2c_write_reg8(fd, MMA8452Q_CTRL_REG1, 0x00) != 0)
        return -1;

    /* Data rate: 100 Hz (0b010) */
    if (i2c_write_reg8(fd, MMA8452Q_CTRL_REG1, 0x0C) != 0)
        return -1;

    /* Active mode: set ACTIVE bit (bit 0) */
    if (i2c_write_reg8(fd, MMA8452Q_CTRL_REG1, 0x01) != 0)
        return -1;

    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, MMA8452Q_OUT_X_MSB, buf, sizeof(buf)) != 0)
        return -1;

    *x = (int16_t)((buf[0] << 4) | (buf[1] >> 4));
    *y = (int16_t)((buf[2] << 4) | (buf[3] >> 4));
    *z = (int16_t)((buf[4] << 4) | (buf[5] >> 4));
    return 0;
}

static double calculate_tilt(int16_t x, int16_t y, int16_t z)
{
    double fx = (double)x;
    double fy = (double)y;
    double fz = (double)z;
    return atan2(fx, sqrt(fy * fy + fz * fz)) * 180.0 / M_PI;
}

static void log_fall(int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(g_log_fp, "%s X=%d Y=%d Z=%d\n", ts, x, y, z);
    fflush(g_log_fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE (0x%02X) failed: %s\n",
                MMA8452Q_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (mma8452q_init(g_i2c_fd) != 0) {
        fprintf(stderr, "MMA8452Q initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("MMA8452Q initialized. Logging falls to %s. Press Ctrl+C to exit.\n",
           LOG_FILE);

    while (g_running) {
        int16_t x, y, z;
        if (read_accel(g_i2c_fd, &x, &y, &z) != 0) {
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        double tilt = calculate_tilt(x, y, z);
        if (fabs(tilt) > TILT_THRESHOLD_DEG) {
            log_fall(x, y, z);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

