#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LIS3MDL_ADDR   0x1E
#define WHO_AM_I       0x0F
#define WHO_AM_I_VAL   0x3D
#define CTRL_REG1      0x20
#define CTRL_REG2      0x21
#define CTRL_REG3      0x22
#define CTRL_REG4      0x23
#define OUT_X_L        0x28
#define OUT_X_H        0x29
#define OUT_Y_L        0x2A
#define OUT_Y_H        0x2B
#define OUT_Z_L        0x2C
#define OUT_Z_H        0x2D

#define METAL_THRESHOLD_MG  800.0f
#define SAMPLE_PERIOD_US    100000  /* 10 Hz */
#define MAX_RETRIES         3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int lis3mdl_init(int fd) {
    uint8_t who;
    if (i2c_read_reg(fd, WHO_AM_I, &who) != 0) return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: 0x70 = 0b01110000 -> ODR=80 Hz (0111), high-performance mode (0b0000) */
    if (i2c_write_reg(fd, CTRL_REG1, 0x70) != 0) return -1;
    /* CTRL_REG2: 0x00 -> no self-test */
    if (i2c_write_reg(fd, CTRL_REG2, 0x00) != 0) return -1;
    /* CTRL_REG3: 0x00 -> no high-resolution mode */
    if (i2c_write_reg(fd, CTRL_REG3, 0x00) != 0) return -1;
    /* CTRL_REG4: 0x0C -> continuous-conversion mode, 80 Hz ODR */
    if (i2c_write_reg(fd, CTRL_REG4, 0x0C) != 0) return -1;
    return 0;
}

static int read_magnetometer(int fd, float *x_mg, float *y_mg, float *z_mg) {
    uint8_t raw[6];
    if (i2c_read_burst(fd, OUT_X_L, raw, 6) != 0) return -1;

    int16_t x = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t y = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t z = (int16_t)((raw[5] << 8) | raw[4]);

    /* Apply calibration constants (replace with your calibrated values) */
    x = (int16_t)((x * 0.5f) + 1000.0f);
    y = (int16_t)((y * 0.5f) + 1000.0f);
    z = (int16_t)((z * 0.5f) + 1000.0f);

    /* Convert to milliGauss: +-4 gauss sensitivity = 0.146 mG/LSB */
    *x_mg = (float)x * 0.146f;
    *y_mg = (float)y * 0.146f;
    *z_mg = (float)z * 0.146f;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    fprintf(fp, "%.2f,%.2f,%.2f\n", x, y, z);
    fflush(fp);
}

static void check_metal_threshold(float x, float y, float z) {
    float magnitude = sqrtf(x * x + y * y + z * z);
    if (magnitude > METAL_THRESHOLD_MG) {
        fprintf(stderr, "Metal detected! X=%.2f Y=%.2f Z=%.2f mG\n", x, y, z);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", LIS3MDL_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    int init_ok = 0;
    for (int attempt = 0; attempt < MAX_RETRIES && !init_ok; attempt++) {
        if (lis3mdl_init(g_i2c_fd) == 0) {
            init_ok = 1;
        } else {
            fprintf(stderr, "Initialization failed, retry %d/%d\n", attempt + 1, MAX_RETRIES);
            usleep(100000);
        }
    }
    if (!init_ok) {
        fprintf(stderr, "Failed to initialize LIS3MDL after %d attempts\n", MAX_RETRIES);
        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen("magnetic_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open magnetic_log.txt: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("LIS3MDL initialized. Logging to magnetic_log.txt at 10 Hz. Press Ctrl+C to stop.\n");

    while (g_running) {
        float x, y, z;
        if (read_magnetometer(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Read error, retrying...\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        log_data(g_log_fp, x, y, z);
        check_metal_threshold(x, y, z);
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

