#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADXL354B Register Addresses */
#define ADXL354_REG_DEVID_AD  0x00
#define ADXL354_REG_PARTID    0x01
#define ADXL354_REG_XDATA_L   0x08
#define ADXL354_REG_XDATA_H   0x09
#define ADXL354_REG_XDATA_H2  0x0A
#define ADXL354_REG_YDATA_L   0x0B
#define ADXL354_REG_YDATA_H   0x0C
#define ADXL354_REG_YDATA_H2  0x0D
#define ADXL354_REG_ZDATA_L   0x0E
#define ADXL354_REG_ZDATA_H   0x0F
#define ADXL354_REG_ZDATA_H2  0x10
#define ADXL354_REG_STATUS    0x04
#define ADXL354_REG_POWER_CTL 0x2D
#define ADXL354_REG_RESET     0x1F

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0, active low CS */

/* ADXL354B constants */
#define ADXL354_DEVID_AD_VAL  0xE5
#define ADXL354_PARTID_VAL    0x1D
#define ADXL354_RESET_CMD     0x52
#define ADXL354_RESET_DELAY_US 1000
#define ADXL354_RUN_BIT       0x01
#define ADXL354_STABLE_BIT    0x02
#define ADXL354_SENSITIVITY   0.0000039f  /* +-2g range: 3.9 microg/LSB */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float x, y, z;
} accel_data_t;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a single byte to a register */
static int adxl354_write_reg(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x3F), (char)value };
    char rx[2] = { 0 };
    int ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI write to reg 0x%02X failed (ret=%d)\n", reg, ret);
        return -1;
    }
    return 0;
}

/* Read a single byte from a register */
static int adxl354_read_reg(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0 };
    int ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read from reg 0x%02X failed (ret=%d)\n", reg, ret);
        return -1;
    }
    *value = (uint8_t)rx[1];
    return 0;
}

/* Read a 20-bit signed acceleration value (3 bytes, 20-bit left-justified) */
static int adxl354_read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char tx[6] = { 0 };
    char rx[6] = { 0 };
    int ret = spiXfer(spi_handle, tx, rx, 6);
    if (ret != 6) {
        fprintf(stderr, "SPI read acceleration failed (ret=%d)\n", ret);
        return -1;
    }
    /* Combine 3 bytes: LSB, MSB, MSB2 */
    uint32_t raw_x = ((uint32_t)(uint8_t)rx[1] << 12) | ((uint32_t)(uint8_t)rx[2] << 4) | ((uint32_t)(uint8_t)rx[3] >> 4);
    uint32_t raw_y = ((uint32_t)(uint8_t)rx[4] << 12) | ((uint32_t)(uint8_t)rx[5] << 4) | ((uint32_t)(uint8_t)rx[6] >> 4);
    uint32_t raw_z = ((uint32_t)(uint8_t)rx[7] << 12) | ((uint32_t)(uint8_t)rx[8] << 4) | ((uint32_t)(uint8_t)rx[9] >> 4);
    /* Sign-extend 20-bit to 32-bit */
    if (raw_x & 0x80000) raw_x |= 0xFFF00000;
    if (raw_y & 0x80000) raw_y |= 0xFFF00000;
    if (raw_z & 0x80000) raw_z |= 0xFFF00000;
    *x = (int16_t)raw_x;
    *y = (int16_t)raw_y;
    *z = (int16_t)raw_z;
    return 0;
}

/* Initialize the ADXL354B */
static int adxl354_init(void) {
    uint8_t partid = 0;
    if (adxl354_read_reg(ADXL354_REG_PARTID, &partid) != 0) {
        fprintf(stderr, "Failed to read PARTID\n");
        return -1;
    }
    if (partid != ADXL354_PARTID_VAL) {
        fprintf(stderr, "Unexpected PARTID: 0x%02X (expected 0x%02X)\n", partid, ADXL354_PARTID_VAL);
        return -1;
    }
    printf("ADXL354B detected (PARTID=0x%02X)\n", partid);

    /* Reset device */
    if (adxl354_write_reg(ADXL354_REG_RESET, ADXL354_RESET_CMD) != 0) return -1;
    gpioDelay(ADXL354_RESET_DELAY_US);

    /* Clear RUN bit to enter standby */
    if (adxl354_write_reg(ADXL354_REG_POWER_CTL, 0x00) != 0) return -1;
    gpioDelay(1000);

    /* Verify STABLE bit is clear (device not in measurement mode) */
    uint8_t status = 0;
    int timeout = 100;
    do {
        if (adxl354_read_reg(ADXL354_REG_STATUS, &status) != 0) return -1;
        if (status & ADXL354_STABLE_BIT) {
            fprintf(stderr, "STABLE bit still set after reset\n");
            return -1;
        }
        gpioDelay(1000);
        timeout--;
    } while (timeout > 0);

    /* Set RUN bit to enter measurement mode */
    if (adxl354_write_reg(ADXL354_REG_POWER_CTL, ADXL354_RUN_BIT) != 0) return -1;
    gpioDelay(1000);

    printf("ADXL354B initialized successfully\n");
    return 0;
}

/* Log acceleration data with timestamp */
static void log_data(const accel_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, X: %.6f g, Y: %.6f g, Z: %.6f g\n", timestamp, data->x, data->y, data->z);
    fflush(log_file);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize ADXL354B */
    if (adxl354_init() != 0) {
        fprintf(stderr, "ADXL354B initialization failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    /* Open log file */
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Logging vibration data to vibration_log.txt (Ctrl+C to stop)\n");

    /* Main loop */
    while (!terminate) {
        int16_t raw_x, raw_y, raw_z;
        if (adxl354_read_acceleration(&raw_x, &raw_y, &raw_z) == 0) {
            accel_data_t data;
            data.x = (float)raw_x * ADXL354_SENSITIVITY;
            data.y = (float)raw_y * ADXL354_SENSITIVITY;
            data.z = (float)raw_z * ADXL354_SENSITIVITY;
            log_data(&data);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

