#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADIS16362 Register Addresses */
#define X_GYRO_REG   0x04
#define Y_GYRO_REG   0x06
#define Z_GYRO_REG   0x08
#define X_ACCL_REG   0x0A
#define Y_ACCL_REG   0x0C
#define Z_ACCL_REG   0x0E

/* SPI Configuration */
#define SPI_CHANNEL  0
#define SPI_BAUD     1000000  /* 1 MHz */
#define SPI_FLAGS    0x0000   /* Mode 3: active-high clock, sample on trailing edge */

/* Gyroscope and Accelerometer Sensitivities */
#define GYRO_SCALE   0.05f    /* deg/sec per LSB */
#define ACCL_SCALE   0.0025f  /* g per LSB */

/* Sampling interval in microseconds (10 ms -> 100 Hz) */
#define SAMPLE_US    10000

/* Global resources for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read a single register from the ADIS16362 via SPI.
   Returns 0 on success, -1 on SPI transfer failure. */
static int read_register(uint8_t reg, int16_t *value) {
    char tx_buf[2];
    char rx_buf[2];
    int  result;

    /* ADIS16362 read protocol: send address with MSB set, then dummy byte */
    tx_buf[0] = (char)(reg | 0x80);
    tx_buf[1] = 0x00;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X (spiXfer returned %d)\n",
                reg, result);
        return -1;
    }

    /* Data is returned on the second 16-bit transfer */
    tx_buf[0] = 0x00;
    tx_buf[1] = 0x00;
    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI transfer failed for data read from register 0x%02X (spiXfer returned %d)\n",
                reg, result);
        return -1;
    }

    /* Data is MSB-first, 16-bit big-endian */
    *value = (int16_t)(((uint16_t)(uint8_t)rx_buf[0] << 8) | (uint8_t)rx_buf[1]);
    return 0;
}

/* Read all six sensor axes. Returns 0 on success, -1 on any SPI error. */
static int read_imu_data(float *gyro_x, float *gyro_y, float *gyro_z,
                         float *accel_x, float *accel_y, float *accel_z) {
    int16_t raw_x, raw_y, raw_z;

    if (read_register(X_GYRO_REG, &raw_x) != 0) return -1;
    if (read_register(Y_GYRO_REG, &raw_y) != 0) return -1;
    if (read_register(Z_GYRO_REG, &raw_z) != 0) return -1;
    if (read_register(X_ACCL_REG, &raw_x) != 0) return -1;
    if (read_register(Y_ACCL_REG, &raw_y) != 0) return -1;
    if (read_register(Z_ACCL_REG, &raw_z) != 0) return -1;

    *gyro_x = (float)raw_x * GYRO_SCALE;
    *gyro_y = (float)raw_y * GYRO_SCALE;
    *gyro_z = (float)raw_z * GYRO_SCALE;
    *accel_x = (float)raw_x * ACCL_SCALE;
    *accel_y = (float)raw_y * ACCL_SCALE;
    *accel_z = (float)raw_z * ACCL_SCALE;

    return 0;
}

/* Log a timestamped IMU reading to the CSV file. */
static void log_data(float gyro_x, float gyro_y, float gyro_z,
                     float accel_x, float accel_y, float accel_z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return;
    }

    fprintf(log_file, "%ld.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            (long)ts.tv_sec, ts.tv_nsec,
            gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
    fflush(log_file);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel: channel 0, 1 MHz, Mode 3 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
        fflush(log_file);
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not register SIGINT handler: %s\n", strerror(errno));
    }

    printf("IMU data logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        if (read_imu_data(&gyro_x, &gyro_y, &gyro_z,
                          &accel_x, &accel_y, &accel_z) == 0) {
            log_data(gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Error reading IMU data, skipping log entry.\n");
        }

        gpioDelay(SAMPLE_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

