#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip4"
#define CS_LINE_OFFSET 8
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 3
#define SPI_BITS_PER_WORD 8

#define ADIS16266_REG_MSC_CTRL 0x24
#define ADIS16266_REG_GYRO_XOUT 0x04
#define ADIS16266_REG_GYRO_YOUT 0x06
#define ADIS16266_REG_GYRO_ZOUT 0x08

#define GYRO_SCALE_FACTOR 0.02f

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int adis16266_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), value };
    uint8_t rx[2] = {0};
    return spi_transfer(fd, tx, rx, 2);
}

static int adis16266_read_reg(int fd, uint8_t reg, uint16_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), 0x00 };
    uint8_t rx[2] = {0};
    if (spi_transfer(fd, tx, rx, 2) < 0) return -1;
    *value = ((uint16_t)rx[0] << 8) | rx[1];
    return 0;
}

static int adis16266_init(int fd) {
    if (adis16266_write_reg(fd, ADIS16266_REG_MSC_CTRL, 0x00) < 0) return -1;
    usleep(10000);
    if (adis16266_write_reg(fd, ADIS16266_REG_MSC_CTRL, 0x01) < 0) return -1;
    usleep(10000);
    return 0;
}

static int read_gyro_data(int fd, float *x, float *y, float *z) {
    uint16_t raw_x, raw_y, raw_z;

    if (adis16266_read_reg(fd, ADIS16266_REG_GYRO_XOUT, &raw_x) < 0) return -1;
    if (adis16266_read_reg(fd, ADIS16266_REG_GYRO_YOUT, &raw_y) < 0) return -1;
    if (adis16266_read_reg(fd, ADIS16266_REG_GYRO_ZOUT, &raw_z) < 0) return -1;

    *x = (float)((int16_t)raw_x) * GYRO_SCALE_FACTOR;
    *y = (float)((int16_t)raw_y) * GYRO_SCALE_FACTOR;
    *z = (float)((int16_t)raw_z) * GYRO_SCALE_FACTOR;

    return 0;
}

int main(void) {
    int spi_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CS_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    if (gpiod_line_request_output(cs_line, "adis16266_cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        goto cleanup_chip;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup_cs;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup_spi;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup_spi;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        goto cleanup_spi;
    }

    if (adis16266_init(spi_fd) < 0) {
        fprintf(stderr, "Failed to initialize ADIS16266\n");
        goto cleanup_spi;
    }

    printf("ADIS16266 initialized. Reading gyroscope data...\n");

    while (running) {
        float x, y, z;
        if (read_gyro_data(spi_fd, &x, &y, &z) == 0) {
            printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }
        usleep(100000);
    }

    printf("\nExiting gracefully...\n");
    ret = 0;

cleanup_spi:
    if (spi_fd >= 0) close(spi_fd);
cleanup_cs:
    if (cs_line) gpiod_line_release(cs_line);
cleanup_chip:
    if (chip) gpiod_chip_close(chip);

    return ret;
}

