    cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CS_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    if (gpiod_line_request_output(cs_line, "adis16266_cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        goto cleanup_chip;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup_cs;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup_spi;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup_spi;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        goto cleanup_spi;
    }

    if (adis16266_init(spi_fd) < 0) {
        fprintf(stderr, "Failed to initialize ADIS16266\n");
        goto cleanup_spi;
    }

    printf("ADIS16266 initialized. Reading gyroscope data...\n");

    while (running) {
        float x, y, z;
        if (read_gyro_data(spi_fd, &x, &y, &z) == 0) {
            printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }
        usleep(100000);
    }

    printf("\nExiting gracefully...\n");
    ret = 0;

cleanup_spi:
    if (spi_fd >= 0) close(spi_fd);
cleanup_cs:
    if (cs_line) gpiod_line_release(cs_line);
cleanup_chip:
    if (chip) gpiod_chip_close(chip);

    return ret;
}

