#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR I2C 7-bit address (SA0 tied high on Adafruit breakout) */
#define LSM6DSR_ADDR 0x6B

/* WHO_AM_I register and expected value */
#define LSM6DSR_WHO_AM_I 0x0F
#define LSM6DSR_WHO_AM_I_VAL 0x6B

/* Accelerometer control register */
#define LSM6DSR_CTRL1_XL 0x10

/* Gyroscope control register */
#define LSM6DSR_CTRL2_G 0x11

/* Output register for burst read (gyro X/Y/Z then accel X/Y/Z) */
#define LSM6DSR_OUTX_L_G 0x22

/* Sensitivities for the chosen full-scale ranges */
#define GYRO_SENSITIVITY 0.00875f  /* dps per LSB at +-250 dps */
#define ACCEL_SENSITIVITY 0.000061f /* g per LSB at +-2g */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (rc=%d)\n",
                value, reg, rc);
    }
    return rc;
}

static int read_regs(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "Error reading %u bytes from register 0x%02X (rc=%d)\n",
                len, reg, rc);
        return -1;
    }
    return 0;
}

static int init_lsm6dsr(int handle)
{
    int who = i2cReadByteData(handle, LSM6DSR_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register (rc=%d)\n", who);
        return -1;
    }
    if (who != LSM6DSR_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LSM6DSR_WHO_AM_I_VAL);
        return -1;
    }

    if (write_reg(handle, LSM6DSR_CTRL1_XL, 0x42) < 0)
        return -1; /* +-2g, 104 Hz, 12-bit */

    if (write_reg(handle, LSM6DSR_CTRL2_G, 0x42) < 0)
        return -1; /* +-250 dps, 104 Hz, 12-bit */

    return 0;
}

static int read_sensor_data(int handle, float *gx, float *gy, float *gz,
                            float *ax, float *ay, float *az)
{
    uint8_t buf[12];

    if (read_regs(handle, LSM6DSR_OUTX_L_G, buf, sizeof(buf)) < 0)
        return -1;

    int16_t rgx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t rgy = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t rgz = (int16_t)((buf[5] << 8) | buf[4]);
    int16_t rax = (int16_t)((buf[7] << 8) | buf[6]);
    int16_t ray = (int16_t)((buf[9] << 8) | buf[8]);
    int16_t raz = (int16_t)((buf[11] << 8) | buf[10]);

    *gx = (float)rgx * GYRO_SENSITIVITY;
    *gy = (float)rgy * GYRO_SENSITIVITY;
    *gz = (float)rgz * GYRO_SENSITIVITY;
    *ax = (float)rax * ACCEL_SENSITIVITY;
    *ay = (float)ray * ACCEL_SENSITIVITY;
    *az = (float)raz * ACCEL_SENSITIVITY;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X (rc=%d)\n",
                LSM6DSR_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lsm6dsr(g_i2c_handle) < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float gx, gy, gz, ax, ay, az;

        if (read_sensor_data(g_i2c_handle, &gx, &gy, &gz, &ax, &ay, &az) == 0) {
            printf("Gyro: X=%.2f, Y=%.2f, Z=%.2f dps | "
                   "Accel: X=%.2f, Y=%.2f, Z=%.2f g\n",
                   gx, gy, gz, ax, ay, az);
        } else {
            fprintf(stderr, "Sensor read failed; aborting.\n");
            break;
        }

        gpioDelay(100000); /* 100 ms */
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

