#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* FXOS8700 I2C address (SA0 tied to VDD on Adafruit breakout) */
#define FXOS8700_ADDR 0x1D

/* FXOS8700 register addresses */
#define FXOS8700_WHO_AM_I   0x0D
#define FXOS8700_WHO_AM_I_VAL 0xC7
#define FXOS8700_CTRL_REG1  0x2A
#define FXOS8700_CTRL_REG2  0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_OUT_X_MSB  0x01

/* Hybrid mode: accelerometer 14-bit left-aligned, magnetometer 16-bit */
#define CTRL_REG1_HYBRID 0x00
#define M_CTRL_REG1_HYBRID 0x00
#define M_CTRL_REG2_HYBRID 0x00

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n",
                reg, value, rc);
    }
    return rc;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, expected=%u, got=%d\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

static int initialize_fxos8700(int handle)
{
    uint8_t who_am_i = 0;

    /* Verify sensor identity */
    if (i2c_read_block(handle, FXOS8700_WHO_AM_I, &who_am_i, 1) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor may be absent or bus error.\n");
        return -1;
    }
    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode before configuration */
    if (i2c_write_byte(handle, FXOS8700_CTRL_REG1, 0x00) != 0)
        return -1;
    if (i2c_write_byte(handle, FXOS8700_CTRL_REG2, 0x00) != 0)
        return -1;

    /* Magnetometer: hybrid mode, 800 Hz ODR, normal measurement */
    if (i2c_write_byte(handle, FXOS8700_M_CTRL_REG1, M_CTRL_REG1_HYBRID) != 0)
        return -1;
    if (i2c_write_byte(handle, FXOS8700_M_CTRL_REG2, M_CTRL_REG2_HYBRID) != 0)
        return -1;

    /* Accelerometer: hybrid mode, 1 kHz ODR, normal measurement */
    if (i2c_write_byte(handle, FXOS8700_CTRL_REG1, CTRL_REG1_HYBRID) != 0)
        return -1;
    if (i2c_write_byte(handle, FXOS8700_CTRL_REG2, 0x00) != 0)
        return -1;

    return 0;
}

static int read_sensor_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *mx, int16_t *my, int16_t *mz)
{
    uint8_t buf[12];

    if (i2c_read_block(handle, FXOS8700_OUT_X_MSB, buf, sizeof(buf)) != 0)
        return -1;

    /*
     * Data layout (hybrid mode, 12-byte block):
     *   buf[0..5] : 14-bit accelerometer X/Y/Z (left-aligned, bits 13..0)
     *   buf[6..11]: 16-bit magnetometer X/Y/Z
     */
    uint16_t accel_x = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t accel_y = ((uint16_t)buf[2] << 8) | buf[3];
    uint16_t accel_z = ((uint16_t)buf[4] << 8) | buf[5];

    /* Left-aligned 14-bit: shift right 2 to get signed 14-bit value */
    *ax = (int16_t)((accel_x >> 2) & 0x7FFF);
    *ay = (int16_t)((accel_y >> 2) & 0x7FFF);
    *az = (int16_t)((accel_z >> 2) & 0x7FFF);

    uint16_t mag_x = ((uint16_t)buf[6] << 8) | buf[7];
    uint16_t mag_y = ((uint16_t)buf[8] << 8) | buf[9];
    uint16_t mag_z = ((uint16_t)buf[10] << 8) | buf[11];

    *mx = mag_x;
    *my = mag_y;
    *mz = mag_z;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x%02X: %d\n",
                FXOS8700_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_fxos8700(g_i2c_handle) != 0) {
        fprintf(stderr, "FXOS8700 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("FXOS8700 initialized. Logging data every 100 ms (Ctrl+C to stop).\n");

    while (g_running) {
        int16_t ax, ay, az, mx, my, mz;

        if (read_sensor_data(g_i2c_handle, &ax, &ay, &az, &mx, &my, &mz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  |  Mag: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "Read error — attempting to reinitialize...\n");
            if (initialize_fxos8700(g_i2c_handle) != 0) {
                fprintf(stderr, "Reinitialization failed; aborting.\n");
                break;
            }
        }

        gpioDelay(100000); /* 100 ms */
    }

    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

