    if (i2c_read_block(handle, FXOS8700_OUT_X_MSB, buf, sizeof(buf)) != 0)
        return -1;

    /*
     * Data layout (hybrid mode, 12-byte block):
     *   buf[0..5] : 14-bit accelerometer X/Y/Z (left-aligned, bits 13..0)
     *   buf[6..11]: 16-bit magnetometer X/Y/Z
     */
    uint16_t accel_x = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t accel_y = ((uint16_t)buf[2] << 8) | buf[3];
    uint16_t accel_z = ((uint16_t)buf[4] << 8) | buf[5];

    /* Left-aligned 14-bit: shift right 2 to get signed 14-bit value */
    *ax = (int16_t)((accel_x >> 2) & 0x7FFF);
    *ay = (int16_t)((accel_y >> 2) & 0x7FFF);
    *az = (int16_t)((accel_z >> 2) & 0x7FFF);

    uint16_t mag_x = ((uint16_t)buf[6] << 8) | buf[7];
    uint16_t mag_y = ((uint16_t)buf[8] << 8) | buf[9];
    uint16_t mag_z = ((uint16_t)buf[10] << 8) | buf[11];

    *mx = mag_x;
    *my = mag_y;
    *mz = mag_z;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x%02X: %d\n",
                FXOS8700_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_fxos8700(g_i2c_handle) != 0) {
        fprintf(stderr, "FXOS8700 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("FXOS8700 initialized. Logging data every 100 ms (Ctrl+C to stop).\n");

    while (g_running) {
        int16_t ax, ay, az, mx, my, mz;

        if (read_sensor_data(g_i2c_handle, &ax, &ay, &az, &mx, &my, &mz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  |  Mag: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "Read error — attempting to reinitialize...\n");
            if (initialize_fxos8700(g_i2c_handle) != 0) {
                fprintf(stderr, "Reinitialization failed; aborting.\n");
                break;
            }
        }

        gpioDelay(100000); /* 100 ms */
    }

    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

