#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define ADXL345_ADDRESS 0x53
#define I2C_BUS "/dev/i2c-1"
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define SAMPLE_INTERVAL_US 100000

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) {
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        return -1;
    }
    return 0;
}

static int adxl345_init(int fd) {
    if (i2c_write_byte(fd, 0x2D) < 0) {
        fprintf(stderr, "Error: Failed to write POWER_CTL register (sensor absent?)\n");
        return -1;
    }
    usleep(10000);
    return 0;
}

static int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t reg = 0x32;
    uint8_t buf[6];

    if (i2c_write_byte(fd, reg) < 0) {
        return -1;
    }
    if (i2c_read_burst(fd, buf, 6) < 0) {
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void calculate_tilt(int16_t x, int16_t y, int16_t z, float *roll, float *pitch) {
    *roll = atan2((float)x, sqrt((float)y * y + (float)z * z)) * 180.0 / M_PI;
    *pitch = atan2((float)y, sqrt((float)x * x + (float)z * z)) * 180.0 / M_PI;
}

static void log_event(float roll, float pitch) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s - Tilt: Roll=%.2f, Pitch=%.2f\n", timestamp, roll, pitch);
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_BUS);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return 1;
    }

    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "Error: ADXL345 initialization failed.\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen " LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Tilt detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t x, y, z;
        if (read_acceleration(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error: I2C read failed: %s\n", strerror(errno));
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float roll, pitch;
        calculate_tilt(x, y, z, &roll, &pitch);

        if (fabs(roll) > TILT_THRESHOLD || fabs(pitch) > TILT_THRESHOLD) {
            log_event(roll, pitch);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully.\n");
    cleanup();
    return 0;
}

