#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_GPIO 17
#define WINDOW_SECONDS 5
#define SAMPLE_INTERVAL_US 1000

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", SOUND_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_sound_sensor(void) {
    return gpioRead(SOUND_SENSOR_GPIO);
}

static void log_alert(int threshold, int high_count) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s - ALERT: Sound level exceeded threshold (%d high readings in %d seconds, threshold %d)\n",
           timestamp, high_count, WINDOW_SECONDS, threshold);
    fflush(stdout);
}

static void log_status(int threshold, int high_count) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s - Status: Sound level below threshold (%d high readings in %d seconds, threshold %d)\n",
           timestamp, high_count, WINDOW_SECONDS, threshold);
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    int threshold = 0;
    int high_count = 0;
    int i;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        fprintf(stderr, "  threshold: minimum number of high readings per %d-second window\n", WINDOW_SECONDS);
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    errno = 0;
    threshold = strtol(argv[1], &endptr, 10);
    if (errno != 0 || endptr == argv[1] || *endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: invalid threshold '%s'. Must be a positive integer.\n", argv[1]);
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler\n");
    }

    printf("Monitoring sound levels on GPIO%d every %d seconds. Threshold: %d high readings.\n",
           SOUND_SENSOR_GPIO, WINDOW_SECONDS, threshold);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (!terminate) {
        for (i = 0; i < WINDOW_SECONDS * 100 && !terminate; i++) {
            int reading = read_sound_sensor();
            if (reading < 0) {
                fprintf(stderr, "Error: gpioRead failed on GPIO%d\n", SOUND_SENSOR_GPIO);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            if (reading == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL_US);
        }

        if (terminate) {
            break;
        }

        if (high_count >= threshold) {
            log_alert(threshold, high_count);
        } else {
            log_status(threshold, high_count);
        }

        if (!terminate) {
            gpioDelay(1000000);
        }
    }

    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

