/*
 * Door access control system for Raspberry Pi 4 Model B
 * Uses libgpiod (modern GPIO API) instead of deprecated wiringPi.
 *
 * Wiring:
 *   - 5V relay module (active-HIGH) on GPIO17 (Door A)
 *   - 5V relay module on GPIO27 (Door B)
 *   - TIP120 NPN transistor between relay VCC and 12V lock supply
 *   - Relay IN pin -> GPIO17 / GPIO27 (BCM numbering)
 *   - Relay VCC    -> 5V pin (pin 2 or 4)
 *   - Relay GND    -> GND pin (pin 6)
 *   - 12V lock GND  -> GND pin (pin 6)
 *
 * Build: gcc -Wall -o door_access door_access.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define DOOR_A_LINE  17
#define DOOR_B_LINE  27
#define LOG_FILE     "access_log.txt"
#define CODE_LENGTH  6
#define UNLOCK_SEC   5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int generate_code(char *buf, size_t len)
{
    return snprintf(buf, len, "%06d", rand() % 900000 + 100000);
}

static int log_access(const char *code)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%s\n", ts, code);
    } else {
        fprintf(fp, "1970-01-01 00:00:00,%s\n", code);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *door_a = NULL;
    struct gpiod_line *door_b = NULL;
    int ret = EXIT_FAILURE;

    srand((unsigned int)time(NULL));

    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
