#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_ONE_TIME_HIGH_RES_MODE2 0x21
#define CONVERSION_TIME_MS 180
#define LOG_FILE "light_log.txt"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != (ssize_t)len) {
        return -1;
    }
    return 0;
}

static int read_bh1750(int fd, float *lux_out) {
    if (i2c_write_byte(fd, BH1750_ONE_TIME_HIGH_RES_MODE2) < 0) {
        return -1;
    }

    usleep(CONVERSION_TIME_MS * 1000);

    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) {
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int log_data(const char *filename, float lux) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    printf("BH1750 light sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (read_bh1750(fd, &lux) < 0) {
            fprintf(stderr, "Error reading BH1750 sensor: %s\n", strerror(errno));
        } else {
            if (log_data(LOG_FILE, lux) < 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully...\n");
    close(fd);
    return 0;
}

