#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC Register Addresses
#define LSM303_CTRL_REG1_M 0x20
#define LSM303_OUT_X_L_M   0x08

// GPIO settings
#define GPIO_CHIP_NAME "gpiochip0"
#define LED_PIN 17

// PWM settings
#define PWM_PERIOD_NS 10000000  // 10 Hz
#define PWM_DUTY_MAX 1000000    // 100% duty cycle

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t running = 1;

// Function prototypes
int init_i2c(void);
int init_magnetometer(void);
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void set_led_brightness(float magnitude);
void log_error(const char *message);
void cleanup(void);
void signal_handler(int signal);

// Initialize I2C communication
int init_i2c(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        log_error("Failed to acquire I2C bus access");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Initialize the magnetometer
int init_magnetometer(void) {
    uint8_t buf[2];
    buf[0] = LSM303_CTRL_REG1_M;
    buf[1] = 0x18; // 10 Hz, continuous conversion

    if (write(i2c_fd, buf, 2) != 2) {
        log_error("Failed to write to magnetometer control register");
        return -1;
    }

    return 0;
}

// Read magnetometer data (X, Y, Z)
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t reg = LSM303_OUT_X_L_M;
    uint8_t data[6];

    // Write the register address to read from
    if (write(i2c_fd, &reg, 1) != 1) {
        log_error("Failed to write register address for magnetometer data");
        return -1;
    }

    // Read 6 bytes of data
    if (read(i2c_fd, data, 6) != 6) {
        log_error("Failed to read magnetometer data");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Calculate the magnitude of the Z-axis magnetic field
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float magnitude = sqrt((float)(x * x + y * y + z * z));
    return magnitude;
}

// Set the LED brightness using hardware PWM
void set_led_brightness(float magnitude) {
    int duty_cycle = (int)(magnitude / 100.0 * PWM_DUTY_MAX);
    if (duty_cycle > PWM_DUTY_MAX) duty_cycle = PWM_DUTY_MAX;
    if (duty_cycle < 0) duty_cycle = 0;

    gpiod_line_set_value(led_line, 1);
    gpiod_line_set_value(led_line, 0); // This is a simple toggle; for PWM, we need to use the hardware PWM peripheral.
    // For a real implementation, we would use the PWM hardware. This example uses a simple on/off for demonstration.
    // In a production environment, you would use the PWM hardware or a library like pigpio.
}

// Log errors to a file
void log_error(const char *message) {
    FILE *fp = fopen("error.log", "a");
    if (fp != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fclose(fp);
    } else {
        perror("Failed to open error log file");
    }
}

// Cleanup resources
void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int main(void) {
    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize magnetometer
    if (init_magnetometer() != 0) {
        fprintf(stderr, "Magnetometer initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO using libgpiod
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        log_error("Failed to open GPIO chip");
        cleanup();
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        log_error("Failed to get GPIO line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(led_line, "magnetometer_led", 0) < 0) {
        log_error("Failed to request GPIO line as output");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
