#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HMC5883L_ADDR 0x1E
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_ID 0x0A
#define HMC5883L_STATUS 0x09
#define HMC5883L_NUM_SAMPLES 100
#define I2C_BUS 1

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_magnetometer(int handle, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_msb, x_lsb, y_msb, y_lsb, z_msb, z_lsb;

    if (read_register(handle, HMC5883L_DATA_X_MSB, &x_msb) < 0) return -1;
    if (read_register(handle, HMC5883L_DATA_X_LSB, &x_lsb) < 0) return -1;
    if (read_register(handle, HMC5883L_DATA_Y_MSB, &y_msb) < 0) return -1;
    if (read_register(handle, HMC5883L_DATA_Y_LSB, &y_lsb) < 0) return -1;
    if (read_register(handle, HMC5883L_DATA_Z_MSB, &z_msb) < 0) return -1;
    if (read_register(handle, HMC5883L_DATA_Z_LSB, &z_lsb) < 0) return -1;

    *x = (int16_t)((x_msb << 8) | x_lsb);
    *y = (int16_t)((y_msb << 8) | y_lsb);
    *z = (int16_t)((z_msb << 8) | z_lsb);
    return 0;
}

static int initialize_magnetometer(int handle) {
    uint8_t id;
    if (read_register(handle, HMC5883L_ID, &id) < 0) return -1;
    if (id != 0x12) {
        fprintf(stderr, "Invalid HMC5883L ID: 0x%02X (expected 0x12)\n", id);
        return -1;
    }

    if (write_register(handle, HMC5883L_CONFIG_A, 0x70) < 0) return -1;
    if (write_register(handle, HMC5883L_CONFIG_B, 0x20) < 0) return -1;
    if (write_register(handle, HMC5883L_MODE, 0x00) < 0) return -1;

    return 0;
}

static void calculate_offsets(int16_t *x_offsets, int16_t *y_offsets, int16_t *z_offsets, int num_samples) {
    double sum_x = 0.0, sum_y = 0.0, sum_z = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_x += x_offsets[i];
        sum_y += y_offsets[i];
        sum_z += z_offsets[i];
    }
    double avg_x = sum_x / num_samples;
    double avg_y = sum_y / num_samples;
    double avg_z = sum_z / num_samples;

    x_offsets[0] = (int16_t)avg_x;
    y_offsets[0] = (int16_t)avg_y;
    z_offsets[0] = (int16_t)avg_z;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_magnetometer(i2c_handle) < 0) {
        fprintf(stderr, "Error initializing HMC5883L\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int16_t x_offsets[HMC5883L_NUM_SAMPLES] = {0};
    int16_t y_offsets[HMC5883L_NUM_SAMPLES] = {0};
    int16_t z_offsets[HMC5883L_NUM_SAMPLES] = {0};
    int sample_count = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        int16_t raw_x, raw_y, raw_z;
        if (read_magnetometer(i2c_handle, &raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "Error reading magnetometer data\n");
            gpioDelay(500000);
            continue;
        }

        x_offsets[sample_count] = raw_x;
        y_offsets[sample_count] = raw_y;
        z_offsets[sample_count] = raw_z;
        sample_count++;

        if (sample_count >= HMC5883L_NUM_SAMPLES) {
            calculate_offsets(x_offsets, y_offsets, z_offsets, HMC5883L_NUM_SAMPLES);
            sample_count = 0;
        }

        gpioDelay(500000);
    }

    printf("Shutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

