#define THRESHOLD_REG_VAL   (THRESHOLD_LSB / 16)       /* 0x7D */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_line = NULL;

/* ---- Circular buffer ---- */
typedef struct {
    int16_t x, y, z;
} accel_sample_t;

static accel_sample_t g_buf[BUFFER_SIZE];
static int g_head = 0;
static int g_count = 0;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len)
{
    /* MSB of register address = 0x80 enables auto-increment (multi-byte read) */
    reg |= 0x80;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (block reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C block read from 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- LSM303D helpers ---- */
static int lsm303d_init(int fd)
{
    uint8_t who;
    if (i2c_read_reg8(fd, LSM303D_WHO_AM_I, &who) < 0)
        return -1;
    if (who != LSM303D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LSM303D_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: 50 Hz ODR, XYZ axes enabled (0x57) */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG1, 0x57) < 0)
        return -1;

    /* CTRL_REG4: full-scale +-2g (0x00) */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG4, 0x00) < 0)
        return -1;

    /* INT1_CFG: threshold 2 LSB (0x7D), duration 0 (immediate) */
    if (i2c_write_reg8(fd, LSM303D_INT1_CFG, THRESHOLD_REG_VAL) < 0)
        return -1;

    return 0;
}

static int lsm303d_read_accel(int fd, accel_sample_t *out)
{
    uint8_t raw[6];
    if (i2c_read_block(fd, LSM303D_OUT_X_L_A, raw, 6) < 0)
        return -1;

    /* LSM303D is little-endian: LSB first, then MSB */
    out->x = (int16_t)((raw[1] << 8) | raw[0]);
    out->y = (int16_t)((raw[3] << 8) | raw[2]);
    out->z = (int16_t)((raw[5] << 8) | raw[4]);
    return 0;
}

/* ---- GPIO interrupt event ---- */
