#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DELAY_MS      500
#define CONSUMER      "solenoid-actuator"

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SOLENOID_1_PIN);
    if (!line1) {
        perror("gpiod_chip_get_line(solenoid1)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SOLENOID_2_PIN);
    if (!line2) {
        perror("gpiod_chip_get_line(solenoid2)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially LOW (solenoids off) */
    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(solenoid1)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(solenoid2)");
        goto cleanup;
    }

    /* Main alternating sequence loop */
    while (running) {
        /* Energize solenoid 1 */
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("gpiod_line_set_value(solenoid1 ON)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("gpiod_line_set_value(solenoid2 OFF)");
            goto cleanup;
        }
        printf("Solenoid 1 ON\n");
        fflush(stdout);

        /* Sleep 500 ms, interruptible by signals */
        struct timespec ts = { .tv_sec = 0, .tv_nsec = DELAY_MS * 1000000L };
        while (nanosleep(&ts, &ts) < 0 && errno == EINTR && running)
            ;

        /* De-energize solenoid 1, energize solenoid 2 */
        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value(solenoid1 OFF)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value(solenoid2 ON)");
            goto cleanup;
        }
        printf("Solenoid 2 ON\n");
        fflush(stdout);

        /* Sleep 500 ms, interruptible */
        while (nanosleep(&ts, &ts) < 0 && errno == EINTR && running)
            ;
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure both solenoids are off on exit */
    if (line1) gpiod_line_set_value(line1, 0);
    if (line2) gpiod_line_set_value(line2, 0);
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip)  gpiod_chip_close(chip);
    return ret;
}

