#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

#define LOCK_1_GPIO 17
#define LOCK_2_GPIO 27
#define SERIAL_PORT_1 "/dev/serial0"
#define SERIAL_PORT_2 "/dev/serial1"
#define BAUD_RATE 9600
#define CODE_LENGTH 6
#define EXPECTED_CODE "123456"
#define UNLOCK_DURATION_MS 2000
#define READ_TIMEOUT_MS 5000
#define POLL_DELAY_US 100000

static volatile sig_atomic_t program_running = 1;
static int serial_port1_fd = -1;
static int serial_port2_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    gpioSetMode(LOCK_1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK_2_GPIO, PI_OUTPUT);
    gpioWrite(LOCK_1_GPIO, 0);
    gpioWrite(LOCK_2_GPIO, 0);
    return 0;
}

static int init_serial(const char *port, int *fd) {
    *fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (*fd < 0) {
        fprintf(stderr, "Error: Failed to open serial port %s: %s\n", port, strerror(errno));
        return -1;
    }
    struct termios options;
    if (tcgetattr(*fd, &options) != 0) {
        fprintf(stderr, "Error: tcgetattr failed on %s: %s\n", port, strerror(errno));
        close(*fd);
        *fd = -1;
        return -1;
    }
    cfsetispeed(&options, B9600);
    cfsetospeed(&options, B9600);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_oflag &= ~OPOST;
    if (tcsetattr(*fd, TCSANOW, &options) != 0) {
        fprintf(stderr, "Error: tcsetattr failed on %s: %s\n", port, strerror(errno));
        close(*fd);
        *fd = -1;
        return -1;
    }
    return 0;
}

static int read_code(int fd, char *code, size_t code_len) {
    size_t idx = 0;
    while (idx < code_len) {
        char ch;
        ssize_t n = read(fd, &ch, 1);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            fprintf(stderr, "Error: Serial read error on fd %d: %s\n", fd, strerror(errno));
            return -1;
        }
        if (n == 0) {
            continue;
        }
        if (n > 0 && (ch >= '0' && ch <= '9')) {
            code[idx++] = ch;
        } else {
            idx = 0;
            code[idx++] = '\0';
            fprintf(stderr, "Warning: Non-numeric character received on fd %d, resetting buffer.\n", fd);
        }
        if (idx == code_len) {
            code[idx] = '\0';
            return (int)idx;
        }
    }
    return (int)idx;
}

static int compare_codes(const char *code1, const char *code2) {
