#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_PIN      4
#define RELAY_PIN    17
#define CHIP_NAME    "gpiochip0"
#define POLL_MS      50
#define STRIKE_MS    1000
#define FAILSAFE_MS  10000

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(int priority, const char *msg) {
    syslog(priority, "%s", msg);
}

static void log_event_with_val(int priority, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    char buf[512];
    vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);
    syslog(priority, "%s", buf);
}

int main(void) {
    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_event(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        log_event(LOG_ERR, "Failed to open %s: %s", CHIP_NAME, strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *pir = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir) {
        log_event(LOG_ERR, "Failed to get PIR line %d: %s", PIR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *relay = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay) {
        log_event(LOG_ERR, "Failed to get relay line %d: %s", RELAY_PIN, strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(pir, "door_strike_pir") < 0) {
        log_event(LOG_ERR, "Failed to request PIR line as input: %s", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(relay, "door_strike_relay", 0) < 0) {
        log_event(LOG_ERR, "Failed to request relay line as output: %s", strerror(errno));
        goto cleanup;
    }

    log_event(LOG_INFO, "Door strike controller started (PIR=GPIO%d, Relay=GPIO%d)", PIR_PIN, RELAY_PIN);

    int relay_on = 0;
    time_t failsafe_start = 0;

    while (running) {
        int val = gpiod_line_get_value(pir);
        if (val < 0) {
            log_event(LOG_ERR, "Failed to read PIR: %s", strerror(errno));
            usleep(POLL_MS * 1000);
            continue;
        }

        if (val == 1) {
            if (!relay_on) {
                if (gpiod_line_set_value(relay, 1) < 0) {
                    log_event(LOG_ERR, "Failed to energize relay: %s", strerror(errno));
                } else {
                    relay_on = 1;
                    log_event(LOG_INFO, "Motion detected, relay energized");
                }
            }

            failsafe_start = time(NULL);

            for (int elapsed = 0; elapsed < FAILSAFE_MS && running; elapsed += POLL_MS) {
                usleep(POLL_MS * 1000);
            }

            if (!running) break;

            if (relay_on) {
                if (gpiod_line_set_value(relay, 0) < 0) {
                    log_event(LOG_ERR, "Failed to de-energize relay: %s", strerror(errno));
                } else {
                    relay_on = 0;
                    log_event(LOG_INFO, "Relay de-energized");
                }
            }
        } else {
            if (relay_on) {
                if (gpiod_line_set_value(relay, 0) < 0) {
                    log_event(LOG_ERR, "Failed to de-energize relay: %s", strerror(errno));
                } else {
                    relay_on = 0;
                    log_event(LOG_INFO, "Relay de-energized");
                }
            }
        }

        if (relay_on) {
            time_t now = time(NULL);
            if (difftime(now, failsafe_start) >= FAILSAFE_MS) {
                log_event(LOG_WARNING, "PIR sensor HIGH for >10s - potential malfunction, de-energizing relay");
                if (gpiod_line_set_value(relay, 0) < 0) {
                    log_event(LOG_ERR, "Failed to de-energize relay on failsafe: %s", strerror(errno));
                } else {
                    relay_on = 0;
                    log_event(LOG_INFO, "Failsafe triggered, relay de-energized");
                }
            }
        }
    }

    log_event(LOG_INFO, "Shutting down");

cleanup:
    if (relay) {
        gpiod_line_set_value(relay, 0);
        gpiod_line_release(relay);
    }
    if (pir) gpiod_line_release(pir);
    gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}

