#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

#define ACTIVATION_TIME_SEC 300
#define PAUSE_TIME_SEC     60
#define TIMER_ID           0

static volatile sig_atomic_t program_running = 1;
static volatile sig_atomic_t timer_fired = 0;
static volatile int current_relay = 0;

static const int relay_gpios[] = {RELAY1_GPIO, RELAY2_GPIO, RELAY3_GPIO, RELAY4_GPIO};
static const int num_relays = 4;

static void log_event(int relay_gpio, const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "[%s] Relay GPIO %d: %s", timestamp, relay_gpio, event);
}

static void relay_on(int relay_gpio) {
    if (gpioWrite(relay_gpio, 0) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d HIGH (relay ON)", relay_gpio);
        return;
    }
    log_event(relay_gpio, "ACTIVATED");
}

static void relay_off(int relay_gpio) {
    if (gpioWrite(relay_gpio, 1) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d LOW (relay OFF)", relay_gpio);
        return;
    }
    log_event(relay_gpio, "DEACTIVATED");
}

static void timer_callback(void *userdata) {
    (void)userdata;
    timer_fired = 1;
}

static void cleanup(void) {
    for (int i = 0; i < num_relays; i++) {
        gpioWrite(relay_gpios[i], 1);
    }
    gpioTerminate();
    closelog();
}

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_relays; i++) {
        if (gpioSetMode(relay_gpios[i], PI_OUTPUT) != 0) {
            syslog(LOG_ERR, "Failed to set GPIO %d as output", relay_gpios[i]);
            gpioTerminate();
            closelog();
            return EXIT_FAILURE;
        }
        if (gpioWrite(relay_gpios[i], 1) != 0) {
            syslog(LOG_ERR, "Failed to initialize GPIO %d to HIGH", relay_gpios[i]);
            gpioTerminate();
            closelog();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetTimerFuncEx(TIMER_ID, 0, timer_callback, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set timer 0");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handlers");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    log_event(RELAY1_GPIO, "System started");

    while (program_running) {
        if (timer_fired) {
            timer_fired = 0;
            current_relay = (current_relay + 1) % num_relays;
            relay_on(relay_gpios[current_relay]);
            for (int i = 0; i < ACTIVATION_TIME_SEC && program_running; i += PAUSE_TIME_SEC / 10) {
                gpioDelay(PAUSE_TIME_SEC * 1000000);
            }
            relay_off(relay_gpios[current_relay]);
        }
        gpioDelay(100000);
    }

    log_event(RELAY1_GPIO, "System shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

