#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <sys/timerfd.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define I2C_BUS "/dev/i2c-1"
#define ACCEL_XOUT_H 0x3B
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 100
#define SAMPLE_PERIOD_NS (1000000000L / SAMPLE_RATE_HZ)

typedef struct {
    float x, y, z;
} AccelData;

typedef struct {
    AccelData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int sysfs_fd = -1;
static CircularBuffer buffer;
static timer_t timer_id;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg8(fd, ACCEL_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_accel(int fd, AccelData *out) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) < 0) return -1;
    int16_t x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t z = (int16_t)((buf[4] << 8) | buf[5]);
    out->x = (float)x / 16384.0f;
    out->y = (float)y / 16384.0f;
    out->z = (float)z / 16384.0f;
    return 0;
}

static void buffer_add(CircularBuffer *b, AccelData d) {
    b->data[b->head] = d;
    b->head = (b->head + 1) % BUFFER_SIZE;
    if (b->count < BUFFER_SIZE) b->count++;
}

static int sysfs_write(const char *path, const char *val) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    if (write(fd, val, strlen(val)) < 0) {
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int sysfs_read(const char *path, char *buf, size_t len) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) return -1;
    ssize_t n = read(fd, buf, len - 1);
    close(fd);
    if (n < 0) return -1;
    buf[n] = '\0';
    return 0;
}

static void timer_callback(int sig, struct itimerspec *spec, void *user) {
    (void)sig; (void)user;
    AccelData d;
    if (read_accel(i2c_fd, &d) < 0) return;
    buffer_add(&buffer, d);
    struct itimerspec next;
    memset(&next, 0, sizeof(next));
    next.it_value.tv_sec = 0;
    next.it_value.tv_nsec = SAMPLE_PERIOD_NS;
    next.it_interval.tv_sec = 0;
    next.it_interval.tv_nsec = SAMPLE_PERIOD_NS;
    timerfd_settime(timer_id, 0, &next, NULL);
}

static void cleanup(void) {
    if (sysfs_fd >= 0) {
        char path[128];
        snprintf(path, sizeof(path), "/sys/kernel/mpu6050_accel/latest");
        sysfs_write(path, "0,0,0");
        snprintf(path, sizeof(path), "/sys/kernel/mpu6050_accel/head");
        sysfs_write(path, "0");
        snprintf(path, sizeof(path), "/sys/kernel/mpu6050_accel/count");
        sysfs_write(path, "0");
        close(sysfs_fd);
        sysfs_fd = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    timerfd_close(timer_id);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 init failed (sensor absent or bus error)\n");
        close(i2c_fd);
        return 1;
    }

    sysfs_fd = open("/sys/kernel/mpu6050_accel/head", O_WRONLY);
    if (sysfs_fd < 0) {
        fprintf(stderr, "Failed to open sysfs head: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    memset(&buffer, 0, sizeof(buffer));

    struct sigevent sev;
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    sev.sigev_value.sival_ptr = &timer_id;

    if (timerfd_create(CLOCK_MONOTONIC, &timer_id) < 0) {
        fprintf(stderr, "timerfd_create failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (timerfd_settime(timer_id, 0, &sev, NULL) < 0) {
        fprintf(stderr, "timerfd_settime failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("MPU6050 logging started. Press Ctrl+C to stop.\n");
    while (running) {
        struct itimerspec now;
        memset(&now, 0, sizeof(now));
        now.it_value.tv_sec = 1;
        now.it_value.tv_nsec = 0;
        now.it_interval.tv_sec = 0;
        now.it_interval.tv_nsec = 0;
        if (timerfd_settime(timer_id, 0, &now, NULL) < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "timerfd_settime failed: %s\n", strerror(errno));
            break;
        }
    }
    cleanup();
    printf("Exited cleanly.\n");
    return 0;
}

