#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define RELAY_PINS {18, 23, 24, 25}
#define NUM_RELAYS 4
#define INTERVALS {2, 3, 5, 7}
#define NUM_INTERVALS (sizeof(INTERVALS) / sizeof(INTERVALS[0]))

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_signal_handlers(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int pins[NUM_RELAYS] = RELAY_PINS;
    int ret = EXIT_FAILURE;

    if (setup_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "smart-lighting", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output\n", pins[i]);
            goto cleanup;
        }
    }

    struct timespec last_toggle[NUM_RELAYS];
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (clock_gettime(CLOCK_MONOTONIC, &last_toggle[i]) == -1) {
            perror("clock_gettime");
            goto cleanup;
        }
    }

    while (running) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            struct timespec now;
            if (clock_gettime(CLOCK_MONOTONIC, &now) == -1) {
                perror("clock_gettime");
                goto cleanup;
            }

            long elapsed_ns = (now.tv_sec - last_toggle[i].tv_sec) * 1000000000L +
                              (now.tv_nsec - last_toggle[i].tv_nsec);

            if (elapsed_ns >= (long)INTERVALS[i] * 1000000000L) {
                if (gpiod_line_set_value(lines[i], 1) < 0) {
                    perror("gpiod_line_set_value");
                    goto cleanup;
                }
                last_toggle[i] = now;
                printf("Light %d toggled ON\n", i + 1);
            }
        }
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

