        }
    }

    struct timespec last_toggle[NUM_RELAYS];
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (clock_gettime(CLOCK_MONOTONIC, &last_toggle[i]) == -1) {
            perror("clock_gettime");
            goto cleanup;
        }
    }

    while (running) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            struct timespec now;
            if (clock_gettime(CLOCK_MONOTONIC, &now) == -1) {
                perror("clock_gettime");
                goto cleanup;
            }

            long elapsed_ns = (now.tv_sec - last_toggle[i].tv_sec) * 1000000000L +
                              (now.tv_nsec - last_toggle[i].tv_nsec);

            if (elapsed_ns >= (long)INTERVALS[i] * 1000000000L) {
                if (gpiod_line_set_value(lines[i], 1) < 0) {
                    perror("gpiod_line_set_value");
                    goto cleanup;
                }
                last_toggle[i] = now;
                printf("Light %d toggled ON\n", i + 1);
            }
        }
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

