#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define WHO_AM_I     0x75
#define GYRO_XOUT_H  0x43

// Expected WHO_AM_I value
#define MPU6050_WHO_AM_I 0x68

// Gyroscope sensitivity for +-250 dps range (LSB/deg/s)
#define GYRO_SENSITIVITY 131.0

// Angular velocity threshold (degrees/second)
#define ANGULAR_VELOCITY_THRESHOLD 50.0

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
static int i2c_fd = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t running = 1;

// Function prototypes
int init_i2c();
int init_mpu6050();
int read_gyro_data(gyro_data_t *data);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
void check_threshold(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

// Initialize I2C communication
int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Initialize the MPU-6050
int init_mpu6050() {
    // Verify device identity
    int who_am_i = i2c_read_byte_data(i2c_fd, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != MPU6050_WHO_AM_I) {
        fprintf(stderr, "MPU-6050 not found. WHO_AM_I returned 0x%02X, expected 0x%02X\n", who_am_i, MPU6050_WHO_AM_I);
        return -1;
    }

    // Wake up the MPU-6050 (clear sleep bit in PWR_MGMT_1)
    int status = i2c_write_byte_data(i2c_fd, PWR_MGMT_1, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }

    // Allow time for the sensor to stabilize
    usleep(100000); // 100ms

    return 0;
}

// Read gyroscope data from the MPU-6050
int read_gyro_data(gyro_data_t *data) {
    char buffer[6];
    int status = i2c_read_i2c_block_data(i2c_fd, GYRO_XOUT_H, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading gyroscope data: %s\n", strerror(errno));
        return -1;
    }
    if (status != 6) {
        fprintf(stderr, "Error reading gyroscope data: expected 6 bytes, got %d\n", status);
        return -1;
    }

    // Combine high and low bytes, convert to signed 16-bit integers
    int16_t gyro_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t gyro_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t gyro_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert to degrees/second
    data->x = (float)gyro_x / GYRO_SENSITIVITY;
    data->y = (float)gyro_y / GYRO_SENSITIVITY;
    data->z = (float)gyro_z / GYRO_SENSITIVITY;

    return 0;
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Check if the angular velocity exceeds the threshold
void check_threshold(gyro_data_t data) {
    float magnitude = sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
    if (magnitude > ANGULAR_VELOCITY_THRESHOLD) {
        printf("Threshold exceeded! Magnitude: %.2f deg/s\n", magnitude);
    }
}

int main() {
    // Initialize circular buffer
    init_circular_buffer(&gyro_buffer);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("MPU-6050 Gyroscope Data Acquisition\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gyro_data_t gyro_data;

        if (read_gyro_data(&gyro_data) == 0) {
            add_to_buffer(&gyro_buffer, gyro_data);
            check_threshold(gyro_data);
        } else {
            fprintf(stderr, "Error reading gyroscope data. Retrying...\n");
        }

        usleep(10000); // 10ms delay
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

