/*
 * MH-Z19B CO2 sensor reader for Raspberry Pi 3 Model B+
 * UART: /dev/serial0 (TXD=GPIO14, RXD=GPIO15) at 9600 baud
 * Command: {0xFF,0x01,0x86,0x00,0x00,0x00,0x00,0x00,0x79}
 * Response: 9 bytes: [cmd_len][crc_lo][crc_hi][byte_count][byte_sum_lo][byte_sum_hi][co2_msb][co2_lsb][checksum]
 * CO2 = (response[2] << 8) | response[3]
 * Checksum: (sum(bytes 1-7) + 1) & 0xFF
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE    "/dev/serial0"
#define BAUD_RATE      9600
#define READ_INTERVAL  5
#define READ_TIMEOUT   1000000  /* microseconds */
#define RESP_LEN       9
#define CMD_LEN        9
#define LOG_FILE       "co2_log.json"
#define ERR_FILE       "co2_error.log"

static volatile sig_atomic_t g_running = 1;
static int  g_uart_handle = -1;
static FILE *g_log_fp     = NULL;
static FILE *g_err_fp     = NULL;

/* ------------------------------------------------------------------ */
/* Logging helpers                                                     */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    if (!g_err_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(g_err_fp, "%04d-%02d-%02d %02d:%02d:%02d ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(g_err_fp);
}

static void log_data(uint32_t co2_ppm, int error)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    if (g_log_fp) {
        fprintf(g_log_fp,
                "{\"timestamp\":\"%s\",\"co2_ppm\":%u,\"error\":%d}\n",
                ts, co2_ppm, error);
        fflush(g_log_fp);
    }
    printf("{\"timestamp\":\"%s\",\"co2_ppm\":%u,\"error\":%d}\n",
           ts, co2_ppm, error);
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MH-Z19B read                                                       */
/* ------------------------------------------------------------------ */
static int read_mh_z19b(uint16_t *co2_ppm)
{
    uint8_t cmd[CMD_LEN] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};
    uint8_t resp[RESP_LEN];
    int     elapsed = 0;

    /* Send command */
    if (serWrite(g_uart_handle, (char *)cmd, CMD_LEN) != CMD_LEN) {
        log_error("serWrite failed");
        return -1;
    }

    /* Wait for response (sensor needs ~100 ms) */
    while (elapsed < READ_TIMEOUT) {
        gpioDelay(1000);  /* 1 ms */
        elapsed += 1000;
        if (serDataAvailable(g_uart_handle) >= RESP_LEN)
            break;
    }
    if (elapsed >= READ_TIMEOUT) {
        log_error("Timeout waiting for sensor response");
        return -1;
    }

    /* Read response */
    int total = 0;
    while (total < RESP_LEN) {
        int n = serRead(g_uart_handle, (char *)(resp + total), RESP_LEN - total);
        if (n < 0) {
            log_error("serRead failed");
            return -1;
        }
        total += n;
    }

    /* Validate checksum */
    uint8_t crc = 0;
    for (int i = 1; i < RESP_LEN - 1; i++)
        crc += resp[i];
    uint8_t expected = (crc + 1) & 0xFF;
    if (resp[RESP_LEN - 1] != expected) {
        log_error("Checksum mismatch");
        return -1;
    }

    /* Parse CO2 */
    *co2_ppm = ((uint16_t)resp[2] << 8) | resp[3];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_uart_handle >= 0) {
        serClose(g_uart_handle);
        g_uart_handle = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_err_fp) {
        fclose(g_err_fp);
        g_err_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Open error log */
    g_err_fp = fopen(ERR_FILE, "a");
    if (!g_err_fp) {
        perror("fopen(" ERR_FILE ")");
        return EXIT_FAILURE;
    }

    /* Open UART */
    g_uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (g_uart_handle < 0) {
        log_error("serOpen failed");
        fclose(g_err_fp);
        return EXIT_FAILURE;
    }

    /* Open data log */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        serClose(g_uart_handle);
        fclose(g_err_fp);
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MH-Z19B CO2 monitor started. Logging to %s every %d s.\n",
           LOG_FILE, READ_INTERVAL);

    while (g_running) {
        uint16_t co2 = 0;
        int rc = read_mh_z19b(&co2);

        if (rc == 0) {
            log_data(co2, 0);
        } else {
            log_data(0, 1);
        }

        /* Sleep READ_INTERVAL seconds, but wake early on signal */
        for (int i = 0; i < READ_INTERVAL && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

