#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

#define HMC5883L_ADDR 0x1E
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_ID 0x0C
#define HMC5883L_ID_VAL 0x03
#define HMC5883L_DATA_LEN 6
#define TARGET_HEADING 90.0
#define DEVIATION_THRESHOLD 10.0
#define CIRCULAR_BUFFER_SIZE 100
#define SAMPLE_INTERVAL_US 100000
#define I2C_BUS 1

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    time_t timestamp;
    float heading;
} heading_data_t;

static heading_data_t circular_buffer[CIRCULAR_BUFFER_SIZE];
static int buffer_index = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_hmc5883l(void) {
    int id = i2cReadByteData(i2c_handle, HMC5883L_ID);
    if (id < 0) {
        fprintf(stderr, "Error reading HMC5883L ID register: %d\n", id);
        return -1;
    }
    if (id != HMC5883L_ID_VAL) {
        fprintf(stderr, "HMC5883L ID mismatch: got 0x%02X, expected 0x%02X\n", id, HMC5883L_ID_VAL);
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing CONFIG_A\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing CONFIG_B\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing MODE\n");
        return -1;
    }
    return 0;
}

static int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char data[HMC5883L_DATA_LEN];
    int result = i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, data, HMC5883L_DATA_LEN);
    if (result != HMC5883L_DATA_LEN) {
        fprintf(stderr, "Error reading magnetometer data: %d\n", result);
        return -1;
    }
    *x = (int16_t)((data[0] << 8) | data[1]);
    *z = (int16_t)((data[2] << 8) | data[3]);
    *y = (int16_t)((data[4] << 8) | data[5]);
    return 0;
}

static float compensate_heading(int16_t x, int16_t y) {
    float heading = atan2f((float)y, (float)x) * 180.0f / M_PI;
    if (heading < 0) {
        heading += 360.0f;
    }
    return heading + 100.0f;
}

static void control_servo(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

static void log_heading(float heading) {
    time_t now = time(NULL);
    circular_buffer[buffer_index].timestamp = now;
    circular_buffer[buffer_index].heading = heading;
    buffer_index = (buffer_index + 1) % CIRCULAR_BUFFER_SIZE;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(17, PI_OUTPUT);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int16_t x, y, z;
    float heading;

    while (!terminate) {
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            heading = compensate_heading(x, y);
            log_heading(heading);

            if (fabs(heading - TARGET_HEADING) > DEVIATION_THRESHOLD) {
                control_servo(17, 1);
            } else {
                control_servo(17, 0);
            }
        } else {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    control_servo(17, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

