#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define RED_PIN    17
#define GREEN_PIN  27
#define BLUE_PIN   22
#define I2C_BUS    "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define LOG_FILE   "lighting_log.txt"
#define CONV_TIME_MS 120

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int bh1750_read_lux(int fd, float *lux) {
    unsigned char cmd = 0x10;
    unsigned char buf[2];

    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "BH1750 write failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(CONV_TIME_MS * 1000);

    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "BH1750 read failed: %s\n", strerror(errno));
        return -1;
    }
    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static void set_relay(struct gpiod_line *line, int pin, int state) {
    if (gpiod_line_set_value(line, state) < 0) {
        fprintf(stderr, "Failed to set GPIO %d: %s\n", pin, strerror(errno));
    }
}

static void log_data(FILE *fp, float lux, int red, int green, int blue) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
