#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define DISTANCE_MIN 10
#define DISTANCE_MAX 100
#define DISTANCE_THRESHOLD 50
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_motor_pwm(int in1, int in2, int pwm_value) {
    if (gpioPWM(in1, 0) < 0) return -1;
    if (gpioWrite(in2, pwm_value > 0 ? 1 : 0) < 0) return -1;
    return 0;
}

static int set_motor_direction(int in1, int in2, int direction) {
    if (direction == 0) {
        if (gpioWrite(in1, 0) < 0) return -1;
        if (gpioWrite(in2, 0) < 0) return -1;
        return 0;
    }
    if (gpioWrite(in1, 1) < 0) return -1;
    if (gpioWrite(in2, 1) < 0) return -1;
    return 0;
}

static int map_distance_to_pwm(int distance) {
    if (distance <= DISTANCE_MIN) return PWM_RANGE;
    if (distance >= DISTANCE_MAX) return 0;
    return PWM_RANGE - (int)(((float)(distance - DISTANCE_MIN) / (DISTANCE_MAX - DISTANCE_MIN)) * PWM_RANGE);
}

static int control_motor(int in1, int in2, int distance) {
    int pwm_value = map_distance_to_pwm(distance);
    if (set_motor_pwm(in1, in2, pwm_value) < 0) return -1;
    if (distance < DISTANCE_THRESHOLD) {
        if (set_motor_direction(in1, in2, 1) < 0) return -1;
    } else {
        if (set_motor_direction(in1, in2, 0) < 0) return -1;
    }
    return 0;
}

