#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define IN1 17
#define IN2 18
#define IN3 27
#define IN4 22
#define BUTTON_LOCK 24
#define BUTTON_UNLOCK 23
#define STEPS_PER_REV 512
#define STEP_DELAY_US 2000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int deenergize(void) {
    return safe_write(IN1, 0) && safe_write(IN2, 0) &&
           safe_write(IN3, 0) && safe_write(IN4, 0);
}

static int rotate_cw(int steps) {
    for (int i = 0; i < steps; i++) {
        if (!running) return -1;
        if (safe_write(IN1, 1) < 0) return -1;
        if (safe_write(IN2, 0) < 0) return -1;
        if (safe_write(IN3, 0) < 0) return -1;
        if (safe_write(IN4, 0) < 0) return -1;
        gpioDelay(STEP_DELAY_US);
        if (!running) return -1;
        if (safe_write(IN1, 0) < 0) return -1;
        if (safe_write(IN2, 1) < 0) return -1;
        if (safe_write(IN3, 0) < 0) return -1;
        if (safe_write(IN4, 0) < 0) return -1;
        gpioDelay(STEP_DELAY_US);
    }
    return 0;
}

static int rotate_ccw(int steps) {
    for (int i = 0; i < steps; i++) {
        if (!running) return -1;
        if (safe_write(IN1, 0) < 0) return -1;
        if (safe_write(IN2, 0) < 0) return -1;
        if (safe_write(IN3, 1) < 0) return -1;
        if (safe_write(IN4, 0) < 0) return -1;
        gpioDelay(STEP_DELAY_US);
        if (!running) return -1;
        if (safe_write(IN1, 0) < 0) return -1;
        if (safe_write(IN2, 0) < 0) return -1;
        if (safe_write(IN3, 0) < 0) return -1;
        if (safe_write(IN4, 1) < 0) return -1;
        gpioDelay(STEP_DELAY_US);
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_set_mode(IN1, PI_OUTPUT) < 0 ||
        safe_set_mode(IN2, PI_OUTPUT) < 0 ||
        safe_set_mode(IN3, PI_OUTPUT) < 0 ||
        safe_set_mode(IN4, PI_OUTPUT) < 0 ||
        safe_set_mode(BUTTON_LOCK, PI_INPUT) < 0 ||
        safe_set_mode(BUTTON_UNLOCK, PI_INPUT) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(BUTTON_LOCK, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(BUTTON_UNLOCK, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (deenergize() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Automatic Door Lock System\n");
    printf("Press the lock button (GPIO24) to lock.\n");
    printf("Press the unlock button (GPIO23) to unlock.\n");
    printf("Press Ctrl+C to exit.\n");

    int lock_steps = STEPS_PER_REV;
    int unlock_steps = STEPS_PER_REV;
    int last_lock_state = 0;
    int last_unlock_state = 0;

    while (running) {
        if (gpioRead(BUTTON_LOCK) == 0 && !last_lock_state) {
            printf("Locking...\n");
            if (rotate_cw(lock_steps) == 0) {
                printf("Door locked.\n");
            } else {
                fprintf(stderr, "Error: lock rotation failed\n");
            }
