#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PITCH_THRESHOLD 15.0
#define ROLL_THRESHOLD 15.0
#define PWM_CHIP 2
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 10000000
#define PWM_DUTY_MAX 8000000
#define PWM_DUTY_MIN 2000000
#define PWM_DUTY_CENTER 5000000
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180
#define LOG_FILE "solar_tracker.log"
#define SAMPLE_DELAY_US 100000
#define MAX_RETRIES 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int pwm_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

int init_mpu6050(int fd) {
    uint8_t whoami;
    if (i2c_read_reg8(fd, 0x75, &whoami) < 0) return -1;
    if (whoami != 0x68) return -1;
    if (i2c_write_reg8(fd, 0x1A, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x1B, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x1F, 0x00) < 0) return -1;
    return 0;
}

int read_accel_data(int fd, float *ax, float *ay, float *az) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, 0x3B, buf, 6) < 0) return -1;
    int16_t raw_ax = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_ay = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_az = (int16_t)((buf[4] << 8) | buf[5]);
    *ax = (float)raw_ax / 16384.0f;
    *ay = (float)raw_ay / 16384.0f;
    *az = (float)raw_az / 16384.0f;
    return 0;
}

int read_gyro_data(int fd, float *gx, float *gy, float *gz) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, 0x43, buf, 6) < 0) return -1;
    int16_t raw_gx = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_gy = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_gz = (int16_t)((buf[4] << 8) | buf[5]);
    *gx = (float)raw_gx / 131.0f;
    *gy = (float)raw_gy / 131.0f;
    *gz = (float)raw_gz / 131.0f;
    return 0;
}

int init_pwm(void) {
    char path[256];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d", PWM_CHIP, PWM_CHANNEL);
    pwm_fd = open(path, O_WRONLY);
    if (pwm_fd < 0) {
        fprintf(stderr, "Failed to open PWM export: %s\n", strerror(errno));
        return -1;
    }
    char export_path[256];
    snprintf(export_path, sizeof(export_path), "/sys/class/pwm/pwmchip%d/export", PWM_CHIP);
    int written = write(pwm_fd, "0", 1);
    if (written < 0) {
        fprintf(stderr, "Failed to export PWM: %s\n", strerror(errno));
        close(pwm_fd);
        pwm_fd = -1;
        return -1;
    }
    if (written == 0) {
        fprintf(stderr, "PWM already exported\n");
    }
    usleep(100000);
    char period_path[256];
    snprintf(period_path, sizeof(period_path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_CHANNEL);
    char duty_path[256];
    snprintf(duty_path, sizeof(duty_path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    char enable_path[256];
    snprintf(enable_path, sizeof(enable_path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
    FILE *fp = fopen(period_path, "w");
    if (fp) {
        fprintf(fp, "%d", PWM_PERIOD_NS);
        fclose(fp);
    }
    fp = fopen(duty_path, "w");
    if (fp) {
        fprintf(fp, "%d", PWM_DUTY_CENTER);
        fclose(fp);
    }
    fp = fopen(enable_path, "w");
    if (fp) {
        fprintf(fp, "1");
        fclose(fp);
    }
    return 0;
}

int set_servo_angle(int angle) {
    if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) return -1;
    int duty = PWM_DUTY_CENTER + (angle - SERVO_MIN_ANGLE) * (PWM_DUTY_MAX - PWM_DUTY_CENTER) / (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE);
    char duty_path[256];
    snprintf(duty_path, sizeof(duty_path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    FILE *fp = fopen(duty_path, "w");
    if (!fp) return -1;
    fprintf(fp, "%d", duty);
    fclose(fp);
    return 0;
}

int log_data(float pitch, float roll, int servo_angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return -1;
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, servo_angle);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU-6050\n");
        close(i2c_fd);
        return 1;
    }
    if (init_pwm() < 0) {
        fprintf(stderr, "Failed to initialize PWM\n");
        close(i2c_fd);
        return 1;
    }

    float pitch = 0.0f, roll = 0.0f;
    int servo_angle = 90;
    int pwm_duty = PWM_DUTY_CENTER;

    while (running) {
        float ax, ay, az, gx, gy, gz;
        int retries = 0;
        int success = 0;
        while (retries < MAX_RETRIES && !success) {
            if (read_accel_data(i2c_fd, &ax, &ay, &az) == 0 && read_gyro_data(i2c_fd, &gx, &gy, &gz) == 0) {
                success = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "I2C read error (attempt %d/%d): %s\n", retries, MAX_RETRIES, strerror(errno));
                    usleep(10000 << retries);
                }
            }
        }
        if (!success) {
            fprintf(stderr, "Max retries reached, skipping sample\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }
        pitch += ax * 0.1f;
        roll += ay * 0.1f;
        if (fabs(pitch) > PITCH_THRESHOLD || fabs(roll) > ROLL_THRESHOLD) {
            if (fabs(pitch) > fabs(roll)) {
                servo_angle = SERVO_MAX_ANGLE;
            } else {
                servo_angle = SERVO_MIN_ANGLE;
            }
        } else {
            servo_angle = 90;
        }
        if (servo_angle < 0) servo_angle = 0;
        if (servo_angle > 180) servo_angle = 180;
        if (servo_angle != PWM_DUTY_CENTER) {
            if (set_servo_angle(servo_angle) < 0) {
                fprintf(stderr, "Failed to set servo angle\n");
            } else {
                pwm_duty = servo_angle;
            }
        }
        if (log_data(pitch, roll, servo_angle) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }
        usleep(SAMPLE_DELAY_US);
    }

    if (pwm_fd >= 0) {
        set_servo_angle(90);
        usleep(100000);
        close(pwm_fd);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

