#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY_1_PIN 4
#define RELAY_2_PIN 17
#define RELAY_3_PIN 27
#define RELAY_4_PIN 22
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define FADE_DURATION 1800
#define SLEEP_INTERVAL 1
#define MAX_SCHEDULE_ENTRIES 100

typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int state;
} ScheduleEntry;

static volatile sig_atomic_t running = 1;
static ScheduleEntry schedule[MAX_SCHEDULE_ENTRIES];
static int schedule_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_schedule(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp) && schedule_count < MAX_SCHEDULE_ENTRIES) {
        int relay;
        int state;
        if (sscanf(line, "%d:%d:%d,%d,%d",
                   &schedule[schedule_count].hour,
                   &schedule[schedule_count].minute,
                   &schedule[schedule_count].second,
                   &relay, &state) == 5) {
            if (relay >= 1 && relay <= 4) {
                schedule[schedule_count].relay_number = relay;
                schedule[schedule_count].state = state;
                schedule_count++;
            } else {
                fprintf(stderr, "Invalid relay number %d in schedule\n", relay);
            }
        } else {
            fprintf(stderr, "Invalid schedule entry: %s", line);
        }
    }

    fclose(fp);
    return 0;
}

static int is_time_in_schedule(int current_hour, int current_minute, int current_second) {
    for (int i = 0; i < schedule_count; i++) {
        if (schedule[i].hour == current_hour &&
            schedule[i].minute == current_minute &&
            schedule[i].second == current_second &&
            schedule[i].relay_number == 1) {
            return schedule[i].state;
        }
    }
    return 0;
}

static void set_relay_state(int relay_pin, int state) {
    if (gpioPWM(relay_pin, state ? PWM_RANGE : 0) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", relay_pin);
    }
}

static void fade_lamp(int relay_pin, int target_state) {
    int current_state = gpioGetPWMdutycycle(relay_pin);
    if (current_state < 0) {
        fprintf(stderr, "Failed to get PWM duty cycle on GPIO %d\n", relay_pin);
        return;
    }

    int step_size = (target_state == current_state) ? -1 : 1;
    int duration_us = FADE_DURATION * 1000000;
    int elapsed_us = 0;

    while (elapsed_us < duration_us && running) {
        current_state += step_size;
        if (current_state < 0) current_state = 0;
        if (current_state > PWM_RANGE) current_state = PWM_RANGE;

        if (gpioPWM(relay_pin, current_state) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", relay_pin);
            return;
        }

        gpioDelay(1000);
        elapsed_us += 1000;
    }

    if (gpioPWM(relay_pin, target_state ? PWM_RANGE : 0) != 0) {
        fprintf(stderr, "Failed to set final PWM on GPIO %d\n", relay_pin);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int pins[] = {RELAY_1_PIN, RELAY_2_PIN, RELAY_3_PIN, RELAY_4_PIN};
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", pins[i]);
            gpioTerminate();
            return 1;
        }
        set_relay_state(pins[i], 0);
    }

    if (read_schedule("lighting_schedule.txt") != 0) {
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handler");
        gpioTerminate();
        return 1;
    }

    time_t current_time;
    time(&current_time);
    struct tm *time_info = localtime(&current_time);
    if (!time_info) {
        perror("Failed to get local time");
        gpioTerminate();
        return 1;
    }

    int current_hour = time_info->tm_hour;
    int current_minute = time_info->tm_min;
    int current_second = time_info->tm_sec;

    while (running) {
        if (is_time_in_schedule(current_hour, current_minute, current_second)) {
            int target_state = is_time_in_schedule(current_hour, current_minute, current_second);
            for (int i = 0; i < 4; i++) {
                if (gpioGetMode(pins[i]) == PI_OUTPUT) {
                    fade_lamp(pins[i], target_state);
                }
            }
        }

        current_time += SLEEP_INTERVAL;
        time_info = localtime(&current_time);
        if (time_info) {
            current_hour = time_info->tm_hour;
            current_minute = time_info->tm_min;
            current_second = time_info->tm_sec;
        } else {
            fprintf(stderr, "Failed to update current time\n");
        }

        gpioDelay(SLEEP_INTERVAL * 1000000);
    }

    set_relay_state(RELAY_1_PIN, 0);
    set_relay_state(RELAY_2_PIN, 0);
    set_relay_state(RELAY_3_PIN, 0);
    set_relay_state(RELAY_4_PIN, 0);
    gpioTerminate();
    return 0;
}

