#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE "vibration_events.log"
#define WINDOW_SIZE 5
#define DEFAULT_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(FILE *log_file, int value) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s, Value: %d\n", timestamp, value) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(log_file) == EOF) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }

    if (fsync(fileno(log_file)) == -1) {
        fprintf(stderr, "fsync failed: %s\n", strerror(errno));
    }
}

static int check_earthquake_alert(int value, int *window, int *index, int window_size) {
    window[*index] = value;
    *index = (*index + 1) % window_size;

    int count = 0;
    for (int i = 0; i < window_size; i++) {
        if (window[i] == 1) {
            count++;
        }
    }
    return (count >= 3) ? 1 : 0;
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_file = NULL;
    int timeout_ms = DEFAULT_TIMEOUT_MS;
    int ret = EXIT_FAILURE;

    if (argc > 1) {
        timeout_ms = atoi(argv[1]);
        if (timeout_ms <= 0) {
            fprintf(stderr, "Invalid timeout value: %s\n", argv[1]);
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    if (gpiod_line_request_input(line, "sw420-vibration") < 0) {
