#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE "vibration_events.log"
#define WINDOW_SIZE 5
#define DEFAULT_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(FILE *log_file, int value) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s, Value: %d\n", timestamp, value) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(log_file) == EOF) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }

    if (fsync(fileno(log_file)) == -1) {
        fprintf(stderr, "fsync failed: %s\n", strerror(errno));
    }
}

static int check_earthquake_alert(int value, int *window, int *index, int window_size) {
    window[*index] = value;
    *index = (*index + 1) % window_size;

    int count = 0;
    for (int i = 0; i < window_size; i++) {
        if (window[i] == 1) {
            count++;
        }
    }
    return (count >= 3) ? 1 : 0;
}

