#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* LSM303DLHC magnetometer I2C 7-bit address (SA0 tied to VDD -> 0x1E) */
#define LSM303_MAG_ADDR 0x1E

/* Register addresses */
#define MR_REG_M       0x02  /* Output data rate / mode register */
#define CRA_REG_M      0x00  /* Control register A */
#define OUT_X_MSB_M    0x03  /* X MSB */
#define OUT_X_LSB_M    0x04  /* X LSB */
#define OUT_Z_MSB_M    0x05  /* Z MSB */
#define OUT_Z_LSB_M    0x06  /* Z LSB */
#define OUT_Y_MSB_M    0x07  /* Y MSB */
#define OUT_Y_LSB_M    0x08  /* Y LSB */

/* Calibration offsets (replace with values from your calibration process) */
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

#define I2C_BUS "/dev/i2c-1"
#define CSV_FILE "mag_log.csv"
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read burst from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_magnetometer(int fd)
{
    /* Continuous-conversion mode: MR_REG_M = 0x00 */
    if (i2c_write_reg8(fd, MR_REG_M, 0x00) < 0)
        return -1;

    /* 15 Hz output data rate: CRA_REG_M = 0x14 */
    if (i2c_write_reg8(fd, CRA_REG_M, 0x14) < 0)
        return -1;

    return 0;
}

static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t raw[6];
    if (i2c_read_burst(fd, OUT_X_MSB_M, raw, sizeof(raw)) < 0)
        return -1;

    *x = (int16_t)((raw[0] << 8) | raw[1]);
    *z = (int16_t)((raw[2] << 8) | raw[3]);
    *y = (int16_t)((raw[4] << 8) | raw[5]);
    return 0;
}

static void calibrate_data(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                            float *cal_x, float *cal_y, float *cal_z)
{
    *cal_x = (float)raw_x - X_OFFSET;
    *cal_y = (float)raw_y - Y_OFFSET;
    *cal_z = (float)raw_z - Z_OFFSET;
}

static float calculate_heading(float cal_x, float cal_y)
{
    float heading = atan2f(cal_y, cal_x) * 180.0f / (float)M_PI;
    if (heading < 0.0f)
        heading += 360.0f;
    return heading;
}

static const char *determine_direction(float heading)
{
    if (heading >= 337.5f || heading < 22.5f) return "North";
    if (heading >= 22.5f && heading < 67.5f) return "Northeast";
    if (heading >= 67.5f && heading < 112.5f) return "East";
    if (heading >= 112.5f && heading < 157.5f) return "Southeast";
    if (heading >= 157.5f && heading < 202.5f) return "South";
    if (heading >= 202.5f && heading < 247.5f) return "Southwest";
    if (heading >= 247.5f && heading < 292.5f) return "West";
    if (heading >= 292.5f || heading < 337.5f) return "Northwest";
    return NULL;
}

static int log_data(FILE *fp, float cal_x, float cal_y, float cal_z, float heading, const char *direction)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f,%s\n",
                ts, cal_x, cal_y, cal_z, heading, direction) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush CSV failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_csv_fp) {
        fclose(g_csv_fp);
        g_csv_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                LSM303_MAG_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (init_magnetometer(g_i2c_fd) < 0) {
        fprintf(stderr, "Magnetometer initialization failed.\n");
        cleanup();
        return 1;
    }

    /* Check if CSV file exists to decide on header */
    int file_exists = (access(CSV_FILE, F_OK) == 0);
    g_csv_fp = fopen(CSV_FILE, "a");
    if (!g_csv_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILE, strerror(errno));
        cleanup();
        return 1;
    }
    if (!file_exists) {
        if (fprintf(g_csv_fp, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n") < 0) {
            fprintf(stderr, "Cannot write CSV header: %s\n", strerror(errno));
            cleanup();
            return 1;
        }
        if (fflush(g_csv_fp) != 0) {
            fprintf(stderr, "Cannot flush CSV header: %s\n", strerror(errno));
            cleanup();
            return 1;
        }
    }

    printf("LSM303DLHC magnetometer logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;
        if (read_magnetometer(g_i2c_fd, &raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "I2C read error; skipping sample.\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float cal_x, cal_y, cal_z;
        calibrate_data(raw_x, raw_y, raw_z, &cal_x, &cal_y, &cal_z);
        float heading = calculate_heading(cal_x, cal_y);
        const char *direction = determine_direction(heading);

        printf("Heading: %.2f degrees, Direction: %s\n", heading, direction);

        if (log_data(g_csv_fp, cal_x, cal_y, cal_z, heading, direction) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return 0;
}

