#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_US 200000  /* 200 ms in microseconds */
#define LOG_FILE "relay_log.json"

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t relay_state = 0;
static volatile uint32_t last_touch_tick = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    const char *state_str = (state == 1) ? "ON" : "OFF";
    if (fprintf(fp, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n",
                timestamp, state_str) < 0) {
        perror("fprintf");
    }

    if (fclose(fp) != 0) {
        perror("fclose");
    }
}

static void touch_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;

    if (level != 1) {
        return;  /* Only act on rising edge (touch) */
    }

    uint32_t elapsed = tick - last_touch_tick;
    if (elapsed < DEBOUNCE_US) {
        return;  /* Debounce: ignore touches within 200 ms */
    }
    last_touch_tick = tick;

    relay_state = !relay_state;
    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "gpioWrite failed on pin %d\n", RELAY_PIN);
    }

    log_relay_state(relay_state);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for pin %d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite failed to initialise relay to OFF\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFunc(TOUCH_SENSOR_PIN, RISING_EDGE, 0, touch_callback) != 0) {
        fprintf(stderr, "gpioSetISRFunc failed for pin %d\n", TOUCH_SENSOR_PIN);
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Relay control started. Touch GPIO%d to toggle GPIO%d. Ctrl+C to exit.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);

    while (running) {
        gpioDelay(100000);  /* 100 ms sleep to reduce CPU usage */
    }

    printf("\nShutting down...\n");

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn relay OFF during shutdown\n");
    }

    log_relay_state(0);

    gpioSetISRFunc(TOUCH_SENSOR_PIN, RISING_EDGE, 0, NULL);
    gpioTerminate();

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

