#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25
#define MOISTURE_THRESHOLD 30
#define IRRIGATION_DURATION 5
#define LOG_FILE "irrigation_log.txt"
#define CHIP_NAME "gpiochip0"

static volatile sig_atomic_t running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[4] = {NULL, NULL, NULL, NULL};
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_gpio(void) {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    unsigned int pins[4] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < 4; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %u\n", pins[i]);
            return -1;
        }

        if (gpiod_line_request_output(relay_lines[i], "irrigation", 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for pin %u\n", pins[i]);
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void) {
    for (int i = 0; i < 4; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 1);
            gpiod_line_release(relay_lines[i]);
            relay_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int activate_relay(int relay_number) {
    if (relay_number < 1 || relay_number > 4) {
        fprintf(stderr, "Invalid relay number: %d\n", relay_number);
        return -1;
    }

    int pin = (relay_number == 1) ? RELAY1_PIN :
              (relay_number == 2) ? RELAY2_PIN :
              (relay_number == 3) ? RELAY3_PIN : RELAY4_PIN;

    if (gpiod_line_set_value(relay_lines[relay_number - 1], 0) < 0) {
        perror("gpiod_line_set_value (activate)");
        return -1;
    }
    printf("Relay %d activated\n", relay_number);

    sleep(IRRIGATION_DURATION);

    if (gpiod_line_set_value(relay_lines[relay_number - 1], 1) < 0) {
        perror("gpiod_line_set_value (deactivate)");
        return -1;
    }
    printf("Relay %d deactivated\n", relay_number);
    return 0;
}

static int log_irrigation(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (!localtime_r(&rawtime, &timeinfo)) {
        perror("localtime_r");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Relay %d activated due to low moisture level (%d)\n",
                timestamp, relay_number, moisture_level) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(log_file) == EOF) {
        perror("fflush");
        return -1;
    }
    return 0;
}

static int simulate_moisture_level(void) {
    return rand() % 101;
}

int main(void) {
    srand(time(NULL));

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    if (setup_gpio() < 0) {
        fclose(log_file);
        return 1;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_level = simulate_moisture_level();
        printf("Simulated moisture level: %d\n", moisture_level);

        if (moisture_level < MOISTURE_THRESHOLD) {
            for (int i = 1; i <= 4; i++) {
                if (!running) break;
                if (activate_relay(i) < 0) {
                    fprintf(stderr, "Error activating relay %d\n", i);
                } else {
                    if (log_irrigation(i, moisture_level) < 0) {
                        fprintf(stderr, "Error logging irrigation for relay %d\n", i);
                    }
                }
            }
        }

        sleep(10);
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    if (log_file) {
        fclose(log_file);
    }
    return 0;
}

