/*
 * Automated Plant Watering System — Raspberry Pi Zero W
 * pigpio servo control of two SG90 servos.
 *
 * Wiring:
 *   Water valve servo signal  -> GPIO17 (physical pin 11)
 *   Water valve servo power    -> 5 V (pin 2 or 4)
 *   Water valve servo GND      -> GND (pin 6)
 *   Directional nozzle servo signal -> GPIO18 (physical pin 12)
 *   Directional nozzle servo power -> 5 V (pin 2 or 4)
 *   Directional nozzle servo GND  -> GND (pin 6)
 *
 * Build:  gcc -Wall -Wextra -O2 -o watering watering.c -lpigpio -lrt
 * Run:    sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_GPIO      17
#define NOZZLE_GPIO     18

#define SERVO_MIN_US    500   /* ~0 degrees   */
#define SERVO_MID_US    1500  /* ~90 degrees  */
#define SERVO_MAX_US    2500  /* ~180 degrees */

#define MOISTURE_THRESHOLD 50
#define WATERING_HOLD_SEC   5
#define CYCLE_DELAY_SEC     5
#define ANGLE_HOLD_SEC      2
#define ANGLE_COUNT         5
#define MAX_RETRIES         3
#define RETRY_DELAY_US      100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* Servo helpers                                                       */
/* ------------------------------------------------------------------ */

/*
 * Drive a servo to the given angle (0–180) using gpioServo().
 * Returns 0 on success, -1 on failure.
 */
static int set_servo_angle(int gpio, int angle)
{
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Invalid angle %d for GPIO %d\n", angle, gpio);
        return -1;
    }

    int pulse_us = SERVO_MIN_US +
                   (int)((long)angle * (SERVO_MAX_US - SERVO_MIN_US) / 180);

    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        if (gpioServo(gpio, pulse_us) == 0)
            return 0;

        fprintf(stderr, "gpioServo(GPIO=%d, %d us) failed (attempt %d/%d)\n",
                gpio, pulse_us, attempt, MAX_RETRIES);
        if (attempt < MAX_RETRIES)
            gpioDelay(RETRY_DELAY_US);
    }

    fprintf(stderr, "gpioServo(GPIO=%d, %d us) failed after %d attempts\n",
            gpio, pulse_us, MAX_RETRIES);
    return -1;
}

/*
 * Stop pulsing a servo (0 degrees).
 * Returns 0 on success, -1 on failure.
 */
static int stop_servo(int gpio)
{
    return gpioServo(gpio, 0);
}

/*
 * Open the water valve servo to 90 degrees.
 * Returns 0 on success, -1 on failure.
 */
static int open_valve(void)
{
    return set_servo_angle(VALVE_GPIO, 90);
}

/*
 * Close the water valve servo to 0 degrees.
 * Returns 0 on success, -1 on failure.
 */
static int close_valve(void)
{
    return set_servo_angle(VALVE_GPIO, 0);
