 * Stop pulsing a servo (0 degrees).
 * Returns 0 on success, -1 on failure.
 */
static int stop_servo(int gpio)
{
    return gpioServo(gpio, 0);
}

/*
 * Open the water valve servo to 90 degrees.
 * Returns 0 on success, -1 on failure.
 */
static int open_valve(void)
{
    return set_servo_angle(VALVE_GPIO, 90);
}

/*
 * Close the water valve servo to 0 degrees.
 * Returns 0 on success, -1 on failure.
 */
static int close_valve(void)
{
    return set_servo_angle(VALVE_GPIO, 0);
}

/*
 * Sweep the directional nozzle servo through the given angles.
 * Holds ANGLE_HOLD_SEC at each angle, then holds WATERING_HOLD_SEC
 * at the final angle before returning.
 * Returns 0 on success, -1 on failure.
 */
static int sweep_nozzle(const int angles[ANGLE_COUNT])
{
    for (int i = 0; i < ANGLE_COUNT - 1; i++) {
        if (!g_running)
            return -1;

        if (set_servo_angle(NOZZLE_GPIO, angles[i]) != 0)
            return -1;

        gpioDelay(ANGLE_HOLD_SEC * 1000000);
    }

    /* Final hold — also check g_running so SIGINT/SIGTERM can interrupt. */
    if (!g_running)
        return -1;

    if (set_servo_angle(NOZZLE_GPIO, angles[ANGLE_COUNT - 1]) != 0)
        return -1;

    gpioDelay(WATERING_HOLD_SEC * 1000000);

    return 0;
}

/*
 * Water the plant: open valve, sweep nozzle, close valve.
 * Returns 0 on success, -1 on failure.
 */
static int water_plant(void)
{
    printf("Watering plant...\n");

    if (open_valve() != 0) {
        fprintf(stderr, "CRITICAL: failed to open water valve servo\n");
        return -1;
    }

    int angles[ANGLE_COUNT] = {0, 45, 90, 135, 180};
    if (sweep_nozzle(angles) != 0) {
        fprintf(stderr, "CRITICAL: failed to sweep nozzle servo\n");
        (void)close_valve();
        return -1;
    }

    if (close_valve() != 0) {
        fprintf(stderr, "CRITICAL: failed to close water valve servo\n");
        return -1;
    }

    printf("Watering cycle complete.\n");
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Ensure servos are off before we start. */
    if (stop_servo(VALVE_GPIO) != 0 || stop_servo(NOZZLE_GPIO) != 0) {
        fprintf(stderr, "Failed to initialise servo GPIOs\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Automated Plant Watering System started.\n");
    printf("Valve servo: GPIO%d | Nozzle servo: GPIO%d\n",
           VALVE_GPIO, NOZZLE_GPIO);
    printf("Moisture threshold: %d | Hold: %ds | Cycle: %ds\n",
           MOISTURE_THRESHOLD, WATERING_HOLD_SEC, CYCLE_DELAY_SEC);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int moisture = 0;

        /* Simulated soil-moisture readings (0–100). */
        moisture = 20;
        if (g_running) {
            if (moisture < MOISTURE_THRESHOLD) {
                printf("Moisture level: %d%% — below threshold (%d%%). "
                       "Watering plant...\n",
                       moisture, MOISTURE_THRESHOLD);
                if (water_plant() != 0) {
                    fprintf(stderr, "Watering cycle failed.\n");
                }
            } else {
                printf("Moisture level: %d%% — adequate. No watering needed.\n",
                       moisture);
