#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK_PIN 24
#define UNLOCK_PIN 23
#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22

#define STEPS_PER_ROTATION 512
#define STEP_DELAY_US 3000
#define DEBOUNCE_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_write(unsigned pin, unsigned level) {
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "gpioWrite failed on pin %u\n", pin);
        return -1;
    }
    return 0;
}

static int safe_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "gpioSetMode failed on pin %u\n", pin);
        return -1;
    }
    return 0;
}

static int safe_set_pull(unsigned pin, unsigned pud) {
    if (gpioSetPullUpDown(pin, pud) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed on pin %u\n", pin);
        return -1;
    }
    return 0;
}

static int rotate_cw(int steps) {
    for (int i = 0; i < steps; i++) {
        if (!running) return -1;
        if (safe_write(IN1, 1) < 0) return -1;
        if (safe_write(IN2, 0) < 0) return -1;
        if (safe_write(IN3, 0) < 0) return -1;
        if (safe_write(IN4, 0) < 0) return -1;
        gpioDelay(STEP_DELAY_US);
        if (!running) return -1;
        if (safe_write(IN1, 0) < 0) return -1;
        if (safe_write(IN2, 1) < 0) return -1;
        if (safe_write(IN3, 0) < 0) return -1;
        if (safe_write(IN4, 0) < 0) return -1;
        gpioDelay(STEP_DELAY_US);
    }
    return 0;
}

static int rotate_ccw(int steps) {
    for (int i = 0; i < steps; i++) {
        if (!running) return -1;
        if (safe_write(IN1, 0) < 0) return -1;
        if (safe_write(IN2, 0) < 0) return -1;
        if (safe_write(IN3, 1) < 0) return -1;
        if (safe_write(IN4, 0) < 0) return -1;
        gpioDelay(STEP_DELAY_US);
        if (!running) return -1;
        if (safe_write(IN1, 0) < 0) return -1;
        if (safe_write(IN2, 0) < 0) return -1;
        if (safe_write(IN3, 0) < 0) return -1;
        if (safe_write(IN4, 1) < 0) return -1;
        gpioDelay(STEP_DELAY_US);
    }
    return 0;
}

static int deenergize(void) {
    if (safe_write(IN1, 0) < 0) return -1;
    if (safe_write(IN2, 0) < 0) return -1;
    if (safe_write(IN3, 0) < 0) return -1;
    if (safe_write(IN4, 0) < 0) return -1;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(LOCK_PIN, PI_INPUT) < 0 ||
        safe_set_mode(UNLOCK_PIN, PI_INPUT) < 0 ||
        safe_set_mode(IN1, PI_OUTPUT) < 0 ||
