#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define TIMEOUT_US  50000   /* 50 ms timeout for echo edges */
#define GUARD_US    60000   /* 60 ms between measurements */
#define TRIGGER_US  10
#define SPEED_CM_S  0.01715 /* 343 m/s / 2 */

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

static int log_distance(FILE *fp, int distance)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (!fp) {
        fprintf(stderr, "log_distance: NULL file pointer\n");
        return -1;
    }
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s, %d\n", ts, distance) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_distance(struct gpiod_line *trig, struct gpiod_line *echo,
                          int *distance)
{
    struct timespec t0, t1;
    long elapsed_us;

    /* Ensure trigger is low before starting */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "set trigger low failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(5);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "set trigger high failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(TRIGGER_US);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "set trigger low after pulse failed: %s\n",
                strerror(errno));
        return -1;
    }

    /* Wait for echo rising edge */
    while (gpiod_line_get_value(echo) == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &t0) < 0) {
            fprintf(stderr, "clock_gettime t0 failed: %s\n", strerror(errno));
            return -1;
        }
        elapsed_us = (long)(t0.tv_sec - t0.tv_sec) * 1000000L +
                    (long)(t0.tv_nsec - t0.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            return -1;
        }
    }
    if (clock_gettime(CLOCK_MONOTONIC, &t0) < 0) {
        fprintf(stderr, "clock_gettime t0 failed: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for echo falling edge */
    while (gpiod_line_get_value(echo) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &t1) < 0) {
            fprintf(stderr, "clock_gettime t1 failed: %s\n", strerror(errno));
            return -1;
        }
        elapsed_us = (long)(t1.tv_sec - t0.tv_sec) * 1000000L +
                    (long)(t1.tv_nsec - t0.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            return -1;
        }
    }
    if (clock_gettime(CLOCK_MONOTONIC, &t0) < 0) {
        fprintf(stderr, "clock_gettime t0 failed: %s\n", strerror(errno));
        return -1;
    }

    *distance = (int)(elapsed_us * SPEED_CM_S);
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        fprintf(stderr, "request_output(trig) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        fprintf(stderr, "request_input(echo) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 logging started. Press Ctrl+C to stop.\n");

    while (running) {
        int distance;
        if (read_distance(trig, echo, &distance) == 0) {
            if (log_distance(fp, distance) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; logging -1.\n");
            if (log_distance(fp, -1) != 0) {
                fprintf(stderr, "Logging -1 failed.\n");
            }
        }
        usleep(GUARD_US);
    }

    printf("\nShutting down cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    if (fp)   fclose(fp);
    return ret;
}

