#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define RELAY_GPIO     18
#define DISTANCE_THRESHOLD 50
#define POLL_DELAY_US  100000  /* 100 ms */

/* VL53L1X register addresses */
#define REG_SOFT_RESET              0x0000
#define REG_SYSTEM_MODE_START      0x0080
#define REG_RESULT_INTERRUPT_STATUS 0x0044
#define REG_RESULT_DISTANCE_MSB    0x0096
#define REG_RESULT_DISTANCE_LSB    0x0097

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write one byte to a 16-bit VL53L1X register address */
static int vl53l1x_write_byte(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read one byte from a 16-bit VL53L1X register address */
static int vl53l1x_read_byte(int handle, uint16_t reg, uint8_t *value)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    char data;
    if (i2cReadDevice(handle, &data, 1) != 1)
        return -1;
    *value = (uint8_t)data;
    return 0;
}

/* Read a 16-bit big-endian value from two consecutive registers */
static int vl53l1x_read_word(int handle, uint16_t reg, uint16_t *value)
{
    uint8_t msb, lsb;
    if (vl53l1x_read_byte(handle, reg, &msb) < 0)
        return -1;
    if (vl53l1x_read_byte(handle, reg + 1, &lsb) < 0)
        return -1;
    *value = ((uint16_t)msb << 8) | lsb;
    return 0;
}

static int init_vl53l1x(int handle)
{
    /* Software reset */
    if (vl53l1x_write_byte(handle, REG_SOFT_RESET, 0x00) < 0) {
