/*
 * MPU-6050 Gyroscope Reader for Raspberry Pi 3 Model B+
 * Uses Linux i2c-dev ioctl interface (modern, no wiringPi/libgpiod).
 *
 * Wiring:
 *   MPU-6050 VCC -> Pi 3.3V (Pin 1)
 *   MPU-6050 GND -> Pi GND  (Pin 9)
 *   MPU-6050 SCL -> Pi GPIO3 / SCL1 (Pin 5)
 *   MPU-6050 SDA -> Pi GPIO2 / SDA1 (Pin 3)
 *
 * Build: gcc -O2 -Wall -o mpu6050_gyro mpu6050_gyro.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68

/* MPU-6050 Registers */
#define REG_PWR_MGMT_1 0x6B
#define REG_GYRO_CONFIG 0x1B
#define REG_GYRO_XOUT_H 0x43

/* Sensitivity for ±250 dps range: 131 LSB/dps */
#define GYRO_SENSITIVITY 131.0f

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    /* Wake up the MPU-6050 (clear sleep bit, use internal 8 MHz oscillator) */
    if (i2c_write_reg(fd, REG_PWR_MGMT_1, 0x00) < 0) {
        return -1;
    }
    usleep(100000); /* 100 ms stabilization */

    /* Set gyroscope full-scale range to ±250 dps */
    if (i2c_write_reg(fd, REG_GYRO_CONFIG, 0x00) < 0) {
        return -1;
    }

    return 0;
}

static int read_gyro_data(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_burst(fd, REG_GYRO_XOUT_H, buf, sizeof(buf)) < 0) {
        return -1;
    }

    /* MPU-6050 outputs big-endian 16-bit values */
    raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

int main(void) {
    int fd = -1;
    float x, y, z;
    struct sigaction sa;

    /* Set up signal handlers for graceful shutdown */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the I2C slave address */
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Initialize the MPU-6050 */
    if (init_mpu6050(fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU-6050 at address 0x%02X\n", MPU6050_ADDR);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialized. Reading gyroscope data (±250 dps)...\n");
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        if (read_gyro_data(fd, &x, &y, &z) == 0) {
            printf("X: %+.2f dps, Y: %+.2f dps, Z: %+.2f dps\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data. Retrying...\n");
        }
        usleep(100000); /* 100 ms */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (fd >= 0) {
        close(fd);
    }
    return EXIT_SUCCESS;
}

