/*
 * Automated Plant Watering System — libgpiod v1 version
 * Board:  Raspberry Pi 4 Model B
 * Relays: 4 × 5V active-low relay modules on BCM GPIO17, 18, 27, 22
 * Build:  gcc -O2 -Wall -Wextra -o watering watering.c -lgpiod
 * Run:    sudo ./watering   (or ensure user is in the 'gpio' group)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS      4
#define WATERING_DURATION_SEC 5
#define WATERING_INTERVAL_SEC 86400
#define POLL_INTERVAL_SEC     60
#define LOG_FILE              "watering_log.txt"
#define GPIO_CHIP_NAME        "gpiochip0"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_watering_start(const char *timestamp)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    if (fprintf(fp, "%s\n", timestamp) < 0) {
        perror("fprintf(log)");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose(log)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int set_relay(struct gpiod_line *line, int value)
{
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "gpiod_line_set_value failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int water_plant(struct gpiod_line *lines[], int num_lines)
{
    for (int i = 0; i < num_lines; i++) {
        if (set_relay(lines[i], 0) < 0)
            return -1;
        sleep(WATERING_DURATION_SEC);
        if (set_relay(lines[i], 1) < 0)
            return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_RELAYS; i++)
        lines[i] = NULL;

    /* --- Signal handlers ------------------------------------------- */
