#include <string.h>
#include <unistd.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define STEP_DELAY_US 1000000
#define TOTAL_STEPS 300

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen("smart_lighting.log", "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    if (gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(RELAY1_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(RELAY2_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(RELAY3_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(RELAY4_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    gpioPWM(RELAY1_PIN, 0);
    gpioPWM(RELAY2_PIN, 0);
    gpioPWM(RELAY3_PIN, 0);
    gpioPWM(RELAY4_PIN, 0);
    gpioTerminate();
}

static void sunrise_effect(int duration_minutes) {
    int total_steps = duration_minutes * 60 / 10;
    if (total_steps > TOTAL_STEPS) total_steps = TOTAL_STEPS;

    for (int i = 0; i < total_steps && running; ++i) {
        int duty_cycle = (i + 1) * PWM_RANGE / total_steps;
        if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

        if (gpioPWM(RELAY1_PIN, duty_cycle) != 0 ||
            gpioPWM(RELAY2_PIN, duty_cycle) != 0 ||
            gpioPWM(RELAY3_PIN, duty_cycle) != 0 ||
            gpioPWM(RELAY4_PIN, duty_cycle) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
            break;
        }

        char log_message[128];
        snprintf(log_message, sizeof(log_message),
                 "Sunrise step %d/%d, duty cycle: %d",
                 i + 1, total_steps, duty_cycle);
        log_event(log_message);

        usleep(STEP_DELAY_US);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handler");
        return 1;
    }

    if (setup_gpio() != 0) {
        return 1;
    }

    log_event("Smart lighting system started");
    sunrise_effect(30);

    log_event("Smart lighting system stopped");
    cleanup_gpio();
    return 0;
}

