#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 register addresses */
#define MPU6050_SMPLRT_DIV   0x19
#define MPU6050_CONFIG       0x1A
#define MPU6050_GYRO_CONFIG  0x1B
#define MPU6050_PWR_MGMT_1   0x6B
#define MPU6050_GYRO_XOUT_H  0x43
#define MPU6050_WHO_AM_I     0x75

/* Expected device ID */
#define MPU6050_WHO_AM_I_VAL 0x68

/* GPIO pin for LED */
#define LED_PIN 17

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Angular velocity threshold (degrees/second) */
#define THRESHOLD 250.0f

/* Sampling period (microseconds) for 20 Hz */
#define SAMPLE_PERIOD_US 50000

/* Re-initialisation attempts before exit */
#define MAX_REINIT_ATTEMPTS 3

typedef struct {
    time_t timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_mpu6050(int handle) {
    /* Verify device identity */
    int who = i2cReadByteData(handle, MPU6050_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I register (pigpio error %d)\n", who);
        return -1;
    }
    if (who != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who, MPU6050_WHO_AM_I_VAL);
        return -1;
    }

    /* Wake up: clear SLEEP bit in PWR_MGMT_1 */
    if (i2cWriteByteData(handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle time */

    /* Sample rate divider = 7 -> 1 kHz / (1 + 7) = 125 Hz; use 100 Hz for safety */
    if (i2cWriteByteData(handle, MPU6050_SMPLRT_DIV, 0x0B) < 0) {
        fprintf(stderr, "Error: failed to write SMPLRT_DIV\n");
        return -1;
    }

    /* Gyro full-scale range: ±250 deg/s (FS_SEL = 0) */
    if (i2cWriteByteData(handle, MPU6050_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write GYRO_CONFIG\n");
        return -1;
    }

    return 0;
}

static int read_gyro_data(int handle, float *x, float *y, float *z) {
    char raw[6];
    int16_t x_raw, y_raw, z_raw;

    if (i2cReadI2CBlockData(handle, MPU6050_GYRO_XOUT_H, raw, 6) != 6) {
        fprintf(stderr, "Error: failed to read gyroscope data block\n");
        return -1;
    }

    x_raw = (int16_t)((raw[0] << 8) | raw[1]);
    y_raw = (int16_t)((raw[2] << 8) | raw[3]);
    z_raw = (int16_t)((raw[4] << 8) | raw[5]);

    /* ±250 deg/s range: 131 LSB per deg/s */
    *x = (float)x_raw / 131.0f;
    *y = (float)y_raw / 131.0f;
    *z = (float)z_raw / 131.0f;

    return 0;
}

static void add_to_buffer(float x, float y, float z) {
    gyro_buffer[buffer_index].timestamp = time(NULL);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void check_threshold(float x, float y, float z) {
    if (fabsf(x) > THRESHOLD || fabsf(y) > THRESHOLD || fabsf(z) > THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus 1 at address 0x%02X (pigpio error %d)\n",
                MPU6050_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_mpu6050(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int reinit_attempts = 0;

    while (!terminate) {
        float x, y, z;

        if (read_gyro_data(i2c_handle, &x, &y, &z) == 0) {
            add_to_buffer(x, y, z);
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "Warning: read failed, attempting re-initialisation (%d/%d)\n",
                    reinit_attempts + 1, MAX_REINIT_ATTEMPTS);
            if (init_mpu6050(i2c_handle) < 0) {
                reinit_attempts++;
                if (reinit_attempts >= MAX_REINIT_ATTEMPTS) {
                    fprintf(stderr, "Error: max re-initialisation attempts reached, exiting\n");
                    break;
                }
            } else {
                reinit_attempts = 0;
            }
            gpioDelay(100000); /* 100 ms backoff before retry */
            continue;
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

