#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define CS_LINE_OFFSET  8
#define GYRO_XOUT_H     0x43
#define GYRO_SCALE      131.0f
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0
#define LOG_FILE        "gyro_log.txt"
#define SAMPLE_PERIOD_NS 10000000L
#define MAX_RETRIES     3

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_cs_line = NULL;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_xfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (gpiod_line_set_value(g_cs_line, 0) < 0) {
        fprintf(stderr, "CS low failed: %s\n", strerror(errno));
        return -1;
    }

    int ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
    if (gpiod_line_set_value(g_cs_line, 1) < 0) {
        fprintf(stderr, "CS high failed: %s\n", strerror(errno));
        return -1;
    }

    if (ret < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx[6] = { GYRO_XOUT_H, 0, 0, 0, 0, 0 };
    uint8_t rx[6] = { 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (spi_xfer(g_spi_fd, tx, rx, 6) == 0) {
            *x = (int16_t)((rx[0] << 8) | rx[1]);
            *y = (int16_t)((rx[2] << 8) | rx[3]);
            *z = (int16_t)((rx[4] << 8) | rx[5]);
            return 0;
        }
        usleep(1000);
    }
    return -1;
}

static void log_data(FILE *fp, float x, float y, float z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return;
    }
    if (fprintf(fp, "%ld.%09ld,%.2f,%.2f,%.2f\n",
                (long)ts.tv_sec, ts.tv_nsec, x, y, z) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

static void cleanup(void) {
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_cs_line) {
        gpiod_line_release(g_cs_line);
        g_cs_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    g_chip = gpiod_chip_open(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return 1;
    }

    g_cs_line = gpiod_chip_get_line(g_chip, CS_LINE_OFFSET);
    if (!g_cs_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", CS_LINE_OFFSET, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(g_cs_line, "mpu9250-cs", 1) < 0) {
        fprintf(stderr, "Cannot request CS line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Gyroscope data logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;
        if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
            float x = (float)raw_x / GYRO_SCALE;
            float y = (float)raw_y / GYRO_SCALE;
            float z = (float)raw_z / GYRO_SCALE;
            log_data(g_log_fp, x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyro data after %d retries.\n", MAX_RETRIES);
        }
        usleep(SAMPLE_PERIOD_NS);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

