#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 register addresses */
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40

/* GPIO pin for the LED */
#define LED_PIN 21

/* Tilt thresholds (degrees) */
#define ROLL_THRESHOLD 45.0
#define PITCH_THRESHOLD 45.0

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 100000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — async-signal-safe subset only                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of accelerometer data (X, Y, Z)                        */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_accelerometer(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    char buffer[6];

    if (i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buffer, 6) != 6) {
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | (uint8_t)buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | (uint8_t)buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | (uint8_t)buffer[5]);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute roll and pitch from raw accelerometer data                  */
/* ------------------------------------------------------------------ */
static void compute_tilt(int16_t ax, int16_t ay, int16_t az,
                         float *roll, float *pitch)
{
    /* Convert raw to g (±2g range: 16384 LSB/g) */
    const float scale = 16384.0f;
    float gx = (float)ax / scale;
    float gy = (float)ay / scale;
    float gz = (float)az / scale;

    *roll  = atan2f(gy, gz) * 180.0f / (float)M_PI;
    *pitch = atan2f(-gx, sqrtf(gy * gy + gz * gz)) * 180.0f / (float)M_PI;
}

/* ------------------------------------------------------------------ */
/* Log tilt data to a CSV file                                          */
/* ------------------------------------------------------------------ */
static void log_tilt_data(float roll, float pitch)
{
    FILE *fp = fopen("tilt_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening tilt_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, roll, pitch);
    } else {
        fprintf(fp, "1970-01-01 00:00:00,%.2f,%.2f\n", roll, pitch);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Control the LED based on tilt thresholds                            */
/* ------------------------------------------------------------------ */
static void control_led(int led_pin, float roll, float pitch)
{
    int state = (fabsf(roll) > ROLL_THRESHOLD || fabsf(pitch) > PITCH_THRESHOLD) ? 1 : 0;
    if (gpioWrite(led_pin, state) < 0) {
        fprintf(stderr, "Warning: gpioWrite failed on pin %d\n", led_pin);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                         */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at MPU-6050 address */
    g_i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n",
                MPU6050_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Wake up the MPU-6050 (clear sleep bit in PWR_MGMT_1) */
    if (i2cWriteByteData(g_i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set accelerometer full-scale range to ±2g (ACCEL_CONFIG = 0x00) */
    if (i2cWriteByteData(g_i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to ACCEL_CONFIG\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it starts off */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPU-6050 tilt monitor started. Press Ctrl+C to exit.\n");

    int16_t ax, ay, az;
    float roll, pitch;

    while (g_running) {
        if (read_accelerometer(g_i2c_handle, &ax, &ay, &az) == 0) {
            compute_tilt(ax, ay, az, &roll, &pitch);
            log_tilt_data(roll, pitch);
            control_led(LED_PIN, roll, pitch);
            printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);
        } else {
            fprintf(stderr, "Error reading accelerometer data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

