#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1145_ADDR    0x5A
#define ALS_REG         0x20
#define PXS_REG         0x22
#define GPIO_CHIP       "gpiochip0"
#define GPIO_LINE       17
#define PROX_THRESHOLD  100
#define LOG_FILE        "biometric_log.txt"
#define SAMPLE_PERIOD_US 100000
#define I2C_RETRIES     3
#define I2C_RETRY_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    for (int i = 0; i < I2C_RETRIES; i++) {
        if (write(fd, buf, 2) == 2) return 0;
        usleep(I2C_RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    for (int i = 0; i < I2C_RETRIES; i++) {
        if (write(fd, &reg, 1) != 1) { usleep(I2C_RETRY_DELAY_US); continue; }
        uint8_t buf[2];
        if (read(fd, buf, 2) == 2) { *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8); return 0; }
        usleep(I2C_RETRY_DELAY_US);
    }
    return -1;
}

static int log_data(FILE *fp, uint16_t als, uint16_t prox) {
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) return -1;
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,AmbientLight:%u,Proximity:%u\n", ts, als, prox) < 0) return -1;
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) { perror("open i2c bus"); return 1; }
    if (ioctl(fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("ioctl I2C_SLAVE"); close(fd); return 1;
    }

    FILE *log = fopen(LOG_FILE, "a");
    if (!log) { perror("fopen log"); close(fd); return 1; }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) { perror("gpiod_chip_open"); fclose(log); close(fd); return 1; }
    struct gpiod_line *led = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!led) { perror("gpiod_chip_get_line"); gpiod_chip_close(chip); fclose(log); close(fd); return 1; }
    if (gpiod_line_request_output(led, "si1145_prox", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip); fclose(log); close(fd); return 1;
    }

    while (running) {
        uint16_t als = 0, prox = 0;
        if (i2c_read_reg16(fd, ALS_REG, &als) < 0 || i2c_read_reg16(fd, PXS_REG, &prox) < 0) {
            fprintf(stderr, "I2C read error\n");
        } else {
            if (log_data(log, als, prox) < 0) perror("log_data");
            if (gpiod_line_set_value(led, prox > PROX_THRESHOLD ? 1 : 0) < 0) {
                perror("gpiod_line_set_value");
            }
        }
        usleep(SAMPLE_PERIOD_US);
    }

    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    fclose(log);
    close(fd);
    return 0;
}

