#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADXRS290 Register Addresses */
#define ADXRS290_REG_XGYRO_OUT 0x02
#define ADXRS290_REG_YGYRO_OUT 0x04

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    0        /* CPOL=0, CPHA=0 */

/* Sensitivity: 200 LSB/deg/s */
#define SENSITIVITY 200.0f

/* Sampling interval: 10 ms for ~100 Hz */
#define SAMPLE_DELAY_US 10000

/* Reinit retries */
#define MAX_REINIT_ATTEMPTS 3

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read a 16-bit register from the ADXRS290.
 * Returns 0 on success, -1 on SPI transfer failure.
 */
static int read_register(uint8_t reg, int16_t *value) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }
    *value = (int16_t)(((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

static int read_gyro_data(int16_t *x_rate, int16_t *y_rate) {
    if (read_register(ADXRS290_REG_XGYRO_OUT, x_rate) != 0) {
        return -1;
    }
    if (read_register(ADXRS290_REG_YGYRO_OUT, y_rate) != 0) {
        return -1;
    }
    return 0;
}

static void log_data(int16_t x_rate, int16_t y_rate) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(log_file, "%s.%06ld,%d,%d\n", timestamp, ts.tv_nsec / 1000, x_rate, y_rate);
    fflush(log_file);
}

static int initialize_spi(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d: %s\n",
                SPI_CHANNEL, pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int16_t x_rate, y_rate;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_spi() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting ADXRS290 data acquisition (Ctrl+C to stop)...\n");

    while (running) {
        if (read_gyro_data(&x_rate, &y_rate) == 0) {
            log_data(x_rate, y_rate);
        } else {
            fprintf(stderr, "Failed to read gyro data. Attempting SPI reinit...\n");
            int retries = 0;
            while (retries < MAX_REINIT_ATTEMPTS && running) {
                if (initialize_spi() == 0) {
                    break;
                }
                retries++;
                gpioDelay(100000); /* 100 ms backoff */
            }
            if (retries >= MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "SPI reinit failed after %d attempts. Exiting.\n", MAX_REINIT_ATTEMPTS);
                break;
            }
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

