#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN    17
#define LOG_FILE     "seismic_events.txt"
#define ALERT_DURATION_MS 2000
#define POLL_INTERVAL_US 10000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_file, "%s - %s\n", timestamp, message);
    fflush(log_file);
}

static void sensor_callback(int gpio, int level, uint32_t tick) {
    (void)tick;
    if (level != 0) return;

    static uint32_t tilt_start_tick = 0;
    static int tilt_active = 0;

    if (tilt_active) {
        uint32_t elapsed = tick - tilt_start_tick;
        if (elapsed >= (ALERT_DURATION_MS * 1000)) {
            log_event("Seismic event detected!");
            gpioWrite(ALERT_PIN, 1);
            gpioDelay(ALERT_DURATION_MS * 1000);
            gpioWrite(ALERT_PIN, 0);
            tilt_active = 0;
        }
    } else {
        tilt_active = 1;
        tilt_start_tick = tick;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    if (gpioSetAlertFunc(SENSOR_1_PIN, sensor_callback) != 0 ||
        gpioSetAlertFunc(SENSOR_2_PIN, sensor_callback) != 0) {
        fprintf(stderr, "Failed to set alert callbacks\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
