#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

/* ADXRS290 Register Addresses */
#define ADXRS290_REG_STATUS 0x00
#define ADXRS290_REG_RATE_XL 0x02
#define ADXRS290_REG_RATE_XH 0x03

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    0

/* GPIO Configuration */
#define LED_GPIO    17

/* Threshold for angular velocity (degrees/second) */
#define THRESHOLD  20.0f

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Sensitivity: 200 LSB/deg/s */
#define SENSITIVITY 200.0f

/* Structure to hold gyroscope data and timestamp */
typedef struct {
    float angular_velocity;
    struct timespec timestamp;
} gyro_data_t;

/* Circular buffer structure */
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

/* Global variables */
static int spi_handle = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int spi_read_register(uint8_t reg_addr, uint8_t *data);
static float convert_to_degrees_per_second(uint16_t raw_data);
static void add_to_circular_buffer(circular_buffer_t *buffer, float angular_velocity);
static int check_threshold(float angular_velocity);
static void signal_handler(int signal);
static void cleanup(void);
static int init_circular_buffer(circular_buffer_t *buffer);

/*
 * Function to read a 16-bit register from the ADXRS290 via SPI.
 * The MSB of the register address (bit 7) is set to 1 to indicate a read.
 */
static int spi_read_register(uint8_t reg_addr, uint8_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    /* Set MSB of register address to 1 for read operation */
    reg_addr |= 0x80;

    tx_buf[0] = (reg_addr >> 8) & 0xFF;
    tx_buf[1] = reg_addr & 0xFF;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI read transfer failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    data[0] = rx_buf[0];
    data[1] = rx_buf[1];
    return 0;
}

/*
 * Function to convert raw 16-bit data to degrees per second.
 * ADXRS290 sensitivity: 200 LSB/deg/s (two's complement, 16-bit range)
 */
static float convert_to_degrees_per_second(uint16_t raw_data) {
    int16_t signed_data = (int16_t)raw_data;
    return (float)signed_data / SENSITIVITY;
}

/*
 * Function to add data to the circular buffer.
 */
static void add_to_circular_buffer(circular_buffer_t *buffer, float angular_velocity) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);

    buffer->buffer[buffer->head].angular_velocity = angular_velocity;
    buffer->buffer[buffer->head].timestamp = ts;

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;

    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    } else {
        /* Buffer is full, overwrite the oldest entry */
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }
}

/*
 * Function to check if the angular velocity exceeds the threshold.
 */
static int check_threshold(float angular_velocity) {
    return (fabsf(angular_velocity) > THRESHOLD);
}

/*
 * Signal handler for graceful shutdown.
 */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/*
 * Cleanup function to release resources.
 */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/*
 * Initialize the circular buffer.
 */
static int init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    if (pthread_mutex_init(&buffer->mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        return -1;
    }
    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    /* Configure LED GPIO */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Initialize circular buffer */
    if (init_circular_buffer(&gyro_buffer) != 0) {
        cleanup();
        return 1;
    }

    /* Set up signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Gyroscope data acquisition started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (program_running) {
        uint8_t data[2];
        uint16_t raw_data;
        float angular_velocity;

        /* Read X-axis angular rate (RATE_XL and RATE_XH) */
        if (spi_read_register(ADXRS290_REG_RATE_XL, data) != 0) {
            fprintf(stderr, "Failed to read X-axis data\n");
            gpioDelay(100000); /* 100ms delay before retry */
            continue;
        }
        if (spi_read_register(ADXRS290_REG_RATE_XH, data) != 0) {
            fprintf(stderr, "Failed to read X-axis data\n");
            gpioDelay(100000);
            continue;
        }

        raw_data = ((uint16_t)data[0] << 8) | data[1];
        angular_velocity = convert_to_degrees_per_second(raw_data);

        /* Timestamp the reading */
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);

        /* Add to circular buffer */
        add_to_circular_buffer(&gyro_buffer, angular_velocity);

        /* Check threshold and control LED */
        if (check_threshold(angular_velocity)) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        printf("Angular Velocity: %.2f deg/s, Timestamp: %ld.%09ld\n",
               angular_velocity, ts.tv_sec, ts.tv_nsec);

        gpioDelay(10000); /* 10ms delay */
    }

    /* Cleanup */
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

