#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP1_PIN 17
#define LAMP2_PIN 18
#define LAMP3_PIN 27
#define PWM_RANGE 255
#define PWM_FREQ 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_lamp_brightness(int pin, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    if (gpioPWM(pin, brightness) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static void turn_off_lamp(int pin) {
    if (set_lamp_brightness(pin, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn off lamp on pin %d\n", pin);
    }
}

static void cleanup_all_lamps(void) {
    turn_off_lamp(LAMP1_PIN);
    turn_off_lamp(LAMP2_PIN);
    turn_off_lamp(LAMP3_PIN);
}

static int validate_duration(int duration) {
    if (duration <= 0 || duration > 3600) {
        fprintf(stderr, "Error: duration must be between 1 and 3600 seconds\n");
        return 0;
    }
    return 1;
}

static void perform_fade(int pin, int duration_seconds) {
    int brightness = PWM_RANGE;
    int elapsed = 0;
    int step_us = (duration_seconds * 1000000) / (PWM_RANGE + 1);

    while (running && elapsed < duration_seconds) {
        brightness -= 1;
        if (brightness < 0) brightness = 0;

        if (set_lamp_brightness(pin, brightness) != 0) {
            fprintf(stderr, "Error: failed to set brightness on pin %d\n", pin);
            running = 0;
            break;
        }

        gpioDelay(step_us);
        elapsed += step_us / 1000000.0;
    }

    if (brightness == 0) {
        printf("Lamp on pin %d faded to off.\n", pin);
    } else {
        fprintf(stderr, "Warning: lamp on pin %d did not reach full off.\n", pin);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_seconds>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int duration = atoi(argv[1]);
    if (duration <= 0) {
        fprintf(stderr, "Error: duration must be a positive integer.\n");
        return EXIT_FAILURE;
    }

    if (!validate_duration(duration)) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    int pins[] = {LAMP1_PIN, LAMP2_PIN, LAMP3_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed on pin %d\n", pins[i]);
            cleanup_all_lamps();
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: gpioSetPWMrange failed on pin %d\n", pins[i]);
            cleanup_all_lamps();
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ) != 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency failed on pin %d\n", pins[i]);
            cleanup_all_lamps();
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (set_lamp_brightness(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: initial set_lamp_brightness failed on pin %d\n", pins[i]);
            cleanup_all_lamps();
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to set signal handlers.\n");
        cleanup_all_lamps();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Sunset Simulator starting. Fade duration: %d seconds.\n", duration);
    printf("Lamps on GPIO%d, GPIO%d, GPIO%d. Press Ctrl+C to exit.\n",
           LAMP1_PIN, LAMP2_PIN, LAMP3_PIN);

    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]) && running; i++) {
        printf("Starting fade for lamp on pin %d...\n", pins[i]);
        perform_fade(pins[i], duration);
    }

    cleanup_all_lamps();
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

