        elapsed += step_us / 1000000.0;
    }

    if (brightness == 0) {
        printf("Lamp on pin %d faded to off.\n", pin);
    } else {
        fprintf(stderr, "Warning: lamp on pin %d did not reach full off.\n", pin);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_seconds>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int duration = atoi(argv[1]);
    if (duration <= 0) {
        fprintf(stderr, "Error: duration must be a positive integer.\n");
        return EXIT_FAILURE;
    }

    if (!validate_duration(duration)) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    int pins[] = {LAMP1_PIN, LAMP2_PIN, LAMP3_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed on pin %d\n", pins[i]);
            cleanup_all_lamps();
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: gpioSetPWMrange failed on pin %d\n", pins[i]);
            cleanup_all_lamps();
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ) != 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency failed on pin %d\n", pins[i]);
            cleanup_all_lamps();
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (set_lamp_brightness(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: initial set_lamp_brightness failed on pin %d\n", pins[i]);
            cleanup_all_lamps();
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to set signal handlers.\n");
        cleanup_all_lamps();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Sunset Simulator starting. Fade duration: %d seconds.\n", duration);
    printf("Lamps on GPIO%d, GPIO%d, GPIO%d. Press Ctrl+C to exit.\n",
           LAMP1_PIN, LAMP2_PIN, LAMP3_PIN);

    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]) && running; i++) {
        printf("Starting fade for lamp on pin %d...\n", pins[i]);
        perform_fade(pins[i], duration);
    }

    cleanup_all_lamps();
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

