#define RED_PIN 17
#define YELLOW_PIN 22
#define GREEN_PIN 23
#define ALL_PINS_PIN 24

#define RED_DURATION 10
#define YELLOW_DURATION 2
#define GREEN_DURATION 10
#define YELLOW_DURATION_2 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_ms(int ms) {
    struct timespec ts = { ms / 1000, (ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static void sleep_s(int s) {
    sleep(s);
}

static void release_lines(struct gpiod_line *lines[], int count) {
    for (int i = 0; i < count; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red_line = NULL, *yellow_line = NULL, *green_line = NULL, *all_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    yellow_line = gpiod_chip_get_line(chip, YELLOW_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    all_line = gpiod_chip_get_line(chip, ALL_PINS_PIN);
    if (!red_line || !yellow_line || !green_line || !all_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(red_line, "traffic_light", 1) < 0 ||
        gpiod_line_request_output(yellow_line, "traffic_light", 1) < 0 ||
        gpiod_line_request_output(green_line, "traffic_light", 1) < 0 ||
        gpiod_line_request_output(all_line, "traffic_light", 1) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("Traffic light simulator started. Press Ctrl+C to exit.\n");

    while (running) {
        printf("Red\n");
        fflush(stdout);
        sleep_ms(RED_DURATION * 1000);
        if (!running) break;

        printf("Red+Yellow\n");
        fflush(stdout);
        sleep_ms(YELLOW_DURATION * 1000);
        if (!running) break;

        printf("Green\n");
        fflush(stdout);
        sleep_ms(GREEN_DURATION * 1000);
        if (!running) break;

        printf("Yellow\n");
        fflush(stdout);
        sleep_ms(YELLOW_DURATION_2 * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    release_lines((struct gpiod_line[]){red_line, yellow_line, green_line, all_line}, 4);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

