#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define I2C_BUS 1

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5D
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CHARGETIME 0x5C
#define MPR121_RUNMODE 0x5E
#define MPR121_RESET 0x80
#define MPR121_STOPMODE 0x5E

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int i2c_handle = -1;

static void log_message(const char *message) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "I2C write error: reg=0x%02X, val=0x%02X, rc=%d", reg, value, rc);
        log_message(buf);
    }
    return rc;
}

static int mpr121_init(void) {
    if (mpr121_write_reg(MPR121_RESET, 0x63) < 0) return -1;
    gpioDelay(10000);
    if (mpr121_write_reg(MPR121_STOPMODE, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_ELECTRODE_CONFIG, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_TOUCHTH_0, 0x0A) < 0) return -1;
    if (mpr121_write_reg(MPR121_RELEASETH_0, 0x08) < 0) return -1;
    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x21) < 0) return -1;
    if (mpr121_write_reg(MPR121_CHARGETIME, 0x0D) < 0) return -1;
    if (mpr121_write_reg(MPR121_RUNMODE, 0x0D) < 0) return -1;
    return 0;
}

static int read_touch_status(uint16_t *status) {
    int l = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_L);
    if (l < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "I2C read error: reg=0x%02X, rc=%d", MPR121_TOUCHSTATUS_L, l);
        log_message(buf);
        return -1;
    }
    int h = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);
    if (h < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "I2C read error: reg=0x%02X, rc=%d", MPR121_TOUCHSTATUS_H, h);
        log_message(buf);
        return -1;
    }
    *status = (uint16_t)((h << 8) | l);
    return 0;
}

static void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("touch_relay.log", "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_message("Program started");

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        log_message("Failed to set relay GPIO mode");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "I2C open failed: rc=%d", i2c_handle);
        log_message(buf);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        log_message("MPR121 initialisation failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t touch_status = 0;
    int relay_state = 0;
    int consecutive_errors = 0;

    while (running) {
        if (read_touch_status(&touch_status) == 0) {
            consecutive_errors = 0;
            if (touch_status & (1 << 0)) {
                relay_state = !relay_state;
                control_relay(relay_state);
                log_message(relay_state ? "Relay ON" : "Relay OFF");
            }
        } else {
            consecutive_errors++;
            if (consecutive_errors > 10) {
                log_message("Too many consecutive I2C errors, aborting");
                break;
            }
        }
        gpioDelay(10000);
    }

    log_message("Program exiting");
    control_relay(0);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

