#include <string.h>
#include <errno.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DISPENSE_DURATION_MS 1000
#define DISPENSE_INTERVAL_S 5
#define LOG_FILE "dispense_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void dispense(void) {
    printf("Dispensing...\n");
    fflush(stdout);

    if (gpioWrite(SOLENOID_1_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to activate solenoid 1\n");
        return;
    }
    gpioDelay(DISPENSE_DURATION_MS * 1000);

    if (gpioWrite(SOLENOID_1_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to deactivate solenoid 1\n");
        return;
    }

    if (gpioWrite(SOLENOID_2_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to activate solenoid 2\n");
        return;
    }
    gpioDelay(DISPENSE_DURATION_MS * 1000);

    if (gpioWrite(SOLENOID_2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to deactivate solenoid 2\n");
        return;
    }
}

static int log_dispense(int solenoid1_pin, int solenoid2_pin, int duration_ms) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s - Solenoid 1 (GPIO%d), Solenoid 2 (GPIO%d), Duration: %d ms\n",
            timestamp, solenoid1_pin, solenoid2_pin, duration_ms);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    printf("Pneumatic dispenser started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        dispense();
        if (log_dispense(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION_MS) != 0) {
            fprintf(stderr, "Warning: failed to log dispense event\n");
        }
        for (int i = 0; i < DISPENSE_INTERVAL_S * 10 && running; i++) {
            gpioDelay(100000);
        }
    }

    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);
    gpioTerminate();
    printf("Pneumatic dispenser stopped.\n");
    return 0;
}

