#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

/* Motor A GPIO pins */
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

/* Motor B GPIO pins */
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

/* L298N enable pins */
#define ENA 24
#define ENB 25

/* PID constants */
#define Kp 1.0
#define Ki 0.01
#define Kd 0.1

/* Obstacle avoidance threshold (cm) */
#define OBSTACLE_THRESHOLD 20.0

/* PWM range */
#define PWM_RANGE 255

/* Log file name */
#define LOG_FILE "balance_log.txt"

/* Global state */
static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* PID state */
static double integral = 0.0;
static double previous_error = 0.0;

/* Function prototypes */
static void signal_handler(int sig);
static int initialize_gpio(void);
static void cleanup_gpio(void);
static void set_motor_speed(int motor, int speed);
static void stop_motors(void);
static double pid_control(double error);
static double simulate_distance(void);
static void log_data(double tilt_error, double distance,
                      int motor_a_speed, int motor_b_speed);

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Initialize pigpio and configure motor pins */
static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    /* Set motor pins as outputs */
    if (gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set motor pin modes\n");
        gpioTerminate();
        return -1;
    }

    /* Set enable pins as outputs and hold them HIGH for PWM */
    if (gpioSetMode(ENA, PI_OUTPUT) != 0 ||
        gpioSetMode(ENB, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set enable pin modes\n");
        gpioTerminate();
        return -1;
    }
    gpioWrite(ENA, 1);
    gpioWrite(ENB, 1);

    return 0;
}

/* Clean up GPIO resources */
static void cleanup_gpio(void) {
    /* Stop motors and disable L298N */
    stop_motors();
    gpioTerminate();
}

/* Set motor speed (0-255) */
static void set_motor_speed(int motor, int speed) {
    int forward_pin, backward_pin;

    if (motor == 1) {
        forward_pin = MOTOR_A_FORWARD;
        backward_pin = MOTOR_A_BACKWARD;
    } else if (motor == 2) {
        forward_pin = MOTOR_B_FORWARD;
        backward_pin = MOTOR_B_BACKWARD;
    } else {
        fprintf(stderr, "Invalid motor number: %d\n", motor);
        return;
    }

    if (speed > 0) {
        gpioWrite(forward_pin, 1);
        gpioWrite(backward_pin, 0);
        gpioPWM(forward_pin, speed);
    } else if (speed < 0) {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 1);
        gpioPWM(backward_pin, -speed);
    } else {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 0);
    }
}

/* Stop both motors */
static void stop_motors(void) {
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
}

/* PID controller: returns motor speed (0-255) */
static double pid_control(double error) {
    double proportional = Kp * error;
    integral += Ki * error;
    double derivative = Kd * (error - previous_error);
    double output = proportional + integral + derivative;
    previous_error = error;
    return output;
}

/* Simulated distance sensor: returns distance in cm (2.0-400.0) */
static double simulate_distance(void) {
    return 2.0 + (double)(rand() % 399) / 100.0;
}

/* Log data to file */
static void log_data(double tilt_error, double distance,
                      int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n",
            timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

int main(void) {
    /* Install signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    /* Initialize GPIO */
    if (initialize_gpio() != 0) {
        return 1;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup_gpio();
        return 1;
    }

    srand(time(NULL));

    printf("Self-balancing robot simulation started. Press Ctrl+C to exit.\n");

    while (running) {
        /* Simulate sensor data */
        double tilt_error = (double)(rand() % 210) / 10.0 - 10.0;
        double distance = simulate_distance();

        /* PID control */
        int motor_a_speed = (int)pid_control(tilt_error);
        int motor_b_speed = (int)pid_control(tilt_error);

        /* Clamp speeds to valid range */
        if (motor_a_speed > PWM_RANGE) motor_a_speed = PWM_RANGE;
        if (motor_a_speed < -PWM_RANGE) motor_a_speed = -PWM_RANGE;
        if (motor_b_speed > PWM_RANGE) motor_b_speed = PWM_RANGE;
        if (motor_b_speed < -PWM_RANGE) motor_b_speed = -PWM_RANGE;

        /* Obstacle avoidance: reverse both motors at 50% speed */
        if (distance < OBSTACLE_THRESHOLD) {
            motor_a_speed = -PWM_RANGE / 2;
            motor_b_speed = -PWM_RANGE / 2;
            printf("Obstacle detected! Reversing motors.\n");
        }

        /* Apply motor commands */
        set_motor_speed(1, motor_a_speed);
        set_motor_speed(2, motor_b_speed);

        /* Log data */
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        /* 50 ms delay */
        gpioDelay(50000);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    stop_motors();
    if (log_file != NULL) {
        fclose(log_file);
    }
    cleanup_gpio();
    printf("Cleanup complete. Exiting.\n");
    return 0;
}

