#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_US 50000  /* 50 ms debounce */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output and ensure it starts OFF */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay to OFF state.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure touch sensor pin as input with internal pull-down */
    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d.\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_state = 0;  /* 0 = OFF, 1 = ON */
    int last_touch_state = 0;

    printf("Smart Light Switch running. Touch sensor on GPIO%d to toggle relay on GPIO%d.\n",
           TOUCH_SENSOR_GPIO, RELAY_GPIO);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_GPIO);
        if (touch_state < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d.\n", TOUCH_SENSOR_GPIO);
            break;
        }

        /* Detect rising edge: touch pressed (sensor pulls low, reads HIGH) */
        if (touch_state == 1 && last_touch_state == 0) {
            /* Debounce: wait and re-read */
            gpioDelay(DEBOUNCE_DELAY_US);
            int debounced = gpioRead(TOUCH_SENSOR_GPIO);
            if (debounced < 0) {
                fprintf(stderr, "Error: failed to read GPIO%d during debounce.\n", TOUCH_SENSOR_GPIO);
                break;
            }
            if (debounced == 1) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_GPIO, relay_state) != 0) {
                    fprintf(stderr, "Error: failed to write GPIO%d.\n", RELAY_GPIO);
                    break;
                }
                printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
                gpioDelay(DEBOUNCE_DELAY_US);  /* brief settle delay */
            }
        }
        last_touch_state = touch_state;
        gpioDelay(10000);  /* 10 ms poll interval */
    }

    /* Clean shutdown: ensure relay is OFF */
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

