#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define DEFAULT_SENSITIVITY 1.0
#define DEFAULT_SAMPLE_RATE 8000
#define DEFAULT_PERIOD_SIZE 1024
#define DEFAULT_UPDATE_DELAY_US 10000

#define NUM_SAMPLES 100

static volatile sig_atomic_t running = 1;
static double sensitivity = DEFAULT_SENSITIVITY;
static int sample_rate = DEFAULT_SAMPLE_RATE;
static int period_size = DEFAULT_PERIOD_SIZE;
static int update_delay_us = DEFAULT_UPDATE_DELAY_US;

static snd_pcm_t *pcm_handle = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (pcm_handle != NULL) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
        pcm_handle = NULL;
    }
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
}

static int init_pigpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(RED_PIN, sample_rate);
    gpioSetPWMfrequency(GREEN_PIN, sample_rate);
    gpioSetPWMfrequency(BLUE_PIN, sample_rate);
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);
    return 0;
}

static int init_alsa(void) {
    snd_pcm_hw_params_t *hw_params;
    snd_pcm_format_t format;
    snd_pcm_channel_mask_t channel_mask;
    snd_pcm_uframes_t period_size_uframes;
    snd_pcm_uframes_t period_size_bytes;
    int err;

    err = snd_pcm_open(&pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "Error: ALSA capture open failed: %s\n", snd_strerror(err));
        return -1;
    }

    hw_params = snd_pcm_hw_params_alloca();
    if (snd_pcm_hw_params_any(pcm_handle, hw_params) < 0) {
        fprintf(stderr, "Error: ALSA hw_params_any failed\n");
        goto fail;
    }

    if (snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED) < 0) {
        fprintf(stderr, "Error: ALSA set_access failed\n");
        goto fail;
    }

    if (snd_pcm_hw_params_set_format(pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE) < 0) {
        fprintf(stderr, "Error: ALSA set_format failed\n");
        goto fail;
    }

    channel_mask = SND_PCM_CHANNEL_MONO;
    if (snd_pcm_hw_params_set_channels(pcm_handle, hw_params, &channel_mask) < 0) {
        fprintf(stderr, "Error: ALSA set_channels failed\n");
        goto fail;
    }

    if (snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &sample_rate, 0) < 0) {
        fprintf(stderr, "Error: ALSA set_rate_near failed\n");
        goto fail;
    }

    period_size_uframes = period_size;
    if (snd_pcm_hw_params_set_period_size_near(pcm_handle, hw_params, &period_size_uframes, 0) < 0) {
        fprintf(stderr, "Error: ALSA set_period_size_near failed\n");
        goto fail;
    }

    period_size_bytes = period_size_uframes * snd_pcm_hw_params_get_channels(hw_params);
    if (snd_pcm_hw_params_set_period_size(pcm_handle, hw_params, period_size_bytes) < 0) {
        fprintf(stderr, "Error: ALSA set_period_size failed\n");
        goto fail;
    }

    if (snd_pcm_hw_params(pcm_handle, hw_params) < 0) {
        fprintf(stderr, "Error: ALSA hw_params failed\n");
        goto fail;
    }

    format = snd_pcm_hw_params_get_format(hw_params);
    if (snd_pcm_hw_params_get_format_bits_per_sample(hw_params, &format) < 0) {
        fprintf(stderr, "Error: ALSA get_format_bits_per_sample failed\n");
        goto fail;
    }
    printf("ALSA initialized: %d Hz, %d-bit, mono, %d-byte period\n",
           sample_rate, format, period_size_bytes);
    return 0;

fail:
    snd_pcm_close(pcm_handle);
    pcm_handle = NULL;
    return -1;
}

static int read_audio_samples(short *samples, int num_samples) {
    int frames_to_read = period_size;
    int frames_read = 0;
    int err;

    while (frames_read < num_samples) {
        err = snd_pcm_readi(pcm_handle, samples + frames_read * period_size_bytes / sizeof(short), frames_to_read);
        if (err < 0) {
            if (snd_pcm_prepare(pcm_handle) < 0) {
                fprintf(stderr, "Error: ALSA prepare failed: %s\n", snd_strerror(err));
                return -1;
            }
            frames_to_read = period_size;
            frames_read = 0;
            continue;
        }
        if (err == 0) {
            frames_to_read = period_size;
            frames_read = num_samples;
            break;
        }
        frames_read += err;
        frames_to_read -= err;
    }
    return frames_read;
}

static double calculate_rms(const short *samples, int num_samples) {
    double sum_sq = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double val = (double)samples[i];
        sum_sq += val * val;
    }
    return sqrt(sum_sq / num_samples);
}

static void map_rms_to_rgb(double rms, double *r, double *g, double *b) {
    double norm = rms / 32768.0;
    if (norm > 1.0) norm = 1.0;
    if (norm < 0.0) norm = 0.0;
    double coolness = 1.0 - norm;
    *r = coolness;
    *g = 1.0;
    *b = 0.0;
}

static void set_led_color(double r, double g, double b) {
    int red_val = (int)(r * 255.0);
    int green_val = (int)(g * 255.0);
    int blue_val = (int)(b * 255.0);
    gpioPWM(RED_PIN, red_val);
    gpioPWM(GREEN_PIN, green_val);
    gpioPWM(BLUE_PIN, blue_val);
}

static void simulate_audio_input(double *rms_out) {
    double amplitude = 0.0;
    for (int i = 0; i < NUM_SAMPLES; i++) {
        amplitude += (double)rand() / (double)(RAND_MAX + 1);
    }
    amplitude /= (double)NUM_SAMPLES;
    *rms_out = amplitude;
}

int main(int argc, char *argv[]) {
    int opt;
    short *audio_samples = NULL;

    while ((opt = getopt(argc, argv, "s:r:p:d:")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                if (sensitivity <= 0.0) {
                    fprintf(stderr, "Error: sensitivity must be positive\n");
                    return 1;
                }
                break;
            case 'r':
                sample_rate = atoi(optarg);
                if (sample_rate <= 0) {
                    fprintf(stderr, "Error: sample rate must be positive\n");
                    return 1;
                }
                break;
            case 'p':
                period_size = atoi(optarg);
                if (period_size <= 0) {
                    fprintf(stderr, "Error: period size must be positive\n");
                    return 1;
                }
                break;
            case 'd':
                update_delay_us = atoi(optarg);
                if (update_delay_us <= 0) {
                    fprintf(stderr, "Error: update delay must be positive\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity] [-r sample_rate] [-p period_size] [-d update_delay_us]\n", argv[0]);
                return 1;
        }
    }

    if (init_pigpio() != 0) {
        return 1;
    }

    if (init_alsa() != 0) {
        fprintf(stderr, "Warning: ALSA unavailable, running in simulation mode\n");
        sensitivity = DEFAULT_SENSITIVITY;
    }

    audio_samples = (short *)malloc(period_size * sizeof(short));
    if (audio_samples == NULL) {
        fprintf(stderr, "Error: memory allocation failed\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Mood light started. Sensitivity: %.2f, Sample rate: %d Hz, Period: %d, Delay: %d us\n",
           sensitivity, sample_rate, period_size, update_delay_us);

    while (running) {
        int frames_read = read_audio_samples(audio_samples, NUM_SAMPLES);
        if (frames_read < 0) {
            fprintf(stderr, "Error: audio read failed\n");
            break;
        }
        if (frames_read == 0) {
            usleep(update_delay_us);
            continue;
        }
        double rms = 0.0;
        if (init_alsa() != 0) {
            fprintf(stderr, "Error: ALSA initialization failed during resume\n");
            break;
        }
        if (frames_read > 0) {
            rms = calculate_rms(audio_samples, frames_read);
        } else {
            simulate_audio_input(&rms);
        }
        double r, g, b;
        map_rms_to_rgb(rms, &r, &g, &b);
        set_led_color(r, g, b);
        usleep(update_delay_us);
    }

    free(audio_samples);
    cleanup();
    printf("Mood light stopped.\n");
    return 0;
}

