#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

#define ENABLE_PON 0x01
#define ENABLE_AEN 0x02
#define ENABLE_ALL 0x03

static int i2c_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, TCS34725_COMMAND_BIT | reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_word(uint8_t reg_low, uint16_t *value) {
    uint8_t lo, hi;
    if (read_reg(reg_low, &lo) < 0) return -1;
    if (read_reg(reg_low + 1, &hi) < 0) return -1;
    *value = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int init_sensor(void) {
    if (write_reg(TCS34725_ENABLE, ENABLE_PON) < 0) return -1;
    gpioDelay(3000);
    if (write_reg(TCS34725_ATIME, 0xD5) < 0) return -1;
    if (write_reg(TCS34725_CONTROL, 0x03) < 0) return -1;
    if (write_reg(TCS34725_ENABLE, ENABLE_PON | ENABLE_AEN) < 0) return -1;
    gpioDelay(3000);
    return 0;
}

static int read_color_data(uint16_t *c, uint16_t *r, uint16_t *g, uint16_t *b) {
    if (read_word(TCS34725_CDATA, c) < 0) return -1;
    if (read_word(TCS34725_RDATA, r) < 0) return -1;
    if (read_word(TCS34725_GDATA, g) < 0) return -1;
    if (read_word(TCS34725_BDATA, b) < 0) return -1;
    return 0;
}

static void log_data(uint16_t c, uint16_t r, uint16_t g, uint16_t b) {
    time_t now = time(NULL);
    fprintf(fp, "%ld,%u,%u,%u,%u\n", (long)now, c, r, g, b);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fp = fopen("color_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening color_data.csv: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(fp, "timestamp,clear,red,green,blue\n");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t c, r, g, b;
    while (!terminate) {
        if (read_color_data(&c, &r, &g, &b) == 0) {
            log_data(c, r, g, b);
        } else {
            fprintf(stderr, "Error reading color data, setting to 0\n");
            c = r = g = b = 0;
        }
        gpioDelay(500000);
    }

    if (fp) fclose(fp);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

