#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_LAMPS 4
#define CHIP_NAME "gpiochip0"

/* BCM GPIO pin numbers for the four relay control lines */
static const unsigned int lamp_pins[NUM_LAMPS] = {17, 27, 22, 23};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts;
    ts.tv_sec = ms / 1000;
    ts.tv_nsec = (long)(ms % 1000) * 1000000L;
    nanosleep(&ts, NULL);
}

static void all_lamps_off(struct gpiod_line *lines[NUM_LAMPS])
{
    for (int i = 0; i < NUM_LAMPS; i++) {
        if (lines[i])
            gpiod_line_set_value(lines[i], 1); /* active-low: HIGH = off */
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_LAMPS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_LAMPS; i++)
        lines[i] = NULL;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Acquire each line as an output, initially LOW (relay energized = ON) */
    for (int i = 0; i < NUM_LAMPS; i++) {
        lines[i] = gpiod_chip_get_line(chip, lamp_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %u\n", lamp_pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "lamp-sim", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for pin %u\n", lamp_pins[i]);
            goto cleanup;
        }
    }

    printf("Sunrise/Sunset Simulator started. Press Ctrl+C to exit.\n");

    while (program_running) {
        /* Sunrise: gradual brightness increase over 1 hour */
        for (int i = 0; i < 3600 && program_running; i += 100) {
            int duty = i / 3600 * 4; /* 0..4 */
            for (int j = 0; j < NUM_LAMPS; j++) {
                int val = (gpiod_line_get_value(lines[j]) == 0) ? 1 : 0; /* active-low */
                if (gpiod_line_set_value(lines[j], val) < 0) {
                    perror("gpiod_line_set_value (sunrise)");
                    goto cleanup;
                }
            }
            sleep_ms(100);
        }

        /* Daytime: full brightness for 6 hours */
        for (int i = 0; i < 3600 * 6 && program_running; i += 100) {
            sleep_ms(100);
        }

        /* Sunset: gradual brightness decrease over 1 hour */
        for (int i = 0; i < 3600 && program_running; i += 100) {
            int duty = 4 - (3600 - i) / 3600 * 4; /* 4..0 */
            for (int j = 0; j < NUM_LAMPS; j++) {
                int val = (gpiod_line_get_value(lines[j]) == 0) ? 1 : 0; /* active-low */
                if (gpiod_line_set_value(lines[j], val) < 0) {
                    perror("gpiod_line_set_value (sunset)");
                    goto cleanup;
                }
            }
            sleep_ms(100);
        }

        /* Nighttime: off for 14.4 hours */
        for (int i = 0; i < 3600 * 14 && program_running; i += 100) {
            sleep_ms(100);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    all_lamps_off(lines);
    for (int i = 0; i < NUM_LAMPS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);
    return ret;
}

