#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define VIDEO_DURATION 5
#define DEBOUNCE_DELAY 200000  /* 200 ms in microseconds */
#define LOG_FILE_PATH "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int generate_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y%m%d_%H%M%S", timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int log_motion_event(const char *timestamp) {
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE_PATH, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }
    if (fprintf(log_file, "%s - Motion detected\n", timestamp) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("Error flushing log file");
        return -1;
    }
    return 0;
}

static int record_video(const char *timestamp) {
    char command[512];
    char filepath[256];

    if (generate_timestamp(filepath, sizeof(filepath)) != 0) {
        fprintf(stderr, "Error generating timestamp for video file\n");
        return -1;
    }
    snprintf(filepath, sizeof(filepath), "%s/%s.h264", VIDEO_DIR, timestamp);

    /* raspivid: 1920x1080, 15 fps, 10 seconds duration */
    snprintf(command, sizeof(command),
             "raspivid -w 1920 -h 1080 -fps 15 -t %d -o %s",
             VIDEO_DURATION * 1000000, filepath);

    int status = system(command);
    if (status == -1) {
        perror("Error executing raspivid");
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspivid exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_PIN);

    uint32_t last_trigger_tick = 0;

    while (running) {
        if (gpioRead(SENSOR_PIN) == 0) {
            uint32_t now = gpioTick();
            if (now - last_trigger_tick >= DEBOUNCE_DELAY) {
                last_trigger_tick = now;

                char timestamp[32];
                if (generate_timestamp(timestamp, sizeof(timestamp)) == 0) {
                    printf("Motion detected at %s\n", timestamp);

                    if (record_video(timestamp) != 0) {
                        fprintf(stderr, "Failed to record video\n");
                    }
                    if (log_motion_event(timestamp) != 0) {
                        fprintf(stderr, "Failed to log motion event\n");
                    }
                } else {
                    fprintf(stderr, "Failed to generate timestamp\n");
                }
            }
        }
        gpioDelay(10000); /* 10 ms polling interval */
    }

    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

