#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* MPU-6050 I2C address (AD0 low) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define SMPLRT_DIV   0x19
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_XOUT_L  0x44
#define GYRO_YOUT_H  0x45
#define GYRO_YOUT_L  0x46
#define GYRO_ZOUT_H  0x47
#define GYRO_ZOUT_L  0x48

/* Sensitivity for ±250°/s range: 131 LSB per °/s */
#define GYRO_SENSITIVITY 131.0f

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Sampling interval: 10 ms (100 Hz) */
#define SAMPLE_INTERVAL_US 10000

/* Re-init retries before logging an error */
#define MAX_REINIT_ATTEMPTS 3

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Initialize MPU-6050: wake, set sample rate, set gyro range          */
/* ------------------------------------------------------------------ */
static int init_mpu6050(int handle)
{
    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle */

    /* Set sample rate divider: 1 kHz / (1 + 125) = 7.8125 Hz -> 125 Hz */
    if (i2cWriteByteData(handle, SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error writing SMPLRT_DIV: %s\n", strerror(errno));
        return -1;
    }

    /* Set gyroscope full-scale range to ±250°/s (FS_SEL = 0) */
    if (i2cWriteByteData(handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing GYRO_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of gyroscope data and convert to °/s                  */
/* ------------------------------------------------------------------ */
static int read_gyro_data(int handle, float *x, float *y, float *z)
{
    char buffer[6];

    /*
     * i2cReadI2CBlockData returns the number of bytes read, or < 0 on error.
     * On success, buffer[0..5] contains GYRO_XOUT_H through GYRO_ZOUT_L.
     */
    int bytes_read = i2cReadI2CBlockData(handle, GYRO_XOUT_H, buffer, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error reading gyroscope data: %s (read %d bytes)\n",
                strerror(errno), bytes_read);
        return -1;
    }

    /* Combine high and low bytes (big-endian) */
    int16_t raw_x = (int16_t)((buffer[0] << 8) | (uint8_t)buffer[1]);
    int16_t raw_y = (int16_t)((buffer[2] << 8) | (uint8_t)buffer[3]);
    int16_t raw_z = (int16_t)((buffer[4] << 8) | (uint8_t)buffer[5]);

    /* Convert to °/s */
    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one data row to the CSV file                                    */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x, float y, float z)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp_ms = (long long)ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL;

    fprintf(fp, "%lld.%03lld,%.2f,%.2f,%.2f\n",
            timestamp_ms, 0, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Attempt to re-initialize the MPU-6050                               */
/* ------------------------------------------------------------------ */
static int reinit_mpu6050(int handle)
{
    fprintf(stderr, "Attempting to re-initialize MPU-6050...\n");

    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error re-waking MPU-6050: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle */

    if (i2cWriteByteData(handle, SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error re-setting sample rate: %s\n", strerror(errno));
        return -1;
    }

    if (i2cWriteByteData(handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error re-setting gyro range: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at MPU-6050 address */
    g_i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, MPU6050_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050(g_i2c_handle) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("gyro_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
        fflush(g_log_file);
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fprintf(stderr, "MPU-6050 vibration monitor started. Logging to gyro_log.csv\n");

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;

        if (read_gyro_data(g_i2c_handle, &x, &y, &z) == 0) {
            log_data(g_log_file, x, y, z);
        } else {
            /* Attempt re-initialization up to MAX_REINIT_ATTEMPTS times */
            int attempt;
            for (attempt = 0; attempt < MAX_REINIT_ATTEMPTS; attempt++) {
                if (reinit_mpu6050(g_i2c_handle) == 0) {
                    break;
                }
                gpioDelay(100000); /* 100 ms before retry */
            }

            if (attempt == MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Failed to re-initialize MPU-6050 after %d attempts.\n",
                        MAX_REINIT_ATTEMPTS);
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

