#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define RELAY_1_PIN 4
#define RELAY_2_PIN 17
#define RELAY_3_PIN 27
#define RELAY_4_PIN 22
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    int pins[] = {RELAY_1_PIN, RELAY_2_PIN, RELAY_3_PIN, RELAY_4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(pins[i], 1) != 0) {
            fprintf(stderr, "Error: failed to drive GPIO %d HIGH.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void) {
    int pins[] = {RELAY_1_PIN, RELAY_2_PIN, RELAY_3_PIN, RELAY_4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioWrite(pins[i], 1);
    }
    gpioTerminate();
}

static int read_moisture_sensor(int pin) {
    return rand() % 101;
}

static void control_relay(int pin, int moisture_level) {
    int state = (moisture_level < MOISTURE_THRESHOLD) ? 0 : 1;
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d.\n", pin);
    }
}

static void log_data(int zone, int moisture_level, int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s - Zone %d: Moisture Level = %d, Relay State = %d\n",
            timestamp, zone, moisture_level, relay_state);
    fflush(log_file);
}

int main(void) {
    srand(time(NULL));
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (initialize_gpio() != 0) {
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup_gpio();
        return 1;
    }
    printf("Smart Greenhouse Irrigation System started. Press Ctrl+C to exit.\n");
    while (running) {
        for (int i = 1; i <= 4; ++i) {
            int moisture_level = read_moisture_sensor(i);
            control_relay(i, moisture_level);
            int relay_state = gpioRead(i);
            log_data(i, moisture_level, relay_state);
        }
        sleep(POLL_INTERVAL_SEC);
    }
    printf("\nShutting down...\n");
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
    }
    return 0;
}

