#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32
#define ADXL345_RANGE_2G 0x0B
#define ADXL345_MEASURE 0x08
#define FREEFALL_THRESHOLD 0.2f
#define FREEFALL_DURATION_MS 500
#define SAMPLE_INTERVAL_MS 100
#define ALARM_GPIO 27
#define ALARM_HOLD_MS 5000
#define LOG_FILE "freefall.log"

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_adxl345(int handle) {
    if (i2cWriteByteData(handle, ADXL345_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set ADXL345 to standby mode.\n");
        return -1;
    }
    if (i2cWriteByteData(handle, ADXL345_DATA_FORMAT, ADXL345_RANGE_2G) < 0) {
        fprintf(stderr, "Error: Could not set DATA_FORMAT register.\n");
        return -1;
    }
    if (i2cWriteByteData(handle, ADXL345_POWER_CTL, ADXL345_MEASURE) < 0) {
        fprintf(stderr, "Error: Could not set POWER_CTL register.\n");
        return -1;
    }
    return 0;
}

static int read_accelerometer(int handle, float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(handle, ADXL345_DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error: Could not read accelerometer data.\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    *x = (float)raw_x / 256.0f;
    *y = (float)raw_y / 256.0f;
    *z = (float)raw_z / 256.0f;
    return 0;
}

static int detect_freefall(float x, float y, float z) {
    return (fabsf(x) < FREEFALL_THRESHOLD && fabsf(y) < FREEFALL_THRESHOLD && fabsf(z) < FREEFALL_THRESHOLD);
}

static void trigger_alarm(int gpio) {
    gpioWrite(gpio, 1);
    gpioDelay(ALARM_HOLD_MS * 1000);
    gpioWrite(gpio, 0);
}

static void log_freefall(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file.\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at address 0x%02X.\n", ADXL345_ADDRESS);
        gpioTerminate();
        return 1;
    }
    if (init_adxl345(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0);
    signal(SIGINT, signal_handler);
    printf("Freefall detection started. Press Ctrl+C to exit.\n");
    uint32_t freefall_start_time = 0;
    while (!terminate) {
        float x, y, z;
        if (read_accelerometer(i2c_handle, &x, &y, &z) == 0) {
            if (detect_freefall(x, y, z)) {
                if (freefall_start_time == 0) {
                    freefall_start_time = gpioTick();
                } else if ((gpioTick() - freefall_start_time) >= (FREEFALL_DURATION_MS * 1000)) {
                    printf("Freefall detected!\n");
                    log_freefall(x, y, z);
                    trigger_alarm(ALARM_GPIO);
                    freefall_start_time = 0;
                }
            } else {
                freefall_start_time = 0;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }
    i2cClose(i2c_handle);
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

