#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <string.h>
#include <errno.h>
#include <pthread.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 18
#define TIMEOUT_US 100000  /* 100 ms timeout for echo */
#define MAX_DISTANCE_US 23200  /* ~4 meters */
#define TRIGGER_INTERVAL_US 200000  /* 200 ms between triggers */
#define LOG_FILE "distance_log.txt"

/* Shared state protected by mutex */
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static volatile int pulse_valid = 0;
static volatile uint32_t pulse_width = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

/* ---- Interrupt callbacks ---- */

static void trigger_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)userdata;
    start_tick = tick;
    echo_received = 0;
    pulse_valid = 0;
    pulse_width = 0;
}

static void echo_rising_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)userdata;
    pthread_mutex_lock(&mutex);
    start_tick = tick;
    echo_received = 1;
    pthread_mutex_unlock(&mutex);
}

static void echo_falling_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)userdata;
    pthread_mutex_lock(&mutex);
    end_tick = tick;
    pthread_mutex_unlock(&mutex);
}

/* ---- Helpers ---- */

static uint32_t tick_diff(uint32_t start, uint32_t end)
{
    return end - start;  /* unsigned subtraction wraps correctly */
}

static double calculate_distance(uint32_t pulse_width_us)
{
    /* Speed of sound ~343 m/s => 0.0343 cm/µs; round trip -> /2 */
    return (double)pulse_width_us * 0.0343 / 2.0;
}

static void log_distance(double distance_cm)
{
    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm tm_info;
    localtime_r(&tv.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s.%09ld,%.2f\n", timestamp, (long)tv.tv_usec, distance_cm);
    fflush(log_file);
}

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ---- Main ---- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN pull-down\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000);  /* 50 ms settle */

    /* Register interrupt callbacks */
    if (gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, trigger_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set trigger ISR\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, echo_rising_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set echo rising ISR\n");
        gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ECHO_PIN, FALLING_EDGE, 0, echo_falling_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set echo falling ISR\n");
        gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, NULL, NULL);
