#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define BUZZER_GPIO 17

#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28

#define DEFAULT_FREEFALL_THRESHOLD 0.2f
#define DEFAULT_IMPACT_THRESHOLD 1.5f
#define DEFAULT_BUZZER_DURATION 1.0f
#define DEFAULT_SAMPLE_RATE 100.0f
#define DEFAULT_SENSITIVITY 16384.0f

#define MAX_RETRIES 3
#define SAMPLE_DELAY_US (1000000 / DEFAULT_SAMPLE_RATE)

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteByteData(i2c_handle, reg, value);
        if (rc == 0) return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d): rc=%d\n", reg, attempt + 1, rc);
        gpioDelay(10000);
    }
    return -1;
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, uint32_t len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
        if (rc == (int)len) return 0;
        fprintf(stderr, "I2C block read from reg 0x%02X failed (attempt %d): rc=%d\n", reg, attempt + 1, rc);
        gpioDelay(10000);
    }
    return -1;
}

static int init_lis3dh(void) {
    if (i2c_write_reg(CTRL_REG1, 0x77) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG1\n");
        return -1;
    }
    if (i2c_write_reg(CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG4\n");
        return -1;
    }
    return 0;
}

static int read_acceleration(float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block(OUT_X_L, buf, 6) != 0) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x / DEFAULT_SENSITIVITY;
    *y = (float)raw_y / DEFAULT_SENSITIVITY;
    *z = (float)raw_z / DEFAULT_SENSITIVITY;
    return 0;
}

static void activate_buzzer(float duration) {
    gpioWrite(BUZZER_GPIO, 1);
    gpioDelay((uint32_t)duration * 1000000);
    gpioWrite(BUZZER_GPIO, 0);
}

int main(int argc, char *argv[]) {
    float freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
    float impact_threshold = DEFAULT_IMPACT_THRESHOLD;
    float buzzer_duration = DEFAULT_BUZZER_DURATION;
    float sensitivity = DEFAULT_SENSITIVITY;

    if (argc > 1) freefall_threshold = (float)atof(argv[1]);
    if (argc > 2) impact_threshold = (float)atof(argv[2]);
    if (argc > 3) buzzer_duration = (float)atof(argv[3]);
    if (argc > 4) sensitivity = (float)atof(argv[4]);

    if (sensitivity <= 0) {
        fprintf(stderr, "Sensitivity must be positive\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", LIS3DH_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_lis3dh() != 0) {
        fprintf(stderr, "LIS3DH initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Fall detection started. Freefall: %.2f g, Impact: %.2f g, Buzzer: %.1fs\n",
           freefall_threshold, impact_threshold, buzzer_duration);

    while (!terminate) {
        float x, y, z;
        if (read_acceleration(&x, &y, &z) != 0) {
            fprintf(stderr, "Read error, continuing...\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        float magnitude = sqrtf(x * x + y * y + z * z);

        if (magnitude < freefall_threshold) {
            printf("Freefall detected! Magnitude: %.2f g\n", magnitude);
            activate_buzzer(buzzer_duration);
        }

        if (magnitude > impact_threshold) {
            printf("Impact detected! Magnitude: %.2f g\n", magnitude);
            activate_buzzer(buzzer_duration);
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(BUZZER_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

