static int set_motor_pins(int in1, int in2, int in3, int in4, int state) {
    if (gpioWrite(in1, state) != 0) return -1;
    if (gpioWrite(in2, state) != 0) return -1;
    if (gpioWrite(in3, state) != 0) return -1;
    if (gpioWrite(in4, state) != 0) return -1;
