    // Move Y-axis forward
    if (move_motor(MOTOR2_IN1, MOTOR2_IN2, MOTOR2_IN3, MOTOR2_IN4, steps_per_side, 1) != 0) return -1;

    // Move X-axis reverse
    if (move_motor(in1, in2, in3, in4, steps_per_side, -1) != 0) return -1;

    // Move Y-axis reverse
    if (move_motor(MOTOR2_IN1, MOTOR2_IN2, MOTOR2_IN3, MOTOR2_IN4, steps_per_side, -1) != 0) return -1;

