#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* LIS3DH I2C address (SA0 tied to GND) */
#define LIS3DH_ADDR_DEFAULT 0x18

/* LIS3DH register addresses */
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

/* Configuration values */
#define CTRL1_VAL 0x57  /* ±2g, high-resolution, 100 Hz ODR */
#define CTRL4_VAL 0x88  /* Enable XYZ high-resolution output */

/* Default threshold in g */
#define DEFAULT_THRESHOLD 2.0f

/* Sampling interval in microseconds (10 Hz) */
#define SAMPLE_INTERVAL_US 100000

/* Global state */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;
static int i2c_address = LIS3DH_ADDR_DEFAULT;
static float acceleration_threshold = DEFAULT_THRESHOLD;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a register                                  */
/* ------------------------------------------------------------------ */
static int write_reg(uint8_t reg, uint8_t value)
{
    if (i2cWriteByteData(i2c_handle, reg, value) < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X\n", value, reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the LIS3DH accelerometer                                 */
/* ------------------------------------------------------------------ */
static int init_lis3dh(void)
{
    if (write_reg(CTRL_REG1, CTRL1_VAL) < 0)
        return -1;
    if (write_reg(CTRL_REG4, CTRL4_VAL) < 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration data (g) from the LIS3DH                           */
/* ------------------------------------------------------------------ */
static int read_acceleration(float *x, float *y, float *z)
{
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    int16_t raw_x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);

    /* High-resolution mode: 12-bit left-justified -> shift right 4 */
    *x = (float)raw_x >> 4;
    *y = (float)raw_y >> 4;
    *z = (float)raw_z >> 4;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a high-acceleration event to the system log                    */
/* ------------------------------------------------------------------ */
static void log_event(float x, float y, float z)
{
    FILE *fp = fopen("/var/log/high_acceleration.log", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - High acceleration: X=%.3f g, Y=%.3f g, Z=%.3f g\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                x, y, z);
    } else {
        fprintf(fp, "Timestamp unavailable - High acceleration: X=%.3f g, Y=%.3f g, Z=%.3f g\n",
                x, y, z);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Trigger a system shutdown                                           */
/* ------------------------------------------------------------------ */
static void trigger_shutdown(void)
{
    fprintf(stderr, "Shutting down system...\n");
    int ret = system("sudo shutdown -h now");
    if (ret == -1) {
        perror("Error executing shutdown command");
    }
}

/* ------------------------------------------------------------------ */
/* Parse command-line arguments                                        */
/* ------------------------------------------------------------------ */
static void parse_arguments(int argc, char *argv[])
{
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 16);
                if (i2c_address < 0x08 || i2c_address > 0x77) {
                    fprintf(stderr, "Invalid I2C address: 0x%02X (must be 0x08-0x77)\n", i2c_address);
                    exit(EXIT_FAILURE);
                }
                break;
            case 't':
                acceleration_threshold = strtof(optarg, NULL);
                if (acceleration_threshold <= 0.0f) {
                    fprintf(stderr, "Invalid threshold: %.2f (must be > 0)\n", acceleration_threshold);
                    exit(EXIT_FAILURE);
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold_g]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    parse_arguments(argc, argv);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (non-hardware environment?)\n");
        return EXIT_SUCCESS;
    }

    /* Open I2C bus 1 (default for Raspberry Pi 5) */
    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", i2c_address, i2c_handle);
        gpioTerminate();
        return EXIT_SUCCESS;
    }

    /* Initialize the LIS3DH */
    if (init_lis3dh() < 0) {
        fprintf(stderr, "Error initializing LIS3DH at address 0x%02X\n", i2c_address);
        cleanup();
        return EXIT_SUCCESS;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error registering SIGINT handler");
        cleanup();
        return EXIT_SUCCESS;
    }

    printf("Monitoring acceleration on I2C address 0x%02X (threshold %.2f g)...\n",
           i2c_address, acceleration_threshold);

    /* Main loop */
    while (program_running) {
        float x, y, z;

        if (read_acceleration(&x, &y, &z) == 0) {
            if (fabsf(x) > acceleration_threshold ||
                fabsf(y) > acceleration_threshold ||
                fabsf(z) > acceleration_threshold) {
                log_event(x, y, z);
                trigger_shutdown();
                break;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

