static struct gpiod_chip *chip = NULL;
static struct gpiod_line *left_line = NULL;
static struct gpiod_line *center_line = NULL;
static struct gpiod_line *right_line = NULL;
static struct gpiod_line *alert_line = NULL;
static CircularBuffer sensor_buffer;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void add_to_circular_buffer(CircularBuffer *cb, SensorData data) {
    cb->data[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static int read_sensor(struct gpiod_line *line) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Error reading sensor on line: %s\n", strerror(errno));
        return -1;
    }
    return val;
}

static SensorData read_sensors(void) {
    SensorData data;
    data.left = read_sensor(left_line);
    data.center = read_sensor(center_line);
    data.right = read_sensor(right_line);
    return data;
}

static void check_alert_condition(void) {
    if (sensor_buffer.count < ALERT_THRESHOLD) return;
    int no_line_count = 0;
    for (int i = 0; i < sensor_buffer.count; i++) {
        if (sensor_buffer.data[i].center == 1) no_line_count++;
    }
    if (no_line_count == sensor_buffer.count) {
        if (gpiod_line_set_value(alert_line, 1) < 0) {
            fprintf(stderr, "Error setting alert pin HIGH: %s\n", strerror(errno));
        }
        sleep(ALERT_DURATION_SEC);
        if (gpiod_line_set_value(alert_line, 0) < 0) {
            fprintf(stderr, "Error setting alert pin LOW: %s\n", strerror(errno));
        }
    }
}

static void line_following_logic(SensorData data) {
    if (data.left == 0 && data.center == 0 && data.right == 0) {
        printf("Stopping...\n");
        return;
    }
    if (data.left == 0) {
        printf("Turning left\n");
        return;
    }
    if (data.right == 0) {
        printf("Turning right\n");
        return;
    }
    printf("Moving forward\n");
}

static void cleanup(void) {
    if (alert_line) {
        gpiod_line_set_value(alert_line, 0);
        gpiod_line_release(alert_line);
    }
    if (left_line) gpiod_line_release(left_line);
    if (center_line) gpiod_line_release(center_line);
    if (right_line) gpiod_line_release(right_line);
