#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define SI7210_ADDR 0x30
#define RELAY_GPIO 17
#define THRESHOLD_MT 5.0
#define SAMPLE_INTERVAL_US 100000
#define POLL_TIMEOUT_MS 50
#define POLL_DELAY_US 1000
#define CONVERSION_DELAY_US 10000

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void log_event(const char *message) {
    FILE *fp = fopen("magnetic_events.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", ts, message);
    }
    fclose(fp);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_si7210_field(int handle, float *field_mt) {
    if (i2cWriteByteData(handle, 0xC1, 0x01) < 0) {
        log_event("Error: Failed to start conversion.");
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);

    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        int status = i2cReadByteData(handle, 0xC1);
        if (status < 0) {
            log_event("Error: Failed to read conversion status.");
            return -1;
        }
        if (status == 0x00) break;
        gpioDelay(POLL_DELAY_US);
    }

    if (status != 0x00) {
        log_event("Error: Conversion timeout.");
        return -1;
    }

    int lsb = i2cReadByteData(handle, 0xC0);
    if (lsb < 0) {
        log_event("Error: Failed to read LSB.");
        return -1;
    }
    int msb = i2cReadByteData(handle, 0xC0 + 1);
    if (msb < 0) {
        log_event("Error: Failed to read MSB.");
        return -1;
    }

    int16_t field_raw = (int16_t)((msb << 8) | lsb);
    *field_mt = (float)field_raw * 25.0 / 1000.0;
    return 0;
}

static void control_relay(int gpio, int state) {
    if (gpioWrite(gpio, state) < 0) {
        log_event("Error: Failed to write relay GPIO.");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting relay GPIO mode\n");
        cleanup();
        return 1;
    }
    control_relay(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    log_event("Program started.");

    while (running) {
        float field_mt;
        if (read_si7210_field(i2c_handle, &field_mt) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Field: %.2f mT", field_mt);
            log_event(msg);

            if (field_mt > (THRESHOLD_MT * 100.0)) {
                control_relay(RELAY_GPIO, 1);
                log_event("Relay activated.");
            } else {
                control_relay(RELAY_GPIO, 0);
                log_event("Relay deactivated.");
            }
        } else {
            log_event("Error reading sensor data.");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    log_event("Program terminated.");
    cleanup();
    return 0;
}

