#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS              1
#define SENSOR1_ADDR         0x08
#define SENSOR2_ADDR         0x09
#define GPIO_RELAY           18
#define FLOW_THRESHOLD_MLM   5.0f
#define SCALE_FACTOR         1.0f / 1500.0f
#define POLL_DELAY_US        100000  /* 100 ms */
#define LOG_FILE             "flow_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle1 = -1;
static int g_i2c_handle2 = -1;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR) ---- */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_sensor(int handle)
{
    /* Start continuous measurement: command 0x3608 */
    uint8_t cmd[2] = { 0x36, 0x08 };
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] Failed to send start-measurement command to handle %d\n", handle);
        return -1;
    }
    /* Allow sensor to settle after command */
    gpioDelay(20000); /* 20 ms */
    return 0;
}

static int read_flow_rate(int handle, float *flow_rate)
{
    uint8_t buf[3];
    int n = i2cReadDevice(handle, (char *)buf, 3);
    if (n != 3) {
        fprintf(stderr, "[WARN] I2C read returned %d bytes (expected 3) from handle %d\n", n, handle);
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[WARN] CRC mismatch on handle %d\n", handle);
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw * SCALE_FACTOR;
    return 0;
}

static void log_flow_data(float f1, float f2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] Cannot open %s for append\n", LOG_FILE);
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
            tbuf, ts.tv_nsec / 1000000, f1, f2);
    fflush(fp);
    fclose(fp);
}

static void cleanup(void)
{
    if (g_i2c_handle1 >= 0) {
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
    }
    if (g_i2c_handle2 >= 0) {
        i2cClose(g_i2c_handle2);
        g_i2c_handle2 = -1;
    }
    gpioWrite(GPIO_RELAY, 0);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (g_i2c_handle1 < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed for sensor 1 (addr 0x%02X): %d\n", SENSOR1_ADDR, g_i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (g_i2c_handle2 < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed for sensor 2 (addr 0x%02X): %d\n", SENSOR2_ADDR, g_i2c_handle2);
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_handle1) != 0 || init_sensor(g_i2c_handle2) != 0) {
        fprintf(stderr, "[FATAL] Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode failed for GPIO %d\n", GPIO_RELAY);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(GPIO_RELAY, 0) != 0) {
        fprintf(stderr, "[FATAL] gpioWrite failed for GPIO %d\n", GPIO_RELAY);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction failed; continuing without graceful shutdown signal\n");
    }

    printf("Monitoring flow sensors (threshold %.1f ml/min). Press Ctrl+C to exit.\n", FLOW_THRESHOLD_MLM);

    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = read_flow_rate(g_i2c_handle1, &f1);
        int ok2 = read_flow_rate(g_i2c_handle2, &f2);

        if (ok1 == 0 && ok2 == 0) {
            if (f1 < FLOW_THRESHOLD_MLM || f2 < FLOW_THRESHOLD_MLM) {
                gpioWrite(GPIO_RELAY, 1);
            } else {
                gpioWrite(GPIO_RELAY, 0);
            }
            log_flow_data(f1, f2);
        } else {
            /* On read error, de-energize relay for safety */
            gpioWrite(GPIO_RELAY, 0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

