#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN   22
#define MOTOR_IN1_PIN   23
#define MOTOR_IN2_PIN   24

#define POLL_INTERVAL_US  200000   /* 200 ms */
#define MOTOR_RUN_US      5000000  /* 5 s   */
#define DRY_SUPPRESS_MS   3000     /* 3 s   */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) < 0) {
        syslog(LOG_ERR, "gpioWrite(pin=%u, level=%u) failed", pin, level);
        return -1;
    }
    return 0;
}

static int motor_stop(void)
{
    int rc = 0;
    rc |= safe_write(MOTOR_ENA_PIN, 0);
    rc |= safe_write(MOTOR_IN1_PIN, 0);
    rc |= safe_write(MOTOR_IN2_PIN, 0);
    return rc;
}

static int motor_start(void)
{
    int rc = 0;
    rc |= safe_write(MOTOR_ENA_PIN, 1);
    rc |= safe_write(MOTOR_IN1_PIN, 1);
    rc |= safe_write(MOTOR_IN2_PIN, 0);
    return rc;
}

static int motor_stop_and_wait(void)
{
    if (motor_stop() < 0)
        return -1;
    gpioDelay(100000);  /* 100 ms settle */
    return 0;
}

static int close_window(void)
{
    syslog(LOG_INFO, "Closing window...");
    if (motor_start() < 0)
        return -1;

    for (int elapsed = 0; elapsed < MOTOR_RUN_US && g_running; elapsed += POLL_INTERVAL_US) {
        gpioDelay(POLL_INTERVAL_US);
    }

    if (!g_running) {
        syslog(LOG_INFO, "Shutdown requested during motor run; stopping motor...");
        motor_stop_and_wait();
        return -1;
    }

    if (motor_stop() < 0)
        return -1;

    syslog(LOG_INFO, "Window closed.");
    return 0;
}

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Rain-actuated window controller starting.");

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %m");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "pigpio initialised.");

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(rain=%d) failed", RAIN_SENSOR_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(rain=%d) failed", RAIN_SENSOR_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(motor) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Rain sensor on GPIO %d, L298N ENA=GPIO %d, IN1=GPIO %d, IN2=GPIO %d",
           RAIN_SENSOR_PIN, MOTOR_ENA_PIN, MOTOR_IN1_PIN, MOTOR_IN2_PIN);

    int last_dry_count = 0;
    int last_rain_state = 1;  /* assume dry at startup */

    while (g_running) {
        int rain_state = gpioRead(RAIN_SENSOR_PIN);
        if (rain_state < 0) {
            syslog(LOG_ERR, "gpioRead(rain=%d) failed", RAIN_SENSOR_PIN);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        /* Rising edge: dry -> wet (DO goes LOW) */
        if (rain_state == 0 && last_rain_state == 1) {
            syslog(LOG_INFO, "Rain detected (sensor LOW). Closing window.");
            if (close_window() < 0) {
                syslog(LOG_ERR, "close_window() failed; continuing to suppress triggers");
            }
            last_dry_count = 0;
        } else if (rain_state == 1) {
            last_dry_count++;
            if (last_dry_count >= DRY_SUPPRESS_MS / (POLL_INTERVAL_US / 1000)) {
                last_rain_state = 1;
            }
        } else {
            last_dry_count = 0;
            last_rain_state = 0;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down.");
    motor_stop();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

