#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define BUTTON_LOCK    21
#define BUTTON_UNLOCK  22

#define LOCK_PULSE_US  2000
#define UNLOCK_PULSE_US 1000
#define DEBOUNCE_US    200000   /* 200 ms */
#define POLL_US        10000    /* 10 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo(int pin, int pulse_us)
{
    if (gpioServo(pin, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo(pin=%d, pulse=%d) failed\n", pin, pulse_us);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Stop servo pulses and release pigpio resources */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure button pins as inputs with internal pull-ups */
    if (gpioSetMode(BUTTON_LOCK, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(BUTTON_LOCK) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUTTON_UNLOCK, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(BUTTON_UNLOCK) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_LOCK, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(BUTTON_LOCK) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_UNLOCK, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(BUTTON_UNLOCK) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure servo starts in a known (stopped) state */
    if (set_servo(SERVO_PIN, 0) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Door lock control started. Press Ctrl+C to exit.\n");
    printf("  GPIO %d: lock (2000 us pulse)\n", BUTTON_LOCK);
    printf("  GPIO %d: unlock (1000 us pulse)\n", BUTTON_UNLOCK);

    int last_lock_state = 0;
    int last_unlock_state = 0;

    while (g_running) {
        int lock_pressed = (gpioRead(BUTTON_LOCK) == 0);
        int unlock_pressed = (gpioRead(BUTTON_UNLOCK) == 0);

        if (lock_pressed && !last_lock_state) {
            if (set_servo(SERVO_PIN, LOCK_PULSE_US) == 0) {
                printf("Lock engaged\n");
            }
            last_lock_state = 1;
        }

        if (unlock_pressed && !last_unlock_state) {
            if (set_servo(SERVO_PIN, UNLOCK_PULSE_US) == 0) {
                printf("Lock disengaged\n");
            }
            last_unlock_state = 1;
        }

        /* Debounce: wait for button release and a short extra delay */
        if (lock_pressed) {
            while (g_running && gpioRead(BUTTON_LOCK) == 0) {
                gpioDelay(POLL_US);
            }
            gpioDelay(DEBOUNCE_US);
        }
        if (unlock_pressed) {
            while (g_running && gpioRead(BUTTON_UNLOCK) == 0) {
                gpioDelay(POLL_US);
            }
            gpioDelay(DEBOUNCE_US);
        }

        gpioDelay(POLL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

