#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_PIN 4
#define FLOOD_PIN 17
#define LOG_FILE "security_log.txt"
#define FLOOD_ON_TIME_SEC 60
#define POLL_DELAY_US 100000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int log_event(const char *event_type, const char *description) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - %s: %s\n", timestamp, event_type, description) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose log failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int activate_floodlight(void) {
    if (gpioWrite(FLOOD_PIN, 1) != 0) {
        fprintf(stderr, "Failed to turn on floodlight on GPIO %d\n", FLOOD_PIN);
        return -1;
    }
    return 0;
}

static int deactivate_floodlight(void) {
    if (gpioWrite(FLOOD_PIN, 0) != 0) {
        fprintf(stderr, "Failed to turn off floodlight on GPIO %d\n", FLOOD_PIN);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    deactivate_floodlight();
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR pin %d as input\n", PIR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOOD_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set FLOOD pin %d as output\n", FLOOD_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(FLOOD_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize floodlight to OFF on GPIO %d\n", FLOOD_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Smart Security Light System started. Monitoring PIR on GPIO %d, floodlight on GPIO %d.\n",
           PIR_PIN, FLOOD_PIN);
    printf("Press Ctrl+C to exit.\n");

    int last_pir_state = gpioRead(PIR_PIN);
    if (last_pir_state < 0) {
        fprintf(stderr, "Failed to read initial PIR state on GPIO %d\n", PIR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int pir_state = gpioRead(PIR_PIN);
        if (pir_state < 0) {
            fprintf(stderr, "Failed to read PIR sensor on GPIO %d\n", PIR_PIN);
            break;
        }

        if (pir_state == 1 && last_pir_state == 0) {
            printf("Motion detected! Activating floodlight for %d seconds.\n", FLOOD_ON_TIME_SEC);
            if (activate_floodlight() != 0) {
                break;
            }

            if (log_event("ACTIVATION", "Floodlight activated on motion detection") != 0) {
                deactivate_floodlight();
                break;
            }

            for (int elapsed = 0; elapsed < FLOOD_ON_TIME_SEC && g_running; elapsed++) {
                gpioDelay(POLL_DELAY_US);
            }

            if (!g_running) {
                break;
            }

            if (deactivate_floodlight() != 0) {
                break;
            }

            if (log_event("DEACTIVATION", "Floodlight deactivated after %d seconds", elapsed) != 0) {
                break;
            }
        }

        last_pir_state = pir_state;
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

