#include <unistd.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define I2C_BUS 1

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_MHD_RISING     0x02
#define MPR121_NHD_RISING     0x03
#define MPR121_NCL_RISING     0x04
#define MPR121_FDL_RISING     0x05
