#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <errno.h>
#include <stdarg.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define PWM_PERIOD_US 2000   /* 50 Hz */
#define PWM_RANGE 180
#define LOG_FILE "security.log"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;

static void log_message(const char *fmt, ...) {
    if (!log_fp) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_fp, "%s ", ts);
    va_list ap;
    va_start(ap, fmt);
    vfprintf(log_fp, fmt, ap);
    va_end(ap);
    fprintf(log_fp, "\n");
    fflush(log_fp);
    syslog(LOG_INFO, "%s", ts);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip4: %s", strerror(errno));
        return -1;
    }
    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        syslog(LOG_ERR, "Failed to get servo line %d: %s", SERVO_PIN, strerror(errno));
        return -1;
    }
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR line %d: %s", PIR_PIN, strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(servo_line, "servo", 0) < 0) {
        syslog(LOG_ERR, "Failed to request servo line as output: %s", strerror(errno));
        return -1;
    }
    if (gpiod_line_request_input(pir_line, "pir") < 0) {
        syslog(LOG_ERR, "Failed to request PIR line as input: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static void set_servo_angle(int angle) {
    if (angle < 0 || angle > PWM_RANGE) {
        log_message("Invalid servo angle %d (0-%d).", angle, PWM_RANGE);
        return;
    }
    int pulse_us = (angle * PWM_PERIOD_US) / PWM_RANGE;
    if (gpiod_line_set_value(servo_line, 1) < 0) {
        log_message("Failed to set servo high: %s", strerror(errno));
        return;
    }
    usleep(pulse_us);
    if (gpiod_line_set_value(servo_line, 0) < 0) {
        log_message("Failed to set servo low: %s", strerror(errno));
        return;
    }
    usleep(PWM_PERIOD_US - pulse_us);
}

static int read_pir(void) {
    int val = gpiod_line_get_value(pir_line);
    if (val < 0) {
        log_message("Failed to read PIR sensor: %s", strerror(errno));
        return -1;
    }
    return val;
}

static void handle_client(int client_fd) {
    char buffer[1024];
    ssize_t n = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (n <= 0) {
        close(client_fd);
        return;
    }
    buffer[n] = '\0';
    char *cmd = strtok(buffer, " \r\n");
    if (strcmp(cmd, "SERVO") == 0) {
        cmd = strtok(NULL, " \r\n");
        if (!cmd) {
            send(client_fd, "Usage: SERVO <angle>\n", 21, 0);
            return;
        }
        int angle = atoi(cmd);
        if (angle < 0 || angle > PWM_RANGE) {
            send(client_fd, "Invalid angle. Use 0-180.\n", 24, 0);
            return;
        }
        set_servo_angle(angle);
        char resp[64];
        snprintf(resp, sizeof(resp), "SERVO: %d\n", angle);
        send(client_fd, resp, strlen(resp), 0);
    } else if (strcmp(cmd, "PIR") == 0) {
        int pir = read_pir();
        if (pir < 0) {
            send(client_fd, "PIR: -1\n", 8, 0);
            return;
        }
        char resp[16];
        snprintf(resp, sizeof(resp), "PIR: %d\n", pir);
        send(client_fd, resp, strlen(resp), 0);
    } else {
        send(client_fd, "Usage: SERVO <angle> | PIR\n", 27, 0);
    }
}

static void *pwm_thread(void *arg) {
    (void)arg;
    while (running) {
        for (int i = 0; i < PWM_RANGE && running; i++) {
            set_servo_angle(i);
        }
    }
    return NULL;
}

int main(void) {
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() < 0) {
        if (log_fp) fclose(log_fp);
        return 1;
    }
    log_message("GPIO initialized. Listening on port %d.", PORT);

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_message("Socket creation failed: %s", strerror(errno));
        gpiod_line_release(servo_line);
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        if (log_fp) fclose(log_fp);
        return 1;
    }
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_message("setsockopt failed: %s", strerror(errno));
        close(server_fd);
        gpiod_line_release(servo_line);
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        if (log_fp) fclose(log_fp);
        return 1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);
    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        log_message("Bind failed: %s", strerror(errno));
        close(server_fd);
        gpiod_line_release(servo_line);
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        if (log_fp) fclose(log_fp);
        return 1;
    }
    if (listen(server_fd, 3) < 0) {
        log_message("Listen failed: %s", strerror(errno));
        close(server_fd);
        gpiod_line_release(servo_line);
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        if (log_fp) fclose(log_fp);
        return 1;
    }
    log_message("Listening for connections...");
    while (running) {
        struct sockaddr_in caddr;
        socklen_t clen = sizeof(caddr);
        int cfd = accept(server_fd, (struct sockaddr *)&caddr, &clen);
        if (cfd < 0) {
            if (errno == EINTR) continue;
            log_message("Accept failed: %s", strerror(errno));
            continue;
        }
        char ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &caddr.sin_addr, ip, sizeof(ip));
        log_message("Connection from %s:%d", ip, ntohs(caddr.sin_port));
        handle_client(cfd);
        close(cfd);
    }
    log_message("Shutting down...");
    if (server_fd >= 0) close(server_fd);
    if (log_fp) fclose(log_fp);
    if (servo_line) gpiod_line_release(servo_line);
    if (pir_line) gpiod_line_release(pir_line);
    if (chip) gpiod_chip_close(chip);
    closelog();
    return 0;
}

