        if (gpiod_line_set_value(sck, 0) < 0) {
            syslog(LOG_ERR, "SCK low failed: %s", strerror(errno));
            return -1;
        }
        usleep(1);
    }

    /* 25th clock pulse: select Channel A / Gain 128 */
    if (gpiod_line_set_value(sck, 1) < 0) {
        syslog(LOG_ERR, "SCK high (25th) failed: %s", strerror(errno));
        return -1;
    }
    usleep(1);
    if (gpiod_line_set_value(sck, 0) < 0) {
        syslog(LOG_ERR, "SCK low (25th) failed: %s", strerror(errno));
        return -1;
    }
    usleep(1);

    /* Convert 24-bit two's complement to signed 32-bit */
    if (data & 0x800000) {
        data |= ~0xFFFFFF;
    }

    *raw_out = data;
    return 0;
}

static double calculate_weight(int raw_reading, double tare_offset, double scale) {
    return ((double)raw_reading - tare_offset) / scale;
}

static int control_solenoid(struct gpiod_line *solenoid, int duration_ms) {
    if (gpiod_line_set_value(solenoid, 1) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid HIGH: %s", strerror(errno));
        return -1;
    }
    usleep(duration_ms * 1000);
    if (gpiod_line_set_value(solenoid, 0) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid LOW: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup_resources(struct gpiod_chip *chip, struct gpiod_line *dout,
                             struct gpiod_line *sck, struct gpiod_line *solenoid) {
    if (dout) gpiod_line_release(dout);
    if (sck)  gpiod_line_release(sck);
    if (solenoid) gpiod_line_set_value(solenoid, 0);
    if (chip) gpiod_chip_close(chip);
}

int main(int argc, char *argv[]) {
    double threshold = DEFAULT_THRESHOLD;
    double scale = DEFAULT_SCALE;
    int duration = DEFAULT_DURATION;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *dout = NULL, *sck = NULL, *solenoid = NULL;
    int ret = EXIT_FAILURE;

    openlog("load_cell_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (set_up_signals() != 0) {
        goto cleanup;
    }

    if (argc > 1) {
        if (strcmp(argv[1], "--threshold") == 0 && argc > 2) {
            threshold = atof(argv[2]);
        } else if (strcmp(argv[1], "--scale") == 0 && argc > 2) {
            scale = atof(argv[2]);
        } else if (strcmp(argv[1], "--duration") == 0 && argc > 2) {
            duration = atoi(argv[2]);
        } else {
            fprintf(stderr, "Usage: %s [--threshold <grams>] [--scale <factor>] [--duration <ms>]\n", argv[0]);
            goto cleanup;
        }
    }

    syslog(LOG_INFO, "Threshold: %.2f grams, Scale: %.2f, Duration: %d ms", threshold, scale, duration);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        goto cleanup;
    }

    dout = gpiod_chip_get_line(chip, HX711_DOUT_PIN);
    sck  = gpiod_chip_get_line(chip, HX711_SCK_PIN);
    solenoid = gpiod_chip_get_line(chip, SOLENOID_PIN);
    if (!dout || !sck || !solenoid) {
        syslog(LOG_ERR, "Failed to get GPIO lines: %s", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(dout, "hx711_dout") < 0) {
        syslog(LOG_ERR, "Failed to request DOUT as input: %s", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(sck, "hx711_sck", 0) < 0) {
        syslog(LOG_ERR, "Failed to request SCK as output: %s", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(solenoid, "solenoid", 0) < 0) {
        syslog(LOG_ERR, "Failed to request solenoid as output: %s", strerror(errno));
        goto cleanup;
    }

    double tare_offset = 0.0;
    int tare_count = 0;
    int read_count = 0;

    while (running) {
        int raw_reading;
        int success = 0;

        for (int i = 0; i < READ_SAMPLES && running; i++) {
            if (read_hx711(dout, sck, &raw_reading) == 0) {
                tare_offset += raw_reading;
                tare_count++;
                success = 1;
            } else {
                syslog(LOG_ERR, "HX711 read failed, retrying...");
                usleep(100000);
                continue;
            }
        }

        if (success) {
            if (tare_count >= TARE_SAMPLES) {
                tare_offset /= TARE_SAMPLES;
                syslog(LOG_INFO, "Tare offset: %.2f", tare_offset);
                tare_count = 0;
            }
            double weight = calculate_weight(raw_reading, tare_offset, scale);
            syslog(LOG_INFO, "Raw: %d, Weight: %.2f grams", raw_reading, weight);

            if (weight > threshold) {
                syslog(LOG_INFO, "Weight exceeds threshold, activating solenoid for %d ms", duration);
                if (control_solenoid(solenoid, duration) != 0) {
                    syslog(LOG_ERR, "Solenoid control failed");
                }
            }
        } else {
            syslog(LOG_ERR, "Failed to read HX711 after %d retries, exiting", MAX_RETRIES);
            goto cleanup;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    syslog(LOG_INFO, "Shutting down...");
    cleanup_resources(chip, dout, sck, solenoid);
    closelog();
    return ret;
}

