/*
 * relay_controller.c — MQTT relay controller for Raspberry Pi 4 Model B
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c -lmosquitto -lpigpio -lrt
 * Run:    sudo ./relay_controller
 *
 * Hardware: Relay module on GPIO17 (BCM 17, physical pin 11), active-high.
 * MQTT:   Connect to broker at localhost:1883, topic home/lights/control, QoS 0.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_HOST        "localhost"
#define MQTT_PORT        1883
#define MQTT_CLIENT_ID   "relay_controller_1"
#define MQTT_TOPIC       "home/lights/control"
#define MQTT_QOS         0
#define MQTT_KEEPALIVE   60
#define GPIO_RELAY       17
#define RETRY_DELAY_SEC  5

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int relay_set(int state)
{
    if (gpioWrite(GPIO_RELAY, state) < 0) {
        syslog(LOG_ERR, "gpioWrite(GPIO%d, %d) failed: %s",
               GPIO_RELAY, state, strerror(errno));
        return -1;
    }
    syslog(LOG_INFO, "Relay on GPIO%d set to %s", GPIO_RELAY,
           state ? "ON (energized)" : "OFF (de-energized)");
    return 0;
}

static void relay_off(void)
{
    (void)relay_set(0);
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                     */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *m, void *userdata, int result)
{
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_HOST, MQTT_PORT);
        if (mosquitto_subscribe(m, NULL, MQTT_TOPIC, MQTT_QOS) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "subscribe failed: %s", mosquitto_strerror(result));
        } else {
            syslog(LOG_INFO, "Subscribed to %s", MQTT_TOPIC);
        }
    } else {
        syslog(LOG_ERR, "connack: %s", mosquitto_strerror(result));
    }
}

static void on_disconnect(struct mosquitto *m, void *userdata, int rc)
{
    (void)m;
    (void)userdata;
    syslog(LOG_WARNING, "MQTT disconnected (rc=%d)", rc);
}

static void on_message(struct mosquitto *m, void *userdata,
                        const struct mosquitto_message *message)
{
    (void)m;
    (void)userdata;

    if (message->payloadlen <= 0) {
        syslog(LOG_ERR, "Empty payload received on topic %s",
               message->topic ? message->topic : "(null)");
        return;
    }

    char payload[32];
    size_t len = (size_t)message->payloadlen;
    if (len >= sizeof(payload))
        len = sizeof(payload) - 1;
    memcpy(payload, message->payload, len);
    payload[len] = '\0';

    syslog(LOG_INFO, "Received message on %s: %s", message->topic, payload);

    if (strcmp(payload, "ON") == 0) {
        relay_set(1);
    } else if (strcmp(payload, "OFF") == 0) {
        relay_set(0);
    } else {
        syslog(LOG_ERR, "Invalid command '%s' on topic %s", payload, message->topic);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    relay_off();

    if (g_mosq) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("relay_controller", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting relay controller (GPIO%d)", GPIO_RELAY);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(GPIO%d) failed", GPIO_RELAY);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    relay_off();

    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        syslog(LOG_ERR, "mosquitto_new failed: %s", strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_message_callback_set(g_mosq, on_message);

    int rc = mosquitto_connect(g_mosq, MQTT_HOST, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_HOST, MQTT_PORT);

    while (g_running) {
        rc = mosquitto_loop(g_mosq, RETRY_DELAY_SEC, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_loop error: %s", mosquitto_strerror(rc));
            syslog(LOG_WARNING, "Reconnecting in %d s...", RETRY_DELAY_SEC);
            sleep(RETRY_DELAY_SEC);
            continue;
        }
        if (!g_running)
            break;
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

