#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#define NUM_SERVOS 5
#define PWM_FREQ 50
#define PWM_RANGE 20000
#define HOLD_TIME 3

int servo_pins[NUM_SERVOS] = {7, 8, 9, 10, 11};
int servo_positions[NUM_SERVOS] = {1000, 1500, 2000, 500, 2500};

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_SERVOS; i++) {
        gpioSetMode(servo_pins[i], PI_OUTPUT);
        gpioSetPWMfrequency(servo_pins[i], PWM_FREQ);
        gpioSetPWMrange(servo_pins[i], PWM_RANGE);
    }

    for (int i = 0; i < NUM_SERVOS; i++) {
        if (gpioServo(servo_pins[i], servo_positions[i]) < 0) {
            fprintf(stderr, "Error: gpioServo failed for pin %d.\n", servo_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("Servo positions set. Holding for %d seconds...\n", HOLD_TIME);
    sleep(HOLD_TIME);

    for (int i = 0; i < NUM_SERVOS; i++) {
        gpioServo(servo_pins[i], 0);
    }

    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

