#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <stdatomic.h>

/* Motor A */
#define MOTOR_A_PWM_PIN 17
#define MOTOR_A_DIR_PIN 18

/* Motor B */
#define MOTOR_B_PWM_PIN 22
#define MOTOR_B_DIR_PIN 23

/* Encoder A */
#define ENCODER_A_A_PIN 4
#define ENCODER_A_B_PIN 5

/* Encoder B */
#define ENCODER_B_A_PIN 6
#define ENCODER_B_B_PIN 12

/* Encoder parameters */
#define TICKS_PER_REV 64.0
#define STALL_TIMEOUT_SEC 2.0

/* Control parameters */
#define TARGET_SPEED_RPM 50.0
#define PI_KP 0.5
#define PI_KI 0.05
#define PWM_FREQUENCY 10000
#define PWM_RANGE 255
#define CONTROL_PERIOD_US 100000

/* Global state */
static volatile sig_atomic_t running = 1;
static double motor_a_integral = 0.0;
static double motor_b_integral = 0.0;
static atomic_int encoder_a_ticks = 0;
static atomic_int encoder_b_ticks = 0;
static struct timespec encoder_a_last_tick = {0, 0};
static struct timespec encoder_b_last_tick = {0, 0};

/* Function prototypes */
static void signal_handler(int sig);
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
static void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
static void set_motor_speed(int motor, double speed_rpm);
static double calculate_pid(double setpoint, double actual, double *integral, double kp, double ki, double dt);
static void stop_motors(void);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Encoder A ISR: one count per rising edge */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)user;
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    double dt = (now.tv_sec - encoder_a_last_tick.tv_sec) +
                (now.tv_nsec - encoder_a_last_tick.tv_nsec) / 1e9;
    if (dt > 0.0) {
        atomic_fetch_add(&encoder_a_ticks, 1);
        encoder_a_last_tick = now;
    }
}

/* Encoder B ISR: one count per rising edge */
