#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define RELAY_GPIO 17
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define POLL_INTERVAL_SEC 5
#define BH1750_MEAS_DELAY_US 180000
#define LOG_FILE "chicken_coop_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int handle, float *lux_out) {
    char cmd = 0x21;
    char buf[2];

    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(BH1750_MEAS_DELAY_US);

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    unsigned int raw = ((unsigned int)buf[0] << 8) | (unsigned int)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

static void log_data(float lux, int relay_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
        fflush(log_file);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    control_relay(0);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    control_relay(0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int relay_state = 0;
    int last_lux = -1;

    while (running) {
        float lux = 0.0f;
        if (read_bh1750(i2c_handle, &lux) != 0) {
            fprintf(stderr, "Sensor read failed, turning off relay for safety.\n");
            control_relay(0);
            relay_state = 0;
            log_data(0.0f, relay_state);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (lux < LUX_THRESHOLD_DUSK && relay_state == 0) {
            control_relay(1);
            relay_state = 1;
            log_data(lux, relay_state);
            printf("Dusk detected. Lux: %.2f, Relay ON\n", lux);
        } else if (lux > LUX_THRESHOLD_DAWN && relay_state == 1) {
            control_relay(0);
            relay_state = 0;
            log_data(lux, relay_state);
            printf("Dawn detected. Lux: %.2f, Relay OFF\n", lux);
        }

        log_data(lux, relay_state);
        sleep(POLL_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

