        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int relay_state = 0;
    int last_lux = -1;

    while (running) {
        float lux = 0.0f;
        if (read_bh1750(i2c_handle, &lux) != 0) {
            fprintf(stderr, "Sensor read failed, turning off relay for safety.\n");
            control_relay(0);
            relay_state = 0;
            log_data(0.0f, relay_state);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (lux < LUX_THRESHOLD_DUSK && relay_state == 0) {
            control_relay(1);
            relay_state = 1;
            log_data(lux, relay_state);
            printf("Dusk detected. Lux: %.2f, Relay ON\n", lux);
        } else if (lux > LUX_THRESHOLD_DAWN && relay_state == 1) {
            control_relay(0);
            relay_state = 0;
            log_data(lux, relay_state);
            printf("Dawn detected. Lux: %.2f, Relay OFF\n", lux);
        }

        log_data(lux, relay_state);
        sleep(POLL_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

