#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_US 50000   /* 50 ms */
#define MAIN_LOOP_SLEEP_US 10000  /* 10 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("[%s] Relay is now %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

int main(void) {
    int relay_state = 0;
    int last_touch = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay to OFF\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Touch-to-relay controller started. Touch GPIO %d, Relay GPIO %d.\n",
           TOUCH_SENSOR_GPIO, RELAY_GPIO);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int touch = gpioRead(TOUCH_SENSOR_GPIO);
        if (touch < 0) {
            fprintf(stderr, "Error: failed to read touch sensor on GPIO %d\n",
                    TOUCH_SENSOR_GPIO);
            break;
        }

        if (touch == 1 && last_touch == 0) {
            /* Rising edge: debounce */
            gpioDelay(DEBOUNCE_DELAY_US);
            int touch_debounced = gpioRead(TOUCH_SENSOR_GPIO);
            if (touch_debounced < 0) {
                fprintf(stderr, "Error: failed to read touch sensor during debounce\n");
                break;
            }
            if (touch_debounced == 1) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_GPIO, relay_state) != 0) {
                    fprintf(stderr, "Error: failed to write relay GPIO %d\n", RELAY_GPIO);
                    break;
                }
                log_relay_state(relay_state);
                last_touch = 1;
            }
        } else if (touch == 0 && last_touch == 1) {
            /* Falling edge: wait for release to avoid repeated toggles */
            gpioDelay(DEBOUNCE_DELAY_US);
            int touch_released = gpioRead(TOUCH_SENSOR_GPIO);
            if (touch_released < 0) {
                fprintf(stderr, "Error: failed to read touch sensor during release debounce\n");
                break;
            }
            if (touch_released == 0) {
                last_touch = 0;
            }
        }

        gpioDelay(MAIN_LOOP_SLEEP_US);
    }

    /* Graceful shutdown: ensure relay is OFF */
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    printf("\nExiting gracefully. Relay OFF.\n");
    return EXIT_SUCCESS;
}

