#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD 5.0
#define LPM_HYSTERESIS 4.5
#define SAMPLE_INTERVAL_SEC 1
#define DEBOUNCE_US 1000000
#define LOG_FILE "water_flow.log"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t pulse_mutex;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(log_file);
}

static void flow_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    pthread_mutex_lock(&pulse_mutex);
    static int pulse_count = 0;
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

static double calculate_lpm(int pulses) {
    return ((double)pulses / PULSES_PER_LITER) * 60.0;
}

static int control_solenoid(double lpm) {
    static int solenoid_state = 1;
    int new_state;

    if (lpm > LPM_THRESHOLD) {
        new_state = 0;
    } else if (lpm < LPM_HYSTERESIS) {
        new_state = 1;
    } else {
        return 0;
    }

    if (new_state != solenoid_state) {
        if (gpioWrite(SOLENOID_GPIO, new_state) != 0) {
            log_event("ERROR: Failed to write solenoid GPIO");
            return -1;
        }
        solenoid_state = new_state;
        char msg[128];
        snprintf(msg, sizeof(msg), "Solenoid state changed to %s",
                 solenoid_state ? "OPEN" : "CLOSED");
        log_event(msg);
    }
    return 0;
}

static void cleanup(void) {
    if (log_file) {
        log_event("Shutting down...");
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(SOLENOID_GPIO, 0);
    gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL);
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flow sensor GPIO mode\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(SOLENOID_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set solenoid GPIO mode\n");
        cleanup();
        return 1;
    }
    if (gpioWrite(SOLENOID_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to set solenoid initial state\n");
        cleanup();
        return 1;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, flow_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers\n");
        cleanup();
        return 1;
    }

    log_event("System started");

    while (running) {
        sleep(SAMPLE_INTERVAL_SEC);
        if (!running) break;

        pthread_mutex_lock(&pulse_mutex);
        int pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double lpm = calculate_lpm(pulses);
        char msg[128];
        snprintf(msg, sizeof(msg), "Flow rate: %.2f LPM, pulses: %d", lpm, pulses);
        log_event(msg);

        control_solenoid(lpm);
    }

    cleanup();
    return 0;
}

