#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define HX711_DATA_PIN 23
#define HX711_SCK_PIN  24
#define SERVO_PIN      18

#define CONFIG_FILE    "config.ini"
#define LOG_FILE       "dispensing_log.json"

#define DEFAULT_CALIBRATION_FACTOR 1000.0
#define DEFAULT_SERVER_IP          "127.0.0.1"
#define DEFAULT_SERVER_PORT        12345
#define DEFAULT_SERVO_MIN_PULSE_US 1000
#define DEFAULT_SERVO_MAX_PULSE_US 2000
#define DEFAULT_SERVO_OPEN_ANGLE_US 1500
#define DEFAULT_SERVO_CLOSE_ANGLE_US 1000
#define DEFAULT_STABILIZE_DELAY_S 1
#define DEFAULT_TIMEOUT_ATTEMPTS 1000

#define HX711_TIMEOUT_US 1000000
#define SERVO_SETTLE_US  500000

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static char server_ip[64] = DEFAULT_SERVER_IP;
static int server_port = DEFAULT_SERVER_PORT;
static int servo_min_pulse_us = DEFAULT_SERVO_MIN_PULSE_US;
static int servo_max_pulse_us = DEFAULT_SERVO_MAX_PULSE_US;
static int servo_open_angle_us = DEFAULT_SERVO_OPEN_ANGLE_US;
static int servo_close_angle_us = DEFAULT_SERVO_CLOSE_ANGLE_US;
static int stabilize_delay_s = DEFAULT_STABILIZE_DELAY_S;
static int timeout_attempts = DEFAULT_TIMEOUT_ATTEMPTS;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: could not open config file '%s': %s. Using defaults.\n",
                filename, strerror(errno));
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        line[strcspn(line, "\n")] = 0;
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");
        if (!key || !value) continue;

        if (strcmp(key, "calibration_factor") == 0) {
            calibration_factor = atof(value);
        } else if (strcmp(key, "server_ip") == 0) {
            strncpy(server_ip, value, sizeof(server_ip) - 1);
            server_ip[sizeof(server_ip) - 1] = 0;
        } else if (strcmp(key, "server_port") == 0) {
            server_port = atoi(value);
        } else if (strcmp(key, "servo_min_pulse_us") == 0) {
            servo_min_pulse_us = atoi(value);
        } else if (strcmp(key, "servo_max_pulse_us") == 0) {
            servo_max_pulse_us = atoi(value);
        } else if (strcmp(key, "servo_open_angle_us") == 0) {
            servo_open_angle_us = atoi(value);
        } else if (strcmp(key, "servo_close_angle_us") == 0) {
            servo_close_angle_us = atoi(value);
        } else if (strcmp(key, "stabilize_delay_s") == 0) {
            stabilize_delay_s = atoi(value);
        } else if (strcmp(key, "timeout_attempts") == 0) {
            timeout_attempts = atoi(value);
        }
    }
    fclose(fp);

    if (calibration_factor <= 0.0) {
        fprintf(stderr, "Error: calibration_factor must be positive. Using default.\n");
        calibration_factor = DEFAULT_CALIBRATION_FACTOR;
    }
    if (server_port <= 0 || server_port > 65535) {
        fprintf(stderr, "Error: server_port must be 1-65535. Using default.\n");
        server_port = DEFAULT_SERVER_PORT;
    }
    if (servo_min_pulse_us < 500 || servo_max_pulse_us > 2500 ||
        servo_open_angle_us < servo_min_pulse_us || servo_close_angle_us > servo_max_pulse_us) {
        fprintf(stderr, "Error: servo pulse widths out of range. Using defaults.\n");
        servo_min_pulse_us = DEFAULT_SERVO_MIN_PULSE_US;
        servo_max_pulse_us = DEFAULT_SERVO_MAX_PULSE_US;
        servo_open_angle_us = DEFAULT_SERVO_OPEN_ANGLE_US;
        servo_close_angle_us = DEFAULT_SERVO_CLOSE_ANGLE_US;
    }
    if (stabilize_delay_s < 0) {
        fprintf(stderr, "Error: stabilize_delay_s must be non-negative. Using default.\n");
        stabilize_delay_s = DEFAULT_STABILIZE_DELAY_S;
    }
    if (timeout_attempts < 1) {
        fprintf(stderr, "Error: timeout_attempts must be positive. Using default.\n");
        timeout_attempts = DEFAULT_TIMEOUT_ATTEMPTS;
    }

    printf("Config loaded: calibration=%.2f, ip=%s, port=%d, "
           "min_pulse=%d, max_pulse=%d, open=%d, close=%d, "
           "stabilize=%ds, timeout=%d\n",
           calibration_factor, server_ip, server_port,
           servo_min_pulse_us, servo_max_pulse_us,
           servo_open_angle_us, servo_close_angle_us,
           stabilize_delay_s, timeout_attempts);
    return 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

