static void cleanup_gpio(void) {
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

static int read_hx711(int32_t *raw_value) {
    if (raw_value == NULL) return -1;

    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout >= timeout_attempts) {
            fprintf(stderr, "Error: HX711 not ready (DATA stuck HIGH). Sensor absent or not responding.\n");
            return -1;
        }
    }

