        return -1;
    }
    return 0;
}

static int log_dispensing(double target_weight, double actual_weight, const char *error_msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: could not open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (error_msg) {
        fprintf(fp, "{\"timestamp\": \"%s\", \"target_weight\": %.2f, \"actual_weight\": null, \"error\": \"%s\"}\n",
                timestamp, target_weight, error_msg);
    } else {
        fprintf(fp, "{\"timestamp\": \"%s\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error\": null}\n",
                timestamp, target_weight, actual_weight);
    }

    fclose(fp);
    return 0;
}

static void send_all(int sock, const char *buf, size_t len) {
    size_t sent = 0;
