        close(sock);
        return;
    }
    buffer[n] = '\0';

    double target_weight;
    if (sscanf(buffer, "%lf", &target_weight) != 1) {
        fprintf(stderr, "Error: invalid target weight format.\n");
        send_all(sock, "{\"error\": \"invalid_weight_format\"}\n", 32);
        close(sock);
        return;
    }

    printf("Received target weight: %.2f g\n", target_weight);

    if (control_servo(servo_open_angle_us) != 0) {
        fprintf(stderr, "Error: failed to open servo.\n");
