    printf("Actual weight: %.2f g\n", actual_weight);

    if (log_dispensing(target_weight, actual_weight, NULL) != 0) {
        fprintf(stderr, "Warning: log_dispensing failed.\n");
    }

    char response[128];
    snprintf(response, sizeof(response),
             "{\"target_weight\": %.2f, \"actual_weight\": %.2f, \"error\": null}\n",
             target_weight, actual_weight);
    send_all(sock, response, strlen(response));

    if (control_servo(servo_close_angle_us) != 0) {
        fprintf(stderr, "Error: failed to close servo.\n");
    }

    close(sock);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed: %s\n", strerror(errno));
