#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO 17
#define DEFAULT_DEBOUNCE_MS 50

static volatile sig_atomic_t running = 1;
static int debounce_ms = DEFAULT_DEBOUNCE_MS;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("%s Relay: %s\n", ts, state ? "ON" : "OFF");
    fflush(stdout);
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay to OFF\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce_ms = atoi(optarg);
                if (debounce_ms <= 0) {
                    fprintf(stderr, "Error: debounce must be > 0\n");
                    return EXIT_FAILURE;
                }
