#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <termios.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define ANGLE_STEP 10
#define DEFAULT_ANGLE 90
#define PWM_FREQ 50
#define PWM_RANGE 2000000
#define PULSE_PERIOD_US (1000000 / PWM_FREQ)

static volatile sig_atomic_t running = 1;
static struct termios orig_termios;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int save_terminal(void) {
    struct termios *t = termios_get_state(STDIN_FILENO);
    if (!t) {
        perror("termios_get_state");
        return -1;
    }
    if (tcsetattr(STDIN_FILENO, TCSANOW, orig_termios) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static int restore_terminal(void) {
    struct termios *t = termios_get_state(STDIN_FILENO);
    if (!t) {
        perror("termios_get_state");
        return -1;
    }
    if (tcsetattr(STDIN_FILENO, TCSANOW, orig_termios) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static int angle_to_pulse_width(int angle) {
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    return MIN_PULSE_WIDTH + (int)((long)angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / MAX_ANGLE);
}

static int pulse_width_to_angle(int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH) pulse_width = MIN_PULSE_WIDTH;
    if (pulse_width > MAX_PULSE_WIDTH) pulse_width = MAX_PULSE_WIDTH;
    return (int)((long)(pulse_width - MIN_PULSE_WIDTH) * MAX_ANGLE / (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));
}

static int set_servo_angle(int angle) {
    int pulse_width = angle_to_pulse_width(angle);
    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "gpioServo failed for pulse width %d\n", pulse_width);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (tcgetattr(STDIN_FILENO, &orig_termios) != 0) {
        perror("tcgetattr");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (save_terminal() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int angle = DEFAULT_ANGLE;
    printf("Servo control on GPIO%d (Ctrl-C to quit)\n", SERVO_PIN);

    while (running) {
        int c = getchar();
        if (c == EOF) {
            if (!running) break;
            continue;
        }

        if (c == '+' || c == '=') {
            angle += ANGLE_STEP;
            if (angle > MAX_ANGLE) angle = MAX_ANGLE;
        } else if (c == '-' || c == '_') {
            angle -= ANGLE_STEP;
            if (angle < MIN_ANGLE) angle = MIN_ANGLE;
        } else if (c == 'q' || c == 'Q') {
            running = 0;
            break;
        }

        if (set_servo_angle(angle) == 0) {
            printf("Angle: %3d°  Pulse: %4d us\n", angle, angle_to_pulse_width(angle));
        }

        fflush(stdout);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    restore_terminal();
    return EXIT_SUCCESS;
}

