#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE "motor_rpm.log"
#define SAMPLE_INTERVAL_SEC 5
#define DEBOUNCE_NS 2000000L  /* 2 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int log_rpm(FILE *log_file, double rpm)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&ts.tv_sec, &tm_info) == NULL) {
        perror("localtime_r");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    int ms = (int)(ts.tv_nsec / 1000000L);

    if (fprintf(log_file, "%s.%03d,%.2f\n", timestamp, ms, rpm) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(log_file) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request rising-edge events with internal pull-up bias.
     * The A3144 has an open-collector output, so a pull-up is required. */
    if (gpiod_line_request_rising_edge_events_flags(line, "conveyor-rpm",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_rising_edge_events_flags");
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        goto cleanup;
    }

    printf("Monitoring conveyor belt RPM on GPIO %d. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    unsigned long pulse_count = 0;
    struct timespec last_event_ts = {0, 0};

    while (program_running) {
        struct timespec ts_timeout = {SAMPLE_INTERVAL_SEC, 0};
        int rv = gpiod_line_event_wait(line, &ts_timeout);

        if (rv < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("gpiod_line_event_wait");
            break;
        }

        if (rv == 0) {
            /* Timeout — loop back and check program_running. */
            continue;
        }

        /* Event detected — read and consume it. */
        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("gpiod_line_event_read");
            break;
        }

        /* Debounce: ignore events within DEBOUNCE_NS of the last accepted one. */
        struct timespec now = event.ts;
        long delta_ns = (now.tv_sec - last_event_ts.tv_sec) * 1000000000L +
                        (now.tv_nsec - last_event_ts.tv_nsec);

        if (delta_ns < DEBOUNCE_NS) {
            continue;
        }
        last_event_ts = now;

        pulse_count++;

        double rpm = (double)pulse_count / (SAMPLE_INTERVAL_SEC * 60.0);
        printf("RPM: %.2f\n", rpm);

        if (log_rpm(log_file, rpm) != 0) {
            fprintf(stderr, "Failed to log RPM data.\n");
            break;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Program finished.\n");
    return ret;
}

