#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO        17
#define POLL_DELAY_US     50000   /* 50 ms */
#define FAILSAFE_TIMEOUT  10      /* seconds */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", RELAY_GPIO);
        gpioTerminate();
        return -1;
    }

    /* Start with relay OFF */
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay state on GPIO%d.\n", RELAY_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Best-effort: turn relay off and release pigpio resources */
    (void)gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

