#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLOW_SENSOR_PIN 24
#define VALVE_ENABLE_PIN 23
#define PWM_PIN 18

#define PWM_RANGE 255
#define PWM_FREQ 1000
#define SAMPLE_INTERVAL_US 100000
#define PULSES_PER_LITER 450.0
#define KP 1.0

static volatile int pulse_count = 0;
static volatile int running = 1;
static FILE *log_file = NULL;

static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user);
static double calculate_flow_rate(int pulses);
static int set_valve_position(int position);
static int set_pwm_duty_cycle(int duty_cycle);
static int validate_target_flow_rate(double target_flow_rate);
static void signal_handler(int signal);
static void cleanup(void);

int main(int argc, char *argv[]) {
    double target_flow_rate = 0.0;
    int valve_position = 0;
    int duty_cycle = 0;

    if (argc > 1) {
        target_flow_rate = atof(argv[1]);
        if (validate_target_flow_rate(target_flow_rate) != 0) {
            fprintf(stderr, "Error: Invalid target flow rate. Please enter a positive number.\n");
            return 1;
        }
    } else {
        fprintf(stderr, "Error: Target flow rate not provided. Please use -t <target_flow_rate_L/min>\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set FLOW_SENSOR_PIN mode\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set VALVE_ENABLE_PIN mode\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set PWM_PIN mode\n");
        cleanup();
        return 1;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: Failed to set PWM range\n");
        cleanup();
        return 1;
    }
    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency\n");
        cleanup();
        return 1;
    }

    if (gpioWrite(VALVE_ENABLE_PIN, 1) != 0) {
        fprintf(stderr, "Error: Failed to enable valve\n");
        cleanup();
        return 1;
    }
    if (set_valve_position(0) != 0) {
        fprintf(stderr, "Error: Failed to set initial valve position\n");
        cleanup();
        return 1;
    }
    if (set_pwm_duty_cycle(0) != 0) {
        fprintf(stderr, "Error: Failed to set initial PWM duty cycle\n");
        cleanup();
        return 1;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set ISR for flow sensor\n");
        cleanup();
        return 1;
    }

    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handlers\n");
        cleanup();
        return 1;
    }

    printf("Flow control system started. Target flow rate: %.2f L/min\n", target_flow_rate);

    while (running) {
        pulse_count = 0;
        gpioDelay(SAMPLE_INTERVAL_US);

        double current_flow_rate = calculate_flow_rate(pulse_count);
        int error = 0;
        if (current_flow_rate < 0.0) {
            fprintf(stderr, "Error: Invalid flow rate calculation\n");
            error = 1;
        }

        if (!error) {
            int desired_position = (int)(KP * (target_flow_rate - current_flow_rate));
            if (desired_position < 0) {
                desired_position = 0;
            } else if (desired_position > 255) {
                desired_position = 255;
            }
            if (set_valve_position(desired_position) != 0) {
                fprintf(stderr, "Error: Failed to set valve position\n");
                error = 1;
            }
            if (!error) {
                duty_cycle = set_pwm_duty_cycle(desired_position);
                if (duty_cycle < 0) {
                    fprintf(stderr, "Error: Failed to set PWM duty cycle\n");
                    error = 1;
                }
            }
        }

        if (!error) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);
            fprintf(log_file, "%ld,%.2f,%d\n", timestamp_ms, current_flow_rate, duty_cycle);
            fflush(log_file);
        }

        gpioDelay(10000);
    }

    cleanup();
    return 0;
}

static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    pulse_count++;
}

static double calculate_flow_rate(int pulses) {
    return (double)pulses / PULSES_PER_LITER;
}

static int set_valve_position(int position) {
    if (gpioWrite(VALVE_ENABLE_PIN, 1) != 0) {
        fprintf(stderr, "Error: Failed to enable valve\n");
        return -1;
    }
    if (set_pwm_duty_cycle(position) != 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle\n");
        return -1;
    }
    return 0;
}

static int set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    if (gpioPWM(PWM_PIN, duty_cycle) != 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle\n");
        return -1;
    }
    return 0;
}

static int validate_target_flow_rate(double target_flow_rate) {
    if (target_flow_rate <= 0.0) {
        return -1;
    }
    return 0;
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static void cleanup(void) {
    set_pwm_duty_cycle(0);
    gpioWrite(VALVE_ENABLE_PIN, 0);
    gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, NULL, NULL);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

