#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK_PIN_1 17
#define LOCK_PIN_2 27
#define BUTTON_PIN 22
#define SPI_CHANNEL 0
#define SPI_SPEED 100000
#define RFID_DATA_LENGTH 10
#define DEBOUNCE_DELAY_US 50000
#define DISENGAGE_DELAY_US 5000000
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static const unsigned char valid_rfid_tag[RFID_DATA_LENGTH] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event_type, const char *additional_info) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) return;
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(log_file, "%s - %s - %s\n", timestamp, event_type, additional_info);
    fflush(log_file);
}

static int read_rfid_tag(unsigned char *rfid_data) {
    if (spi_handle < 0) return -1;
    char tx_buf[RFID_DATA_LENGTH + 1];
    char rx_buf[RFID_DATA_LENGTH + 1];
    memset(tx_buf, 0, sizeof(tx_buf));
    memset(rx_buf, 0, sizeof(rx_buf));
    tx_buf[0] = 0x01;
    int result = spiXfer(spi_handle, tx_buf, rx_buf, RFID_DATA_LENGTH + 1);
    if (result < 0) {
        log_event("RFID Read Failure", "SPI transfer error");
        return -1;
    }
    if (result != RFID_DATA_LENGTH) {
        log_event("RFID Read Failure", "Incomplete read");
        return -1;
    }
    memcpy(rfid_data, rx_buf, RFID_DATA_LENGTH);
    return 0;
}

static int check_rfid_tag(const unsigned char *rfid_data) {
    for (int i = 0; i < RFID_DATA_LENGTH; i++) {
        if (rfid_data[i] != valid_rfid_tag[i]) return 0;
    }
    return 1;
}

static int read_button_state(void) {
    int val = gpioRead(BUTTON_PIN);
    gpioDelay(DEBOUNCE_DELAY_US);
    return (val == 0);
}

static void disengage_locks(void) {
    gpioWrite(LOCK_PIN_1, 0);
    gpioWrite(LOCK_PIN_2, 0);
    log_event("Locks Disengaged", "Access granted");
    gpioDelay(DISENGAGE_DELAY_US);
    if (running) {
        gpioWrite(LOCK_PIN_1, 1);
        gpioWrite(LOCK_PIN_2, 1);
        log_event("Locks Re-Engaged", "Access granted");
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LOCK_PIN_1, 1);
    gpioWrite(LOCK_PIN_2, 1);
    if (log_file) {
        log_event("System Shutdown", "Clean exit");
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    log_file = fopen("/var/log/door_access.log", "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }
    log_event("System Started", "Initialization complete");
    gpioSetMode(LOCK_PIN_1, PI_OUTPUT);
    gpioSetMode(LOCK_PIN_2, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        log_event("SPI Initialization Failure", "SPI open error");
        cleanup();
        return 1;
    }
