#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <errno.h>
#include <gpiod.h>

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19

#define PWM_FREQUENCY 100
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY)
#define SAMPLE_TIME_MS 100
#define PULSES_PER_REV 600.0

#define KP 1.0
#define KI 0.1
#define KD 0.01

#define TARGET_RPM 60.0

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor_lines[6];
static struct gpiod_line *encoder_lines[2];
static pthread_mutex_t encoder_mutex[2];
static volatile int encoder_counts[2] = {0, 0};
static volatile int pwm_duty_cycle[2] = {0, 0};
static volatile double pid_p[2] = {0.0, 0.0};
static volatile double pid_i[2] = {0.0, 0.0};
static volatile double pid_d[2] = {0.0, 0.0};
static volatile double pid_output[2] = {0.0, 0.0};
static volatile double integral[2] = {0.0, 0.0};
static volatile double prev_error[2] = {0.0, 0.0};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void motor_stop(int idx) {
    if (motor_lines[idx * 2] && motor_lines[idx * 2 + 1]) {
        gpiod_line_set_value(motor_lines[idx * 2], 0);
        gpiod_line_set_value(motor_lines[idx * 2 + 1], 0);
    }
}

static void motor_forward(int idx) {
    gpiod_line_set_value(motor_lines[idx * 2], 1);
    gpiod_line_set_value(motor_lines[idx * 2 + 1], 0);
}

static void motor_backward(int idx) {
    gpiod_line_set_value(motor_lines[idx * 2], 0);
    gpiod_line_set_value(motor_lines[idx * 2 + 1], 1);
}

static void software_pwm(int idx, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;
    int on_time = (PWM_PERIOD_US * duty_cycle) / 100;
    int off_time = PWM_PERIOD_US - on_time;
    gpiod_line_set_value(motor_lines[idx * 2], 1);
    gpiod_line_set_value(motor_lines[idx * 2 + 1], 0);
    usleep(on_time);
    gpiod_line_set_value(motor_lines[idx * 2], 0);
    gpiod_line_set_value(motor_lines[idx * 2 + 1], 1);
    usleep(off_time);
}

static void encoder_callback(int idx, int gpio, int event_type, void *user_data) {
    (void)gpio;
    (void)event_type;
    (void)user_data;
    pthread_mutex_lock(&encoder_mutex[idx]);
    if (event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
        encoder_counts[idx]++;
    } else if (event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
        encoder_counts[idx]--;
    }
    double rpm = ((double)(encoder_counts[idx] - encoder_counts[idx - 1]) / PULSES_PER_REV) * 60.0;
    pid_output[idx] = KP * (TARGET_RPM - rpm) + KI * integral[idx] + KD * (rpm - prev_error[idx]);
    int duty = (int)(pid_output[idx] + 0.5);
    if (duty < 0) duty = 0;
    if (duty > 100) duty = 100;
    pwm_duty_cycle[idx] = duty;
    prev_error[idx] = rpm;
    pthread_mutex_unlock(&encoder_mutex[idx]);
}

static void *encoder_thread(void *arg) {
    int idx = *(int *)arg;
    encoder_lines[idx] = gpiod_chip_get_line(chip, gpio_lines[idx * 2]);
    if (!encoder_lines[idx]) {
        fprintf(stderr, "Failed to get encoder line %d: %s\n", gpio_lines[idx * 2], strerror(errno));
        return NULL;
    }
    if (gpiod_line_request_both_edges_events(encoder_lines[idx], "encoder_event") < 0) {
        fprintf(stderr, "Failed to request events on encoder line %d: %s\n", gpio_lines[idx * 2], strerror(errno));
        return NULL;
    }
    if (pthread_mutex_init(&encoder_mutex[idx], NULL) != 0) {
        fprintf(stderr, "Failed to init mutex for encoder %d\n", idx + 1);
        return NULL;
    }
    while (running) {
        struct timespec ts = {0, 10000000};
        int ret = gpiod_line_event_wait(encoder_lines[idx], &ts);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error waiting for encoder event: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) continue;
        encoder_callback(idx, gpio_lines[idx * 2], gpiod_line_event_get_event_type(encoder_lines[idx]), NULL);
    }
    gpiod_line_release(encoder_lines[idx]);
    pthread_mutex_destroy(&encoder_mutex[idx]);
    return NULL;
}

static int setup_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }
    gpio_lines[0] = MOTOR1_ENA; gpio_lines[1] = MOTOR1_IN1; gpio_lines[2] = MOTOR1_IN2;
    gpio_lines[3] = MOTOR2_ENB; gpio_lines[4] = MOTOR2_IN3; gpio_lines[5] = MOTOR2_IN4;
    gpio_lines[6] = ENCODER1_A; gpio_lines[7] = ENCODER1_B;
    gpio_lines[8] = ENCODER2_A; gpio_lines[9] = ENCODER2_B;
    for (int i = 0; i < 6; i++) {
        motor_lines[i] = gpiod_chip_get_line(chip, gpio_lines[i]);
        if (!motor_lines[i]) {
            fprintf(stderr, "Failed to get motor line %d: %s\n", gpio_lines[i], strerror(errno));
            return -1;
        }
        if (gpiod_line_request_output(motor_lines[i], "motor_control", 0) < 0) {
            fprintf(stderr, "Failed to request motor line %d as output: %s\n", gpio_lines[i], strerror(errno));
            return -1;
        }
    }
    for (int i = 0; i < 2; i++) {
        encoder_lines[i] = gpiod_chip_get_line(chip, gpio_lines[i + 6]);
        if (!encoder_lines[i]) {
            fprintf(stderr, "Failed to get encoder line %d: %s\n", gpio_lines[i + 6], strerror(errno));
            return -1;
        }
        if (gpiod_line_request_both_edges_events(encoder_lines[i], "encoder_event") < 0) {
            fprintf(stderr, "Failed to request events on encoder line %d: %s\n", gpio_lines[i + 6], strerror(errno));
            return -1;
        }
    }
    return 0;
}

static void cleanup(void) {
    motor_stop(0);
    motor_stop(1);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    for (int i = 0; i < 6; i++) {
        if (motor_lines[i]) gpiod_line_release(motor_lines[i]);
    }
    if (chip) gpiod_chip_close(chip);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen("motor_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }
    fprintf(log_file, "Timestamp,Motor1_RPM,Motor2_RPM,PID_P1,PID_I1,PID_D1,PID_O1,PID_P2,PID_I2,PID_D2,PID_O2\n");

    if (setup_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    pthread_t encoder_threads[2];
    int thread_args[2] = {0, 1};
    for (int i = 0; i < 2; i++) {
        if (pthread_create(&encoder_threads[i], NULL, encoder_thread, &thread_args[i]) != 0) {
            fprintf(stderr, "Failed to create encoder thread %d: %s\n", i + 1, strerror(errno));
            cleanup();
            return 1;
        }
    }

    while (running) {
        struct timespec sleep_ts = {0, SAMPLE_TIME_MS * 1000000L};
        nanosleep(&sleep_ts, NULL);
        if (!running) break;
        for (int i = 0; i < 2; i++) {
            int duty = pwm_duty_cycle[i];
            if (duty > 0) {
                motor_forward(i);
            } else if (duty < 0) {
                motor_backward(i);
            } else {
                motor_stop(i);
            }
            double rpm = ((double)(encoder_counts[i] - encoder_counts[i - 1]) / PULSES_PER_REV) * 60.0;
            pid_output[i] = KP * (TARGET_RPM - rpm) + KI * integral[i] + KD * (rpm - prev_error[i]);
            int duty_out = (int)(pid_output[i] + 0.5);
            if (duty_out < 0) duty_out = 0;
            if (duty_out > 100) duty_out = 100;
            if (duty_out != pwm_duty_cycle[i]) {
                pwm_duty_cycle[i] = duty_out;
            }
        }
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
        fprintf(log_file, "%s,%.2f,%.2f,%.4f,%.4f,%.4f,%.4f,%.2f,%.4f,%.4f,%.4f\n",
                timestamp,
                ((double)(encoder_counts[0] - encoder_counts[0 - 1]) / PULSES_PER_REV) * 60.0,
                ((double)(encoder_counts[1] - encoder_counts[1 - 1]) / PULSES_PER_REV) * 60.0,
                pid_p[0], pid_i[0], pid_d[0], pid_output[0],
                pid_p[1], pid_i[1], pid_d[1], pid_output[1]);
        fflush(log_file);
    }

    running = 0;
    for (int i = 0; i < 2; i++) {
        if (encoder_threads[i]) pthread_join(encoder_threads[i], NULL);
    }
    cleanup();
    return 0;
}

