#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1
#define LOG_FILE "relay_log.txt"

/* MPR121 Register Addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHD_R 0x2B
#define MPR121_NHD_R 0x2C
#define MPR121_NCL_R 0x2D
#define MPR121_FDL_R 0x2E
#define MPR121_MHD_F 0x2F
#define MPR121_NHD_F 0x30
#define MPR121_NCL_F 0x31
#define MPR121_FDL_F 0x32
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int mpr121_init(int handle) {
    /* Soft reset */
    if (mpr121_write_reg(handle, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000); /* 10 ms */

    /* Filtering */
    if (mpr121_write_reg(handle, MPR121_MHD_R, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHD_R, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCL_R, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDL_R, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_MHD_F, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHD_F, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCL_F, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDL_F, 0x00) < 0) return -1;

    /* Touch and release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(handle, MPR121_E0TTH + 2 * i, 0x0C) < 0) return -1;
        if (mpr121_write_reg(handle, MPR121_E0RTH + 2 * i, 0x0A) < 0) return -1;
    }

    /* Debounce: 3 samples for touch, 3 for release */
    if (mpr121_write_reg(handle, MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* Config1: 16 µA charge current, 0.5 µs charge time */
    if (mpr121_write_reg(handle, MPR121_CONFIG1, 0x10) < 0) return -1;

    /* Config2: 128 µA filter charge current */
    if (mpr121_write_reg(handle, MPR121_CONFIG2, 0x20) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking */
    if (mpr121_write_reg(handle, MPR121_ECR, 0x8F) < 0) return -1;

    gpioDelay(10000); /* 10 ms settle */
    return 0;
}

static int read_touch_status(int handle) {
    int lo = i2cReadByteData(handle, MPR121_TOUCHSTATUS_L);
    if (lo < 0) {
        fprintf(stderr, "Error reading touch status low byte: %d\n", lo);
        return -1;
    }
    int hi = i2cReadByteData(handle, MPR121_TOUCHSTATUS_H);
    if (hi < 0) {
        fprintf(stderr, "Error reading touch status high byte: %d\n", hi);
        return -1;
    }
    return (hi << 8) | lo;
}

static void log_relay_state(int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Relay %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                state ? "ON" : "OFF");
    }
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int prev_state = -1;

    while (running) {
        int touch = read_touch_status(i2c_handle);
        if (touch < 0) {
            fprintf(stderr, "Touch read error, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        int touched = (touch & 0x0FFF) != 0;
        if (touched != relay_state) {
            gpioWrite(RELAY_GPIO, touched ? 1 : 0);
            relay_state = touched ? 1 : 0;
            log_relay_state(relay_state);
            printf("Relay %s\n", relay_state ? "ON" : "OFF");
        }

        gpioDelay(50000); /* 50 ms */
    }

    /* Graceful shutdown */
    gpioWrite(RELAY_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

