#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define VALVE_1_GPIO 17
#define VALVE_2_GPIO 18
#define VALVE_1_DURATION_MS 500
#define VALVE_2_DURATION_MS 1000
#define VALVE_1_PAUSE_MS 5000
#define VALVE_2_PAUSE_MS 10000
#define LOG_FILE "valve_log.txt"
#define GPIO_CHIP_NAME "gpiochip0"

static volatile sig_atomic_t program_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *valve1_line = NULL;
static struct gpiod_line *valve2_line = NULL;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void cleanup(void) {
    if (valve1_line) {
        gpiod_line_release(valve1_line);
        valve1_line = NULL;
    }
    if (valve2_line) {
        gpiod_line_release(valve2_line);
        valve2_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int log_event(const char *message) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (!localtime_r(&rawtime, &timeinfo)) {
        perror("localtime_r");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

static int activate_valve(struct gpiod_line *line, int duration_ms) {
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value (ON)");
        return -1;
    }
    usleep(duration_ms * 1000);
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value (OFF)");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        fclose(log_file);
        log_file = NULL;
        return EXIT_FAILURE;
    }

    valve1_line = gpiod_chip_get_line(chip, VALVE_1_GPIO);
    if (!valve1_line) {
        perror("gpiod_chip_get_line(VALVE_1_GPIO)");
        cleanup();
        return EXIT_FAILURE;
    }

    valve2_line = gpiod_chip_get_line(chip, VALVE_2_GPIO);
    if (!valve2_line) {
        perror("gpiod_chip_get_line(VALVE_2_GPIO)");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(valve1_line, "valve_control", 0) < 0) {
        perror("gpiod_line_request_output(valve1)");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(valve2_line, "valve_control", 0) < 0) {
        perror("gpiod_line_request_output(valve2)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Automated Greenhouse Valve Control System started.\n");
    log_event("System started.");

    while (program_running) {
        printf("Activating Valve 1 for %d ms...\n", VALVE_1_DURATION_MS);
        log_event("Valve 1 activated");
        if (activate_valve(valve1_line, VALVE_1_DURATION_MS) < 0) {
            log_event("Error activating Valve 1");
            cleanup();
            return EXIT_FAILURE;
        }
        if (!program_running) break;
        usleep(VALVE_1_PAUSE_MS * 1000);

        printf("Activating Valve 2 for %d ms...\n", VALVE_2_DURATION_MS);
        log_event("Valve 2 activated");
        if (activate_valve(valve2_line, VALVE_2_DURATION_MS) < 0) {
            log_event("Error activating Valve 2");
            cleanup();
            return EXIT_FAILURE;
        }
        if (!program_running) break;
        usleep(VALVE_2_PAUSE_MS * 1000);
    }

    printf("Shutting down...\n");
    log_event("System stopped");
    cleanup();
    return EXIT_SUCCESS;
}

