#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MIN_STEPS 5
#define MAX_STEPS 15
#define MIN_DURATION_MS 50
#define MAX_DURATION_MS 200
#define PWM_RANGE 255

typedef struct {
    int motor1_duty;
    int motor2_duty;
    int duration_ms;
} MotorStep;

typedef struct {
    MotorStep steps[MAX_STEPS];
    int num_steps;
} HapticPattern;

volatile sig_atomic_t shutdown_flag = 0;

void signal_handler(int sig) {
    (void)sig;
    shutdown_flag = 1;
}

int generate_random_pattern(HapticPattern *pattern) {
    pattern->num_steps = (rand() % (MAX_STEPS - MIN_STEPS + 1)) + MIN_STEPS;
    if (pattern->num_steps == 0) pattern->num_steps = 1;

    for (int i = 0; i < pattern->num_steps; i++) {
        pattern->steps[i].motor1_duty = rand() % (PWM_RANGE + 1);
        pattern->steps[i].motor2_duty = rand() % (PWM_RANGE + 1);
        pattern->steps[i].duration_ms = rand() % (MAX_DURATION_MS - MIN_DURATION_MS + 1) + MIN_DURATION_MS;
    }
    return 0;
}

void play_pattern(const HapticPattern *pattern) {
    for (int i = 0; i < pattern->num_steps; i++) {
        if (shutdown_flag) break;

        if (gpioPWM(MOTOR1_PIN, pattern->steps[i].motor1_duty) < 0) {
            fprintf(stderr, "Error: gpioPWM failed for motor 1\n");
            return;
        }
        if (gpioPWM(MOTOR2_PIN, pattern->steps[i].motor2_duty) < 0) {
            fprintf(stderr, "Error: gpioPWM failed for motor 2\n");
            return;
        }

        gpioDelay(pattern->steps[i].duration_ms * 1000);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR2_PIN);
        gpioTerminate();
        return 1;
    }

    srand(time(NULL));

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to register signal handler\n");
        gpioTerminate();
        return 1;
    }

    HapticPattern pattern;
    while (!shutdown_flag) {
        if (generate_random_pattern(&pattern) != 0) {
            fprintf(stderr, "Error: Pattern generation failed\n");
            break;
        }
        printf("Playing pattern: %d steps\n", pattern.num_steps);
        play_pattern(&pattern);
    }

    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
    gpioTerminate();
    printf("Shutdown complete.\n");
    return 0;
}

