#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define WEIGHT_LOG_FILE "weight_log.txt"
#define THRESHOLD_KG 10.0
#define NUM_CALIBRATION_READINGS 100
#define READ_INTERVAL_US 500000
#define HX711_TIMEOUT_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin, long *out_value) {
    long value = 0;
    int i;

    if (gpioSetMode(data_pin, PI_INPUT) < 0) return -1;
    if (gpioSetMode(clock_pin, PI_OUTPUT) < 0) return -1;

    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    for (i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        value = value << 1;
        if (gpioRead(data_pin)) value++;
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    if (value & 0x800000) value |= 0xFF000000;

    *out_value = value;
    return 0;
}

static double calibrate_hx711(int data_pin, int clock_pin) {
    long sum = 0;
    int i;
    long val;

    printf("Starting calibration. Remove all weight from the load cell.\n");
    gpioDelay(2000000);

    for (i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        if (read_hx711(data_pin, clock_pin, &val) != 0) {
            fprintf(stderr, "Error reading HX711 during calibration.\n");
            return 0.0;
        }
        sum += val;
        gpioDelay(10000);
    }

    double avg = (double)sum / NUM_CALIBRATION_READINGS;
    printf("Calibration complete. Average raw value: %.2f\n", avg);
    return avg;
}

static void log_weight(double weight_kg) {
    FILE *fp = fopen(WEIGHT_LOG_FILE, "a");
    if (!fp) {
        perror("Error opening weight log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, %.2f\n", timestamp, weight_kg);
    fclose(fp);
}

int main(void) {
    FILE *fp;
    double scale_factor = 1.0, offset = 0.0;
    int ret = 1;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    fp = fopen(CALIBRATION_FILE, "r");
    if (fp) {
        if (fscanf(fp, "%lf %lf", &scale_factor, &offset) == 2) {
            printf("Loaded calibration data: scale=%.2f, offset=%.2f\n", scale_factor, offset);
        } else {
            fprintf(stderr, "Invalid calibration data. Using defaults.\n");
        }
        fclose(fp);
    } else {
        printf("No calibration file found. Using defaults.\n");
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        goto cleanup;
    }
    gpioWrite(SOLENOID_PIN, 0);

    printf("Calibrating HX711...\n");
    offset = calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);

    fp = fopen(CALIBRATION_FILE, "w");
    if (fp) {
        fprintf(fp, "%.2f %.2f\n", scale_factor, offset);
        fclose(fp);
    } else {
        perror("Error saving calibration data");
    }

    printf("Starting main loop. Press Ctrl+C to exit.\n");

    while (running) {
        long raw;
        if (read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &raw) != 0) {
            fprintf(stderr, "Error reading HX711. Skipping iteration.\n");
            gpioDelay(READ_INTERVAL_US);
            continue;
        }

        double weight = (raw - offset) / scale_factor;

        if (weight > THRESHOLD_KG) {
            gpioWrite(SOLENOID_PIN, 1);
            printf("Weight %.2f kg exceeds threshold %.2f kg. Lock engaged.\n", weight, THRESHOLD_KG);
        } else {
            gpioWrite(SOLENOID_PIN, 0);
            printf("Weight %.2f kg below threshold %.2f kg. Lock released.\n", weight, THRESHOLD_KG);
        }

        log_weight(weight);
        gpioDelay(READ_INTERVAL_US);
    }

    gpioWrite(SOLENOID_PIN, 0);
    ret = 0;

cleanup:
    gpioTerminate();
    return ret;
}

