#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define HX711_DT_PIN 23
#define HX711_SCK_PIN 24
#define SOLENOID_PIN 17
#define WEIGHT_THRESHOLD 100.0
#define WEIGHT_LOG_FILE "stock_events.txt"
#define HX711_TIMEOUT_US 1000000
#define SOLENOID_DURATION_US 5000000
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int hx711_read(int dt_pin, int sck_pin) {
    if (gpioSetMode(dt_pin, PI_INPUT) != 0) return -1;
    if (gpioSetMode(sck_pin, PI_OUTPUT) != 0) return -1;

    int timeout = 0;
    while (gpioRead(dt_pin) == 1) {
        gpioDelay(100);
        if (++timeout > HX711_TIMEOUT_US) return -1;
    }

    long count = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(sck_pin, 1) != 0) return -1;
        gpioDelay(1);
        count = count << 1;
        if (gpioWrite(sck_pin, 0) != 0) return -1;
        gpioDelay(1);
        if (gpioRead(dt_pin) == 1) count |= 1;
    }

    if (gpioWrite(sck_pin, 1) != 0) return -1;
    gpioDelay(1);
    if (gpioWrite(sck_pin, 0) != 0) return -1;
    gpioDelay(1);

    if (count & 0x800000) count |= 0xFF000000;
    return (int)count;
}

static double convert_to_grams(int raw_value) {
    if (raw_value == 0) return 0.0;
    return (double)raw_value / 32768.0 * 1000.0;
}

static int log_event(const char *filename, double weight) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - Weight: %.2f g\n", timestamp, weight);
    fclose(fp);
    return 0;
}

static void activate_solenoid(int pin, int duration_us) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error activating solenoid on GPIO%d\n", pin);
        return;
    }
    gpioDelay(duration_us);
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error deactivating solenoid on GPIO%d\n", pin);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting solenoid pin mode\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(SOLENOID_PIN, 0);

    printf("Stock monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw = hx711_read(HX711_DT_PIN, HX711_SCK_PIN);
        if (raw == -1) {
            fprintf(stderr, "HX711 read timeout or error\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double weight = convert_to_grams(raw);
        printf("Weight: %.2f g\n", weight);

        if (weight < WEIGHT_THRESHOLD) {
            printf("Weight below threshold. Activating solenoid.\n");
            if (log_event(WEIGHT_LOG_FILE, weight) != 0) {
                fprintf(stderr, "Failed to log event\n");
            }
            activate_solenoid(SOLENOID_PIN, SOLENOID_DURATION_US);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("Stock monitoring stopped.\n");
    return 0;
}

