#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"

#define WEIGHT_THRESHOLD 5.0
#define SOLENOID_HOLD_TIME_US 5000000
#define HX711_TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;
static double calibration_factor = 1.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int *raw_out) {
    if (raw_out == NULL) return -1;

    int data = 0;
    int timeout = 0;

    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout >= HX711_TIMEOUT_US / 1000) {
            fprintf(stderr, "HX711 timeout: data line stuck high\n");
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1);
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) data++;
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1);
    }

    if (gpioRead(HX711_DATA_PIN)) data++;

    if (data & 0x800000) data |= 0xFF000000;
    *raw_out = data;
    return 0;
}

static double calculate_weight(int raw_value) {
    return (double)raw_value / calibration_factor;
}

static int log_security_event(double weight) {
    FILE *fp = fopen(SECURITY_LOG_FILE, "a");
    if (!fp) {
        perror("fopen security.log");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Weight: %.2f kg\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    } else {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int calibrate_hx711(double known_weight) {
    int raw_value;
    if (read_hx711(&raw_value) != 0) {
        fprintf(stderr, "Calibration failed: HX711 read error\n");
        return -1;
    }
    calibration_factor = (double)raw_value / known_weight;
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (!fp) {
        perror("fopen calibration.txt");
        return -1;
    }
    fprintf(fp, "%.6f\n", calibration_factor);
    fclose(fp);
    printf("Calibration factor: %.6f\n", calibration_factor);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (calibrate_hx711(2.0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting weight monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_value;
        if (read_hx711(&raw_value) != 0) {
            gpioDelay(100000);
            continue;
        }

        double weight = calculate_weight(raw_value);
        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            printf("Threshold exceeded! Logging and locking solenoid.\n");
            if (log_security_event(weight) != 0) {
                fprintf(stderr, "Logging failed\n");
            }
            gpioWrite(SOLENOID_PIN, 1);
            gpioDelay(SOLENOID_HOLD_TIME_US);
            gpioWrite(SOLENOID_PIN, 0);
            printf("Solenoid unlocked.\n");
        }

        gpioDelay(100000);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

