#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_LEFT 4
#define SENSOR_CENTER 17
#define SENSOR_RIGHT 27
#define MOTOR_LEFT_PWM 22
#define MOTOR_RIGHT_PWM 23
#define MOTOR_LEFT_DIR 24
#define MOTOR_RIGHT_DIR 25
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define LOOP_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int gpio) {
    int val = gpioRead(gpio);
    if (val < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return val;
}

static int set_motor_speed(int dir_gpio, int pwm_gpio, int speed) {
    if (gpioWrite(dir_gpio, 1) < 0) {
        fprintf(stderr, "Error setting direction GPIO %d high: %s\n", dir_gpio, strerror(errno));
        return -1;
    }
    if (gpioPWM(pwm_gpio, speed) < 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d: %s\n", pwm_gpio, strerror(errno));
        gpioWrite(dir_gpio, 0);
        return -1;
    }
    return 0;
}

static int set_motor_stop(int dir_gpio, int pwm_gpio) {
    gpioWrite(dir_gpio, 0);
    gpioPWM(pwm_gpio, 0);
    return 0;
}

static int control_robot(int left_sensor, int center_sensor, int right_sensor, int *left_speed, int *right_speed) {
    if (center_sensor == 0) {
        *left_speed = 150;
        *right_speed = 150;
    } else if (left_sensor == 0) {
        *left_speed = 150;
        *right_speed = 75;
    } else if (right_sensor == 0) {
        *left_speed = 75;
        *right_speed = 150;
    } else {
        *left_speed = 0;
        *right_speed = 0;
    }
    return 0;
}

static void log_data(int left_sensor, int center_sensor, int right_sensor, int left_speed, int right_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Left: %d, Center: %d, Right: %d, Left Speed: %d, Right Speed: %d\n",
                timestamp, left_sensor, center_sensor, right_sensor, left_speed, right_speed);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main(void) {
    int left_sensor, center_sensor, right_sensor;
    int left_speed, right_speed;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_LEFT, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_CENTER, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_RIGHT, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting sensor GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(MOTOR_LEFT_PWM, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_LEFT_DIR, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_RIGHT_PWM, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_RIGHT_DIR, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting motor GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(MOTOR_LEFT_PWM, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_RIGHT_PWM, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(MOTOR_LEFT_PWM, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_RIGHT_PWM, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(SENSOR_LEFT, NULL) < 0 ||
        gpioSetAlertFunc(SENSOR_CENTER, NULL) < 0 ||
        gpioSetAlertFunc(SENSOR_RIGHT, NULL) < 0) {
        fprintf(stderr, "Error setting sensor alert functions\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("trace_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Line following robot started. Press Ctrl+C to exit.\n");

    while (running) {
        left_sensor = read_sensor(SENSOR_LEFT);
        center_sensor = read_sensor(SENSOR_CENTER);
        right_sensor = read_sensor(SENSOR_RIGHT);

        if (left_sensor < 0 || center_sensor < 0 || right_sensor < 0) {
            fprintf(stderr, "Error reading sensors, stopping motors.\n");
            set_motor_stop(MOTOR_LEFT_DIR, MOTOR_LEFT_PWM);
            set_motor_stop(MOTOR_RIGHT_DIR, MOTOR_RIGHT_PWM);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        control_robot(left_sensor, center_sensor, right_sensor, &left_speed, &right_speed);

        if (set_motor_speed(MOTOR_LEFT_DIR, MOTOR_LEFT_PWM, left_speed) < 0 ||
            set_motor_speed(MOTOR_RIGHT_DIR, MOTOR_RIGHT_PWM, right_speed) < 0) {
            fprintf(stderr, "Error setting motor speeds, stopping motors.\n");
            set_motor_stop(MOTOR_LEFT_DIR, MOTOR_LEFT_PWM);
            set_motor_stop(MOTOR_RIGHT_DIR, MOTOR_RIGHT_PWM);
        }

        log_data(left_sensor, center_sensor, right_sensor, left_speed, right_speed);

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    set_motor_stop(MOTOR_LEFT_DIR, MOTOR_LEFT_PWM);
    set_motor_stop(MOTOR_RIGHT_DIR, MOTOR_RIGHT_PWM);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

