#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150
#define LOG_FILE "grow_log.txt"
#define MEASUREMENT_DELAY_US 180000

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld: %s\n", timestamp, ts.tv_nsec / 1000000, message);
    fclose(fp);
}

static int read_lux(int handle, int *lux_out) {
    char cmd = 0x10;
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        log_message("Error: Failed to write measurement command to BH1750");
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_US);
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        log_message("Error: Failed to read lux data from BH1750");
        return -1;
    }
    int raw = (buf[0] << 8) | buf[1];
    *lux_out = raw / 1.2;
    return 0;
}

static void control_relay(int gpio, int state) {
    gpioWrite(gpio, state);
    char msg[64];
    snprintf(msg, sizeof(msg), "Relay on GPIO%d set to %s", gpio, state ? "ON" : "OFF");
    log_message(msg);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    log_message("System started");
    while (running) {
        int lux;
        if (read_lux(i2c_handle, &lux) == 0) {
            char msg[64];
            snprintf(msg, sizeof(msg), "Lux reading: %d", lux);
            log_message(msg);
            if (lux < LUX_THRESHOLD) {
                control_relay(RELAY_GPIO, 1);
            } else {
                control_relay(RELAY_GPIO, 0);
            }
        } else {
            log_message("Error reading lux");
        }
        gpioDelay(500000);
    }
    log_message("System shutting down");
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    return 0;
}

