static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_servo_pulse(int pin, int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH) {
        pulse_width = SERVO_MIN_PULSE_WIDTH;
    } else if (pulse_width > SERVO_MAX_PULSE_WIDTH) {
        pulse_width = SERVO_MAX_PULSE_WIDTH;
    }
    return gpioServo(pin, pulse_width);
}

static int move_servo(int pin, int pulse_width) {
    if (safe_servo_pulse(pin, pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to set servo pulse width on GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static int lock_door(void) {
    printf("Locking door...\n");
    if (move_servo(SERVO_PIN, SERVO_LOCK_POSITION) != 0) {
        return -1;
    }
    gpioDelay(500000);
    return 0;
}

static int unlock_door(void) {
    printf("Unlocking door...\n");
    if (move_servo(SERVO_PIN, SERVO_UNLOCK_POSITION) != 0) {
        return -1;
    }
    gpioDelay(500000);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set servo pin %d as output\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0 ||
        gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set button pins as input\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up resistors on button pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(LOCK_BUTTON, NULL) != 0 ||
        gpioSetAlertFunc(UNLOCK_BUTTON, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set alert functions for button pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            if (lock_door() == 0) {
                gpioDelay(DEBOUNCE_DELAY_US);
            }
        }
        if (gpioRead(UNLOCK_BUTTON) == 0) {
            if (unlock_door() == 0) {
                gpioDelay(DEBOUNCE_DELAY_US);
            }
        }
        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

