#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define CONSUMER "haptic_feedback"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_motor(struct gpiod_line *line, int pin, int duration_ms) {
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Failed to set GPIO high");
        return -1;
    }
    usleep(duration_ms * 1000);
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Failed to set GPIO low");
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *motor1_line = NULL;
    struct gpiod_line *motor2_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("Failed to open gpiochip4");
        return EXIT_FAILURE;
    }

    motor1_line = gpiod_chip_get_line(chip, MOTOR1_PIN);
    if (!motor1_line) {
        perror("Failed to get GPIO17 line");
        goto cleanup;
    }

    motor2_line = gpiod_chip_get_line(chip, MOTOR2_PIN);
    if (!motor2_line) {
        perror("Failed to get GPIO27 line");
        goto cleanup;
    }

    if (gpiod_line_request_output(motor1_line, CONSUMER, 0) < 0) {
        perror("Failed to request GPIO17 as output");
        goto cleanup;
    }

    if (gpiod_line_request_output(motor2_line, CONSUMER, 0) < 0) {
        perror("Failed to request GPIO27 as output");
        goto cleanup;
    }

    while (running) {
        if (set_motor(motor1_line, MOTOR1_PIN, 200) < 0) {
            goto cleanup;
        }
        if (!running) break;
        if (set_motor(motor2_line, MOTOR2_PIN, 300) < 0) {
            goto cleanup;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (motor1_line) {
        gpiod_line_release(motor1_line);
    }
    if (motor2_line) {
        gpiod_line_release(motor2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

