#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <zmq.h>

#define SOUND_SENSOR_GPIO 17
#define ALARM_LED_GPIO 27
#define ZMQ_PORT 5555
#define POLL_INTERVAL_US 10000
#define ALARM_DURATION_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int publish_alert(void) {
    void *context = zmq_ctx_new();
    if (!context) {
        fprintf(stderr, "Failed to create ZeroMQ context: %s\n", strerror(errno));
        return -1;
    }

    void *publisher = zmq_socket(context, ZMQ_PUB);
    if (!publisher) {
        fprintf(stderr, "Failed to create ZeroMQ publisher socket: %s\n", strerror(errno));
        zmq_ctx_destroy(context);
        return -1;
    }

    int rc = zmq_bind(publisher, "tcp://*:" ZMQ_PORT);
    if (rc != 0) {
        fprintf(stderr, "Failed to bind publisher to port %d: %s\n", ZMQ_PORT, strerror(errno));
        zmq_close(publisher);
        zmq_ctx_destroy(context);
        return -1;
    }

    char message[64];
    snprintf(message, sizeof(message), "Sound alert on GPIO%d", SOUND_SENSOR_GPIO);
    rc = zmq_send(publisher, message, strlen(message), 0);
    if (rc < 0) {
        fprintf(stderr, "Failed to send alert: %s\n", strerror(errno));
    }

    zmq_close(publisher);
    zmq_ctx_destroy(context);
    return 0;
}

static void trigger_alarm(void) {
    printf("Sound detected! Triggering alarm.\n");
    fflush(stdout);

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, ALARM_LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO%d line: %s\n", ALARM_LED_GPIO, strerror(errno));
        return;
    }

    if (gpiod_line_set_value(led_line, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO%d high: %s\n", ALARM_LED_GPIO, strerror(errno));
        return;
    }

    usleep(ALARM_DURATION_MS * 1000);

    if (gpiod_line_set_value(led_line, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO%d low: %s\n", ALARM_LED_GPIO, strerror(errno));
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s {sound_sensor|alarm_node}\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *sensor_line = gpiod_chip_get_line(chip, SOUND_SENSOR_GPIO);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get GPIO%d line: %s\n", SOUND_SENSOR_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, ALARM_LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO%d line: %s\n", ALARM_LED_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sensor_line, "sound_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO%d as input: %s\n", SOUND_SENSOR_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "alarm_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO%d as output: %s\n", ALARM_LED_GPIO, strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (strcmp(mode, "sound_sensor") == 0) {
        printf("Sound sensor mode started. Press Ctrl+C to exit.\n");
        fflush(stdout);

        while (running) {
            int val = gpiod_line_get_value(sensor_line);
            if (val < 0) {
                fprintf(stderr, "Failed to read GPIO%d: %s\n", SOUND_SENSOR_GPIO, strerror(errno));
                break;
            }

            if (val == 0) {
                printf("Sound detected!\n");
                fflush(stdout);
                trigger_alarm();
            }

            usleep(POLL_INTERVAL_US);
        }

        gpiod_line_release(sensor_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_SUCCESS;
    }

    if (strcmp(mode, "alarm_node") == 0) {
        void *context = zmq_ctx_new();
        if (!context) {
            fprintf(stderr, "Failed to create ZeroMQ context: %s\n", strerror(errno));
            gpiod_line_release(sensor_line);
            gpiod_line_release(led_line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        void *subscriber = zmq_socket(context, ZMQ_SUB);
        if (!subscriber) {
            fprintf(stderr, "Failed to create ZeroMQ subscriber socket: %s\n", strerror(errno));
            zmq_ctx_destroy(context);
            gpiod_line_release(sensor_line);
            gpiod_line_release(led_line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        int rc = zmq_connect(subscriber, "tcp://localhost:5555");
        if (rc != 0) {
            fprintf(stderr, "Failed to connect to ZeroMQ server: %s\n", strerror(errno));
            zmq_close(subscriber);
            zmq_ctx_destroy(context);
            gpiod_line_release(sensor_line);
            gpiod_line_release(led_line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        rc = zmq_setsockopt(subscriber, ZMQ_SUBSCRIBE, "SOUND_ALERTS", 12);
        if (rc != 0) {
            fprintf(stderr, "Failed to subscribe to SOUND_ALERTS: %s\n", strerror(errno));
            zmq_close(subscriber);
            zmq_ctx_destroy(context);
            gpiod_line_release(sensor_line);
            gpiod_line_release(led_line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        printf("Alarm node mode started. Listening for sound alerts...\n");
        fflush(stdout);

        while (running) {
            void *message = zmq_msg_t;
            int more = 1;

            while (more) {
                rc = zmq_msg_recv(&message, subscriber, &more);
                if (rc == 0) {
                    char *payload = (char *)zmq_msg_data(message);
                    printf("Received alert: %s\n", payload);
                    fflush(stdout);
                    trigger_alarm();
                    zmq_msg_close(&message);
