                        syslog(LOG_WARNING, "Invalid extended addr bit low at %d", idx);
                        return -1;
                    }
                    if (pulses[idx + 1] < NEC_ONE_SPACE - NEC_TOLERANCE) {
                        addr_high |= (1u << i);
                    } else if (pulses[idx + 1] < NEC_ONE_SPACE + NEC_TOLERANCE) {
                        addr_high |= (0u << i);
                    } else {
                        syslog(LOG_WARNING, "Invalid extended addr bit high at %d", idx);
                        return -1;
                    }
                }
                if ((addr_low & 0xFF) != (address & 0xFF) ||
                    (addr_high & 0xFF) != ((address >> 8) & 0xFF)) {
                    syslog(LOG_WARNING, "Extended NEC address mismatch: 0x%02X 0x%02X",
                           addr_low & 0xFF, addr_high & 0xFF);
                    return -1;
                }
                address = addr_low;
            } else {
                syslog(LOG_WARNING, "Invalid extended NEC address mark at index 12");
                return -1;
            }
        } else {
            syslog(LOG_WARNING, "Invalid extended NEC header mark at index 8");
            return -1;
        }
    }

    /* Validate command */
    if (count >= 34 + 8 && pulses[34] < NEC_BIT_MARK - NEC_TOLERANCE &&
        pulses[35] < NEC_BIT_MARK - NEC_TOLERANCE) {
        unsigned int cmd_low = 0, cmd_high = 0;
        for (int i = 0; i < 8; i++) {
            int idx = 36 + i * 2;
            if (idx + 1 >= count) return -1;
            if (pulses[idx] < NEC_BIT_MARK - NEC_TOLERANCE) {
                cmd_low |= (1u << i);
            } else if (pulses[idx] < NEC_BIT_MARK + NEC_TOLERANCE) {
                cmd_low |= (0u << i);
            } else {
                syslog(LOG_WARNING, "Invalid command bit low at index %d", idx);
                return -1;
            }
            if (pulses[idx + 1] < NEC_ONE_SPACE - NEC_TOLERANCE) {
                cmd_high |= (1u << i);
            } else if (pulses[idx + 1] < NEC_ONE_SPACE + NEC_TOLERANCE) {
                cmd_high |= (0u << i);
            } else {
                syslog(LOG_WARNING, "Invalid command bit high at index %d", idx);
                return -1;
            }
        }
        if ((cmd_low & 0xFF) != (command & 0xFF) ||
            (cmd_high & 0xFF) != ((command >> 8) & 0xFF)) {
            syslog(LOG_WARNING, "NEC command checksum mismatch: 0x%02X 0x%02X",
                   cmd_low & 0xFF, cmd_high & 0xFF);
            return -1;
        }
    }

    out->address = address;
    out->command = command;
    return 0;
}

/* ---- MQTT publish callback ---- */
static void publish_callback(struct mosquitto *m, void *userdata,
                              const struct mosquitto_message *message) {
    (void)m;
    (void)userdata;
    if (message->payloadlen > 0) {
        syslog(LOG_INFO, "Publishing: %s", (const char *)message->payload);
    }
}

/* ---- MQTT connect callback ---- */
static void connect_callback(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_HOST, MQTT_PORT);
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(result));
    }
}

/* ---- MQTT disconnect callback ---- */
static void disconnect_callback(struct mosquitto *m, void *userdata, int result) {
    (void)m;
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT disconnected");
    } else {
        syslog(LOG_ERR, "MQTT disconnect failed: %s", mosquitto_strerror(result));
    }
}

/* ---- MQTT loop ---- */
static void mqtt_loop(void) {
    while (running) {
        mosquitto_loop(mosq, 100, 1);
    }
}

/* ---- Cleanup ---- */
static void cleanup(void) {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handlers");
        closelog();
        return 1;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return 1;
    }

    /* Configure GPIO */
    gpioSetMode(IR_GPIO, PI_INPUT);
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP);

    /* Register alert callback */
    if (gpioSetAlertFunc(IR_GPIO, ir_callback) != 0) {
        syslog(LOG_ERR, "Failed to set alert function on GPIO %d", IR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }

    /* Initialize MQTT */
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_message_callback_set(mosq, publish_callback);

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosq = NULL;
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "IR decoder started on GPIO %d", IR_GPIO);

    /* Main loop */
    while (running) {
        gpioDelay(100000); /* 100 ms */
        if (mosq) {
            mosquitto_loop(mosq, 100, 1);
        }
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return 0;
}

