#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE      "/dev/i2c-1"
#define MULTICAST_ADDR  "239.255.255.250"
#define MULTICAST_PORT  5005
#define NUM_SENSORS     4
#define CONV_TIME_MS    180

static const int sensor_addresses[NUM_SENSORS] = {0x23, 0x24, 0x25, 0x26};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Open /dev/i2c-1 and set the slave address via ioctl. Returns fd or -1. */
static int i2c_open(int addr) {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_DEVICE, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/* Read one BH1750FVI in One-Time High-Resolution mode. Returns lux or NaN. */
static float read_bh1750(int fd) {
    uint8_t cmd = 0x20; /* One-Time High-Resolution mode */
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "BH1750 write failed: %s\n", w < 0 ? strerror(errno) : "short write");
        return NAN;
    }
    usleep(CONV_TIME_MS * 1000);

    uint8_t buf[2];
    ssize_t r = read(fd, buf, 2);
    if (r != 2) {
        fprintf(stderr, "BH1750 read failed: %s\n", r < 0 ? strerror(errno) : "short read");
        return NAN;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    return (float)raw / 1.2f;
}

/* Send a UDP multicast packet with semicolon-separated sensor data. */
static void send_multicast(int sock, int sensor_id, float lux) {
    char buffer[128];
    int len = snprintf(buffer, sizeof(buffer), "%d,%.2f", sensor_id, lux);
    if (len < 0 || (size_t)len >= sizeof(buffer)) {
        fprintf(stderr, "snprintf failed for sensor %d\n", sensor_id);
        return;
    }
    if (sendto(sock, buffer, (size_t)len, 0, NULL, 0) < 0) {
        fprintf(stderr, "sendto failed: %s\n", strerror(errno));
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int i2c_fds[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_fds[i] = i2c_open(sensor_addresses[i]);
        if (i2c_fds[i] < 0) {
            fprintf(stderr, "Failed to open I2C for sensor %d (0x%02X)\n", i + 1, sensor_addresses[i]);
            for (int j = 0; j < i; j++) close(i2c_fds[j]);
            return 1;
        }
    }

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "socket creation failed: %s\n", strerror(errno));
        for (int i = 0; i < NUM_SENSORS; i++) close(i2c_fds[i]);
        return 1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (connect(sockfd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "connect failed: %s\n", strerror(errno));
        for (int i = 0; i < NUM_SENSORS; i++) close(i2c_fds[i]);
        close(sockfd);
        return 1;
    }

    while (g_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            float lux = read_bh1750(i2c_fds[i]);
            send_multicast(sockfd, i + 1, lux);
        }
        sleep(1);
    }

    for (int i = 0; i < NUM_SENSORS; i++) close(i2c_fds[i]);
    close(sockfd);
    return 0;
}

