#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define AWM7300V_ADDR  0x28
#define LOG_FILE       "airflow_log.txt"
#define SAMPLE_PERIOD  1
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_open(const char *bus, uint8_t addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int read_airflow(int fd, float *flow_slpm) {
    uint8_t buf[2];
    ssize_t n;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        n = write(fd, buf, 0);
        if (n == 0) {
            break;
        }
        if (n < 0 && errno != EIO) {
            fprintf(stderr, "I2C write failed (attempt %d): %s\n", attempt + 1, strerror(errno));
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        usleep(RETRY_DELAY_MS * 1000);
    }

    if (n < 0) {
        fprintf(stderr, "I2C write failed after %d retries: %s\n", MAX_RETRIES, strerror(errno));
        return -1;
    }

    n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read failed: expected 2 bytes, got %zd (%s)\n", n, strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    raw &= 0x3FFF;
    *flow_slpm = ((float)raw - 3277.0f) * 0.1f;
    return 0;
}

static int log_data(const char *filename, float flow_slpm) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f\n", timestamp, flow_slpm);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = i2c_open(I2C_BUS, AWM7300V_ADDR);
    if (g_i2c_fd < 0) {
        return 1;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float flow_slpm;
        if (read_airflow(g_i2c_fd, &flow_slpm) == 0) {
            if (log_data(LOG_FILE, flow_slpm) != 0) {
                fprintf(stderr, "Error logging data.\n");
            } else {
                printf("Flow: %.2f SLPM\n", flow_slpm);
            }
        } else {
            fprintf(stderr, "Error reading flow data.\n");
        }
        sleep(SAMPLE_PERIOD);
    }

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nAirflow monitoring stopped.\n");
    return 0;
}

