#define AS7341_I2C_ADDR 0x39
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "spectral_log.csv"
#define SAMPLE_INTERVAL_SEC 5

/* AS7341 register addresses */
#define AS7341_REG_WHO_AM_I     0x24
#define AS7341_REG_ENABLE       0x80
#define AS7341_REG_CFG6         0xAF
#define AS7341_REG_DATA0_L      0x60
#define AS7341_REG_DATA0_H      0x61
#define AS7341_REG_DATA1_L      0x62
#define AS7341_REG_DATA1_H      0x63
#define AS7341_REG_DATA2_L      0x64
#define AS7341_REG_DATA2_H      0x65
#define AS7341_REG_DATA3_L      0x66
#define AS7341_REG_DATA3_H      0x67
#define AS7341_REG_DATA4_L      0x68
#define AS7341_REG_DATA4_H      0x69
#define AS7341_REG_DATA5_L      0x6A
#define AS7341_REG_DATA5_H      0x6B
#define AS7341_REG_DATA6_L      0x6C
#define AS7341_REG_DATA6_H      0x6D
#define AS7341_REG_DATA7_L      0x6E
#define AS7341_REG_DATA7_H      0x6F
#define AS7341_REG_DATA8_L      0x70
#define AS7341_REG_DATA8_H      0x71
#define AS7341_REG_DATA9_L      0x72
#define AS7341_REG_DATA9_H      0x73

#define AS7341_WHO_AM_I_VAL     0x19
#define AS7341_ENABLE_PON       0x01
#define AS7341_ENABLE_SP_EN     0x02
#define AS7341_CFG6_SMUX_F1     0x01

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg_l, uint16_t *val) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg_l, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, reg_l + 1, &hi) < 0) return -1;
    *val = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int as7341_init(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, AS7341_REG_WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error.\n");
        return -1;
    }
    if (who_am_i != AS7341_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, AS7341_WHO_AM_I_VAL);
        return -1;
    }
    printf("AS7341 detected (WHO_AM_I = 0x%02X).\n", who_am_i);

    if (i2c_write_reg8(fd, AS7341_REG_ENABLE, AS7341_ENABLE_PON) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg8(fd, AS7341_REG_ENABLE, AS7341_ENABLE_PON | AS7341_ENABLE_SP_EN) < 0) return -1;
    usleep(10000);

    if (i2c_write_reg8(fd, AS7341_REG_CFG6, AS7341_CFG6_SMUX_F1) < 0) return -1;
    usleep(10000);

    printf("AS7341 initialized: spectral measurement enabled.\n");
    return 0;
}

static int read_spectral_data(int fd, uint16_t *data) {
    data[0] = 0;
    data[1] = 0;
    data[2] = 0;
    data[3] = 0;
    data[4] = 0;
    data[5] = 0;
    data[6] = 0;
    data[7] = 0;
    data[8] = 0;
    data[9] = 0;

    if (i2c_read_reg16(fd, AS7341_REG_DATA0_L, &data[0]) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_DATA1_L, &data[1]) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_DATA2_L, &data[2]) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_DATA3_L, &data[3]) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_DATA4_L, &data[4]) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_DATA5_L, &data[5]) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_DATA6_L, &data[6]) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_DATA7_L, &data[7]) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_DATA8_L, &data[8]) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_DATA9_L, &data[9]) < 0) return -1;
    return 0;
}

static float calculate_lux(const uint16_t *data) {
    float f1 = (float)data[0] / 100.0f;
    float f2 = (float)data[1] / 100.0f;
    float f3 = (float)data[2] / 100.0f;
    float f4 = (float)data[3] / 100.0f;
    float c  = (float)data[4] / 100.0f;
    float nir = (float)data[5] / 100.0f;
    float red = (float)data[6] / 100.0f;
    float green = (float)data[7] / 100.0f;
    float blue = (float)data[8] / 100.0f;
    float clear = (float)data[9] / 100.0f;

    float lux = 0.0f;
    if (f1 > 0.0f) lux += f1 * 0.001f;
    if (f2 > 0.0f) lux += f2 * 0.001f;
    if (f3 > 0.0f) lux += f3 * 0.001f;
    if (f4 > 0.0f) lux += f4 * 0.001f;
    if (c > 0.0f)  lux += c  * 0.001f;
    if (nir > 0.0f) lux += nir * 0.001f;
    if (red > 0.0f) lux += red * 0.001f;
    if (green > 0.0f) lux += green * 0.001f;
    if (blue > 0.0f) lux += blue * 0.001f;
    if (clear > 0.0f) lux += clear * 0.001f;
    return lux;
}

static int log_data(FILE *fp, float lux, const uint16_t *data) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f,%u,%u,%u,%u,%u,%u,%u,%u,%u\n",
                ts, lux, data[0], data[1], data[2], data[3],
                data[4], data[5], data[6], data[7], data[8], data[9]) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, AS7341_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                AS7341_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (as7341_init(g_i2c_fd) < 0) {
        fprintf(stderr, "AS7341 initialization failed.\n");
        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,Lux,F1,F2,F3,F4,Clear,NIR,Red,Green,Blue\n");
    }

    uint16_t spectral_data[10];
    float lux;

    while (g_running) {
        if (read_spectral_data(g_i2c_fd, spectral_data) < 0) {
            fprintf(stderr, "Spectral read failed; retrying next cycle.\n");
        } else {
            lux = calculate_lux(spectral_data);
            if (log_data(g_log_fp, lux, spectral_data) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down cleanly...\n");
    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

