#include <linux/i2c-dev.h>

#define D7S_I2C_ADDR 0x37
#define D7S_REG_X_L 0x28
#define D7S_REG_X_H 0x29
#define D7S_REG_Y_L 0x2A
#define D7S_REG_Y_H 0x2B
#define D7S_REG_Z_L 0x2C
#define D7S_REG_Z_H 0x2D
#define D7S_SCALE 0.000244f
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define DEFAULT_INTERVAL 1
#define CSV_FILENAME "seismic_data.csv"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *csv_file = NULL;
static char *csv_filename = CSV_FILENAME;
static int i2c_address = D7S_I2C_ADDR;
static int i2c_interval = DEFAULT_INTERVAL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s (errno: %s)\n", ts, msg, strerror(errno));
    if (csv_file) {
        fprintf(csv_file, "%s,ERROR,%s\n", ts, msg);
        fflush(csv_file);
    }
}

static int i2c_write_byte(uint8_t reg) {
    if (write(i2c_fd, &reg, 1) != 1) return -1;
    return 0;
}

