#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_POWER_ON 0x01
#define BH1750_CONT_HIGH_RES 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint16_t *value) {
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_light_level(int fd, float *lux) {
    uint16_t raw;
    if (i2c_read_word(fd, &raw) < 0) {
        return -1;
    }
    *lux = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(float lux) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return -1;
    }

    int ttl = 1;
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("setsockopt IP_MULTICAST_TTL failed");
        close(sockfd);
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    char buffer[64];
    int len = snprintf(buffer, sizeof(buffer), "%.2f", lux);
    if (len < 0 || (size_t)len >= sizeof(buffer)) {
        fprintf(stderr, "snprintf failed\n");
        close(sockfd);
        return -1;
    }

    if (sendto(sockfd, buffer, len, 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto failed");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write_byte(i2c_fd, BH1750_POWER_ON) < 0) {
        fprintf(stderr, "Failed to power on BH1750\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    usleep(10000);

    if (i2c_write_byte(i2c_fd, BH1750_CONT_HIGH_RES) < 0) {
        fprintf(stderr, "Failed to set BH1750 to continuous high-res mode\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    usleep(180000);

    printf("BH1750 initialized. Broadcasting to %s:%d every %d s.\n",
           MULTICAST_ADDR, MULTICAST_PORT, SAMPLE_INTERVAL_SEC);

    while (running) {
        float lux;
        if (read_light_level(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error, retrying in 1 s...\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        if (send_multicast(lux) < 0) {
            fprintf(stderr, "Multicast send error, retrying in 1 s...\n");
        }

        printf("Light level: %.2f lux\n", lux);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    close(i2c_fd);
    return EXIT_SUCCESS;
}

