#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define CSV_FILE "radar_data.csv"
#define MAX_OBJECTS 100
#define MAGIC_WORD_LEN 8
#define HEADER_LEN 40
#define TLV_HEADER_LEN 8
#define TLV_TYPE_DETECTED_POINTS 1
#define TLV_TYPE_RANGE_PROFILE 2
#define TLV_TYPE_NOISE_PROFILE 3
#define TLV_TYPE_AZIMUTH_HEAT_MAP 4
#define TLV_TYPE_RANGE_DOPPLER_HEAT_MAP 5
#define TLV_TYPE_STATS 6
#define TLV_TYPE_PLATFORM_ID 7
#define TLV_TYPE_FRAME_NUMBER 8
#define TLV_TYPE_TIME_CYCLES 9
#define TLV_TYPE_TARGET_INDEX 10
#define TLV_TYPE_RANGE_INDEX 11
#define TLV_TYPE_DOPPLER_INDEX 12
#define TLV_TYPE_CUSTOM_DATA 13
#define TLV_TYPE_END 14

#define MAGIC_WORD_0 0x0204
#define MAGIC_WORD_1 0x0306
#define MAGIC_WORD_2 0x0805
#define MAGIC_WORD_3 0x0709

#define FRAME_HEADER_VERSION 0x0100
#define FRAME_HEADER_TOTAL_PACKET_LEN 0x0000
#define FRAME_HEADER_PLATFORM 0x0100
#define FRAME_HEADER_FRAME_NUMBER 0x0200
#define FRAME_HEADER_TIME_CYCLES 0x0300
#define FRAME_HEADER_NUM_DETECTED_OBJ 0x0400
#define FRAME_HEADER_NUM_TLVS 0x0500

#define DETECTED_POINT_SIZE 16
#define TLV_HEADER_TYPE 0
#define TLV_HEADER_LENGTH 4

typedef struct {
    uint32_t version;
    uint32_t total_packet_len;
    uint32_t platform;
    uint32_t frame_number;
    uint32_t time_cycles;
    uint32_t num_detected_obj;
    uint32_t num_tlvs;
    uint32_t sub_frame_num;
    uint32_t chirp_profile;
    uint32_t frame_seq_num;
    uint32_t time_stamp;
    uint32_t num_tlvs_in_frame;
} FrameHeader;

typedef struct {
    uint16_t range_idx;
    uint16_t doppler_idx;
    uint16_t peak_val;
    uint16_t x;
    uint16_t y;
    uint16_t z;
} DetectedPoint;

static int uart_handle = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_uart(void) {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART %s: %d\n", UART_DEVICE, uart_handle);
        return -1;
    }
    printf("UART initialized on %s at %d baud\n", UART_DEVICE, BAUD_RATE);
    return 0;
}

static int init_csv(void) {
    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        perror("Error opening CSV file");
        return -1;
    }
    fseek(csv_file, 0, SEEK_END);
    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }
    fflush(csv_file);
    return 0;
}

static void close_resources(void) {
    if (uart_handle >= 0) {
        serClose(uart_handle);
        uart_handle = -1;
    }
    if (csv_file) {
        fflush(csv_file);
        fclose(csv_file);
        csv_file = NULL;
    }
    gpioTerminate();
}

static int read_exact(int handle, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        int n = serRead(handle, (char *)(buf + total), len - total);
        if (n < 0) {
            fprintf(stderr, "UART read error: %d\n", n);
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART read timeout (got %d of %d)\n", total, len);
            return -1;
        }
        total += n;
    }
    return 0;
}

static int find_magic_word(int handle, uint8_t *buf, int len) {
    for (int i = 0; i <= len - MAGIC_WORD_LEN; i++) {
        uint32_t w0 = (uint32_t)buf[i] | ((uint32_t)buf[i + 1] << 8) |
                     ((uint32_t)buf[i + 2] << 16) | ((uint32_t)buf[i + 3] << 24);
        uint32_t w1 = (uint32_t)buf[i + 4] | ((uint32_t)buf[i + 5] << 8) |
                     ((uint32_t)buf[i + 6] << 16) | ((uint32_t)buf[i + 7] << 24);
        uint32_t w2 = (uint32_t)buf[i + 8] | ((uint32_t)buf[i + 9] << 8) |
                     ((uint32_t)buf[i + 10] << 16) | ((uint32_t)buf[i + 11] << 24);
        uint32_t w3 = (uint32_t)buf[i + 12] | ((uint32_t)buf[i + 13] << 8) |
                      ((uint32_t)buf[i + 14] << 16) | ((uint32_t)buf[i + 15] << 24);
        if (w0 == MAGIC_WORD_0 && w1 == MAGIC_WORD_1 &&
            w2 == MAGIC_WORD_2 && w3 == MAGIC_WORD_3) {
            return i;
        }
    }
