#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <time.h>
#include <sys/select.h>
#include <signal.h>
#include <sys/time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define LINE_BUF_SIZE 256
#define READ_BUF_SIZE 128
#define POLL_TIMEOUT_SEC 2
#define POLL_TIMEOUT_US 0

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag |= CLOCAL | CREAD;

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5; /* 0.5 s inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int parse_range_data(const char *line, float *range_out) {
    char *endptr = NULL;
    errno = 0;
    long ts = strtol(line, &endptr, 10);
    if (errno != 0 || endptr == line || *endptr != ',') {
        return -1;
    }
    const char *rng_str = endptr + 1;
    errno = 0;
    float range = strtof(rng_str, &endptr);
    if (errno != 0 || endptr == rng_str) {
        return -1;
    }
    *range_out = range;
    return 0;
}

static void log_range_data(float range) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm tm_info;
    localtime_r(&tv.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("Timestamp: %s, Range: %.2f meters\n", timestamp, range);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    g_uart_fd = init_uart(UART_DEVICE);
    if (g_uart_fd < 0) {
        return 1;
    }

    char line_buf[LINE_BUF_SIZE];
    size_t line_len = 0;
    char read_buf[READ_BUF_SIZE];

    printf("Starting AWR1642 range detection on %s...\n", UART_DEVICE);
    fflush(stdout);

    while (g_running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(g_uart_fd, &readfds);

        struct timeval tv;
        tv.tv_sec = POLL_TIMEOUT_SEC;
        tv.tv_usec = POLL_TIMEOUT_US;

        int sel = select(g_uart_fd + 1, &readfds, NULL, NULL, &tv);
        if (sel < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error from select: %s\n", strerror(errno));
            break;
        }
        if (sel == 0) {
            continue;
        }

        ssize_t n = read(g_uart_fd, read_buf, sizeof(read_buf));
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            fprintf(stderr, "Error from read: %s\n", strerror(errno));
            break;
        }
        if (n == 0) {
            continue;
        }

        for (ssize_t i = 0; i < n && g_running; i++) {
            char c = read_buf[i];
            if (c == '\n') {
                line_buf[line_len] = '\0';
                if (line_len > 0) {
                    float range;
                    if (parse_range_data(line_buf, &range) == 0) {
                        log_range_data(range);
                    } else {
                        fprintf(stderr, "Invalid data line: %s", line_buf);
                    }
                }
                line_len = 0;
            } else if (c != '\r') {
                if (line_len < LINE_BUF_SIZE - 1) {
                    line_buf[line_len++] = c;
                } else {
                    fprintf(stderr, "Line buffer overflow, discarding\n");
                    line_len = 0;
                }
            }
        }
    }

    if (g_uart_fd >= 0) {
        tcflush(g_uart_fd, TCIOFLUSH);
        close(g_uart_fd);
        g_uart_fd = -1;
    }
    printf("\nExiting gracefully.\n");
    return 0;
}

